\label{thm:no-angular}
Almost-periodicity does NOT automatically imply angular concentration ($\rho \to 1$).

More precisely: there exist profiles $\phi \in \Hdot{1/2}$ such that:
\begin{enumerate}
\item $\phi$ could be a blow-up profile (in principle)
\item $\phi$ is angularly spread: $\rho^\phi := \max_j E_j^\phi / \|\phi\|_{\Hdot{1/2}}^2 \ll 1$
\end{enumerate}

\label{thm:gen-dichotomy}
Let $u$ be almost-periodic with profile $\phi$ and $\rho^\phi \in (0, 1]$. Then:

\textbf{Case 1:} If $\rho^\phi \geq 1 - \eps_*$ (angular concentration), the original dichotomy applies.

\textbf{Case 2:} If $\rho^\phi < 1 - \eps_*$ (angular spread), then:
\begin{itemize}
\item The profile $\phi$ has spread angular energy
\item The nonlinear evolution from $\phi$ has special structure due to the spread
\end{itemize}

\label{thm:mod-compact}
For an almost-periodic blow-up solution $u(t)$:
\begin{enumerate}
\item The radial part $\bar{u}(t)$ satisfies a \textbf{modified} NS equation
\item The angular fluctuation $\tilde{u}(t)$ is controlled by $\bar{u}(t)$
\item If $\|\tilde{u}^\phi\| / \|\phi\|$ is small (profile is nearly radial), then $\rho \to 1$
\item If $\|\tilde{u}^\phi\| / \|\phi\|$ is large (profile has angular structure), then $\rho < 1$
\end{enumerate}

\label{thm:trilinear}
Let $u, v, w$ be divergence-free vector fields with Fourier
support in $\mathcal{C}_\delta(\hat{n})$ for some
$\delta \in (0,1/2)$.  Then
\begin{equation}\label{eq:trilinear-main}
  \left| \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx \right|
  \leq C_0\,\delta\,\norm{u}_{\dot{H}^{1/2}}
  \norm{v}_{\dot{H}^{3/2}} \norm{w}_{\dot{H}^{1/2}},
\end{equation}
where $C_0$ is a universal constant independent of $\delta$,
$\hat{n}$, and the functions.  The estimate holds uniformly
across all frequency regimes (high--high--high, low--high--high,
high--low--high).

\label{thm:conditional}
Let $u$ be a smooth solution to~\eqref{eq:NS} on $[0,T)$ with
$u_0 \in H^1(\R^3)$ divergence-free.  Suppose there exists
$\hat{n}(t) \in S^2$ and $\delta(t) \in (0,1/2)$ such that $u(t)$
is $\delta(t)$-concentrated around~$\hat{n}(t)$ for all
$t \in [0,T)$, with
\begin{equation}\label{eq:delta-condition}
  \delta(t) < \frac{\nu}{2C_0\norm{u(t)}_{\dot{H}^{1/2}}}
\end{equation}
where $C_0$ is the constant from Theorem~\ref{thm:trilinear}.
Then the solution exists globally:
\begin{equation}
  \frac{d}{dt}\norm{u}_{\dot{H}^{1/2}}^2
  \leq -\nu\norm{u}_{\dot{H}^{3/2}}^2 < 0
\end{equation}
whenever $u \neq 0$.  In particular, $T = \infty$ and
$\norm{u(t)}_{\dot{H}^{1/2}} \to 0$ as $t \to \infty$.

\label{def:frame}
Fix a reference direction $\hat{n} \in S^2$.  For
$\xi \in \R^3 \setminus \{0\}$ with $\hat{\xi} \neq -\hat{n}$,
define
\begin{equation}
  e_1(\xi) := \frac{\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}}
  {|\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}|},
  \qquad
  e_2(\xi) := \hat{\xi} \times e_1(\xi).
\end{equation}
When $\hat{\xi} = \hat{n}$, extend by continuity.

\label{lem:frame}
For $|\hat{\xi} - \hat{n}| \leq \delta$ and
$|\hat{\zeta} - \hat{n}| \leq \delta$ with
$\delta \in (0,1/2)$:
\begin{equation}\label{eq:frame-lip}
  |e_i(\xi) - e_i(\zeta)| \leq \frac{4}{\delta}|\hat{\xi} - \hat{\zeta}|
  \qquad (i = 1,2).
\end{equation}

\label{prop:freq-uniform}
The estimate of Theorem~\ref{thm:trilinear} holds uniformly
across all frequency interactions consistent with cone localization.

\label{cor:suppressed-nonlin}
If $u$ is $\delta$-concentrated, the nonlinear energy transfer
