\label{thm:main-reg}
There exists a universal constant $C_J > 0$ such that the following
holds.  Let $u$ be a Leray--Hopf solution on $[0,T) \times \T^3$.
If
\begin{equation}\label{eq:main-criterion}
\delta(u(t))\norm{u(t)}_{\Hdot{1/2}} < \frac{\nu}{2C_J}
\qquad\text{for all } t \in [0,T),
\end{equation}
then $u$ is regular on $[0,T)$.

\label{thm:main-bilinear}
Let $v_1, v_2$ be NS solutions with initial data whose Fourier
transforms are supported in cones $\cC_1, \cC_2$ with angular
separation $\theta := d_{\mathrm{ang}}(\cC_1, \cC_2) > 0$.
Then the cross-bilinear interaction satisfies:
\begin{equation}\label{eq:main-bilinear}
\norm{B(v_1, v_2)}_{N_T}
\leq C\sin\theta\,\norm{v_1}_{X_T}\norm{v_2}_{X_T},
\end{equation}
where $X_T, N_T$ are the Koch--Tataru critical spacetime norms.

\label{thm:main-decoupling}
There exists $\theta_0 = \theta_0(E_c, \nu) > 0$ such that:
\begin{enumerate}[label=(\alph*)]
\item \textbf{Decoupling:}  If $\phi = \phi_1 + \phi_2$ with
$\max(\norm{\phi_j}_{\Hdot{1/2}}) < E_c$, angular separation
$\theta \leq \theta_0$, then the NS solution from $\phi$ is global.

\item \textbf{Blow-up spread bound:}  Any minimal blow-up element
$u^*$ in the Gallagher--Koch--Planchon sense satisfies
\begin{equation}\label{eq:main-spread}
\liminf_{t\to T^*}\delta(u^*(t)) \geq \theta_0 > 0.
\end{equation}
Blow-up data must be angularly spread.
\end{enumerate}

\label{thm:main-L4}
Any Leray--Hopf solution on $[0,T^*) \times \T^3$ satisfies:
\begin{equation}\label{eq:main-L4}
\int_0^{T^*}\norm{u(t)}_{\Hdot{1/2}}^4\,dt
\leq \frac{\norm{u_0}_2^2\norm{u_0}_{\Hdot{1/2}}^2}{\nu}.
\end{equation}

