\label{thm:S3}
The operator $L = \Delta_{S^3} - \nabla V \cdot \nabla$ with $V(\theta)
= -c\cos\theta$ on $S^3$ satisfies
\begin{equation}
  \boxed{\mathrm{CD}(2-c,\,\infty)}\,.
\end{equation}
Equivalently, for all smooth $f \colon S^3 \to \R$:
\begin{equation}\label{eq:CD-S3}
  \Gamma_{L,2}(f,f) \;\ge\; (2-c)\,\Gamma(f,f),
\end{equation}
where $\Gamma(f,f) = |\nabla f|^2$ and $\Gamma_{L,2}(f,f) =
\tfrac{1}{2}[L\,\Gamma(f,f) - 2\,\Gamma(f,Lf)]$.

following_proof:
For a diffusion operator $L = \Delta - \nabla V \cdot \nabla$ on a
Riemannian manifold $(M,g)$, the standard Bakry-\'{E}mery identity
gives
\begin{equation}\label{eq:BE-general}
  \Gamma_{L,2}(f,f) = |\Hess\,f|^2 + (\Ric + \Hess\,V)(\nabla f,
  \nabla f).
\end{equation}

On $S^3$ with constant curvature, $\Ric = 2g$.

For $V(\theta) = -c\cos\theta$, the Hessian is computed using the
formula for radial functions on $S^n$:
\begin{equation}
  \Hess\,V = V''\,d\theta \otimes d\theta + V'\cot\theta\,(g -
  d\theta \otimes d\theta).
\end{equation}
Since $V'' = c\cos\theta$ and $V'\cot\theta = c\sin\theta \cdot
\frac{\cos\theta}{\sin\theta} = c\cos\theta$, both components equal
$c\cos\theta$, giving:
\begin{equation}
  \Hess\,V = c\cos\theta \cdot g_{S^3}.
\end{equation}
This is a \emph{scalar multiple of the metric at every point} --- the
key structural identity.

Substituting into~\eqref{eq:BE-general}:
\begin{equation}
  \Gamma_{L,2}(f,f) = |\Hess\,f|^2 + (2 + c\cos\theta)\,|\nabla f|^2
  \;\ge\; (2 + c\cos\theta)\,\Gamma(f,f).
\end{equation}
Taking the infimum over $\theta \in [0,\pi]$:
\begin{equation}
  \Gamma_{L,2}(f,f) \;\ge\; (2-c)\,\Gamma(f,f). \qedhere
\end{equation}

statement:
\label{cor:poincare}
For $c < 2$, the single-link conditional measure $\mu_\ell$ satisfies
\begin{equation}
  \Var_{\mu_\ell}(f) \;\le\; \frac{1}{2-c}\,\mathcal{E}_L(f,f),
\end{equation}
where $\mathcal{E}_L(f,f) = \int |\nabla f|^2\,d\mu_\ell$ is the
Dirichlet form.

For the semigroup $P_t^L = e^{tL}$:
\begin{equation}
  |\nabla P_t^L f|^2 \;\le\; e^{-2(2-c)t}\, P_t^L\!\bigl[|\nabla f|^2\bigr].
\end{equation}

\label{lem:Lp-moments}
For $p \in (1,\gamma)$ and any interval $[s,t] \subset [0,T]$,
\begin{equation}\label{eq:Lp-moment}
  \E[|L_t - L_s|^p] = C_{p,\gamma}\,(t-s)^{p/\gamma}.
\end{equation}
For the second moment of jumps below threshold $\epsilon > 0$:
\begin{equation}\label{eq:small-jump-moment}
  \E\!\left[\sum_{s < r \leq t,\,|\Delta L_r| \leq \epsilon}
  |\Delta L_r|^2\right]
  = (t-s)\int_{|z|\leq\epsilon}z^2\,\nu(dz)
  = C_\gamma'(t-s)\,\epsilon^{2-\gamma},
  \qquad C_\gamma' := c_\gamma \cdot \frac{2}{2-\gamma}.
\end{equation}

following_proof:
The first follows from self-similarity: $L_t - L_s \stackrel{d}{=}
(t-s)^{1/\gamma}L_1$.  The second is the compensator of the
restricted jump measure.

statement:
\label{lem:taylor-partition}
Let $\phi \in C_b^3(\R)$.  On each partition interval $[t_k, t_{k+1}]$,
\begin{equation}\label{eq:taylor-full}
  \phi(L_{t_{k+1}}) - \phi(L_{t_k})
  = \phi'(L_{t_k})\,\Delta_k L
  + \sum_{t_k < s \leq t_{k+1}}
  \bigl[\phi(L_s) - \phi(L_{s-}) - \phi'(L_{s-})\,\Delta L_s\bigr]
  + E_k^n,
\end{equation}
where the error $E_k^n$ is defined by
\begin{equation}\label{eq:error-Ek}
  E_k^n := \int_{t_k}^{t_{k+1}}
  \bigl[\phi'(L_{s-}) - \phi'(L_{t_k})\bigr]\,dL_s.
\end{equation}

\label{rem:taylor-structure}
The identity~\eqref{eq:taylor-full} separates the increment
$\phi(L_{t_{k+1}}) - \phi(L_{t_k})$ into three parts:
\begin{enumerate}[label=(\alph*)]
\item $\phi'(L_{t_k})\,\Delta_k L$: the ``stochastic integral
  part'' (using the left-endpoint evaluation, which is
  $\mathcal{F}_{t_k}^L$-measurable);
\item the defect sum: the jump corrections on $[t_k, t_{k+1}]$;
\item $E_k^n$: a stochastic integral error from replacing
  $\phi'(L_{s-})$ by $\phi'(L_{t_k})$ in the integrand.
\end{enumerate}

\label{lem:error-convergence}
Under the notation of Lemma~\ref{lem:taylor-partition}, the total
error satisfies
\begin{equation}\label{eq:total-error}
  \sum_{k=0}^{n-1} E_k^n \to 0
  \qquad \text{in } L^p(\Omega) \text{ as } n \to \infty.
\end{equation}

\label{lem:riemann-stochastic}
For $\phi \in C_b^1(\R)$,
\begin{equation}\label{eq:riemann-stochastic}
  \sum_{k=0}^{n-1} \phi'(L_{t_k})\,\Delta_kL
  \to \int_0^T \phi'(L_{t-})\,dL_t
  \qquad \text{in } L^p(\Omega) \text{ as } n \to \infty.
\end{equation}

\label{lem:defect-convergence}
For $\phi \in C_b^2(\R)$,
\begin{equation}\label{eq:defect-conv}
  \sum_{k=0}^{n-1}
  \sum_{t_k < s \leq t_{k+1}}
  \bigl[\phi(L_s) - \phi(L_{s-}) - \phi'(L_{s-})\,\Delta L_s\bigr]
  = \Gamma_L^{\phi}(T)
\end{equation}
for every $n \in \N$.  That is, the partition defect equals the
full defect \emph{exactly}, with no approximation error.

\label{def:chain-defect}
For $\phi \in C_b^2(\R)$ and a symmetric $\gamma$-stable process $L$,
define the \emph{chain-rule defect}
\begin{equation}\label{eq:chain-defect}
  \Gamma_L^{\phi}(T) :=
  \sum_{0 < s \leq T}
  \bigl[\phi(L_s) - \phi(L_{s-}) - \phi'(L_{s-})\,\Delta L_s\bigr].
\end{equation}
This is the failure of $\phi$ to be linear on each jump:
$\Gamma_L^{\phi}(T) = 0$ if and only if $\phi$ is affine.

following_proof:
The proof proceeds by time discretization from operator principles,
following the strategy of~\cite{Fontes2026c}, Theorem~4.1,
adapted to the jump/Banach setting.

\medskip
\textbf{Step 1: Time discretization.}
Fix $n \in \N$ and the partition $\Pi_n = \{t_k^n\}$.
Write the telescoping identity:
\begin{equation}\label{eq:telescoping}
  \phi(L_T) - \phi(0)
  = \sum_{k=0}^{n-1}
  \bigl[\phi(L_{t_{k+1}}) - \phi(L_{t_k})\bigr].
\end{equation}

\medskip
\textbf{Step 2: Apply the Taylor decomposition on each interval.}
By Lemma~\ref{lem:taylor-partition}, each summand decomposes as
\begin{align}
  \phi(L_{t_{k+1}}) - \phi(L_{t_k})
  &= \phi'(L_{t_k})\,\Delta_k L \label{eq:step2a}\\
  &\quad+ \sum_{t_k < s \leq t_{k+1}}
  \bigl[\phi(L_s) - \phi(L_{s-}) - \phi'(L_{s-})\,\Delta L_s\bigr]
  \label{eq:step2b}\\
  &\quad+ E_k^n. \label{eq:step2c}
\end{align}

\medskip
\textbf{Step 3: Sum over the partition.}
Summing~\eqref{eq:step2a}--\eqref{eq:step2c} over $k$:
\begin{equation}\label{eq:partition-sum}
  \phi(L_T) - \phi(0)
  = \underbrace{\sum_{k=0}^{n-1} \phi'(L_{t_k})\,\Delta_kL}_{\text{(I)}}
  \;+\; \underbrace{\sum_{k=0}^{n-1}
  \sum_{t_k < s \leq t_{k+1}}
  \bigl[\phi(L_s) - \phi(L_{s-}) - \phi'(L_{s-})\Delta L_s\bigr]}_{\text{(II)}}
  \;+\; \underbrace{\sum_{k=0}^{n-1} E_k^n}_{\text{(III)}}.
\end{equation}

\medskip
\textbf{Step 4: Identify each term.}

\emph{Term~(II) = $\Gamma_L^{\phi}(T)$ exactly.}
By Lemma~\ref{lem:defect-convergence}, term~(II) equals
$\Gamma_L^{\phi}(T)$ for every $n$---no limit needed.

\emph{Term~(I) $\to \delta_L(\phi'(L_{\cdot-}))$ in $L^p(\Omega)$.}
By Lemma~\ref{lem:riemann-stochastic}.

\emph{Term~(III) $\to 0$ in $L^p(\Omega)$.}
By Lemma~\ref{lem:error-convergence}.

\medskip
\textbf{Step 5: Take $n \to \infty$.}
Since~\eqref{eq:partition-sum} holds as an identity for every $n$,
and the left-hand side $\phi(L_T) - \phi(0)$ is independent of $n$,
we may take $n \to \infty$.  Terms~(I) and~(III) converge in
$L^p(\Omega)$, and term~(II) is already exact.  Thus in $L^p$:
\[
  \phi(L_T) - \phi(0)
  = \delta_L(\phi'(L_{\cdot-})) + \Gamma_L^{\phi}(T),
\]
which is~\eqref{eq:banach-ito}.

\medskip
\textbf{Step 6: Operator-theoretic interpretation.}
Multiplying~\eqref{eq:banach-ito} by $\delta_L(u)$ for bounded
predictable $u \in H_L$ and taking expectations (using
$\E[\delta_L(u)] = 0$):
\begin{align}
  \langle D_L(\phi(L_T)), u \rangle
  &= \E[\phi(L_T) \cdot \delta_L(u)] \notag\\
  &= \E\!\left[\delta_L(\phi'(L_{\cdot-})) \cdot \delta_L(u)\right]
  + \E\!\left[\Gamma_L^{\phi}(T) \cdot \delta_L(u)\right],
  \label{eq:DL-phi-verify}
\end{align}
which is~\eqref{eq:DL-phi-decomp}.

statement:
\label{thm:generator}
Let $L$ be a symmetric $\gamma$-stable L\'evy process with
$\gamma \in (1,2)$, and let $f \in C_b^2(\R)$.  Define the
Feynman--Kac function
\[
  u(t,x) := \E[f(L_T) \mid L_t = x]
  = \E[f(x + L_{T-t})]
\]
for $t \in [0,T]$ and $x \in \R$.

Then $u$ solves the backward equation
\begin{equation}\label{eq:backward-eq}
  \partial_t u + \mathcal{L}u = 0,
  \qquad u(T,x) = f(x),
\end{equation}
where the generator $\mathcal{L}$ is the nonlocal operator
\begin{equation}\label{eq:generator-formula}
  \mathcal{L}f(x)
  = \int_{\R}
  \bigl(f(x+z) - f(x) - f'(x)z\,\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
For the symmetric $\gamma$-stable measure
$\nu(dz) = c_\gamma|z|^{-1-\gamma}\,dz$, this gives
\begin{equation}\label{eq:fractional-laplacian}
  \mathcal{L} = -(-\Delta)^{\gamma/2}.
\end{equation}

\label{rem:defect-generator}
The proof reveals the pathway from Banach energy space to generator:
\[
  H_L = L^p
  \;\xrightarrow{D_L = \delta_L^*}\;
  D_L F \in H_L^* = L^q
  \;\xrightarrow{\Gamma_L}\;
  \text{jump defect}
  \;\xrightarrow{\text{compensate}}\;
  \int_{\R}(\cdots)\,\nu(dz)
  \;=\; (-\Delta)^{\gamma/2}.
\]
In the Hilbert case, the pathway is
$\mathcal{H} \to \|DF\|^2_{\mathcal{H}} \to \frac{1}{2}\Delta$.
The defect replaces the squared norm as the object that produces
the generator.

\label{thm:banach-product-rule}
Let $F = f(L_T)$ and $G = g(L_T)$ with $f, g \in C_b^2(\R)$,
and let $u \in H_L$ be a bounded predictable process.
Then
\begin{equation}\label{eq:banach-product-rule}
  \langle D_L(FG), u \rangle
  = \langle F \cdot D_L G + G \cdot D_L F, u \rangle
  + \langle \Gamma_L(F,G), u \rangle,
\end{equation}
where the Leibniz defect acts on test integrands via
\begin{equation}\label{eq:leibniz-defect-action}
  \langle \Gamma_L(F,G), u \rangle
  = \E\!\left[\sum_{0 < s \leq T}
  \bigl[(fg)(L_s) - (fg)(L_{s-})
  - (f'g + fg')(L_{s-})\,\Delta L_s\bigr]
  \cdot \delta_L(u)\right].
\end{equation}

\label{lem:Lp-moments}
For $p \in (1,\gamma)$ and any interval $[s,t] \subset [0,T]$,
\begin{equation}\label{eq:Lp-moment}
  \E[|L_t - L_s|^p] = C_{p,\gamma}\,(t-s)^{p/\gamma}.
\end{equation}
For the second moment of jumps below threshold $\epsilon > 0$:
\begin{equation}\label{eq:small-jump-moment}
  \E\!\left[\sum_{s < r \leq t,\,|\Delta L_r| \leq \epsilon}
  |\Delta L_r|^2\right]
  = (t-s)\int_{|z|\leq\epsilon}z^2\,\nu(dz)
  = C_\gamma'(t-s)\,\epsilon^{2-\gamma}.
\end{equation}

