  \langle D_L(\phi(L_T)), u \rangle
  &= \E[\phi(L_T) \cdot \delta_L(u)] \notag\\
  &= \E\!\left[\delta_L(\phi'(L_{\cdot-})) \cdot \delta_L(u)\right]
  + \E\!\left[\Gamma_L^{\phi}(T) \cdot \delta_L(u)\right],
  \label{eq:DL-phi-verify}
\end{align}
which is~\eqref{eq:DL-phi-decomp}.

statement:
\label{thm:generator}
Let $L$ be a symmetric $\gamma$-stable L\'evy process with
$\gamma \in (1,2)$, and let $f \in C_b^2(\R)$.  Define the
Feynman--Kac function
\[
  u(t,x) := \E[f(L_T) \mid L_t = x]
  = \E[f(x + L_{T-t})]
\]
for $t \in [0,T]$ and $x \in \R$.

Then $u$ solves the backward equation
\begin{equation}\label{eq:backward-eq}
  \partial_t u + \mathcal{L}u = 0,
  \qquad u(T,x) = f(x),
\end{equation}
where the generator $\mathcal{L}$ is the nonlocal operator
\begin{equation}\label{eq:generator-formula}
  \mathcal{L}f(x)
  = \int_{\R}
  \bigl(f(x+z) - f(x) - f'(x)z\,\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
For the symmetric $\gamma$-stable measure
$\nu(dz) = c_\gamma|z|^{-1-\gamma}\,dz$, this gives
\begin{equation}\label{eq:fractional-laplacian}
  \mathcal{L} = -(-\Delta)^{\gamma/2}.
\end{equation}

following_proof:
The proof applies the Banach It\^o formula (Theorem~\ref{thm:banach-ito})
to the Feynman--Kac function and extracts the generator from the
martingale condition.

\textbf{Step 1: Apply the Banach It\^o formula to $u(t, L_t)$.}
Define $Y_t := u(t, L_t)$.  By the Markov property of $L$,
$Y_t = \E[f(L_T) \mid \mathcal{F}_t^L]$ is a martingale.

Since $u$ depends on both $t$ and $x$, consider a short time
interval $[t, t+h]$.  The increment of $Y$ is
\begin{align}
  Y_{t+h} - Y_t
  &= u(t+h, L_{t+h}) - u(t, L_t) \notag\\
  &= \bigl[u(t+h, L_{t+h}) - u(t, L_{t+h})\bigr]
    + \bigl[u(t, L_{t+h}) - u(t, L_t)\bigr].
    \label{eq:Y-increment}
\end{align}
The first bracket is $\partial_t u(t, L_{t+h}) \cdot h + O(h^2)$
(by Taylor in $t$).  For the second bracket, apply the Banach
It\^o formula with $\phi(\cdot) = u(t, \cdot)$:
\begin{equation}\label{eq:spatial-ito}
  u(t, L_{t+h}) - u(t, L_t)
  = \int_t^{t+h} \partial_x u(t, L_{s-})\,dL_s
  + \sum_{t < r \leq t+h}
  \bigl[u(t, L_r) - u(t, L_{r-}) - \partial_x u(t, L_{r-})\,\Delta L_r\bigr].
\end{equation}

\textbf{Step 2: Compute the compensator of the jump sum.}
The jump sum in~\eqref{eq:spatial-ito} has a systematic part
and a martingale part.  Using the compensation formula for
the Poisson random measure $N(ds,dz)$ associated with $L$:
\begin{align}
  &\E\!\left[\sum_{t < r \leq t+h}
  \bigl[u(t,L_r) - u(t,L_{r-}) - \partial_x u(t,L_{r-})\Delta L_r\bigr]
  \;\Big|\; \mathcal{F}_t\right] \notag\\
  &\qquad= \int_t^{t+h}\!\!\int_{\R}
  \bigl[u(t, L_{s-}+z) - u(t, L_{s-})
  - \partial_x u(t, L_{s-})\,z\,\mathbf{1}_{|z|\leq 1}\bigr]\,\nu(dz)\,ds
  \notag\\
  &\qquad\quad+ \int_t^{t+h}\!\!\int_{|z|>1}
  \partial_x u(t, L_{s-})\,z\,\nu(dz)\,ds.
  \label{eq:compensator-full}
\end{align}
Here we used that the compensated sum removes the $\tilde{N}$
martingale part, and the truncation function
$z\,\mathbf{1}_{|z|\leq 1}$ appears because the L\'evy process
is defined via compensation of small jumps.

For the symmetric stable measure, $\int_{|z|>1}z\,\nu(dz) = 0$
by symmetry, so the second integral vanishes.

\textbf{Step 3: Apply the martingale condition.}
Since $Y_t$ is a martingale,
$\E[Y_{t+h} - Y_t \mid \mathcal{F}_t] = 0$.
Taking conditional expectations of~\eqref{eq:Y-increment} and
using~\eqref{eq:spatial-ito}--\eqref{eq:compensator-full}:
\begin{equation}\label{eq:mart-cond}
  0 = \partial_t u(t, L_t)\,h
  + \int_t^{t+h}\!\!\int_{\R}
  \bigl[u(t, L_t+z) - u(t, L_t)
  - \partial_x u(t, L_t)\,z\,\mathbf{1}_{|z|\leq 1}\bigr]\,\nu(dz)\,ds
  + o(h).
\end{equation}
Dividing by $h$ and taking $h \to 0$:
\begin{equation}\label{eq:pde}
  \partial_t u(t, x) + \int_{\R}
  \bigl[u(t, x+z) - u(t, x)
  - \partial_x u(t, x)\,z\,\mathbf{1}_{|z| \leq 1}\bigr]\,\nu(dz) = 0,
\end{equation}
which is $\partial_t u + \mathcal{L}u = 0$ with $\mathcal{L}$ as
in~\eqref{eq:generator-formula}.

\textbf{Step 4: Identify the fractional Laplacian.}
For $\nu(dz) = c_\gamma|z|^{-1-\gamma}\,dz$ symmetric, the
truncation term $f'(x)z\,\mathbf{1}_{|z| \leq 1}$ vanishes under the
integral by symmetry, and
\[
  \mathcal{L}f(x) = c_\gamma\,\PV\!\int_{\R}
  \frac{f(x+z) - f(x)}{|z|^{1+\gamma}}\,dz
  = -(-\Delta)^{\gamma/2}f(x),
\]
the fractional Laplacian of order $\gamma/2$.

statement:
\label{rem:defect-generator}
The proof reveals the pathway from Banach energy space to generator:
\[
  H_L = L^p
  \;\xrightarrow{D_L = \delta_L^*}\;
  D_L F \in H_L^* = L^q
  \;\xrightarrow{\Gamma_L}\;
  \text{jump defect}
  \;\xrightarrow{\text{compensate}}\;
  \int_{\R}(\cdots)\,\nu(dz)
  \;=\; (-\Delta)^{\gamma/2}.
\]
In the Hilbert case, the pathway is
$\mathcal{H} \to \|DF\|^2_{\mathcal{H}} \to \frac{1}{2}\Delta$.
The defect replaces the squared norm as the object that produces
the generator.

\label{lem:Lp-moments}
For $p \in (1,\gamma)$ and any interval $[s,t] \subset [0,T]$,
\begin{equation}\label{eq:Lp-moment}
  \E[|L_t - L_s|^p] = C_{p,\gamma}\,(t-s)^{p/\gamma}.
\end{equation}
For the second moment of jumps below threshold $\epsilon > 0$:
\begin{equation}\label{eq:small-jump-moment}
  \E\!\left[\sum_{s < r \leq t,\,|\Delta L_r| \leq \epsilon}
  |\Delta L_r|^2\right]
  = (t-s)\int_{|z|\leq\epsilon}z^2\,\nu(dz)
  = C_\gamma'(t-s)\,\epsilon^{2-\gamma},
  \qquad C_\gamma' := c_\gamma \cdot \frac{2}{2-\gamma}.
\end{equation}

