$\mathcal{H} \to \|DF\|^2_{\mathcal{H}} \to \frac{1}{2}\Delta$.
The defect replaces the squared norm as the object that produces
the generator.

\label{thm:impossibility}
Let $\gamma \in (1,2)$ and $p \in (1,\gamma)$.
There exists no quasi-Banach space $\mathcal{H}$ of
predictable integrands
$h : [0,T] \times \R \times \Omega \to \R$
satisfying all three of:
\begin{enumerate}[label=\textup{(A\arabic*)}]
\item \textup{(Homogeneity.)}
  $\|ch\|_{\mathcal{H}} = |c|\,\|h\|_{\mathcal{H}}$
  for all $c \in \R$, $h \in \mathcal{H}$.
\item \textup{(BR control.)}
  For all $h \in \mathcal{H}$,
  both terms in~\eqref{eq:BR} are finite.
\item \textup{(Contains the process.)}
  The integrand $h(t,z) = z$ lies in $\mathcal{H}$.
\end{enumerate}

\label{thm:banach-product-rule}
Let $F = f(L_T)$ and $G = g(L_T)$ with $f, g \in C_b^2(\R)$,
and let $u \in H_L$ be a bounded predictable process.
Then
\begin{equation}\label{eq:banach-product-rule}
  \langle D_L(FG), u \rangle
  = \E\!\left[\int_0^T (f'g + fg')(L_{t-})\,dL_t
  \cdot \delta_L(u)\right]
  + \E\!\left[\Gamma_L^{fg}(T) \cdot \delta_L(u)\right],
\end{equation}
where the Leibniz defect of the product is
\begin{equation}\label{eq:leibniz-defect-action}
  \Gamma_L^{fg}(T) :=
  \sum_{0 < s \leq T}
  \bigl[(fg)(L_s) - (fg)(L_{s-})
  - (f'g + fg')(L_{s-})\,\Delta L_s\bigr].
\end{equation}

\label{def:chain-defect}
For $\phi \in C_b^2(\R)$, define the chain-rule defect
\begin{equation}\label{eq:chain-defect}
  \Gamma_L^{\phi}(T) :=
  \sum_{0 < s \leq T}
  \bigl[\phi(L_s) - \phi(L_{s-}) - \phi'(L_{s-})\,\Delta L_s\bigr].
\end{equation}
This sum converges absolutely a.s.: for small jumps,
each summand is $O(|\Delta L_s|^2)$, and for large jumps,
each is bounded by $2\|\phi\|_\infty + \|\phi'\|_\infty|\Delta L_s|$.

\label{rem:hilbert-banach}
\renewcommand{\arraystretch}{1.3}
\begin{center}
\begin{tabular}{p{3cm}p{5cm}p{5cm}}
& \textbf{Hilbert~\cite{Fontes2026c}} & \textbf{Banach (this paper)} \\
\hline
Energy space & $\mathcal{H}$ (Hilbert) & $L^p$, $p < 2$ (Banach)\\
It\^o correction
  & $\frac{1}{2}\phi''\|\Pi DF\|_{\mathcal{H}}^2$
  & $\Gamma_L^{\phi}(T)$ (jump sum) \\
Correction type & Squared Hilbert norm & Leibniz defect \\
Norm controls both terms? & Yes ($L^2$-BDG) & \textbf{No}
  (Thm.~\ref{thm:impossibility}) \\
\end{tabular}
\end{center}
The common abstraction: \emph{the It\^o correction is the
Leibniz defect of the operator--covariant derivative,
evaluated through the natural pairing of the energy space
and its dual.}  In Hilbert spaces, this pairing is an
inner product.  In Banach spaces, it is a duality pairing,
and the impossibility theorem shows that it cannot be
reduced to a norm.

\label{prop:generator}
For $f \in C_b^2(\R)$, the Feynman--Kac function
$u(t,x) := \E[f(x + L_{T-t})]$ solves
$\partial_t u + \mathcal{L}u = 0$, $u(T,x) = f(x)$,
where
\begin{equation}\label{eq:generator-formula}
  \mathcal{L}f(x)
  = \int_{\R}
  \bigl(f(x+z) - f(x) - f'(x)z\,\mathbf{1}_{|z| \leq 1}\bigr)
  \,\nu(dz)
  = -(-\Delta)^{\gamma/2}f(x).
\end{equation}

\label{def:DX}
Let $X$ be a process with integrand space $H_X$ and stochastic integral
$\delta_X : H_X \to L^p(\Omega)$. The \emph{operator--covariant derivative} is the dual operator
\[
  D_X := \delta_X^* : L^q(\Omega) \to H_X^*,
\]
defined by
\begin{equation}\label{eq:DX-def}
  \langle D_X F,\, u \rangle_{H_X^*, H_X}
  \;:=\;
  \E\bigl[F \cdot \delta_X(u)\bigr]
  \qquad \text{for all } F \in L^q(\Omega),\; u \in H_X.
\end{equation}

\label{def:defect}
\textbf{Module action.}
For $F \in L^{2q}(\Omega)$ and $\varphi \in H_X^*$, the \emph{module action}
$F \cdot \varphi$ is the functional on the subspace
$\{u \in H_X : F \cdot u \in H_X\}$ defined by
\[
  \langle F \cdot \varphi,\, u \rangle_{H_X^*, H_X}
  \;:=\;
  \langle \varphi,\, F \cdot u \rangle_{H_X^*, H_X}.
\]

\textbf{Commutator defect.}
For $F, G \in L^{2q}(\Omega)$ (so that $FG \in L^q(\Omega)$), the \emph{commutator defect}
of $D_X$ is
\begin{equation}\label{eq:defect}
  \Gamma_X(F, G) \;:=\; D_X(FG) - F \cdot D_X G - G \cdot D_X F,
\end{equation}
a priori a functional on the subspace of $u \in H_X$ for which the module actions are
well-defined.
Evaluating via \eqref{eq:DX-def}:
\begin{equation}\label{eq:defect-eval}
  \langle \Gamma_X(F,G),\, u \rangle
  = \E\bigl[FG \cdot \delta_X(u)\bigr]
    - \E\bigl[G \cdot \delta_X(F \cdot u)\bigr]
    - \E\bigl[F \cdot \delta_X(G \cdot u)\bigr]
\end{equation}
for $u$ such that $F \cdot u, G \cdot u \in H_X$.

\label{def:stable-integrand}
Fix $p \in (1, \gamma)$. Define the integrand space
\[
  H_L \;:=\; L^p\bigl([0,T] \times \Omega,\, \mathcal{P},\, dt \otimes dP\bigr),
\]
the Banach space of predictable processes with finite $p$-th moment, normed by
\[
  \|u\|_{H_L}^p \;:=\; \E\!\Bigl[\int_0^T |u_t|^p\,dt\Bigr].
\]
The stochastic integral $\delta_L : H_L \to L^p(\Omega)$ is the It\^o integral with
respect to $L$, defined initially on simple predictable processes and extended by
continuity using the Burkholder--Davis--Gundy inequality for stable processes
(see \cite{Applebaum2009}):
\begin{equation}\label{eq:BDG-stable}
  c_p\,\|u\|_{H_L} \;\leq\;
  \Bigl\|\int_0^T u_t\,dL_t\Bigr\|_p
  \;\leq\;
  C_p\,\|u\|_{H_L}
\end{equation}
for constants $0 < c_p \leq C_p < \infty$ depending on $p$ and $\gamma$.

\label{prop:stable-compute}
Let $f \in C_b^1(\R)$ and $F = f(L_T)$. Then $D_L F \in H_L^*$ acts on
$u \in H_L$ as
\begin{equation}\label{eq:DL-action}
  \langle D_L F,\, u \rangle
  \;=\;
  \E\!\Bigl[f(L_T) \int_0^T u_t\,dL_t\Bigr].
\end{equation}
By the It\^o formula for L\'evy processes (\cite{Applebaum2009}, Theorem 4.4.7),
$f(L_T) = f(0) + \int_0^T f'(L_{t-})\,dL_t + J_f(T)$,
where
\begin{equation}\label{eq:jump-remainder}
  J_f(T) \;:=\; \sum_{0 < s \leq T}
  \bigl[f(L_s) - f(L_{s-}) - f'(L_{s-})\,\Delta L_s\bigr]
\end{equation}
is the compensated jump remainder.
Substituting and using \ref{H:centered}:
\begin{equation}\label{eq:DL-explicit}
  \langle D_L F,\, u \rangle
  \;=\;
  \E\!\Bigl[\int_0^T f'(L_{t-})\,dL_t \cdot \int_0^T u_t\,dL_t\Bigr]
  \;+\;
  \E\!\Bigl[J_f(T) \int_0^T u_t\,dL_t\Bigr].
\end{equation}
The first term is the ``Leibniz part'' and the second is the
``jump correction part.'' In the Brownian case ($\gamma = 2$),
$J_f(T) = \frac{1}{2}\int_0^T f''(B_t)\,dt$ and the correction is
continuous; for stable processes, $J_f(T)$ is a sum over jumps.

\label{def:DX}
Let $\delta_X : H_X \to L^p(\Omega)$ be a bounded stochastic integral
(Definition~\ref{def:integrand-space}). The \emph{operator--covariant derivative}
is the Banach-space dual operator
\[
  D_X := \delta_X^* : L^q(\Omega) \to H_X^*,
\]
defined by the duality pairing
\begin{equation}\label{eq:DX-def}
  \langle D_X F,\, u \rangle_{H_X^*, H_X}
