  \;:=\;
  \E\bigl[F \cdot \delta_X(u)\bigr]
  \qquad \text{for all } F \in L^q(\Omega),\; u \in H_X.
\end{equation}
This is well-defined and bounded: by H\"older's inequality,
$|\E[F \cdot \delta_X(u)]| \leq \|F\|_q\,\|\delta_X(u)\|_p
\leq \|F\|_q\,C_\delta\,\|u\|_{H_X}$,
so $D_X F \in H_X^*$ with $\|D_X F\|_{H_X^*} \leq C_\delta\,\|F\|_q$.

\label{def:defect}
\textbf{Module action.}
For $F \in L^{2q}(\Omega)$ and $\varphi \in H_X^*$, the \emph{module action}
$F \cdot \varphi$ is the functional on the subspace
$\{u \in H_X : F \cdot u \in H_X\}$ defined by
\[
  \langle F \cdot \varphi,\, u \rangle_{H_X^*, H_X}
  \;:=\;
  \langle \varphi,\, F \cdot u \rangle_{H_X^*, H_X}.
\]

\textbf{Leibniz defect.}
For $F, G \in L^{2q}(\Omega)$ (so that $FG \in L^q(\Omega)$), the \emph{Leibniz defect}
of $D_X$ is
\begin{equation}\label{eq:defect}
  \Gamma_X(F, G) \;:=\; D_X(FG) - F \cdot D_X G - G \cdot D_X F,
\end{equation}
a priori a functional on the subspace of $u \in H_X$ for which the module actions are
well-defined.
Evaluating via \eqref{eq:DX-def}:
\begin{equation}\label{eq:defect-eval}
  \langle \Gamma_X(F,G),\, u \rangle
  = \E\bigl[FG \cdot \delta_X(u)\bigr]
    - \E\bigl[G \cdot \delta_X(F \cdot u)\bigr]
    - \E\bigl[F \cdot \delta_X(G \cdot u)\bigr]
\end{equation}
for $u$ such that $F \cdot u, G \cdot u \in H_X$.
When $D_X$ is a derivation ($\Gamma_X = 0$), one recovers classical calculus;
$\Gamma_X \neq 0$ is the algebraic signature of stochastic calculus.

\label{prop:stable-compute}
Let $f \in C_b^2(\R)$ and $F = f(L_T)$. Then $D_L F \in H_L^*$ acts on
$u \in H_L$ as
\begin{equation}\label{eq:DL-action}
  \langle D_L F,\, u \rangle
  \;=\;
  \E\!\Bigl[f(L_T) \int_0^T u_t\,dL_t\Bigr].
\end{equation}
Moreover, $D_L F$ decomposes as
\begin{equation}\label{eq:DL-explicit}
  \langle D_L F,\, u \rangle
  \;=\;
  \E\!\Bigl[\int_0^T f'(L_{t-})\,dL_t \cdot \int_0^T u_t\,dL_t\Bigr]
  \;+\;
  \E\!\Bigl[J_f(T) \int_0^T u_t\,dL_t\Bigr],
\end{equation}
where
\begin{equation}\label{eq:jump-remainder}
  J_f(T) \;:=\; \sum_{0 < s \leq T}
  \bigl[f(L_s) - f(L_{s-}) - f'(L_{s-})\,\Delta L_s\bigr]
\end{equation}
is the compensated jump remainder.
The first term in \eqref{eq:DL-explicit} is the ``Leibniz part'' and
the second is the ``jump correction part.'' By analogy, in the Brownian case
($\gamma = 2$, outside the scope of the present framework),
$J_f(T) = \frac{1}{2}\int_0^T f''(B_t)\,dt$ and the
correction is continuous; for stable processes, $J_f(T)$ is a sum over jumps.

\label{thm:stable-defect}
Let $f, g \in C_b^2(\R)$, $F = f(L_T)$, $G = g(L_T)$. For bounded predictable $u \in H_L$, define
the \emph{predictable Leibniz contribution}
\[
  \mathcal{L}(F,G; u) :=
  \E\!\Bigl[\int_0^T\! f'(L_{t-})\,g(L_{t-})\,dL_t \cdot \delta_L(u)\Bigr]
  + \E\!\Bigl[\int_0^T\! f(L_{t-})\,g'(L_{t-})\,dL_t \cdot \delta_L(u)\Bigr],
\]
and the \emph{Leibniz defect} by
\[
  \langle \Gamma_L(F,G),\, u \rangle
  := \langle D_L(FG), u \rangle - \mathcal{L}(F,G; u).
\]
Then $\Gamma_L(F,G) \in H_L^*$, and
\begin{equation}\label{eq:stable-defect}
  \langle \Gamma_L(F,G),\, u \rangle
  \;=\;
  \E\!\Biggl[
  \sum_{0 < s \leq T}
  \Delta_s(f,g)
  \cdot \delta_L(u)\Biggr],
\end{equation}
where the \emph{product jump defect} at time $s$ is
\begin{equation}\label{eq:jump-defect}
  \Delta_s(f,g) \;:=\;
  (fg)(L_s) - (fg)(L_{s-})
    - f'(L_{s-})\,g(L_{s-})\,\Delta L_s
    - f(L_{s-})\,g'(L_{s-})\,\Delta L_s.
\end{equation}
In particular, $\Gamma_L(F,G) \neq 0$ whenever $f$ or $g$ is nonlinear.

