\label{def:integrand-space}
An \emph{integrand space} for a process $X$ is a Banach space $H_X$
of jointly measurable processes with a bounded linear
\emph{stochastic integral}
$\delta_X : H_X \to L^p(\Omega)$,
$\|\delta_X(u)\|_{L^p} \leq C_\delta\,\|u\|_{H_X}$.

\label{def:derivative}
The \emph{operator--covariant derivative} is
$D_X := \delta_X^* : L^q(\Omega) \to H_X^*$, defined by
\begin{equation}\label{eq:DX-def}
  \langle D_X F, u \rangle_{H_X^*, H_X}
  := \E\bigl[F \cdot \delta_X(u)\bigr].
\end{equation}
This is bounded: $\|D_X F\|_{H_X^*} \leq C_\delta\,\|F\|_q$.

\label{rem:DX-dual}
$D_X F \in H_X^*$, not $H_X$.  When $H_X$ is Hilbert, Riesz
identifies these; when $H_X$ is Banach, the distinction is essential.

\label{ass:factorization}
\begin{enumerate}[label=\textup{(H\arabic*)}]
\item \textup{Centered integrals:}
  $\E[\delta_X(u)] = 0$ for all $u \in H_X$.
\item \textup{Injectivity:}
  $\beta_X(v,u) := \E[\delta_X(v) \cdot \delta_X(u)]$ is
  non-degenerate on $H_X^{\mathcal{P}}$.
\item \textup{Representation:}
  Every centered $\tilde{F} \in L^p \cap L^q$ is
  $\tilde{F} = \delta_X(v)$ for predictable $v$.
\item \textup{Bounded conditional expectation:}
  $\Pi_X$ satisfies Definition~\ref{def:predictable}.
\end{enumerate}

\label{thm:factorization}
Under (H1)--(H4), for all $\mathcal{F}_T^X$-measurable
$F \in L^p \cap L^q$:
\begin{equation}\label{eq:factorization-thm}
  F - \E[F] = \delta_X\bigl(\iota_X^{-1}(D_X F|_{H_X^{\mathcal{P}}})\bigr).
\end{equation}
Equivalently: $\Id - \E = \delta_X \circ \iota_X^{-1} \circ r \circ D_X$.

\label{def:leibniz}
For $F, G \in L^{2q}(\Omega)$:
\begin{equation}\label{eq:leibniz-abstract}
  \Gamma_X(F,G) := D_X(FG) - F \cdot D_X G - G \cdot D_X F
  \;\in H_X^*.
\end{equation}
When $D_X$ is a derivation ($\Gamma_X = 0$), one recovers classical
calculus; $\Gamma_X \neq 0$ is the algebraic signature of stochastic
calculus.

\label{def:HL}
Fix $p \in (1,\gamma)$.
$H_L := L^p([0,T] \times \Omega, \mathcal{P}, dt \otimes dP)$,
with $\delta_L(u) := \int_0^T u_t\,dL_t$ and BDG equivalence
\begin{equation}\label{eq:BDG}
  c_p\,\|u\|_{H_L} \leq \|\delta_L(u)\|_{L^p}
  \leq C_p\,\|u\|_{H_L}.
\end{equation}

