  = \E\!\left[\int_0^T f'(L_{t-})\,dL_t \cdot \delta_L(u)\right]
  + \E\!\left[J_f(T) \cdot \delta_L(u)\right],
\end{equation}
where
\begin{equation}\label{eq:jump-remainder}
  J_f(T) := \sum_{0 < s \leq T}
  [f(L_s) - f(L_{s-}) - f'(L_{s-})\Delta L_s]
\end{equation}
is the compensated jump remainder.  The first term in
\eqref{eq:DLF-decomp} is the ``Leibniz part'' and the second is the
``jump correction part.''

\label{prop:H3-fails}
$\im(\delta_L) \subsetneq L^p_0(\Omega)$: there exist centered
functionals in $L^p \cap L^q$ not representable as $\int u_t\,dL_t$.

\label{prop:DLF}
For $f \in C_b^2(\R)$ and $F = f(L_T)$, $D_L F \in H_L^*$ acts on
$u \in H_L$ as
\begin{equation}\label{eq:DL-action}
  \langle D_L F, u \rangle = \E\!\left[f(L_T) \int_0^T u_t\,dL_t\right].
\end{equation}
Moreover, $D_L F$ decomposes as
\begin{equation}\label{eq:DLF-decomp}
  \langle D_L F, u \rangle
  = \E\!\left[\int_0^T f'(L_{t-})\,dL_t \cdot \delta_L(u)\right]
  + \E\!\left[J_f(T) \cdot \delta_L(u)\right],
\end{equation}
where
\begin{equation}\label{eq:jump-remainder}
  J_f(T) := \sum_{0 < s \leq T}
  [f(L_s) - f(L_{s-}) - f'(L_{s-})\Delta L_s]
\end{equation}
is the compensated jump remainder.  The first term in
\eqref{eq:DLF-decomp} is the ``Leibniz part'' and the second is the
``jump correction part.''

\label{prop:H3-fails}
$\im(\delta_L) \subsetneq L^p_0(\Omega)$: there exist centered
functionals in $L^p \cap L^q$ not representable as $\int u_t\,dL_t$.

\label{thm:chaos}
Let $L$ be a symmetric $\gamma$-stable process with
$\gamma \in (1,2)$, and let $F \in L^2(\Omega, \mathcal{F}_T^L)$
with Poisson chaos expansion $F = \sum_{n \geq 0} I_n(f_n)$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item \textup{(Kernel.)}
  $D_L F = 0$ if and only if
  \begin{equation}\label{eq:kernel-char}
    \Phi_M(s) := \int_{|z| \leq M}
    f_1(s,z)\,z\,\nu_\gamma(dz) \;\longrightarrow\; 0
    \quad \text{in } L^q([0,T], dt) \text{ as } M \to \infty.
  \end{equation}
  In particular, $\ker(D_L)$ contains all constants, the entire
  higher chaos $\bigoplus_{n \geq 2} \mathcal{C}_n$, and all
  first-chaos elements with even kernels.

\item \textup{(Range characterization.)}
  The $L^p$-closure of $\im(\delta_L)$ satisfies
  \begin{equation}\label{eq:range-char}
    \overline{\im(\delta_L)}^{L^p}
    = \bigl\{I_1(h) \in L^p(\Omega) :
    h = \lim_{M \to \infty} \alpha_M \cdot z_M
    \text{ in } L^p(\Omega)\text{-integral sense}\bigr\},
  \end{equation}
  where the closure is taken in $L^p_0(\Omega)$.  Equivalently,
  $\overline{\im(\delta_L)}^{L^p}$ consists of all first-chaos
  elements representable as limits of integrals
  $\int\!\int \alpha_M(s)\,z\,\mathbf{1}_{|z| \leq M}\,
  \widetilde{N}(ds,dz)$ in $L^p$.

\item \textup{(Annihilator.)}
  The $L^q$--$L^p$ annihilator of $\im(\delta_L)$ in
  $L^q_0(\Omega)$ is
  \begin{equation}\label{eq:annihilator}
    \im(\delta_L)^{\perp_{q,p}}
    := \{G \in L^q_0(\Omega, \mathcal{F}_T^L) :
    \E[G \cdot \delta_L(u)] = 0 \;\forall\, u \in H_L\}.
  \end{equation}
  This annihilator contains: all centered elements of the higher
  chaoses $\mathcal{C}_n$ ($n \geq 2$), and all first-chaos elements
  $I_1(h)$ satisfying \eqref{eq:kernel-char}.

  The annihilator is infinite-dimensional: the first-chaos elements
  $I_1(h_k)$ with $h_k(s,z) := \mathbf{1}_{[0,T]}(s)\,
  \mathbf{1}_{k < |z| \leq k+1}$ for $k = 1, 2, 3, \ldots$ are
  linearly independent elements of the annihilator.
\end{enumerate}

\label{prop:DLF}
For $f \in C_b^2(\R)$ and $F = f(L_T)$, $D_L F \in H_L^*$ acts on
$u \in H_L$ as
\begin{equation}\label{eq:DL-action}
  \langle D_L F, u \rangle = \E\!\left[f(L_T) \int_0^T u_t\,dL_t\right].
\end{equation}
Moreover, $D_L F$ decomposes as
\begin{equation}\label{eq:DLF-decomp}
  \langle D_L F, u \rangle
  = \E\!\left[\int_0^T f'(L_{t-})\,dL_t \cdot \delta_L(u)\right]
  + \E\!\left[J_f(T) \cdot \delta_L(u)\right],
\end{equation}
where
\begin{equation}\label{eq:jump-remainder}
  J_f(T) := \sum_{0 < s \leq T}
  [f(L_s) - f(L_{s-}) - f'(L_{s-})\Delta L_s]
\end{equation}
is the compensated jump remainder.  The first term in
\eqref{eq:DLF-decomp} is the ``Leibniz part'' and the second is the
``jump correction part.''

\label{def:transfer}
The \emph{block transfer operator} is the conditional expectation
\begin{equation}\label{eq:transfer}
(TF)(x) := \E_\mu[F(x,y) \mid x] = \int F(x,y)\, \mu(dy \mid x).
\end{equation}

\label{def:sobolev}
$T$ is \emph{Sobolev contractive} with constant $q < 1$ if
\begin{equation}\label{eq:sobolev-contract}
\norm{\nabla_x (TF)}_{L^2(\mu_x)} \leq q\, \norm{\nabla F}_{L^2(\mu)}.
\end{equation}

\label{def:free-fact}
The quadratic core satisfies \emph{free factorization} if
\begin{equation}\label{eq:free-fact}
\nabla^2_{xy} V_0 = 0,
\end{equation}
i.e., the mixed Hessian vanishes.

The reference transfer operator is
\begin{equation}
(T_0 F)(x) := \E_{\mu_0}[F(x,y) \mid x]
= \int F(x,y)\, \mu_0^y(dy).
\end{equation}

\label{lem:ym-fact}
The quadratic approximation to the Wilson action satisfies
\begin{equation}
V_0(x,y) = \frac{\beta c_2}{2} \norm{Ay + vx}^2
= \frac{\beta c_2}{2}\bigl(\norm{Ay}^2 + 2\ip{Ay}{vx} + \norm{vx}^2\bigr).
\end{equation}
The constraint $A^\top v = 0$ (which holds by the lattice Bianchi identity)
implies that the mixed Hessian $\nabla^2_{xy} V_0 = \beta c_2\, A^\top v = 0$.

\label{thm:ym}
For $\beta \geq \beta_0$ sufficiently large, the hypotheses of
Theorem~\ref{thm:abstract} hold with:
\begin{enumerate}[label=(\roman*)]
\item $q_0 = e^{-\lambda_1(A^\top A)/\beta} < 1$, where $\lambda_1(A^\top A)$
  is the smallest nonzero eigenvalue of the fiber Laplacian;
\item $\varepsilon_B = O(1/\beta)$ from the Baker--Campbell--Hausdorff
  expansion of the non-abelian plaquette action;
\item $\eta = O(1/\beta)$ from the covariance correction.
\end{enumerate}
For $\beta$ large, $q = q_0 + O(1/\beta) < 1$.

Sobolev contraction $q < 1$ implies exponential decay of correlations:
\begin{equation}
\abs{\ip{F}{G}_\mu - \ip{F}{\mathbf{1}}_\mu \ip{\mathbf{1}}{G}_\mu}
\leq C\, q^{d(F,G)/L}\, \norm{F}_{H^1}\, \norm{G}_{H^1},
\end{equation}
where $d(F,G)$ is the lattice distance between the supports of $F$
and $G$.  This is equivalent to a spectral gap (mass gap)
$m \geq -\log q / L > 0$.

\label{lem:ns-fact}
The enstrophy $\mathcal{E}(u) = \frac{1}{2}\norm{\nabla u}_{L^2}^2$
has block-diagonal Hessian with respect to the frequency decomposition:
\begin{equation}\label{eq:ns-orth}
\ip{\Pi_{\leq K} u}{\Pi_{>K} u}_{L^2} = 0,
\qquad
\ip{\Pi_{\leq K} u}{\Pi_{>K} u}_{H^s} = 0
\quad \forall\, s \geq 0.
\end{equation}
Consequently,
\begin{equation}
\mathcal{E}(u) = \mathcal{E}(u_{\leq K}) + \mathcal{E}(u_{>K}),
\end{equation}
and the Gaussian part of any Gibbs-type measure
$\mu \propto e^{-\mathcal{E}/\nu}$ factorizes:
$e^{-\mathcal{E}/\nu} = e^{-\mathcal{E}(u_{\leq K})/\nu}
\cdot e^{-\mathcal{E}(u_{>K})/\nu}$.

\label{lem:ns-ref}
For the Gaussian reference (viscous part only), the high-frequency
conditional expectation contracts with
\begin{equation}
q_0 = e^{-\nu (K+1)^2\, t_{\mathrm{eff}}},
\end{equation}
where $(K+1)^2$ is the spectral gap of $-\Delta$ restricted to
$\{|k| > K\}$ and $t_{\mathrm{eff}}$ is the effective time scale.

\label{lem:triadic}
The projection $\Pi_{>K} B(u,u)$ at frequency $m$ with $|m| > K$
requires $k + \ell = m$ with $\max(|k|, |\ell|) \geq K/2$.
In particular:
\begin{equation}
\Pi_{>K} B(u_{\leq K/2},\, u_{\leq K/2}) = 0.
\end{equation}

\label{thm:cone-perturb}
Let $u$ be $\delta$-concentrated.  Then the trilinear form satisfies
\begin{equation}\label{eq:cone-tri}
\abs{\int_{\T^3} (u \cdot \nabla v) \cdot w\, dx}
\leq C_0\, \delta\, \norm{u}_{\dot{H}^{1/2}}\, \norm{v}_{\dot{H}^{3/2}}\,
\norm{w}_{\dot{H}^{1/2}}
\end{equation}
for all divergence-free $u, v, w$ with Fourier support in
$\mathcal{C}_\delta(\hat{n})$, where $C_0$ depends only on dimension.

In particular, the perturbation in the block-contraction framework
satisfies
\begin{equation}
\varepsilon_B \leq C_0\, \delta\, \frac{\norm{u}_{\dot{H}^{1/2}}}{\nu}.
\end{equation}

\label{thm:ns-reg}
Let $u$ be a smooth solution of~\eqref{eq:NS} on $[0, T^*)$ with
$\delta$-concentrated Fourier support.  If
\begin{equation}\label{eq:ns-threshold}
\delta < \delta_* := \frac{\nu}{2C_0\, \norm{u}_{\dot{H}^{1/2}}},
\end{equation}
then hypotheses \ref{H1}--\ref{H5} of Theorem~\ref{thm:abstract}
hold, and the total contraction satisfies $q < 1$.  Consequently:
\begin{equation}
\frac{d}{dt}\norm{u}_{\dot{H}^{1/2}}^2 \leq -\nu\, \norm{u}_{\dot{H}^{3/2}}^2,
\end{equation}
and the solution extends smoothly beyond $T^*$ with algebraic decay
\begin{equation}
\norm{u(t)}_{\dot{H}^{1/2}}^2 \leq
\frac{\norm{u(t_0)}_{\dot{H}^{1/2}}^2}
{(1 + c\, \norm{u(t_0)}_{\dot{H}^{1/2}}\, (t - t_0))^2}.
\end{equation}

The gap between conditional and unconditional regularity is:
\begin{quote}
\emph{Can the Navier--Stokes flow maintain angular concentration
$\delta(t) \leq \delta_*(t)$ as $\norm{u}_{\dot{H}^{1/2}} \to \infty$?}
\end{quote}
If not, the solution must eventually leave the regime where the
perturbation is small, and then either disperse (regularity) or
develop multi-directional concentration (which is \emph{not}
covered by cone depletion but faces stronger nonlinear cancellations).

The YM analogy suggests that the correct approach is to find an NS
analogue of the ``corridor'' argument: a set of states (defined by
angular concentration) that is dynamically absorbing, with
perturbation bounds that hold uniformly on this set.

\label{prop:core-schur}
Assume $A^\top A$ is invertible.  Then the Schur complement of $V_{yy}^{(0)}$ in $\nabla^2 V^{(0)}$ is
\begin{equation}\label{eq:core-schur}
\mathrm{Schur}(V^{(0)}) \;=\; \beta c_2\,v^\top(I-P_A)\,v.
\end{equation}
Under $A^\top v = 0$ (Lemma~\ref{lem:Atv0}) with $v=(1,\ldots,1)^\top\in\R^{n_p}$,
\begin{equation}\label{eq:schur-value}
\mathrm{Schur}(V^{(0)}) \;=\; n_p\,\beta\, c_2.
\end{equation}
In particular, for a $2\times 2$ tile with $n_p=4$ plaquettes, $\mathrm{Schur}(V^{(0)})=4\beta c_2$.

\label{lem:schur-stab}
Let $H, H_0$ be symmetric block matrices with $H_0$ having invertible lower-right block $C_0\succeq m_0 I$.
If $\norm{H-H_0}_{\mathrm{block}}\le(\eta_{xx},\eta_{xy},\eta_{yy})$ with $\eta_{yy}\le\frac{1}{2}m_0$,
and if $b_0$ denotes the off-diagonal block of $H_0$, then
\begin{equation}\label{eq:schur-stab}
\mathrm{Schur}(H) \;\ge\; \mathrm{Schur}(H_0)
- \eta_{xx} - \frac{4\eta_{xy}^2}{m_0} - \frac{2\norm{b_0}^2}{m_0^2}\,\eta_{yy}.
\end{equation}

\label{thm:robust-schur}
Under Assumptions~\ref{ass:coerc}--\ref{ass:C2}, if $K_{yy}\le\frac{1}{2}\beta c_2\lambda_i$,
then
\begin{equation}\label{eq:robust-schur}
\mathrm{Schur}(V) \;\ge\; n_p\,\beta c_2 - K_{xx} - \frac{4K_{xy}^2}{\beta c_2\lambda_i}.
\end{equation}
In particular, if $K_{xx}=o(\beta)$ and $K_{xy}=o(\beta)$ as $\beta\to\infty$
(corridor scaling), then $\mathrm{Schur}(V)\ge\frac{n_p}{2}\,\beta c_2$ for $\beta$
sufficiently large.

