\label{thm:main}
For pure $\mathrm{SU}(2)$ Yang--Mills theory on $\Z^3$ in
Hamiltonian formulation:
\begin{equation}
m(g^2) > 0 \qquad \text{for all } g^2 > 0.
\end{equation}

\label{thm:general}
For pure Yang--Mills theory on $\Z^3$ with any compact simple gauge
group~$G$:
\begin{equation}
m_G(g^2) > 0 \qquad \text{for all } g^2 > 0.
\end{equation}

\label{def:intrinsic-bracket}
For a kernel-driven process $Z$ with kernel $K$ and bracket measure $\mu$, define:
\begin{equation}\label{eq:Gamma}
\Gamma_K(t) := \int_0^t K(t,s)^2\,\mu(ds).
\end{equation}
This is the \emph{intrinsic bracket} of $Z$ at time $t$.

\label{def:DeltaGamma}
The \emph{fresh-noise energy increment} is
\begin{equation}\label{eq:DeltaGamma}
\dGamma(t,h) := \int_t^{t+h} K(t+h,s)^2\,\mu(ds) = \E[F_{t,h}^2 \mid \F_t].
\end{equation}

\label{def:operator-deriv}
Let $X$ be a process with a closed stochastic integral $\delta_X: \HH_X \to L^2(\Omega)$ 
on an energy space $\HH_X$. The \emph{operator derivative} $D_X F$ is defined, 
for $F \in L^2(\Omega)$, as the unique element of $L^2(\Omega; \HH_X)$ satisfying
\begin{equation}\label{eq:riesz}
\E[F \cdot \delta_X(u)] = \E[\ip{D_X F}{u}_{\HH_X}] \quad \text{for all } u \in \HH_X.
\end{equation}

\label{prop:second-order}
For a kernel-driven process $Z$ with increment decomposition $\Delta Z = H + F$:
\begin{align}
\E[(\Delta Z)^2 \mid \F_t] &= \E[H^2 \mid \F_t] + 2\E[HF \mid \F_t] + \E[F^2 \mid \F_t] \\
&= \E[H^2 \mid \F_t] + \dGamma(t,h), \label{eq:second-order-decomp}
\end{align}
where we used $\E[HF \mid \F_t] = H \cdot \E[F \mid \F_t] = 0$ (martingale property).

\label{def:alpha}
A kernel $K$ has \emph{regularity exponent} $\alpha > 0$ if
\begin{equation}\label{eq:alpha}
\|K(t+h, \cdot) - K(t, \cdot)\|_{L^2([0,t], \mu)} \lesssim h^\alpha
\end{equation}
uniformly in $t$ on compact sets.

\label{thm:leibniz-fails}
Let $M_t = \int_0^t W_s\,dW_s$. Then:
\begin{equation}\label{eq:failure}
(D_M(M_T^2))_t = 2M_t \neq 2M_T = 2M_T \cdot (D_M(M_T))_t.
\end{equation}
The standard Leibniz rule fails.

\label{thm:cov-density}
Let $M_t = \int_0^t \sigma_s\,dW_s$ with $\sigma_t > 0$ a.s. For $F \in \Dom(D_M)$:
\begin{equation}\label{eq:cov-density}
(D_M F)_t = \frac{1}{\sigma_t^2} \lim_{\epsilon \to 0} \frac{1}{\epsilon}
\E[F \cdot (M_{t+\epsilon} - M_t) \mid \F_t].
\end{equation}

\label{thm:modified-leibniz}
For $F, G \in \Dom(D_M)$ with sufficient integrability:
\begin{equation}\label{eq:modified-leibniz}
(D_M(FG))_t = \E[F \mid \F_t] \cdot (D_M G)_t + \E[G \mid \F_t] \cdot (D_M F)_t.
\end{equation}

\label{thm:chain}
Let $X$ be a process with operator derivative $D_X$, and let $f \in C^2(\R)$. 
For $F \in \Dom(D_X)$ with sufficient regularity:
\begin{equation}\label{eq:chain}
D_X(f(F))_t = f'(\E[F|\F_t]) \cdot (D_X F)_t + \text{higher-order corrections}.
\end{equation}
When $F$ is $\F_t$-measurable, this reduces to $D_X(f(F))_t = f'(F) \cdot (D_X F)_t$.

\label{def:hurst}
A kernel-driven process $Z$ has \emph{operator-induced Hurst exponent} $H \in (0,1)$ 
if
\begin{equation}\label{eq:hurst}
\dGamma(t,h) \asymp h^{2H} \quad \text{as } h \to 0
\end{equation}
uniformly in $t$ on compact sets.

\label{prop:fBM-scaling}
Fractional Brownian motion with Hurst parameter $H$ satisfies 
$\dGamma(t,h) \asymp h^{2H}$.

\label{def:intrinsic-bracket}
For a kernel-driven process $Z$ with kernel $K$ and bracket measure $\mu$, define:
\begin{equation}\label{eq:Gamma}
\Gamma_K(t) := \int_0^t K(t,s)^2\,\mu(ds).
\end{equation}
This is the \emph{intrinsic bracket} of $Z$ at time $t$.

\label{def:DeltaGamma}
The \emph{fresh-noise energy increment} is
\begin{equation}\label{eq:DeltaGamma}
\dGamma(t,h) := \int_t^{t+h} K(t+h,s)^2\,\mu(ds) = \E[F_{t,h}^2 \mid \F_t].
