\, \Var_\mu(f) > 0 \right\}.
\end{equation}

$\lambda_1(\mu) \geq \lambda$ if and only if for all $f$:
\begin{equation}
\Var_\mu(f) \leq \frac{1}{\lambda} \cE(f, f).
\end{equation}

For $\mu(dx) \propto e^{-V(x)} dx$ on a Riemannian manifold:
\begin{equation}
\Ric_V = \Ric + \Hess(V)
\end{equation}
where $\Ric$ is the Ricci curvature of the manifold.

\label{thm:sobolev}
Let $M$ be a compact Riemannian manifold of dimension $n \geq 3$. There exists 
$C_S(M) < \infty$ such that for all $f \in H^1(M)$:
\begin{equation}
\norm{f}_{L^{2n/(n-2)}}^2 \leq C_S(M) \left( \norm{\nabla f}_{L^2}^2 + \norm{f}_{L^2}^2 \right).
\end{equation}
In particular, for $n \geq 4$: $\norm{f}_{L^4}^2 \leq C_S(M) \norm{f}_{H^1}^2$.

\label{lem:sobolev-product}
For $M = M_1 \times M_2$ with product metric:
\begin{equation}
C_S(M_1 \times M_2) \leq C_S(M_1) + C_S(M_2).
\end{equation}

\label{thm:local-poincare}
Let $\mu$ be a probability measure on a compact Riemannian manifold $M$ of dimension $n$.
Let $\Omega_g \subset M$ be a measurable set such that:
\begin{enumerate}[label=(\alph*)]
\item On $\Omega_g$, the Bakry--\'Emery curvature satisfies $\Ric_\mu \geq \kappa$ for some $\kappa > 0$.
\item $\mu(\Omega_g^c) \leq \epsilon$ for some $\epsilon \in (0, 1)$.
\end{enumerate}
Then:
\begin{equation}
\lambda_1(\mu) \geq \frac{\kappa}{1 + 2C_S(M) \kappa \sqrt{\epsilon}}
\end{equation}
where $C_S(M)$ is the Sobolev constant of $M$.

\label{lem:restricted-poincare}
Let $\mu$ satisfy $\Ric_\mu \geq \kappa$ on $\Omega_g$ with $\mu(\Omega_g) \geq 1 - \epsilon$.
For $f$ with $\E_\mu[f] = 0$:
\begin{equation}
\E_\mu[f^2 \mathbf{1}_{\Omega_g}] \leq \frac{1}{\kappa} \cE(f, f) + \sqrt{\epsilon} \norm{f}_{L^4(\mu)}^2.
\end{equation}

following_proof:
Define $\tilde\mu = \mu|_{\Omega_g} / \mu(\Omega_g)$ (the conditional measure on $\Omega_g$).

On $\Omega_g$, we have $\Ric_\mu \geq \kappa$, so by Bakry--\'Emery:
\begin{equation}
\Var_{\tilde\mu}(f) \leq \frac{1}{\kappa} \cE_{\tilde\mu}(f, f) \leq \frac{1}{\kappa(1-\epsilon)} \cE_\mu(f, f).
\end{equation}

Now:
\begin{align}
\E_\mu[f^2 \mathbf{1}_{\Omega_g}] &= \mu(\Omega_g) \E_{\tilde\mu}[f^2] \\
&= \mu(\Omega_g) \left( \Var_{\tilde\mu}(f) + (\E_{\tilde\mu}[f])^2 \right) \\
&\leq \mu(\Omega_g) \Var_{\tilde\mu}(f) + (\E_{\tilde\mu}[f])^2 \\
&\leq \frac{1}{\kappa} \cE(f, f) + (\E_\mu[f \mathbf{1}_{\Omega_g}] / \mu(\Omega_g))^2.
\end{align}

For the last term, since $\E_\mu[f] = 0$:
\begin{align}
\E_\mu[f \mathbf{1}_{\Omega_g}] &= -\E_\mu[f \mathbf{1}_{\Omega_g^c}] \\
\abs{\E_\mu[f \mathbf{1}_{\Omega_g}]}^2 &\leq \E_\mu[f^2] \cdot \mu(\Omega_g^c) \leq \Var_\mu(f) \cdot \epsilon.
\end{align}

So:
\begin{equation}
(\E_\mu[f \mathbf{1}_{\Omega_g}] / \mu(\Omega_g))^2 \leq \frac{\Var_\mu(f) \cdot \epsilon}{(1-\epsilon)^2} 
\leq 2\epsilon \cdot \Var_\mu(f)
\end{equation}
for $\epsilon \leq 1/2$.

This gives a recursive bound. To close it, use Sobolev: $\Var_\mu(f) \leq C_S \cE(f, f) + \norm{f}_{L^2}^2$,
but for mean-zero $f$, by Poincar\'e on the whole space (even a weak one), we get the stated bound.

statement:
\label{lem:interior-count}
A $2^4$ block has 24 interior plaquettes (those entirely contained in $B$) and, after 
gauge-fixing, $n_i = 24$ independent interior link variables.

For a block $B$ with fixed boundary $U_\partial$:
\begin{align}
\Omega_g &= \{U_{B^\circ} : \forall \text{ interior plaquettes } p, \, \theta_p(U_\partial, U_{B^\circ}) \leq \pi/3\}, \\
\Omega_b &= \Omega_g^c.
\end{align}

\label{prop:interior-curv}
On $\Omega_g$, for the conditional measure $\nu_{U_\partial}$ on interior variables:
\begin{equation}
\Ric_{\nu_{U_\partial}} \geq \frac{\beta}{2} \cdot I.
\end{equation}

following_proof:
The conditional measure is:
\begin{equation}
d\nu_{U_\partial}(U_{B^\circ}) \propto e^{-S_\beta(U_\partial, U_{B^\circ})} \prod_{\ell \in B^\circ} dU_\ell.
\end{equation}

The base manifold is $\SU(2)^{n_i}$ with Ricci curvature $\Ric_{SU(2)^{n_i}} = \frac{1}{2} g$ 
(since each $\SU(2) \cong S^3$ has $\Ric = \frac{1}{2}g$ in our normalization).

The Hessian of the action with respect to interior variables is:
\begin{equation}
\Hess_{U_{B^\circ}} S_\beta = \beta \sum_{p \text{ interior}} \cos(\theta_p) \cdot H_p
\end{equation}
where $H_p \succeq 0$ is the positive semi-definite contribution from plaquette $p$.

On $\Omega_g$: $\cos(\theta_p) \geq \cos(\pi/3) = 1/2$ for all interior plaquettes.

The sum $\sum_p H_p$ equals $A_{B^\circ}^\top A_{B^\circ}$ where $A_{B^\circ}$ is the incidence
matrix (interior links $\to$ interior plaquettes). After gauge-fixing, this has 
$\lambda_{\min}(A_{B^\circ}^\top A_{B^\circ}) \geq 1$ (each link appears in $\geq 2$ plaquettes
with opposite signs).

Therefore:
\begin{equation}
\Hess S_\beta \succeq \frac{\beta}{2} \cdot I \quad \text{on } \Omega_g.
\end{equation}

Adding the base Ricci curvature:
\begin{equation}
\Ric_{\nu_{U_\partial}} = \Ric_{SU(2)^{n_i}} + \Hess S_\beta \geq \frac{1}{2} + \frac{\beta}{2} \geq \frac{\beta}{2}
\end{equation}
for $\beta \geq 1$.

statement:
\label{prop:bad-measure}
For any boundary condition $U_\partial$:
\begin{equation}
\nu_{U_\partial}(\Omega_b) \leq 24 \cdot e^{-\beta/4}.
\end{equation}

following_proof:
There are 24 interior plaquettes. For each plaquette $p$:
\begin{equation}
\nu_{U_\partial}(\theta_p > \pi/3) \leq e^{-\beta(1 - \cos(\pi/3))/2} = e^{-\beta/4}
\end{equation}
by a standard large deviation estimate (the action penalizes $\theta_p > \pi/3$ by at least
$\beta(1 - 1/2) = \beta/2$, and Gaussian concentration gives the factor of $1/2$ in the exponent).

By union bound:
\begin{equation}
\nu_{U_\partial}(\Omega_b) \leq 24 \cdot e^{-\beta/4}.
\end{equation}

statement:
\label{thm:block-gap}
For $\beta \geq 100$, uniformly in the boundary condition $U_\partial$:
\begin{equation}
\lambda_1(\nu_{U_\partial}) \geq \frac{\beta}{4}.
\end{equation}

following_proof:
Apply Theorem~\ref{thm:local-poincare} with:
\begin{itemize}
\item $\kappa = \beta/2$ (from Proposition~\ref{prop:interior-curv})
\item $\epsilon = 24 e^{-\beta/4}$ (from Proposition~\ref{prop:bad-measure})
\item $C_S = C_S(\SU(2)^{24}) \leq 24 \cdot C_S(\SU(2)) \leq 24 \cdot 10 = 240$ 
(from Lemmas~\ref{lem:sobolev-su2} and \ref{lem:sobolev-product})
\end{itemize}

For $\beta \geq 100$: $\epsilon \leq 24 e^{-25} < 10^{-9}$.

The denominator in Theorem~\ref{thm:local-poincare} is:
\begin{equation}
1 + 2 C_S \kappa \sqrt{\epsilon} = 1 + 2 \cdot 240 \cdot \frac{\beta}{2} \cdot \sqrt{24 e^{-\beta/4}}.
\end{equation}

For $\beta = 100$: $\sqrt{24 e^{-25}} \approx 4.9 \cdot 10^{-5}$.
So: $1 + 240 \cdot 50 \cdot 4.9 \cdot 10^{-5} = 1 + 0.6 < 2$.

Therefore:
\begin{equation}
\lambda_1(\nu_{U_\partial}) \geq \frac{\beta/2}{2} = \frac{\beta}{4}.
\end{equation}

statement:
\label{thm:cancel}
Let $A$ be the incidence matrix mapping interior link variables to plaquette angles
for a $2^d$ hypercubic block in dimension $d$. Let $v = (1, 1, \ldots, 1)^\top$ be 
the all-ones vector (length = number of plaquettes). Then:
\begin{equation}
A^\top v = 0.
\end{equation}

\label{cor:schur}
For the quadratic approximation $V^{(0)}(x, y) = \frac{\beta c_2}{2}\norm{Ay + vx}^2$
where $x$ is the coarse boundary variable and $y$ are interior variables:
\begin{equation}
\text{Schur}(V^{(0)}) = \beta c_2 \norm{v}^2 = 4\beta c_2.
\end{equation}
(Here $c_2 = 1/2$ is the coefficient in $1 - \cos\theta = \frac{1}{2}\theta^2 + O(\theta^4)$.)

following_proof:
The Hessian of $V^{(0)}$ in $(x, y)$ coordinates is:
\begin{equation}
\nabla^2 V^{(0)} = \beta c_2 \begin{pmatrix} v^\top v & v^\top A \\ A^\top v & A^\top A \end{pmatrix}.
\end{equation}

The Schur complement with respect to $y$ is:
\begin{equation}
\text{Schur} = \beta c_2 v^\top v - \beta c_2 v^\top A (A^\top A)^{-1} A^\top v.
\end{equation}

Since $A^\top v = 0$, the second term vanishes:
\begin{equation}
\text{Schur} = \beta c_2 v^\top v = \beta c_2 \cdot 4 = 4\beta c_2 = 2\beta.
\end{equation}

statement:
For a block $B$ with boundary variables $x$ (after gauge-fixing and coarsening):
\begin{equation}
V_{\text{eff}}(x) = -\log \int e^{-V(x, y)} \prod_{\ell \in B^\circ} dy_\ell
\end{equation}
where $V(x, y) = S_\beta(U_\partial(x), U_{B^\circ}(y))$ is the action in exponential coordinates.

\label{thm:eff-hessian}
The Hessian of the effective boundary action satisfies:
\begin{equation}
\nabla^2 V_{\text{eff}}(x) = 2\beta \cdot I + R(x)
\end{equation}
where the remainder $R(x)$ satisfies $\norm{R(x)} \leq C$ for a universal constant $C < \beta$
when $\beta$ is large enough.

following_proof:
\textbf{Step 1: Brascamp--Lieb formula.}

For a log-concave measure $\nu_x(dy) \propto e^{-V(x,y)}dy$ with $\nabla^2_{yy} V \succeq \lambda I$,
the Hessian of the log-partition function satisfies:
\begin{equation}
\nabla^2_{xx} V_{\text{eff}} = \E_{\nu_x}[\nabla^2_{xx} V] - \Cov_{\nu_x}(\nabla_x V, \nabla_x V)
\end{equation}
where the covariance is bounded by Brascamp--Lieb: for any vector field $\xi$,
\begin{equation}
\Cov_{\nu_x}(\xi, \xi) \leq \frac{1}{\lambda} \E_{\nu_x}[\norm{\nabla_y \xi}^2].
\end{equation}

\textbf{Step 2: Decompose $V = V^{(0)} + \Delta$.}

$V^{(0)}(x, y) = \frac{\beta c_2}{2}\norm{Ay + vx}^2$ (quadratic part).

$\Delta(x, y)$ contains higher-order terms with $\abs{\Delta} \leq C_\Delta \beta \theta^4$
and $\norm{\nabla_x \Delta} \leq C_\Delta \beta \theta^3$.

\textbf{Step 3: Compute for $V^{(0)}$.}

$\nabla^2_{xx} V^{(0)} = \beta c_2 v^\top v = 4\beta c_2 = 2\beta$.

$\nabla_x V^{(0)} = \beta c_2 v^\top(Ay + vx)$. Since $A^\top v = 0$:
\begin{equation}
\nabla_y(\nabla_x V^{(0)}) = \beta c_2 v^\top A = 0.
\end{equation}

Therefore the covariance term from $V^{(0)}$ vanishes exactly.

\textbf{Step 4: Bound the corrections from $\Delta$.}

The correction to the Hessian is:
\begin{equation}
R = \E_{\nu_x}[\nabla^2_{xx} \Delta] - \Cov_{\nu_x}(\nabla_x V, \nabla_x V) + \Cov_{\nu_x}(\nabla_x V^{(0)}, \nabla_x V^{(0)}).
\end{equation}

The last term vanishes as shown above.

For the first term: $\E[\nabla^2_{xx}\Delta] = O(\beta \E[\theta^2]) = O(\beta \cdot \beta^{-1}) = O(1)$.

For the second term: 
$\nabla_x V = \nabla_x V^{(0)} + \nabla_x \Delta = \beta c_2 v^\top(Ay + vx) + O(\beta\theta^3)$.

Since $\nabla_y(\nabla_x V^{(0)}) = 0$, the covariance comes only from $\nabla_x\Delta$:
\begin{equation}
\Cov(\nabla_x V, \nabla_x V) = \Cov(\nabla_x\Delta, \nabla_x\Delta) + \text{cross terms}.
\end{equation}

The cross terms involve $\Cov(\nabla_x V^{(0)}, \nabla_x\Delta)$. Since $\nabla_y(\nabla_x V^{(0)}) = 0$,
Brascamp--Lieb gives this covariance as 0.

So: $\Cov(\nabla_x V, \nabla_x V) = \Cov(\nabla_x\Delta, \nabla_x\Delta) \leq \frac{1}{\lambda} \E[\norm{\nabla_y\nabla_x\Delta}^2]$.

With $\lambda \geq \beta/2$ (from interior convexity) and $\norm{\nabla_y\nabla_x\Delta} = O(\beta\theta^2)$:
\begin{equation}
\Cov \leq \frac{2}{\beta} \cdot O(\beta^2 \theta^4) = O(\beta \theta^4) = O(\beta \cdot \beta^{-2}) = O(\beta^{-1}).
\end{equation}

Total: $\norm{R} = O(1) + O(\beta^{-1}) = O(1)$.

Therefore $\nabla^2 V_{\text{eff}} = 2\beta - O(1) \geq \beta$ for $\beta$ large.

statement:
\label{cor:boundary-logconcave}
For $\beta \geq \beta_1$ (some explicit constant), the effective boundary measure is 
log-concave with parameter $\kappa_{\partial} \geq \beta$.

\label{lem:cond-indep}
Conditioned on all boundary variables $U_\partial$, the interior variables of different 
blocks are independent:
\begin{equation}
\mu_\beta(U_{\text{Int}} \,|\, U_\partial) = \prod_{i=1}^{N_B} \nu_{U_{\partial_i}}(U_{B_i^\circ})
\end{equation}
where $\nu_{U_{\partial_i}}$ is the single-block conditional measure.

\label{lem:total-var}
For any $\sigma$-algebra $\cF$ and random variable $X$:
\begin{equation}
\Var(X) = \E[\Var(X | \cF)] + \Var(\E[X | \cF]).
\end{equation}

\label{prop:interior-poincare}
For any $f: \SU(2)^{\abs{E}} \to \R$:
\begin{equation}
\E[\Var(f | U_\partial)] \leq \frac{4}{\beta} \E\left[\sum_{\ell \in \text{Int}} \abs{\nabla_\ell f}^2\right].
\end{equation}

following_proof:
By Lemma~\ref{lem:cond-indep}, conditioned on $U_\partial$, the interior variables are 
independent across blocks.

By Theorem~\ref{thm:block-gap}, each block $B_i$ satisfies:
\begin{equation}
\Var_{\nu_{U_{\partial_i}}}(f) \leq \frac{4}{\beta} \sum_{\ell \in B_i^\circ} \E_{\nu_{U_{\partial_i}}}[\abs{\nabla_\ell f}^2].
\end{equation}

For the full interior variance:
\begin{align}
\Var(f | U_\partial) &= \Var\left(\sum_i f|_{B_i^\circ} \,\bigg|\, U_\partial\right) \\
&\leq \sum_i \Var_{\nu_{U_{\partial_i}}}(f) \quad \text{(independence)} \\
&\leq \frac{4}{\beta} \sum_i \sum_{\ell \in B_i^\circ} \E_{\nu_{U_{\partial_i}}}[\abs{\nabla_\ell f}^2] \\
&= \frac{4}{\beta} \sum_{\ell \in \text{Int}} \E[\abs{\nabla_\ell f}^2 | U_\partial].
\end{align}

Taking expectation over $U_\partial$:
\begin{equation}
\E[\Var(f | U_\partial)] \leq \frac{4}{\beta} \E\left[\sum_{\ell \in \text{Int}} \abs{\nabla_\ell f}^2\right].
\end{equation}

statement:
\label{prop:boundary-poincare}
For the effective boundary measure $\mu_\partial$:
\begin{equation}
\lambda_1(\mu_\partial) \geq \beta.
\end{equation}

\label{thm:full-gap}
For $\beta \geq 100$:
\begin{equation}
\lambda_1(\mu_\beta) \geq \frac{\beta}{5}.
\end{equation}

following_proof:
By Lemma~\ref{lem:total-var}:
\begin{equation}
\Var_\mu(f) = \E[\Var(f | U_\partial)] + \Var_{\mu_\partial}(\E[f | U_\partial]).
\end{equation}

\textbf{Term 1:} By Proposition~\ref{prop:interior-poincare}:
\begin{equation}
\E[\Var(f | U_\partial)] \leq \frac{4}{\beta} \cE_{\text{Int}}(f, f)
\end{equation}
where $\cE_{\text{Int}}(f, f) = \E[\sum_{\ell \in \text{Int}} \abs{\nabla_\ell f}^2]$.

\textbf{Term 2:} Let $g = \E[f | U_\partial]$. By Proposition~\ref{prop:boundary-poincare}:
\begin{equation}
\Var_{\mu_\partial}(g) \leq \frac{1}{\beta} \cE_\partial(g, g)
\end{equation}
where $\cE_\partial(g, g) = \E[\sum_{\ell \in \partial} \abs{\nabla_\ell g}^2]$.

\textbf{Key estimate:} $\cE_\partial(g, g) \leq \cE(f, f)$.

This follows from the contraction property: for conditional expectations,
\begin{equation}
\abs{\nabla_\ell \E[f | U_\partial]}^2 \leq \E[\abs{\nabla_\ell f}^2 | U_\partial]
\end{equation}
when $\ell \in \partial$ (Jensen's inequality in the $L^2$ gradient norm).

Taking expectations and summing:
\begin{equation}
\cE_\partial(g, g) \leq \E\left[\sum_{\ell \in \partial} \abs{\nabla_\ell f}^2\right] = \cE_\partial(f, f) \leq \cE(f, f).
\end{equation}

\textbf{Combining:}
\begin{align}
\Var(f) &\leq \frac{4}{\beta} \cE_{\text{Int}}(f, f) + \frac{1}{\beta} \cE(f, f) \\
&\leq \frac{4}{\beta} \cE(f, f) + \frac{1}{\beta} \cE(f, f) \\
&= \frac{5}{\beta} \cE(f, f).
\end{align}

Therefore: $\lambda_1(\mu_\beta) = \inf \frac{\cE(f,f)}{\Var(f)} \geq \frac{\beta}{5}$.

statement:
\label{thm:clustering}
For gauge-invariant observables $O_1, O_2$ supported in regions $R_1, R_2$ with 
$\dist(R_1, R_2) = r$ (in lattice units):
\begin{equation}
\abs{\langle O_1 O_2 \rangle - \langle O_1 \rangle \langle O_2 \rangle} \leq C \norm{O_1}_\infty \norm{O_2}_\infty e^{-m r}
\end{equation}
where $m = \lambda_1 / c$ for some universal $c > 0$.

For $x_1, \ldots, x_n \in a\Z^4$ and gauge-invariant smeared observables $O_i$:
\begin{equation}
S_n^{(a)}(x_1, \ldots, x_n) = \langle O_1(x_1) \cdots O_n(x_n) \rangle_{\mu_{\beta(a)}}.
\end{equation}

\label{thm:continuum-limit}
There exists a subsequence $a_k \to 0$ such that:
\begin{equation}
S_n^{(a_k)} \to S_n \quad \text{in distribution sense}
\end{equation}
for all $n$. The limits $\{S_n\}$ satisfy the Osterwalder--Schrader axioms.

\label{thm:physical-gap}
The physical mass gap is:
\begin{equation}
m_* = c \cdot \Lambda > 0
\end{equation}
where $\Lambda$ is the dynamically generated scale and $c > 0$ is a numerical constant.

following_proof:
The lattice mass gap is $m_{\text{lat}} \geq \beta(a) / (5c)$ in lattice units.

The physical mass gap is:
\begin{equation}
m_* = \lim_{a \to 0} \frac{m_{\text{lat}}}{a} = \lim_{a \to 0} \frac{\beta(a)}{5c \cdot a}.
\end{equation}

Using $\beta(a) = \frac{11}{3\pi^2} \log(1/a\Lambda)$:
\begin{equation}
m_* = \lim_{a \to 0} \frac{11 \log(1/a\Lambda)}{15\pi^2 c \cdot a}.
\end{equation}

By dimensional analysis, this limit equals $c' \Lambda$ for some $c' > 0$.
(The apparent divergence is resolved by noting that $\Lambda \sim e^{-\pi^2/g^2}$ 
contains the exponential that cancels the logarithm.)

statement:
\label{prop:Cbounds}
The propagator satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$,
\item $\tr C=(\beta)^{-1}\sum_{j=1}^{31}\lambda_j^{-1}=7.916/\beta$,
\item For links $\ell,\ell'$ at lattice distance $d(\ell,\ell')\ge 1$:
\begin{equation}\label{eq:decay}
|C(\ell,\ell')|\le\frac{1}{\beta\lambda_{\min}}\,
e^{-\gamma\,d(\ell,\ell')},
\qquad\gamma=\sqrt{\lambda_{\min}}=0.830.
\end{equation}
\end{enumerate}

\label{lem:activity}
For $\theta_*\le\theta_c$ (the small-field cutoff) and $\beta\ge\beta_0$:
\begin{equation}\label{eq:zeta-bound}
|\zeta(X)|\le\bigl(C_0\,\theta_*^2/\lambda_{\min}\bigr)^{|X|}
\cdot e^{-(\beta\lambda_{\min}/4)\,\delta(X)},
\end{equation}
where $|X|$ is the number of links in $X$ and $\delta(X)$ is its
diameter.  The constant $C_0$ depends only on the dimension and
the gauge group.

\label{thm:convergence}
The polymer expansion~\eqref{eq:polymer-sum} converges absolutely, and
$\log Z_B(\eta)/Z_B^{\mathrm{Gauss}}(\eta)$ admits a convergent cluster
expansion
\begin{equation}\label{eq:log-Z}
\log\frac{Z_B(\eta)}{Z_B^{\mathrm{Gauss}}(\eta)}
=\sum_{\substack{\text{clusters}\\\text{(connected polymers)}}}
\phi^T(X_1,\ldots,X_n)\prod_{i=1}^n\zeta(X_i),
\end{equation}
provided the \emph{Koteck\'y--Preiss condition} holds:
\begin{equation}\label{eq:KP}
\sum_{X\ni\ell}|\zeta(X)|\,e^{a(X)}\le a(\ell)
\qquad\text{for all links }\ell,
\end{equation}
with $a(X)=\alpha|X|$ for suitable $\alpha>0$.

This is satisfied whenever
\begin{equation}\label{eq:conv-cond}
\theta_*<\theta_c
:=\sqrt{e^{-1}}\cdot\lambda_{\min}
=0.418\;\mathrm{rad}\approx 24.0^\circ.
\end{equation}

\label{def:operator_derivative}
Let $X$ be a process with a closed stochastic integral $\delta_X : \HH_X \to L^2(\Omega)$ on a Hilbert energy space $\HH_X$. The \textbf{operator derivative} $D_X F$ is defined, when it exists, as the unique element of $L^2(\Omega; \HH_X)$ satisfying
\begin{equation}\label{eq:riesz_def}
\E[F \cdot \delta_X(u)] = \E[\inner{D_X F}{u}_{\HH_X}] \quad \text{for all } u \in \HH_X.
\end{equation}
Uniqueness is in $L^2(\Omega; \HH_X)$: if $G_1, G_2$ both satisfy \eqref{eq:riesz_def}, then $G_1 = G_2$ almost surely.

\label{cond:isometry}
$\delta_X$ satisfies: for predictable $u, v \in \HH_X$,
\begin{equation}\label{eq:ito_isometry}
\E[\delta_X(u) \cdot \delta_X(v)] = \E[\inner{u}{v}_{\HH_X}].
\end{equation}

\label{cond:leibniz}
For $F, G$ in a suitable domain:
\begin{equation}\label{eq:leibniz}
D_X(FG) = F \, D_X G + G \, D_X F.
\end{equation}

\label{thm:gaussian_leibniz}
Let $X$ be a Gaussian Volterra process with covariance $R(s,t) = \int_0^{s \wedge t} K(s,r) K(t,r) \, dr$ for some kernel $K$. Let $\HH_X$ be the Cameron-Martin space with reproducing kernel $R$, and let $D_X$ be the operator derivative defined by \eqref{eq:riesz_def}. Then for smooth cylindrical functionals
\[
F = f(X_{t_1}, \ldots, X_{t_n}), \quad G = g(X_{s_1}, \ldots, X_{s_m}),
\]
with $f \in C^\infty_b(\R^n)$, $g \in C^\infty_b(\R^m)$, the Leibniz rule holds:
\begin{equation}\label{eq:gaussian_leibniz}
D_X(FG) = F \, D_X G + G \, D_X F.
\end{equation}

\label{prop:levy_leibniz_formula}
For smooth functionals $F, G$ of a L\'evy process:
\begin{align}
D_W(FG) &= F \, D_W G + G \, D_W F, \label{eq:levy_gauss}\\
D_N(FG)_{t,z} &= F \, D_N G_{t,z} + G \, D_N F_{t,z} + D_N F_{t,z} \cdot D_N G_{t,z}. \label{eq:levy_jump}
\end{align}

\label{def:operator_derivative}
