\label{thm:obstruction}
Let $X$ be a Gaussian process with filtration $\FF_t = \sigma(X_s : s \leq t)$, and let $\Pi$ be a projection on $L^2(\Omega; \HH)$ that includes directions supported in $(t, T]$ with nonzero weight. Then there exists $F \in L^2(\Omega)$ such that
\begin{equation}
\Pi(D P_t F - P_t DF) = -\Pi P_t(DF) \neq 0,
\end{equation}
and consequently no $a(t) < 1$ satisfies the commutator contraction.

\label{thm:salvage}
Let $X$ be a Gaussian process admitting an innovations representation: there exists a Brownian motion $W$ such that $\FF_t = \sigma(W_s : s \leq t)$ and $X_t = \int_0^t K(t,s) \, dW_s$ for some kernel $K$. Define the filtration-compatible projection
\begin{equation}
(\Pi_t u)(s) := \mathbf{1}_{[0,t]}(s) \, u(s).
\end{equation}
Then for all $F$ in the domain of $D_W$:
\begin{equation}\label{eq:predictable-commutation}
\Pi_t(D_W P_t F - P_t D_W F) = 0.
\end{equation}

\label{def:commutator}
For $F \in \mathcal{D}$ such that $P_t F \in \mathcal{D}$, the \textbf{commutator} of $D$ and $P_t$ is
\begin{equation}
C_t(F) := D(P_t F) - P_t(DF) \in L^2(\Omega; \HH).
\end{equation}

\label{def:commutator-contraction}
We say the pair $(D, \Pi)$ satisfies the \textbf{commutator contraction} on a domain $\mathcal{D}$ if there exists a function $a : [0,T] \to [0,1)$ such that for all $F \in \mathcal{D}$ and all $t \in [0,T]$:
\begin{equation}\label{eq:CC}
\|\Pi C_t(F)\|_{L^2(\Omega; \HH)} \leq a(t) \, \|\Pi P_t(DF)\|_{L^2(\Omega; \HH)}.
\end{equation}

\label{thm:spine}
Assume:
\begin{enumerate}[label=(\roman*)]
\item $P_t$ are orthogonal projections as above.
\item $D$ is closed with domain $\mathcal{D}$.
\item The commutator contraction \eqref{eq:CC} holds with $a(t) \leq a^* < 1$ on $[0, T_0]$.
\item There exists an $\HH$-cylindrical martingale $M$ such that the stochastic integral
\begin{equation}
\int_0^t \inner{U_s}{dM_s}_\HH
\end{equation}
is defined for predictable $U \in L^2(\Omega \times [0,T]; \HH)$ with the usual isometry.
\end{enumerate}
Then for every $F \in \mathcal{D}$:
\begin{equation}
F = \E[F] + \int_0^T \inner{K_t(F)}{dM_t}_\HH,
\end{equation}
where the canonical integrand is
\begin{equation}\label{eq:integrand}
K_t(F) := (I - \Pi C_t^\sharp)^{-1} \Pi P_t(DF) = \sum_{n \geq 0} (\Pi C_t)^n \Pi P_t(DF).
\end{equation}

\label{def:innovations}
A Gaussian process $X$ admits an \textbf{innovations representation} if there exists a Brownian motion $W$ such that:
\begin{enumerate}[label=(\roman*)]
\item $\FF_t^X = \FF_t^W$, i.e., the filtration generated by $X$ equals the filtration generated by $W$.
\item $X_t = \int_0^t K(t,s) \, dW_s$ for some causal kernel $K$ (Volterra form).
\end{enumerate}

\label{def:Pi-t}
For $\HH = L^2([0,T])$, define
\begin{equation}
(\Pi_t u)(s) := \mathbf{1}_{[0,t]}(s) \, u(s).
\end{equation}
This is the \textbf{truncation to times $\leq t$}.

\label{cor:a-equals-zero}
Under the hypotheses of Theorem~\ref{thm:salvage}, the commutator contraction \eqref{eq:CC} holds with
\begin{equation}
a(t) = 0.
\end{equation}

\label{thm:necessity}
If the commutator contraction \eqref{eq:CC} holds with $a(t) < 1$, then $\Pi$ must satisfy:
\begin{equation}
\Ran(\Pi) \cap \{u \in L^2(\Omega; \HH) : \supp(u) \subset (t, T]\} = \{0\}.
\end{equation}

The pair $(D, \Pi)$ satisfies the \textbf{commutator contraction} if there exists $a(t) < 1$ such that
\begin{equation}\label{eq:CC}
\|\Pi C_t(F)\| \leq a(t) \|\Pi P_t(DF)\|
\end{equation}
for all $F$ in the domain of $D$.

\label{thm:salvage-gaussian}
Let $X$ be a Gaussian process with innovations representation $X_t = \int_0^t K(t,s) dW_s$. Define $\Pi_t u := \mathbf{1}_{[0,t]} \cdot u$. Then for all $F$ in the domain of $D_W$:
\begin{equation}\label{eq:commutator-zero-gaussian}
\Pi_t C_t(F) = \Pi_t(D_W P_t F - P_t D_W F) = 0.
\end{equation}

\label{thm:salvage-discrete}
Let $(\varepsilon_k)_{k \geq 1}$ be independent (not necessarily Gaussian) random variables with $\E[\varepsilon_k] = 0$ and $\E[\varepsilon_k^2] = 1$. Let $\FF_n = \sigma(\varepsilon_1, \ldots, \varepsilon_n)$, and define the operator derivative
\begin{equation}
(D_k F)(\omega) := \lim_{h \to 0} \frac{F(\omega + h e_k) - F(\omega)}{h}
\end{equation}
where $e_k$ perturbs only $\varepsilon_k$. Define $\Pi_n$ to project onto indices $\{1, \ldots, n\}$. Then:
\begin{equation}\label{eq:commutator-zero-discrete}
\Pi_n C_n(F) = \Pi_n(D P_n F - P_n DF) = 0.
\end{equation}

For $\HH = L^2([0,T])$, the \textbf{truncation projection} is
\begin{equation}
(\Pi_t u)(s) := \mathbf{1}_{[0,t]}(s) \cdot u(s).
\end{equation}

For $F = f(\varepsilon_1, \ldots, \varepsilon_N)$ smooth, the \textbf{operator derivative} is
\begin{equation}
D_k F := \frac{\partial f}{\partial \varepsilon_k}(\varepsilon_1, \ldots, \varepsilon_N).
\end{equation}
The full derivative is $DF = (D_1 F, \ldots, D_N F) \in L^2(\Omega; \R^N)$.

For $\HH = \R^N$, the \textbf{truncation projection} $\Pi_n$ is
\begin{equation}
(\Pi_n u)_k := \begin{cases} u_k & k \leq n \\ 0 & k > n. \end{cases}
\end{equation}

\label{conj:continuous-non-gaussian}
Let $M$ be a square-integrable martingale with independent increments (a L\'evy process). Define $D_M$ via Riesz representation against the stochastic integral with respect to $M$. Then the predictable commutation property holds:
\begin{equation}
\Pi_t(D_M P_t F - P_t D_M F) = 0.
\end{equation}

A family of projections $(\Pi_t)$ is \textbf{filtration-compatible} if:
\begin{equation}
\Ran(\Pi_t) \subseteq \{u \in L^2(\Omega; \HH) : u \text{ is } \FF_t\text{-measurable and supported on ``past'' directions}\}.
\end{equation}

\label{thm:main-principle}
If $(\Pi_t)$ is filtration-compatible and innovations are independent, then:
\begin{equation}
\Pi_t C_t(F) = 0
\end{equation}
for all $F$ in the domain of $D$.

The theory has a \textbf{mass gap} $m > 0$ if the connected two-point function 
of any local gauge-invariant observable $\mathcal{O}$ satisfies
\begin{equation}
\langle \mathcal{O}(x) \mathcal{O}(y) \rangle_c \le C e^{-m|x-y|}
\end{equation}
for some constant $C$ and all $x, y$ with $|x-y|$ large.

\label{def:constants}
\begin{align}
\alpha_\Phi &= \frac{1}{2} & &\text{(block-lift linear coefficient)} \\
C_3 &= \frac{1}{3} & &\text{(BCH third-order bound for $\mathfrak{su}(2)$)} \\
C_5 &= 1 & &\text{(BCH second-derivative bound)} \\
c_2 &= \frac{1}{2} & &\text{(Wilson quadratic coefficient)} \\
\lambda_i &= 1 & &\text{(minimum eigenvalue of $A^\top A$)} \\
\theta_0 &= 3 & &\text{(Brascamp--Lieb convexity loss)}
\end{align}

\begin{align}
C_{\mathrm{hol}} &= 64 \cdot C_3 = \frac{64}{3} \\
\beta_\Phi &= \frac{C_{\mathrm{hol}}}{16} = \frac{4}{3} \\
b_0 &= 24 \cdot C_5 = 24
\end{align}

\label{def:R}
The invariant region $\mathcal{R} = \mathcal{R}(\delta_*, \varepsilon_*, \lambda_*)$ consists 
of effective actions $V$ satisfying:
\begin{enumerate}
\item[(R1)] \textbf{Corridor:} $\|(x,y)\| \le \delta_*$
\item[(R2)] \textbf{Convexity:} $\nabla^2_{yy} V \succeq \lambda_* I$
\item[(R3)] \textbf{Mixed Hessian:} $\|\nabla^2_{xy} V\| \le M$ where $M = 48\delta_*$
\item[(R4)] \textbf{$C^2$ control:} $\|\nabla^2 \Delta\| \le \varepsilon_*$
\end{enumerate}

\label{thm:feasibility}
The parameter choice
\begin{equation}
(\delta_*, \varepsilon_*, \lambda_*, \beta_0) = (0.01, 0.1, 10, 10^6)
\end{equation}
satisfies all constraints (I1)--(I6). Moreover, the box
\begin{equation}
\mathcal{B} = [0.009, 0.011] \times [0.09, 0.11] \times [9, 11] \times [9 \times 10^5, 11 \times 10^5]
\end{equation}
is contained in the feasible region.

