\label{def:complex-energy}
For a complex Gaussian process $Z = X + iY$ with independent components and common real energy space $\HX$, the \emph{complexified energy space} is
\begin{equation}\label{eq:complex-energy}
\HZ := \HX \oplus \HX = \{(u, v) : u, v \in \HX\},
\end{equation}
equipped with the inner product
\begin{equation}\label{eq:hermitian-ip}
\ip{(u_1, v_1)}{(u_2, v_2)}_{\HZ} := \ip{u_1}{u_2}_{\HX} + \ip{v_1}{v_2}_{\HX}.
\end{equation}
We identify $(u, v) \in \HZ$ with the complex-valued process $u + iv$.

\label{def:complex-operator-deriv}
Let $Z = X + iY$ be a complex Gaussian process with independent components. For $F \in \Lp{2}(\FT^Z; \C)$ (complex-valued, $\FT^Z$-measurable, square-integrable), define
\begin{equation}\label{eq:complex-deriv}
D_Z F := (D_X F, D_Y F) \in \Lp{2}(\Omega; \HZ),
\end{equation}
where $D_X$ and $D_Y$ are the operator derivatives with respect to the real and imaginary components. This is well-defined whenever $F \in \Dom(D_X) \cap \Dom(D_Y)$.

\label{def:complex-divergence}
For a complex Gaussian process $Z = X + iY$, the \emph{complex stochastic integral} of an adapted complex-valued process $u = (u_t)_{t \in [0,T]}$ is
\begin{equation}\label{eq:complex-div}
\int_0^T u_t \, dZ_t := \int_0^T u_t \, dX_t + i\int_0^T u_t \, dY_t,
\end{equation}
where the right-hand side involves the stochastic integrals $\delta_X$ and $\delta_Y$ applied to the (possibly complex-valued) integrand $u$.

When $u$ is real-valued, this simplifies to $\delta_X(u) + i\delta_Y(u)$. For the pair representation $(u, v) \in \HZ = \HX \oplus \HX$ (both real), we write $\delta_Z(u, v) := \delta_X(u) + i\delta_Y(v)$.

\label{def:operator-wirtinger}
Let $Z = X + iY$ be a complex Gaussian process with independent components. For $F \in \Dom(D_Z)$, the \emph{operator Wirtinger derivatives} are
\begin{align}
D_z F &:= \frac{1}{2}(D_X F - iD_Y F) \in \Lp{2}(\Omega; \HZ), \label{eq:Dz}\\
D_{\bar{z}} F &:= \frac{1}{2}(D_X F + iD_Y F) \in \Lp{2}(\Omega; \HZ). \label{eq:Dzbar}
\end{align}
Here $iD_Y F$ denotes multiplication of the $\HX$-valued random variable $D_Y F$ by the scalar $i$.

\label{def:op-holo}
A random variable $F \in \Lp{2}(\Omega; \C)$ is \emph{operator-holomorphic} (or \emph{stochastically analytic}) if $F \in \Dom(D_Z)$ and
\begin{equation}\label{eq:op-holo}
D_{\bar{z}} F = 0 \quad \text{in } \Lp{2}(\Omega; \HZ).
\end{equation}

\label{prop:op-CR}
Let $F = U + iV$ where $U, V: \Omega \to \R$ are real-valued random variables in $\Dom(D_X) \cap \Dom(D_Y)$. Then $D_{\bar{z}} F = 0$ if and only if
\begin{align}
D_X U &= D_Y V, \label{eq:CR1}\\
D_Y U &= -D_X V. \label{eq:CR2}
\end{align}

following_proof:
Compute:
\begin{align}
D_{\bar{z}} F &= \frac{1}{2}(D_X + iD_Y)(U + iV) \notag\\
&= \frac{1}{2}\left[(D_X U - D_Y V) + i(D_Y U + D_X V)\right]. \label{eq:CR-expand}
\end{align}
This vanishes in $\Lp{2}(\Omega; \HZ)$ if and only if both the real part $D_X U - D_Y V$ and the imaginary part $D_Y U + D_X V$ vanish, giving \eqref{eq:CR1}--\eqref{eq:CR2}.

statement:
\label{def:complex-structure}
On $\HZ = \HX \oplus \HX$, define the \emph{complex structure} $J: \HZ \to \HZ$ by
\begin{equation}\label{eq:J-def}
J(u, v) := (-v, u).
\end{equation}
Note that $J^2 = -\Id$, so $J$ has eigenvalues $\pm i$.

\label{def:H10-H01}
The complexified energy space decomposes as
\begin{equation}\label{eq:hodge}
\HZ \otimes_\R \C = \mathcal{H}^{1,0} \oplus \mathcal{H}^{0,1},
\end{equation}
where:
\begin{itemize}
\item $\mathcal{H}^{1,0} := \{w \in \HZ \otimes_\R \C : Jw = iw\}$ is the \emph{$(1,0)$-subspace} (the $+i$ eigenspace of $J$).
\item $\mathcal{H}^{0,1} := \{w \in \HZ \otimes_\R \C : Jw = -iw\}$ is the \emph{$(0,1)$-subspace} (the $-i$ eigenspace of $J$).
\end{itemize}
Explicitly, $\mathcal{H}^{1,0} = \{(h, ih) : h \in \HX \otimes_\R \C\}$ and $\mathcal{H}^{0,1} = \{(h, -ih) : h \in \HX \otimes_\R \C\}$.

We use the terms ``$(1,0)$'' and ``$(0,1)$'' by analogy with the Hodge decomposition in complex geometry. However, we emphasize that this is linear algebra on a complexified Hilbert space---there is no complex manifold structure on path space, no analytic continuation, and no boundary theory. The analogy with complex analysis is algebraic, not geometric.

\label{def:wirtinger-proj}
The projections onto the $(1,0)$ and $(0,1)$ subspaces are:
\begin{align}
\Pi^{1,0}&: \HZ \to \mathcal{H}^{1,0}, \quad \Pi^{1,0}(u, v) := \frac{1}{2}(u - iv, i(u - iv)) = \frac{1}{2}(u - iv)(1, i), \label{eq:Pi10}\\
\Pi^{0,1}&: \HZ \to \mathcal{H}^{0,1}, \quad \Pi^{0,1}(u, v) := \frac{1}{2}(u + iv, -i(u + iv)) = \frac{1}{2}(u + iv)(1, -i). \label{eq:Pi01}
\end{align}
Equivalently, viewing elements of $\HZ$ as pairs $(u, v)$:
\begin{equation}
\Pi^{1,0}(u, v) = \frac{1}{2}((u, v) - iJ(u, v)), \quad \Pi^{0,1}(u, v) = \frac{1}{2}((u, v) + iJ(u, v)).
\end{equation}

\label{def:cauchy}
Let $Z = X + iY$ be a complex Gaussian process with independent components. For $F \in \Dom(D_Z)$, the \emph{stochastic Cauchy operator} is
\begin{equation}\label{eq:cauchy}
\mathcal{C}[F] := \delta_Z(\Pi^{1,0} \Pi_Z D_Z F).
\end{equation}
The \emph{anti-holomorphic Cauchy operator} is:
\begin{equation}\label{eq:anti-cauchy}
\overline{\mathcal{C}}[F] := \delta_Z(\Pi^{0,1} \Pi_Z D_Z F).
\end{equation}
Here $\Pi_Z$ is the predictable projection (Definition~\ref{def:pred-proj}) applied componentwise, and $\Pi^{1,0}$, $\Pi^{0,1}$ are the $(1,0)$-$(0,1)$ projections (Definition~\ref{def:wirtinger-proj}).

\label{thm:cauchy-decomp}
Let $Z$ be a complex Gaussian process with the representation property. For $F \in \Dom(D_Z)$ measurable with respect to $\FT^Z$:
\begin{equation}\label{eq:cauchy-decomp}
F = \E[F] + \mathcal{C}[F] + \overline{\mathcal{C}}[F].
\end{equation}

following_proof:
By the operator factorization (Theorem~\ref{thm:factorization}) applied to the complex process:
\begin{equation}\label{eq:factorization-apply}
F - \E[F] = \delta_Z(\Pi_Z D_Z F).
\end{equation}
Since $\HZ \otimes_\R \C = \mathcal{H}^{1,0} \oplus \mathcal{H}^{0,1}$, we can decompose:
\begin{equation}\label{eq:decomp-energy}
\Pi_Z D_Z F = \Pi^{1,0}(\Pi_Z D_Z F) + \Pi^{0,1}(\Pi_Z D_Z F).
\end{equation}
Applying the linear operator $\delta_Z$:
\begin{equation}\label{eq:decomp-final}
F - \E[F] = \delta_Z(\Pi^{1,0} \Pi_Z D_Z F) + \delta_Z(\Pi^{0,1} \Pi_Z D_Z F) = \mathcal{C}[F] + \overline{\mathcal{C}}[F].
\end{equation}

Let $u := \Pi^{1,0} \Pi_Z D_Z F \in \mathcal{H}^{1,0}$ and $v := \Pi^{0,1} \Pi_Z D_Z F \in \mathcal{H}^{0,1}$. Both are adapted (by construction of $\Pi_Z$). By Tier~2 (isometry for adapted integrands):
\begin{equation}\label{eq:orthog-L2}
\E[\mathcal{C}[F] \cdot \overline{\overline{\mathcal{C}}[F]}] = \E[\delta_Z(u) \cdot \overline{\delta_Z(v)}] = \E[\ip{u}{v}_{\HZ}].
\end{equation}
Since $u \in \mathcal{H}^{1,0}$ and $v \in \mathcal{H}^{0,1}$, Lemma~\ref{lem:orthogonal} gives $\ip{u}{v}_{\HZ} = 0$.

statement:
\label{thm:energy}
When Tier~2 holds:
\begin{align}
\E[|\mathcal{C}[F]|^2] &= \E\left[\norm{\Pi^{1,0} \Pi_Z D_Z F}_{\HZ}^2\right], \label{eq:energy-C}\\
\Var(F) &= \E\left[\norm{\Pi^{1,0} \Pi_Z D_Z F}_{\HZ}^2\right] + \E\left[\norm{\Pi^{0,1} \Pi_Z D_Z F}_{\HZ}^2\right]. \label{eq:energy-var}
\end{align}

following_proof:
By Tier~2: $\E[|\delta_Z(u)|^2] = \E[\norm{u}_{\HZ}^2]$ for adapted $u$.

The first identity follows directly. The second follows from the first plus orthogonality (Theorem~\ref{thm:orthogonality}):
\begin{equation}\label{eq:energy-proof}
\Var(F) = \E[|F - \E[F]|^2] = \E[|\mathcal{C}[F] + \overline{\mathcal{C}}[F]|^2] = \E[|\mathcal{C}[F]|^2] + \E[|\overline{\mathcal{C}}[F]|^2].
\end{equation}

\textbf{Step 1: Compute $D_X F$ and $D_Y F$ using the cylindrical formula.}

Write $z = x + iy$ for the complex variable. The functional $F = f(Z_T) = f(X_T + iY_T)$ can be viewed as a function of the pair $(X_T, Y_T) \in \R^2$.

By Proposition~\ref{prop:cylindrical} (the explicit formula for cylindricals), applied to each real component:
\begin{align}
D_X F &= \frac{\partial}{\partial x}\big|_{(x,y) = (X_T, Y_T)} f(x + iy) \cdot k_T = \frac{\partial f}{\partial x}(Z_T) \cdot k_T, \label{eq:DXF}\\
D_Y F &= \frac{\partial}{\partial y}\big|_{(x,y) = (X_T, Y_T)} f(x + iy) \cdot k_T = \frac{\partial f}{\partial y}(Z_T) \cdot k_T, \label{eq:DYF}
\end{align}
where $k_T \in \HX$ is the evaluation representer at time $T$.

\textbf{Step 2: Apply the classical Cauchy--Riemann equations.}

Since $f$ is holomorphic, it satisfies the classical Cauchy--Riemann equations. In terms of Wirtinger derivatives:
\begin{equation}\label{eq:classical-CR}
\frac{\partial f}{\partial \bar{z}} = \frac{1}{2}\left(\frac{\partial f}{\partial x} + i\frac{\partial f}{\partial y}\right) = 0.
\end{equation}
Equivalently: $\frac{\partial f}{\partial y} = i\frac{\partial f}{\partial x}$, which gives $\frac{\partial f}{\partial y}(Z_T) = i\frac{\partial f}{\partial x}(Z_T)$.

\textbf{Step 3: Compute $D_{\bar{z}} F$.}
\begin{align}
D_{\bar{z}} F &= \frac{1}{2}(D_X F + iD_Y F) \notag\\
&= \frac{1}{2}\left(\frac{\partial f}{\partial x}(Z_T) + i\frac{\partial f}{\partial y}(Z_T)\right) \cdot k_T \notag\\
&= \frac{\partial f}{\partial \bar{z}}(Z_T) \cdot k_T \notag\\
&= 0. \label{eq:Dzbar-zero}
\end{align}

\textbf{Step 4: Conclude (b) and (c).}

From $D_Y F = iD_X F$ (by the Cauchy--Riemann relation $\frac{\partial f}{\partial y} = i\frac{\partial f}{\partial x}$), we have:
\begin{equation}\label{eq:DZF-holo}
D_Z F = (D_X F, D_Y F) = \left(\frac{\partial f}{\partial x}(Z_T) \cdot k_T,\, i\frac{\partial f}{\partial x}(Z_T) \cdot k_T\right).
\end{equation}
Since $\frac{\partial f}{\partial z} = \frac{1}{2}(\frac{\partial f}{\partial x} - i\frac{\partial f}{\partial y}) = \frac{1}{2}(\frac{\partial f}{\partial x} - i \cdot i\frac{\partial f}{\partial x}) = \frac{\partial f}{\partial x}$, we have $\frac{\partial f}{\partial x} = f'$ (the complex derivative). Thus:
\begin{equation}
D_Z F = f'(Z_T) \cdot (k_T, ik_T).
\end{equation}

The element $(k_T, ik_T)$ lies in $\mathcal{H}^{1,0}$ (the holomorphic subspace). Using the explicit formula \eqref{eq:Pi01} for $\Pi^{0,1}$:
\begin{equation}\label{eq:Pi01-zero}
\Pi^{0,1}(u, v) = \frac{1}{2}(u + iv, -i(u + iv)).
\end{equation}
For $(u, v) = (k_T, ik_T)$: $u + iv = k_T + i(ik_T) = k_T - k_T = 0$. Thus $\Pi^{0,1}(k_T, ik_T) = 0$.

Therefore $D_Z F \in \mathcal{H}^{1,0}$, so $\Pi^{0,1} D_Z F = 0$, hence $\overline{\mathcal{C}}[F] = \delta_Z(\Pi^{0,1} \Pi_Z D_Z F) = 0$.

By Theorem~\ref{thm:cauchy-decomp}: $F - \E[F] = \mathcal{C}[F] + \overline{\mathcal{C}}[F] = \mathcal{C}[F]$.

statement:
\label{rem:proof-uses}
The proof uses:
\begin{enumerate}
\item The explicit formula for $D_X$ on cylindricals (Proposition~\ref{prop:cylindrical}), derived from Gaussian integration by parts.
\item The classical Cauchy--Riemann equations for the holomorphic function $f$.
\item Linear algebra in $\HZ = \mathcal{H}^{1,0} \oplus \mathcal{H}^{0,1}$.
\end{enumerate}
No Malliavin calculus, Sobolev spaces, or semigroup theory is invoked. Crucially, Tier~2 is \emph{not} used---the result holds for any complex Gaussian process, including fBM with $H \neq \frac{1}{2}$.

\label{cor:cauchy-rep}
Let $f: \C \to \C$ be holomorphic with polynomial growth and let $F = f(Z_T)$. Then:
\begin{equation}\label{eq:cauchy-rep-general}
f(Z_T) = \E[f(Z_T)] + \delta_Z(\Pi_Z(f'(Z_T) \cdot (k_T, ik_T))).
\end{equation}
For complex Brownian motion, where $k_T = \mathbf{1}_{[0,T]}$ (the indicator function of $[0,T]$) and the predictable projection gives $(\Pi_Z(f'(Z_T) \cdot (k_T, ik_T)))_t = f'(Z_t) \cdot (\mathbf{1}_{[0,t]}, i\mathbf{1}_{[0,t]})$:
\begin{equation}\label{eq:cauchy-rep-BM}
f(Z_T) = \E[f(Z_T)] + \int_0^T f'(Z_t) \, dZ_t.
\end{equation}

\label{prop:exit}
\begin{equation}\label{eq:exit-rep}
f(Z_\tau) = \E[f(Z_\tau)] + \int_0^\tau f'(Z_t) \, dZ_t,
\end{equation}
and when Tier~2 holds:
\begin{equation}\label{eq:exit-energy}
\Var(f(Z_\tau)) = \E\left[\int_0^\tau |f'(Z_t)|^2 \, dt\right].
\end{equation}

\label{cor:fBM-rep}
For $f$ holomorphic with polynomial growth:
\begin{equation}\label{eq:fBM-rep}
f(Z_T) = \E[f(Z_T)] + \delta_Z^H(\Pi_Z(f'(Z_T) \cdot (k_T^H, ik_T^H))),
\end{equation}
where $\delta_Z^H$ is the fBM divergence and $k_T^H$ is the fBM evaluation representer.

\label{thm:fBM-energy}
For $F = f(Z_T)$ with $f$ holomorphic:
\begin{equation}\label{eq:fBM-energy}
\Var(f(Z_T)) = \E\left[\int_0^T \int_0^T (\Pi_Z f'(Z_T))_s \cdot \overline{(\Pi_Z f'(Z_T))_t} \, d\tilde{R}_H(s,t)\right],
\end{equation}
where $d\tilde{R}_H(s,t) = dR_H(s,t) + dR_H(s,t)$ accounts for both real and imaginary components (i.e., $d\tilde{R}_H = 2\,dR_H$ due to the two independent fBM components).

following_proof:
By Theorem~\ref{thm:fBM-analytic}, $F - \E[F] = \mathcal{C}[F] = \delta_Z^H(u)$ where $u = \Pi_Z(f'(Z_T) \cdot (k_T^H, ik_T^H)) \in \mathcal{H}^{1,0}$.

Applying \eqref{eq:fBM-isometry} to the complex divergence and using independence of the two fBM components:
\begin{align}
\Var(F) &= \E[|\delta_Z^H(u)|^2] \notag\\
&= \E[|\delta_X^H(u_X)|^2] + \E[|\delta_Y^H(u_Y)|^2] \notag\\
&= \E\left[\int_0^T \int_0^T u_{X,s} u_{X,t} \, dR_H(s,t)\right] + \E\left[\int_0^T \int_0^T u_{Y,s} u_{Y,t} \, dR_H(s,t)\right]. \label{eq:fBM-energy-proof}
\end{align}
Since $u = (u_X, iu_X)$ with $u_X = \Pi_Z(f'(Z_T)) \cdot k_T^H$, we have $u_Y = iu_X$, so both integrals contribute equally.

statement:
\label{prop:fBM-power}
For $F = Z_T^n$ and complex fBM with parameter $H$:
\begin{equation}\label{eq:fBM-power}
\E[|Z_T^n|^2] = n^2 \int_0^T \int_0^T \E\left[(\Pi_Z Z_T^{n-1})_s \cdot \overline{(\Pi_Z Z_T^{n-1})_t}\right] d\tilde{R}_H(s,t).
\end{equation}

For $n = 1$ (i.e., $F = Z_T$):
\begin{equation}\label{eq:fBM-n1}
\E[|Z_T|^2] = \E[(B_T^{H,(1)})^2] + \E[(B_T^{H,(2)})^2] = 2T^{2H}.
\end{equation}

For $n = 2$: The predictable projection $(\Pi_Z Z_T)_s = \E[Z_T \mid \Fs]$ for fBM is given by the conditional expectation formula (see \cite{Fontes26b}).

\label{rem:compare-BM}
For $H = \frac{1}{2}$, $\E[B_T \mid \Fs] = B_s$ (martingale property) and $dR_{1/2}(s,t) = ds \, \delta(s - t)$ (Dirac delta), recovering
\begin{equation}\label{eq:BM-n2}
\E[|Z_T^2|^2] = 4\int_0^T \E[|Z_s|^2] \, ds = 4\int_0^T 2s \, ds = 4T^2.
\end{equation}
For $H \neq \frac{1}{2}$, the double integral structure reflects non-trivial long-range dependence.

\label{prop:fBM-exp}
For $F = e^{Z_T}$ and complex fBM:
\begin{equation}\label{eq:fBM-exp-mean}
\E[e^{Z_T}] = \E[e^{B_T^{H,(1)}}] \cdot \E[e^{iB_T^{H,(2)}}] = e^{T^{2H}/2} \cdot e^{-T^{2H}/2} = 1,
\end{equation}
and the variance is given by \eqref{eq:fBM-energy} with $f(z) = e^z$.

\label{prop:orthog-fail}
For complex fBM with $H \neq \frac{1}{2}$ and $F = |Z_T|^2$:
\begin{equation}\label{eq:orthog-fail}
\E[\mathcal{C}[F] \cdot \overline{\overline{\mathcal{C}}[F]}] \neq 0 \quad \text{in general}.
\end{equation}

\label{thm:levy}
Let $D, D' \subset \C$ be simply connected domains, and let $\varphi: D \to D'$ be a conformal (biholomorphic) map. Let $Z_t$ be complex Brownian motion started at $z_0 \in D$. Define the time change
\begin{equation}\label{eq:time-change}
\sigma(t) := \int_0^t |\varphi'(Z_s)|^2 \, ds,
\end{equation}
and let $\tau_D := \inf\{t \geq 0 : Z_t \notin D\}$ be the first exit time from $D$. Then:
\begin{equation}\label{eq:conformal-BM}
\tilde{Z}_{\sigma(t)} := \varphi(Z_t), \quad t \in [0, \tau_D],
\end{equation}
is complex Brownian motion in $D'$ started at $\varphi(z_0)$, run until time $\sigma(\tau_D)$.

\label{prop:conformal-DZ}
Let $\varphi: D \to D'$ be conformal, let $f: \bar{D}' \to \C$ be holomorphic, and define $F := (f \circ \varphi)(Z_{\tau_D})$. Then:
\begin{equation}\label{eq:conformal-DZ}
D_Z F = (f' \circ \varphi)(Z_{\tau_D}) \cdot \varphi'(Z_{\tau_D}) \cdot (k_{\tau_D}, ik_{\tau_D}).
\end{equation}

following_proof:
By the chain rule (Tier~3):
\begin{equation}\label{eq:chain}
D_Z((f \circ \varphi)(Z_{\tau_D})) = (f \circ \varphi)'(Z_{\tau_D}) \cdot (k_{\tau_D}, ik_{\tau_D}) = (f' \circ \varphi)(Z_{\tau_D}) \cdot \varphi'(Z_{\tau_D}) \cdot (k_{\tau_D}, ik_{\tau_D}).
\end{equation}

statement:
\label{thm:conformal}
Let $\varphi: D \to D'$ be conformal, $\tau := \tau_D$ the first exit time from $D$, and $f: \bar{D}' \to \C$ holomorphic. Define:
\begin{itemize}
\item $F := (f \circ \varphi)(Z_\tau)$ --- functional of $Z$ in domain $D$.
\item $\tilde{F} := f(\tilde{Z}_{\tilde{\tau}})$ --- corresponding functional of $\tilde{Z} := \varphi(Z)$ in domain $D'$, where $\tilde{\tau} := \sigma(\tau)$.
\end{itemize}
Then the Cauchy representations are related by:
\begin{equation}\label{eq:C-D}
\mathcal{C}[F] = \int_0^\tau (f' \circ \varphi)(Z_t) \cdot \varphi'(Z_t) \, dZ_t,
\end{equation}
and
\begin{equation}\label{eq:C-Dprime}
\mathcal{C}[\tilde{F}] = \int_0^{\tilde{\tau}} f'(\tilde{Z}_s) \, d\tilde{Z}_s.
\end{equation}
These are equal in law under the time change $s = \sigma(t)$.

following_proof:
For $F = (f \circ \varphi)(Z_\tau)$, Corollary~\ref{cor:cauchy-rep} gives:
\begin{equation}\label{eq:C-F}
\mathcal{C}[F] = \int_0^\tau [(f \circ \varphi)'](Z_t) \, dZ_t = \int_0^\tau (f' \circ \varphi)(Z_t) \cdot \varphi'(Z_t) \, dZ_t.
\end{equation}

For the transformed process, $\tilde{F} = f(\tilde{Z}_{\tilde{\tau}})$:
\begin{equation}\label{eq:C-Ftilde}
\mathcal{C}[\tilde{F}] = \int_0^{\tilde{\tau}} f'(\tilde{Z}_s) \, d\tilde{Z}_s.
\end{equation}

Under the time change $s = \sigma(t)$, we have $d\tilde{Z}_s = \varphi'(Z_t) \, dZ_t$ (by It\^o's formula for conformal maps), so:
\begin{align}
\int_0^{\tilde{\tau}} f'(\tilde{Z}_s) \, d\tilde{Z}_s &= \int_0^\tau f'(\varphi(Z_t)) \cdot \varphi'(Z_t) \, dZ_t \notag\\
&= \int_0^\tau (f' \circ \varphi)(Z_t) \cdot \varphi'(Z_t) \, dZ_t. \label{eq:time-change-proof}
\end{align}
This matches $\mathcal{C}[F]$.

statement:
\label{cor:dirichlet}
For $f: \bar{D}' \to \C$ holomorphic and $\varphi: D \to D'$ conformal:
\begin{equation}\label{eq:dirichlet-inv}
\E\left[\int_0^{\tau_D} |(f' \circ \varphi)(Z_t)|^2 |\varphi'(Z_t)|^2 \, dt\right] = \E\left[\int_0^{\tau_{D'}} |f'(\tilde{Z}_s)|^2 \, ds\right].
\end{equation}

\label{def:cauchy-op}
The \emph{stochastic Cauchy operator} is
\begin{equation}\label{eq:cauchy-def}
\mathcal{C}[F] := \delta_Z(\Pi^{1,0} \Pi_Z D_Z F),
\end{equation}
where $D_Z$ is the complex operator derivative (Definition~\ref{def:complex-operator-deriv}), $\Pi_Z$ is the predictable projection (Definition~\ref{def:pred-proj}), $\Pi^{1,0}$ is the holomorphic projection (Definition~\ref{def:wirtinger-proj}), and $\delta_Z = D_Z^*$ is the divergence.

\label{thm:decomp-intro}
Let $\Dom(D_Z)$ denote the domain of the complex operator derivative (Definition~\ref{def:complex-operator-deriv}). For $F \in \Dom(D_Z)$ measurable with respect to $\FT^Z$ (the terminal $\sigma$-algebra generated by $Z$),
\begin{equation}\label{eq:decomp-intro}
F = \E[F] + \mathcal{C}[F] + \overline{\mathcal{C}}[F],
\end{equation}
with $\mathcal{C}[F] \perp \overline{\mathcal{C}}[F]$ in $\Lp{2}(\Omega)$ when Tier~2 holds.

\label{thm:energy-intro}
For complex Brownian motion (Tier~2 holds), let $\HZ$ denote the complexified energy space (Definition~\ref{def:complex-energy}), $\Pi^{1,0}$ the holomorphic projection, and $\Pi^{0,1}$ the anti-holomorphic projection (Definition~\ref{def:wirtinger-proj}). Then:
\begin{equation}\label{eq:energy-intro}
\Var(F) = \E\left[\norm{\Pi^{1,0} \Pi_Z D_Z F}_{\HZ}^2\right] + \E\left[\norm{\Pi^{0,1} \Pi_Z D_Z F}_{\HZ}^2\right].
\end{equation}
For complex fBM with $H \neq \frac{1}{2}$ (Tier~2 fails), covariance corrections appear (Section~\ref{sec:fBM}).

\label{thm:conformal-intro}
Let $D, D' \subset \C$ be simply connected domains and let $\varphi: D \to D'$ be a conformal (biholomorphic) map. Let $Z_t$ be complex Brownian motion started at $z_0 \in D$, and let $\tau_D := \inf\{t \geq 0 : Z_t \notin D\}$ be the first exit time from $D$. For $f: \bar{D}' \to \C$ analytic, define $F := (f \circ \varphi)(Z_{\tau_D})$. Then
\begin{equation}\label{eq:conformal-intro}
\mathcal{C}[F] = \int_0^{\tau_D} (f' \circ \varphi)(Z_t) \cdot \varphi'(Z_t) \, dZ_t,
\end{equation}
which equals $\mathcal{C}[f(\tilde{Z}_{\tilde{\tau}})]$ in law under the conformal time change, where $\tilde{Z} := \varphi(Z)$ and $\tilde{\tau} := \inf\{s \geq 0 : \tilde{Z}_s \notin D'\}$.

{Fontes26d}}]\label{def:operator-deriv}
Let $X$ be a centered Gaussian process with energy space $(\HX, \delta_X)$. The \emph{operator derivative} $D_X F \in \Lp{2}(\Omega; \HX)$ is defined, when it exists, as the unique element satisfying
\begin{equation}\label{eq:riesz-def}
\E[F \cdot \delta_X(u)] = \E[\ip{D_X F}{u}_{\HX}] \quad \text{for all } u \in \HX.
\end{equation}
This is the Riesz representation of the continuous linear functional $u \mapsto \E[F \cdot \delta_X(u)]$. Uniqueness is in $\Lp{2}(\Omega; \HX)$. The domain of $D_X$ is $\Dom(D_X) := \{F \in \Lp{2}(\Omega) : \exists\, D_X F \in \Lp{2}(\Omega; \HX) \text{ satisfying } \eqref{eq:riesz-def}\}$.

\label{def:pred-proj}
Let $u = (u_t)_{t \in [0,T]} \in \Lp{2}(\Omega; \HX)$ be an $\HX$-valued random variable that can be represented as a process. The \emph{predictable projection} $\Pi_X: \Lp{2}(\Omega; \HX) \to \Lp{2}(\Omega; \HX)$ is defined by
\begin{equation}\label{eq:pred-proj}
(\Pi_X u)_t := \E[u_t \mid \Ft] \quad \text{for } t \in [0,T].
\end{equation}

\label{thm:factorization}
Let $X$ be a Gaussian process with the representation property. For $F \in \Dom(D_X)$ measurable with respect to $\FT^X$:
\begin{equation}\label{eq:factorization}
F - \E[F] = \delta_X(\Pi_X D_X F).
\end{equation}

{Fontes26d}}]\label{prop:cylindrical}
Let $X$ be a Gaussian process with covariance $R(s,t) = \E[X_s X_t]$. For a cylindrical functional $F = f(X_{t_1}, \ldots, X_{t_n})$ with $f \in C_b^\infty(\R^n)$:
\begin{equation}\label{eq:cylindrical}
D_X F = \sum_{j=1}^n \partial_j f(X_{t_1}, \ldots, X_{t_n}) \cdot k_{t_j},
\end{equation}
where $\partial_j$ denotes the partial derivative with respect to the $j$-th argument, and $k_t \in \HX$ is the \emph{representer of evaluation at time $t$}, characterized by $\ip{k_t}{h}_{\HX} = h(t)$ for all $h \in \HX$.

following_proof:
By the Gaussian integration-by-parts formula: for $F = f(X_{t_1}, \ldots, X_{t_n})$ and deterministic $u \in \HX$,
\begin{equation}\label{eq:ibp}
\E[F \cdot \delta_X(u)] = \sum_{j=1}^n \E[\partial_j f(X_{t_1}, \ldots, X_{t_n})] \cdot \ip{k_{t_j}}{u}_{\HX}.
\end{equation}
This is the defining equation \eqref{eq:riesz-def} with $D_X F$ given by \eqref{eq:cylindrical}.

