\label{prop:fBM-power}
For $F = Z_T^n$ and complex fBM with parameter $H$:
\begin{equation}\label{eq:fBM-power}
\E[|Z_T^n|^2] = n^2 \int_0^T \int_0^T \E\left[(\Pi_Z Z_T^{n-1})_s \cdot \overline{(\Pi_Z Z_T^{n-1})_t}\right] d\tilde{R}_H(s,t).
\end{equation}

For $n = 1$ (i.e., $F = Z_T$):
\begin{equation}\label{eq:fBM-n1}
\E[|Z_T|^2] = \E[(B_T^{H,(1)})^2] + \E[(B_T^{H,(2)})^2] = 2T^{2H}.
\end{equation}

For $n = 2$: The predictable projection $(\Pi_Z Z_T)_s = \E[Z_T \mid \Fs]$ for fBM is given by the conditional expectation formula (see \cite{Fontes26b}).

\label{rem:compare-BM}
For $H = \frac{1}{2}$, $\E[B_T \mid \Fs] = B_s$ (martingale property) and $dR_{1/2}(s,t) = ds \, \delta(s - t)$ (Dirac delta), recovering
\begin{equation}\label{eq:BM-n2}
\E[|Z_T^2|^2] = 4\int_0^T \E[|Z_s|^2] \, ds = 4\int_0^T 2s \, ds = 4T^2.
\end{equation}
For $H \neq \frac{1}{2}$, the double integral structure reflects non-trivial long-range dependence.

\label{prop:fBM-exp}
For $F = e^{Z_T}$ and complex fBM:
\begin{equation}\label{eq:fBM-exp-mean}
\E[e^{Z_T}] = \E[e^{B_T^{H,(1)}}] \cdot \E[e^{iB_T^{H,(2)}}] = e^{T^{2H}/2} \cdot e^{-T^{2H}/2} = 1,
\end{equation}
and the variance is given by \eqref{eq:fBM-energy} with $f(z) = e^z$.

\label{prop:orthog-fail}
For complex fBM with $H \neq \frac{1}{2}$ and $F = |Z_T|^2$:
\begin{equation}\label{eq:orthog-fail}
\E[\mathcal{C}[F] \cdot \overline{\overline{\mathcal{C}}[F]}] \neq 0 \quad \text{in general}.
\end{equation}

\label{thm:levy}
Let $D, D' \subset \C$ be simply connected domains, and let $\varphi: D \to D'$ be a conformal (biholomorphic) map. Let $Z_t$ be complex Brownian motion started at $z_0 \in D$. Define the time change
\begin{equation}\label{eq:time-change}
\sigma(t) := \int_0^t |\varphi'(Z_s)|^2 \, ds,
\end{equation}
and let $\tau_D := \inf\{t \geq 0 : Z_t \notin D\}$ be the first exit time from $D$. Then:
\begin{equation}\label{eq:conformal-BM}
\tilde{Z}_{\sigma(t)} := \varphi(Z_t), \quad t \in [0, \tau_D],
\end{equation}
is complex Brownian motion in $D'$ started at $\varphi(z_0)$, run until time $\sigma(\tau_D)$.

\label{prop:conformal-DZ}
Let $\varphi: D \to D'$ be conformal, let $f: \bar{D}' \to \C$ be holomorphic, and define $F := (f \circ \varphi)(Z_{\tau_D})$. Then:
\begin{equation}\label{eq:conformal-DZ}
D_Z F = (f' \circ \varphi)(Z_{\tau_D}) \cdot \varphi'(Z_{\tau_D}) \cdot (k_{\tau_D}, ik_{\tau_D}).
\end{equation}

following_proof:
By the chain rule (Tier~3):
\begin{equation}\label{eq:chain}
D_Z((f \circ \varphi)(Z_{\tau_D})) = (f \circ \varphi)'(Z_{\tau_D}) \cdot (k_{\tau_D}, ik_{\tau_D}) = (f' \circ \varphi)(Z_{\tau_D}) \cdot \varphi'(Z_{\tau_D}) \cdot (k_{\tau_D}, ik_{\tau_D}).
\end{equation}

statement:
\label{thm:conformal}
Let $\varphi: D \to D'$ be conformal, $\tau := \tau_D$ the first exit time from $D$, and $f: \bar{D}' \to \C$ holomorphic. Define:
\begin{itemize}
\item $F := (f \circ \varphi)(Z_\tau)$ --- functional of $Z$ in domain $D$.
\item $\tilde{F} := f(\tilde{Z}_{\tilde{\tau}})$ --- corresponding functional of $\tilde{Z} := \varphi(Z)$ in domain $D'$, where $\tilde{\tau} := \sigma(\tau)$.
\end{itemize}
Then the Cauchy representations are related by:
\begin{equation}\label{eq:C-D}
\mathcal{C}[F] = \int_0^\tau (f' \circ \varphi)(Z_t) \cdot \varphi'(Z_t) \, dZ_t,
\end{equation}
and
\begin{equation}\label{eq:C-Dprime}
\mathcal{C}[\tilde{F}] = \int_0^{\tilde{\tau}} f'(\tilde{Z}_s) \, d\tilde{Z}_s.
\end{equation}
These are equal in law under the time change $s = \sigma(t)$.

following_proof:
For $F = (f \circ \varphi)(Z_\tau)$, Corollary~\ref{cor:cauchy-rep} gives:
\begin{equation}\label{eq:C-F}
\mathcal{C}[F] = \int_0^\tau [(f \circ \varphi)'](Z_t) \, dZ_t = \int_0^\tau (f' \circ \varphi)(Z_t) \cdot \varphi'(Z_t) \, dZ_t.
\end{equation}

For the transformed process, $\tilde{F} = f(\tilde{Z}_{\tilde{\tau}})$:
\begin{equation}\label{eq:C-Ftilde}
\mathcal{C}[\tilde{F}] = \int_0^{\tilde{\tau}} f'(\tilde{Z}_s) \, d\tilde{Z}_s.
\end{equation}

Under the time change $s = \sigma(t)$, we have $d\tilde{Z}_s = \varphi'(Z_t) \, dZ_t$ (by It\^o's formula for conformal maps), so:
\begin{align}
\int_0^{\tilde{\tau}} f'(\tilde{Z}_s) \, d\tilde{Z}_s &= \int_0^\tau f'(\varphi(Z_t)) \cdot \varphi'(Z_t) \, dZ_t \notag\\
&= \int_0^\tau (f' \circ \varphi)(Z_t) \cdot \varphi'(Z_t) \, dZ_t. \label{eq:time-change-proof}
\end{align}
This matches $\mathcal{C}[F]$.

statement:
\label{cor:dirichlet}
For $f: \bar{D}' \to \C$ holomorphic and $\varphi: D \to D'$ conformal:
\begin{equation}\label{eq:dirichlet-inv}
\E\left[\int_0^{\tau_D} |(f' \circ \varphi)(Z_t)|^2 |\varphi'(Z_t)|^2 \, dt\right] = \E\left[\int_0^{\tau_{D'}} |f'(\tilde{Z}_s)|^2 \, ds\right].
\end{equation}

\label{prop:hierarchy}
\[
\text{Profile concentration} \Rightarrow \text{Spatial concentration} \Rightarrow \text{Scale concentration}
\]

Angular concentration is related but not directly comparable:
\begin{itemize}
\item Profile concentration at a point $\Rightarrow$ angular concentration (generically)
\item Angular concentration $\not\Rightarrow$ spatial concentration (energy could be spread in space but aligned in direction)
\end{itemize}

\label{prop:partial}
Let $\phi$ be a blow-up profile (as in Theorem~\ref{thm:minimal}). Then $\phi$ cannot be ``maximally spread'' in the sense:
\[
E_{\Omega}^\phi \leq \frac{1}{N} \|\phi\|_{\Hdot{1/2}}^2 + o(1) \quad \text{for all caps } \Omega \text{ in an } N\text{-cap partition}
\]

\label{thm:weakest}
The following hypothesis is sufficient for the blow-up contradiction argument:

\begin{hypothesis}[Sequential Angular Concentration]\label{hyp:sac}
If NS blows up at $T^*$, then there exists:
\begin{itemize}
\item A sequence $t_n \nearrow T^*$
\item A sequence of caps $\Omega_n$ (of fixed diameter $\theta_0$)
\end{itemize}
such that:
\[
\liminf_{n \to \infty} \rho(t_n) \geq 1 - \eps_*
\]
where $\eps_* < 1/4$ is the threshold in the main paper.
\end{hypothesis}

Under Hypothesis~\ref{hyp:sac}, the Closing Lemma dichotomy applies along the sequence, and the blow-up contradiction follows.

\label{prop:spatial-angular}
Spatial concentration at a point does NOT automatically imply angular concentration.

However, if spatial concentration occurs with a \textbf{specific blow-up profile shape}, angular concentration may follow.

\label{thm:final}
\begin{enumerate}
\item \textbf{KNOWN:} If NS blows up, the minimal blow-up element has spatial concentration (single profile, localized in space).

\item \textbf{HEURISTIC:} Angularly spread profiles should disperse, not blow up, suggesting blow-up profiles are angularly concentrated.

\item \textbf{GAP:} A rigorous proof that blow-up profiles are angularly concentrated (Hypothesis~\ref{hyp:pac} or \ref{hyp:sac}).

\item \textbf{CONDITIONAL:} Under Hypothesis~\ref{hyp:sac}, the Closing Lemma + dichotomy gives a complete blow-up contradiction.
\end{enumerate}

\label{cond:Phi}
There exist $\delta_1, c_1 > 0$ such that for every smooth
divergence-free $u$ on $\T^3$ with $\delta(u) \leq \delta_1$
and $D/E \geq 1/\delta_1$:
\begin{equation}\label{eq:Phi}
\cS_{\mathrm{cross}}(u) \geq -c_1\,\frac{D}{E}\,\delta(u).
\end{equation}

\label{thm:cross-scale}
Fix $\eta \in (0,1)$.  Define the cross-scale entropy transfer
\begin{equation}
\cS_{\mathrm{cross}}^{\mathrm{diff}}(u)
= \text{contribution to } \cS_{\mathrm{cross}}
\text{ from triads with } |p|/|q| \notin [\eta, 1/\eta].
\end{equation}
Then for any smooth divergence-free $u$ with
$\delta(u) \geq \theta_0 > 0$:
\begin{equation}\label{eq:cross-scale-bound}
\abs{\cS_{\mathrm{cross}}^{\mathrm{diff}}}
\leq \frac{C(\eta)}{\theta_0}\,\delta\,\frac{D}{E}\,
\norm{u}_{L^2}\norm{u}_{\Hdot{1}}/E.
\end{equation}
In the blow-up regime where $E = \norm{u}_{\Hdot{1/2}}^2
\gg 1$, the factor $\norm{u}_{L^2}\norm{u}_{\Hdot{1}}/E$
is bounded by $\norm{u}_{L^2}^2/E \leq C$
(by interpolation and energy inequality), giving
$|\cS_{\mathrm{cross}}^{\mathrm{diff}}|
\leq C'\delta(D/E)$.

\label{thm:return}
Let $B(u_{\Omega_a}, u_{\Omega_b})$ be the bilinear
interaction of fields with angular support in sectors
$\Omega_a, \Omega_b \subset S^2$ with
$\Area(\Omega_a), \Area(\Omega_b) \leq 2\pi$.
The fraction of the bilinear $\Hdot{1/2}$~output energy
landing in $\Omega_a$ is at most:
\begin{equation}\label{eq:return-bound}
R_{ab \to a}
:= \frac{\norm{P_{\Omega_a}B(u_{\Omega_a},u_{\Omega_b})}
_{\Hdot{1/2}}^2}
{\norm{B(u_{\Omega_a},u_{\Omega_b})}_{\Hdot{1/2}}^2}
\leq \frac{\Area(\Omega_a)}{\Area(\Omega_a \oplus \Omega_b)}
\leq \frac{1}{3},
\end{equation}
provided the bilinear output is \emph{symbol-balanced} in
the sense of Definition~\ref{def:symbol-balanced}.

\label{lem:stationarity}
If $u$ is a self-similar blow-up solution with profile $U$,
then the sector probabilities $p_j$ are time-independent,
and the nonlinear and dissipative transfers satisfy:
\begin{equation}\label{eq:stationarity}
\cN_j(U) = \nu\bigl(D_j(U) - E_j(U)\bigr) \qquad
\forall\,j = 1,\ldots,J.
\end{equation}

\label{lem:mink-area}
For a spherical cap $\Omega \subset S^2$ with
$\Area(\Omega) \leq 2\pi$:
\begin{equation}
\Area(\Omega \oplus \Omega) \geq 3\,\Area(\Omega).
\end{equation}
For two disjoint caps $\Omega_a, \Omega_b$ with
angular separation $\theta_{ab} > 0$:
\begin{equation}
\Area(\Omega_a \oplus \Omega_b)
\geq \Area(\Omega_a) + \Area(\Omega_b)
+ c\,\theta_{ab}^2.
\end{equation}

\label{def:symbol-balanced}
We say the bilinear output $B(u_{\Omega_a}, u_{\Omega_b})$
is \emph{symbol-balanced} if the angular distribution of
the output energy within $\Omega_a \oplus \Omega_b$ satisfies:
for every $\Omega_j \subset \Omega_a \oplus \Omega_b$,
\begin{equation}\label{eq:symbol-balanced}
\frac{\norm{P_{\Omega_j}B(u_{\Omega_a},u_{\Omega_b})}
_{\Hdot{1/2}}^2}
{\norm{B(u_{\Omega_a},u_{\Omega_b})}_{\Hdot{1/2}}^2}
\leq C_{\mathrm{sb}}\,
\frac{\Area(\Omega_j \cap (\Omega_a\oplus\Omega_b))}
{\Area(\Omega_a\oplus\Omega_b)},
\end{equation}
for a universal constant $C_{\mathrm{sb}} > 0$.

following_proof:
Under symbol-balance~\eqref{eq:symbol-balanced},
the return fraction is bounded by the area ratio:
\begin{align}
R_{ab\to a}
&= \frac{\norm{P_{\Omega_a}B(u_{\Omega_a},u_{\Omega_b})}
_{\Hdot{1/2}}^2}
{\norm{B(u_{\Omega_a},u_{\Omega_b})}_{\Hdot{1/2}}^2}
\nonumber\\
&\leq C_{\mathrm{sb}}\,
\frac{\Area(\Omega_a \cap (\Omega_a\oplus\Omega_b))}
{\Area(\Omega_a\oplus\Omega_b)}
\nonumber\\
&\leq C_{\mathrm{sb}}\,
\frac{\Area(\Omega_a)}
{\Area(\Omega_a\oplus\Omega_b)}.
\label{eq:return-area}
\end{align}
Now apply Lemma~\ref{lem:mink-area}.  If $\Omega_a = \Omega_b$
(self-interaction of one sector), then
$\Area(\Omega_a\oplus\Omega_a) \geq 3\Area(\Omega_a)$, giving
\begin{equation}\label{eq:return-self}
R_{aa\to a} \leq \frac{C_{\mathrm{sb}}}{3}.
\end{equation}
For cross-sector interactions ($a \neq b$), the Minkowski
sum is even larger:
$\Area(\Omega_a\oplus\Omega_b)
\geq \Area(\Omega_a) + \Area(\Omega_b) + c\theta_{ab}^2
\geq 2\Area(\Omega_a) + c\theta_{ab}^2$
(assuming comparable area), giving
$R_{ab\to a} \leq C_{\mathrm{sb}}/(2 + c\theta_{ab}^2/\Area(\Omega_a))
< C_{\mathrm{sb}}/2$.

With $C_{\mathrm{sb}} = 1$ (the symbol-balance constant
for the idealized case of uniform output), we obtain
$R_{ab\to a} \leq 1/3$ in the self-interaction case and
$R_{ab\to a} \leq 1/2$ in the cross-sector case.

statement:
\label{def:decoherence}
We say $u$ has \emph{$(\gamma,\beta)$-phase decoherence}
if the near-boundary triads satisfy:
\begin{equation}\label{eq:decoherence}
\abs{\sum_{\text{near-bdy triads to }j}
|\sigma|\,|\hat{u}(p)|\,|\hat{u}(q)|\,|\hat{u}(k)|
\,\cos\phi_{pq}}
\leq \gamma \sum_{\text{near-bdy triads to }j}
|\sigma|\,|\hat{u}(p)|\,|\hat{u}(q)|\,|\hat{u}(k)|,
\end{equation}
for all sectors $j = 1,\ldots,J$.

\label{thm:decoherence}
If $u$ has $(\gamma,\beta)$-phase decoherence with
$\beta \leq \delta$ and $\gamma \leq c_0/(\log J + |\log p_{\min}|)$
for a sufficiently small constant $c_0$, then
\begin{equation}
|\cS_{\mathrm{cross}}^{\mathrm{near}}|
\leq c_1\,\delta\,\frac{D}{E},
\end{equation}
i.e., Condition~$\Phi$ holds for the near-boundary component.

following_proof:
With $\beta$-phase decoherence, the near-boundary
transfer to sector~$j$ satisfies:
\begin{equation}\label{eq:Nj-decoherent}
|\cN_j^{\mathrm{near-bdy}}|
\leq \gamma\sum_{\text{near-bdy triads to }j}
|\sigma|\,|\hat{u}(p)|\,|\hat{u}(q)|\,|\hat{u}(k)|.
\end{equation}

The symbol bound $|\sigma| \leq \beta|q| \leq \delta|q|$
(since $\beta \leq \delta$) gives:
\begin{equation}
|\cN_j^{\mathrm{near-bdy}}|
\leq \gamma\delta\sum|q|\,|\hat{u}(p)|\,|\hat{u}(q)|\,|\hat{u}(k)|
\leq C\gamma\delta\,E_j^{1/2}D_j^{1/2}E^{1/2}.
\end{equation}
(The bound uses Cauchy--Schwarz on the trilinear sum,
with $|q| \leq |k|^{1/2}|q|^{1/2}\cdot|q|^{1/2}$
distributing the derivatives.)

The total near-boundary transfer:
$|\cN^{\mathrm{near-bdy}}|
\leq C\gamma\delta\,D^{1/2}E$.

The deviation from proportional redistribution:
\begin{align}
|\cN_j^{\mathrm{near-bdy}} - p_j\cN^{\mathrm{near-bdy}}|
&\leq 2C\gamma\delta\,E_j^{1/2}D_j^{1/2}E^{1/2}.
\end{align}

The entropy contribution:
\begin{align}
|\cS_{\mathrm{cross}}^{\mathrm{near}}|
&\leq \frac{2}{E}\sum_j |\log p_j|\cdot
2C\gamma\delta\,E_j^{1/2}D_j^{1/2}E^{1/2}
\nonumber\\
&\leq \frac{4C\gamma\delta}{E^{1/2}}\sum_j
|\log p_j|\,E_j^{1/2}D_j^{1/2}
\nonumber\\
&\leq \frac{4C\gamma\delta}{E^{1/2}}
\left(\sum_j |\log p_j|^2 E_j\right)^{1/2}
\left(\sum_j D_j\right)^{1/2}
\nonumber\\
&= 4C\gamma\delta\,\frac{D^{1/2}}{E^{1/2}}
\left(\sum_j |\log p_j|^2 p_j\right)^{1/2}.
\end{align}

Using $\sum_j |\log p_j|^2 p_j
\leq (\log J + |\log p_{\min}|)^2$
and $D^{1/2}/E^{1/2} \leq (D/E)^{1/2}$:
\begin{equation}
|\cS_{\mathrm{cross}}^{\mathrm{near}}|
\leq 4C\gamma(\log J + |\log p_{\min}|)\,
\delta\,\left(\frac{D}{E}\right)^{1/2}.
\end{equation}

Since $D/E \geq 1/\delta_1 \geq 1$ in the Condition~$\Phi$
regime, we have $(D/E)^{1/2} \leq (D/E)$, giving:
\begin{equation}
|\cS_{\mathrm{cross}}^{\mathrm{near}}|
\leq 4C\gamma(\log J + |\log p_{\min}|)\,
\delta\,\frac{D}{E}.
\end{equation}

With $\gamma \leq c_0/(\log J + |\log p_{\min}|)$,
this gives $|\cS_{\mathrm{cross}}^{\mathrm{near}}|
\leq 4Cc_0\,\delta(D/E)$, which is Condition~$\Phi$
with $c_1 = 4Cc_0$.

Set $\gamma = 1$ in the proof of
Theorem~\ref{thm:decoherence}.  The bound at
$\gamma = 1$ (no phase cancellation whatsoever) gives:
\begin{equation}
|\cS_{\mathrm{cross}}^{\mathrm{near}}|
\leq 4C\cdot 1 \cdot
(\log J + |\log p_{\min}|)\,\delta\,
\left(\frac{D}{E}\right)^{1/2}.
\end{equation}
On $\T^3 = [0,2\pi]^3$, the Poincar\'e inequality gives
$D/E = \norm{u}^2_{\Hdot{3/2}}/\norm{u}^2_{\Hdot{1/2}}
\geq \lambda_1 = 1$,
so $(D/E)^{1/2} \leq D/E$.  Therefore:
\begin{equation}
|\cS_{\mathrm{cross}}^{\mathrm{near}}|
\leq 4C(\log J + |\log p_{\min}|)\,\delta\,\frac{D}{E}
= C_J^*\,\delta\,\frac{D}{E}.
\end{equation}
The constant $C_J^*$ is finite whenever
$p_{\min} > 0$, which holds whenever $\cS > 0$.

