\begin{equation}\label{eq:restriction}
\norm{T_\beta(f,g)}_{\ell^\infty(j;\text{weighted})}
\leq C\delta\,\norm{f}_{\ell^2(|k|)}
\norm{g}_{\ell^2(|k|)}\cdot
\frac{(D/E)^{1/2}}{(\log J + |\log p_{\min}|)},
\end{equation}
where the $\ell^\infty(j;\text{weighted})$ norm has weight
$|\log p_j|/E$ on sector~$j$.

\label{def:cone}
For a unit vector $\hat{n} \in S^2$ and aperture $\delta \in (0,1/2)$, the angular cone of aperture $\delta$ centered at $\hat{n}$ is
\begin{equation}
\mathcal{C}_\delta(\hat{n}) := \bigl\{ k \in \R^3 \setminus \{0\} : |\hat{k} - \hat{n}| \leq \delta \bigr\},
\end{equation}
where $\hat{k} = k/|k|$.

\label{thm:main-trilinear}
Let $u, v, w$ be divergence-free vector fields on $\R^3$ with Fourier support in $\mathcal{C}_\delta(\hat{n})$ for some $\hat{n} \in S^2$ and $\delta \in (0,1/2)$.  Then
\begin{equation}\label{eq:trilinear-main}
\biggl| \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx \biggr| \leq C_0\, \delta\, \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}},
\end{equation}
where $C_0$ is a universal constant independent of $\delta$, $\hat{n}$, and the fields $u,v,w$.

\label{thm:main-regularity}
Let $u$ be a Leray--Hopf weak solution of \eqref{eq:NS} with $u_0 \in H^1(\R^3)$ divergence-free.  Suppose that for all $t \in [0,T^*)$ the Fourier transform $\hat{u}(\cdot, t)$ is supported in $\mathcal{C}_{\delta(t)}(\hat{n}(t))$ for some measurable $\hat{n}(t) \in S^2$ and $\delta(t) \in (0,1/2)$ satisfying
\begin{equation}\label{eq:threshold}
\delta(t) < \delta_* := \frac{\nu}{2C_0\, \|u(t)\|_{\dot{H}^{1/2}}},
\end{equation}
where $C_0$ is the constant from Theorem~\ref{thm:main-trilinear}.  Then $u$ is smooth on $[0,T^*) \times \R^3$ and satisfies the algebraic decay estimate
\begin{equation}\label{eq:decay}
\|u(t)\|_{\dot{H}^{1/2}}^2 \leq \frac{\|u(t_0)\|_{\dot{H}^{1/2}}^2}{\bigl(1 + c\,\|u(t_0)\|_{\dot{H}^{1/2}}\,(t - t_0)\bigr)^2}
\end{equation}
for all $t_0 < t < T^*$, with $c > 0$ depending on $\nu$, $C_0$, and $\sup_t \delta(t)/\delta_*$.

\label{def:frame}
Fix $\hat{n} \in S^2$.  For $\xi \in \R^3 \setminus \{0\}$ with $\hat{\xi} \neq -\hat{n}$, define
\begin{equation}
e_1(\xi) := \frac{\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}}{|\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}|}, \qquad e_2(\xi) := \hat{\xi} \times e_1(\xi),
\end{equation}
and extend to $\hat{\xi} = \hat{n}$ by continuity.  The helical basis vectors are
\begin{equation}
e^\pm(\xi) := \frac{1}{\sqrt{2}}\bigl[e_1(\xi) \pm i\, e_2(\xi)\bigr].
\end{equation}

\label{lem:frame}
For $\hat{\xi}, \hat{\zeta} \in \mathcal{C}_\delta(\hat{n})$ with $\delta \in (0,1/2)$:
\begin{equation}
|e_i(\xi) - e_i(\zeta)| \leq \frac{4}{\delta}\, |\hat{\xi} - \hat{\zeta}|, \qquad i = 1,2.
\end{equation}

\label{lem:helical-inner}
For $\hat{\xi}, \hat{\zeta} \in \mathcal{C}_\delta(\hat{n})$ with $\delta \in (0,1/2)$:
\begin{align}
|e^+(\xi) \cdot e^+(\zeta)| &\leq 10\delta, \label{eq:pp}\\
|e^-(\xi) \cdot e^-(\zeta)| &\leq 10\delta, \label{eq:mm}\\
|e^+(\xi) \cdot e^-(\zeta) - 1| &\leq 10\delta. \label{eq:pm}
\end{align}

\label{lem:same}
For same-helicity interactions $(+,+) \to s_3$ or $(-,-) \to s_3$ with $\hat{p}, \hat{q}, \hat{k} \in \mathcal{C}_\delta(\hat{n})$:
\begin{equation}
|\sigma^{++s_3}(p,q,k)|, \; |\sigma^{--s_3}(p,q,k)| \lesssim \delta\, |q|.
\end{equation}

\label{lem:mixed}
For mixed-helicity interactions $(+,-) \to s_3$ or $(-,+) \to s_3$ with all directions in $\mathcal{C}_\delta(\hat{n})$:
\begin{equation}
|\sigma^{+-s_3}(p,q,k)|, \; |\sigma^{-+s_3}(p,q,k)| \lesssim \delta\, |q|.
\end{equation}

\label{prop:universal}
For \textbf{any} trilinear helicity interaction with all three wave-vector directions in $\mathcal{C}_\delta(\hat{n})$:
\begin{equation}
|\sigma^{s_1 s_2 s_3}(p,q,k)| \leq C_1\, \delta\, |q|,
\end{equation}
where $C_1$ is a universal constant.  Moreover, four of the eight channels---namely $(+,+) \to -$, $(-,-) \to +$, $(+,-) \to +$, and $(-,+) \to -$---satisfy the doubly-suppressed bound $|\sigma| \leq C_1\, \delta^2\, |q|$.

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\textbf{Interaction} & \textbf{First factor} & \textbf{Second factor} & \textbf{Total} \\
\hline
$(+,+) \to +$ & $O(\delta)$ & $O(1)$ & $O(\delta)$ \\
$(+,+) \to -$ & $O(\delta)$ & $O(\delta)$ & $O(\delta^2)$ \\
$(-,-) \to -$ & $O(\delta)$ & $O(1)$ & $O(\delta)$ \\
$(-,-) \to +$ & $O(\delta)$ & $O(\delta)$ & $O(\delta^2)$ \\
$(+,-) \to +$ & $O(\delta)$ & $O(\delta)$ & $O(\delta^2)$ \\
$(+,-) \to -$ & $O(\delta)$ & $O(1)$ & $O(\delta)$ \\
$(-,+) \to +$ & $O(\delta)$ & $O(1)$ & $O(\delta)$ \\
$(-,+) \to -$ & $O(\delta)$ & $O(\delta)$ & $O(\delta^2)$ \\
\hline
\end{tabular}
\end{center}

The pattern: the output helicity matching the second input helicity ($s_3 = s_2$) gives single suppression $O(\delta)$; mismatched ($s_3 \neq s_2$) gives double suppression $O(\delta^2)$.

Without angular localization, the standard trilinear estimate is
\begin{equation}
\biggl|\int (u \cdot \nabla v) \cdot w\, dx\biggr| \leq C\, \|u\|_{\dot{H}^{1/2}}\, \|v\|_{\dot{H}^1}\, \|w\|_{\dot{H}^{1/2}},
\end{equation}
which is \emph{critical} (saturates the NS scaling).  Theorem~\ref{thm:main-trilinear} gains a factor $\delta$ at the cost of replacing $\|v\|_{\dot{H}^1}$ by $\|v\|_{\dot{H}^{3/2}}$.  Since the latter appears in the dissipation term, this trade-off is favorable for energy estimates.

\label{cor:suppressed}
If $u$ is $\delta$-concentrated, then the nonlinear energy transfer in $\dot{H}^{1/2}$ satisfies
\begin{equation}\label{eq:suppressed}
\biggl|\int_{\R^3} (u \cdot \nabla u) \cdot |\nabla|u\, dx\biggr| \leq C_0\, \delta\, \|u\|_{\dot{H}^{1/2}}^2\, \|u\|_{\dot{H}^{3/2}}.
\end{equation}

\label{prop:dissipation}
Under the angular concentration condition \eqref{eq:threshold}, the critical energy decays:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\nu\, \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

\label{cor:criterion}
Let $u$ be a smooth solution of \eqref{eq:NS} on $[0,T^*)$.  If there exist $\hat{n}(t) \in S^2$ and $\delta_0 < 1/2$ such that
\begin{equation}
\int_{|k| |\hat{u}(k,t)|^2 \, \mathbf{1}_{\hat{k} \notin \mathcal{C}_{\delta_0}(\hat{n}(t))}\, dk \leq \varepsilon\, \|u(t)\|_{\dot{H}^{1/2}}^2
\end{equation}
with $\varepsilon$ and $\delta_0$ satisfying $\delta_0 + C\sqrt{\varepsilon} < \nu/(2C_0\, \|u\|_{L^\infty_t \dot{H}^{1/2}})$, then the solution extends smoothly beyond $T^*$.

\label{thm:BBD}
Suppose there exist real numbers $\tilde{\lambda}_t$ (allowed to
be negative) such that
\begin{equation}\label{eq:BBD-cond}
  \dot{C}_t^{1/2}\,\Hess(V_t)(\phi)\,\dot{C}_t^{1/2}
  - \tfrac{1}{2}\ddot{C}_t
  \ge \tilde{\lambda}_t\,\dot{C}_t
  \qquad \forall \phi, \forall t \ge 0,
\end{equation}
and set $\lambda_t = \int_0^t \tilde{\lambda}_s\,ds$. If
\begin{equation}\label{eq:BBD-integral}
  \frac{1}{\gamma} := \int_0^\infty e^{-2\lambda_t}\,dt < \infty,
\end{equation}
then $\nu_0$ satisfies the log-Sobolev inequality with constant
$\ge \gamma$.

The \emph{susceptibility} of the lattice Yang--Mills measure
$\mu_\Lambda$ at coupling $g^2$ is
\begin{equation}\label{eq:susc-def}
  \chi(g^2) := \sup_{x \in \Lambda}
  \sum_{y \in \Lambda} |\mathrm{Cov}_\mu(f_x, f_y)|,
\end{equation}
where $f_x$ is a local gauge-invariant observable at site $x$
(e.g., a plaquette variable).

\label{thm:susc}
The lattice Yang--Mills susceptibility satisfies
\begin{equation}\label{eq:susc-result}
  \chi(g^2) \le \frac{C(d, G)}{m(g^2)},
\end{equation}
where $m(g^2) > 0$ is the mass gap established
in~\cite{FontesLattice}.

\label{thm:lattice-LSI}
The lattice Yang--Mills measure on $\Lambda \subset \Z^d$ with
gauge group $G$ at coupling $g^2$ satisfies the log-Sobolev
inequality
\begin{equation}\label{eq:lattice-LSI}
  \Ent_\mu(F) \le \frac{C}{\gamma_{\mathrm{LSI}}}\,\cE_\mu(F),
\end{equation}
where $\gamma_{\mathrm{LSI}} > 0$ depends on $g^2$, $G$, $d$,
and $\cE_\mu$ is the Dirichlet form of the Glauber dynamics.
Moreover, $\gamma_{\mathrm{LSI}}$ is bounded below by
\begin{equation}
  \gamma_{\mathrm{LSI}} \ge c\bigl(\chi(g^2)\bigr)^{-1} > 0.
\end{equation}

\label{cor:concentration}
For any Wilson loop $W_\cC = \tr\,U_\cC$ around a contour $\cC$
in the lattice:
\begin{equation}\label{eq:concentration}
  \mu\bigl(|W_\cC - \langle W_\cC\rangle| \ge t\bigr)
  \le 2\exp\Bigl(-\frac{\gamma_{\mathrm{LSI}}\,t^2}
  {2\,\mathrm{Lip}(W_\cC)^2}\Bigr),
\end{equation}
where $\mathrm{Lip}(W_\cC)$ is the Lipschitz constant of $W_\cC$
with respect to the product metric on $G^{|\Lambda|}$.

\label{cor:hyper}
The Glauber semigroup $T_t$ satisfies
\begin{equation}
  \|T_t F\|_{L^q(\mu)} \le \|F\|_{L^p(\mu)}
  \qquad \text{for } \frac{q-1}{p-1} = e^{2\gamma_{\mathrm{LSI}}\,t}.
\end{equation}

\label{cor:entropy-decay}
The relative entropy of the Glauber dynamics decays exponentially:
\begin{equation}
  H(m_t | \mu) \le e^{-2\gamma_{\mathrm{LSI}}\,t}\,H(m_0 | \mu).
\end{equation}
This is strictly stronger than the spectral gap bound
$\Var_{m_t}(f) \le e^{-2\gamma\,t}\Var_{m_0}(f)$.

\label{prop:UV}
Assuming Balaban-type UV stability bounds~\cite{Balaban1987}:
for $0 \le t \le t_1$ with $g^2(t) \le \epsilon_0$,
\begin{equation}\label{eq:UV-hess}
  \Hess(V_t) \ge -\kappa_{\mathrm{UV}}(t)\,\mathrm{id}
\end{equation}
with $\kappa_{\mathrm{UV}}(t) \le C\,g^2(t)^2 \le C\,\epsilon_0^2$.

\label{prop:IR}
For $t \ge t_2$ with $g^2(t) \ge M_0$: the renormalized potential
$V_t$ satisfies
\begin{equation}\label{eq:IR-hess}
  \Hess(V_t) \ge \rho_G\,\mathrm{id},
\end{equation}
where $\rho_G > 0$ is the Ricci curvature of $G$
($\rho_{\SU(N)} = N$).

\label{thm:crossover}
Assuming the lattice block gap $\gamma_0(L_0, g^2) > 0$ of
\cite{FontesLattice}: for $t_1 \le t \le t_2$,
\begin{equation}\label{eq:cross-hess}
  \Hess(V_t) \ge -\frac{C}{\gamma_0}\,\mathrm{id}.
\end{equation}

