The DNS reveals that at high Reynolds number
($E \gg \nu^2$), the cross-cone transfer dominates:
\begin{equation}\label{eq:cross-dom}
\N_{\mathrm{cross}} > \N_{\mathrm{self}}.
\end{equation}

If this can be proved analytically, then from \eqref{eq:N-lower}:
\begin{equation}\label{eq:N-bound-gap}
\nu D < 2\N_{\mathrm{cross}}
\leq 2C\sin\theta_0\cdot E D^{1/2}.
\end{equation}

\label{def:curvature-zeta}
The \emph{curvature spectral zeta function} of $L_\gamma$ on $\mathbb{T}$ is
\begin{equation}\label{eq:curvature-zeta}
Z_\kappa(\gamma, s) \;:=\; \sum_{k=1}^{\infty} \kappa_k(\gamma)^{-s},
\qquad \operatorname{Re}(s) > 1,
\end{equation}
where $\{\kappa_k(\gamma)\}_{k \geq 1}$ are the eigenvalues of $M(\gamma) = R_H^{-1} R_H^{\circ 2}$
in the limit $N \to \infty$.

\label{cor:curvature-zeta-identity}
At $\gamma = 1$, the curvature spectral zeta function satisfies
\begin{equation}\label{eq:zeta-identity}
Z_\kappa(1, s) \;=\; (1 - 2^{-s})\,\zeta(s),
\end{equation}
where $\zeta(s) = \sum_{n=1}^\infty n^{-s}$ is the Riemann zeta function.

\label{cor:heat-trace}
At $\gamma = 1$, the heat trace of $M(1)$ is
\begin{equation}\label{eq:heat-trace}
\operatorname{Tr}\, e^{-t M(1)}
= \sum_{k=1}^{\infty} e^{-t(2k-1)}
= \frac{e^{-t}}{1 - e^{-2t}}
= \frac{1}{2 \sinh t},
\end{equation}
with a simple pole at $t = 0$ of residue $1/2$.

\label{cor:determinant}
The truncated curvature determinant satisfies
\begin{equation}\label{eq:determinant}
\det M_N(1) = \prod_{k=1}^N (2k-1) = (2N-1)!! = \mathbb{E}[X^{2N}],
\qquad X \sim \mathcal{N}(0,1).
\end{equation}
