statement:
\label{prop:rates}
For blow-up with $E \to \infty$:
\begin{enumerate}
\item $\mathcal{T} < -\nu D$ (trilinear must be large and negative)
\item $|\mathcal{T}| \leq CED^{1/2}$ (upper bound)
\item Combined: $\nu D < CED^{1/2}$, so $\lambda < CE^{1/2}/\nu$
\end{enumerate}

Under the hypothetical blow-up scenario:
\begin{enumerate}
\item $E$ must grow: $E \to \infty$
\item $D$ must grow: $D \geq cE$ (at least linear in $E$)
\item $\mathcal{T}$ must be large negative: $\mathcal{T} < -\nu D$
\item $\lambda$ must satisfy $\lambda < CE^{1/2}/\nu$ (sublinear in $E^{1/2}$)
\end{enumerate}

The term that ``fails first'' is the trilinear $\mathcal{T}$: it needs to be more negative than $-\nu D$, but this is incompatible with:
\begin{itemize}
\item The Closing Lemma bound (under concentration), which gives $dE/dt < 0$ for high $\lambda$
\item The outflow mechanism (under concentration), which breaks concentration for low $\lambda$
\end{itemize}

For spectrally localized data with $a > \lambda_{crit} = c_1/(4\nu)$:
\begin{itemize}
\item If concentrated: $\lambda \geq a > \lambda_{crit}$, so $dE/dt < 0$ (energy decreases)
\item If not concentrated: standard bounds apply
\end{itemize}
Either way, no blow-up.

\label{prop:dominant}
If $u_0$ has $(\rho_0, \Omega)$-dominant projection with $\rho_0 > 1 - \varepsilon_*$, then:
\begin{enumerate}
\item The solution starts concentrated
\item Either concentration breaks (Case (ii)) or energy decreases (Case (iii))
\item Global regularity follows
\end{enumerate}

\mbox{}
\begin{enumerate}
\item \textbf{Forward stability:} The corridor condition cannot fail instantaneously. Solutions transition continuously between cases, with rate bounds given by Theorem~\ref{thm:short-time}.

\item \textbf{Blow-up contradiction:} Under hypothetical blow-up, the trilinear term $\mathcal{T}$ would need to satisfy $\mathcal{T} < -\nu D$, but the Closing Lemma shows this is incompatible with maintaining concentration. The ``escape routes'' (low $\lambda$ or high $\lambda$) both lead away from blow-up.

\item \textbf{Natural satisfaction:} The corridor condition automatically implies no blow-up for:
\begin{itemize}
\item Almost-helical flows (remain non-concentrated)
\item Spectrally localized data with high minimum frequency (energy decreases)
\item Data with dominant projected component (dichotomy applies)
\item Solutions with bounded enstrophy growth (BKM satisfied)
\end{itemize}
\end{enumerate}

\label{cond:var}
For each block-averaged field $\Phi_{k+1}$ in the
small field region:
\begin{enumerate}[label=(\alph*),nosep]
  \item There exists a unique (modulo gauge) minimizer
    $U^{\min}$ of $S_k$ subject to $Q(U) = \Phi_{k+1}$;
  \item $U^{\min}$ is analytic in $\Phi_{k+1}$
    on the small field domain;
  \item the minimizer satisfies regularity:
    $\|F_{U^{\min}}\|_\infty \le C \|F_{\Phi_{k+1}}\|_\infty$;
  \item the dependence on data at distance $r$
    decays as $e^{-mr}$ with $m = O(\sqrt{\beta_k})$.
\end{enumerate}

\label{cond:prop}
The gauge-covariant propagator~\eqref{eq:propagator}
with $\SU(N)$ background satisfies:
\begin{enumerate}[label=(\alph*),nosep]
  \item $C_k$ exists and is bounded:
    $\|C_k\| \le C_0$ uniformly in the small field
    background;
  \item exponential decay: $|C_k(x,y)| \le C_0
    e^{-m_0 |x-y|/\eta_k}$ with $m_0 > 0$
    independent of $k$;
  \item the random walk expansion converges
    with $\SU(N)$ commutator corrections
    bounded by $C g^2 \eta_k$;
  \item $C_k$ is analytic in the background field
    on the small field domain.
\end{enumerate}

\label{cond:poly}
The polymer activities $K(X, \Phi_{k+1})$
satisfy:
\begin{enumerate}[label=(\alph*),nosep]
  \item $|K(X, \Phi_{k+1})| \le e^{-c_0 |X|}$
    for a constant $c_0$ independent of $k$;
  \item gauge invariance: $K(X, \Phi_{k+1}^u) =
    K(X, \Phi_{k+1})$;
  \item stability: the estimates are preserved
    under $N \to N-1$ RG steps.
\end{enumerate}

\label{thm:3d_uv}
Assume Conditions~\ref{cond:avg}--\ref{cond:poly}
hold for $G = \SU(N)$ in $d = 3$ with coupling
$g^2 > 0$. Then the partition function
satisfies the UV stability bound:
\begin{equation}
  e^{-C_1 L^{3M}} \le \cZ_{M,N}
  \le e^{C_2 L^{3M}}
\end{equation}
uniformly in $N$ (lattice spacing $\eta = L^{-N}$),
for constants $C_1, C_2$ depending on $g^2$ and $L$
but not on $N$.

\label{cond:4d}
The bare coupling $g^2(0)$ can be chosen as a
function of $N$ (the number of RG steps) such that:
\begin{enumerate}[label=(\alph*),nosep]
  \item $g^2(0) \sim \frac{1}{b_0 N \log L}$ as $N \to \infty$;
  \item the effective coupling $g^2(k)$ satisfies
    $c_1/(N-k) \le g^2(k) \le c_2/(N-k)$ for
    $0 \le k \le N - k_0$ (UV regime);
  \item the correction $V_k$ satisfies
    $\|V_k\|_\infty \le C g^4(k)$ uniformly;
  \item the polymer remainder satisfies
    $\|K_k - 1\| \le C g^2(k)$ uniformly.
\end{enumerate}

\label{cond:4d_action}
At each scale $k$, the effective action
$\cS_k(\Phi_k) = g^{-2}(k) S_k + V_k$
satisfies the \emph{Hessian bound}:
\begin{equation}\label{eq:hessian_4d}
  \|\Hess \cS_k(\Phi_k) - \Hess_0\|_{\text{op}}
  \le C g^2(k)
\end{equation}
on the small field region, where $\Hess_0$ is the
Hessian of the free (Gaussian) action at scale $k$.

\label{thm:4d_uv}
Assume Conditions~\ref{cond:avg}--\ref{cond:poly}
(adapted to $d=4$ with running coupling)
and Conditions~\ref{cond:4d}--\ref{cond:4d_action}.
Then the partition function satisfies
\begin{equation}
  e^{-C_1 L^{4M}} \le \cZ_{M,N}
  \le e^{C_2 L^{4M}}
\end{equation}
uniformly in $N$, for constants depending on $L$
and the renormalized coupling $g^2_R = g^2(N)$.

\label{ass:blowup}
Let $u$ be a smooth solution to 3D Navier-Stokes on $[0, T^*)$ with:
\begin{enumerate}[label=(\roman*)}
\item Bounded initial energy: $\|u_0\|_{L^2}^2 < \infty$
\item Critical blow-up: $\limsup_{t \to T^*} \|u(t)\|_{\Hdot{1/2}} = +\infty$
\end{enumerate}

\label{lem:high-freq}
Under Assumption~\ref{ass:blowup}, there exists a sequence $t_n \nearrow T^*$ and scales $N_n \to \infty$ such that:
\begin{equation}\label{eq:freq-conc}
\int_{|\xi| \geq N_n} |\xi| |\hat{u}(t_n, \xi)|^2 d\xi \geq \frac{1}{2} E(t_n)
\end{equation}

\label{lem:spatial-loc}
If \eqref{eq:freq-conc} holds at time $t$, then there exists $x_0 \in \R^3$ such that:
\begin{equation}\label{eq:spatial-conc}
\int_{|x - x_0| \leq R} |(-\Delta)^{1/4} u(t,x)|^2 dx \geq c_0 E(t)
\end{equation}
for $R = C_1/N_n$, where $c_0, C_1 > 0$ are universal constants.

\label{lem:freq-balance}
Let $P_N = P_{\geq N}$ be the projection to frequencies $|\xi| \geq N$. Define:
\[
E_N(t) := \|P_N u(t)\|_{\Hdot{1/2}}^2, \quad D_N(t) := \|P_N u(t)\|_{\Hdot{3/2}}^2
\]

Then:
\begin{equation}\label{eq:EN-evol}
\frac{d}{dt} E_N = -2\Tril_N - 2\nu D_N + \text{Flux}_N
\end{equation}
where:
\begin{align}
\Tril_N &:= \langle P_N[(u \cdot \nabla)u], |\nabla| P_N u \rangle \\
\text{Flux}_N &:= \text{energy flux from low to high frequencies across } |\xi| = N
\end{align}

\label{lem:diss-lower}
\begin{equation}
D_N \geq N^2 E_N
\end{equation}

\label{lem:tril-N}
\begin{equation}
|\Tril_N| \leq C_0 E \cdot D^{1/2}
\end{equation}
where $E, D$ are the full (not frequency-localized) norms.

More refined:
\begin{equation}
|\Tril_N| \leq C_0 E_N^{1/2} E^{1/2} D^{1/2} + C_0 E_{<N} E_N^{1/2} D_N^{1/2}
\end{equation}
where $E_{<N} = E - E_N$.

\label{thm:summary}
Under Assumption~\ref{ass:blowup}:
\begin{enumerate}
\item Blow-up requires frequency concentration: $\lambda(t) \to \infty$
\item Blow-up requires $\lambda(t) \leq C E(t)^{1/2}/\nu$ for energy growth
\item The energy balance allows $\frac{dE}{dt} \lesssim E^2$, permitting finite-time blow-up
\item Enstrophy must also blow up
\end{enumerate}

\textbf{Not proven:} A contradiction ruling out blow-up.

\label{prop:attn}
For any fixed $q$:
\textnormal{(i)}~$\Pi_q$ is linear;
\textnormal{(ii)}~positive
($v_i \geq 0 \Rightarrow \Pi_q(v) \geq 0$);
\textnormal{(iii)}~normalized
($\Pi_q(\mathbf{1}) = 1$);
\textnormal{(iv)}~a contraction
($\norm{\Pi_q(v)} \leq \max_i \norm{v_i}$, by Jensen).

\label{prop:innovation}
Applying~\eqref{eq:diff} before the attention layers:
\textnormal{(i)}~costs $O(L)$, negligible relative to
$O(L^2)$ attention;
\textnormal{(ii)}~changes no parameters;
\textnormal{(iii)}~transforms temporal signals from
a space where they are invisible to $\Pi$
(content-similar values) to one where they are
visible (sparse innovations at transitions).

\label{cor:bounds}
For $\alpha \in (0,1)$, $\lambda > 0$, and $t > 0$:
\begin{equation}\label{eq:bounds}
\frac{1}{1 + \lambda\,t^\alpha / \Gamma(1+\alpha)}
\;\leq\; E_\alpha(-\lambda\,t^\alpha)
\;\leq\; \frac{1}{1 + \lambda\,t^\alpha
  / \Gamma(1-\alpha)}.
\end{equation}

\label{rem:alpha_role}
The fractional order $\alpha$ controls the sharpness
of temporal discrimination:
$\alpha \to 1$ approaches exponential decay
(sharp cutoff, short memory);
$\alpha \to 0$ approaches a constant function
(no discrimination, infinite memory).
The spectral representation~\eqref{eq:spectral}
makes this explicit: at $\alpha = 1$, the spectral
density concentrates on a single rate $r = \lambda$;
at smaller $\alpha$, the density spreads over a
continuum of rates, generating the multi-scale
persistence that characterizes fractional dynamics.

\label{prop:stretching-decomp}
For smooth divergence-free $u$ on $\T^3$:
\begin{equation}\label{eq:W-alpha}
\mathcal{W} = \int_{\T^3}|\omega(x)|^2\,
\alpha(x)\,dx,
\end{equation}
where $\alpha = \hat\omega\cdot S\hat\omega
\in[-|S|,|S|]$ is the local stretching rate.
The normalized stretching ratio
\begin{equation}\label{eq:rho-def}
\rho(u) := \frac{\int|\omega|^2\alpha\,dx}
{\int|\omega|^2|S|\,dx}
= \frac{\mathcal{W}}{\int|\omega|^2|S|\,dx}
\in [-1,1]
\end{equation}
is degree~0 (dimensionless).  The enstrophy equation
becomes
\begin{equation}\label{eq:enst-rho}
\frac{1}{2}\frac{d}{dt}\|\omega\|^2
= \rho\int|\omega|^2|S|\,dx
- \nu\|\nabla\omega\|^2.
\end{equation}

