\label{cor:bounds}
For $\alpha \in (0,1)$, $\lambda > 0$, and $t > 0$:
\begin{equation}\label{eq:bounds}
\frac{1}{1 + \lambda\,t^\alpha / \Gamma(1+\alpha)}
\;\leq\; E_\alpha(-\lambda\,t^\alpha)
\;\leq\; \frac{1}{1 + \lambda\,t^\alpha
  / \Gamma(1-\alpha)}.
\end{equation}

\label{rem:alpha_role}
The fractional order $\alpha$ controls the sharpness
of temporal discrimination:
$\alpha \to 1$ approaches exponential decay
(sharp cutoff, short memory);
$\alpha \to 0$ approaches a constant function
(no discrimination, infinite memory).
The spectral representation~\eqref{eq:spectral}
makes this explicit: at $\alpha = 1$, the spectral
density concentrates on a single rate $r = \lambda$;
at smaller $\alpha$, the density spreads over a
continuum of rates, generating the multi-scale
persistence that characterizes fractional dynamics.

\label{def:cdc}
For the jump generator $L_\gamma$ with L\'evy measure $\nu_\gamma$,
the sesquilinear carr\'e du champ is
\begin{equation}\label{eq:cdc}
  \widetilde{\Gamma}_\gamma(f,g)(x)
  := \frac{1}{2} \int_{\R \setminus \{0\}}
  \bigl[f(x+z) - f(x)\bigr]\,
  \overline{\bigl[g(x+z) - g(x)\bigr]}\;
  \nu_\gamma(dz).
\end{equation}
On real-valued functions, $\widetilde{\Gamma}_\gamma(f,g) = \Gamma_\gamma(f,g)$,
the standard bilinear carr\'e du champ.

\label{thm:gamma2-kernel}
Let $\gamma \in (0,2)$ and $\xi, \eta \in \R$. Then
\begin{equation}\label{eq:gamma2-kernel}
  \widetilde{\Gamma}_{\gamma,2}(e^{i\xi\cdot}, e^{i\eta\cdot})(x)
  = e^{i(\xi-\eta)x}\,\Phi_{\gamma,2}(\xi,\eta),
\end{equation}
where the $\Gamma_2$-kernel is
\begin{equation}\label{eq:Phi-formula}
  \Phi_{\gamma,2}(\xi,\eta)
  = \bigl[\Psi_\gamma(\xi,\eta)\bigr]^2
  = \bigl[R_{\gamma/2}(|\xi|,|\eta|)\bigr]^2.
\end{equation}

\label{thm:curvature}
Let $N \geq 1$ and let $\mathcal{T}_N^+$ denote the space of
trigonometric polynomials $f = \sum_{n=1}^N a_n\,e^{inx}$
(positive frequencies only). Then
\begin{equation}\label{eq:kappa-def}
  \kappa(\gamma, N)
  := \inf_{f \in \mathcal{T}_N^+ \setminus \{0\}}
  \inf_{x \in \T}
  \frac{\widetilde{\Gamma}_{\gamma,2}(f,f)(x)}
       {\widetilde{\Gamma}_\gamma(f,f)(x)}
  = \lambda_{\min}\!\bigl(R_H^{\circ 2},\, R_H\bigr),
\end{equation}
where $H = \gamma/2$, $R_H$ is the $N \times N$ matrix
$(R_H)_{nm} = R_H(n,m)$, $R_H^{\circ 2}$ is its Hadamard square,
and $\lambda_{\min}$ is the smallest generalized eigenvalue solving
$R_H^{\circ 2}\,v = \lambda\,R_H\,v$.

