\label{thm:cauchy}
At $\gamma = 1$ ($H = 1/2$), the $N \times N$ matrix
$R_{1/2}^{-1}\,R_{1/2}^{\circ 2}$ is upper triangular with diagonal
entries $2k - 1$ for $k = 1,\ldots,N$. The generalized eigenvalues
of $(R_{1/2}^{\circ 2}, R_{1/2})$ are therefore
$\{1, 3, 5, \ldots, 2N-1\}$, and
\begin{equation}\label{eq:kappa-cauchy}
  \kappa(1, N) = 1 \quad \text{for all } N \geq 1.
\end{equation}

\label{thm:phase-transition}
The curvature $\kappa(\gamma, N)$ exhibits the following behavior:
\begin{enumerate}[label=(\roman*)]
\item \textbf{Sub-Cauchy regime ($\gamma < 1$).}
  For each $\gamma \in (0,1)$, the sequence $\kappa(\gamma, N)$
  converges to a finite limit $\kappa(\gamma) > 1$ as $N \to \infty$.
  The function $\gamma \mapsto \kappa(\gamma)$ is continuous on $(0,1)$
  with $\kappa(\gamma) \to 1$ as $\gamma \to 1^-$.

\item \textbf{Cauchy point ($\gamma = 1$).} $\kappa(1, N) = 1$ for all $N$.

\item \textbf{Super-Cauchy regime ($\gamma > 1$).}
  For each $\gamma \in (1,2)$ and each finite $N$, $\kappa(\gamma, N) > 0$
  for $N$ sufficiently small. However, for each $\gamma > 1$,
  $\kappa(\gamma, N) \to -\infty$ as $N \to \infty$.
\end{enumerate}

\label{thm:logsob}
For $\gamma \in (0,1]$ and $f = \sum_{n=1}^N a_n\,e^{inx}$:
\begin{equation}\label{eq:logsob}
  \int_\T \widetilde{\Gamma}_\gamma(f,f)\,\log
  \frac{\widetilde{\Gamma}_\gamma(f,f)}
       {\|\widetilde{\Gamma}_\gamma(f,f)\|_{L^1(\T)}}\,d\mu
  \leq C(\gamma)\,
  \int_\T \widetilde{\Gamma}_{\gamma,2}(f,f)\,d\mu,
\end{equation}
where $C(\gamma) = 2/\kappa(\gamma)$ and $\kappa(\gamma)$
is the curvature from Theorem~\ref{thm:phase-transition}.

In particular, $C(1) = 2$ (the classical constant).

\label{def:cdc}
The sesquilinear carr\'e du champ of $L_\gamma$ is
\begin{equation}\label{eq:cdc}
  \widetilde{\Gamma}_\gamma(f,g)(x)
  := \frac{1}{2} \int_{\R \setminus \{0\}}
  \bigl[f(x+z) - f(x)\bigr]\,
  \overline{\bigl[g(x+z) - g(x)\bigr]}\;
  \nu_\gamma(dz).
\end{equation}
On Fourier modes:
\begin{equation}\label{eq:psi-kernel}
  \widetilde{\Gamma}_\gamma(e^{i\xi\cdot}, e^{i\eta\cdot})(x)
  = e^{i(\xi-\eta)x}\,\Psi_\gamma(\xi,\eta),
\end{equation}
where $\Psi_\gamma(\xi,\eta)
= \tfrac{1}{2}(|\xi|^\gamma + |\eta|^\gamma - |\xi-\eta|^\gamma)$.

\label{thm:duality}
For $\gamma \in (0,2)$ and all $\xi, \eta \in \R$:
\begin{equation}\label{eq:duality}
  \Psi_\gamma(\xi,\eta)
  = \tfrac{1}{2}\bigl(|\xi|^\gamma + |\eta|^\gamma
  - |\xi - \eta|^\gamma\bigr)
  = R_{\gamma/2}(|\xi|, |\eta|).
\end{equation}
The carr\'e du champ of the $\gamma$-stable generator, evaluated
on Fourier modes, is the covariance of fBM with $H = \gamma/2$.

\label{rem:three}
The kernel $\frac{1}{2}(|\xi|^\gamma + |\eta|^\gamma
- |\xi-\eta|^\gamma)$ appears in:
(i)~Schoenberg's theory of conditionally negative definite
functions~\cite{Schoenberg1938};
(ii)~Dirichlet forms for jump
processes~\cite{BoettcherSchillingWang2013};
(iii)~fBM covariance theory~\cite{Mishura2008}.
These three appearances have not previously been connected explicitly.

