\label{lem:lambda-evol}
\begin{equation}\label{eq:lambda2}
\frac{d}{dt}(\lambda^2) = \frac{d}{dt}\left(\frac{D}{E}\right) = \frac{1}{E}\left(\frac{dD}{dt} - \lambda^2 \frac{dE}{dt}\right)
\end{equation}

Substituting the evolution equations:
\begin{equation}\label{eq:lambda2-full}
\frac{d(\lambda^2)}{dt} = \frac{1}{E}\left[-2\Tril_{3/2} - 2\nu F + \lambda^2(2\Tril + 2\nu D)\right]
\end{equation}

Simplifying:
\begin{equation}\label{eq:lambda2-simple}
\boxed{\frac{d(\lambda^2)}{dt} = \frac{2}{E}\left[\lambda^2 \Tril - \Tril_{3/2}\right] + \frac{2\nu}{E}\left[\lambda^2 D - F\right]}
\end{equation}

\label{lem:diss-term}
\begin{equation}
\lambda^2 D - F \leq 0
\end{equation}
with equality iff $u$ is supported at a single frequency $|\xi| = \lambda$.

\label{lem:tril-bounds}
\begin{align}
|\Tril| &\leq C_1 E D^{1/2} = C_1 \lambda E^{3/2} \\
|\Tril_{3/2}| &\leq C_2 E^{1/2} D^{1/2} F^{1/2} \leq C_2 D^{3/2} = C_2 \lambda^3 E^{3/2}
\end{align}

\label{cor:delta-tril}
\begin{equation}
|\Delta\Tril| = |\lambda^2 \Tril - \Tril_{3/2}| \leq C_1 \lambda^3 E^{3/2} + C_2 \lambda^3 E^{3/2} = C \lambda^3 E^{3/2}
\end{equation}

