\label{def:dd-pair}
A \emph{derivative-divergence pair} $(D, \delta)$ consists of:
\begin{enumerate}[label=(\roman*)]
\item A closed, densely-defined operator $D: \mathrm{Dom}(D) \subset L^2(\Omega) \to L^2(\Omega; \cH)$
\item Its adjoint $\delta := D^*: \mathrm{Dom}(\delta) \subset L^2(\Omega; \cH) \to L^2(\Omega)$
\end{enumerate}
satisfying the integration-by-parts relation
\begin{equation}\label{eq:ibp}
\E[F \cdot \delta(u)] = \E[\ip{DF}{u}_\cH]
\end{equation}
for $F \in \mathrm{Dom}(D)$ and $u \in \mathrm{Dom}(\delta)$.

\label{def:compatible}
A projection $\Pi$ is \emph{compatible} with $(D, \delta)$ if
\begin{equation}\label{eq:compatible}
(\Id - \E)F = \delta(\Pi D F)
\end{equation}
for all $F$ in a dense subspace of $L^2(\Omega)$.

\label{def:curvature}
The \emph{curvature} of a projection $\Pi$ with respect to $D$ is the commutator
\begin{equation}\label{eq:curvature-def}
\Omega_\Pi := [D, \Pi] = D\Pi - \Pi D
\end{equation}
defined on suitable domains.

following_proof:
Assume $[D, \Pi] = 0$, so $D\Pi = \Pi D$. For $F \in \mathrm{Dom}(D)$:
\begin{align}
\delta(\Pi D F) &= \delta(\Pi D F) \\
&= D^*(\Pi D F).
\end{align}
By the projection property $\Pi^2 = \Pi$ and self-adjointness $\Pi^* = \Pi$:
\begin{equation}
\E[\delta(\Pi DF)] = \E[\ip{D(\cdot)}{\Pi DF}_\cH] = \E[\ip{\Pi D(\cdot)}{DF}_\cH].
\end{equation}
The commutativity $D\Pi = \Pi D$ and standard integration by parts yield
\begin{equation}
\delta(\Pi D F) = F - \E[F]. \qedhere
\end{equation}

statement:
\label{def:curv-norm}
The \emph{curvature norm} is
\begin{equation}
\norm{\Omega_\Pi} := \sup_{\norm{u}_\cH = 1} \norm{[D, \Pi] u}_{L^2(\Omega; \cH)}.
\end{equation}

\label{def:marg-proj}
A \emph{marginalization projection} is defined by
\begin{equation}\label{eq:marg-proj}
(\Pi f)(x) = \int f(x, y) \, \mu(dy | x)
\end{equation}
where $\mu(\cdot | x)$ is a conditional probability measure on ``interior'' variables $y$ given ``boundary'' variables $x$.

\label{def:convexity}
The projection has \emph{convexity} $\lambda > 0$ if the conditional measure $\mu(\cdot | x)$ is $\lambda$-log-concave:
\begin{equation}\label{eq:log-concave}
\nabla^2_{yy} V(x, y) \succeq \lambda I
\end{equation}
where $\mu(dy | x) \propto e^{-V(x,y)} dy$.

\label{lem:BL}
Let $\mu \propto e^{-V}$ with $\nabla^2 V \succeq \lambda I$. Then for any smooth $g$:
\begin{equation}\label{eq:BL}
\Var_\mu(g) \leq \frac{1}{\lambda} \E_\mu[\norm{\nabla g}^2].
\end{equation}

\label{prop:curv-hessian}
For a marginalization projection with potential $V(x,y)$, the curvature satisfies
\begin{equation}\label{eq:curv-hessian}
\norm{\Omega_\Pi} \leq \frac{1}{\lambda} \norm{\nabla^2_{xy} V}_{\mathrm{op}}
\end{equation}
where $\nabla^2_{xy} V$ is the mixed Hessian.

following_proof:
The boundary derivative of the marginalized function involves:
\begin{equation}
\nabla_x (\Pi f) = \Pi(\nabla_x f) + \text{(curvature term)}.
\end{equation}
The curvature term arises from differentiating the conditional measure:
\begin{equation}
\nabla_x \mu(dy|x) = -(\nabla_x V - \E_\mu[\nabla_x V]) \mu(dy|x).
\end{equation}
By Brascamp-Lieb, the covariance of $\nabla_x V$ with $f$ is controlled by $\nabla^2_{xy} V / \lambda$.

statement:
\label{thm:contraction}
Let $\Pi$ be a marginalization projection with convexity $\lambda > 0$ and curvature bound $\norm{\Omega_\Pi} \leq M$. Define the \emph{boundary derivative} $D_\partial$ as differentiation in the $x$-variables. Then:
\begin{equation}\label{eq:contraction}
\norm{D_\partial(\Pi f)}_{L^2} \leq q \norm{D_\partial f}_{L^2}
\end{equation}
where the \emph{contraction rate} is
\begin{equation}\label{eq:q-def}
q := \frac{M^2}{\lambda + M^2} < 1.
\end{equation}

following_proof:
Write the full Hessian of $V$ in block form:
\begin{equation}
\nabla^2 V = \begin{pmatrix} H_{xx} & H_{xy} \\ H_{yx} & H_{yy} \end{pmatrix}
\end{equation}
where $H_{yy} \succeq \lambda I$ by convexity and $\norm{H_{xy}} \leq M$ by the curvature bound.

The Schur complement formula gives the effective boundary Hessian after marginalizing $y$:
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}} = H_{xx} - H_{xy} H_{yy}^{-1} H_{yx}.
\end{equation}

The gradient contraction follows from comparing the full and effective covariances:
\begin{equation}
\norm{\nabla_x (\Pi f)}^2 \leq \ip{\nabla f}{(\nabla^2 V)^{-1} \nabla f} - \ip{\nabla_y f}{H_{yy}^{-1} \nabla_y f}.
\end{equation}

By the Schur complement bound:
\begin{equation}
\frac{\norm{\nabla_x(\Pi f)}^2}{\norm{\nabla_x f}^2} \leq 1 - \frac{\lambda}{\lambda + M^2} = \frac{M^2}{\lambda + M^2} = q^2.
\end{equation}
Taking square roots gives \eqref{eq:contraction}.

statement:
\label{thm:clustering}
Let $f, g$ be observables localized at regions separated by distance $r$ (corresponding to $n \sim r/L$ projection steps, where $L$ is the block size). Then:
\begin{equation}\label{eq:clustering}
\abs{\Cov(f, g)} \leq C q^n \norm{Df} \norm{Dg} \leq C e^{-mr} \norm{Df} \norm{Dg}
\end{equation}
where $m = -(\log q)/L > 0$ is the \emph{mass gap}.

following_proof:
The covariance factors through intermediate projections:
\begin{equation}
\Cov(f, g) = \E[(f - \E f)(g - \E g)] = \E[(f - \E f) \cdot \Pi^{(n)}(g - \E g)].
\end{equation}
By Cauchy-Schwarz and the Poincaré inequality:
\begin{equation}
\abs{\Cov(f,g)} \leq \norm{f - \E f}_{L^2} \cdot \norm{\Pi^{(n)}(g - \E g)}_{L^2}.
\end{equation}
The Poincaré inequality gives $\norm{h - \E h} \leq C \norm{Dh}$. By iterated contraction:
\begin{equation}
\norm{\Pi^{(n)}(g - \E g)} \leq C q^n \norm{Dg}.
\end{equation}
Combining: $\abs{\Cov(f,g)} \leq C^2 q^n \norm{Df} \norm{Dg}$.

