\label{def:holonomy}
For a path $\gamma = (e_1, \ldots, e_k)$, the \emph{holonomy} is
\begin{equation}
U_\gamma := U_{e_1} U_{e_2} \cdots U_{e_k} \in G.
\end{equation}

\label{def:wilson}
Let $\rho: G \to \mathrm{GL}(V)$ be the fundamental representation with $\dim V = d_\rho$. The \emph{Wilson action} is
\begin{equation}\label{eq:wilson}
S_\beta[U] := \beta \sum_{p} \left(1 - \frac{1}{d_\rho} \mathrm{Re}\, \Tr_\rho(U_p)\right)
\end{equation}
where $\beta > 0$ is the \emph{inverse coupling} and the sum is over all plaquettes.

\label{def:gibbs}
The \emph{lattice Gibbs measure} is
\begin{equation}\label{eq:gibbs}
d\mu_\beta := \frac{1}{Z_\beta} e^{-S_\beta[U]} \prod_{e \in E} dU_e
\end{equation}
where $dU_e$ is normalized Haar measure on $G$ and $Z_\beta$ is the partition function.

\label{def:quad-core}
\begin{equation}\label{eq:V0}
V^{(0)}(x, y) := \frac{\beta c_2}{2} \norm{Ay + vx}^2
\end{equation}
with:
\begin{itemize}
\item $A \in \R^{P \times I}$: incidence matrix (plaquettes $\times$ interior edges)
\item $v \in \R^P$: boundary coupling vector
\item $c_2 = 1/2$: coefficient from $1 - \cos\theta = \theta^2/2 + O(\theta^4)$
\end{itemize}

\label{def:delta}
$\Delta(x, y)$ contains:
\begin{enumerate}
\item BCH corrections from $\log(e^X e^Y) \neq X + Y$
\item Jacobian corrections from the exponential map
\item Higher-order terms in the Wilson action
\end{enumerate}

\label{def:transfer}
The \emph{transfer operator} $T: L^2(\partial B) \to L^2(\partial B)$ is
\begin{equation}\label{eq:transfer}
(Tf)(x) := \int f(x, y) \, \mu_B(dy | x)
\end{equation}
where $\mu_B(\cdot | x) \propto e^{-V(x, \cdot)}$ is the conditional measure on interior variables.

\label{prop:factor}
The transfer operator satisfies the factorization identity:
\begin{equation}\label{eq:factor-gauge}
(\Id - \E_B) = \delta_\partial \, T \, D_\partial
\end{equation}
where $D_\partial$ is the boundary Lie derivative and $\delta_\partial = D_\partial^*$.

\label{def:curv-transfer}
The \emph{curvature of the transfer operator} is
\begin{equation}\label{eq:curv-transfer}
\Omega_T := [D_\partial, T] = D_\partial T - T D_\partial.
\end{equation}

\label{def:v}
For a $2 \times 2$ tile in $d = 4$ dimensions (projected to a 2D slice), the boundary coupling vector is
\begin{equation}\label{eq:v}
v = (1, 1, 1, 1)^\top \in \R^4
\end{equation}
corresponding to the four interior plaquettes each coupling to the coarse boundary holonomy with coefficient $+1$.

\label{lem:topo}
For the incidence matrix $A$ and boundary coupling vector $v$:
\begin{equation}\label{eq:Atv}
A^\top v = 0.
\end{equation}

following_proof:
Each interior edge $i$ appears in exactly two of the four plaquettes in the tile, with \emph{opposite orientations} (one as $+1$, one as $-1$). This is a consequence of the tile geometry: an interior edge lies between two adjacent plaquettes and is traversed in opposite directions.

For each interior edge $i$, let $p^+$ and $p^-$ be the two plaquettes containing it. Then:
\begin{equation}
(A^\top v)_i = \sum_{p=1}^{4} A_{pi} v_p = A_{p^+, i} \cdot 1 + A_{p^-, i} \cdot 1 = (+1) + (-1) = 0.
\end{equation}
Since this holds for all interior edges $i$, we have $A^\top v = 0$.

