\label{def:inv-region}
The \emph{invariant region} $\cR = \cR(\delta_*, \varepsilon_*, \lambda_*)$ consists of effective actions $V$ satisfying:
\begin{enumerate}
\item[(R1)] \textbf{Corridor}: $\norm{(x, y)} \leq \delta_*$
\item[(R2)] \textbf{Convexity}: $\nabla^2_{yy} V \succeq \lambda_* I$
\item[(R3)] \textbf{Mixed Hessian}: $\norm{\nabla^2_{xy} V} \leq M_* = 48\delta_*$
\item[(R4)] \textbf{$C^2$ control}: $\norm{\nabla^2 \Delta} \leq \varepsilon_*$
\end{enumerate}

\label{thm:closure}
The region $\cR$ is preserved under the RG step if:
\begin{align}
\text{(I1)} &\quad \alpha_\Phi \delta_* + \frac{\beta_\Phi}{2} \delta_*^2 < \delta_* \label{eq:I1} \\
\text{(I2)} &\quad a_0 := \frac{M_*^2}{\lambda_0 + M_*^2} < 1 \label{eq:I2} \\
\text{(I3)} &\quad \frac{b_0 \delta_*^2}{1 - a_0} \leq \varepsilon_* \label{eq:I3} \\
\text{(I4)} &\quad \lambda_0 - \frac{\theta_0 \varepsilon_*}{1 - a_0} \geq \lambda_* \label{eq:I4} \\
\text{(I5)} &\quad \lambda_0 \geq \lambda_* \label{eq:I5} \\
\text{(I6)} &\quad \delta_* \leq 0.2 \label{eq:I6}
\end{align}
where $\lambda_0 = \beta_0 c_2 \lambda_i = \beta_0/2$ and $M_* = 48\delta_*$.

\label{def:box}
