Given boundary condition $\eta=(U_\ell)_{\ell\in\partial B}$, the
\emph{background field} $U_0(y|\eta)$ is the configuration of interior
links that minimizes the action:
\begin{equation}\label{eq:minimizer}
U_0(y|\eta)=\arg\min_{y}\sum_{p\cap B^\circ\ne\emptyset}
\bigl(1-\tfrac{1}{2}\tr\,U_p(y,\eta)\bigr).
\end{equation}

\label{def:Q}
The blocking map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$
sends the fine-lattice configuration $U$ to the coarse-lattice
configuration $V=QU$ defined by:
\begin{equation}\label{eq:Q}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice from the
source to the target of the coarse link $\ell'$, chosen along the
block boundary.

\label{prop:equivariant}
The blocking map~\eqref{eq:Q} is gauge-equivariant: for any gauge
transformation $g=(g_x)_{x\in\Lambda_k}$,
\begin{equation}
Q(U^g)=(QU)^{\bar{g}},
\end{equation}
where $\bar{g}$ is the induced gauge transformation on the coarse
lattice, $\bar{g}_{x'}=g_{x'}$ for coarse vertices $x'$.

\label{cor:NAschur}
The non-abelian Schur complement satisfies
\begin{equation}\label{eq:NAschur-bound}
H_{\mathrm{eff}}^{\mathrm{NA}}
=H_{\mathrm{eff}}^{\mathrm{ab}}+O(\theta_*^2),
\end{equation}
where $H_{\mathrm{eff}}^{\mathrm{ab}}$ is the abelian Schur complement
computed in Papers~9 and~12 (with $\lambda_{\min}^{\mathrm{bdy}}=0.696$).

\label{thm:effaction}
After integrating out interior links of block $B$ with boundary
$\eta$ held fixed, the effective action takes the form
\begin{equation}\label{eq:Seff}
S_{\mathrm{eff}}(\eta)
=\beta_{\mathrm{eff}}\sum_{p\in\partial B}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+E(\eta),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{\mathrm{eff}}=\beta-\delta\beta$ with
$\delta\beta=8b_0\log 2+O(1/\beta)$ (Paper~12);
\item $V_p(\eta)$ is the coarse plaquette formed from boundary links;
\item $|E(X)|\le C(4/\beta)^2 e^{-\kappa d(X)}$ with
$\kappa=0.83$ (Papers~13--14);
\item $S_{\mathrm{eff}}$ is gauge-invariant on $\partial B$.
\end{enumerate}

At RG step $k$, the effective action on the coarse lattice
$\Lambda_k$ has the form
\[
S_k(V)=\beta_k\sum_p\bigl(1-\tfrac{1}{2}\tr\,V_p\bigr)+E_k(V),
\]
where:
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:} $\beta_k\ge 35$;
\item \textbf{Hessian:}
$\lambda_{\min}(H_k)\ge 0.689\cos\theta_*-C\theta_*^2>0$;
\item \textbf{Remainder:} $|E_k(X)|\le(4/\beta_k)^{2\alpha}
e^{-\kappa_k d(X)}$ with $\kappa_k\ge 0.83$;
\item \textbf{Gauge invariance:} $S_k$ is gauge-invariant.
\end{enumerate}

\label{thm:inductive}
If IH($k$) holds with $\beta_k\ge 100$, then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}=\beta_k-\delta\beta_k$, $\delta\beta_k>0$
(Paper~12);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_{\min}(H_k)$
(spectral monotonicity, Paper~9);
\item $|E_{k+1}|\le C(4/\beta_k)^2 e^{-\kappa_{k+1}d}$ with
$\kappa_{k+1}\ge\kappa_k$ (Papers~13--14);
\item gauge invariance preserved (Proposition~\ref{prop:equivariant}).
\end{enumerate}

\label{prop:bracket-inv}
The quadratic variation of $X_t$ is the same under
$\PP$ and $\QQ$:
\begin{equation}\label{eq:bracket-inv}
\langle X^i\rangle_t^{\QQ}
= \langle X^i\rangle_t^{\PP}
