\label{prop:var-bound}
The expected quadratic variation of $M_t$ under $\QQ$ is:
\begin{equation}\label{eq:EQV}
\E^{\QQ}[[M]_t]
= \frac{1}{2\nu}\int_0^t
\E^{\QQ}[|u(X_s,s)|^2]\,ds
= \frac{1}{2\nu\,\Vol}\int_0^t
\|u(\cdot,s)\|_{L^2}^2\,ds
\leq \frac{t\,\|u_0\|_{L^2}^2}{2\nu\,\Vol}.
\end{equation}

\label{prop:DM}
For $s\leq t$:
\begin{equation}\label{eq:DsM}
(D_s M_t)
= \frac{u(X_s,s)}{\sqrt{2\nu}}
+ \int_s^t \nabla u(X_r,r)\cdot dB_r^{\QQ},
\end{equation}
where $D_s = D_s^{B^{\QQ}}$ is the operator derivative at
time~$s$.

\label{thm:var-decomp}
\begin{equation}\label{eq:var-decomp}
\mathrm{Var}^{\QQ}(M_t)
= \underbrace{
  \frac{1}{\Vol}\int_0^t
  \|u(\cdot,s)\|_{L^2}^2\,ds
}_{\text{(I) direct, controlled by energy}}
\;+\;
\underbrace{
  \frac{2\nu}{\Vol}\int_0^t
  r\,\|\nabla u(\cdot,r)\|_{L^2}^2\,dr
}_{\text{(II) propagated, controlled by enstrophy}}.
\end{equation}
Both terms are bounded by $\|u_0\|_{L^2}^2/\Vol$:
\begin{equation}\label{eq:var-bound}
\mathrm{Var}^{\QQ}(M_t)
\leq \frac{2t\,\|u_0\|_{L^2}^2}{\Vol}.
\end{equation}

\label{cond:AID}
For a smooth NS solution $u(t)$ on $[0,T]$, define
the \emph{deformation angular variance} at shell~$r$:
\begin{equation}\label{eq:V-deform}
V_{\rm def}^{(r)}(t) := \sum_{j=1}^J
\left(\frac{\sum_{k\in\Omega_j\cap S_r}|k|^2\,
\E^{\QQ}[|\mathcal{A}_t|^2\mid X_t\in S_r\cap\Omega_j]}
{\sum_{k\in S_r}|k|^2\,
\E^{\QQ}[|\mathcal{A}_t|^2\mid X_t\in S_r]}
- \frac{1}{J}\right)^{\!\!2}.
\end{equation}
Condition AID states: $V_{\rm def}^{(r)}(t)$ is
\emph{monotonically non-increasing} in $r$ and satisfies
\begin{equation}\label{eq:AID}
V_{\rm def}^{(H)}(t) \leq \gamma^2\,V_{\rm def}^{(L)}(t)
\qquad\text{with $\gamma < 1$ uniform in $t\in[0,T]$.}
\end{equation}

\label{def:shell-var}
\begin{equation}\label{eq:V-shell}
V^{(r)}(t) := \sum_{j=1}^J
\bigl(\varepsilon_j^{(r)}(t)\bigr)^2,
\qquad
\varepsilon_j^{(r)} := p_j^{(r)} - 1/J,
\end{equation}
where $p_j^{(r)} = E_j^{(r)}/E^{(r)}$ is the sector
fraction at shell~$r$.

\label{thm:V-bound}
Under Condition~AID, the angular variance at shell~$r$
satisfies:
\begin{equation}\label{eq:V-bound}
V^{(r)}(t) \leq V_{\rm def}^{(r)}(t)
+ C_{\rm den}^{(r)}(t),
\end{equation}
where:
\begin{itemize}[nosep]
\item $V_{\rm def}^{(r)}$ is the deformation angular
  variance~\eqref{eq:V-deform};
\item $C_{\rm den}^{(r)}(t)$ is the \emph{density
  contribution}, bounded by:
  \begin{equation}\label{eq:Cden}
  C_{\rm den}^{(r)}(t) \leq
  \frac{C}{\nu^2\kappa_r^4}\cdot
  \frac{\Var^{\QQ}(M_t)}{t^2}
  \leq
  \frac{C\,\|u_0\|_{L^2}^4}{\nu^2\kappa_r^4\Vol^2},
  \end{equation}
  using $\Var^{\QQ}(M_t)\leq 2t\|u_0\|_{L^2}^2/\Vol$
  (Theorem~3.1 of v1).
\end{itemize}

\label{thm:ccen}
Let $u(t)$ be a smooth NS solution satisfying
Condition~AID with constant~$\gamma<1$.  Then there
exists $\kappa_H^*$ (depending on $u_0,\nu,\gamma$
but \textbf{not} on $\|u(t)\|_{H^2}$ for $t>0$)
such that for $\kappa_H>\kappa_H^*$:
\begin{equation}\label{eq:ccen}
c_{\rm cen}(u(t)) < 1
\qquad\text{for all } t\in(0,T^*].
\end{equation}

\label{def:alignment}
The \emph{alignment coefficient}:
\begin{equation}\label{eq:alignment}
\alpha_G := \frac{\Phi_G}{\sqrt{\sigma\,V^{(G)}}}
= \corr(\varepsilon,\varepsilon^{(G)})
\in [-1,1].
\end{equation}
Then $c_{\rm cen}<1$ iff
$\alpha_L\sqrt{V^{(L)}} > \alpha_H\sqrt{V^{(H)}}$.

\label{thm:ccen-PD}
Let $u(t)$ be a smooth NS solution on $\T^3$ with
$\nu>0$ and anisotropic initial data
($\mathcal{V}^{(L)}(0)>0$).  Define the
\emph{alignment ratio}:
