\label{def:heat}
Let $(X_t)_{t\in[0,T]}$ be a real-valued stochastic process. We say that $X$ satisfies a \emph{heat-type equation} with generator $\LL$ and clock $\theta$ if:
\begin{enumerate}[label=(\arabic*)]
\item For each $t > 0$, $X_t$ has a density $p(\cdot\,;\theta(t))$ with respect to Lebesgue measure, parameterized by a scalar function $\theta:[0,T]\to\mathbb{R}_+$ of bounded variation with $\theta(0) = 0$.
\item The density satisfies the forward equation
\begin{equation}\label{eq:forward}
\frac{\partial p}{\partial\theta}(x;\theta) = \LL^*p(x;\theta),
\end{equation}
where $\LL^*$ is the formal $L^2$-adjoint of a linear differential (or integro-differential) operator $\LL$.
\item For $\varphi$ in a suitable test function class $\mathcal{C}$ (at minimum $C^2_b(\mathbb{R})$ for second-order $\LL$), integration by parts is valid:
\begin{equation}\label{eq:ibp}
\int_\mathbb{R}\varphi(x)\,\LL^*p(x;\theta)\,dx = \int_\mathbb{R}\LL\varphi(x)\,p(x;\theta)\,dx.
\end{equation}
\end{enumerate}

\label{thm:expectation}
If $X$ satisfies a heat-type equation with generator $\LL$ and clock $\theta$, then for $\varphi\in\mathcal{C}$,
\begin{equation}\label{eq:expectformula}
\mathbb{E}[\varphi(X_t)] = \varphi(x_0) + \int_0^t \mathbb{E}[\LL\varphi(X_s)]\,d\theta(s),
\end{equation}
where $x_0 := \lim_{\theta\to 0} X_t$ in distribution (typically $X_0 = x_0$ a.s.).

\label{thm:Ito}
Suppose in addition to the hypotheses of Theorem~\ref{thm:expectation}, the process $X$ admits a stochastic integral representation
\[
X_t - X_0 = M_t + A_t,
\]
where $M_t$ is a martingale term (representable via a stochastic integral $\delta(\cdot)$) and $A_t$ is a drift/finite-variation term. Suppose a Clark--Ocone-type factorization holds for the process (as in the operator framework of \cite{FonI,FonII,FonIII}). Then
\begin{equation}\label{eq:generalIto}
\varphi(X_t) = \varphi(X_0) + \text{(martingale/stochastic integral term)} + \int_0^t \LL\varphi(X_s)\,d\theta(s).
\end{equation}
The correction term $\int_0^t \LL\varphi(X_s)\,d\theta(s)$ is completely determined by the generator $\LL$ and the clock $\theta$. The stochastic integral term is determined by the martingale representation.

