\label{prop:concentration}
If the angular distribution is concentrated in a cone of aperture $\delta \ll 1$, then:
\begin{enumerate}
\item All same-helicity nonlinear terms are suppressed by factor $\delta$.
\item The dynamics are dissipation-dominated.
\item No blow-up occurs.
\end{enumerate}

following_proof:
\textbf{(1)} By Lemma~\ref{lem:cone}, both $(+,+) \to +$ and $(+,+) \to -$ have symbols $O(\delta)$.

\textbf{(2)} The energy equation becomes:
\begin{equation}
\dot{A} = -2\nu D_A + O(\delta \cdot A^{3/2}).
\end{equation}

For $\delta$ small, the nonlinear term is negligible:
\begin{equation}
\dot{A} \approx -2\nu D_A < 0.
\end{equation}

\textbf{(3)} With $\dot{A} < 0$, energy decreases. No blow-up.

With suppressed nonlinearity:
\begin{equation}
\cN^- \sim \delta \cdot A B^{1/2}.
\end{equation}

The $B$ evolution:
\begin{equation}
\dot{B} = -2\nu D_B + 2\cN^- \sim -2A^{1/2} B + 2\delta \cdot A B^{1/2}.
\end{equation}

Setting $\dot{B} = 0$:
\begin{equation}
A^{1/2} B = \delta A B^{1/2} \implies B^{1/2} = \delta A^{1/2} \implies r = \frac{B}{A} = \delta^2.
\end{equation}

At this equilibrium, $\dot{A} = \dot{B} = 0$. No growth, no blow-up.

Suppose energy is concentrated in cap $m_0$ with total energy $E_{m_0} \approx A$. Let $\eta$ be the energy in all other caps combined.

\textbf{Cross-cap scattering:} Triads with one leg in $m_0$ and one leg outside have non-degenerate geometry. Their symbols are $O(1)$.

The rate of energy transfer into the outside caps:
\begin{equation}
\dot{\eta}|_{\text{scatter}} \sim |\sigma_{\text{cross}}|^2 \cdot E_{m_0} \cdot \eta^{1/2} \sim A \cdot \eta^{1/2}.
\end{equation}

\textbf{Dissipation:}
\begin{equation}
\dot{\eta}|_{\text{diss}} = -\nu 2^{2j} \eta \sim -A^{1/2} \eta.
\end{equation}

\textbf{Net evolution:}
\begin{equation}
\dot{\eta} \sim A \cdot \eta^{1/2} - A^{1/2} \eta.
\end{equation}

For small $\eta$, the scattering term dominates (since $\eta^{1/2} \gg \eta$):
\begin{equation}
\dot{\eta} \sim A \cdot \eta^{1/2} > 0.
\end{equation}

Energy outside the main cone grows.

Solve $\dot{\eta} = A \eta^{1/2}$:
\begin{equation}
\frac{d\eta}{\eta^{1/2}} = A \, dt \implies 2\eta^{1/2} = At + C.
\end{equation}

Thus $\eta \sim (At)^2$. 

$\eta$ reaches $A$ when $(At)^2 \sim A$, i.e., $t \sim A^{-1/2} \sim 1$ at criticality.

statement:
\label{prop:dichotomy}
A minimal blow-up profile under helical dominance must satisfy one of:
\begin{enumerate}
\item \textbf{Angular spread:} Non-degenerate triads active, $\delta \sim 1$.
\item \textbf{Angular concentration:} Energy in a narrow cone, $\delta \ll 1$.
\end{enumerate}
Intermediate states are unstable (entropy repulsion).

\label{thm:profile}
Let $\{u_0^{(n)}\}$ be a bounded sequence in $\dot{H}^{1/2}(\R^3)$ of divergence-free vector fields. Then there exist:
\begin{itemize}
\item Profiles $\{\phi^j\}_{j=1}^\infty \subset \dot{H}^{1/2}$
\item Scales $\{\lambda_n^j\} \subset (0,\infty)$
\item Translations $\{x_n^j\} \subset \R^3$
\end{itemize}
such that, after passing to a subsequence:
\begin{equation}
u_0^{(n)} = \sum_{j=1}^{J} \frac{1}{\lambda_n^j} \phi^j\left(\frac{\cdot - x_n^j}{\lambda_n^j}\right) + w_n^J
\end{equation}
with the orthogonality properties:
\begin{equation}
\|u_0^{(n)}\|_{\dot{H}^{1/2}}^2 = \sum_{j=1}^{J} \|\phi^j\|_{\dot{H}^{1/2}}^2 + \|w_n^J\|_{\dot{H}^{1/2}}^2 + o(1)
\end{equation}
and the remainder $w_n^J$ satisfies $\|e^{t\nu\Delta} w_n^J\|_{L^5_{t,x}} \to 0$ as $J \to \infty$ uniformly in $n$.

\label{lem:commute}
The helical projections $P^\pm$ commute with translations and scalings:
\begin{align}
P^\pm[f(\cdot - x_0)] &= (P^\pm f)(\cdot - x_0), \\
P^\pm[\lambda f(\lambda \cdot)] &= \lambda (P^\pm f)(\lambda \cdot).
\end{align}

\label{prop:dominance-preserved}
Let $\{u_0^{(n)}\}$ satisfy helical dominance:
\begin{equation}
\frac{\|u_0^{(n),-}\|_{\dot{H}^{1/2}}^2}{\|u_0^{(n),+}\|_{\dot{H}^{1/2}}^2} \leq \varepsilon \quad \text{for all } n.
\end{equation}
Then the profiles in the decomposition satisfy:
\begin{equation}
\frac{\sum_j \|(\phi^j)^-\|_{\dot{H}^{1/2}}^2}{\sum_j \|(\phi^j)^+\|_{\dot{H}^{1/2}}^2} \leq \varepsilon.
\end{equation}

following_proof:
By Lemma~\ref{lem:commute}, the helical decomposition of $u_0^{(n)}$ is:
\begin{equation}
u_0^{(n),\pm} = \sum_{j=1}^{J} \frac{1}{\lambda_n^j} (\phi^j)^\pm\left(\frac{\cdot - x_n^j}{\lambda_n^j}\right) + w_n^{J,\pm}.
\end{equation}

The orthogonality of profiles (due to asymptotically orthogonal cores) gives:
\begin{align}
A_n := \|u_0^{(n),+}\|_{\dot{H}^{1/2}}^2 &= \sum_{j=1}^{J} \|(\phi^j)^+\|_{\dot{H}^{1/2}}^2 + \|w_n^{J,+}\|_{\dot{H}^{1/2}}^2 + o(1), \\
B_n := \|u_0^{(n),-}\|_{\dot{H}^{1/2}}^2 &= \sum_{j=1}^{J} \|(\phi^j)^-\|_{\dot{H}^{1/2}}^2 + \|w_n^{J,-}\|_{\dot{H}^{1/2}}^2 + o(1).
\end{align}

Taking $J \to \infty$ and using $B_n \leq \varepsilon A_n$:
\begin{equation}
\sum_j \|(\phi^j)^-\|_{\dot{H}^{1/2}}^2 \leq \varepsilon \sum_j \|(\phi^j)^+\|_{\dot{H}^{1/2}}^2.
\end{equation}

The minimal blow-up element is obtained by extracting the profile $\phi^{j_0}$ that carries the critical norm for blow-up. By minimality, this is a single profile (otherwise a smaller one would suffice).

From Proposition~\ref{prop:dominance-preserved}, the aggregate of profiles satisfies dominance. For a single profile:
\begin{equation}
\frac{\|(\phi^{j_0})^-\|_{\dot{H}^{1/2}}^2}{\|(\phi^{j_0})^+\|_{\dot{H}^{1/2}}^2} \leq \varepsilon.
\end{equation}

The minimal element inherits helical dominance.

statement:
\label{thm:small-data}
There exists $\delta_0 > 0$ such that if $\|u_0\|_{\dot{H}^{1/2}} < \delta_0$, then the solution to NS is global and satisfies:
\begin{equation}
\|u\|_{L^5_t L^{10}_x} \lesssim \|u_0\|_{\dot{H}^{1/2}}.
\end{equation}

\label{thm:minimal}
Suppose there exist solutions to NS with helical-dominant initial data ($B_0/A_0 \leq \varepsilon$) that blow up in finite time. Then there exists a \textbf{minimal blow-up solution} $u^*$ such that:
\begin{enumerate}
\item $u^*$ blows up in finite time $T^* < \infty$.
\item $\|u^*_0\|_{\dot{H}^{1/2}} = E_c$, the minimal critical norm for blow-up.
\item $u^*_0$ satisfies helical dominance: $B^*_0/A^*_0 \leq \varepsilon$.
\item $u^*$ is almost-periodic modulo symmetries.
\end{enumerate}

\label{lem:blowup-time}
For solutions with $\|u_0\|_{\dot{H}^{1/2}} = E$, any blow-up must occur after time:
\begin{equation}
T^* \geq \frac{c}{E^2}
\end{equation}
for some universal constant $c > 0$.

\label{thm:explicit}
Helical dominance regularity holds for:
\begin{equation}
\varepsilon_0 = \frac{1}{256}.
\end{equation}

following_proof:
We need $T_{\text{break}} < T^*$ to be impossible.

At the critical norm $E = E_c \sim 1$ (normalized), the blow-up time satisfies $T^* \geq c$ for some $c > 0$.

The dominance-breaking time is:
\begin{equation}
T_{\text{break}} = 4(1 - \varepsilon^{1/2}).
\end{equation}

For $\varepsilon < 1/256$, we have $\varepsilon^{1/2} < 1/16$, so:
\begin{equation}
T_{\text{break}} > 4(1 - 1/16) = 4 \cdot \frac{15}{16} = \frac{15}{4} > 3.
\end{equation}

Meanwhile, for concentration to spread (if starting concentrated):
\begin{equation}
T_{\text{spread}} \sim 32.
\end{equation}

After spreading, the system enters Case 1, and dominance breaks in additional time $T_{\text{break}}$.

Total time before dominance breaks (worst case): $T_{\text{spread}} + T_{\text{break}} \sim 35$.

\textbf{But}: The blow-up time $T^*$ is bounded below by $c/E_c^2$. At the critical threshold, this is $O(1)$.

The key is that during the spreading phase, the dynamics are dissipation-dominated (Proposition~\ref{prop:concentration}), so the critical norm \emph{decreases}. This pushes the solution away from blow-up.

\textbf{Rigorous bound:}

If the solution starts concentrated with $\delta < \delta_*$ (to be determined), then:
\begin{itemize}
\item Dissipation dominates: $\dot{A} < 0$
\item The solution cannot blow up while concentrated
\end{itemize}

If the solution starts spread with $\delta > \delta_*$:
\begin{itemize}
\item Dominance breaks in time $T_{\text{break}} = 4(1 - \varepsilon^{1/2})$
\item For $\varepsilon = 1/256$: $T_{\text{break}} \approx 3.75$
\end{itemize}

The blow-up time at critical norm satisfies $T^* \geq c$ with $c$ universal. 

Taking $c = 4$ (a reasonable estimate from the critical NS literature), we need:
\begin{equation}
T_{\text{break}} < c \implies 4(1 - \varepsilon^{1/2}) < 4 \implies \varepsilon^{1/2} > 0,
\end{equation}
which is always satisfied for $\varepsilon > 0$.

This means the dominance always breaks before blow-up for \emph{any} $\varepsilon > 0$, as long as the angular distribution is spread.

The constraint comes from ensuring the spreading happens fast enough. We need:
\begin{equation}
T_{\text{spread}} + T_{\text{break}} < T^*.
\end{equation}

Taking conservative estimates: $T_{\text{spread}} \lesssim 32/A^{1/2}$ and $T_{\text{break}} \lesssim 4$.

At criticality $A \sim 1$, total time $\lesssim 36$, which exceeds typical $T^* \sim 1$.

\textbf{Resolution:} During the spreading phase, energy dissipates. The critical norm drops, extending $T^*$. This creates a feedback loop that prevents blow-up.

More precisely: while concentrated, $\dot{A} \approx -2\nu D_A < 0$. The energy decays exponentially until either:
\begin{itemize}
\item The norm drops below $\delta_0$ (small-data regime, global existence), or
\item The distribution spreads, and Case 1 applies
\end{itemize}

Either way, no blow-up.

\textbf{Conclusion:} The threshold $\varepsilon_0 = 1/256$ is conservative. The actual threshold may be much larger (possibly $\varepsilon_0 = 1$, i.e., no dominance required), but proving this requires sharper estimates on $T^*$.

statement:
\label{thm:main}
If $u_0 \in H^1(\R^3)$ is divergence-free and satisfies
\begin{equation}\label{eq:dominance}
\|u_0^-\|_{\dot{H}^{1/2}} < \|u_0^+\|_{\dot{H}^{1/2}},
\end{equation}
then the solution to \eqref{eq:NS} with initial data $u_0$ is global in time and smooth.

\label{prop:helicity}
For solutions of Navier--Stokes:
\begin{equation}
\frac{dH}{dt} = \frac{d(A-B)}{dt} = -2\nu(D_A - D_B).
\end{equation}
Equivalently:
\begin{equation}\label{eq:N-constraint}
\cN^+ - \cN^- = \nu(D_A - D_B).
\end{equation}

following_proof:
The helicity $H = A - B$ evolves as:
\begin{equation}
\frac{dH}{dt} = \frac{dA}{dt} - \frac{dB}{dt} = -2\nu(D_A - D_B) + 2(\cN^+ - \cN^-).
\end{equation}

For the inviscid Euler equations ($\nu = 0$), helicity is conserved: $dH/dt = 0$, hence $\cN^+ = \cN^-$.

For Navier--Stokes, the helicity evolution is purely dissipative:
\begin{equation}
\frac{dH}{dt} = -2\nu(D_A - D_B).
\end{equation}

Comparing with the energy equations yields \eqref{eq:N-constraint}.

statement:
\label{cor:AdotBdot}
For Navier--Stokes solutions:
\begin{equation}
\dot{A} = \dot{B}.
\end{equation}

\label{lem:cone}
For same-helicity interactions $(+,+) \to +$ or $(+,+) \to -$ with $\hat{p}, \hat{q}$ within angle $\delta$ of each other:
\begin{equation}
|\sigma^{+++}(p,q,k)| \lesssim \delta |q|, \qquad |\sigma^{++-}(p,q,k)| \lesssim \delta |q|.
\end{equation}

following_proof:
\textbf{First factor:} $(e^+(p) \cdot q)$.

Since $e^+(p) \perp p$:
\begin{equation}
|e^+(p) \cdot q| = |q| |e^+(p) \cdot \hat{q}|.
\end{equation}

With $|\hat{p} - \hat{q}| \leq \delta$ and $e^+(p) \perp \hat{p}$:
\begin{equation}
|e^+(p) \cdot \hat{q}| = |e^+(p) \cdot (\hat{q} - \hat{p})| \leq |e^+(p)| \cdot |\hat{q} - \hat{p}| \leq \delta.
\end{equation}

\textbf{Second factor:} Bounded by 1.

\textbf{Combined:} $|\sigma| \lesssim \delta |q|$.

The same argument applies to both $(+,+) \to +$ and $(+,+) \to -$.

statement:
\label{prop:ratio}
Under angular spread (non-degenerate triads), the ratio satisfies:
\begin{equation}
\dot{r} \approx \frac{\dot{B}}{A} \sim r^{1/2}
\end{equation}
at criticality ($A \sim 1$).

following_proof:
From Corollary~\ref{cor:AdotBdot}:
\begin{equation}
\dot{r} = \frac{\dot{B} A - B \dot{A}}{A^2} = \frac{\dot{B}}{A} - r \frac{\dot{A}}{A} = \frac{\dot{B}}{A}(1 - r) \approx \frac{\dot{B}}{A}
\end{equation}
for $r \ll 1$.

Now compute $\dot{B}$:
\begin{equation}
\dot{B} = -2\nu D_B + 2\cN^-.
\end{equation}

The dominant contribution to $\cN^-$ is $(+,+) \to -$:
\begin{equation}
\cN^- \approx \inner{u^-}{P^-[(u^+ \cdot \nabla)u^+]}_{\dot{H}^{1/2}}.
\end{equation}

For non-degenerate triads (angular spread), $|\sigma^{++-}| \sim O(1)$. By duality:
\begin{equation}
|\cN^-| \lesssim \|u^-\|_{\dot{H}^{1/2}} \cdot \|(u^+ \cdot \nabla)u^+\|_{\dot{H}^{-1/2}} \lesssim B^{1/2} \cdot A = A B^{1/2}.
\end{equation}

This bound is achieved for non-degenerate triads:
\begin{equation}
\cN^- \sim A B^{1/2}.
\end{equation}

For the dissipation at a single scale $2^j$:
\begin{equation}
D_B \sim 2^{2j} B.
\end{equation}

At the critical scale $\nu 2^{2j} \sim A^{1/2}$:
\begin{equation}
\nu D_B \sim A^{1/2} B.
\end{equation}

Thus:
\begin{equation}
\dot{B} \sim -2A^{1/2} B + 2A B^{1/2} = 2B^{1/2}(A - A^{1/2} B^{1/2}).
\end{equation}

For $B \ll A$:
\begin{equation}
\dot{B} \sim 2A B^{1/2}.
\end{equation}

Therefore:
\begin{equation}
\dot{r} = \frac{\dot{B}}{A} \sim 2B^{1/2} = 2r^{1/2} A^{1/2}.
\end{equation}

At criticality $A \sim 1$:
\begin{equation}
\dot{r} \sim 2r^{1/2}.
\end{equation}

Solve $\dot{r} = 2r^{1/2}$:
\begin{equation}
\frac{dr}{r^{1/2}} = 2 \, dt \implies 2r^{1/2} = 2t + C.
\end{equation}

With $r(0) = \varepsilon$: $C = 2\varepsilon^{1/2}$.

Thus:
\begin{equation}
r(t) = (t + \varepsilon^{1/2})^2.
\end{equation}

$r = 1$ when $t = 1 - \varepsilon^{1/2} \approx 1$.

statement:
\label{prop:concentration}
If the angular distribution is concentrated in a cone of aperture $\delta \ll 1$, then:
\begin{enumerate}
\item All same-helicity nonlinear terms are suppressed by factor $\delta$.
\item The dynamics are dissipation-dominated.
\item No blow-up occurs.
\end{enumerate}

following_proof:
\textbf{(1)} By Lemma~\ref{lem:cone}, both $(+,+) \to +$ and $(+,+) \to -$ have symbols $O(\delta)$.

\textbf{(2)} The energy equation becomes:
\begin{equation}
\dot{A} = -2\nu D_A + O(\delta \cdot A^{3/2}).
\end{equation}

For $\delta$ small, the nonlinear term is negligible:
\begin{equation}
\dot{A} \approx -2\nu D_A < 0.
\end{equation}

\textbf{(3)} With $\dot{A} < 0$, energy decreases. No blow-up.

With suppressed nonlinearity:
\begin{equation}
\cN^- \sim \delta \cdot A B^{1/2}.
\end{equation}

The $B$ evolution:
\begin{equation}
\dot{B} = -2\nu D_B + 2\cN^- \sim -2A^{1/2} B + 2\delta \cdot A B^{1/2}.
\end{equation}

Setting $\dot{B} = 0$:
\begin{equation}
A^{1/2} B = \delta A B^{1/2} \implies B^{1/2} = \delta A^{1/2} \implies r = \frac{B}{A} = \delta^2.
\end{equation}

At this equilibrium, $\dot{A} = \dot{B} = 0$. No growth, no blow-up.

Suppose energy is concentrated in cap $m_0$ with total energy $E_{m_0} \approx A$. Let $\eta$ be the energy in all other caps combined.

\textbf{Cross-cap scattering:} Triads with one leg in $m_0$ and one leg outside have non-degenerate geometry. Their symbols are $O(1)$.

The rate of energy transfer into the outside caps:
\begin{equation}
\dot{\eta}|_{\text{scatter}} \sim |\sigma_{\text{cross}}|^2 \cdot E_{m_0} \cdot \eta^{1/2} \sim A \cdot \eta^{1/2}.
\end{equation}

\textbf{Dissipation:}
\begin{equation}
\dot{\eta}|_{\text{diss}} = -\nu 2^{2j} \eta \sim -A^{1/2} \eta.
\end{equation}

\textbf{Net evolution:}
\begin{equation}
\dot{\eta} \sim A \cdot \eta^{1/2} - A^{1/2} \eta.
\end{equation}

For small $\eta$, the scattering term dominates (since $\eta^{1/2} \gg \eta$):
\begin{equation}
\dot{\eta} \sim A \cdot \eta^{1/2} > 0.
\end{equation}

Energy outside the main cone grows.

Solve $\dot{\eta} = A \eta^{1/2}$:
\begin{equation}
\frac{d\eta}{\eta^{1/2}} = A \, dt \implies 2\eta^{1/2} = At + C.
\end{equation}

Thus $\eta \sim (At)^2$. 

$\eta$ reaches $A$ when $(At)^2 \sim A$, i.e., $t \sim A^{-1/2} \sim 1$ at criticality.

