\label{prop:Lambda}
The matching scale satisfies
\begin{equation}\label{eq:ell-star}
\frac{1}{\ell_*}=\frac{1}{a}\cdot 2^{-k_*}
=\frac{1}{a}\cdot\exp\bigl(-k_*\log 2\bigr)
=\frac{1}{a}\cdot\exp\Bigl(-\frac{(\beta-\beta_*)\log 2}{\delta\beta}\Bigr)
=\Lam\cdot e^{\beta_*/(8b_0)},
\end{equation}
where $\Lam=(1/a)\exp(-\beta/(8b_0))$ and
$e^{\beta_*/(8b_0)}=e^{35\cdot 2.692}=e^{94.2}$ is a
($\beta$-independent) constant.

\label{thm:mgap}
For $\SU(2)$ Yang--Mills with Wilson action at coupling $\beta$ on
a $d$-dimensional lattice, the mass gap satisfies
\begin{equation}\label{eq:mgap}
m\ge-\frac{1}{\ell_*}\cdot(d-1)\log\bigl\langle\tfrac{1}{2}\tr\,U_p
\bigr\rangle_\beta,
\end{equation}
where $\langle\cdot\rangle_\beta$ denotes the expectation in the
Gibbs measure and the factor $(d-1)=3$ counts the number of
plaquette orientations involving the temporal direction.

\label{cor:mgap}
At the matching scale:
\begin{equation}\label{eq:mgap-quant}
m\ge\frac{3\times 0.0290}{\ell_*}=\frac{0.087}{\ell_*}
=0.087\cdot\Lam\cdot e^{94.2}.
\end{equation}
In the continuum limit $(a\to 0,\;\beta\to\infty)$:
\begin{equation}\label{eq:mgap-continuum}
m_{\mathrm{phys}}\ge c_0\cdot\Lam,\qquad c_0=0.087\cdot e^{94.2}>0.
\end{equation}
This is a \emph{positive, lattice-spacing-independent lower bound}.

\label{thm:single}
For all $\beta\in(0,\infty)$ and all staple sums $W_\ell\in M_2(\mathbb{C})$, the spectral gap of the heat-bath kernel associated with~\eqref{eq:conditional} satisfies
\begin{equation}
\gamma_\ell(\beta,W_\ell) \;\ge\; \tfrac{3}{4}.
\end{equation}

\label{prop:multi}
Let $\Lambda_L$ be a spatial block of side length $L$ with gauge-fixed tree. Suppose there exists $L_0$ and $g_0>0$ such that
\begin{equation}\label{eq:block_condition}
\inf_{\omega,\,\beta\in[2.3,\,5.0]} \gamma(\Lambda_{L_0},\omega,\beta) \;\ge\; g_0.
\end{equation}
Then $m(\beta)>0$ for $\beta\in[2.3,\,5.0]$, and consequently $m(\beta)>0$ for all $\beta>0$.

The surface series is Borel summable with positive terms. The Borel sum
\begin{equation}
F(z) = \int_0^\infty B(tz)\,e^{-t}\,dt
\end{equation}
converges for all $z\in\mathbb{C}$ and agrees with the partition function for $z=\alpha_{1/2}(\beta)$.

\label{lem:single_link}
The single-link conditional of the Wilson measure at coupling 
$\beta$ satisfies $\LSI(\rho_\ell)$ with
\begin{equation}\label{eq:rho_ell}
  \rho_\ell(\beta) \;\geq\; 
  \frac{N^2-1}{2N}\;\exp\!\bigl(-4(d-1)\beta\bigr).
\end{equation}

\label{lem:dob_coeff}
For the Wilson measure at coupling~$\beta$:
\begin{equation}\label{eq:dob_entry}
  C_{\ell\ell'} \leq 
  \begin{cases}
    1 - e^{-2\beta} & \text{if } \ell \sim \ell' 
    \text{ (plaquette-neighbors)}, \\
    0 & \text{otherwise}.
  \end{cases}
\end{equation}

\label{prop:threshold}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{eq:threshold}
  6(d-1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
Then for all $\beta < \beta_c$, the Wilson measure on any finite 
lattice $\Lambda$ satisfies $\LSI(\rho_\Lambda)$ with
\begin{equation}\label{eq:global_gap}
  \rho_\Lambda \;\geq\; 
  \frac{N^2-1}{2N}\;e^{-4(d-1)\beta}\;
  \bigl(1 - 6(d-1)(1-e^{-2\beta})\bigr) \;>\; 0,
\end{equation}
uniformly in $|\Lambda|$.

\label{def:kstar}
Define the \emph{Dobrushin scale}
\[
  k_* = \left\lceil \frac{\log(\beta/\beta_c)}{d\log L} 
  \right\rceil + 1,
\]
where $\beta_c = \beta_c(d)$ is the threshold from 
Proposition~\ref{prop:threshold}.

\label{lem:perturbed_link}
The single-link conditional of $\mu_{k_*}$ satisfies 
$\LSI(\rho_\ell^*)$ with
\[
  \rho_\ell^* \;\geq\; 
  \rho_{\Haar}\;\exp\!\bigl(-4(d-1)\beta_{\mathrm{eff}} 
  - 2\varepsilon(\beta)\bigr),
\]
where $\varepsilon(\beta)$ is Balaban's smallness parameter.

\label{lem:perturbed_dob}
The Dobrushin matrix of $\mu_{k_*}$ satisfies
\begin{equation}\label{eq:perturbed_dob}
  \|C^*\|_\infty \;\leq\; 
  6(d-1)\bigl(1 - e^{-2\beta_{\mathrm{eff}} - 2\varepsilon_1}\bigr) 
  \;+\; c_d\,\varepsilon(\beta),
\end{equation}
where $\varepsilon_1 = \sup_{\ell\sim\ell'}\sum_{X\ni\ell,\ell'}\sup|a_k|$ 
and $c_d$ is a dimension-dependent constant.

\label{prop:combined}
There exists $\beta_0 = \beta_0(N,d)$ such that for $\beta > \beta_0$, 
the effective measure $\mu_{k_*}$ on the coarse lattice 
$\Lambda_{k_*}$ satisfies $\LSI(\rho^*)$ with
\begin{equation}\label{eq:rho_star}
  \rho^* \;\geq\; \rho_\ell^*\,(1 - \|C^*\|_\infty) \;>\; 0,
\end{equation}
uniformly in~$|\Lambda|$.

\label{cor:continuum}
Under Assumption~\ref{ass:balaban}, along the asymptotic freedom 
trajectory $\beta(a) = (2Nb_0)^{-1}\log(1/(a\Lambda_{\mathrm{QCD}}))$ 
with $b_0 = 11/(48\pi^2)$:
\[
  m_{\mathrm{phys}}(a) \;=\; \frac{m \cdot a}{a} \;\geq\; 
  \frac{c}{a\,[\log(1/(a\Lambda_{\mathrm{QCD}}))]^{1/d}} 
  \;\longrightarrow\; +\infty
  \quad \text{as } a \to 0.
\]

