\label{def:quadform}
For $\varphi\in C^2_b(\mathbb{R})$ and $X_t\in\Dom(D)$, define the \emph{noise quadratic form} at time $t$ by
\begin{equation}\label{eq:quadform}
Q_t(\varphi) := \inner{D\varphi(X_t)}{\Pi D\varphi(X_t)}_\HH.
\end{equation}
By the chain rule, $D\varphi(X_t) = \varphi'(X_t)DX_t$, so
\begin{equation}\label{eq:quadformexpanded}
Q_t(\varphi) = |\varphi'(X_t)|^2\inner{DX_t}{\Pi DX_t}_\HH = |\varphi'(X_t)|^2\,\Gamma^X(t),
\end{equation}
where $\Gamma^X(t) := \norm{\Pi DX_t}_\HH^2$ is the energy function (using orthogonality of $\Pi$, as in \cite[Lemma~3.3]{FonIII}).

\label{cor:gaussian}
Let $X$ be a centered Gaussian process admitting a $(D,\delta,\Pi)$ triple with deterministic Malliavin derivative $DX_t = K(t,\cdot)$. Then the unique generator compatible with the operator factorization is
\begin{equation}\label{eq:gaussgenerator}
\LL = \frac{1}{2}\partial_{xx},
\end{equation}
and the unique clock is $\theta(t) = \Gamma^X(t) = \mathbb{E}[X_t^2]$.

\label{thm:clock}
Let $X$ be a centered process with finite variance ($\mathbb{E}[X_t^2] < \infty$ for all $t$) satisfying the hypotheses of Theorem~\ref{thm:generator}, with deterministic $DX_t$ and second-order generator $\LL = \frac{c}{2}\partial_{xx} + \text{lower order}$. Then the clock $\theta$ in the It\^o formula~\eqref{eq:abstractIto} satisfies
\begin{equation}\label{eq:clockidentity}
\theta(t) = \Gamma^X(t)/c, \qquad \Gamma^X(t) := \norm{\Pi DX_t}_\HH^2 = \mathbb{E}[X_t^2],
\end{equation}
where $c$ is the leading coefficient of $\LL$. With the standard normalization $\LL = \frac{1}{2}\partial_{xx}$ (so $c = 1$), $\theta = \Gamma^X$.

\label{thm:correspondence}
Under Definition~\ref{def:heat},
\begin{equation}\label{eq:expectformula}
\mathbb{E}[\varphi(X_t)] = \varphi(x_0) + \int_0^t \mathbb{E}[\LL\varphi(X_s)]\,d\theta(s).
\end{equation}

\label{thm:fullIto}
If $X$ satisfies a heat-type equation with generator $\LL$ and clock $\theta$, and admits a $(D,\delta,\Pi)$ triple with factorization $(\Id-\mathbb{E}) = \delta\Pi D$, then
\begin{equation}\label{eq:fullIto}
\varphi(X_t) = \varphi(X_0) + \delta(\Pi D\varphi(X)\cdot\mathbf{1}_{[0,t]}) + \int_0^t \LL\varphi(X_s)\,d\theta(s).
\end{equation}
The correction is uniquely determined by $(\LL, \theta)$ (Theorem~\ref{thm:generator}), and both $\LL$ and $\theta$ are determined by the noise geometry (Corollary~\ref{cor:gaussian} for Gaussian processes, Theorem~\ref{thm:clock} for the clock).

