$\sum_j p_j\,\dot r_j|_v\,\log(1/p_j)$.

following_proof:
The $p$-and-$f$ contributions (Lemma~\ref{lem:Mdot} with $t=0,1$)
give:
\begin{equation}
\dot\Phi\big|_v\big|_{p,f}
= 2\nu\frac{D}{E}\bigl[\Phi^2 - M(2)/\cS + W\bigr]
\end{equation}
(as computed previously via the quotient rule).
Adding $\mathcal{R}/\cS$ from~\eqref{eq:correction}:
\begin{align}
\dot\Phi\big|_v
&= 2\nu\frac{D}{E}\bigl[\Phi^2 - M(2)/\cS + W\bigr]
+ 2\nu\frac{D}{E}\bigl[(M(2)-H)/\cS - \rho\,N_s/\cS\bigr]\\
&= 2\nu\frac{D}{E}\bigl[\Phi^2 - \Phi + W - \rho\,N_s/\cS\bigr]\\
&= 2\nu\frac{D}{E}\bigl[\Phi(\Phi-1) + W - \rho\,N_s/\cS\bigr].
\qquad\qed
\end{align}
\renewcommand{\qedsymbol}{}

statement:
\label{thm:logistic}
The viscous evolution of $W = (V_2-1)/\cS$ satisfies:
\begin{equation}\label{eq:logistic}
\dot W\big|_v \leq 2\nu\frac{D}{E}\cdot W(\Phi - 2 - W\cS).
\end{equation}
The term $-W\cS$ provides quadratic self-damping beyond the linear term.

\label{thm:injection}
The nonlinear contribution to $\dot r_j$ satisfies, in
$\tau$-time ($d\tau = \nu(D/E)\,dt$):
\begin{equation}\label{eq:injection}
\left|\frac{dr_j}{d\tau}\bigg|_{\rm NL}\right| \leq C\delta r_j,
\end{equation}
where $C$ depends on $J$ but not on $E$.

\label{thm:riccati}
In $\tau$-time, $R(t) = \max_j r_j(t)$ satisfies:
\begin{equation}\label{eq:riccati}
\frac{dR}{d\tau} \leq -2R\bigl[\rho(s_{j^*}-1)-(R-1)\bigr] + C\delta R,
\end{equation}
where $\rho = GE/D^2 \geq 1$ and $j^* = \arg\max_j r_j$.
Under the spectral hierarchy monotonicity $s_{j^*}\geq R$
(Gap~2, Section~\ref{sec:gaps}):
\begin{equation}\label{eq:riccati-damped}
\frac{dR}{d\tau} \leq -2R(\rho-1)(R-1) + C\delta R.
\end{equation}

\label{thm:Rbound}
Conditional on the spectral hierarchy monotonicity $s_{j^*}\geq R$
and on $\rho \geq \rho_0 > 1$ for some uniform $\rho_0$:
for any smooth NS solution on $\T^3$:
\begin{equation}\label{eq:Rbound}
R(t) \leq \max\!\left(R(0),\; 1 + \frac{C\pi/2}{2(\rho_0-1)}\right)
=: C_H < \infty \quad\text{for all } t \geq 0.
\end{equation}

For $\hat n\in S^2$, aperture $\delta\in(0,\pi/2)$, scale $N\geq 1$:
\begin{equation}
K_N^\delta = \{k\in\Z^3 : N\leq|k|\leq 2N,\;\angle(\hat k,\hat n)\leq\delta\}.
\end{equation}

\label{thm:bernstein-single}
If $u_N$ has Fourier support in $K_N^\delta$:
\begin{equation}\label{eq:bernstein-single}
\|u_N\|_{L^\infty} \leq C\delta\,\|u_N\|_{\Hdot{3/2}}.
\end{equation}
The bound is sharp.

\label{prop:incomp}
For divergence-free $u_N$ with Fourier support in $K_N^\delta$,
the axial component $u_N^{\hat n} = (u_N\cdot\hat n)\hat n$ satisfies:
\begin{equation}
\|u_N^{\hat n}\|_{L^\infty} \leq C\delta^2\,\|u_N\|_{\Hdot{3/2}}.
\end{equation}

\label{thm:bernstein-multi}
For any $\epsilon > 0$ and smooth divergence-free $u$ on $\T^3$
with Fourier support in a cone of aperture $\delta$:
\begin{equation}\label{eq:bernstein-multi}
\|u\|_{L^\infty} \leq C_\epsilon\delta\,\|u\|_{\Hdot{3/2+\epsilon}}.
\end{equation}

\label{thm:enstrophy-max}
Let $u(t)$ be a smooth NS solution on $[t_0,T)$ with
$\delta(u(t)) \leq \theta_0$ throughout.  Then for any fixed
$\epsilon > 0$:
\begin{equation}\label{eq:Dstar}
D(t) \leq D_*(\theta_0,\nu,\epsilon) := \max\!\left(D(t_0),\;
\frac{\nu^2}{C_\epsilon^2\theta_0^2}\right) \quad\text{for all } t\in[t_0,T),
\end{equation}
where $C_\epsilon$ depends on $\epsilon$ and $J$ but not on $u$.

\label{lem:fourier-split}
For any smooth NS solution on $\T^3$:
\begin{equation}\label{eq:fourier-split}
E(t) \to \infty \implies \frac{D(t)}{E(t)} \to \infty.
\end{equation}

\label{thm:dichotomy}
If blow-up occurs at $T^* < \infty$, then necessarily:
\begin{equation}\label{eq:dichotomy}
\int_0^{T^*}\frac{D(t)}{E(t)}\,dt = \infty.
\end{equation}

\label{lem:entropy-concentration}
If $\cS(u(t)) \leq \epsilon/\log J$, then $\delta(u(t)) \leq 2\alpha$,
where $\alpha = \diam(\Omega_j) = O(J^{-1/2})$ is the sector aperture.

\label{thm:main-crossentropy}
For any smooth NS solution on $\T^3$:
\begin{equation}
H(q,p)(t) \leq C_H\,\cS(t) \quad\text{for all }t\geq 0,
\end{equation}
where $C_H = \max\!\bigl(R_0,\;1 + C\pi/2\bigr)$ with $R_0 = \max_j r_j(0)$.
No spread condition, sub-criticality condition, or profile decomposition
is required.

\label{thm:main-gronwall}
Under the hypotheses of Theorem~\ref{thm:main-crossentropy}:
\begin{equation}
\cS(u(t)) \geq \cS(u_0)\exp\!\left(
-C_H C_{\rm prop}\,C_\cB\,\frac{\norm{u_0}_{L^2}^4}{\nu^2}
\right) > 0 \quad\text{for all } t \geq 0.
\end{equation}

\label{def:moment}
For $t \geq 0$, define:
\begin{equation}
M(t) = \sum_{j=1}^J p_j\,r_j^t\,\log(1/p_j).
\end{equation}
Note $M(0) = \cS$, $M(1) = H$, and $M(t) \geq 0$ since
$r_j, p_j, \log(1/p_j) \geq 0$.

\label{thm:logconvex}
The function $t \mapsto M(t)$ is log-convex: for all $t \geq 1$,
\begin{equation}\label{eq:logconvex}
M(t)^2 \leq M(t-1)\cdot M(t+1).
\end{equation}
Consequently $H^2 = M(1)^2 \leq M(0)\cdot M(2) = \cS\cdot M(2)$,
i.e.\ $\Phi^2 \leq M(2)/\cS$.

following_proof:
The weights $w_j = p_j\log(1/p_j) \geq 0$ define a positive measure
on $\{1,\ldots,J\}$, so $M(t) = \mathbb{E}_w[r_j^t]$.  By the
Cauchy--Schwarz inequality applied to $r_j^{t/2}\cdot r_j^{t/2}$:
\begin{equation}
M(t)^2 = \bigl(\mathbb{E}_w[r_j^{t/2}\cdot r_j^{t/2}]\bigr)^2
\leq \mathbb{E}_w[r_j^{t-1}]\cdot\mathbb{E}_w[r_j^{t+1}]
= M(t-1)\cdot M(t+1). \qquad\qed
\end{equation}
\renewcommand{\qedsymbol}{}

statement:
\label{lem:Mdot}
Along a smooth NS solution, the viscous contribution to $\dot M(t)$ is:
\begin{equation}\label{eq:Mdot}
\dot M(t)\big|_v
= 2\nu\frac{D}{E}\bigl[-M(t+1) + M(t) + V_{t+1} - V_t\bigr].
\end{equation}

following_proof:
Differentiating $M(t) = \sum_j p_j r_j^t f_j$ (where $f_j = \log(1/p_j)$)
using $\dot p_j|_v = -2\nu(D/E)p_j(r_j-1)$ and
$\dot f_j|_v = 2\nu(D/E)(r_j-1)$:
\begin{align}
\dot M(t)\big|_v
&= \sum_j\dot p_j r_j^t f_j + \sum_j p_j r_j^t\dot f_j
= -2\nu\frac{D}{E}\bigl(M(t+1)-M(t)\bigr)
+ 2\nu\frac{D}{E}(V_{t+1}-V_t). \qed
\end{align}
\renewcommand{\qedsymbol}{}

statement:
\label{thm:bernoulli}
The viscous contribution to $\dot\Phi = d(H/\cS)/dt$ satisfies:
\begin{equation}\label{eq:bernoulli}
\dot\Phi\big|_v
= \frac{2\nu(D/E)}{\cS}\bigl[\Phi^2 - M(2)/\cS + (V_2-1)/\cS\bigr]
\leq \frac{2\nu(D/E)(V_2-1)}{\cS}
= 2\nu\frac{D}{E}\cdot W.
\end{equation}

\label{thm:logistic}
The viscous evolution of $W = (V_2-1)/\cS$ satisfies:
\begin{equation}\label{eq:logistic}
\dot W\big|_v \leq 2\nu\frac{D}{E}\cdot W(\Phi - 2 - W\cS).
\end{equation}
The term $-W\cS$ provides quadratic self-damping beyond the linear term.

\label{thm:injection}
The nonlinear contribution to $\dot r_j$ satisfies, in
$\tau$-time ($d\tau = \nu(D/E)\,dt$):
\begin{equation}\label{eq:injection}
\left|\frac{dr_j}{d\tau}\bigg|_{\rm NL}\right| \leq C\delta r_j,
\end{equation}
where $C$ depends on $J$ but not on $E$.

\label{thm:riccati}
In $\tau$-time, $R(t) = \max_j r_j(t)$ satisfies:
\begin{equation}\label{eq:riccati}
\frac{dR}{d\tau} \leq -R(R-1) + C\delta R.
\end{equation}

\label{thm:Rbound}
For any smooth NS solution on $\T^3$:
\begin{equation}\label{eq:Rbound}
R(t) \leq \max\!\left(R(0),\; \frac{1+\sqrt{1+4C\pi/2}}{2}\right)
=: C_H < \infty \quad\text{for all } t \geq 0.
\end{equation}

\label{thm:lyapunov}
The sublevel set $\{L \leq 2,\;\Phi < 2\}$ is positively invariant
under the viscous NS dynamics:
\begin{equation}\label{eq:Ldot}
\dot L\big|_v \leq 2\nu\frac{D}{E}\cdot\sqrt{W}(L-2).
\end{equation}
In particular: $L(0) \leq 2 \Rightarrow L(t) \leq 2$ for all $t$.

following_proof:
From Theorem~\ref{thm:bernoulli}: $\dot\Phi|_v \leq 2\nu(D/E)W$.
From Theorem~\ref{thm:logistic} with $x = \sqrt{W}$:
$d\sqrt{W}/dt|_v \leq \nu(D/E)(\Phi-2)\sqrt{W}$.  So:
\begin{align}
\dot L\big|_v
&\leq 2\nu\frac{D}{E}W + 2\nu\frac{D}{E}(\Phi-2)\sqrt{W}
= 2\nu\frac{D}{E}\sqrt{W}\bigl(\sqrt{W}+\Phi-2\bigr)\\
&= 2\nu\frac{D}{E}\sqrt{W}(L - \sqrt{W} - 2) \leq 2\nu\frac{D}{E}\sqrt{W}(L-2),
\end{align}
using $\sqrt{W} \geq 0$.  For $L \leq 2$: $\dot L|_v \leq 0$.

statement:
\label{cor:subcritical}
For smooth NS solutions with $L(0) < 2$: set $\epsilon_0 = 2-L(0) > 0$.
Then $W(\tau) \leq W(0)e^{-2\epsilon_0\tau}$ and:
\begin{equation}
\Phi(t) \leq \Phi(0) + \frac{W(0)}{2-L(0)} + \text{(nonlinear terms)} < \infty.
\end{equation}

For $\hat n\in S^2$, aperture $\delta\in(0,\pi/2)$, scale $N\geq 1$:
\begin{equation}
K_N^\delta = \{k\in\Z^3 : N\leq|k|\leq 2N,\;\angle(\hat k,\hat n)\leq\delta\}.
\end{equation}

\label{thm:bernstein-single}
If $u_N$ has Fourier support in $K_N^\delta$:
\begin{equation}\label{eq:bernstein-single}
\|u_N\|_{L^\infty} \leq C\delta\,\|u_N\|_{\Hdot{3/2}}.
\end{equation}
The bound is sharp.

\label{prop:incomp}
For divergence-free $u_N$ with Fourier support in $K_N^\delta$,
the axial component $u_N^{\hat n} = (u_N\cdot\hat n)\hat n$ satisfies:
\begin{equation}
\|u_N^{\hat n}\|_{L^\infty} \leq C\delta^2\,\|u_N\|_{\Hdot{3/2}}.
\end{equation}

\label{thm:bernstein-multi}
For any $\epsilon > 0$ and smooth divergence-free $u$ on $\T^3$
with Fourier support in a cone of aperture $\delta$:
\begin{equation}\label{eq:bernstein-multi}
\|u\|_{L^\infty} \leq C_\epsilon\delta\,\|u\|_{\Hdot{3/2+\epsilon}}.
\end{equation}

\label{thm:enstrophy-max}
Let $u(t)$ be a smooth NS solution on $[t_0,T)$ with
$\delta(u(t)) \leq \theta_0$ throughout.  Then:
\begin{equation}\label{eq:Dstar}
D(t) \leq D_*(\theta_0,\nu) := \max\!\left(D(t_0),\;
\frac{C^2\theta_0^2}{\nu^2}\right) \quad\text{for all } t\in[t_0,T).
\end{equation}

\label{lem:fourier-split}
For any smooth NS solution on $\T^3$:
\begin{equation}\label{eq:fourier-split}
E(t) \to \infty \implies \frac{D(t)}{E(t)} \to \infty.
\end{equation}

\label{thm:dichotomy}
If blow-up occurs at $T^* < \infty$, then necessarily:
\begin{equation}\label{eq:dichotomy}
\int_0^{T^*}\frac{D(t)}{E(t)}\,dt = \infty.
\end{equation}

\label{lem:entropy-concentration}
If $\cS(u(t)) \leq \epsilon/\log J$, then $\delta(u(t)) \leq 2\alpha$,
where $\alpha = \diam(\Omega_j) = O(J^{-1/2})$ is the sector aperture.

\label{thm:main}
There exists an explicit constant $\delta_*>0$, depending only on $\nu$
and universal Sobolev and Coifman--Meyer constants, with the following
property.  Let $u$ be a Leray--Hopf solution of~\eqref{eq:NS} on $[0,T^*)$
with $T^*<\infty$ the maximal time of existence.  If
\begin{equation}\label{eq:angular-criterion}
\limsup_{t\to T^*}\,\delta(u(t)) < \delta_*,
\end{equation}
then $u$ extends smoothly past $T^*$.

\label{def:frame}
Fix a reference direction $\hat{n}\in S^2$.  For $\xi\in\R^3\setminus\{0\}$
with $\hat{\xi}\neq -\hat{n}$, define
\begin{equation}\label{eq:frame}
e_1(\xi) := \frac{\hat{n}-(\hat{n}\cdot\hat{\xi})\hat{\xi}}
{|\hat{n}-(\hat{n}\cdot\hat{\xi})\hat{\xi}|},\qquad
e_2(\xi) := \hat{\xi}\times e_1(\xi).
\end{equation}
The helical basis vectors are
$e^\pm(\xi):=\frac{1}{\sqrt{2}}[e_1(\xi)\pm i\,e_2(\xi)]$.

\label{lem:frame}
For $\hat{\xi},\hat{\zeta}$ both within angle $\delta\in(0,1/2)$ of $\hat{n}$:
\begin{equation}\label{eq:frame-lip}
|e_i(\xi)-e_i(\zeta)|\leq \frac{4}{\delta}\,|\hat{\xi}-\hat{\zeta}|
\end{equation}
for $i=1,2$.

\label{lem:helical-inner}
For $\hat{\xi},\hat{\zeta}$ both within angle $\delta\in(0,1/2)$ of $\hat{n}$:
\begin{align}
|e^+(\xi)\cdot e^+(\zeta)| &\leq 10\,\delta, \label{eq:pp}\\
|e^-(\xi)\cdot e^-(\zeta)| &\leq 10\,\delta, \label{eq:mm}\\
|e^+(\xi)\cdot e^-(\zeta)-1| &\leq 10\,\delta. \label{eq:pm}
\end{align}

\label{prop:universal}
For \textbf{any} trilinear interaction $(s_1,s_2)\to s_3$ with
$\hat{p},\hat{q},\hat{k}$ all within angle~$\delta$ of a common
direction $\hat{n}$:
\begin{equation}\label{eq:universal}
|\sigma^{s_1 s_2 s_3}(p,q,k)| \leq C_1\,\delta\,|q|,
\end{equation}
where $C_1=20$ is a universal constant.  Four of the eight channels
are doubly suppressed at $O(\delta^2|q|)$.

The single-helicity result of~\cite{BT} exploits cancellation in the
$(+,+)\to+$ channel.  Our observation is that \emph{all eight channels}
are simultaneously suppressed under angular concentration, including the
mixed-helicity interactions that prevent direct extension of~\cite{BT}
to the full equations.

\label{thm:trilinear}
Let $u,v,w$ be divergence-free vector fields with Fourier support in
$\cC_\delta(\hat{n})$ for some $\delta\in(0,1/2)$ and $\hat{n}\in S^2$.
Then:
\begin{equation}\label{eq:trilinear-main}
\abs{\int_{\R^3}(u\cdot\nabla v)\cdot w\,dx}
\leq C_0\,\delta\,\norm{u}_{\Hdot{1/2}}\norm{v}_{\Hdot{3/2}}\norm{w}_{\Hdot{1/2}},
\end{equation}
where $C_0$ depends only on the Coifman--Meyer constant and Sobolev
embedding constants.

\label{prop:freq-uniform}
The estimate of Theorem~\ref{thm:trilinear} holds uniformly across
all frequency regimes consistent with the cone localization hypothesis.

\label{cor:suppressed}
If $u$ has Fourier support in $\cC_\delta(\hat{n})$, then the nonlinear
energy transfer in $\Hdot{1/2}$ satisfies:
\begin{equation}\label{eq:suppressed}
\abs{\ip{|\nabla|^{1/2}(u\cdot\nabla)u}{|\nabla|^{1/2}u}}
\leq C_0\,\delta\,\norm{u}_{\Hdot{1/2}}^2\,\norm{u}_{\Hdot{3/2}}.
\end{equation}

\label{prop:dissipation}
Let $u$ be a smooth divergence-free solution of~\eqref{eq:NS}
with Fourier support in $\cC_\delta(\hat{n})$.  If
\begin{equation}\label{eq:delta-threshold}
\delta < \delta_* := \frac{\nu}{2C_0\,\norm{u(t)}_{\Hdot{1/2}}},
\end{equation}
then:
\begin{equation}\label{eq:energy-decay}
\frac{d}{dt}\norm{u}_{\Hdot{1/2}}^2 \leq -\nu\,\norm{u}_{\Hdot{3/2}}^2.
\end{equation}
In particular, the critical norm is strictly decreasing.

\label{prop:approx}
Let $u\in\Hdot{1/2}(\R^3)$ be divergence-free with concentration aperture
$\delta(u)<\delta_0$.  Decompose $u=u_{\mathrm{in}}+u_{\mathrm{out}}$
where $\hat{u}_{\mathrm{in}}$ is supported in $\cC_{\delta_0}(\hat{n})$
(the optimal cone) and $\hat{u}_{\mathrm{out}}$ is the remainder.
By definition, $\norm{u_{\mathrm{in}}}_{\Hdot{1/2}}^2\geq
\frac{1}{2}\norm{u}_{\Hdot{1/2}}^2$.  Then the nonlinear transfer satisfies:
\begin{equation}\label{eq:approx-suppressed}
|\cN| \leq C_0\delta_0\norm{u_{\mathrm{in}}}_{\Hdot{1/2}}^2
\norm{u_{\mathrm{in}}}_{\Hdot{3/2}}
+ C\norm{u_{\mathrm{out}}}_{\Hdot{1/2}}\norm{u}_{\Hdot{1/2}}
\norm{u}_{\Hdot{3/2}},
\end{equation}
where the first term carries the $\delta_0$-suppression and the second
is bounded by the out-of-cone energy (which is at most
$\frac{1}{2}\norm{u}_{\Hdot{1/2}}^2$).

\label{lem:continuation}
If $u$ is a mild solution on $[0,T^*)$ with $T^*<\infty$ maximal, then
$\limsup_{t\to T^*}\norm{u(t)}_{\Hdot{1/2}}=+\infty$.

\label{conj:angular}
If $u^*$ is a minimal blow-up element in the sense of~\cite{GKP2016},
then $\lim_{t\to T^*}\delta(u^*(t))=0$.

\label{conj:spreading}
For any smooth solution $u(t)$ of the 3D Navier--Stokes
equations on $\T^3$ with non-uniform angular energy
distribution ($\cC > 1/J$):
\begin{equation}
\frac{d\cC}{dt}\bigg|_{\rm NL} < 0.
\end{equation}

\label{conj:TIR}
For any smooth divergence-free field $u$ on $\T^3$:
\begin{equation}
\frac{d\cC}{dt}\bigg|_{\rm NL}[\bar u]
= -\frac{d\cC}{dt}\bigg|_{\rm NL}[u],
\end{equation}
where $\bar u$ denotes the field with
$\hat{\bar u}(k) = \hat u(k)^*$.

\label{conj:nongaussian}
For divergence-free Gaussian random fields $u$ with
independent Fourier phases:
\begin{equation}
\mathbb{E}\left[\frac{d\cC}{dt}\bigg|_{\rm NL}\right] = 0.
\end{equation}
The nonzero spreading for NS solutions is entirely due
to the non-Gaussian triadic phase correlations.

\label{def:sector}
For a smooth divergence-free field $u$ on $\T^3$:
\begin{align}
E_j &= \sum_{\hat k\in\Omega_j}|k|\,|\hat u(k)|^2,
\qquad E = \sum_j E_j, \qquad p_j = E_j/E,\\
\cC(u) &= \sum_j p_j^2 = \|p\|_{\ell^2}^2
\quad\text{(angular concentration)},\\
\cS(u) &= -\sum_j p_j\log p_j
\quad\text{(angular entropy)}.
\end{align}

\label{def:transfer}
Let $B(u,u) = -P[(u\cdot\nabla)u]$ denote the
Leray-projected advection, with Fourier representation
\begin{equation}
\widehat{B(u,u)}_j(k)
= -P_{jm}(k)\sum_{p+q=k}
iq_l\,\hat u_l(p)\,\hat u_m(q),
\end{equation}
where $P_{jm}(k) = \delta_{jm}-k_jk_m/|k|^2$ and
repeated indices are summed.  The per-mode $\Hdot{1/2}$
energy transfer is
\begin{equation}\label{eq:Tk}
T(k;u) = 2\,\re\bigl[|k|\,\hat u(k)^*
\cdot\widehat{B(u,u)}(k)\bigr].
\end{equation}
The spreading functional is:
\begin{equation}\label{eq:Sigma}
\Sigma(u) = \frac{d\cC}{dt}\bigg|_{\rm NL}
= \frac{2}{E}\sum_j p_j\Bigl(\sum_{\hat k\in\Omega_j}T(k;u)
- p_j\sum_k T(k;u)\Bigr).
\end{equation}

\label{cor:irreversible}
The transfer is purely time-irreversible:
$T^+ := (T(k;u)+T(k;\bar u))/2 \equiv 0$.

\label{prop:triadic}
\begin{equation}\label{eq:sinPsi}
T(k;u) = 2|k|\sum_{\substack{p+q=k\\j,l,m}}
P_{jm}(k)\,q_l\,|\hat u_j(k)||\hat u_l(p)||\hat u_m(q)|
\,\sin\Psi_{jlm},
\end{equation}
where $\Psi_{jlm}(k,p,q) = -\phi_j(k)+\phi_l(p)+\phi_m(q)$
is the triadic phase.

\label{prop:factored}
Without the Leray projector:
\begin{equation}\label{eq:factored}
T(k;u) = 2|k|\,\im\Bigl[
\sum_{p+q=k}(q\cdot\hat u(p))(\hat u(k)^*\cdot\hat u(q))
\Bigr].
\end{equation}

\label{prop:phase-preserve}
If $\hat u(k)=iV(k)$ with $V$ real for all $k$, then
$\hat B(k)=iR(k)$ with $R(k)\in\R^3$.

For $k\in\cK$, define:
\begin{equation}
\widetilde R_j(k) = \sum_mP_{jm}(k)\sum_{q\in\cK}
\bigl[(\mathbf{q}\cdot R(k\!-\!q))V_m(q)
+(\mathbf{(k\!-\!q)}\cdot V(q))R_m(k\!-\!q)\bigr],
\end{equation}
where the sum runs over $q\in\cK$ with
$k-q\in\cK'$.  The second-generation forcing is
$\hat B^{(2)}(k) = i\Delta t\,\widetilde R(k)$.

\label{thm:TG}
For all $k\in\cK$:
\begin{equation}
\widetilde R(k) = -\frac{1}{16}V(k),
\end{equation}
and therefore:
\begin{equation}
V(k)\cdot\widetilde R(k) = -\frac{|V(k)|^2}{16}
= -\frac{1}{512} < 0.
\end{equation}
The forcing is exactly anti-parallel to the velocity:
$\cos\alpha(k) = -1$ at every TG mode.  The nonlinear
transfer $T^{(2)}(k) = 2\sqrt{3}\,\Delta t\cdot(-1/512)<0$
depletes every original mode.

following_proof:
By exact rational arithmetic over the finite set
$\cK\times\cK'$.  The computation enumerates all
triads $(k,p',q)$ with $k\in\cK$, $q\in\cK$,
$p'=k-q\in\cK'$, evaluates the two advection contributions
(Type~A: new mode advects, original advected;
Type~B: original advects, new mode advected),
applies the Leray projector, and sums.

The result for each $k\in\cK$:
\begin{equation}
\widetilde R(k) = \left(\frac{k_1}{128},\;
-\frac{k_2}{128},\;0\right) = -\frac{1}{16}V(k).
