Using the frame representation and $e^\pm = (e_1 \pm i e_2)/\sqrt{2}$, we compute:

\textbf{Same-helicity:}
\begin{align}
e^+(\xi) \cdot e^+(\zeta) &= \tfrac{1}{2}\bigl[(e_1(\xi) \cdot e_1(\zeta)) - (e_2(\xi) \cdot e_2(\zeta)) + i(e_1(\xi) \cdot e_2(\zeta) + e_2(\xi) \cdot e_1(\zeta))\bigr].
\end{align}
For $\hat{\xi}, \hat{\zeta}$ both near $\hat{n}$, the frame vectors satisfy $e_1(\xi) \cdot e_1(\zeta) = 1 + O(\delta^2)$, $e_2(\xi) \cdot e_2(\zeta) = 1 + O(\delta^2)$, and $e_1(\xi) \cdot e_2(\zeta) = O(\delta)$.  The real part cancels to $O(\delta^2)$ while the imaginary part is $O(\delta)$, giving $|e^+(\xi) \cdot e^+(\zeta)| \leq 10\delta$.

\textbf{Opposite helicity:}
\begin{align}
e^+(\xi) \cdot e^-(\zeta) &= \tfrac{1}{2}\bigl[(e_1 \cdot e_1) + (e_2 \cdot e_2) + i(e_2 \cdot e_1 - e_1 \cdot e_2)\bigr] = 1 + O(\delta).
\end{align}
Thus $|e^+(\xi) \cdot e^-(\zeta) - 1| \leq 10\delta$.

