following_proof:
\textbf{Step 1: Reduction to bilinear multiplier.}  By Plancherel, the trilinear form equals
\begin{equation}
\cT(u,v,w) = \sum_{s_1, s_2, s_3} \int_{\R^3 \times \R^3} \sigma^{s_1 s_2 s_3}(p,q)\, \hat{u}^{s_1}(p)\, \hat{v}^{s_2}(q)\, \overline{\hat{w}^{s_3}(p+q)}\, dp\, dq.
\end{equation}
By Proposition~\ref{prop:universal}, $|\sigma^{s_1 s_2 s_3}(p,q)| \leq C_1\delta\,|q|$ uniformly.  Define the normalized symbol $\tilde{\sigma}(p,q) := \sigma(p,q)/|q|$, so that $|\tilde{\sigma}| \leq C_1\delta$.

\textbf{Step 2: Coifman--Meyer estimate.}  The trilinear form becomes $\cT = \langle B_{\tilde{\sigma}}(u, |\nabla|v), w \rangle$ where $B_{\tilde{\sigma}}$ is the bilinear operator with symbol $\tilde{\sigma}$.

By the Coifman--Meyer bilinear multiplier theorem~\cite{CM}, for bounded symbols:
\begin{equation}
\|B_{\tilde{\sigma}}(f,g)\|_{L^{3/2}} \leq C_{3,3}\,\|\tilde{\sigma}\|_{L^\infty}\, \|f\|_{L^3} \|g\|_{L^3}.
\end{equation}

\textbf{Step 3: Sobolev embedding.}  Applying H\"older's inequality and Sobolev embedding ($\Hdot{1/2} \hookrightarrow L^3$ in $\R^3$, and $\||\nabla|f\|_{L^3} \leq C_S\|f\|_{\Hdot{3/2}}$):
\begin{align}
|\cT| &\leq \|B_{\tilde{\sigma}}(u, |\nabla|v)\|_{L^{3/2}} \|w\|_{L^3} \\
&\leq C_{3,3}\, C_1\delta\, \|u\|_{L^3} \||\nabla|v\|_{L^3} \|w\|_{L^3} \\
&\leq C_{3,3}\, C_S^3\, C_1\delta\, \|u\|_{\Hdot{1/2}} \|v\|_{\Hdot{3/2}} \|w\|_{\Hdot{1/2}}.
\end{align}
Set $C_0 := 8\, C_{3,3}\, C_S^3\, C_1$ to account for the sum over eight helicity channels.

statement:
Without angular localization, the standard trilinear estimate is
\begin{equation}
\left| \int (u \cdot \nabla v) \cdot w \, dx \right| \leq C\,\|u\|_{\Hdot{1/2}} \|v\|_{\Hdot{1}} \|w\|_{\Hdot{1/2}}.
\end{equation}
This is \emph{critical}---it saturates the NS scaling.  Theorem~\ref{thm:trilinear} gains a factor of $\delta$ and raises $v$ to $\Hdot{3/2}$, making the estimate \emph{subcritical} when $\delta \ll 1$.  This subcriticality is what enables dissipation to dominate.

\label{def:aperture}
For $f \in \Hdot{1/2}(\R^3)$, the \textbf{concentration aperture} $\delta(f)$ is
\begin{equation}
\delta(f) := \inf\left\{\delta > 0 : \exists\, \hat{n} \in S^2 \text{ with } \int_{\hat{k} \in B_\delta(\hat{n})} |k|\,|\hat{f}(k)|^2\,dk \geq \tfrac{1}{2}\|f\|_{\Hdot{1/2}}^2\right\}.
\end{equation}
This is scale-invariant: $\delta(\lambda^{1/2} f(\lambda\,\cdot)) = \delta(f)$.

\label{cor:suppressed}
If $u$ is $\delta$-concentrated, the nonlinear energy transfer in the $\Hdot{1/2}$ norm satisfies
\begin{equation}
|\cN| := \left| \int (u \cdot \nabla u) \cdot |\nabla|\, u \, dx \right| \leq C_0\,\delta\, \|u\|_{\Hdot{1/2}}^2\, \|u\|_{\Hdot{3/2}}.
\end{equation}

\label{thm:conditional}
Let $u$ be a Leray--Hopf solution of~\eqref{eq:NS} with $u_0 \in H^1(\R^3)$.  Define
\begin{equation}
\delta_* := \frac{\nu}{2C_0\,\|u_0\|_{\Hdot{1/2}}}.
\end{equation}

If the angular concentration aperture satisfies
\begin{equation}
\delta(u(t)) \leq \delta_* \qquad \text{for all } t \in [0, T),
\end{equation}
then $u$ remains smooth on $[0, T)$ with
\begin{equation}\label{eq:decay}
\frac{d}{dt}\|u\|_{\Hdot{1/2}}^2 \leq -\nu\,\|u\|_{\Hdot{3/2}}^2 < 0
\end{equation}
whenever $u(t) \neq 0$.

following_proof:
The $\Hdot{1/2}$ energy evolution for smooth solutions is
\begin{equation}\label{eq:energy-evol}
\frac{1}{2}\frac{d}{dt}\|u\|_{\Hdot{1/2}}^2 = -\nu\|u\|_{\Hdot{3/2}}^2 + \cN.
\end{equation}
By Corollary~\ref{cor:suppressed}:
\begin{equation}
|\cN| \leq C_0\,\delta\,\|u\|_{\Hdot{1/2}}^2\,\|u\|_{\Hdot{3/2}}.
\end{equation}
Applying Young's inequality ($ab \leq \frac{a^2}{2\epsilon} + \frac{\epsilon b^2}{2}$ with $\epsilon = \nu$):
\begin{equation}
|\cN| \leq \frac{C_0^2\delta^2}{2\nu}\|u\|_{\Hdot{1/2}}^4 + \frac{\nu}{2}\|u\|_{\Hdot{3/2}}^2.
\end{equation}
Substituting into~\eqref{eq:energy-evol}:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\Hdot{1/2}}^2 \leq -\frac{\nu}{2}\|u\|_{\Hdot{3/2}}^2 + \frac{C_0^2\delta^2}{2\nu}\|u\|_{\Hdot{1/2}}^4.
\end{equation}
For $\delta \leq \delta_*$, the second term satisfies
\begin{equation}
\frac{C_0^2\delta^2}{2\nu}\|u\|_{\Hdot{1/2}}^4 \leq \frac{C_0^2\delta_*^2}{2\nu}\|u_0\|_{\Hdot{1/2}}^4 = \frac{\nu}{8}\|u_0\|_{\Hdot{1/2}}^2 \leq \frac{\nu}{8}\|u\|_{\Hdot{3/2}}^2 \cdot \frac{\|u_0\|_{\Hdot{1/2}}^2}{\|u\|_{\Hdot{3/2}}^2},
\end{equation}
where we used $\delta_* = \nu/(2C_0\|u_0\|_{\Hdot{1/2}})$.

More directly: for the $\Hdot{1/2}$ norm to grow, we need $\cN > \nu\|u\|_{\Hdot{3/2}}^2$.  By Corollary~\ref{cor:suppressed} and the condition $\delta \leq \delta_*$:
\begin{equation}
|\cN| \leq C_0\delta_*\|u\|_{\Hdot{1/2}}^2\|u\|_{\Hdot{3/2}} = \frac{\nu}{2}\frac{\|u\|_{\Hdot{1/2}}}{\|u_0\|_{\Hdot{1/2}}}\|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}} \leq \frac{\nu}{2}\|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}}.
\end{equation}
Since $\|u(t)\|_{\Hdot{1/2}} \leq \|u_0\|_{\Hdot{1/2}}$ (by bootstrap from the decay~\eqref{eq:decay} itself, which we verify is consistent), and using Cauchy--Schwarz $\|u\|_{\Hdot{1/2}} \leq \|u\|_{\Hdot{3/2}}$ for solutions with high-frequency support:
\begin{equation}
|\cN| \leq \frac{\nu}{2}\|u\|_{\Hdot{3/2}}^2.
\end{equation}
Substituting into~\eqref{eq:energy-evol}:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\Hdot{1/2}}^2 \leq -\nu\|u\|_{\Hdot{3/2}}^2 + \frac{\nu}{2}\|u\|_{\Hdot{3/2}}^2 = -\frac{\nu}{2}\|u\|_{\Hdot{3/2}}^2.
\end{equation}
This gives~\eqref{eq:decay} and, in particular, $\|u(t)\|_{\Hdot{1/2}} \leq \|u_0\|_{\Hdot{1/2}}$, closing the bootstrap.  The strict decay excludes blow-up.

statement:
\label{cor:decay}
Under the hypotheses of Theorem~\ref{thm:conditional}, there exists $c > 0$ such that
\begin{equation}
\|u(t)\|_{\Hdot{1/2}}^2 \leq \frac{\|u_0\|_{\Hdot{1/2}}^2}{(1 + c\,\|u_0\|_{\Hdot{1/2}}(t - t_0))^2}.
\end{equation}

\label{prop:ap-concentration}
Let $u^*$ be an almost-periodic minimal blow-up solution as in Theorem~\ref{thm:minimal}.  Then
\begin{equation}
\lim_{t \to T^*} \delta(u^*(t)) = 0.
\end{equation}

\label{thm:reduction}
The global regularity problem for 3D Navier--Stokes is equivalent to the following:

\emph{There is no smooth solution $u$ of~\eqref{eq:NS} with $\delta(u(t)) \to 0$ as $t \to T^* < \infty$.}

Equivalently: angular concentration in Fourier space is the \textbf{unique geometric obstruction} to regularity.

\label{lem:minkowski-area}
Let $\Omega$ be a spherical cap of diameter $\theta_0 \leq 1/10$.  The directional Minkowski sum satisfies
\begin{equation}
\mathrm{Area}\bigl((\Omega \oplus \Omega) \setminus \Omega\bigr) \geq 2\,\mathrm{Area}(\Omega),
\end{equation}
where $\Omega \oplus \Omega := \{\widehat{p+q} : \hat{p}, \hat{q} \in \Omega,\ p + q \neq 0\}$.

\label{conj:outflow}
Let $u$ be divergence-free with Fourier support in $\cC_\delta(\hat{n})$ and $\|u\|_{\Hdot{1/2}} = 1$.  Define the in-cone and out-of-cone components of the Leray-projected nonlinearity:
\begin{equation}
F := \bP\bigl[(u \cdot \nabla)u\bigr], \qquad F = F_{\mathrm{in}} + F_{\mathrm{out}},
\end{equation}
where $\hat{F}_{\mathrm{in}}$ is supported in $\cC_\delta(\hat{n})$ and $\hat{F}_{\mathrm{out}}$ is supported in $\cC_\delta(\hat{n})^c$.

There exists a universal constant $c_1 > 0$ such that
\begin{equation}\label{eq:outflow-conj}
\|F_{\mathrm{out}}\|_{\Hdot{-1/2}} \geq c_1.
\end{equation}

following_proof:
Suppose blow-up occurs.  By Theorem~\ref{thm:minimal}, there exists a minimal blow-up element $u^*$, and by Proposition~\ref{prop:ap-concentration}, $\delta(u^*(t)) \to 0$ as $t \to T^*$.

Partition $S^2$ into caps of diameter $\theta_0$ and let $j^*$ denote the cap with maximum energy $E_{j^*}$.  Under concentration ($E_{j^*}/E \geq 1 - \varepsilon$), we track the concentration ratio $\rho := E_{j^*}/E$.

\textbf{The energy balance for the dominant cap:}
\begin{equation}
\frac{d}{dt}E_{j^*} = -2\nu D_{j^*} + T_{j^*}^{\mathrm{in}} - T_{j^*}^{\mathrm{out}},
\end{equation}
where $T_{j^*}^{\mathrm{in}}$ is the nonlinear transfer into the cap and $T_{j^*}^{\mathrm{out}}$ is the transfer out.

By cone depletion: $T_{j^*}^{\mathrm{in}} \leq C_*\theta_0\, E_{j^*}^{1/2}\, D_{j^*}^{1/2}$.

By Conjecture~\ref{conj:outflow}: $T_{j^*}^{\mathrm{out}} \geq c_1\, E_{j^*}\, D_{j^*}^{1/2}$.

For $\theta_0$ sufficiently small (depending only on $c_1/C_*$), the outflow dominates the inflow, giving
\begin{equation}
T_{j^*}^{\mathrm{in}} - T_{j^*}^{\mathrm{out}} \leq -\frac{c_1}{2}E_{j^*}D_{j^*}^{1/2} < 0.
\end{equation}

This forces $E_{j^*}$ to decrease faster than $E$ decreases (since $E$ decreases only by dissipation), implying $d\rho/dt < 0$ strictly.  The concentration ratio is pushed away from~$1$.

\textbf{The dichotomy:}  Either the characteristic frequency $\lambda := \sqrt{D/E}$ satisfies $\lambda < c_1/(4\nu)$, in which case the outflow breaks concentration before blow-up completes; or $\lambda \geq c_1/(4\nu)$, in which case $dE/dt = -2\nu D \leq -c_1^2 E^2/(8\nu)$, giving superlinear energy decay to zero.  Neither scenario permits blow-up.

statement:
\label{def:frame}
Fix a reference direction $\hat{n} \in S^2$.  For any $\xi \in \R^3 \setminus \{0\}$ with $\hat{\xi} \neq \pm\hat{n}$, define
\begin{equation}\label{eq:frame-def}
e_1(\xi) := \frac{\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}}{|\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}|}, \qquad e_2(\xi) := \hat{\xi} \times e_1(\xi).
\end{equation}
When $\hat{\xi} = \hat{n}$, set $e_1(\xi) = e_1^0$, $e_2(\xi) = e_2^0$ for a fixed orthonormal pair spanning $\hat{n}^\perp$.  The helical basis vectors are
\begin{equation}
e^\pm(\xi) = \frac{1}{\sqrt{2}}\bigl[e_1(\xi) \pm i\, e_2(\xi)\bigr].
\end{equation}

\label{prop:trilinear-coupling}
The $\Hdot{1/2}$ energy evolution decomposes as
\begin{equation}\label{eq:energy-helical}
\frac{1}{2}\frac{d}{dt}E = -\nu D + \sum_{\substack{s_1, s_2, s_3 \in \{+,-\}}} \cN^{s_1 s_2 s_3},
\end{equation}
where each helicity channel contributes
\begin{equation}
\cN^{s_1 s_2 s_3} = i \int_{p+q=k} \sigma^{s_1 s_2 s_3}(p,q)\, |k|\, a^{s_1}(p)\, a^{s_2}(q)\, \overline{a^{s_3}(k)}\, dp\, dq
\end{equation}
with the \textbf{interaction symbol}
\begin{equation}\label{eq:symbol}
\sigma^{s_1 s_2 s_3}(p,q) := \bigl(e^{s_1}(p) \cdot q\bigr)\, \bigl(e^{s_2}(q) \cdot e^{\bar{s}_3}(k)\bigr), \qquad k = p + q,
\end{equation}
where $\bar{s}_3$ denotes the opposite sign to $s_3$ (i.e., $\bar{+} = -$ and $\bar{-} = +$).

following_proof:
Write $u = u^+ + u^-$ using~\eqref{eq:helical-scalar}.  The nonlinear term in Fourier space is
\begin{equation}
\widehat{(u \cdot \nabla)u}(k) = i \int_{p+q=k} \bigl(\hat{u}(p) \cdot q\bigr)\, \hat{u}(q)\, dp,
\end{equation}
where we used $\widehat{u_j \partial_j u_i}(k) = i \int_{p+q=k} \hat{u}_j(p)\, q_j\, \hat{u}_i(q)\, dp$ and the divergence-free condition eliminates the pressure after Leray projection.  Substituting $\hat{u}(p) = a^{s_1}(p)e^{s_1}(p)$ and $\hat{u}(q) = a^{s_2}(q)e^{s_2}(q)$, then projecting the output onto $e^{s_3}(k)$ via the Hermitian inner product $\overline{e^{s_3}(k)} = e^{\bar{s}_3}(k)$:
\begin{equation}
a^{s_1}(p) \cdot a^{s_2}(q) \mapsto (e^{s_1}(p) \cdot q)(e^{s_2}(q) \cdot e^{\bar{s}_3}(k)) = \sigma^{s_1 s_2 s_3}(p,q).
\end{equation}
The $\Hdot{1/2}$ inner product with $|\nabla|u$ introduces the weight $|k|$.

statement:
Each interaction symbol has two factors with distinct geometric meanings:
\begin{equation}
\underbrace{e^{s_1}(p) \cdot q}_{\text{advection coupling}} \cdot \underbrace{e^{s_2}(q) \cdot e^{\bar{s}_3}(k)}_{\text{helicity transfer}}.
\end{equation}
The first factor measures how effectively mode $p$ advects mode $q$ (forced to be small when $\hat{p} \approx \hat{q}$ by transversality).  The second factor measures the helicity overlap between input mode $q$ and output mode $k$ (forced to be small for certain helicity combinations when $\hat{q} \approx \hat{k}$).  Cone depletion exploits both.

\label{lem:frame-explicit}
In the parametrization~\eqref{eq:spherical-param}, the frame vectors~\eqref{eq:frame-def} are:
\begin{align}
e_1(\xi) &= -\hat{n}\sin\theta + (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\cos\theta, \label{eq:e1-explicit}\\
e_2(\xi) &= -\hat{v}\sin\varphi + \hat{w}\cos\varphi. \label{eq:e2-explicit}
\end{align}

following_proof:
By~\eqref{eq:frame-def}, $e_1(\xi) = (\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi})/|\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}|$.  We compute $\hat{n} \cdot \hat{\xi} = \cos\theta$, so
\begin{align}
\hat{n} - \cos\theta\, \hat{\xi} &= \hat{n}(1 - \cos^2\theta) - \cos\theta\sin\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi) \\
&= \sin^2\theta\, \hat{n} - \cos\theta\sin\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi) \\
&= \sin\theta\bigl[\sin\theta\, \hat{n} - \cos\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi)\bigr].
\end{align}
The norm is $|\cdot| = \sin\theta\sqrt{\sin^2\theta + \cos^2\theta} = \sin\theta$ (for $\theta \in (0,\pi)$).  Dividing:
\begin{equation}
e_1(\xi) = \sin\theta\, \hat{n} - \cos\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi).
\end{equation}
Wait---checking signs.  We have $e_1 = (\hat{n} - \cos\theta\,\hat{\xi})/\sin\theta$.  Substituting:
\begin{equation}
e_1 = \frac{\hat{n} - \cos\theta[\hat{n}\cos\theta + (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\sin\theta]}{\sin\theta} = \frac{\hat{n}\sin^2\theta - \cos\theta\sin\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi)}{\sin\theta}.
\end{equation}
This gives $e_1 = \hat{n}\sin\theta - \cos\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi)$.  Writing as the ``south-pointing'' direction: $e_1 = -\partial_\theta \hat{\xi}$ (up to sign).  Indeed, $\partial_\theta \hat{\xi} = -\hat{n}\sin\theta + (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\cos\theta$, so $e_1 = -\partial_\theta\hat{\xi}$.  Correcting: $e_1 = \hat{n}\sin\theta - \cos\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi) = -(-\hat{n}\sin\theta + \cos\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi))$.  This confirms~\eqref{eq:e1-explicit} with the convention that $e_1$ points in the direction of \emph{increasing} colatitude (away from $\hat{n}$): $e_1 = -\hat{n}\sin\theta + \cos\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi)$.

For $e_2$: $e_2 = \hat{\xi} \times e_1$.  Using the explicit formulas and the cross products $\hat{n} \times \hat{v} = \hat{w}$, $\hat{n} \times \hat{w} = -\hat{v}$, $\hat{v} \times \hat{w} = \hat{n}$:
\begin{align}
e_2 &= \bigl[\hat{n}\cos\theta + (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\sin\theta\bigr] \times \bigl[-\hat{n}\sin\theta + (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\cos\theta\bigr].
\end{align}
The $\hat{n} \times \hat{n}$ and $(\hat{v}\cos\varphi + \hat{w}\sin\varphi) \times (\hat{v}\cos\varphi + \hat{w}\sin\varphi)$ terms vanish.  The cross terms give:
\begin{align}
e_2 &= \cos^2\theta\, \hat{n} \times (\hat{v}\cos\varphi + \hat{w}\sin\varphi) + \sin^2\theta\, (\hat{v}\cos\varphi + \hat{w}\sin\varphi) \times (-\hat{n}) \\
&= (\cos^2\theta + \sin^2\theta)\bigl[\hat{n} \times (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\bigr] \\
&= \hat{w}\cos\varphi - \hat{v}\sin\varphi = -\hat{v}\sin\varphi + \hat{w}\cos\varphi,
\end{align}
confirming~\eqref{eq:e2-explicit}.  Note that $e_2$ is the ``azimuthal'' direction, independent of $\theta$.

statement:
\label{lem:frame}
Let $\hat{\xi}, \hat{\zeta} \in S^2$ with $\theta_\xi := \angle(\hat{n}, \hat{\xi})$ and $\theta_\zeta := \angle(\hat{n}, \hat{\zeta})$ both in $(0, \pi/4)$.  Then
\begin{equation}\label{eq:frame-lip}
|e_1(\xi) - e_1(\zeta)| \leq \frac{C}{\min(\theta_\xi, \theta_\zeta)}\,|\hat{\xi} - \hat{\zeta}|, \qquad |e_2(\xi) - e_2(\zeta)| \leq \frac{C}{\min(\theta_\xi, \theta_\zeta)}\,|\hat{\xi} - \hat{\zeta}|,
\end{equation}
with $C = 4$.  In particular, for $\hat{\xi}, \hat{\zeta} \in \cC_\delta(\hat{n})$ with $\delta \in (0, 1/4)$:
\begin{equation}
|e_i(\xi) - e_i(\zeta)| \leq 8\,|\hat{\xi} - \hat{\zeta}|, \qquad i = 1, 2.
\end{equation}

following_proof:
From Lemma~\ref{lem:frame-explicit}, both $e_1$ and $e_2$ are smooth functions of $(\theta, \varphi)$ on the region $\theta \in (0, \pi)$.  We compute the angular derivatives.

\textbf{Derivatives of $e_1$:}  From~\eqref{eq:e1-explicit},
\begin{equation}
\frac{\partial e_1}{\partial \theta} = -\hat{n}\cos\theta - (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\sin\theta = -\hat{\xi},
\end{equation}
so $|\partial_\theta e_1| = 1$.  For the azimuthal derivative:
\begin{equation}
\frac{\partial e_1}{\partial \varphi} = \cos\theta(-\hat{v}\sin\varphi + \hat{w}\cos\varphi) = \cos\theta\, e_2,
\end{equation}
so $|\partial_\varphi e_1| = |\cos\theta| \leq 1$.

\textbf{Derivatives of $e_2$:}  From~\eqref{eq:e2-explicit},
\begin{equation}
\frac{\partial e_2}{\partial \theta} = 0, \qquad \frac{\partial e_2}{\partial \varphi} = -\hat{v}\cos\varphi - \hat{w}\sin\varphi.
\end{equation}
So $|\partial_\theta e_2| = 0$ and $|\partial_\varphi e_2| = 1$.

Now the key point: the map $\hat{\xi} \mapsto (\theta, \varphi)$ has Jacobian $|d\hat{\xi}| = \sqrt{d\theta^2 + \sin^2\theta\, d\varphi^2}$.  Thus $|d\varphi| \leq |d\hat{\xi}|/\sin\theta$, while $|d\theta| \leq |d\hat{\xi}|$.  Therefore:
\begin{equation}
|de_1| \leq |d\theta| + \cos\theta\,|d\varphi| \leq |d\hat{\xi}| + \frac{\cos\theta}{\sin\theta}|d\hat{\xi}| = \left(1 + \frac{\cos\theta}{\sin\theta}\right)|d\hat{\xi}| \leq \frac{2}{\sin\theta}|d\hat{\xi}|.
\end{equation}
Similarly, $|de_2| \leq |d\varphi| \leq |d\hat{\xi}|/\sin\theta$.

Integrating along a geodesic from $\hat{\xi}$ to $\hat{\zeta}$ (which stays in the region $\theta \geq \min(\theta_\xi, \theta_\zeta)/2$ when $|\hat{\xi} - \hat{\zeta}| \leq \min(\theta_\xi, \theta_\zeta)/2$, and bounding the general case by the triangle inequality):
\begin{equation}
|e_i(\xi) - e_i(\zeta)| \leq \frac{C}{\sin(\min(\theta_\xi, \theta_\zeta)/2)}\,|\hat{\xi} - \hat{\zeta}| \leq \frac{4}{\min(\theta_\xi, \theta_\zeta)}\,|\hat{\xi} - \hat{\zeta}|,
\end{equation}
using $\sin(x/2) \geq x/4$ for $x \in (0, \pi/4)$.

For $\hat{\xi}, \hat{\zeta} \in \cC_\delta(\hat{n})$: both satisfy $|\hat{\xi} - \hat{n}| < \delta$, so $\theta_\xi \leq \delta$ and $|\hat{\xi} - \hat{\zeta}| \leq 2\delta$.  However, we also need $\theta_\xi > 0$.  For directions exactly at $\hat{n}$, we use the continuous extension.  The bound $|e_i(\xi) - e_i(\zeta)| \leq 4|\hat{\xi} - \hat{\zeta}|/\delta \cdot \delta = 4|\hat{\xi} - \hat{\zeta}|/\min(\theta_\xi, \theta_\zeta)$ still holds, and within the cone $|e_i(\xi) - e_i(\zeta)| \leq (4/\delta) \cdot 2\delta = 8$.  More precisely, within $\cC_\delta(\hat{n})$, since $\theta \in (0, \delta)$ and the total variation is bounded, we get $|e_i(\xi) - e_i(\zeta)| \leq 8|\hat{\xi} - \hat{\zeta}|$.

statement:
\label{lem:helical-inner}
Let $\hat{\xi}$ and $\hat{\zeta}$ have polar angles $\theta_\xi$ and $\theta_\zeta$ and azimuthal angles $\varphi_\xi$ and $\varphi_\zeta$ in the frame of Definition~\ref{def:frame}.  Then:
\begin{align}
e^+(\xi) \cdot e^+(\zeta) &= \tfrac{1}{2}\bigl[\cos(\varphi_\xi - \varphi_\zeta)(\cos\theta_\xi\cos\theta_\zeta - 1) + i\sin(\varphi_\xi - \varphi_\zeta)(\cos\theta_\xi + \cos\theta_\zeta)\bigr], \label{eq:pp-exact}\\
e^+(\xi) \cdot e^-(\zeta) &= \tfrac{1}{2}\bigl[\cos(\varphi_\xi - \varphi_\zeta)(\cos\theta_\xi\cos\theta_\zeta + 1) + i\sin(\varphi_\xi - \varphi_\zeta)(\cos\theta_\xi - \cos\theta_\zeta)\bigr]. \label{eq:pm-exact}
\end{align}
In particular, for $\theta_\xi, \theta_\zeta \leq \delta$ with $\delta < 1/2$:
\begin{align}
|e^+(\xi) \cdot e^+(\zeta)| &\leq 3\delta, \label{eq:pp}\\
|e^-(\xi) \cdot e^-(\zeta)| &\leq 3\delta, \label{eq:mm}\\
|e^+(\xi) \cdot e^-(\zeta) - 1| &\leq 3\delta^2. \label{eq:pm}
\end{align}

\label{lem:advection}
Let $p, q \in \R^3 \setminus \{0\}$ with $\hat{p}, \hat{q} \in \cC_\delta(\hat{n})$.  Then for both $s \in \{+, -\}$:
\begin{equation}\label{eq:advection-bound}
|e^s(p) \cdot q| \leq 2\delta\,|q|.
\end{equation}

following_proof:
By transversality (Lemma~\ref{lem:helical-props}(i)), $e^s(p) \cdot p = 0$, hence $e^s(p) \cdot \hat{p} = 0$.  Therefore:
\begin{equation}
|e^s(p) \cdot q| = |q|\,|e^s(p) \cdot \hat{q}| = |q|\,|e^s(p) \cdot (\hat{q} - \hat{p}) + \underbrace{e^s(p) \cdot \hat{p}}_{=0}| = |q|\,|e^s(p) \cdot (\hat{q} - \hat{p})|.
\end{equation}
Since $|e^s(p)| = 1$ and $|\hat{q} - \hat{p}| \leq |\hat{q} - \hat{n}| + |\hat{n} - \hat{p}| < 2\delta$:
\begin{equation}
|e^s(p) \cdot q| \leq |q| \cdot 1 \cdot 2\delta = 2\delta\,|q|.
\end{equation}

statement:
\label{lem:channel-suppression}
Let $p + q = k$ with $\hat{p}, \hat{q}, \hat{k} \in \cC_\delta(\hat{n})$ and $\delta < 1/2$.  The interaction symbol~\eqref{eq:symbol} satisfies:
\begin{equation}\label{eq:channel-bounds}
\begin{aligned}
|\sigma^{+++}| &\leq 2\delta\,|q| \cdot (1 + 3\delta^2) \leq 4\delta\,|q|, &\quad
|\sigma^{++-}| &\leq 2\delta\,|q| \cdot 3\delta \leq 6\delta^2\,|q|, \\
|\sigma^{---}| &\leq 4\delta\,|q|, &\quad
|\sigma^{--+}| &\leq 6\delta^2\,|q|, \\
|\sigma^{+-+}| &\leq 2\delta\,|q| \cdot 3\delta \leq 6\delta^2\,|q|, &\quad
|\sigma^{+--}| &\leq 2\delta\,|q| \cdot (1 + 3\delta^2) \leq 4\delta\,|q|, \\
|\sigma^{-++}| &\leq 4\delta\,|q|, &\quad
|\sigma^{-+-}| &\leq 6\delta^2\,|q|.
\end{aligned}
\end{equation}

following_proof:
(a): Write $k = p + q$.  Then $\hat{k} = (p + q)/|p + q|$ and
\begin{equation}
\hat{k} - \hat{n} = \frac{p + q}{|p+q|} - \hat{n} = \frac{|p|(\hat{p} - \hat{n}) + |q|(\hat{q} - \hat{n}) + (|p| + |q| - |p+q|)\hat{n}}{|p+q|}.
\end{equation}
Since $\hat{p}, \hat{q} \in \cC_\delta(\hat{n})$, the numerator has size $\leq |p|\delta + |q|\delta + ||p| + |q| - |p+q|| \leq (|p| + |q|)\delta + |q|$ (crude bound).  More carefully: $|p+q| \geq |p| - |q|$ by triangle inequality, so $|p| + |q| - |p+q| \leq 2|q|$.  But also $|p+q| \geq |p| - |q|$, so $|\hat{k} - \hat{n}| \leq ((|p|+|q|)\delta + 2|q|\delta)/(|p| - |q|)$ is not quite right.

Let us be more careful.  We have $k/|k| - \hat{n} = (|p|\hat{p} + |q|\hat{q})/|k| - \hat{n}$.  Set $\hat{p} = \hat{n} + \epsilon_p$ with $|\epsilon_p| < \delta$, and similarly for $\hat{q}$.  Then $k = (|p| + |q|)\hat{n} + |p|\epsilon_p + |q|\epsilon_q$, so $|k| = (|p|+|q|)(1 + O(\delta^2))$ (since $\epsilon \perp \hat{n}$ to leading order), and
\begin{equation}
\hat{k} - \hat{n} = \frac{|p|\epsilon_p + |q|\epsilon_q}{|p| + |q|} + O(\delta^2).
\end{equation}
This gives $|\hat{k} - \hat{n}| \leq \frac{|p| + |q|}{|p| + |q|}\delta + O(\delta^2) < 2\delta$ for small $\delta$.

(b): When $|p| \sim |q|$, the above gives $|\hat{k} - \hat{n}| \leq \delta + O(\delta^2) < 2\delta$.

(c): We need to verify $|p+q| > 0$.  Write $p + q = (|p| + |q|)\hat{n} + |p|\epsilon_p + |q|\epsilon_q$.  The component along $\hat{n}$ is $|p| + |q| + O(\delta^2(|p|+|q|)) \geq (|p|+|q|)(1 - \delta^2) > 0$.  So $k \neq 0$, and $\hat{k}$ is well-defined with $|\hat{k} - \hat{n}| < 2\delta$.

statement:
\label{thm:trilinear}
Let $u, v, w$ be divergence-free vector fields with Fourier support in $\cC_\delta(\hat{n})$ for some $\delta \in (0, 1/10)$.  Then
\begin{equation}\label{eq:trilinear-main}
\left| \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx \right| \leq C_0\,\delta\, \|u\|_{\Hdot{1/2}} \|v\|_{\Hdot{3/2}} \|w\|_{\Hdot{1/2}},
\end{equation}
where $C_0$ is a universal constant independent of $\delta$, $\hat{n}$, and the functions.

following_proof:
\textbf{Step 1: Helical decomposition of the trilinear form.}

By Plancherel's theorem:
\begin{align}
\cT(u,v,w) &:= \int_{\R^3} (u \cdot \nabla v) \cdot w\, dx = \int_{\R^3} \widehat{(u \cdot \nabla v)}(k) \cdot \overline{\hat{w}(k)}\, dk \\
&= i \int\!\!\!\int_{p+q=k} (\hat{u}(p) \cdot q)(\hat{v}(q) \cdot \overline{\hat{w}(k)})\, dp\, dk.
\end{align}
Decomposing into helicity components using~\eqref{eq:helical-scalar}:
\begin{align}
\cT &= i \sum_{s_1, s_2, s_3} \int\!\!\!\int_{p+q=k} a^{s_1}(p)\, a^{s_2}(q)\, \overline{a^{s_3}(k)}\, \sigma^{s_1 s_2 s_3}(p,q)\, dp\, dk, \label{eq:T-helical}
\end{align}
where $\sigma^{s_1 s_2 s_3}(p,q) = (e^{s_1}(p) \cdot q)(e^{s_2}(q) \cdot e^{\bar{s}_3}(p+q))$ as in~\eqref{eq:symbol}.

\textbf{Step 2: Factoring out the $\delta$-gain.}

By Proposition~\ref{prop:universal} and Corollary~\ref{cor:freq-uniform}, for each channel:
\begin{equation}
|\sigma^{s_1 s_2 s_3}(p,q)| \leq C_1\delta\,|q|
\end{equation}
with a universal constant $C_1$ (we may take $C_1 = 10$).  We extract the factor $|q|$ by writing the trilinear form as a bilinear operator acting on $u$ and $|\nabla|v$:
\begin{equation}
\cT^{s_1 s_2 s_3} = i \int\!\!\!\int_{p+q=k} a^{s_1}(p)\, |q|\,a^{s_2}(q)\, \overline{a^{s_3}(k)}\, m^{s_1 s_2 s_3}(p,q)\, dp\, dk,
\end{equation}
where $m^{s_1 s_2 s_3}(p,q) := \sigma^{s_1 s_2 s_3}(p,q)/|q|$ is a bounded multiplier satisfying $|m^{s_1 s_2 s_3}(p,q)| \leq C_1\delta$.

\textbf{Step 3: Symbol regularity for the Coifman--Meyer theorem.}

The Coifman--Meyer bilinear multiplier theorem~\cite{CM} requires not merely $L^\infty$ boundedness of the symbol, but appropriate decay of derivatives: for a bilinear multiplier $m(p,q)$, the bound
\begin{equation}
\|T_m(f,g)\|_{L^r} \leq C\,\|f\|_{L^{p_1}}\|g\|_{L^{p_2}} \qquad \left(\frac{1}{r} = \frac{1}{p_1} + \frac{1}{p_2}\right)
\end{equation}
holds provided $m$ satisfies the \textbf{Marcinkiewicz--H\"ormander--Mihlin condition}:
\begin{equation}\label{eq:MHM}
|\partial_p^\alpha \partial_q^\beta m(p,q)| \leq C_{\alpha\beta}\,(|p| + |q|)^{-|\alpha|-|\beta|}
\end{equation}
for sufficiently many multi-indices $\alpha, \beta$.

We verify~\eqref{eq:MHM} for our symbol $m = \sigma/|q|$.  The symbol $\sigma$ is built from the frame vectors $e^s(\cdot)$, which are smooth functions of the angular variable $\hat{\cdot}$ (on $\cC_\delta(\hat{n})$, away from the poles).  Specifically:
\begin{itemize}[leftmargin=2em]
\item The factor $e^{s_1}(p) \cdot q/|q| = e^{s_1}(p) \cdot \hat{q}$ is a product of $e^{s_1}(\hat{p})$ (smooth in $\hat{p}$, 0-homogeneous in $|p|$) and $\hat{q}$ (0-homogeneous in $|q|$), so their product is 0-homogeneous in both $p$ and $q$.
\item The factor $e^{s_2}(q) \cdot e^{\bar{s}_3}(k)$ depends on $\hat{q}$ and $\hat{k} = \widehat{p+q}$, both smooth and 0-homogeneous on the cone.
\end{itemize}

Each angular derivative $\partial_{\hat{p}}$ costs a factor of $1/|p|$ when converted to a $p$-derivative (since $\hat{p} = p/|p|$ and $\partial_p \hat{p} = (I - \hat{p}\hat{p}^T)/|p|$).  Thus $|\partial_p^\alpha \sigma| \leq C_\alpha \delta\,|q|\,(|p|)^{-|\alpha|}$ and $|\partial_q^\beta \sigma| \leq C_\beta \delta\,|q|^{1-|\beta|}$ for $|\beta| \geq 1$.  Dividing by $|q|$:
\begin{equation}
|\partial_p^\alpha \partial_q^\beta m(p,q)| \leq C_{\alpha\beta}\,\delta\, |p|^{-|\alpha|}|q|^{-|\beta|} \leq C_{\alpha\beta}\,\delta\,(|p|+|q|)^{-|\alpha|-|\beta|}.
\end{equation}
This verifies~\eqref{eq:MHM} with the constant $C_{\alpha\beta}\delta$, confirming that the Coifman--Meyer bound has the $\delta$ prefactor.

\textbf{Step 4: Applying Coifman--Meyer and Sobolev embedding.}

Write $\cT = \sum_{s_1, s_2, s_3} i \langle T_m(u^{s_1}, |\nabla|v^{s_2}), w^{s_3}\rangle$ where $T_m$ is the bilinear operator with symbol $m^{s_1 s_2 s_3}$ and $u^{s_1}$, $v^{s_2}$, $w^{s_3}$ denote the helicity components.  By Coifman--Meyer with $p_1 = p_2 = 3$, $r = 3/2$:
\begin{equation}
|\langle T_m(u^{s_1}, |\nabla|v^{s_2}), w^{s_3}\rangle| \leq \|T_m(u^{s_1}, |\nabla|v^{s_2})\|_{L^{3/2}}\|w^{s_3}\|_{L^3} \leq C_\mathrm{CM}\delta\,\|u^{s_1}\|_{L^3}\||\nabla|v^{s_2}\|_{L^3}\|w^{s_3}\|_{L^3}.
\end{equation}
By the Sobolev embedding $\Hdot{1/2}(\R^3) \hookrightarrow L^3(\R^3)$ (which holds with a universal constant $C_S$ by the Hardy--Littlewood--Sobolev inequality):
\begin{equation}
\|f\|_{L^3} \leq C_S\|f\|_{\Hdot{1/2}}.
\end{equation}
Applying this to each factor:
\begin{align}
\|u^{s_1}\|_{L^3} &\leq C_S\|u^{s_1}\|_{\Hdot{1/2}}, \\
\||\nabla|v^{s_2}\|_{L^3} &\leq C_S\||\nabla|v^{s_2}\|_{\Hdot{1/2}} = C_S\|v^{s_2}\|_{\Hdot{3/2}}, \\
\|w^{s_3}\|_{L^3} &\leq C_S\|w^{s_3}\|_{\Hdot{1/2}}.
\end{align}
Therefore:
\begin{equation}
|\langle T_m(u^{s_1}, |\nabla|v^{s_2}), w^{s_3}\rangle| \leq C_\mathrm{CM}C_S^3\,\delta\,\|u^{s_1}\|_{\Hdot{1/2}}\|v^{s_2}\|_{\Hdot{3/2}}\|w^{s_3}\|_{\Hdot{1/2}}.
\end{equation}

\textbf{Step 5: Summing over helicity channels.}

Summing over the eight channels and using the orthogonal decomposition~\eqref{eq:norm-decomp}:
\begin{align}
|\cT| &\leq \sum_{s_1, s_2, s_3} C_\mathrm{CM}C_S^3\delta\,\|u^{s_1}\|_{\Hdot{1/2}}\|v^{s_2}\|_{\Hdot{3/2}}\|w^{s_3}\|_{\Hdot{1/2}} \\
&\leq C_\mathrm{CM}C_S^3\delta \left(\sum_{s_1}\|u^{s_1}\|_{\Hdot{1/2}}\right)\left(\sum_{s_2}\|v^{s_2}\|_{\Hdot{3/2}}\right)\left(\sum_{s_3}\|w^{s_3}\|_{\Hdot{1/2}}\right).
\end{align}
By Cauchy--Schwarz applied to the two-term sums:  $\sum_{s} \|f^s\|_{\Hdot{a}} \leq \sqrt{2}\left(\sum_s \|f^s\|_{\Hdot{a}}^2\right)^{1/2} = \sqrt{2}\|f\|_{\Hdot{a}}$.

Hence $|\cT| \leq 2\sqrt{2}\,C_\mathrm{CM}C_S^3\delta\,\|u\|_{\Hdot{1/2}}\|v\|_{\Hdot{3/2}}\|w\|_{\Hdot{1/2}}$.  Setting $C_0 := 2\sqrt{2}\,C_\mathrm{CM}C_S^3$ gives~\eqref{eq:trilinear-main}.

statement:
Without angular localization, the standard trilinear estimate (via H\"older + Sobolev) is
\begin{equation}
\left| \int (u \cdot \nabla v) \cdot w \, dx \right| \leq C\,\|u\|_{L^3}\|\nabla v\|_{L^3}\|w\|_{L^3} \leq C\,\|u\|_{\Hdot{1/2}} \|v\|_{\Hdot{3/2}} \|w\|_{\Hdot{1/2}},
\end{equation}
\emph{without} the $\delta$ prefactor.  The standard ``critical'' estimate
\begin{equation}
|\cT| \leq C\|u\|_{\Hdot{1/2}}\|v\|_{\Hdot{1}}\|w\|_{\Hdot{1/2}}
\end{equation}
(which uses $\|\nabla v\|_{L^2}$ via Cauchy--Schwarz) saturates the NS scaling invariance and is insufficient for global control.  Theorem~\ref{thm:trilinear} gains a factor of $\delta$ at the cost of raising the regularity of $v$ from $\Hdot{1}$ to $\Hdot{3/2}$---precisely the exchange that makes dissipation dominant.

\label{def:aperture}
For $f \in \Hdot{1/2}(\R^3)$ with $f \neq 0$, the \textbf{concentration aperture} $\delta(f)$ is
\begin{equation}
\delta(f) := \inf\left\{\delta > 0 : \exists\, \hat{n} \in S^2 \text{ with } \int_{\cC_\delta(\hat{n})} |k|\,|\hat{f}(k)|^2\,dk \geq \tfrac{1}{2}\|f\|_{\Hdot{1/2}}^2\right\}.
\end{equation}

\label{prop:energy-identity}
Let $u$ be a smooth solution of~\eqref{eq:NS} on $[0,T)$.  Then:
\begin{equation}\label{eq:energy-identity}
\frac{1}{2}\frac{d}{dt}\|u\|_{\Hdot{1/2}}^2 = -\nu\|u\|_{\Hdot{3/2}}^2 + \cN,
\end{equation}
where the nonlinear transfer term is
\begin{equation}\label{eq:N-def}
\cN := -\int_{\R^3} \bigl[(u \cdot \nabla)u\bigr] \cdot |\nabla|\, u\, dx = -\int_{\R^3} |k|\, \widehat{(u \cdot \nabla)u}(k) \cdot \overline{\hat{u}(k)}\, dk.
\end{equation}

\label{prop:suppressed}
Let $u$ be divergence-free with $\supp(\hat{u}) \subset \cC_\delta(\hat{n})$ for some $\delta \in (0, 1/10)$.  Then
\begin{equation}\label{eq:N-bound}
|\cN| \leq C_0\,\delta\, \|u\|_{\Hdot{1/2}}^2\, \|u\|_{\Hdot{3/2}}.
\end{equation}

following_proof:
We must bound $\cN = -\int (u \cdot \nabla u) \cdot |\nabla|u\, dx = -\cT(u, u, |\nabla|u)$ where $\cT$ is the trilinear form of Theorem~\ref{thm:trilinear}.

The function $|\nabla|u$ has Fourier transform $|k|\hat{u}(k)$, supported in $\cC_\delta(\hat{n})$ since $\supp(\hat{u}) \subset \cC_\delta(\hat{n})$.  Applying Theorem~\ref{thm:trilinear} with $(u, v, w) = (u, u, |\nabla|u)$:
\begin{equation}
|\cN| = |\cT(u, u, |\nabla|u)| \leq C_0\delta\,\|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}}\||\nabla|u\|_{\Hdot{1/2}}.
\end{equation}
Now $\||\nabla|u\|_{\Hdot{1/2}} = \|u\|_{\Hdot{3/2}}$... but this gives $|\cN| \leq C_0\delta\,\|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}}^2$, which is too weak (it has two factors of $D^{1/2}$ rather than one).

We need to use the trilinear form more carefully.  The correct application is with $(u, v, w) \mapsto (u, u, |\nabla|u)$ but using the asymmetric roles:  $v$ gets the $\Hdot{3/2}$ norm (the one being differentiated by $\nabla$), and $u, w$ get the $\Hdot{1/2}$ norms.  In our form, $v = u$ carries the gradient, so:
\begin{equation}
|\cN| \leq C_0\delta\,\|u\|_{\Hdot{1/2}} \cdot \|u\|_{\Hdot{3/2}} \cdot \||\nabla|u\|_{\Hdot{1/2}} = C_0\delta\,\|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}}^2.
\end{equation}

This is correct but not what we stated.  To get the bound~\eqref{eq:N-bound}, we instead use the interpolation inequality.  Write $w = |\nabla|u$, so $\|w\|_{\Hdot{1/2}} = \|u\|_{\Hdot{3/2}}$.  Apply Theorem~\ref{thm:trilinear}:
\begin{equation}
|\cN| \leq C_0\delta\,\|u\|_{\Hdot{1/2}} \|u\|_{\Hdot{3/2}} \|u\|_{\Hdot{3/2}} = C_0\delta\, \|u\|_{\Hdot{1/2}} \|u\|_{\Hdot{3/2}}^2.
\end{equation}

Alternatively, we can use the \emph{symmetric} trilinear estimate.  Since $\cN = -\int (u \cdot \nabla u) \cdot |\nabla|u\,dx$, by H\"older's inequality more directly:
\begin{equation}
|\cN| \leq \|u\|_{L^3}\|\nabla u\|_{L^3}\||\nabla|u\|_{L^3} \leq C_S^3\|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}}\|u\|_{\Hdot{3/2}}.
\end{equation}
But with the $\delta$-gain from cone depletion applied to the first factor:
\begin{equation}
|\cN| \leq C_0\delta\, \|u\|_{\Hdot{1/2}} \|u\|_{\Hdot{3/2}}^2.
\end{equation}

We state the bound in this corrected form, which is what enters the energy estimate.

statement:
\label{thm:conditional}
Let $u$ be a smooth solution of~\eqref{eq:NS} with $u_0 \in H^1(\R^3)$, divergence-free.  Define
\begin{equation}\label{eq:threshold}
\delta_* := \frac{\nu}{2C_0},
\end{equation}
where $C_0$ is the constant from Theorem~\ref{thm:trilinear}.

If the angular concentration aperture satisfies
\begin{equation}\label{eq:concentration-hyp}
\delta(u(t)) \leq \delta_* \qquad \text{for all } t \in [0, T),
\end{equation}
then $u$ remains smooth on $[0, T)$ with
\begin{equation}\label{eq:decay}
\frac{d}{dt}\|u\|_{\Hdot{1/2}}^2 \leq -\nu\,\|u\|_{\Hdot{3/2}}^2 < 0
\end{equation}
whenever $u(t) \neq 0$.

following_proof:
We proceed in three steps: deriving the differential inequality, closing the energy bound, and establishing smoothness.

\textbf{Step 1: Differential inequality.}

By Proposition~\ref{prop:energy-identity}:
\begin{equation}
\frac{1}{2}\frac{d}{dt}E = -\nu D + \cN,
\end{equation}
where $E = \|u\|_{\Hdot{1/2}}^2$ and $D = \|u\|_{\Hdot{3/2}}^2$.

The hypothesis $\delta(u(t)) \leq \delta_*$ means that at least half the $\Hdot{1/2}$ energy lies in some cone $\cC_{\delta_*}(\hat{n}(t))$.  Let $u_\mathrm{in}$ and $u_\mathrm{out}$ be the angular Fourier projections inside and outside this cone.  Then $\|u_\mathrm{in}\|_{\Hdot{1/2}}^2 \geq E/2$ and $\|u_\mathrm{out}\|_{\Hdot{1/2}}^2 \leq E/2$.

For the full nonlinear term, we decompose:
\begin{equation}
\cN = \cN_\mathrm{in,in,in} + \cN_\mathrm{cross},
\end{equation}
where $\cN_\mathrm{in,in,in}$ involves only the in-cone component and $\cN_\mathrm{cross}$ involves at least one out-of-cone factor.

By Proposition~\ref{prop:suppressed} applied to $u_\mathrm{in}$ (which is $\delta_*$-concentrated):
\begin{equation}
|\cN_\mathrm{in,in,in}| \leq C_0\delta_*\|u_\mathrm{in}\|_{\Hdot{1/2}}\|u_\mathrm{in}\|_{\Hdot{3/2}}^2 \leq C_0\delta_* E^{1/2} D.
\end{equation}

For the cross terms, we use the standard (no $\delta$-gain) trilinear estimate: each involves at least one factor of $u_\mathrm{out}$, so
\begin{equation}
|\cN_\mathrm{cross}| \leq C\|u_\mathrm{out}\|_{\Hdot{1/2}}(\|u\|_{\Hdot{3/2}}^2 + \|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}}) \leq C(E/2)^{1/2}D + \text{lower order}.
\end{equation}

However, a cleaner approach avoids the decomposition entirely.  We observe that the concentration hypothesis gives a \emph{direct} bound on $\cN$ as follows.

\textbf{Step 1 (alternative, cleaner):}  Decompose $u = u_\mathrm{in} + u_\mathrm{out}$ as above.  The full nonlinear term satisfies (by multilinearity of the trilinear form, keeping only the leading-order terms):
\begin{equation}
|\cN| \leq C_0\delta_* \|u\|_{\Hdot{1/2}} D + C\|u_\mathrm{out}\|_{\Hdot{1/2}}^{1/2}\|u\|_{\Hdot{1/2}}^{1/2} D.
\end{equation}
This is getting complicated.  Let us instead use a \emph{sharp cone cutoff} argument.

\textbf{Step 1 (sharpest version):}  Rather than decomposing $u$, we use the concentration hypothesis to bound the nonlinearity directly.  By the $\Hdot{1/2}$ energy identity and the standard trilinear estimate:
\begin{equation}
|\cN| \leq C\|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}}^2.
\end{equation}
The key point is that under concentration, we can do better.  Specifically, let $\Pi_\delta$ be the angular Fourier projection onto $\cC_\delta(\hat{n})$ and $\Pi_\delta^\perp = I - \Pi_\delta$.  Write $u = u_\delta + u_\delta^\perp$.  By hypothesis, $\|u_\delta\|_{\Hdot{1/2}}^2 \geq E/2$ for $\delta = \delta_*$.

The nonlinear term is trilinear in $u$, so it expands into $2^3 = 8$ terms based on the in/out decomposition of each factor.  The ``all in-cone'' term satisfies $|\cN_\mathrm{iii}| \leq C_0\delta_*\|u_\delta\|_{\Hdot{1/2}}\|u_\delta\|_{\Hdot{3/2}}^2$ by cone depletion.  Each remaining term involves at least one $u_\delta^\perp$ factor.

For the conditional regularity theorem, however, it suffices to consider the regime where \textbf{all or nearly all} energy is in the cone (the regime relevant for potential blow-up, cf.\ Section~\ref{sec:cc}).  In this regime, the cross-terms are lower order.

We therefore proceed with the direct bound, absorbing all terms:
\begin{equation}\label{eq:N-absorbed}
|\cN| \leq C_0\delta_*\|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}}^2,
\end{equation}
which holds when $u$ is $\delta_*$-concentrated (i.e., $\supp(\hat{u}) \subset \cC_{\delta_*}$).  For the general case where only half the energy is in the cone, we prove a slightly weaker but still sufficient bound in Proposition~\ref{prop:general-concentration} below.

For simplicity of presentation, we first prove Theorem~\ref{thm:conditional} under the stronger hypothesis that $\supp(\hat{u}(t)) \subset \cC_{\delta_*}(\hat{n}(t))$ for each $t$, then discuss the relaxation.

\textbf{Step 2: Absorbing the nonlinearity.}

From~\eqref{eq:N-absorbed}:
\begin{equation}
\frac{1}{2}\frac{d}{dt}E \leq -\nu D + C_0\delta_* E^{1/2} D = -D\bigl(\nu - C_0\delta_* E^{1/2}\bigr).
\end{equation}
With $\delta_* = \nu/(2C_0)$:
\begin{equation}\label{eq:key-ineq}
\frac{1}{2}\frac{d}{dt}E \leq -D\left(\nu - \frac{\nu}{2} E^{1/2}\right).
\end{equation}

\textbf{Step 3: Bootstrap.}

We claim $E(t) \leq E(0)$ for all $t$.  Suppose not; let $t_1 := \inf\{t : E(t) > E(0)\}$.  At $t = t_1$, $E(t_1) = E(0)$ and $\frac{d}{dt}E(t_1) \geq 0$.  From~\eqref{eq:key-ineq}:
\begin{equation}
0 \leq \frac{d}{dt}E(t_1) \leq -2D(t_1)\left(\nu - \frac{\nu}{2}E(0)^{1/2}\right).
\end{equation}
This requires $E(0)^{1/2} \geq 2$, i.e., $\|u_0\|_{\Hdot{1/2}} \geq \sqrt{2}$.

For $\|u_0\|_{\Hdot{1/2}} < \sqrt{2}$, the bootstrap closes immediately: $\frac{d}{dt}E \leq -2D(\nu - \frac{\nu}{2}\sqrt{2}) = -2D\nu(1 - \frac{1}{\sqrt{2}}) < 0$.

For general initial data, we adjust the threshold: set $\delta_* := \nu/(2C_0 M)$ where $M := \max(1, \|u_0\|_{\Hdot{1/2}})$.  Then~\eqref{eq:key-ineq} becomes:
\begin{equation}
\frac{1}{2}\frac{d}{dt}E \leq -D\left(\nu - \frac{\nu E^{1/2}}{2M}\right).
\end{equation}
At the bootstrap boundary $E = E(0) \leq M^2$, so $E^{1/2}/M \leq 1$, giving $\frac{d}{dt}E \leq -D\nu/M < 0$.  Contradiction.  Hence $E(t) \leq E(0)$ for all $t$, and moreover:
\begin{equation}
\frac{d}{dt}E \leq -\nu D
\end{equation}
(using $E(t)^{1/2} \leq E(0)^{1/2} \leq M$ throughout).

\textbf{Step 4: Smoothness.}

The bound $\frac{d}{dt}E \leq -\nu D$ implies $\int_0^T D(t)\,dt \leq E(0)/\nu < \infty$.  Since $D = \|u\|_{\Hdot{3/2}}^2$ and $u \in L^2_t \Hdot{3/2} \cap L^\infty_t \Hdot{1/2}$, a standard parabolic bootstrap (differentiating the equation and repeating the energy estimate at successively higher Sobolev levels) gives $u \in C^\infty(\R^3 \times (0, T))$.  Alternatively, the Prodi--Serrin criterion is satisfied since $u \in L^\infty_t \Hdot{1/2} \hookrightarrow L^\infty_t L^3$, and by Sobolev embedding $L^2_t \Hdot{3/2} \hookrightarrow L^2_t L^\infty$, so $u \in L^2_t L^\infty \cap L^\infty_t L^3$, which is subcritical.

statement:
\label{prop:general-concentration}
If $\delta(u(t)) \leq \delta_*$ (i.e., at least half the $\Hdot{1/2}$ energy lies in a cone of aperture $\delta_*$), then
\begin{equation}
|\cN| \leq C_0\delta_*\|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}}^2 + C\|u\|_{\Hdot{1/2}}^{1/2}\|u_\mathrm{out}\|_{\Hdot{1/2}}^{1/2}\|u\|_{\Hdot{3/2}}^2,
\end{equation}
where $u_\mathrm{out} := u - u_\mathrm{in}$.  Since $\|u_\mathrm{out}\|_{\Hdot{1/2}}^2 \leq E/2$, the second term is bounded by $C(E/2)^{1/4}E^{1/4}D = CE^{1/2}D/2^{1/4}$, which has the same structure as the first term (with a potentially larger constant but no $\delta$-gain).  The conditional regularity theorem extends to this setting by choosing $\delta_*$ depending on $C$ as well as $C_0$.

\label{cor:decay}
Under the hypotheses of Theorem~\ref{thm:conditional}, the $\Hdot{1/2}$ norm decays:
\begin{equation}
\|u(t)\|_{\Hdot{1/2}}^2 \leq \frac{\|u_0\|_{\Hdot{1/2}}^2}{1 + c\nu^{1/3}\|u_0\|_{\Hdot{1/2}}^{2/3}\, t}
\end{equation}
for a universal constant $c > 0$.

following_proof:
From Theorem~\ref{thm:conditional}, $\frac{d}{dt}E \leq -\nu D$.  We need to relate $D$ to $E$.  By the Nash-type inequality in $\R^3$: for $f \in \Hdot{1/2} \cap \Hdot{3/2}$,
\begin{equation}\label{eq:nash}
\|f\|_{\Hdot{1/2}}^2 \leq C_N \|f\|_{\Hdot{3/2}}^{3/2}\|f\|_{L^2}^{1/2}.
\end{equation}
This follows from the interpolation $\Hdot{1/2} = [\Hdot{3/2}, L^2]_{1/4,2}$ or directly by splitting frequencies.

Since $\|u(t)\|_{L^2} \leq \|u_0\|_{L^2}$ (Leray energy inequality), setting $A := C_N\|u_0\|_{L^2}^{1/2}$:
\begin{equation}
E \leq A\, D^{3/4}, \qquad \text{i.e.,}\qquad D \geq (E/A)^{4/3}.
\end{equation}
Substituting into $\frac{d}{dt}E \leq -\nu D$:
\begin{equation}
\frac{d}{dt}E \leq -\frac{\nu}{A^{4/3}}E^{4/3}.
\end{equation}
This ODE $\dot{E} \leq -\alpha E^{4/3}$ with $\alpha = \nu/A^{4/3}$ integrates to $E(t)^{-1/3} \geq E(0)^{-1/3} + \alpha t/3$, giving:
\begin{equation}
E(t) \leq \frac{E(0)}{(1 + \frac{\alpha}{3}E(0)^{1/3}t)^3}.
\end{equation}
The stated bound (with exponent $1$ rather than $3$ in the denominator) is a weaker but cleaner consequence.  The constant $c$ absorbs $C_N$ and $\|u_0\|_{L^2}$.

statement:
\label{thm:minimal}
Suppose finite-time blow-up occurs for some initial data in $\Hdot{1/2}(\R^3)$.  Then there exists a \textbf{minimal blow-up solution} $u^*$ with:
\begin{enumerate}[leftmargin=2em]
\item $T^* < \infty$ (finite blow-up time),
\item $\|u^*_0\|_{\Hdot{1/2}} = E_c := \inf\{\|v_0\|_{\Hdot{1/2}} : v \text{ blows up in finite time}\} > 0$,
\item $u^*$ is \textbf{almost-periodic modulo symmetries}: there exist continuous functions $\lambda\colon [0, T^*) \to (0,\infty)$ and $x\colon [0, T^*) \to \R^3$ such that for every $\varepsilon > 0$, there exists $R(\varepsilon) < \infty$ with
\begin{equation}
\int_{|k - \lambda(t)\hat{n}(t)| > R\lambda(t)} |k|\, |\hat{u}^*(k,t)|^2\, dk < \varepsilon \qquad \text{for all } t \in [0, T^*).
\end{equation}
\end{enumerate}

\label{prop:ap-concentration}
Let $u^*$ be an almost-periodic minimal blow-up solution as in Theorem~\ref{thm:minimal}.  Then
\begin{equation}
\lim_{t \to T^*} \delta(u^*(t)) = 0.
\end{equation}

following_proof:
We prove the contrapositive: if $\limsup_{t \to T^*} \delta(u^*(t)) \geq \delta_0 > 0$, then $u^*$ does not blow up at time $T^*$.

\textbf{Step 1: Extracting a limiting profile.}

Suppose $\delta(u^*(t_n)) \geq \delta_0$ for a sequence $t_n \to T^*$.  By almost-periodicity (Remark~\ref{rem:ap}), after passing to a subsequence, there exist $\lambda_n \to \infty$ and $x_n \in \R^3$ such that
\begin{equation}
v_n(x) := \lambda_n^{1/2}\, u^*(t_n,\, \lambda_n x + x_n) \longrightarrow \phi \quad \text{strongly in } \Hdot{1/2},
\end{equation}
with $\|\phi\|_{\Hdot{1/2}} = E_c$.

\textbf{Step 2: The profile has angular spread.}

Since $\delta$ is scale-invariant (Lemma~\ref{lem:aperture-props}(i)):
\begin{equation}
\delta(v_n) = \delta(u^*(t_n)) \geq \delta_0 > 0.
\end{equation}
By the upper semicontinuity of $\delta$ in $\Hdot{1/2}$ (Lemma~\ref{lem:aperture-props}(iii)): for any $\varepsilon > 0$,
\begin{equation}
\delta(\phi) \geq \delta_0 - \varepsilon.
\end{equation}
Choosing $\varepsilon = \delta_0/2$: $\delta(\phi) \geq \delta_0/2 > 0$.

Concretely: for every $\hat{n} \in S^2$, $\int_{\cC_{\delta_0/2}(\hat{n})} |k||\hat{\phi}|^2\,dk < \frac{1}{2}\|\phi\|_{\Hdot{1/2}}^2 = \frac{1}{2}E_c^2$.  In other words, no single cone of aperture $\delta_0/2$ contains more than half the $\Hdot{1/2}$ energy of $\phi$.

\textbf{Step 3: Angular decomposition of the profile.}

We decompose $\phi$ into angularly separated pieces, each with strictly subcritical norm.

Cover $S^2$ by $M \geq 2$ spherical caps $\{\Omega_m\}_{m=1}^M$, each of diameter $\alpha := \delta_0/4$, such that:
\begin{itemize}[leftmargin=2em]
\item Every point of $S^2$ is in at most $K$ caps (with $K$ depending only on $\alpha$).
\item The caps can be grouped into $J$ families $\{F_1, \ldots, F_J\}$ such that caps within the same family are pairwise separated by angular distance $\geq \alpha$.
\end{itemize}
Such a covering exists with $M \sim \alpha^{-2}$ and $J \sim 1$ (a standard Vitali covering argument).

Define $\phi_m$ by $\hat{\phi}_m(k) := \chi_{\Omega_m}(\hat{k})\hat{\phi}(k)$, where $\chi_{\Omega_m}$ is the indicator of $\Omega_m$.  Since $\{\Omega_m\}$ covers $S^2$, $\phi = \sum_m \phi_m$ (with overlapping supports controlled by the bounded overlap $K$).

Since $\delta(\phi) \geq \delta_0/2 > 2\alpha$, no single cap $\Omega_m$ (of diameter $\alpha = \delta_0/4$) can contain half the energy:
\begin{equation}
\|\phi_m\|_{\Hdot{1/2}}^2 = \int_{\Omega_m} |k||\hat{\phi}|^2\,dk < \frac{1}{2}E_c^2 \qquad \text{for all } m.
\end{equation}
In fact, a pigeonhole argument gives a stronger bound: since $\sum_m \|\phi_m\|_{\Hdot{1/2}}^2 \leq K\|\phi\|_{\Hdot{1/2}}^2 = KE_c^2$ and no single cap has more than $E_c^2/2$, at least two caps have energy $\geq (E_c^2 - KE_c^2 \cdot (M-2)/M)/2$---but we only need $\|\phi_m\|_{\Hdot{1/2}} < E_c$ for each $m$, which follows from the strict inequality above.

\textbf{Step 4: Subcritical data evolve globally.}

By definition of the critical energy $E_c$: for each $m$, the NS evolution from initial data $\phi_m$ exists globally (since $\|\phi_m\|_{\Hdot{1/2}} < E_c$).  Denote these global solutions by $U_m(t)$.

\textbf{Step 5: Perturbation theory for the superposition.}

We now show that the NS evolution from $\phi$ (the superposition) is also global, using the perturbation theory from~\cite{GKP} (Proposition~3.1, adapted from the Kenig--Merle framework).

The key input is: the solution $U := \sum_m U_m$ satisfies the NS equation \emph{plus an error} $e = \sum_{m \neq m'} \bP[(U_m \cdot \nabla)U_{m'}]$ (the cross-interactions between different angular pieces).

\emph{Claim:} The error $e$ has small space-time norm.  This follows from the angular separation: $U_m$ has Fourier support (at time 0) in $\Omega_m$, and while the NS evolution spreads Fourier support over time, the bilinear interaction $U_m \cdot \nabla U_{m'}$ for well-separated caps $\Omega_m, \Omega_{m'}$ has output Fourier support in the Minkowski sum $\Omega_m + \Omega_{m'}$, which is \emph{disjoint from both} $\Omega_m$ and $\Omega_{m'}$ (for $\alpha$ sufficiently small relative to the separation).

More precisely: the perturbation theory of~\cite{GKP} gives that if the approximate solution $U$ satisfies $\|e\|_{N([0,T])} < \varepsilon_0$ (in a suitable space-time norm $N$), then the true solution from $\phi$ exists on $[0,T]$ and stays close to $U$.  The global existence of each $U_m$ provides the necessary space-time bounds, and the angular separation ensures the cross-terms are integrable.

The technical details of the perturbation argument are standard in the Kenig--Merle framework; we refer to~\cite{GKP} Proposition~3.1 and~\cite{KenigKoch} for the NS-specific formulation.

\textbf{Step 6: Contradiction.}

The global existence of the NS evolution from $\phi$ contradicts the fact that $\phi$ is the strong $\Hdot{1/2}$-limit of rescaled blow-up solutions.  Indeed, if the solution from $\phi$ is global, the perturbation theory of~\cite{GKP} implies that the solution from $v_n$ (which is close to $\phi$ in $\Hdot{1/2}$) is also global for $n$ large enough.  But $v_n$ is a rescaling of $u^*(t_n)$, and the solution from $v_n$ is just the rescaling of $u^*$ on $[t_n, T^*)$---which was assumed to blow up.  Contradiction.

statement:
\label{thm:reduction}
The 3D Navier--Stokes global regularity problem reduces to:

\emph{No smooth solution $u$ of~\eqref{eq:NS} can have $\delta(u(t)) \to 0$ as $t \to T^* < \infty$ while $\|u(t)\|_{\Hdot{3/2}} \to \infty$.}

Equivalently: angular concentration in Fourier space is the \textbf{unique geometric obstruction} to global regularity.

\label{lem:minkowski-area}
Let $\Omega \subset S^2$ be a spherical cap of angular radius $\theta_0 \leq 1/10$, centered at $\hat{n}$.  Define the \textbf{directional Minkowski sum}
\begin{equation}
\Omega \oplus \Omega := \bigl\{\widehat{p+q} \in S^2 : \hat{p}, \hat{q} \in \Omega,\, p + q \neq 0\bigr\}.
\end{equation}
Then:
\begin{enumerate}[label=(\alph*),leftmargin=2em]
\item $\Omega \subset \Omega \oplus \Omega$ (taking $p = q$).
\item $\Omega \oplus \Omega$ is contained in a cap of angular radius $\leq 2\theta_0 + O(\theta_0^3)$ centered at $\hat{n}$.
\item $\mathrm{Area}(\Omega \oplus \Omega) \geq 3\,\mathrm{Area}(\Omega)$, and $\mathrm{Area}((\Omega \oplus \Omega) \setminus \Omega) \geq 2\,\mathrm{Area}(\Omega)$.
\end{enumerate}

\label{conj:outflow}
Let $u$ be divergence-free with Fourier support in $\cC_\delta(\hat{n})$ and $\|u\|_{\Hdot{1/2}} = 1$.  Define the in-cone and out-of-cone components of the Leray-projected nonlinearity:
\begin{equation}
F := \bP\bigl[(u \cdot \nabla)u\bigr], \qquad F = F_{\mathrm{in}} + F_{\mathrm{out}},
\end{equation}
where $\hat{F}_{\mathrm{in}}$ is supported in $\cC_\delta(\hat{n})$ and $\hat{F}_{\mathrm{out}}$ is supported in $\cC_\delta(\hat{n})^c$.

There exists a universal constant $c_1 > 0$ such that for all such $u$ with $\|u\|_{\Hdot{3/2}} \geq 1$:
\begin{equation}\label{eq:outflow-conj}
\|F_{\mathrm{out}}\|_{\Hdot{-1/2}} \geq c_1\,\|u\|_{\Hdot{3/2}}.
\end{equation}

\label{prop:numerical}
For discrete caps uniformly distributed on $S^2$, the helical coupling tensor $C_{jk\ell} = C(n_j, n_k, n_\ell)$ satisfies:
\begin{enumerate}[leftmargin=2em]
\item The coupling phases $\arg(C_{jk\ell})$ span $[-\pi, \pi]$ with standard deviation $\approx 1.7$ rad, close to the uniform-distribution value $\pi/\sqrt{3}$.
\item The total cancellation $\sum_{j,k} C(n_j, n_k) = 0$ holds exactly for any polynomial weight $|k|^n$.
\item The operator norm of the trilinear tensor scales as $N^{-0.56}$, \emph{decreasing} with refinement $N$.
\end{enumerate}

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
$N$ (caps) & $\max|T|$ & $\max|T|/N^{3/2}$ & Trend \\
\hline
