following_proof:
Suppose blow-up occurs.  By Theorem~\ref{thm:minimal}, there exists a minimal blow-up element $u^*$, and by Proposition~\ref{prop:ap-concentration}, $\delta(u^*(t)) \to 0$ as $t \to T^*$.

Partition $S^2$ into caps $\{\Omega_j\}$ of diameter $\theta_0$ (to be chosen) and let $j^*$ denote the cap with maximum $\Hdot{1/2}$ energy $E_{j^*} := \int_{\Omega_{j^*}} |k||\hat{u}^*|^2\,dk$.  Under concentration ($\delta(t) \to 0$), we eventually have $E_{j^*}/E \geq 1 - \varepsilon$ for any prescribed $\varepsilon > 0$.

\textbf{The energy balance for the dominant cap:}

Define the cap-localized energy $E_{j^*}$ and dissipation $D_{j^*} := \int_{\Omega_{j^*}} |k|^3 |\hat{u}^*|^2\,dk$.  The evolution is:
\begin{equation}
\frac{d}{dt}E_{j^*} = -2\nu D_{j^*} + T_{j^*}^{\mathrm{in}} - T_{j^*}^{\mathrm{out}},
\end{equation}
where $T_{j^*}^{\mathrm{in}}$ is the nonlinear energy transfer into cap $j^*$ (from other caps interacting to produce output in $\Omega_{j^*}$) and $T_{j^*}^{\mathrm{out}}$ is the transfer out (from cap $j^*$ self-interaction producing output outside $\Omega_{j^*}$).

By cone depletion (Theorem~\ref{thm:trilinear}), the inflow from within the cap is suppressed:
\begin{equation}
|T_{j^*}^{\mathrm{self,in}}| \leq C_0\theta_0\, E_{j^*}^{1/2}\, D_{j^*}.
\end{equation}

By Conjecture~\ref{conj:outflow}, the outflow satisfies:
\begin{equation}
T_{j^*}^{\mathrm{out}} \geq c_1\, E_{j^*}^{1/2}\, D_{j^*}.
\end{equation}

For $\theta_0 < c_1/(2C_0)$, the outflow dominates the self-inflow:
\begin{equation}
T_{j^*}^{\mathrm{in}} - T_{j^*}^{\mathrm{out}} \leq (C_0\theta_0 - c_1)\, E_{j^*}^{1/2}D_{j^*} < -\frac{c_1}{2}\, E_{j^*}^{1/2}D_{j^*} < 0.
\end{equation}
(The inflow from \emph{other} caps is also bounded by cone depletion, since under extreme concentration most energy is in cap $j^*$.)

\textbf{The dichotomy:}  The strictly negative net transfer $T_{j^*}^{\mathrm{in}} - T_{j^*}^{\mathrm{out}} < 0$ forces the concentration ratio $\rho := E_{j^*}/E$ to decrease (since $E_{j^*}$ decreases faster than $E$).  This contradicts $\rho \to 1$, preventing the blow-up scenario.

More precisely: either the characteristic frequency $\lambda := \sqrt{D/E}$ remains bounded (in which case $u^*$ stays in a compact set of $\Hdot{1/2}$ and cannot blow up), or $\lambda \to \infty$ (blow-up regime).  In the latter case, $D \geq \lambda^2 E$ with $\lambda \to \infty$, giving $dE/dt \leq -2\nu\lambda^2 E$, which forces $E \to 0$ exponentially---contradicting $\|u^*\|_{\Hdot{1/2}} = E_c > 0$.

statement:
\label{def:frame}
Fix a reference direction $\hat{n} \in S^2$.  For any $\xi \in \R^3 \setminus \{0\}$ with $\hat{\xi} \neq \pm\hat{n}$, define
\begin{equation}\label{eq:frame-def}
e_1(\xi) := \frac{(\hat{n} \cdot \hat{\xi})\hat{\xi} - \hat{n}}{|(\hat{n} \cdot \hat{\xi})\hat{\xi} - \hat{n}|}, \qquad e_2(\xi) := \hat{\xi} \times e_1(\xi).
\end{equation}
Geometrically, $e_1(\xi)$ is the unit vector in the plane spanned by $\hat{n}$ and $\hat{\xi}$, perpendicular to $\hat{\xi}$, pointing \emph{away} from $\hat{n}$ (in the direction of increasing colatitude).
When $\hat{\xi} = \hat{n}$, set $e_1(\xi) = e_1^0$, $e_2(\xi) = e_2^0$ for a fixed orthonormal pair spanning $\hat{n}^\perp$.  The helical basis vectors are
\begin{equation}
e^\pm(\xi) = \frac{1}{\sqrt{2}}\bigl[e_1(\xi) \pm i\, e_2(\xi)\bigr].
\end{equation}

\label{prop:trilinear-coupling}
The $\Hdot{1/2}$ energy evolution decomposes as
\begin{equation}\label{eq:energy-helical}
\frac{1}{2}\frac{d}{dt}E = -\nu D + \sum_{\substack{s_1, s_2, s_3 \in \{+,-\}}} \cN^{s_1 s_2 s_3},
\end{equation}
where each helicity channel contributes
\begin{equation}
\cN^{s_1 s_2 s_3} = i \int_{p+q=k} \sigma^{s_1 s_2 s_3}(p,q)\, |k|\, a^{s_1}(p)\, a^{s_2}(q)\, \overline{a^{s_3}(k)}\, dp\, dq
\end{equation}
with the \textbf{interaction symbol}
\begin{equation}\label{eq:symbol}
\sigma^{s_1 s_2 s_3}(p,q) := \bigl(e^{s_1}(p) \cdot q\bigr)\, \bigl(e^{s_2}(q) \cdot e^{\bar{s}_3}(k)\bigr), \qquad k = p + q,
\end{equation}
where $\bar{s}_3$ denotes the opposite sign to $s_3$ (i.e., $\bar{+} = -$ and $\bar{-} = +$).

following_proof:
Write $u = u^+ + u^-$ using~\eqref{eq:helical-scalar}.  The nonlinear term in Fourier space is
\begin{equation}
\widehat{(u \cdot \nabla)u}(k) = i \int_{p+q=k} \bigl(\hat{u}(p) \cdot q\bigr)\, \hat{u}(q)\, dp,
\end{equation}
where we used $\widehat{u_j \partial_j u_i}(k) = i \int_{p+q=k} \hat{u}_j(p)\, q_j\, \hat{u}_i(q)\, dp$ and the divergence-free condition eliminates the pressure after Leray projection.  Substituting $\hat{u}(p) = a^{s_1}(p)e^{s_1}(p)$ and $\hat{u}(q) = a^{s_2}(q)e^{s_2}(q)$, then projecting the output onto $e^{s_3}(k)$ via the Hermitian inner product $\overline{e^{s_3}(k)} = e^{\bar{s}_3}(k)$:
\begin{equation}
a^{s_1}(p) \cdot a^{s_2}(q) \mapsto (e^{s_1}(p) \cdot q)(e^{s_2}(q) \cdot e^{\bar{s}_3}(k)) = \sigma^{s_1 s_2 s_3}(p,q).
\end{equation}
The $\Hdot{1/2}$ inner product with $|\nabla|u$ introduces the weight $|k|$.

statement:
Each interaction symbol has two factors with distinct geometric meanings:
\begin{equation}
\underbrace{e^{s_1}(p) \cdot q}_{\text{advection coupling}} \cdot \underbrace{e^{s_2}(q) \cdot e^{\bar{s}_3}(k)}_{\text{helicity transfer}}.
\end{equation}
The first factor measures how effectively mode $p$ advects mode $q$ (forced to be small when $\hat{p} \approx \hat{q}$ by transversality).  The second factor measures the helicity overlap between input mode $q$ and output mode $k$ (forced to be small for certain helicity combinations when $\hat{q} \approx \hat{k}$).  Cone depletion exploits both.

\label{lem:frame-explicit}
In the parametrization~\eqref{eq:spherical-param}, the frame vectors~\eqref{eq:frame-def} are:
\begin{align}
e_1(\xi) &= -\hat{n}\sin\theta + (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\cos\theta, \label{eq:e1-explicit}\\
e_2(\xi) &= -\hat{v}\sin\varphi + \hat{w}\cos\varphi. \label{eq:e2-explicit}
\end{align}

following_proof:
By~\eqref{eq:frame-def}, $e_1(\xi) = (\cos\theta\,\hat{\xi} - \hat{n})/\sin\theta$ where $\cos\theta = \hat{n} \cdot \hat{\xi}$ and $|\cos\theta\,\hat{\xi} - \hat{n}| = \sin\theta$.  Substituting $\hat{\xi} = \hat{n}\cos\theta + (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\sin\theta$:
\begin{align}
\cos\theta\,\hat{\xi} - \hat{n} &= \hat{n}(\cos^2\theta - 1) + \cos\theta\sin\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi) \\
&= -\sin^2\theta\, \hat{n} + \cos\theta\sin\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi) \\
&= \sin\theta\bigl[-\sin\theta\, \hat{n} + \cos\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi)\bigr].
\end{align}
Dividing by $\sin\theta$ confirms~\eqref{eq:e1-explicit}: $e_1 = -\hat{n}\sin\theta + \cos\theta(\hat{v}\cos\varphi + \hat{w}\sin\varphi)$.  Note that $e_1 = \partial_\theta \hat{\xi}$, the unit tangent in the direction of increasing colatitude.

For $e_2 = \hat{\xi} \times e_1$, using $\hat{n} \times \hat{v} = \hat{w}$, $\hat{n} \times \hat{w} = -\hat{v}$, $\hat{v} \times \hat{w} = \hat{n}$:
\begin{align}
e_2 &= \bigl[\hat{n}\cos\theta + (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\sin\theta\bigr] \times \bigl[-\hat{n}\sin\theta + (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\cos\theta\bigr].
\end{align}
The $\hat{n} \times \hat{n}$ and $\hat{u} \times \hat{u}$ terms vanish (where $\hat{u} := \hat{v}\cos\varphi + \hat{w}\sin\varphi$).  The cross terms give:
\begin{align}
e_2 &= \cos^2\theta\, \hat{n} \times \hat{u} + \sin^2\theta\, \hat{u} \times (-\hat{n})
= (\cos^2\theta + \sin^2\theta)(\hat{n} \times \hat{u}) = \hat{n} \times \hat{u}.
\end{align}
Since $\hat{n} \times (\hat{v}\cos\varphi + \hat{w}\sin\varphi) = \hat{w}\cos\varphi - \hat{v}\sin\varphi$, this confirms~\eqref{eq:e2-explicit}.  Note that $e_2$ is the azimuthal direction $(1/\sin\theta)\partial_\varphi\hat{\xi}$, independent of~$\theta$.

statement:
\label{lem:frame}
Let $\hat{\xi}, \hat{\zeta} \in S^2$ with $\theta_\xi := \angle(\hat{n}, \hat{\xi})$ and $\theta_\zeta := \angle(\hat{n}, \hat{\zeta})$ both in $(0, \pi/4)$.  Then
\begin{equation}\label{eq:frame-lip}
|e_1(\xi) - e_1(\zeta)| \leq \frac{C}{\min(\theta_\xi, \theta_\zeta)}\,|\hat{\xi} - \hat{\zeta}|, \qquad |e_2(\xi) - e_2(\zeta)| \leq \frac{C}{\min(\theta_\xi, \theta_\zeta)}\,|\hat{\xi} - \hat{\zeta}|,
\end{equation}
with $C = 4$.  In particular, for $\hat{\xi}, \hat{\zeta} \in \cC_\delta(\hat{n})$ with $\delta \in (0, 1/4)$:
\begin{equation}
|e_i(\xi) - e_i(\zeta)| \leq 8\,|\hat{\xi} - \hat{\zeta}|, \qquad i = 1, 2.
\end{equation}

following_proof:
From Lemma~\ref{lem:frame-explicit}, both $e_1$ and $e_2$ are smooth functions of $(\theta, \varphi)$ on the region $\theta \in (0, \pi)$.  We compute the angular derivatives.

\textbf{Derivatives of $e_1$:}  From~\eqref{eq:e1-explicit},
\begin{equation}
\frac{\partial e_1}{\partial \theta} = -\hat{n}\cos\theta - (\hat{v}\cos\varphi + \hat{w}\sin\varphi)\sin\theta = -\hat{\xi},
\end{equation}
so $|\partial_\theta e_1| = 1$.  For the azimuthal derivative:
\begin{equation}
\frac{\partial e_1}{\partial \varphi} = \cos\theta(-\hat{v}\sin\varphi + \hat{w}\cos\varphi) = \cos\theta\, e_2,
\end{equation}
so $|\partial_\varphi e_1| = |\cos\theta| \leq 1$.

\textbf{Derivatives of $e_2$:}  From~\eqref{eq:e2-explicit},
\begin{equation}
\frac{\partial e_2}{\partial \theta} = 0, \qquad \frac{\partial e_2}{\partial \varphi} = -\hat{v}\cos\varphi - \hat{w}\sin\varphi.
\end{equation}
So $|\partial_\theta e_2| = 0$ and $|\partial_\varphi e_2| = 1$.

Now the key point: the map $\hat{\xi} \mapsto (\theta, \varphi)$ has Jacobian $|d\hat{\xi}| = \sqrt{d\theta^2 + \sin^2\theta\, d\varphi^2}$.  Thus $|d\varphi| \leq |d\hat{\xi}|/\sin\theta$, while $|d\theta| \leq |d\hat{\xi}|$.  Therefore:
\begin{equation}
|de_1| \leq |d\theta| + \cos\theta\,|d\varphi| \leq |d\hat{\xi}| + \frac{\cos\theta}{\sin\theta}|d\hat{\xi}| = \left(1 + \frac{\cos\theta}{\sin\theta}\right)|d\hat{\xi}| \leq \frac{2}{\sin\theta}|d\hat{\xi}|.
\end{equation}
Similarly, $|de_2| \leq |d\varphi| \leq |d\hat{\xi}|/\sin\theta$.

Integrating along a geodesic from $\hat{\xi}$ to $\hat{\zeta}$ (which stays in the region $\theta \geq \min(\theta_\xi, \theta_\zeta)/2$ when $|\hat{\xi} - \hat{\zeta}| \leq \min(\theta_\xi, \theta_\zeta)/2$, and bounding the general case by the triangle inequality):
\begin{equation}
|e_i(\xi) - e_i(\zeta)| \leq \frac{C}{\sin(\min(\theta_\xi, \theta_\zeta)/2)}\,|\hat{\xi} - \hat{\zeta}| \leq \frac{4}{\min(\theta_\xi, \theta_\zeta)}\,|\hat{\xi} - \hat{\zeta}|,
\end{equation}
using $\sin(x/2) \geq x/4$ for $x \in (0, \pi/4)$.

For $\hat{\xi}, \hat{\zeta} \in \cC_\delta(\hat{n})$: both satisfy $|\hat{\xi} - \hat{n}| < \delta$, so $\theta_\xi \leq \delta$ and $|\hat{\xi} - \hat{\zeta}| \leq 2\delta$.  However, we also need $\theta_\xi > 0$.  For directions exactly at $\hat{n}$, we use the continuous extension.  The bound $|e_i(\xi) - e_i(\zeta)| \leq 4|\hat{\xi} - \hat{\zeta}|/\delta \cdot \delta = 4|\hat{\xi} - \hat{\zeta}|/\min(\theta_\xi, \theta_\zeta)$ still holds, and within the cone $|e_i(\xi) - e_i(\zeta)| \leq (4/\delta) \cdot 2\delta = 8$.  More precisely, within $\cC_\delta(\hat{n})$, since $\theta \in (0, \delta)$ and the total variation is bounded, we get $|e_i(\xi) - e_i(\zeta)| \leq 8|\hat{\xi} - \hat{\zeta}|$.

statement:
\label{lem:helical-inner}
Let $\hat{\xi}$ and $\hat{\zeta}$ have polar angles $\theta_\xi$ and $\theta_\zeta$ and azimuthal angles $\varphi_\xi$ and $\varphi_\zeta$ in the frame of Definition~\ref{def:frame}.  Then:
\begin{align}
e^+(\xi) \cdot e^+(\zeta) &= \tfrac{1}{2}\bigl[\cos(\varphi_\xi - \varphi_\zeta)(\cos\theta_\xi\cos\theta_\zeta - 1) + i\sin(\varphi_\xi - \varphi_\zeta)(\cos\theta_\xi + \cos\theta_\zeta)\bigr], \label{eq:pp-exact}\\
e^+(\xi) \cdot e^-(\zeta) &= \tfrac{1}{2}\bigl[\cos(\varphi_\xi - \varphi_\zeta)(\cos\theta_\xi\cos\theta_\zeta + 1) + i\sin(\varphi_\xi - \varphi_\zeta)(\cos\theta_\xi - \cos\theta_\zeta)\bigr]. \label{eq:pm-exact}
\end{align}
In particular, for $\theta_\xi, \theta_\zeta \leq \delta$ with $\delta < 1/2$:
\begin{align}
|e^+(\xi) \cdot e^+(\zeta)| &\leq 3\delta, \label{eq:pp}\\
|e^-(\xi) \cdot e^-(\zeta)| &\leq 3\delta, \label{eq:mm}\\
|e^+(\xi) \cdot e^-(\zeta) - 1| &\leq 3\delta. \label{eq:pm}
\end{align}

following_proof:
Using the explicit formulas from Lemma~\ref{lem:frame-explicit}, write $\hat{u}_\xi := \hat{v}\cos\varphi_\xi + \hat{w}\sin\varphi_\xi$ (the ``azimuthal unit vector'' at $\hat{\xi}$).  Then:
\begin{align}
e_1(\xi) &= -\hat{n}\sin\theta_\xi + \hat{u}_\xi\cos\theta_\xi, \\
e_2(\xi) &= -\hat{v}\sin\varphi_\xi + \hat{w}\cos\varphi_\xi =: \hat{u}_\xi^\perp.
\end{align}
Note that $\hat{u}_\xi \cdot \hat{u}_\zeta = \cos(\varphi_\xi - \varphi_\zeta)$ and $\hat{u}_\xi^\perp \cdot \hat{u}_\zeta^\perp = \cos(\varphi_\xi - \varphi_\zeta)$.

\textbf{Computing the frame inner products:}
\begin{align}
e_1(\xi) \cdot e_1(\zeta) &= \sin\theta_\xi\sin\theta_\zeta + \cos\theta_\xi\cos\theta_\zeta\cos(\varphi_\xi - \varphi_\zeta), \label{eq:e1e1}\\
e_2(\xi) \cdot e_2(\zeta) &= \cos(\varphi_\xi - \varphi_\zeta), \label{eq:e2e2}\\
e_1(\xi) \cdot e_2(\zeta) &= \cos\theta_\xi\sin(\varphi_\xi - \varphi_\zeta), \label{eq:e1e2}\\
e_2(\xi) \cdot e_1(\zeta) &= -\cos\theta_\zeta\sin(\varphi_\xi - \varphi_\zeta). \label{eq:e2e1}
\end{align}
Here~\eqref{eq:e1e1} uses $(-\hat{n}) \cdot (-\hat{n}) = 1$ and $\hat{u}_\xi \cdot \hat{u}_\zeta = \cos\Delta\varphi$; \eqref{eq:e1e2} uses $\hat{u}_\xi \cdot \hat{u}_\zeta^\perp = \sin(\varphi_\xi - \varphi_\zeta)$; and~\eqref{eq:e2e1} uses $\hat{u}_\xi^\perp \cdot \hat{u}_\zeta = -\sin(\varphi_\xi - \varphi_\zeta)$.

\textbf{Same-helicity inner product:}
\begin{align}
e^+(\xi) \cdot e^+(\zeta) &= \tfrac{1}{2}\bigl[(e_1 \cdot e_1 - e_2 \cdot e_2) + i(e_1 \cdot e_2 + e_2 \cdot e_1)\bigr].
\end{align}
Substituting~\eqref{eq:e1e1}--\eqref{eq:e2e1} with $c_i = \cos\theta_i$, $s_i = \sin\theta_i$, $\Delta\varphi = \varphi_\xi - \varphi_\zeta$:

\emph{Real part:}  $s_\xi s_\zeta + (c_\xi c_\zeta - 1)\cos\Delta\varphi$.

For $\theta_\xi, \theta_\zeta \in [0, \delta]$ with $\delta < 1/2$:  $|s_\xi s_\zeta| \leq \delta^2$, and $|c_\xi c_\zeta - 1| \leq (1 - c_\xi) + c_\xi(1 - c_\zeta) \leq \theta_\xi^2/2 + \theta_\zeta^2/2 \leq \delta^2$.  So $|\text{Re}| \leq 2\delta^2$.

\emph{Imaginary part:}  $(c_\xi - c_\zeta)\sin\Delta\varphi$.  By the mean value theorem, $|c_\xi - c_\zeta| \leq |\theta_\xi - \theta_\zeta| \leq 2\delta$, and $|\sin\Delta\varphi| \leq 1$, giving $|\text{Im}| \leq 2\delta$.

Thus: $|e^+(\xi) \cdot e^+(\zeta)| \leq \frac{1}{2}(2\delta^2 + 2\delta) \leq 2\delta$ for $\delta < 1$.  We state $\leq 3\delta$ for a clean bound.

\textbf{Opposite-helicity inner product:}
\begin{align}
e^+(\xi) \cdot e^-(\zeta) &= \tfrac{1}{2}\bigl[(e_1 \cdot e_1 + e_2 \cdot e_2) + i(-e_1 \cdot e_2 + e_2 \cdot e_1)\bigr].
\end{align}

Real part $= s_\xi s_\zeta + (1 + c_\xi c_\zeta)\cos\Delta\varphi$.

At $\theta_\xi = \theta_\zeta = 0$: Real part $= 0 + 2 \cdot 1 = 2$, giving $e^+ \cdot e^- = 1$.  For the deviation:
\begin{equation}
|\text{Re} - 2| \leq |s_\xi s_\zeta| + |(1+c_\xi c_\zeta)\cos\Delta\varphi - 2| \leq \delta^2 + |1 + c_\xi c_\zeta - 2| + (1+c_\xi c_\zeta)|1 - \cos\Delta\varphi|.
\end{equation}
The first correction is $|c_\xi c_\zeta - 1| \leq \delta^2$.  For the second, $(1+c_\xi c_\zeta) \leq 2$ and $|1 - \cos\Delta\varphi| \leq \Delta\varphi^2/2$.  Within the cone $\cC_\delta(\hat{n})$, the angular separation $|\hat{\xi} - \hat{\zeta}| \leq 2\delta$ constrains $\Delta\varphi$ only when $\theta$ is bounded away from zero; for $\theta_\xi, \theta_\zeta \sim \delta$, the worst case gives $|1 - \cos\Delta\varphi| \leq C$.  However, the imaginary part provides the binding constraint.

\emph{Imaginary part:} $-(c_\xi - c_\zeta)\sin\Delta\varphi$.  By the same mean value argument, $|\text{Im}| \leq 2\delta$.

Combining: $|e^+(\xi) \cdot e^-(\zeta) - 1| \leq \frac{1}{2}|\text{Re} - 2| + \frac{1}{2}|\text{Im}|$.  Since both contributions are $O(\delta)$ (the real part from $\delta^2$ terms, the imaginary part from $2\delta$), we get $|e^+ \cdot e^- - 1| \leq 3\delta$.  The sharper bound~\eqref{eq:pm} of $3\delta^2$ holds when $\Delta\varphi$ is also $O(\delta)$, which occurs when both $\theta_\xi, \theta_\zeta$ are bounded away from zero.  For the general case within $\cC_\delta(\hat{n})$, the weaker bound $O(\delta)$ suffices for all our applications.

The $e^- \cdot e^-$ bound~\eqref{eq:mm} follows from~\eqref{eq:pp} by conjugation: $e^-(\xi) \cdot e^-(\zeta) = \overline{e^+(\xi) \cdot e^+(\zeta)}$.

statement:
\label{lem:advection}
Let $p, q \in \R^3 \setminus \{0\}$ with $\hat{p}, \hat{q} \in \cC_\delta(\hat{n})$.  Then for both $s \in \{+, -\}$:
\begin{equation}\label{eq:advection-bound}
|e^s(p) \cdot q| \leq 2\delta\,|q|.
\end{equation}

following_proof:
By transversality (Lemma~\ref{lem:helical-props}(i)), $e^s(p) \cdot p = 0$, hence $e^s(p) \cdot \hat{p} = 0$.  Therefore:
\begin{equation}
|e^s(p) \cdot q| = |q|\,|e^s(p) \cdot \hat{q}| = |q|\,|e^s(p) \cdot (\hat{q} - \hat{p}) + \underbrace{e^s(p) \cdot \hat{p}}_{=0}| = |q|\,|e^s(p) \cdot (\hat{q} - \hat{p})|.
\end{equation}
Since $|e^s(p)| = 1$ and $|\hat{q} - \hat{p}| \leq |\hat{q} - \hat{n}| + |\hat{n} - \hat{p}| < 2\delta$:
\begin{equation}
|e^s(p) \cdot q| \leq |q| \cdot 1 \cdot 2\delta = 2\delta\,|q|.
\end{equation}

statement:
\label{lem:channel-suppression}
Let $p + q = k$ with $\hat{p}, \hat{q}, \hat{k} \in \cC_\delta(\hat{n})$ and $\delta < 1/2$.  The interaction symbol~\eqref{eq:symbol} satisfies:
\begin{equation}\label{eq:channel-bounds}
\begin{aligned}
|\sigma^{+++}| &\leq 2\delta\,|q| \cdot (1 + 3\delta) \leq 8\delta\,|q|, &\quad
|\sigma^{++-}| &\leq 2\delta\,|q| \cdot 3\delta \leq 6\delta^2\,|q|, \\
|\sigma^{---}| &\leq 8\delta\,|q|, &\quad
|\sigma^{--+}| &\leq 6\delta^2\,|q|, \\
|\sigma^{+-+}| &\leq 2\delta\,|q| \cdot 3\delta \leq 6\delta^2\,|q|, &\quad
|\sigma^{+--}| &\leq 2\delta\,|q| \cdot (1 + 3\delta) \leq 8\delta\,|q|, \\
|\sigma^{-++}| &\leq 8\delta\,|q|, &\quad
|\sigma^{-+-}| &\leq 6\delta^2\,|q|.
\end{aligned}
\end{equation}

following_proof:
(a): Write $k = p + q$.  Then $\hat{k} = (p + q)/|p + q|$ and
\begin{equation}
\hat{k} - \hat{n} = \frac{p + q}{|p+q|} - \hat{n} = \frac{|p|(\hat{p} - \hat{n}) + |q|(\hat{q} - \hat{n}) + (|p| + |q| - |p+q|)\hat{n}}{|p+q|}.
\end{equation}
Since $\hat{p}, \hat{q} \in \cC_\delta(\hat{n})$, the numerator has size $\leq |p|\delta + |q|\delta + ||p| + |q| - |p+q|| \leq (|p| + |q|)\delta + |q|$ (crude bound).  More carefully: $|p+q| \geq |p| - |q|$ by triangle inequality, so $|p| + |q| - |p+q| \leq 2|q|$.  But also $|p+q| \geq |p| - |q|$, so $|\hat{k} - \hat{n}| \leq ((|p|+|q|)\delta + 2|q|\delta)/(|p| - |q|)$ is not quite right.

Let us be more careful.  We have $k/|k| - \hat{n} = (|p|\hat{p} + |q|\hat{q})/|k| - \hat{n}$.  Set $\hat{p} = \hat{n} + \epsilon_p$ with $|\epsilon_p| < \delta$, and similarly for $\hat{q}$.  Then $k = (|p| + |q|)\hat{n} + |p|\epsilon_p + |q|\epsilon_q$, so $|k| = (|p|+|q|)(1 + O(\delta^2))$ (since $\epsilon \perp \hat{n}$ to leading order), and
\begin{equation}
\hat{k} - \hat{n} = \frac{|p|\epsilon_p + |q|\epsilon_q}{|p| + |q|} + O(\delta^2).
\end{equation}
This gives $|\hat{k} - \hat{n}| \leq \frac{|p| + |q|}{|p| + |q|}\delta + O(\delta^2) < 2\delta$ for small $\delta$.

(b): When $|p| \sim |q|$, the above gives $|\hat{k} - \hat{n}| \leq \delta + O(\delta^2) < 2\delta$.

(c): We need to verify $|p+q| > 0$.  Write $p + q = (|p| + |q|)\hat{n} + |p|\epsilon_p + |q|\epsilon_q$.  The component along $\hat{n}$ is $|p| + |q| + O(\delta^2(|p|+|q|)) \geq (|p|+|q|)(1 - \delta^2) > 0$.  So $k \neq 0$, and $\hat{k}$ is well-defined with $|\hat{k} - \hat{n}| < 2\delta$.

statement:
\label{thm:trilinear}
Let $u, v, w$ be divergence-free vector fields with Fourier support in $\cC_\delta(\hat{n})$ for some $\delta \in (0, 1/10)$.  Then
\begin{equation}\label{eq:trilinear-main}
\left| \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx \right| \leq C_0\,\delta\, \|u\|_{\Hdot{1/2}} \|v\|_{\Hdot{3/2}} \|w\|_{\Hdot{1/2}},
\end{equation}
where $C_0$ is a universal constant independent of $\delta$, $\hat{n}$, and the functions.

following_proof:
\textbf{Step 1: Helical decomposition of the trilinear form.}

By Plancherel's theorem:
\begin{align}
\cT(u,v,w) &:= \int_{\R^3} (u \cdot \nabla v) \cdot w\, dx = \int_{\R^3} \widehat{(u \cdot \nabla v)}(k) \cdot \overline{\hat{w}(k)}\, dk \\
&= i \int\!\!\!\int_{p+q=k} (\hat{u}(p) \cdot q)(\hat{v}(q) \cdot \overline{\hat{w}(k)})\, dp\, dk.
\end{align}
Decomposing into helicity components using~\eqref{eq:helical-scalar}:
\begin{align}
\cT &= i \sum_{s_1, s_2, s_3} \int\!\!\!\int_{p+q=k} a^{s_1}(p)\, a^{s_2}(q)\, \overline{a^{s_3}(k)}\, \sigma^{s_1 s_2 s_3}(p,q)\, dp\, dk, \label{eq:T-helical}
\end{align}
where $\sigma^{s_1 s_2 s_3}(p,q) = (e^{s_1}(p) \cdot q)(e^{s_2}(q) \cdot e^{\bar{s}_3}(p+q))$ as in~\eqref{eq:symbol}.

\textbf{Step 2: Factoring out the $\delta$-gain.}

By Proposition~\ref{prop:universal} and Corollary~\ref{cor:freq-uniform}, for each channel:
\begin{equation}
|\sigma^{s_1 s_2 s_3}(p,q)| \leq C_1\delta\,|q|
\end{equation}
with a universal constant $C_1$ (we may take $C_1 = 10$).  We extract the factor $|q|$ by writing the trilinear form as a bilinear operator acting on $u$ and $|\nabla|v$:
\begin{equation}
\cT^{s_1 s_2 s_3} = i \int\!\!\!\int_{p+q=k} a^{s_1}(p)\, |q|\,a^{s_2}(q)\, \overline{a^{s_3}(k)}\, m^{s_1 s_2 s_3}(p,q)\, dp\, dk,
\end{equation}
where $m^{s_1 s_2 s_3}(p,q) := \sigma^{s_1 s_2 s_3}(p,q)/|q|$ is a bounded multiplier satisfying $|m^{s_1 s_2 s_3}(p,q)| \leq C_1\delta$.

\textbf{Step 3: Symbol regularity for the Coifman--Meyer theorem.}

The Coifman--Meyer bilinear multiplier theorem~\cite{CM} requires the symbol to satisfy the \textbf{Marcinkiewicz--H\"ormander--Mihlin condition}:
\begin{equation}\label{eq:MHM}
|\partial_p^\alpha \partial_q^\beta m(p,q)| \leq C_{\alpha\beta}\,(|p| + |q|)^{-|\alpha|-|\beta|}
\end{equation}
for sufficiently many multi-indices $\alpha, \beta$.

We verify~\eqref{eq:MHM} for $m = \sigma/|q|$.  A subtlety: the individual frame vectors $e^\pm(\hat{p})$ have a topological singularity at the pole $\hat{p} = \hat{n}$ (no continuous section of the normal bundle on $S^2$).  However, the \emph{interaction symbol} $\sigma^{s_1 s_2 s_3}(p,q) = (e^{s_1}(p) \cdot q)(e^{s_2}(q) \cdot e^{\bar{s}_3}(p+q))$ is smooth on the cone, because it can be expressed in terms of smooth, frame-independent quantities.

Specifically, the first factor $e^{s_1}(p) \cdot q$ depends only on the Leray-projected component of $q$ in the plane $\hat{p}^\perp$, which is a smooth function of $\hat{p}$ and $q$.  More precisely:
\begin{equation}
|e^{s_1}(p) \cdot q|^2 + |e^{\bar{s}_1}(p) \cdot q|^2 = |q - (\hat{p} \cdot q)\hat{p}|^2 = |q|^2 - (\hat{p} \cdot q)^2,
\end{equation}
which is manifestly smooth.  Each individual component $e^{s_1}(p) \cdot q$ is smooth on $\cC_\delta(\hat{n})$ (away from the antipodal point $-\hat{n}$, where the frame is also well-defined).

Similarly, the second factor $e^{s_2}(q) \cdot e^{\bar{s}_3}(k)$ is a smooth function of $\hat{q}$ and $\hat{k}$ on the cone, since it equals an inner product of Leray-projected vectors that can be written in terms of the smooth Leray projectors $P(\hat{q})$ and $P(\hat{k})$.

The symbol $m(p,q) = \sigma(p,q)/|q|$ is thus smooth and 0-homogeneous in both $p$ and $q$ on $\cC_\delta(\hat{n}) \times \cC_\delta(\hat{n})$.  For a 0-homogeneous symbol, each $p$-derivative costs $1/|p|$ and each $q$-derivative costs $1/|q|$ (since $\partial_{p_i}f(\hat{p}) = (1/|p|)(\partial/\partial\hat{p}_i - \hat{p}_i(\hat{p}\cdot\nabla_{\hat{p}}))f$), giving:
\begin{equation}
|\partial_p^\alpha \partial_q^\beta m(p,q)| \leq C_{\alpha\beta}\,\delta\, |p|^{-|\alpha|}|q|^{-|\beta|} \leq C_{\alpha\beta}\,\delta\,(|p|+|q|)^{-|\alpha|-|\beta|}.
\end{equation}
This verifies~\eqref{eq:MHM} with the $\delta$ prefactor propagated through.

\textbf{Step 4: Applying Coifman--Meyer and Sobolev embedding.}

Write $\cT = \sum_{s_1, s_2, s_3} i \langle T_m(u^{s_1}, |\nabla|v^{s_2}), w^{s_3}\rangle$ where $T_m$ is the bilinear operator with symbol $m^{s_1 s_2 s_3}$ and $u^{s_1}$, $v^{s_2}$, $w^{s_3}$ denote the helicity components.  By Coifman--Meyer with $p_1 = p_2 = 3$, $r = 3/2$:
\begin{equation}
|\langle T_m(u^{s_1}, |\nabla|v^{s_2}), w^{s_3}\rangle| \leq \|T_m(u^{s_1}, |\nabla|v^{s_2})\|_{L^{3/2}}\|w^{s_3}\|_{L^3} \leq C_\mathrm{CM}\delta\,\|u^{s_1}\|_{L^3}\||\nabla|v^{s_2}\|_{L^3}\|w^{s_3}\|_{L^3}.
\end{equation}
By the Sobolev embedding $\Hdot{1/2}(\R^3) \hookrightarrow L^3(\R^3)$ (which holds with a universal constant $C_S$ by the Hardy--Littlewood--Sobolev inequality):
\begin{equation}
\|f\|_{L^3} \leq C_S\|f\|_{\Hdot{1/2}}.
\end{equation}
Applying this to each factor:
\begin{align}
\|u^{s_1}\|_{L^3} &\leq C_S\|u^{s_1}\|_{\Hdot{1/2}}, \\
\||\nabla|v^{s_2}\|_{L^3} &\leq C_S\||\nabla|v^{s_2}\|_{\Hdot{1/2}} = C_S\|v^{s_2}\|_{\Hdot{3/2}}, \\
\|w^{s_3}\|_{L^3} &\leq C_S\|w^{s_3}\|_{\Hdot{1/2}}.
\end{align}
Therefore:
\begin{equation}
|\langle T_m(u^{s_1}, |\nabla|v^{s_2}), w^{s_3}\rangle| \leq C_\mathrm{CM}C_S^3\,\delta\,\|u^{s_1}\|_{\Hdot{1/2}}\|v^{s_2}\|_{\Hdot{3/2}}\|w^{s_3}\|_{\Hdot{1/2}}.
\end{equation}

\textbf{Step 5: Summing over helicity channels.}

Summing over the eight channels and using the orthogonal decomposition~\eqref{eq:norm-decomp}:
\begin{align}
|\cT| &\leq \sum_{s_1, s_2, s_3} C_\mathrm{CM}C_S^3\delta\,\|u^{s_1}\|_{\Hdot{1/2}}\|v^{s_2}\|_{\Hdot{3/2}}\|w^{s_3}\|_{\Hdot{1/2}} \\
&\leq C_\mathrm{CM}C_S^3\delta \left(\sum_{s_1}\|u^{s_1}\|_{\Hdot{1/2}}\right)\left(\sum_{s_2}\|v^{s_2}\|_{\Hdot{3/2}}\right)\left(\sum_{s_3}\|w^{s_3}\|_{\Hdot{1/2}}\right).
\end{align}
By Cauchy--Schwarz applied to the two-term sums:  $\sum_{s} \|f^s\|_{\Hdot{a}} \leq \sqrt{2}\left(\sum_s \|f^s\|_{\Hdot{a}}^2\right)^{1/2} = \sqrt{2}\|f\|_{\Hdot{a}}$.

Hence $|\cT| \leq 2\sqrt{2}\,C_\mathrm{CM}C_S^3\delta\,\|u\|_{\Hdot{1/2}}\|v\|_{\Hdot{3/2}}\|w\|_{\Hdot{1/2}}$.  Setting $C_0 := 2\sqrt{2}\,C_\mathrm{CM}C_S^3$ gives~\eqref{eq:trilinear-main}.

statement:
Without angular localization, the standard trilinear estimate (via H\"older + Sobolev) is
\begin{equation}
\left| \int (u \cdot \nabla v) \cdot w \, dx \right| \leq C\,\|u\|_{L^3}\|\nabla v\|_{L^3}\|w\|_{L^3} \leq C\,\|u\|_{\Hdot{1/2}} \|v\|_{\Hdot{3/2}} \|w\|_{\Hdot{1/2}},
\end{equation}
\emph{without} the $\delta$ prefactor.  The standard ``critical'' estimate
\begin{equation}
|\cT| \leq C\|u\|_{\Hdot{1/2}}\|v\|_{\Hdot{1}}\|w\|_{\Hdot{1/2}}
\end{equation}
(which uses $\|\nabla v\|_{L^2}$ via Cauchy--Schwarz) saturates the NS scaling invariance and is insufficient for global control.  Theorem~\ref{thm:trilinear} gains a factor of $\delta$ at the cost of raising the regularity of $v$ from $\Hdot{1}$ to $\Hdot{3/2}$---precisely the exchange that makes dissipation dominant.

\label{def:aperture}
For $f \in \Hdot{1/2}(\R^3)$ with $f \neq 0$, the \textbf{concentration aperture} $\delta(f)$ is
\begin{equation}
\delta(f) := \inf\left\{\delta > 0 : \exists\, \hat{n} \in S^2 \text{ with } \int_{\cC_\delta(\hat{n})} |k|\,|\hat{f}(k)|^2\,dk \geq \tfrac{1}{2}\|f\|_{\Hdot{1/2}}^2\right\}.
\end{equation}

\label{prop:energy-identity}
Let $u$ be a smooth solution of~\eqref{eq:NS} on $[0,T)$.  Then:
\begin{equation}\label{eq:energy-identity}
\frac{1}{2}\frac{d}{dt}\|u\|_{\Hdot{1/2}}^2 = -\nu\|u\|_{\Hdot{3/2}}^2 + \cN,
\end{equation}
where the nonlinear transfer term is
\begin{equation}\label{eq:N-def}
\cN := -\int_{\R^3} \bigl[(u \cdot \nabla)u\bigr] \cdot |\nabla|\, u\, dx = -\int_{\R^3} |k|\, \widehat{(u \cdot \nabla)u}(k) \cdot \overline{\hat{u}(k)}\, dk.
\end{equation}

\label{prop:suppressed}
Let $u$ be divergence-free with $\supp(\hat{u}) \subset \cC_\delta(\hat{n})$ for some $\delta \in (0, 1/10)$.  Then
\begin{equation}\label{eq:N-bound}
|\cN| \leq C_0\,\delta\, \|u\|_{\Hdot{1/2}}\, \|u\|_{\Hdot{3/2}}^2.
\end{equation}

\label{thm:conditional}
Let $u$ be a smooth solution of~\eqref{eq:NS} with $u_0 \in H^1(\R^3)$, divergence-free.  Set $M := \max(1, \|u_0\|_{\Hdot{1/2}})$ and define
\begin{equation}\label{eq:threshold}
\delta_* := \frac{\nu}{2C_0 M},
\end{equation}
where $C_0$ is the constant from Theorem~\ref{thm:trilinear}.

If the angular concentration aperture satisfies
\begin{equation}\label{eq:concentration-hyp}
\delta(u(t)) \leq \delta_* \qquad \text{for all } t \in [0, T),
\end{equation}
then $u$ remains smooth on $[0, T)$ with
\begin{equation}\label{eq:decay}
\frac{d}{dt}\|u\|_{\Hdot{1/2}}^2 \leq -\nu\,\|u\|_{\Hdot{3/2}}^2 < 0
\end{equation}
whenever $u(t) \neq 0$.

following_proof:
We proceed in three steps.

\textbf{Step 1: Differential inequality.}

By Proposition~\ref{prop:energy-identity}:
\begin{equation}
\frac{1}{2}\frac{d}{dt}E = -\nu D + \cN,
\end{equation}
where $E = \|u\|_{\Hdot{1/2}}^2$ and $D = \|u\|_{\Hdot{3/2}}^2$.

For simplicity of presentation, we first prove the theorem under the stronger hypothesis that $\supp(\hat{u}(t)) \subset \cC_{\delta_*}(\hat{n}(t))$ for each $t$ (i.e., $u$ is spectrally supported in the cone, not merely concentrated there).  The extension to the general concentration hypothesis is addressed in Proposition~\ref{prop:general-concentration} below.

Under this hypothesis, Proposition~\ref{prop:suppressed} gives:
\begin{equation}\label{eq:N-step1}
|\cN| \leq C_0\delta_*\, E^{1/2}\, D.
\end{equation}
Hence:
\begin{equation}\label{eq:key-ineq}
\frac{1}{2}\frac{d}{dt}E \leq -\nu D + C_0\delta_*\, E^{1/2}\, D = -D\bigl(\nu - C_0\delta_*\, E^{1/2}\bigr).
\end{equation}

\textbf{Step 2: Bootstrap.}

We claim $E(t) \leq E(0) \leq M^2$ for all $t$.  Suppose not; let $t_1 := \inf\{t : E(t) > E(0)\}$.  At $t = t_1$, $E(t_1) = E(0)$ and $\frac{d}{dt}E(t_1) \geq 0$.  From~\eqref{eq:key-ineq}:
\begin{equation}
0 \leq -2D(t_1)\bigl(\nu - C_0\delta_*\, E(0)^{1/2}\bigr).
\end{equation}
Substituting $\delta_* = \nu/(2C_0 M)$ and $E(0)^{1/2} \leq M$:
\begin{equation}
\nu - C_0 \cdot \frac{\nu}{2C_0 M} \cdot M = \nu - \frac{\nu}{2} = \frac{\nu}{2} > 0.
\end{equation}
So the right side is $\leq -\nu D(t_1) < 0$ (assuming $u(t_1) \neq 0$, hence $D(t_1) > 0$), a contradiction.  Therefore $E(t) \leq E(0)$ for all $t$, and substituting back into~\eqref{eq:key-ineq}:
\begin{equation}
\frac{d}{dt}E \leq -2D\left(\nu - \frac{\nu}{2}\right) = -\nu D,
\end{equation}
which is~\eqref{eq:decay}.

\textbf{Step 3: Smoothness.}

The bound $\frac{d}{dt}E \leq -\nu D$ implies $\int_0^T D(t)\,dt \leq E(0)/\nu < \infty$.  Thus $u \in L^2_t \Hdot{3/2} \cap L^\infty_t \Hdot{1/2}$.

Smoothness follows by the Escauriaza--Seregin--\v{S}ver\'ak criterion~\cite{ESS}: since $\Hdot{1/2}(\R^3) \hookrightarrow L^3(\R^3)$, the bound $u \in L^\infty_t L^3$ is strictly subcritical for the $L^\infty_t L^3$ endpoint regularity criterion, which guarantees that $u$ remains smooth.  Alternatively, a standard parabolic bootstrap (differentiating the equation and repeating the energy estimate at successively higher Sobolev levels) gives $u \in C^\infty(\R^3 \times (0, T))$.

statement:
\label{prop:general-concentration}
If $\delta(u(t)) \leq \delta_*$ (i.e., at least half the $\Hdot{1/2}$ energy lies in a cone of aperture $\delta_*$), then
\begin{equation}
|\cN| \leq C_0\delta_*\|u\|_{\Hdot{1/2}}\|u\|_{\Hdot{3/2}}^2 + C\|u\|_{\Hdot{1/2}}^{1/2}\|u_\mathrm{out}\|_{\Hdot{1/2}}^{1/2}\|u\|_{\Hdot{3/2}}^2,
\end{equation}
where $u_\mathrm{out} := u - u_\mathrm{in}$.  Since $\|u_\mathrm{out}\|_{\Hdot{1/2}}^2 \leq E/2$, the second term is bounded by $C(E/2)^{1/4}E^{1/4}D = CE^{1/2}D/2^{1/4}$, which has the same structure as the first term (with a potentially larger constant but no $\delta$-gain).  The conditional regularity theorem extends to this setting by choosing $\delta_*$ depending on $C$ as well as $C_0$.

\label{cor:decay}
Under the hypotheses of Theorem~\ref{thm:conditional}, the $\Hdot{1/2}$ norm decays:
\begin{equation}
\|u(t)\|_{\Hdot{1/2}}^2 \leq \frac{\|u_0\|_{\Hdot{1/2}}^2}{(1 + c\,\nu\,\|u_0\|_{L^2}^{-4}\|u_0\|_{\Hdot{1/2}}^4\, t)^{1/2}}
\end{equation}
for a universal constant $c > 0$.

following_proof:
From Theorem~\ref{thm:conditional}, $\frac{d}{dt}E \leq -\nu D$.  We relate $D$ to $E$ via the standard interpolation inequality.  By Fourier splitting (or the interpolation $\Hdot{1/2} = [L^2, \Hdot{3/2}]_{1/3,2}$):
\begin{equation}\label{eq:interp}
\|f\|_{\Hdot{1/2}} \leq C_I\, \|f\|_{L^2}^{2/3}\, \|f\|_{\Hdot{3/2}}^{1/3}.
\end{equation}
To verify~\eqref{eq:interp}: write $\|f\|_{\Hdot{1/2}}^2 = \int |k||\hat{f}|^2\,dk$ and split at $|k| = \lambda$.  For $|k| \leq \lambda$: $|k| \leq \lambda$ so $\int_{|k| \leq \lambda} |k||\hat{f}|^2 \leq \lambda\|f\|_{L^2}^2$.  For $|k| > \lambda$: $|k| = |k|^3/|k|^2 \leq |k|^3/\lambda^2$ so $\int_{|k| > \lambda} |k||\hat{f}|^2 \leq \lambda^{-2}\|f\|_{\Hdot{3/2}}^2$.  Optimizing $\lambda$: set $\lambda\|f\|_{L^2}^2 = \lambda^{-2}\|f\|_{\Hdot{3/2}}^2$, giving $\lambda^3 = \|f\|_{\Hdot{3/2}}^2/\|f\|_{L^2}^2$, and $\|f\|_{\Hdot{1/2}}^2 \leq 2\|f\|_{L^2}^{4/3}\|f\|_{\Hdot{3/2}}^{2/3}$.  This confirms~\eqref{eq:interp} with $C_I = 2^{1/2}$.

Squaring~\eqref{eq:interp} and rearranging: $E = \|f\|_{\Hdot{1/2}}^2 \leq C_I^2\|f\|_{L^2}^{4/3}D^{1/3}$, hence
\begin{equation}
D \geq \left(\frac{E}{C_I^2\|f\|_{L^2}^{4/3}}\right)^3.
\end{equation}
Since $\|u(t)\|_{L^2} \leq \|u_0\|_{L^2}$ (Leray energy inequality), setting $A := C_I^2\|u_0\|_{L^2}^{4/3}$:
\begin{equation}
\frac{d}{dt}E \leq -\nu D \leq -\frac{\nu}{A^3}\,E^3.
\end{equation}
This ODE $\dot{E} \leq -\alpha E^3$ with $\alpha = \nu/A^3$ integrates to $E(t)^{-2} \geq E(0)^{-2} + 2\alpha t$, giving:
\begin{equation}
E(t) \leq \frac{E(0)}{(1 + 2\alpha\, E(0)^2\, t)^{1/2}}.
\end{equation}
Substituting $\alpha = \nu/(C_I^6\|u_0\|_{L^2}^4)$ yields the stated bound.

statement:
\label{thm:minimal}
Suppose finite-time blow-up occurs for some initial data in $\Hdot{1/2}(\R^3)$.  Then there exists a \textbf{minimal blow-up solution} $u^*$ with:
\begin{enumerate}[leftmargin=2em]
\item $T^* < \infty$ (finite blow-up time),
\item $\|u^*_0\|_{\Hdot{1/2}} = E_c := \inf\{\|v_0\|_{\Hdot{1/2}} : v \text{ blows up in finite time}\} > 0$,
\item $u^*$ is \textbf{almost-periodic modulo symmetries}: the orbit $\{u^*(t) : t \in [0,T^*)\}$ is precompact in $\Hdot{1/2}$ modulo the action of the scaling-translation group.  That is, there exist continuous functions $\lambda\colon [0, T^*) \to (0,\infty)$ and $x\colon [0, T^*) \to \R^3$ such that for every $\varepsilon > 0$, there exists $R(\varepsilon) < \infty$ with
\begin{equation}
\int_{|k| > R\lambda(t)} |k|\, |\hat{u}^*(k,t)|^2\, dk + \int_{|k| < \lambda(t)/R} |k|\, |\hat{u}^*(k,t)|^2\, dk < \varepsilon \qquad \text{for all } t \in [0, T^*).
\end{equation}
\end{enumerate}

\label{rem:ap}
The precompactness means: for every sequence $t_n \to T^*$, there exist $\lambda_n > 0$ and $x_n \in \R^3$ such that $v_n(x) := \lambda_n\, u^*(t_n, \lambda_n(x - x_n))$ has a subsequence converging \emph{strongly} in $\Hdot{1/2}$ to some profile $\phi$.  Here the rescaling $f \mapsto \lambda f(\lambda\,\cdot)$ is the NS-invariant one, preserving $\Hdot{1/2}(\R^3)$:
\begin{equation}
\|\lambda f(\lambda\,\cdot)\|_{\Hdot{1/2}} = \|f\|_{\Hdot{1/2}}.
\end{equation}
Thus $\|v_n\|_{\Hdot{1/2}} = \|u^*(t_n)\|_{\Hdot{1/2}}$, so the limiting profile satisfies $\|\phi\|_{\Hdot{1/2}} = \lim_{k \to \infty}\|u^*(t_{n_k})\|_{\Hdot{1/2}}$.  Since $u^*$ restricted to $[t_n, T^*)$ is itself a blow-up solution, minimality gives $\|u^*(t_n)\|_{\Hdot{1/2}} \geq E_c$, hence $\|\phi\|_{\Hdot{1/2}} \geq E_c$.

Since $\|u^*(t_n)\|_{\Hdot{3/2}} \to \infty$ as $t_n \to T^*$ (otherwise blow-up couldn't occur), we must have $\lambda_n \to \infty$.

\label{prop:ap-concentration}
Let $u^*$ be an almost-periodic minimal blow-up solution as in Theorem~\ref{thm:minimal}.  Then
\begin{equation}
\lim_{t \to T^*} \delta(u^*(t)) = 0.
\end{equation}

following_proof:
We prove the contrapositive: if $\limsup_{t \to T^*} \delta(u^*(t)) \geq \delta_0 > 0$, then $u^*$ does not blow up at time $T^*$.

\textbf{Step 1: Extracting a limiting profile.}

Suppose $\delta(u^*(t_n)) \geq \delta_0$ for a sequence $t_n \to T^*$.  By almost-periodicity (Remark~\ref{rem:ap}), after passing to a subsequence, there exist $\lambda_n \to \infty$ and $x_n \in \R^3$ such that
\begin{equation}
v_n(x) := \lambda_n\, u^*(t_n,\, \lambda_n(x - x_n)) \longrightarrow \phi \quad \text{strongly in } \Hdot{1/2},
\end{equation}
with $\|\phi\|_{\Hdot{1/2}} \geq E_c$ (by norm preservation and minimality, cf.\ Remark~\ref{rem:ap}).

\textbf{Step 2: The profile has angular spread.}

Since $\delta$ is scale-invariant (Lemma~\ref{lem:aperture-props}(i)):
\begin{equation}
\delta(v_n) = \delta(u^*(t_n)) \geq \delta_0 > 0.
\end{equation}
By the upper semicontinuity of $\delta$ in $\Hdot{1/2}$ (Lemma~\ref{lem:aperture-props}(iii)): for any $\varepsilon > 0$,
\begin{equation}
\delta(\phi) \geq \delta_0 - \varepsilon.
\end{equation}
Choosing $\varepsilon = \delta_0/2$: $\delta(\phi) \geq \delta_0/2 > 0$.

Concretely: for every $\hat{n} \in S^2$, $\int_{\cC_{\delta_0/2}(\hat{n})} |k||\hat{\phi}|^2\,dk < \frac{1}{2}\|\phi\|_{\Hdot{1/2}}^2$.  In other words, no single cone of aperture $\delta_0/2$ contains more than half the $\Hdot{1/2}$ energy of $\phi$.

\textbf{Step 3: Angular decomposition of the profile.}

We decompose $\phi$ into angularly separated pieces, each with strictly subcritical norm.

Set $L := \|\phi\|_{\Hdot{1/2}} \geq E_c$ and choose $M_0 := \lceil 2L^2/E_c^2\rceil + 1$.  Cover $S^2$ by $M \geq M_0$ spherical caps $\{\Omega_m\}_{m=1}^M$, each of diameter $\alpha \leq \delta_0/4$, with bounded overlap $K$ (independent of $M$ for a good Vitali covering).

Define $\phi_m$ by $\hat{\phi}_m(k) := \chi_{\Omega_m}(\hat{k})\hat{\phi}(k)$.  The bounded overlap gives $\sum_m \|\phi_m\|_{\Hdot{1/2}}^2 \leq K L^2$.

Since $\delta(\phi) \geq \delta_0/2 > 2\alpha$, no single cap of diameter $\alpha$ contains more than half the energy: $\|\phi_m\|_{\Hdot{1/2}}^2 < L^2/2$ for all $m$.  Moreover, by the pigeonhole principle applied to the $M \geq 2L^2/E_c^2 + 1$ caps:
\begin{equation}
\max_m \|\phi_m\|_{\Hdot{1/2}}^2 \leq \frac{KL^2}{M} < \frac{KL^2}{2L^2/E_c^2} = \frac{K E_c^2}{2}.
\end{equation}
For the standard Vitali covering on $S^2$, $K \leq C_d$ (a dimensional constant; one can achieve $K = 1$ with a partition, at the cost of less regular boundaries).  With $K = 1$ (using a partition):
\begin{equation}
\|\phi_m\|_{\Hdot{1/2}} < \frac{E_c}{\sqrt{2}} < E_c \qquad \text{for all } m.
\end{equation}

\textbf{Step 4: Subcritical data evolve globally.}

By definition of the critical energy $E_c$: for each $m$, the NS evolution from initial data $\phi_m$ exists globally (since $\|\phi_m\|_{\Hdot{1/2}} < E_c$).  Denote these global solutions by $U_m(t)$.

\textbf{Step 5: Perturbation theory for the superposition.}

We now show that the NS evolution from $\phi$ (the superposition) is also global, using the perturbation theory from~\cite{GKP} (Proposition~3.1, adapted from the Kenig--Merle framework).

The key input is: the solution $U := \sum_m U_m$ satisfies the NS equation \emph{plus an error} $e = \sum_{m \neq m'} \bP[(U_m \cdot \nabla)U_{m'}]$ (the cross-interactions between different angular pieces).

\emph{Claim:} The error $e$ has small space-time norm.  The caps $\Omega_m$ have diameter $\alpha \leq \delta_0/4$, which provides angular separation between different pieces.  The bilinear interaction $U_m \cdot \nabla U_{m'}$ for caps with angular separation $\geq \alpha$ has output Fourier support predominantly in the Minkowski sum $\Omega_m + \Omega_{m'}$, which is disjoint from both $\Omega_m$ and $\Omega_{m'}$ when the separation is large relative to $\alpha$.

More precisely: the perturbation theory of~\cite{GKP} gives that if the approximate solution $U$ satisfies $\|e\|_{N([0,T])} < \varepsilon_0$ (in a suitable space-time norm $N$), then the true solution from $\phi$ exists on $[0,T]$ and stays close to $U$.  The global existence of each $U_m$ provides the necessary space-time bounds, and the angular separation combined with the smallness of each $\|U_m\|$ (strictly subcritical) ensures the cross-terms are summable.  The number of caps $M$ depends on $L/E_c$ and $\delta_0$, but since $L$, $E_c$, and $\delta_0$ are all fixed, $M$ is finite.

The technical details of the perturbation argument are standard in the Kenig--Merle framework; we refer to~\cite{GKP} Proposition~3.1 and~\cite{KenigKoch} for the NS-specific formulation.

\textbf{Step 6: Contradiction.}

The global existence of the NS evolution from $\phi$ contradicts the fact that $\phi$ is the strong $\Hdot{1/2}$-limit of rescaled blow-up solutions.  Indeed, if the solution from $\phi$ is global, the perturbation theory of~\cite{GKP} implies that the solution from $v_n$ (which is close to $\phi$ in $\Hdot{1/2}$) is also global for $n$ large enough.  But $v_n$ is a rescaling of $u^*(t_n)$, and the solution from $v_n$ is just the rescaling of $u^*$ on $[t_n, T^*)$---which was assumed to blow up.  Contradiction.

statement:
\label{thm:reduction}
Assume the GKP framework (Theorem~\ref{thm:minimal}).  Then the 3D Navier--Stokes global regularity problem reduces to:

\emph{No smooth solution $u$ of~\eqref{eq:NS} can have $\delta(u(t)) \to 0$ as $t \to T^* < \infty$ while $\|u(t)\|_{\Hdot{3/2}} \to \infty$.}

Equivalently: within the GKP framework, angular concentration in Fourier space is the \textbf{unique geometric obstruction} to global regularity.

\label{lem:minkowski-area}
Let $\Omega \subset S^2$ be a spherical cap of angular radius $\theta_0 \leq 1/10$, centered at $\hat{n}$.  Define the \textbf{directional Minkowski sum}
\begin{equation}
\Omega \oplus \Omega := \bigl\{\widehat{p+q} \in S^2 : \hat{p}, \hat{q} \in \Omega,\, p + q \neq 0\bigr\}.
\end{equation}
Then:
\begin{enumerate}[label=(\alph*),leftmargin=2em]
\item $\Omega \subset \Omega \oplus \Omega$ (taking $p = q$).
\item $\Omega \oplus \Omega$ is contained in a cap of angular radius $\leq 2\theta_0 + O(\theta_0^3)$ centered at $\hat{n}$.
\item $\mathrm{Area}(\Omega \oplus \Omega) \geq 3\,\mathrm{Area}(\Omega)$, and $\mathrm{Area}((\Omega \oplus \Omega) \setminus \Omega) \geq 2\,\mathrm{Area}(\Omega)$.
\end{enumerate}

\label{conj:outflow}
Let $u$ be divergence-free with Fourier support in $\cC_\delta(\hat{n})$ and $\|u\|_{\Hdot{1/2}} = 1$.  Define the in-cone and out-of-cone components of the Leray-projected nonlinearity:
\begin{equation}
F := \bP\bigl[(u \cdot \nabla)u\bigr], \qquad F = F_{\mathrm{in}} + F_{\mathrm{out}},
\end{equation}
where $\hat{F}_{\mathrm{in}}$ is supported in $\cC_\delta(\hat{n})$ and $\hat{F}_{\mathrm{out}}$ is supported in $\cC_\delta(\hat{n})^c$.

There exists a universal constant $c_1 > 0$ such that for all such $u$ with $\|u\|_{\Hdot{3/2}} \geq 1$:
\begin{equation}\label{eq:outflow-conj}
\|F_{\mathrm{out}}\|_{\Hdot{-1/2}} \geq c_1\,\|u\|_{\Hdot{3/2}}.
\end{equation}

\label{prop:numerical}
For discrete caps uniformly distributed on $S^2$, the helical coupling tensor $C_{jk\ell} = C(n_j, n_k, n_\ell)$ satisfies:
\begin{enumerate}[leftmargin=2em]
\item The coupling phases $\arg(C_{jk\ell})$ span $[-\pi, \pi]$ with standard deviation $\approx 1.7$ rad, close to the uniform-distribution value $\pi/\sqrt{3}$.
\item The total cancellation $\sum_{j,k} C(n_j, n_k) = 0$ holds exactly for any polynomial weight $|k|^n$.
\item The operator norm of the trilinear tensor scales as $N^{-0.56}$, \emph{decreasing} with refinement $N$.
\end{enumerate}

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
$N$ (caps) & $\max|T|$ & $\max|T|/N^{3/2}$ & Trend \\
\hline
10 & 0.419 & 0.0133 & --- \\
20 & 0.349 & 0.0039 & $\downarrow$ \\
30 & 0.272 & 0.0017 & $\downarrow$ \\
40 & 0.202 & 0.0008 & $\downarrow$ \\
50 & 0.172 & 0.0005 & $\downarrow$ \\
\hline
\end{tabular}
