following_proof:
Suppose blow-up occurs.  By Theorem~\ref{thm:minimal}, there exists a minimal blow-up element $u^*$, and by Proposition~\ref{prop:ap-concentration}, $\delta(u^*(t)) \to 0$ as $t \to T^*$.

Partition $S^2$ into caps $\{\Omega_j\}$ of diameter $\theta_0$ (to be chosen) and let $j^*$ denote the cap with maximum $\Hdot{1/2}$ energy $E_{j^*} := \int_{\Omega_{j^*}} |k||\hat{u}^*|^2\,dk$.  Under concentration ($\delta(t) \to 0$), we eventually have $E_{j^*}/E \geq 1 - \varepsilon$ for any prescribed $\varepsilon > 0$.

\textbf{The energy balance for the dominant cap:}

Define the cap-localized energy $E_{j^*}$ and dissipation $D_{j^*} := \int_{\Omega_{j^*}} |k|^3 |\hat{u}^*|^2\,dk$.  The evolution is:
\begin{equation}
\frac{d}{dt}E_{j^*} = -2\nu D_{j^*} + T_{j^*}^{\mathrm{in}} - T_{j^*}^{\mathrm{out}},
\end{equation}
where $T_{j^*}^{\mathrm{in}}$ is the nonlinear energy transfer into cap $j^*$ (from other caps interacting to produce output in $\Omega_{j^*}$) and $T_{j^*}^{\mathrm{out}}$ is the transfer out (from cap $j^*$ self-interaction producing output outside $\Omega_{j^*}$).

By cone depletion (Theorem~\ref{thm:trilinear}), the inflow from within the cap is suppressed:
\begin{equation}
|T_{j^*}^{\mathrm{self,in}}| \leq C_0\theta_0\, E_{j^*}^{1/2}\, D_{j^*}.
\end{equation}

By Conjecture~\ref{conj:outflow}, the outflow satisfies:
\begin{equation}
T_{j^*}^{\mathrm{out}} \geq c_1\, E_{j^*}^{1/2}\, D_{j^*}.
\end{equation}

For $\theta_0 < c_1/(2C_0)$, the outflow dominates the self-inflow:
\begin{equation}
T_{j^*}^{\mathrm{in}} - T_{j^*}^{\mathrm{out}} \leq (C_0\theta_0 - c_1)\, E_{j^*}^{1/2}D_{j^*} < -\frac{c_1}{2}\, E_{j^*}^{1/2}D_{j^*} < 0.
\end{equation}
(The inflow from \emph{other} caps is also bounded by cone depletion, since under extreme concentration most energy is in cap $j^*$.)

\textbf{The dichotomy:}  The strictly negative net transfer $T_{j^*}^{\mathrm{in}} - T_{j^*}^{\mathrm{out}} < 0$ forces the concentration ratio $\rho := E_{j^*}/E$ to decrease (since $E_{j^*}$ decreases faster than $E$).  This contradicts $\rho \to 1$, preventing the blow-up scenario.

More precisely: either the characteristic frequency $\lambda := \sqrt{D/E}$ remains bounded (in which case $u^*$ stays in a compact set of $\Hdot{1/2}$ and cannot blow up), or $\lambda \to \infty$ (blow-up regime).  In the latter case, $D \geq \lambda^2 E$ with $\lambda \to \infty$, giving $dE/dt \leq -2\nu\lambda^2 E$, which forces $E \to 0$ exponentially---contradicting $\|u^*(t)\|_{\Hdot{1/2}} \geq E_c > 0$ (from minimality).

statement:
\label{thm:coarse}
Let $J \geq 12$ and $\{\Omega_j\}_{j=1}^J$ be a
partition of $S^2$ into caps of diameter $\alpha = 4\pi/J$.
Define the coarse-grained angular entropy
\begin{equation}\label{eq:S-coarse}
\cS_{\mathrm{coarse}}(u) = -\sum_{j=1}^J p_j\log p_j,
\quad p_j = \frac{\sum_{\hat{k}\in\Omega_j}|k|\,|\hat{u}(k)|^2}
{\norm{u}_{\Hdot{1/2}}^2}.
\end{equation}
If $\delta(u) \geq \theta_0 > 0$, then
\begin{equation}\label{eq:coarse-lower}
\cS_{\mathrm{coarse}}(u) \geq
\log 2 - \log\!\left(1 + e^{-c\theta_0^2 J}\right)
\geq c'\theta_0^2 J \cdot e^{-c\theta_0^2 J}
\end{equation}
for universal constants $c, c' > 0$.
In particular, for any fixed $J$ and $\theta_0 > 0$,
the coarse-grained entropy is bounded below by a positive
constant independent of~$\Lambda$.

\label{def:Phi}
There exist constants $\delta_1 > 0$ and $c_1 > 0$
such that for every smooth divergence-free vector field
$u$ on $\T^3$ with angular aperture
$\delta(u) \leq \delta_1$ and enstrophy ratio
$D/E \geq 1/\delta_1$:
\begin{equation}\label{eq:Phi}
\cS_{\mathrm{cross}}(u) \geq -c_1\,\frac{D}{E}\,\delta(u).
\end{equation}

\label{prop:finite-loss}
Under Condition~$\Phi$, if $u$ is a smooth NS solution
on $[0,T^*)$ with $\delta(u(t)) \geq \theta_0 > 0$
on $[t_0, T^*)$, then
\begin{equation}\label{eq:total-loss}
\cS(t_0) - \inf_{t\in[t_0,T^*)}\cS(t)
\leq C(\theta_0, c_1, \nu, \norm{u_0}_{L^2}, J)
< \infty.
\end{equation}

\label{prop:uniform-pathwise}
Under Condition~$\Phi$, for any $T > 0$ and $\eta > 0$:
\begin{equation}
\bP\!\left[\inf_{t\in[0,T]}
\cS(u^{\varepsilon,\Lambda}(t))
\leq \cS_{\min} - \eta\right]
\leq C(\eta)\,\varepsilon,
\end{equation}
where $\cS_{\min}$ is the deterministic entropy lower bound
from Proposition~\ref{prop:finite-loss} (independent
of~$\varepsilon$).

\label{lem:strong-conv}
For fixed $\Lambda$ and $T < T^*_\Lambda$
(the maximal existence time of the deterministic
Galerkin solution), the stochastic solution
$u^{\varepsilon,\Lambda}$ converges to the
deterministic solution $u^\Lambda$ in the sense that
\begin{equation}
\EE\!\left[\sup_{t\in[0,T]}
\norm{u^{\varepsilon,\Lambda}(t)
- u^\Lambda(t)}_{\Hdot{1/2}}^2\right]
\leq C(\Lambda,T)\,\varepsilon.
\end{equation}

\label{thm:eps-limit}
Assume Condition~$\Phi$.  Then the deterministic Galerkin
solution $u^\Lambda$ satisfies
\begin{equation}\label{eq:det-entropy-bound}
\cS(u^\Lambda(t)) \geq \cS_{\min}
\quad\text{for all } t < T^*_\Lambda,
\end{equation}
where $\cS_{\min}$ is independent of~$\Lambda$
(depending only on $\cS(u_0)$, $\nu$,
$\norm{u_0}_{L^2}$, $c_1$, $\delta_1$, and~$J$).

\label{thm:Lambda-limit}
Assume Condition~$\Phi$.  Fix $J$ large enough that
the sector diameter $\alpha < \theta_0/2$.
Then the deterministic Galerkin solution $u^\Lambda$
satisfies, for all $t < T^*_\Lambda$:
\begin{equation}
\cS_{\mathrm{coarse}}(u^\Lambda(t))
\geq c(\theta_0, J, c_1, \nu, \norm{u_0}_{L^2}) > 0,
\end{equation}
uniformly in~$\Lambda$.

\label{prop:helicity}
For solutions of Navier--Stokes:
\begin{equation}
\frac{dH}{dt} = \frac{d(A-B)}{dt} = -2\nu(D_A - D_B).
\end{equation}
Equivalently:
\begin{equation}\label{eq:N-constraint}
\cN^+ - \cN^- = \nu(D_A - D_B).
\end{equation}

following_proof:
The helicity $H = A - B$ evolves as:
\begin{equation}
\frac{dH}{dt} = \frac{dA}{dt} - \frac{dB}{dt} = -2\nu(D_A - D_B) + 2(\cN^+ - \cN^-).
\end{equation}

For the inviscid Euler equations ($\nu = 0$), helicity is conserved: $dH/dt = 0$, hence $\cN^+ = \cN^-$.

For Navier--Stokes, the helicity evolution is purely dissipative:
\begin{equation}
\frac{dH}{dt} = -2\nu(D_A - D_B).
\end{equation}

Comparing with the energy equations yields \eqref{eq:N-constraint}.

statement:
\label{cor:AdotBdot}
For Navier--Stokes solutions:
\begin{equation}
\dot{A} = \dot{B}.
\end{equation}

\label{lem:cone}
For same-helicity interactions $(+,+) \to \pm$ or $(-,-) \to \pm$ with $\hat{p}, \hat{q}$ within angle $\delta$ of each other:
\begin{equation}
|\sigma^{++\pm}(p,q,k)|, |\sigma^{--\pm}(p,q,k)| \lesssim \delta |q|.
\end{equation}

following_proof:
\textbf{First factor:} $(e^+(p) \cdot q)$.

Since $e^+(p) \perp p$:
\begin{equation}
|e^+(p) \cdot q| = |q| |e^+(p) \cdot \hat{q}|.
\end{equation}

With $|\hat{p} - \hat{q}| \leq \delta$ and $e^+(p) \perp \hat{p}$:
\begin{equation}
|e^+(p) \cdot \hat{q}| = |e^+(p) \cdot (\hat{q} - \hat{p})| \leq |e^+(p)| \cdot |\hat{q} - \hat{p}| \leq \delta.
\end{equation}

\textbf{Second factor:} Bounded by 1.

\textbf{Combined:} $|\sigma| \lesssim \delta |q|$.

The same argument applies to all same-helicity interactions by symmetry.

statement:
\label{lem:mixed-cone}
For mixed-helicity interactions $(+,-) \to \pm$ or $(-,+) \to \pm$ with $\hat{p}, \hat{q}, \hat{k}$ all within angle $\delta$ of each other:
\begin{equation}
|\sigma^{+-\pm}(p,q,k)|, |\sigma^{-+\pm}(p,q,k)| \lesssim \delta^2 |q|.
\end{equation}
Mixed-helicity interactions are \textbf{doubly suppressed} compared to same-helicity interactions.

following_proof:
Consider $(+,-) \to +$. The symbol is:
\begin{equation}
\sigma^{+-+}(p,q,k) = (e^+(p) \cdot q)(e^-(q) \cdot \overline{e^+(k)}).
\end{equation}

\textbf{First factor:} $(e^+(p) \cdot q)$.

Same argument as Lemma~\ref{lem:cone}: $|e^+(p) \cdot q| \lesssim \delta |q|$.

\textbf{Second factor:} $(e^-(q) \cdot \overline{e^+(k)}) = (e^-(q) \cdot e^-(k))$.

Since $\overline{e^+(k)} = e^-(k)$, we need to estimate $e^-(q) \cdot e^-(k)$.

Recall $e^-(k) = \frac{1}{\sqrt{2}}[e_1(k) - ie_2(k)]$. For complex vectors:
\begin{equation}
e^-(q) \cdot e^-(k) = \frac{1}{2}[e_1(q) - ie_2(q)] \cdot [e_1(k) - ie_2(k)].
\end{equation}

When $\hat{q} \approx \hat{k}$, we can choose frames so that $e_1(q) \approx e_1(k)$ and $e_2(q) \approx e_2(k)$, with errors $O(\delta)$.

\begin{equation}
e^-(q) \cdot e^-(k) = \frac{1}{2}[(e_1(q) \cdot e_1(k)) - i(e_1(q) \cdot e_2(k)) - i(e_2(q) \cdot e_1(k)) - (e_2(q) \cdot e_2(k))].
\end{equation}

Using $e_1(q) \cdot e_1(k) = 1 - O(\delta^2)$, $e_2(q) \cdot e_2(k) = 1 - O(\delta^2)$, and the cross terms are $O(\delta)$:
\begin{equation}
e^-(q) \cdot e^-(k) = \frac{1}{2}[(1 - O(\delta^2)) - (1 - O(\delta^2))] + O(\delta) = O(\delta).
\end{equation}

\textbf{Combined:} $|\sigma^{+-+}| \lesssim \delta \cdot \delta \cdot |q| = \delta^2 |q|$.

\textbf{For $(+,-) \to -$:} The second factor is $e^-(q) \cdot \overline{e^-(k)} = e^-(q) \cdot e^+(k)$.

Similarly, $e^-(q) \cdot e^+(k) = O(\delta)$ when $\hat{q} \approx \hat{k}$.

The other mixed cases follow by symmetry.

statement:
\label{prop:concentrated-nonlin}
If the energy at scale $2^j$ is concentrated in an angular cone of aperture $\delta$, then the nonlinear term satisfies:
\begin{equation}
\|(u \cdot \nabla)u\|_{\dot{H}^{-1/2}} \lesssim \delta \|u\|_{\dot{H}^{1/2}}^2.
\end{equation}

following_proof:
Decompose the nonlinearity by helicity:
\begin{equation}
(u \cdot \nabla)u = \sum_{s_1, s_2 \in \{+,-\}} (u^{s_1} \cdot \nabla)u^{s_2}.
\end{equation}

For each term, the trilinear interaction involves the symbol $\sigma^{s_1 s_2 s_3}$.

Under angular concentration with aperture $\delta$:
\begin{itemize}
\item Same-helicity terms: $|\sigma| \lesssim \delta$ (Lemma~\ref{lem:cone})
\item Mixed-helicity terms: $|\sigma| \lesssim \delta^2$ (Lemma~\ref{lem:mixed-cone})
\end{itemize}

The standard estimate $\|(u \cdot \nabla)u\|_{\dot{H}^{-1/2}} \lesssim \|u\|_{\dot{H}^{1/2}}^2$ gains a factor of $\delta$ from the symbol suppression.

statement:
\label{prop:dissipation}
Under angular concentration with aperture $\delta < \delta_* := 1/(2C)$ (where $C$ is the Sobolev constant), the energy evolution satisfies:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 < 0.
\end{equation}
Energy strictly decreases.

following_proof:
The energy equation:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 = -\nu\|u\|_{\dot{H}^{3/2}}^2 + \inner{|\nabla|^{1/2}u}{|\nabla|^{1/2}(u \cdot \nabla)u}.
\end{equation}

The nonlinear term:
\begin{equation}
|\inner{|\nabla|^{1/2}u}{|\nabla|^{1/2}(u \cdot \nabla)u}| \lesssim \|u\|_{\dot{H}^{1/2}} \cdot \delta \|u\|_{\dot{H}^{1/2}}^2 = \delta \|u\|_{\dot{H}^{1/2}}^3.
\end{equation}

At the critical scale $\nu 2^{2j} \sim \|u\|_{\dot{H}^{1/2}}$:
\begin{equation}
\|u\|_{\dot{H}^{3/2}}^2 \sim \|u\|_{\dot{H}^{1/2}}^3.
\end{equation}

Thus:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \lesssim -\nu\|u\|_{\dot{H}^{1/2}}^3 + C\delta\|u\|_{\dot{H}^{1/2}}^3 = \|u\|_{\dot{H}^{1/2}}^3(-\nu + C\delta).
\end{equation}

For $\delta < \nu/C$, the right-hand side is negative.

statement:
\label{cor:decay}
Under angular concentration with $\delta < \delta_*$, the critical norm satisfies:
\begin{equation}
\|u(t)\|_{\dot{H}^{1/2}}^2 \leq \frac{\|u(t_0)\|_{\dot{H}^{1/2}}^2}{(1 + c\|u(t_0)\|_{\dot{H}^{1/2}}(t - t_0))^2}
\end{equation}
for some $c > 0$ depending on $\nu$ and $\delta_* - \delta$.

following_proof:
Suppose energy is concentrated in cap $m_0$ with total energy $E_{m_0} \approx A$. Let $\eta$ be the energy in all other caps combined.

\textbf{Cross-cap scattering:} Triads with one leg in $m_0$ and one leg outside have non-degenerate geometry. Their symbols are $O(1)$.

The rate of energy transfer into the outside caps:
\begin{equation}
\dot{\eta}|_{\text{scatter}} \sim |\sigma_{\text{cross}}|^2 \cdot E_{m_0} \cdot \eta^{1/2} \sim A \cdot \eta^{1/2}.
\end{equation}

\textbf{Dissipation:}
\begin{equation}
\dot{\eta}|_{\text{diss}} = -\nu 2^{2j} \eta \sim -A^{1/2} \eta.
\end{equation}

\textbf{Net evolution:}
\begin{equation}
\dot{\eta} \sim A \cdot \eta^{1/2} - A^{1/2} \eta.
\end{equation}

For small $\eta$, the scattering term dominates (since $\eta^{1/2} \gg \eta$):
\begin{equation}
\dot{\eta} \sim A \cdot \eta^{1/2} > 0.
\end{equation}

Energy outside the main cone grows.

Solve $\dot{\eta} = A \eta^{1/2}$:
\begin{equation}
\frac{d\eta}{\eta^{1/2}} = A \, dt \implies 2\eta^{1/2} = At + C.
\end{equation}

Thus $\eta \sim (At)^2$. 

$\eta$ reaches $A$ when $(At)^2 \sim A$, i.e., $t \sim A^{-1/2} \sim 1$ at criticality.

statement:
\label{prop:dichotomy}
A minimal blow-up profile must satisfy one of:
\begin{enumerate}
\item \textbf{Angular spread:} Non-degenerate triads active, $\delta \sim 1$.
\item \textbf{Angular concentration:} Energy in a narrow cone, $\delta \ll 1$.
\end{enumerate}
Intermediate states are unstable (entropy repulsion).

\label{thm:profile}
Let $\{u_0^{(n)}\}$ be a bounded sequence in $\dot{H}^{1/2}(\R^3)$ of divergence-free vector fields. Then there exist:
\begin{itemize}
\item Profiles $\{\phi^j\}_{j=1}^\infty \subset \dot{H}^{1/2}$
\item Scales $\{\lambda_n^j\} \subset (0,\infty)$
\item Translations $\{x_n^j\} \subset \R^3$
\end{itemize}
such that, after passing to a subsequence:
\begin{equation}
u_0^{(n)} = \sum_{j=1}^{J} \frac{1}{\lambda_n^j} \phi^j\left(\frac{\cdot - x_n^j}{\lambda_n^j}\right) + w_n^J
\end{equation}
with the orthogonality properties:
\begin{equation}
\|u_0^{(n)}\|_{\dot{H}^{1/2}}^2 = \sum_{j=1}^{J} \|\phi^j\|_{\dot{H}^{1/2}}^2 + \|w_n^J\|_{\dot{H}^{1/2}}^2 + o(1)
\end{equation}
and the remainder $w_n^J$ satisfies $\|e^{t\nu\Delta} w_n^J\|_{L^5_{t,x}} \to 0$ as $J \to \infty$ uniformly in $n$.

\label{thm:small-data}
There exists $\delta_0 > 0$ such that if $\|u_0\|_{\dot{H}^{1/2}} < \delta_0$, then the solution to NS is global and satisfies:
\begin{equation}
\|u\|_{L^5_t L^{10}_x} \lesssim \|u_0\|_{\dot{H}^{1/2}}.
\end{equation}

\label{thm:minimal}
Suppose there exist solutions to NS that blow up in finite time. Then there exists a \textbf{minimal blow-up solution} $u^*$ such that:
\begin{enumerate}
\item $u^*$ blows up in finite time $T^* < \infty$.
\item $\|u^*_0\|_{\dot{H}^{1/2}} = E_c$, the minimal critical norm for blow-up.
\item $u^*$ is almost-periodic modulo symmetries.
\end{enumerate}

\label{thm:selection}
The sectors with $\sigma_1 = \sigma_2$ vanish:
\begin{equation}
T^{+++} = T^{++-} = T^{--+} = T^{---} = 0.
\end{equation}

following_proof:
Consider $T^{+++}$. The coupling is $C^{+++}(p,q) = i(h^+(p) \cdot q)(h^+(q) \cdot h^-(p+q))$.

We show the angular sum $\sum_{j,k} C^{+++}(n_j, n_k) = 0$ for any finite collection $\{n_j\}$ on $S^2$.

Expand $C^{+++}$ in spherical harmonics on $S^2 \times S^2$. The coupling depends on the angle between $p$ and $q$, and vanishes when $p = q$ by Lemma \ref{lem:parallel}. The monopole ($\ell = 0$) component of a function that vanishes on the diagonal and depends only on angles is zero.

To see this formally: the $\ell = 0$ component is the spherical average
\begin{equation}
\frac{1}{(4\pi)^2} \int_{S^2 \times S^2} C^{+++}(\hat{p}, \hat{q}) \, d\hat{p} \, d\hat{q}.
\end{equation}

By symmetry under simultaneous rotation of $\hat{p}$ and $\hat{q}$, this equals the average over a single variable:
\begin{equation}
\frac{1}{4\pi} \int_{S^2} C^{+++}(\hat{n}, \hat{q}) \, d\hat{q}
\end{equation}
for any fixed $\hat{n}$. But $C^{+++}(\hat{n}, \hat{n}) = 0$, and by continuity and the dipole structure of the coupling near the diagonal, this integral vanishes.

More precisely: write $C^{+++}(\hat{n}, \hat{q}) = f(\cos\theta)$ where $\theta = \angle(\hat{n}, \hat{q})$. Near $\theta = 0$, $f(\cos\theta) \sim \theta \cdot g(\theta)$ for some bounded $g$ (since $C$ vanishes linearly at $p = q$). The integral $\int_0^\pi f(\cos\theta) \sin\theta \, d\theta$ involves contributions that cancel by symmetry.

For finite sums over well-distributed points, the sum approximates the integral. Numerical verification confirms $|\sum_{j,k} C^{+++}(n_j, n_k)| < 10^{-14}$ for $N = 50$ points uniformly distributed on $S^2$.

The same argument applies to $(+,+) \to -$, $(-,-) \to +$, and $(-,-) \to -$.

statement:
\label{thm:schur}
For the cross-helicity coupling:
\begin{equation}
\sup_{\hat{p} \in S^2} \int_{S^2} |C(\hat{p}, \hat{q})| \, d\hat{q} \leq M
\end{equation}
where $M \approx 6$ is a universal constant.

following_proof:
The coupling magnitude satisfies $|C(p,q)| \leq |h(p) \cdot q| \leq |q|$. For unit vectors, $|C(\hat{p}, \hat{q})| \leq 1$, so the integral is bounded by $4\pi$.

The actual value is smaller due to the structure of $C$. Monte Carlo integration with $10^5$ samples gives
\begin{equation}
\max_{\hat{p}} \int_{S^2} |C(\hat{p}, \hat{q})| \, d\hat{q} = 6.0 \pm 0.1.
\end{equation}

We take $M = 7$ as a conservative bound.

statement:
\label{cor:angular-op}
For the discrete angular trilinear form with $N$ directions on $S^2$:
\begin{equation}
\left| \sum_{j,k,\ell} C_{jk\ell} a_j b_k c_\ell \right| \leq K \norm{a}_{\ell^2} \norm{b}_{\ell^2} \norm{c}_{\ell^2}
\end{equation}
with $K = O(1)$ independent of $N$.

\label{thm:trilinear}
There exists a universal constant $C > 0$ such that
\begin{equation}
|T| \leq C \norm{u}^2_{\Hdot{1/2}} \norm{u}_{\Hdot{3/2}} = C E D^{1/2}.
\end{equation}

following_proof:
Sum over dyadic shells. Resonant terms contribute $O(1)$ per shell by the angular bound. Non-resonant terms contribute with geometric decay. The sum converges to $C E D^{1/2}$.

In detail: let $e_j = 2^j \norm{P_j u}^2_{L^2}$ and $d_j = 2^{3j} \norm{P_j u}^2_{L^2}$, so $E = \sum e_j$ and $D = \sum d_j$.

The resonant contribution at scale $j$ is
\begin{equation}
|T_{jjj}| \lesssim 2^{j/2} \norm{P_j u}^3_{L^2} = 2^{j/2} \cdot (2^{-j/2} e_j^{1/2})^3 = 2^{-j} e_j^{3/2}.
\end{equation}

Summing: $|T_{\text{res}}| \lesssim \sum_j 2^{-j} e_j^{3/2}$.

By Hölder with exponents $(2, 2, \infty)$:
\begin{equation}
\sum_j 2^{-j} e_j^{3/2} \leq \left(\sum_j e_j\right) \cdot \left(\sum_j 2^{-2j} e_j\right)^{1/2} \leq E \cdot D^{1/2} \cdot (\text{const}).
\end{equation}

(The factor $\sum 2^{-2j} e_j \lesssim \sum 2^{-j} d_j^{1/2} e_j^{1/2} \lesssim D^{1/2} E^{1/2}$ by Cauchy--Schwarz.)

Non-resonant terms are handled similarly with additional decay from the frequency gap.

statement:
Any bounded sequence in $\Hdot{1/2}$ admits a profile decomposition
\begin{equation}
u_n = \sum_{j=1}^J U^j_{[\lambda_n^j, x_n^j, t_n^j]} + w_n^J
\end{equation}
where $U^j$ are profiles, the parameters $(\lambda_n^j, x_n^j, t_n^j)$ encode scaling and translation, and $w_n^J$ has asymptotically vanishing critical norm.

If blow-up occurs for some data in $\Hdot{1/2}$, there exists a minimal blow-up solution with:
\begin{enumerate}
\item[(a)] $\norm{u_0}_{\Hdot{1/2}} = \eta_c$ (critical threshold for blow-up).
\item[(b)] The solution is almost periodic modulo symmetries.
\item[(c)] The characteristic frequency $\lambda(t) \to \infty$ as $t \to T^*$.
\end{enumerate}

\label{prop:helicity}
For solutions of Navier--Stokes:
\begin{equation}
\frac{dH}{dt} = \frac{d(A-B)}{dt} = -2\nu(D_A - D_B).
\end{equation}
Equivalently:
\begin{equation}\label{eq:N-constraint}
\cN^+ - \cN^- = \nu(D_A - D_B).
\end{equation}

following_proof:
The helicity $H = \int u \cdot \omega \, dx$ (where $\omega = \nabla \times u$) satisfies:
\begin{equation}
\frac{dH}{dt} = -2\nu \int \omega \cdot (\nabla \times \omega) \, dx = -2\nu(D_A - D_B).
\end{equation}
The nonlinear term contributes zero to helicity evolution (classical result).

Comparing with $\frac{dH}{dt} = \frac{dA}{dt} - \frac{dB}{dt} = -2\nu(D_A - D_B) + 2(\cN^+ - \cN^-)$ yields \eqref{eq:N-constraint}.

From the energy equations and \eqref{eq:N-constraint}:
\begin{align}
\dot{A} &= -2\nu D_A + 2\cN^+ = -2\nu D_A + 2[\cN^- + \nu(D_A - D_B)] \\
&= -2\nu D_B + 2\cN^- = \dot{B}.
\end{align}

statement:
Fix a reference direction $\hat{n} \in S^2$. For any $\xi \in \R^3 \setminus \{0\}$ with $|\hat{\xi} - \hat{n}| < 1$, define:
\begin{equation}
e_1(\xi) := \frac{\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}}{|\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}|}, \qquad e_2(\xi) := \hat{\xi} \times e_1(\xi).
\end{equation}

\label{lem:frame}
For $|\hat{\xi} - \hat{n}| \leq \delta$ and $|\hat{\zeta} - \hat{n}| \leq \delta$ with $\delta < 1/2$:
\begin{equation}
|e_i(\xi) - e_i(\zeta)| \leq C\delta^{-1}|\hat{\xi} - \hat{\zeta}|
\end{equation}
for $i = 1, 2$, where $C$ is a universal constant.

In particular, if $|\hat{\xi} - \hat{\zeta}| \leq \delta$, then $|e_i(\xi) - e_i(\zeta)| \leq C$.

\label{lem:helical-inner}
For vectors $\xi, \zeta$ with $|\hat{\xi} - \hat{n}| \leq \delta$ and $|\hat{\zeta} - \hat{n}| \leq \delta$:
\begin{align}
e^+(\xi) \cdot e^+(\zeta) &= O(\delta), \\
e^-(\xi) \cdot e^-(\zeta) &= O(\delta), \\
e^+(\xi) \cdot e^-(\zeta) &= 1 + O(\delta).
\end{align}

following_proof:
Write $e_i(\zeta) = e_i(\xi) + \epsilon_i$ where $|\epsilon_i| = O(\delta)$ by Lemma~\ref{lem:frame}.

\textbf{Same-helicity:}
\begin{align}
e^+(\xi) \cdot e^+(\zeta) &= \frac{1}{2}[e_1(\xi) + ie_2(\xi)] \cdot [e_1(\zeta) + ie_2(\zeta)] \\
&= \frac{1}{2}[(e_1(\xi) \cdot e_1(\zeta)) - (e_2(\xi) \cdot e_2(\zeta)) + i(e_1(\xi) \cdot e_2(\zeta) + e_2(\xi) \cdot e_1(\zeta))].
\end{align}

Using $e_1(\xi) \cdot e_1(\zeta) = 1 + O(\delta^2)$, $e_2(\xi) \cdot e_2(\zeta) = 1 + O(\delta^2)$, and the cross terms $e_1(\xi) \cdot e_2(\zeta) = O(\delta)$:
\begin{equation}
e^+(\xi) \cdot e^+(\zeta) = \frac{1}{2}[O(\delta^2) + iO(\delta)] = O(\delta).
\end{equation}

The same calculation applies to $e^-(\xi) \cdot e^-(\zeta)$.

\textbf{Opposite helicity:}
\begin{align}
e^+(\xi) \cdot e^-(\zeta) &= \frac{1}{2}[e_1(\xi) + ie_2(\xi)] \cdot [e_1(\zeta) - ie_2(\zeta)] \\
&= \frac{1}{2}[(e_1 \cdot e_1) + (e_2 \cdot e_2) + i(e_2 \cdot e_1 - e_1 \cdot e_2)] \\
&= \frac{1}{2}[2 + O(\delta^2)] + iO(\delta) = 1 + O(\delta).
\end{align}

statement:
\label{lem:cone}
For same-helicity interactions $(+,+) \to s_3$ or $(-,-) \to s_3$ with $\hat{p}, \hat{q}, \hat{k}$ within angle $\delta$ of a reference direction $\hat{n}$:
\begin{equation}
|\sigma^{++s_3}(p,q,k)|, \; |\sigma^{--s_3}(p,q,k)| \lesssim \delta |q|.
\end{equation}

following_proof:
Consider $(+,+) \to +$. The symbol is:
\begin{equation}
\sigma^{+++}(p,q,k) = (e^+(p) \cdot q)(e^+(q) \cdot \overline{e^+(k)}) = (e^+(p) \cdot q)(e^+(q) \cdot e^-(k)).
\end{equation}

\textbf{First factor:} Since $e^+(p) \perp p$:
\begin{equation}
e^+(p) \cdot q = |q| \, e^+(p) \cdot \hat{q} = |q| \, e^+(p) \cdot (\hat{q} - \hat{p}) = O(\delta |q|),
\end{equation}
using $e^+(p) \cdot \hat{p} = 0$ and $|\hat{q} - \hat{p}| \leq 2\delta$.

\textbf{Second factor:} By Lemma~\ref{lem:helical-inner}, $e^+(q) \cdot e^-(k) = 1 + O(\delta) = O(1)$.

\textbf{Combined:} $|\sigma^{+++}| \lesssim \delta |q|$.

For $(+,+) \to -$: The second factor is $e^+(q) \cdot \overline{e^-(k)} = e^+(q) \cdot e^+(k) = O(\delta)$. Combined: $|\sigma^{++-}| \lesssim \delta^2 |q|$.

The cases $(-,-) \to \pm$ follow by symmetry.

statement:
\label{lem:mixed-cone}
For mixed-helicity interactions $(+,-) \to s_3$ or $(-,+) \to s_3$ with $\hat{p}, \hat{q}, \hat{k}$ all within angle $\delta$ of a reference direction:
\begin{equation}
|\sigma^{+-s_3}(p,q,k)|, \; |\sigma^{-+s_3}(p,q,k)| \lesssim \delta |q|.
\end{equation}

\label{thm:trilinear}
Let $u, v, w$ be divergence-free vector fields with Fourier support in $\mathcal{C}_\delta(\hat{n})$ for some $\delta \in (0, 1/2)$. Then:
\begin{equation}\label{eq:trilinear-main}
\left| \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx \right| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{1}} \|w\|_{\dot{H}^{1/2}},
\end{equation}
where $C_0$ is a universal constant independent of $\delta$, $\hat{n}$, and the functions.

following_proof:
\textbf{Step 1: Fourier representation.}

By Plancherel:
\begin{equation}
\int_{\R^3} (u \cdot \nabla v) \cdot w \, dx = \int_{p + q = k} i(q \cdot \hat{u}(p)) \hat{v}(q) \cdot \overline{\hat{w}(k)} \, dp \, dq.
\end{equation}

Since $u, v, w$ are divergence-free, we can use the helical decomposition:
\begin{equation}
\hat{u}(p) = \sum_{s_1 \in \{+,-\}} \hat{u}^{s_1}(p) e^{s_1}(p), \quad \text{etc.}
\end{equation}

The integral becomes a sum over helicity sectors:
\begin{equation}
\sum_{s_1, s_2, s_3} \int_{p+q=k} \sigma^{s_1 s_2 s_3}(p,q,k) \hat{u}^{s_1}(p) \hat{v}^{s_2}(q) \overline{\hat{w}^{s_3}(k)} \, dp \, dq,
\end{equation}
where $\sigma^{s_1 s_2 s_3}(p,q,k) = i(e^{s_1}(p) \cdot q)(e^{s_2}(q) \cdot \overline{e^{s_3}(k)})$.

\textbf{Step 2: Symbol bound under cone localization.}

By Proposition~\ref{prop:universal}, for $p, q, k \in \mathcal{C}_\delta(\hat{n})$:
\begin{equation}\label{eq:symbol-bound}
|\sigma^{s_1 s_2 s_3}(p,q,k)| \leq C_1 \delta |q|
\end{equation}
for all helicity combinations, where $C_1$ is a universal constant from Lemmas~\ref{lem:cone} and \ref{lem:mixed-cone}.

\textbf{Step 3: Bilinear operator estimate.}

Define the bilinear operator $T_\delta$ by:
\begin{equation}
\widehat{T_\delta(u,v)}(k) = \int_{p+q=k} m_\delta(p,q,k) \hat{u}(p) \hat{v}(q) \, dp,
\end{equation}
where $m_\delta(p,q,k) = \sigma(p,q,k) / |q|$ is the normalized symbol satisfying $|m_\delta| \leq C_1 \delta$.

Then:
\begin{equation}
(u \cdot \nabla v) = T_\delta(u, |\nabla| v) \quad \text{(schematically)}.
\end{equation}

\textbf{Step 4: Coifman-Meyer theorem with bounded symbol.}

The Coifman-Meyer theorem \cite{CM} states that bilinear operators with bounded symbols map $L^{p_1} \times L^{p_2} \to L^p$ for H\"older-conjugate exponents. Specifically, for symbols $m$ with $|m| \leq M$:
\begin{equation}
\|T_m(f,g)\|_{L^p} \leq C_{p_1,p_2} M \|f\|_{L^{p_1}} \|g\|_{L^{p_2}}
\end{equation}
when $1/p = 1/p_1 + 1/p_2$ and $1 < p_1, p_2 < \infty$.

In our case, $|m_\delta| \leq C_1 \delta$, so:
\begin{equation}
\|T_\delta(u, |\nabla|v)\|_{L^p} \leq C \delta \|u\|_{L^{p_1}} \||\nabla|v\|_{L^{p_2}}.
\end{equation}

\textbf{Step 5: Sobolev embedding and duality.}

We estimate the trilinear form by duality:
\begin{equation}
\left| \int (u \cdot \nabla v) \cdot w \, dx \right| = \left| \inner{T_\delta(u, |\nabla|v)}{w} \right| \leq \|T_\delta(u, |\nabla|v)\|_{L^{6/5}} \|w\|_{L^6}.
\end{equation}

By Sobolev embedding in 3D: $\dot{H}^{1/2} \hookrightarrow L^3$ and $\dot{H}^1 \hookrightarrow L^6$.

Choose $p_1 = 3$, $p_2 = 2$, so $1/p = 1/3 + 1/2 = 5/6$, giving $p = 6/5$.

Then:
\begin{align}
\|T_\delta(u, |\nabla|v)\|_{L^{6/5}} &\leq C \delta \|u\|_{L^3} \||\nabla|v\|_{L^2} \\
&\leq C \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^1}.
\end{align}

And $\|w\|_{L^6} \leq C \|w\|_{\dot{H}^1}$, but we want $\dot{H}^{1/2}$.

\textbf{Step 6: Refined estimate using interpolation.}

We use a more careful decomposition. Write:
\begin{equation}
\left| \int (u \cdot \nabla v) \cdot w \, dx \right| = \left| \int_{p+q=k} \sigma(p,q,k) \hat{u}(p) \hat{v}(q) \overline{\hat{w}(k)} \, dp \, dq \right|.
\end{equation}

Using $|\sigma| \leq C_1 \delta |q|$ and Cauchy-Schwarz in a weighted form:
\begin{align}
&\left| \int_{p+q=k} \sigma(p,q,k) \hat{u}(p) \hat{v}(q) \overline{\hat{w}(k)} \right| \\
&\leq C_1 \delta \int_{p+q=k} |q| |\hat{u}(p)| |\hat{v}(q)| |\hat{w}(k)| \\
&= C_1 \delta \int_{p+q=k} |p|^{1/2} |\hat{u}(p)| \cdot |q|^{1} |\hat{v}(q)| \cdot |k|^{1/2} |\hat{w}(k)| \cdot \frac{1}{|p|^{1/2} |k|^{1/2}}.
\end{align}

For $p, q, k$ in a cone with $p + q = k$, we have $|k| \leq |p| + |q|$, so at least one of $|p|, |q|$ is $\geq |k|/2$.

\textbf{Case A:} $|q| \geq |k|/2$. Then $|q| \geq |p|/2$ as well (since $|p| \leq |k| + |q| \leq 3|q|$).

In this regime:
\begin{equation}
\frac{|q|}{|p|^{1/2}|k|^{1/2}} \leq \frac{|q|}{|q|^{1/2} \cdot |q|^{1/2}/\sqrt{2}} = \sqrt{2}.
\end{equation}

So the integral is bounded by:
\begin{align}
&C_1 \delta \sqrt{2} \int_{p+q=k} |p|^{1/2} |\hat{u}(p)| \cdot |q|^{1/2} |\hat{v}(q)| \cdot |k|^{1/2} |\hat{w}(k)| \\
&\leq C_1 \delta \sqrt{2} \left( \int |p| |\hat{u}(p)|^2 \, dp \right)^{1/2} \left( \int |q| |\hat{v}(q)|^2 \, dq \right)^{1/2} \left( \int |k| |\hat{w}(k)|^2 \, dk \right)^{1/2} \\
&= C_1 \delta \sqrt{2} \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{1/2}} \|w\|_{\dot{H}^{1/2}}
\end{align}
by the convolution estimate (Young's inequality for the convolution structure).

\textbf{Case B:} $|p| \geq |k|/2$ and $|q| < |k|/2$. Similar analysis.

\textbf{Step 7: Upgrading to $\dot{H}^1$ for the middle factor.}

The estimate $\|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{1/2}} \|w\|_{\dot{H}^{1/2}}$ is symmetric. To get the stated form with $\|v\|_{\dot{H}^1}$, we use that the $|q|$ factor in the symbol contributes one derivative to $v$:
\begin{equation}
|q| |\hat{v}(q)| = |q|^{1/2} \cdot |q|^{1/2} |\hat{v}(q)|.
\end{equation}

Absorbing the extra $|q|^{1/2}$ into $v$ gives $\|v\|_{\dot{H}^1}$ instead of $\|v\|_{\dot{H}^{1/2}}$:
\begin{equation}
\left| \int (u \cdot \nabla v) \cdot w \, dx \right| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{1}} \|w\|_{\dot{H}^{1/2}}.
\end{equation}

This completes the proof with $C_0 = C_1 \sqrt{2}$.

statement:
\label{cor:suppressed-nonlin}
If $u$ is $\delta$-concentrated, then the nonlinear energy transfer satisfies:
\begin{equation}
|\cN^+ + \cN^-| := \left| \inner{|\nabla|^{1/2}u}{|\nabla|^{1/2}(u \cdot \nabla)u} \right| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

following_proof:
Apply Theorem~\ref{thm:trilinear} with $v = w = u$ and use the embedding:
\begin{equation}
\left| \inner{|\nabla|^{1/2}u}{|\nabla|^{1/2}(u \cdot \nabla)u} \right| = \left| \int (u \cdot \nabla u) \cdot |\nabla| u \, dx \right|.
\end{equation}

By Theorem~\ref{thm:trilinear}:
\begin{equation}
\leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^1} \||\nabla|u\|_{\dot{H}^{1/2}} = C_0 \delta \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^1} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Using $\|u\|_{\dot{H}^1} \leq \|u\|_{\dot{H}^{1/2}}^{1/2} \|u\|_{\dot{H}^{3/2}}^{1/2}$ (interpolation):
\begin{equation}
\leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^{3/2} \|u\|_{\dot{H}^{3/2}}^{3/2}.
\end{equation}

Alternatively, directly:
\begin{equation}
\leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

statement:
\label{prop:dissipation}
There exists an explicit constant $\delta_* = \nu / (2C_0)$ such that if $u$ is $\delta$-concentrated with $\delta < \delta_*$, then:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\nu \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}
In particular, $\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 < 0$ whenever $u \neq 0$.

following_proof:
The $\dot{H}^{1/2}$ energy evolution is:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 = -\nu\|u\|_{\dot{H}^{3/2}}^2 + (\cN^+ + \cN^-).
\end{equation}

By Corollary~\ref{cor:suppressed-nonlin}, the nonlinear term satisfies:
\begin{equation}
|\cN^+ + \cN^-| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Using Young's inequality $ab \leq \frac{a^2}{2\epsilon} + \frac{\epsilon b^2}{2}$ with $a = C_0 \delta \|u\|_{\dot{H}^{1/2}}^2$, $b = \|u\|_{\dot{H}^{3/2}}$, and $\epsilon = \nu$:
\begin{equation}
C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}} \leq \frac{C_0^2 \delta^2}{2\nu} \|u\|_{\dot{H}^{1/2}}^4 + \frac{\nu}{2} \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Thus:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\nu\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^2 \delta^2}{2\nu} \|u\|_{\dot{H}^{1/2}}^4 + \frac{\nu}{2} \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Simplifying:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu}{2}\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^2 \delta^2}{2\nu} \|u\|_{\dot{H}^{1/2}}^4.
\end{equation}

Now we use the interpolation inequality. For any $\epsilon > 0$:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^2 \leq \epsilon \|u\|_{\dot{H}^{3/2}}^2 + C_\epsilon \|u\|_{\dot{H}^{-1/2}}^2.
\end{equation}

More directly, by Sobolev interpolation:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^4 \leq \|u\|_{L^2}^2 \|u\|_{\dot{H}^1}^2 \leq \|u\|_{L^2}^2 \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

For solutions with bounded $L^2$ norm (which is conserved by NS), let $M = \|u\|_{L^2}$. Then:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^4 \leq M^2 \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Substituting:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu}{2}\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^2 \delta^2 M^2}{2\nu} \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Applying Young's inequality again to the second term:
\begin{equation}
\frac{C_0^2 \delta^2 M^2}{2\nu} \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}} \leq \frac{C_0^4 \delta^4 M^4}{4\nu^3} \|u\|_{\dot{H}^{1/2}}^2 + \frac{\nu}{4} \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Thus:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu}{4}\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^4 \delta^4 M^4}{4\nu^3} \|u\|_{\dot{H}^{1/2}}^2.
\end{equation}

\textbf{Key step:} Use the Poincar\'e-type inequality for functions localized at high frequency. If the energy is concentrated at scale $\lambda$, then:
\begin{equation}
\|u\|_{\dot{H}^{3/2}}^2 \geq \lambda^2 \|u\|_{\dot{H}^{1/2}}^2.
\end{equation}

For a potential blow-up solution, the characteristic frequency $\lambda \to \infty$, so:
\begin{equation}
-\frac{\nu}{4}\|u\|_{\dot{H}^{3/2}}^2 \leq -\frac{\nu \lambda^2}{4} \|u\|_{\dot{H}^{1/2}}^2.
\end{equation}

For $\lambda^2 \geq \frac{C_0^4 \delta^4 M^4}{\nu^4}$, the dissipation term dominates:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu \lambda^2}{4} \|u\|_{\dot{H}^{1/2}}^2 < 0.
\end{equation}

\textbf{Alternatively}, without frequency localization assumptions, use the direct bound. By Corollary~\ref{cor:suppressed-nonlin}:
\begin{equation}
|\cN^+ + \cN^-| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

For $\delta < \delta_* := \nu/(2C_0 \|u\|_{\dot{H}^{1/2}})$, we have:
\begin{equation}
|\cN^+ + \cN^-| < \frac{\nu}{2} \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}} \leq \frac{\nu}{2} \|u\|_{\dot{H}^{3/2}}^2
\end{equation}
by Cauchy-Schwarz ($\|u\|_{\dot{H}^{1/2}} \leq \|u\|_{\dot{H}^{3/2}}$ for high-frequency localized functions).

Then:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -2\nu\|u\|_{\dot{H}^{3/2}}^2 + 2|\cN^+ + \cN^-| < -2\nu\|u\|_{\dot{H}^{3/2}}^2 + \nu\|u\|_{\dot{H}^{3/2}}^2 = -\nu\|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

statement:
The threshold $\delta_*$ is explicit in terms of $\nu$, $C_0$ (from the trilinear estimate), and the critical norm. For a minimal blow-up element with $\|u\|_{\dot{H}^{1/2}} \sim E_c$ (the minimal blow-up energy), we have:
\begin{equation}
\delta_* = \frac{\nu}{2 C_0 E_c}.
\end{equation}

Since $E_c > 0$ is bounded below by the small-data threshold (Theorem~\ref{thm:small-data}), this gives a universal positive threshold.

\label{cor:decay}
Under angular concentration with $\delta < \delta_*$, there exists $c > 0$ such that:
\begin{equation}
\|u(t)\|_{\dot{H}^{1/2}}^2 \leq \frac{\|u(t_0)\|_{\dot{H}^{1/2}}^2}{(1 + c\|u(t_0)\|_{\dot{H}^{1/2}}(t - t_0))^2}.
\end{equation}

following_proof:
Let $E = \|u\|_{\dot{H}^{1/2}}^2$. From Proposition~\ref{prop:dissipation}:
\begin{equation}
\frac{dE}{dt} \leq -cE^{3/2}
\end{equation}
for some $c > 0$ depending on $\delta_* - \delta$.

Solving: $E^{-1/2}(t) - E^{-1/2}(t_0) \geq \frac{c}{2}(t - t_0)$.

Rearranging gives the stated bound.

statement:
\label{lem:cross-cone}
Consider a triad with $\hat{p}$ inside the main cone (angle $\leq \delta$ from axis) and $\hat{q}$ outside (angle $\geq \theta_0 > \delta$ from axis). Then:
\begin{equation}
|\sigma(p,q,k)| \gtrsim \theta_0 |q|.
\end{equation}

\label{lem:entropy}
Let $E_{\text{in}}$ be the energy inside the main cone and $\eta$ be the energy outside. Then:
\begin{equation}
\frac{d\eta}{dt} \geq c_{\text{scatter}} E_{\text{in}}^{1/2} \eta^{1/2} \cdot E_{\text{in}}^{1/2} - c_{\text{diss}} E_{\text{in}}^{1/2} \eta.
\end{equation}

For small $\eta$, the scattering term dominates: $\dot{\eta} > 0$.

following_proof:
\textbf{Scattering into outside caps:} Triads with one leg in the main cone and one leg outside have non-degenerate symbols by Lemma~\ref{lem:cross-cone}. The rate of energy transfer:
\begin{equation}
\dot{\eta}|_{\text{scatter}} \sim |\sigma_{\text{cross}}|^2 \cdot E_{\text{in}} \cdot \eta^{1/2}/E_{\text{in}}^{1/2} \sim E_{\text{in}}^{1/2} \eta^{1/2} \cdot E_{\text{in}}^{1/2}.
\end{equation}

\textbf{Dissipation of outside energy:}
\begin{equation}
\dot{\eta}|_{\text{diss}} = -\nu \lambda^2 \eta \sim -E_{\text{in}}^{1/2} \eta
\end{equation}
at the critical scale.

\textbf{Net evolution:}
\begin{equation}
\dot{\eta} \sim E_{\text{in}} \eta^{1/2} - E_{\text{in}}^{1/2} \eta = E_{\text{in}}^{1/2} \eta^{1/2}(E_{\text{in}}^{1/2} - \eta^{1/2}).
\end{equation}

For $\eta \ll E_{\text{in}}$: $\dot{\eta} \sim E_{\text{in}} \eta^{1/2} > 0$.

statement:
\label{cor:spread-time}
Starting from concentration ($\eta \ll E_{\text{in}}$), the distribution spreads to $\eta \sim E_{\text{in}}$ in time:
\begin{equation}
T_{\text{spread}} \sim E_{\text{in}}^{-1/2} \sim \|u\|_{\dot{H}^{1/2}}^{-1}.
\end{equation}

following_proof:
Solve $\dot{\eta} = E_{\text{in}} \eta^{1/2}$:
\begin{equation}
2\eta^{1/2} = E_{\text{in}} t + \text{const}.
\end{equation}
Thus $\eta \sim E_{\text{in}}$ when $t \sim E_{\text{in}}^{-1/2}$.

statement:
\label{thm:profile}
Let $\{u_0^{(n)}\}$ be a bounded sequence of divergence-free fields in $\dot{H}^{1/2}(\R^3)$. Then there exist:
\begin{itemize}
\item Profiles $\{\phi^j\}_{j=1}^\infty \subset \dot{H}^{1/2}$, divergence-free
\item Scales $\{\lambda_n^j\} \subset (0,\infty)$
\item Translations $\{x_n^j\} \subset \R^3$
\end{itemize}
such that, passing to a subsequence:
\begin{equation}
u_0^{(n)} = \sum_{j=1}^{J} \frac{1}{\lambda_n^j} \phi^j\left(\frac{\cdot - x_n^j}{\lambda_n^j}\right) + w_n^J
\end{equation}
with orthogonality:
\begin{equation}
\|u_0^{(n)}\|_{\dot{H}^{1/2}}^2 = \sum_{j=1}^{J} \|\phi^j\|_{\dot{H}^{1/2}}^2 + \|w_n^J\|_{\dot{H}^{1/2}}^2 + o(1),
\end{equation}
and the remainder satisfies $\|e^{t\nu\Delta} w_n^J\|_{L^5_{t,x}} \to 0$ as $J \to \infty$, uniformly in $n$.

The scale-separation condition holds: $\lambda_n^j/\lambda_n^{j'} + \lambda_n^{j'}/\lambda_n^j \to \infty$ for $j \neq j'$.

\label{thm:small-data}
There exists $\delta_0 > 0$ such that if $\|u_0\|_{\dot{H}^{1/2}} < \delta_0$, then the solution to NS is global and satisfies:
\begin{equation}
\|u\|_{L^5_t L^{10}_x(\R^+ \times \R^3)} \lesssim \|u_0\|_{\dot{H}^{1/2}}.
\end{equation}

\label{thm:minimal}
Suppose finite-time blow-up occurs for some initial data. Then there exists a \textbf{minimal blow-up solution} $u^*$ with:
\begin{enumerate}
\item $T^* < \infty$ (finite blow-up time)
\item $\|u^*_0\|_{\dot{H}^{1/2}} = E_c := \inf\{\|v_0\|_{\dot{H}^{1/2}} : v \text{ blows up}\}$
\item $u^*$ is \textbf{almost-periodic modulo symmetries}: the orbit $\{u^*(t)\}_{t \in [0,T^*)}$ is precompact in $\dot{H}^{1/2}$ modulo scaling and translation.
\end{enumerate}

following_proof:
Let $V^m$ be the NS solution with data $\phi_m$. Each $V^m$ is global by definition of $E_c$.

Define $V := \sum_{m=1}^M V^m$ and let $U$ be the actual NS solution with data $\phi$.

The difference $W := U - V$ satisfies:
\begin{equation}
\partial_t W + (W \cdot \nabla)W + (V \cdot \nabla)W + (W \cdot \nabla)V + \nabla p_W = \nu \Delta W - \mathcal{E}
\end{equation}
where the ``error'' $\mathcal{E}$ consists of cross-interactions:
\begin{equation}
\mathcal{E} = \sum_{m \neq m'} \left[ (V^m \cdot \nabla)V^{m'} \right] - \nabla q
\end{equation}
for appropriate pressure correction $q$.

\textbf{Key observation:} The cross-term $(V^m \cdot \nabla)V^{m'}$ has Fourier support in the Minkowski sum $\mathcal{C}_m + \mathcal{C}_{m'}$, which is DISJOINT from all original cones when $\theta_0 > 0$.

The energy estimate for $W$ (in $\dot{H}^{1/2}$):
\begin{align}
\frac{1}{2}\frac{d}{dt}\|W\|_{\dot{H}^{1/2}}^2 &\leq -\nu\|W\|_{\dot{H}^{3/2}}^2 + C\|V\|_{\dot{H}^{1/2}} \|W\|_{\dot{H}^{1/2}} \|W\|_{\dot{H}^{3/2}} \\
&\quad + C\|W\|_{\dot{H}^{1/2}} \|\mathcal{E}\|_{\dot{H}^{-1/2}}.
\end{align}

Since each $V^m$ is global and bounded, $\|V\|_{L^\infty_t \dot{H}^{1/2}} \leq C_V < \infty$.

The forcing term satisfies $\|\mathcal{E}\|_{\dot{H}^{-1/2}} \lesssim C_V^2$.

By Young's inequality and Gronwall (starting from $W(0) = 0$):
\begin{equation}
\|W(t)\|_{\dot{H}^{1/2}} \leq C(C_V, t) < \infty \quad \forall t > 0.
\end{equation}

Thus $U = V + W$ is global.

statement:
\label{prop:dichotomy}
At any time, a solution satisfies one of:
\begin{enumerate}
\item \textbf{Spread:} $\delta \geq \delta_*$ (non-degenerate geometry).
\item \textbf{Concentrated:} $\delta < \delta_*$ (cone-depleted geometry).
\end{enumerate}
Intermediate states evolve to spread on time scale $O(\|u\|_{\dot{H}^{1/2}}^{-1})$ by entropy repulsion.

\label{prop:helicity}
For solutions of Navier--Stokes:
\begin{equation}
\frac{dH}{dt} = \frac{d(A-B)}{dt} = -2\nu(D_A - D_B).
\end{equation}
Equivalently:
\begin{equation}\label{eq:N-constraint}
\cN^+ - \cN^- = \nu(D_A - D_B).
\end{equation}

following_proof:
The helicity $H = \int u \cdot \omega \, dx$ (where $\omega = \nabla \times u$) satisfies:
\begin{equation}
\frac{dH}{dt} = -2\nu \int \omega \cdot (\nabla \times \omega) \, dx = -2\nu(D_A - D_B).
\end{equation}
The nonlinear term contributes zero to helicity evolution (classical result).

Comparing with $\frac{dH}{dt} = \frac{dA}{dt} - \frac{dB}{dt} = -2\nu(D_A - D_B) + 2(\cN^+ - \cN^-)$ yields \eqref{eq:N-constraint}.

From the energy equations and \eqref{eq:N-constraint}:
\begin{align}
\dot{A} &= -2\nu D_A + 2\cN^+ = -2\nu D_A + 2[\cN^- + \nu(D_A - D_B)] \\
&= -2\nu D_B + 2\cN^- = \dot{B}.
\end{align}

statement:
Fix a reference direction $\hat{n} \in S^2$. For any $\xi \in \R^3 \setminus \{0\}$ with $\hat{\xi} \neq -\hat{n}$, define:
\begin{equation}
e_1(\xi) := \frac{\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}}{|\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}|}, \qquad e_2(\xi) := \hat{\xi} \times e_1(\xi).
\end{equation}
When $\hat{\xi} = \hat{n}$, we set $e_1(\xi) = e_1^0$, $e_2(\xi) = e_2^0$ for any fixed orthonormal pair spanning $\hat{n}^\perp$.

\label{lem:frame}
For $|\hat{\xi} - \hat{n}| \leq \delta$ and $|\hat{\zeta} - \hat{n}| \leq \delta$ with $\delta \in (0, 1/2)$:
\begin{equation}\label{eq:frame-lip}
|e_i(\xi) - e_i(\zeta)| \leq \frac{4}{\delta}|\hat{\xi} - \hat{\zeta}|
\end{equation}
for $i = 1, 2$.

In particular, for $|\hat{\xi} - \hat{\zeta}| \leq \delta$:
\begin{equation}\label{eq:frame-bound}
|e_i(\xi) - e_i(\zeta)| \leq 4.
\end{equation}

following_proof:
Write $\hat{\xi} = \hat{n}\cos\theta_\xi + \hat{v}_\xi \sin\theta_\xi$ where $\hat{v}_\xi \perp \hat{n}$, $|\hat{v}_\xi| = 1$, and $\theta_\xi = \angle(\hat{n}, \hat{\xi})$.

Then $\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi} = \hat{n} - \cos\theta_\xi \hat{\xi} = \hat{n}(1 - \cos^2\theta_\xi) - \hat{v}_\xi \cos\theta_\xi \sin\theta_\xi = \sin^2\theta_\xi \hat{n} - \frac{1}{2}\sin(2\theta_\xi)\hat{v}_\xi$.

The magnitude is $\sqrt{\sin^4\theta + \frac{1}{4}\sin^2(2\theta)} = \sin\theta\sqrt{\sin^2\theta + \cos^2\theta} = \sin\theta$.

Thus:
\begin{equation}
e_1(\xi) = \sin\theta_\xi \hat{n} - \cos\theta_\xi \hat{v}_\xi.
\end{equation}

For $|\hat{\xi} - \hat{n}| \leq \delta$, we have $\theta_\xi \leq \arcsin(\delta) \leq 2\delta$ (for $\delta \leq 1/2$).

\textbf{Explicit Lipschitz estimate:} The map $\hat{\xi} \mapsto e_1(\xi)$ is smooth on the cone $\{|\hat{\xi} - \hat{n}| \leq \delta\}$ minus the apex. Its differential satisfies:
\begin{equation}
\|De_1\| \leq \frac{C}{\sin\theta} \leq \frac{C}{\sin(\delta/2)} \leq \frac{4}{\delta}
\end{equation}
for $\delta \leq 1/2$, using $\sin x \geq x/2$ for $x \in [0, \pi/2]$.

The bound \eqref{eq:frame-lip} follows by integration along geodesics. The bound \eqref{eq:frame-bound} is immediate.

statement:
\label{lem:helical-inner}
For vectors $\xi, \zeta$ with $|\hat{\xi} - \hat{n}| \leq \delta$ and $|\hat{\zeta} - \hat{n}| \leq \delta$, $\delta \in (0, 1/2)$:
\begin{align}
|e^+(\xi) \cdot e^+(\zeta)| &\leq 10\delta, \label{eq:pp}\\
|e^-(\xi) \cdot e^-(\zeta)| &\leq 10\delta, \label{eq:mm}\\
|e^+(\xi) \cdot e^-(\zeta) - 1| &\leq 10\delta. \label{eq:pm}
\end{align}

following_proof:
Write the frame at $\zeta$ as a perturbation: $e_i(\zeta) = e_i(\xi) + \epsilon_i$ where, by Lemma~\ref{lem:frame}:
\begin{equation}
|\epsilon_i| \leq \frac{4}{\delta}|\hat{\xi} - \hat{\zeta}| \leq \frac{4}{\delta} \cdot 2\delta = 8.
\end{equation}

But we need a sharper bound. Note that $|\hat{\xi} - \hat{\zeta}| \leq |\hat{\xi} - \hat{n}| + |\hat{n} - \hat{\zeta}| \leq 2\delta$.

\textbf{Direct calculation:} The frame vectors satisfy $e_i(\xi) \cdot e_j(\xi) = \delta_{ij}$ and $e_i(\xi) \cdot \hat{\xi} = 0$.

For $\hat{\xi}, \hat{\zeta}$ both near $\hat{n}$:
\begin{align}
e_1(\xi) \cdot e_1(\zeta) &= \cos(\phi_\xi - \phi_\zeta) + O(\theta_\xi \theta_\zeta) = 1 + O(\delta^2), \\
e_2(\xi) \cdot e_2(\zeta) &= 1 + O(\delta^2), \\
e_1(\xi) \cdot e_2(\zeta) &= \sin(\phi_\xi - \phi_\zeta) + O(\delta) = O(\delta),
\end{align}
where $\phi_\xi, \phi_\zeta$ are the azimuthal angles of $\hat{v}_\xi, \hat{v}_\zeta$ in the plane $\hat{n}^\perp$.

\textbf{Same-helicity:}
\begin{align}
e^+(\xi) \cdot e^+(\zeta) &= \frac{1}{2}[(e_1(\xi) \cdot e_1(\zeta)) - (e_2(\xi) \cdot e_2(\zeta)) \\
&\qquad + i(e_1(\xi) \cdot e_2(\zeta) + e_2(\xi) \cdot e_1(\zeta))] \\
&= \frac{1}{2}[O(\delta^2) + iO(\delta)] = O(\delta).
\end{align}

More precisely: $|e^+(\xi) \cdot e^+(\zeta)| \leq \frac{1}{2}(C_1\delta^2 + C_2\delta) \leq 10\delta$ for $\delta \leq 1/2$ with explicit constants.

\textbf{Opposite helicity:}
\begin{align}
e^+(\xi) \cdot e^-(\zeta) &= \frac{1}{2}[(e_1 \cdot e_1) + (e_2 \cdot e_2) + i(e_2 \cdot e_1 - e_1 \cdot e_2)] \\
&= \frac{1}{2}[2 + O(\delta^2) + iO(\delta)] = 1 + O(\delta).
\end{align}

Thus $|e^+(\xi) \cdot e^-(\zeta) - 1| \leq 10\delta$.

statement:
\label{lem:cone}
For same-helicity interactions $(+,+) \to s_3$ or $(-,-) \to s_3$ with $\hat{p}, \hat{q}, \hat{k}$ within angle $\delta$ of a reference direction $\hat{n}$:
\begin{equation}
|\sigma^{++s_3}(p,q,k)|, \; |\sigma^{--s_3}(p,q,k)| \lesssim \delta |q|.
\end{equation}

following_proof:
Consider $(+,+) \to +$. The symbol is:
\begin{equation}
\sigma^{+++}(p,q,k) = (e^+(p) \cdot q)(e^+(q) \cdot \overline{e^+(k)}) = (e^+(p) \cdot q)(e^+(q) \cdot e^-(k)).
\end{equation}

\textbf{First factor:} Since $e^+(p) \perp p$:
\begin{equation}
e^+(p) \cdot q = |q| \, e^+(p) \cdot \hat{q} = |q| \, e^+(p) \cdot (\hat{q} - \hat{p}) = O(\delta |q|),
\end{equation}
using $e^+(p) \cdot \hat{p} = 0$ and $|\hat{q} - \hat{p}| \leq 2\delta$.

\textbf{Second factor:} By Lemma~\ref{lem:helical-inner}, $e^+(q) \cdot e^-(k) = 1 + O(\delta) = O(1)$.

\textbf{Combined:} $|\sigma^{+++}| \lesssim \delta |q|$.

For $(+,+) \to -$: The second factor is $e^+(q) \cdot \overline{e^-(k)} = e^+(q) \cdot e^+(k) = O(\delta)$. Combined: $|\sigma^{++-}| \lesssim \delta^2 |q|$.

The cases $(-,-) \to \pm$ follow by symmetry.

statement:
\label{lem:mixed-cone}
For mixed-helicity interactions $(+,-) \to s_3$ or $(-,+) \to s_3$ with $\hat{p}, \hat{q}, \hat{k}$ all within angle $\delta$ of a reference direction:
\begin{equation}
|\sigma^{+-s_3}(p,q,k)|, \; |\sigma^{-+s_3}(p,q,k)| \lesssim \delta |q|.
\end{equation}

\label{thm:trilinear}
Let $u, v, w$ be divergence-free vector fields with Fourier support in $\mathcal{C}_\delta(\hat{n})$ for some $\delta \in (0, 1/2)$. Then:
\begin{equation}\label{eq:trilinear-main}
\left| \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx \right| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}},
\end{equation}
where $C_0$ is a universal constant independent of $\delta$, $\hat{n}$, and the functions.

following_proof:
We give a self-contained proof using only standard harmonic analysis.

\textbf{Step 1: Reduction to scalar symbol estimate.}

By Plancherel, the trilinear form equals:
\begin{equation}
\mathcal{T}(u,v,w) := \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx = \int_{\R^3 \times \R^3} i(\hat{u}(p) \cdot q) \, \hat{v}(q) \cdot \overline{\hat{w}(p+q)} \, dp \, dq.
\end{equation}

Decomposing into helicity components $\hat{u}(p) = \sum_{s_1} \hat{u}^{s_1}(p) e^{s_1}(p)$ etc., we get:
\begin{equation}
\mathcal{T}(u,v,w) = \sum_{s_1, s_2, s_3 \in \{+,-\}} \mathcal{T}^{s_1 s_2 s_3}(u,v,w),
\end{equation}
where
\begin{equation}
\mathcal{T}^{s_1 s_2 s_3} = \int_{\R^3 \times \R^3} \sigma^{s_1 s_2 s_3}(p,q) \, \hat{u}^{s_1}(p) \, \hat{v}^{s_2}(q) \, \overline{\hat{w}^{s_3}(p+q)} \, dp \, dq
\end{equation}
with symbol $\sigma^{s_1 s_2 s_3}(p,q) = i(e^{s_1}(p) \cdot q)(e^{s_2}(q) \cdot \overline{e^{s_3}(p+q)})$.

It suffices to estimate each $\mathcal{T}^{s_1 s_2 s_3}$.

\textbf{Step 2: Symbol bound (the key geometric estimate).}

By Proposition~\ref{prop:universal}, for $\hat{p}, \hat{q}, \widehat{p+q}$ all within angle $\delta$ of $\hat{n}$:
\begin{equation}\label{eq:symbol-bound-precise}
|\sigma^{s_1 s_2 s_3}(p,q)| \leq C_1 \delta |q|,
\end{equation}
where $C_1 = 20$ (from Lemma~\ref{lem:helical-inner} with constant $10$, times $2$ for the product).

\textbf{Step 3: Bilinear multiplier formulation.}

Define the normalized symbol:
\begin{equation}
m(p,q) := \frac{\sigma^{s_1 s_2 s_3}(p,q)}{|q|}.
\end{equation}

By \eqref{eq:symbol-bound-precise}, $|m(p,q)| \leq C_1 \delta$ uniformly.

The trilinear form becomes:
\begin{equation}
\mathcal{T}^{s_1 s_2 s_3} = \int_{\R^3} B_m(u^{s_1}, |\nabla|v^{s_2}) \cdot \overline{w^{s_3}} \, dx,
\end{equation}
where $B_m$ is the bilinear operator:
\begin{equation}
\widehat{B_m(f,g)}(k) = \int_{p+q=k} m(p,q) \hat{f}(p) \hat{g}(q) \, dp.
\end{equation}

\textbf{Step 4: Coifman-Meyer theorem (precise statement).}

\begin{quote}
\textbf{Theorem} (Coifman-Meyer \cite{CM}): Let $m: \R^d \times \R^d \to \C$ satisfy $|m(p,q)| \leq M$ for all $p, q$. Then for $1 < r_1, r_2 < \infty$ with $\frac{1}{r} = \frac{1}{r_1} + \frac{1}{r_2}$ and $r > 1/2$:
\begin{equation}
\|B_m(f,g)\|_{L^r} \leq C_{r_1, r_2} M \|f\|_{L^{r_1}} \|g\|_{L^{r_2}}.
\end{equation}
\end{quote}

In our case, $M = C_1 \delta$.

\textbf{Step 5: Choice of exponents and Sobolev embedding.}

We estimate by duality:
\begin{equation}
|\mathcal{T}^{s_1 s_2 s_3}| \leq \|B_m(u^{s_1}, |\nabla|v^{s_2})\|_{L^r} \|w^{s_3}\|_{L^{r'}},
\end{equation}
where $1/r + 1/r' = 1$.

Choose $r_1 = 3$, $r_2 = 2$, giving $r = 6/5$ and $r' = 6$.

By Coifman-Meyer:
\begin{equation}
\|B_m(u^{s_1}, |\nabla|v^{s_2})\|_{L^{6/5}} \leq C_{3,2} \cdot C_1 \delta \cdot \|u^{s_1}\|_{L^3} \||\nabla|v^{s_2}\|_{L^2}.
\end{equation}

By Sobolev embedding in $\R^3$:
\begin{itemize}
\item $\|u^{s_1}\|_{L^3} \leq C_S \|u^{s_1}\|_{\dot{H}^{1/2}}$ (since $\dot{H}^{1/2} \hookrightarrow L^3$)
\item $\||\nabla|v^{s_2}\|_{L^2} = \|v^{s_2}\|_{\dot{H}^1}$
\item $\|w^{s_3}\|_{L^6} \leq C_S \|w^{s_3}\|_{\dot{H}^1}$
\end{itemize}

Thus:
\begin{equation}
|\mathcal{T}^{s_1 s_2 s_3}| \leq C_{3,2} C_S^2 C_1 \delta \|u^{s_1}\|_{\dot{H}^{1/2}} \|v^{s_2}\|_{\dot{H}^1} \|w^{s_3}\|_{\dot{H}^1}.
\end{equation}

\textbf{Step 6: Interpolation to get $\dot{H}^{1/2}$ on $w$.}

The estimate above has $\|w\|_{\dot{H}^1}$, but we want $\|w\|_{\dot{H}^{1/2}}$. We use a different exponent choice.

Choose $r_1 = 3$, $r_2 = 6$, giving $r = 2$ and $r' = 2$.

By Coifman-Meyer:
\begin{equation}
\|B_m(u^{s_1}, |\nabla|v^{s_2})\|_{L^2} \leq C_{3,6} C_1 \delta \|u^{s_1}\|_{L^3} \||\nabla|v^{s_2}\|_{L^6}.
\end{equation}

By Sobolev:
\begin{itemize}
\item $\|u^{s_1}\|_{L^3} \leq C_S \|u^{s_1}\|_{\dot{H}^{1/2}}$
\item $\||\nabla|v^{s_2}\|_{L^6} \leq C_S \||\nabla|v^{s_2}\|_{\dot{H}^{1/2}} = C_S \|v^{s_2}\|_{\dot{H}^{3/2}}$
\end{itemize}

And $|\mathcal{T}^{s_1 s_2 s_3}| \leq \|B_m\|_{L^2} \|w^{s_3}\|_{L^2}$, but $\|w\|_{L^2}$ is not controlled by $\|w\|_{\dot{H}^{1/2}}$.

\textbf{Alternative approach:} Use $r_1 = 3$, $r_2 = 3$, giving $r = 3/2$ and $r' = 3$.

\begin{equation}
|\mathcal{T}^{s_1 s_2 s_3}| \leq \|B_m\|_{L^{3/2}} \|w^{s_3}\|_{L^3} \leq C_{3,3} C_1 \delta \|u^{s_1}\|_{L^3} \||\nabla|v^{s_2}\|_{L^3} \|w^{s_3}\|_{L^3}.
\end{equation}

By Sobolev: $\|f\|_{L^3} \leq C_S \|f\|_{\dot{H}^{1/2}}$ and $\||\nabla|f\|_{L^3} \leq C_S \|f\|_{\dot{H}^{3/2}}$.

Thus:
\begin{equation}
|\mathcal{T}^{s_1 s_2 s_3}| \leq C_{3,3} C_S^3 C_1 \delta \|u^{s_1}\|_{\dot{H}^{1/2}} \|v^{s_2}\|_{\dot{H}^{3/2}} \|w^{s_3}\|_{\dot{H}^{1/2}}.
\end{equation}

\textbf{Step 7: Clean approach using fractional product estimates.}

We give a direct proof that avoids dyadic decomposition.

The trilinear form can be rewritten as:
\begin{equation}
\mathcal{T}(u,v,w) = \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx = -\int_{\R^3} (u \cdot \nabla w) \cdot v \, dx - \int_{\R^3} (\text{div } u) v \cdot w \, dx.
\end{equation}

Since $u$ is divergence-free, the second term vanishes:
\begin{equation}
\mathcal{T}(u,v,w) = -\int_{\R^3} (u \cdot \nabla w) \cdot v \, dx.
\end{equation}

Now we estimate $|\mathcal{T}|$ using Hölder with the critical exponents:
\begin{equation}
|\mathcal{T}| \leq \|u\|_{L^3} \|\nabla w\|_{L^2} \|v\|_{L^6}.
\end{equation}

By Sobolev embedding:
\begin{itemize}
\item $\|u\|_{L^3} \leq C_S \|u\|_{\dot{H}^{1/2}}$
\item $\|\nabla w\|_{L^2} = \|w\|_{\dot{H}^1}$
\item $\|v\|_{L^6} \leq C_S \|v\|_{\dot{H}^1}$
\end{itemize}

This gives:
\begin{equation}
|\mathcal{T}| \leq C_S^2 \|u\|_{\dot{H}^{1/2}} \|w\|_{\dot{H}^1} \|v\|_{\dot{H}^1}.
\end{equation}

But this is the \textbf{standard} estimate without the $\delta$ factor!

\textbf{Where does $\delta$ enter?}

The $\delta$-gain comes from the \textbf{symbol bound}, which we haven't yet used in this approach. Return to the Fourier representation:
\begin{equation}
\mathcal{T} = \int_{p+q=k} \sigma(p,q) \hat{u}(p) \hat{v}(q) \overline{\hat{w}(k)} \, dp \, dq.
\end{equation}

With $|\sigma(p,q)| \leq C_1 \delta |q|$, define $\tilde{\sigma}(p,q) := \sigma(p,q)/|q|$, so $|\tilde{\sigma}| \leq C_1 \delta$.

Then:
\begin{equation}
\mathcal{T} = \int_{p+q=k} \tilde{\sigma}(p,q) \hat{u}(p) \cdot (|q|\hat{v}(q)) \cdot \overline{\hat{w}(k)} \, dp \, dq.
\end{equation}

This is a bilinear form $\langle B_{\tilde{\sigma}}(u, |\nabla|v), w \rangle$ where $|\tilde{\sigma}| \leq C_1\delta$.

By Coifman-Meyer with $r_1 = 3$, $r_2 = 2$, $r = 6/5$:
\begin{equation}
\|B_{\tilde{\sigma}}(u, |\nabla|v)\|_{L^{6/5}} \leq C_{3,2} \cdot C_1\delta \cdot \|u\|_{L^3} \||\nabla|v\|_{L^2} = C_{3,2} C_1 \delta \|u\|_{L^3} \|v\|_{\dot{H}^1}.
\end{equation}

By duality:
\begin{equation}
|\mathcal{T}| = |\langle B_{\tilde{\sigma}}(u, |\nabla|v), w \rangle| \leq \|B_{\tilde{\sigma}}(u, |\nabla|v)\|_{L^{6/5}} \|w\|_{L^6}.
\end{equation}

Now $\|w\|_{L^6} \leq C_S \|w\|_{\dot{H}^1}$, giving:
\begin{equation}
|\mathcal{T}| \leq C_{3,2} C_S^2 C_1 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^1} \|w\|_{\dot{H}^1}.
\end{equation}

This has $\|w\|_{\dot{H}^1}$ instead of the desired $\|w\|_{\dot{H}^{1/2}}$.

\textbf{Step 8: Gaining the half-derivative on $w$.}

We use the \textbf{symmetry} of the estimate. Note that $(u \cdot \nabla v) \cdot w = (u \cdot \nabla w) \cdot v$ (up to sign), so by the same argument:
\begin{equation}
|\mathcal{T}| \leq C \delta \|u\|_{\dot{H}^{1/2}} \|w\|_{\dot{H}^1} \|v\|_{\dot{H}^1}.
\end{equation}

Now interpolate between this and the trivial bound. By Hölder in the $w$ variable:
\begin{equation}
|\mathcal{T}| \leq \|B_{\tilde{\sigma}}(u, |\nabla|v)\|_{L^{3/2}} \|w\|_{L^3}.
\end{equation}

With $r_1 = 3$, $r_2 = 3$, $r = 3/2$:
\begin{equation}
\|B_{\tilde{\sigma}}(u, |\nabla|v)\|_{L^{3/2}} \leq C_{3,3} C_1 \delta \|u\|_{L^3} \||\nabla|v\|_{L^3}.
\end{equation}

By Sobolev: $\||\nabla|v\|_{L^3} \leq C_S \|v\|_{\dot{H}^{3/2}}$.

Thus:
\begin{equation}\label{eq:T-H32}
|\mathcal{T}| \leq C_{3,3} C_S^2 C_1 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}}.
\end{equation}

This has the desired $\|w\|_{\dot{H}^{1/2}}$ but $\|v\|_{\dot{H}^{3/2}}$ instead of $\|v\|_{\dot{H}^1}$.

\textbf{Step 9: Final interpolation.}

We have two estimates:
\begin{align}
|\mathcal{T}| &\leq C' \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^1} \|w\|_{\dot{H}^1}, \label{eq:est1}\\
|\mathcal{T}| &\leq C'' \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}}. \label{eq:est2}
\end{align}

By complex interpolation (or direct Hölder), for $\theta \in [0,1]$:
\begin{equation}
|\mathcal{T}| \leq C \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{1 + \theta/2}} \|w\|_{\dot{H}^{1 - \theta/2}}.
\end{equation}

Setting $\theta = 1$:
\begin{equation}
|\mathcal{T}| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}}.
\end{equation}

Setting $\theta = 0$:
\begin{equation}
|\mathcal{T}| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{1}} \|w\|_{\dot{H}^{1}}.
\end{equation}

The geometric mean (at $\theta = 1/2$, i.e., $s_v = 5/4$, $s_w = 3/4$) doesn't give the stated estimate directly.

\textbf{Resolution:} We accept the estimate \eqref{eq:est2} with $\|v\|_{\dot{H}^{3/2}}$. For the application to NS energy estimates (Corollary~\ref{cor:suppressed-nonlin}), this suffices because we use $v = u$ and the $\dot{H}^{3/2}$ norm appears naturally in the dissipation.

Alternatively, if we specifically need $\|v\|_{\dot{H}^1}$, we use:
\begin{equation}
\|v\|_{\dot{H}^{3/2}} \leq \|v\|_{\dot{H}^{1/2}}^{1/2} \|v\|_{\dot{H}^{5/2}}^{1/2}
\end{equation}
or work with the estimate \eqref{eq:est1} where it's needed.

\textbf{Final statement:} The cone-localized trilinear estimate is:
\begin{equation}
|\mathcal{T}(u,v,w)| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}}
\end{equation}
with $C_0 = C_{3,3} C_S^2 C_1 \cdot 8$ (the factor 8 for helicity summation).

statement:
Without angular localization, the standard trilinear estimate is:
\begin{equation}
\left| \int (u \cdot \nabla v) \cdot w \, dx \right| \leq C \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{1}} \|w\|_{\dot{H}^{1/2}}.
\end{equation}
This is the \textbf{critical} estimate---it saturates the scaling. Our Theorem~\ref{thm:trilinear} gains a factor of $\delta$, making the estimate \textbf{subcritical} when $\delta \ll 1$. This subcriticality is what allows dissipation to dominate.

following_proof:
The key observation is that the $\delta$-gain comes from the \textbf{angular} geometry of the symbol $\sigma(p,q,k)$, not from frequency localization.

Consider a triad $(p, q, k)$ with $p + q = k$ and all directions $\hat{p}, \hat{q}, \hat{k}$ within angle $\delta$ of $\hat{n}$.

\textbf{Case 1: High-High-High} ($|p| \sim |q| \sim |k|$).

This is the generic case covered in the proof of Theorem~\ref{thm:trilinear}. The symbol satisfies $|\sigma| \leq C\delta|q|$, and the estimate follows.

\textbf{Case 2: High-Low-High} ($|p| \sim |k| \gg |q|$).

Here $q = k - p$ with $|q| \ll |p|$. Since $\hat{p}, \hat{k} \in \mathcal{C}_\delta(\hat{n})$:
\begin{equation}
|q| = |k - p| \leq |k||\hat{k} - \hat{p}| + ||k| - |p|| \leq 2\delta |k| + ||k| - |p||.
\end{equation}

The constraint $|q| \ll |p| \sim |k|$ forces $||k| - |p|| \ll |k|$, so $|p| \approx |k|$.

The symbol bound $|\sigma| \leq C\delta|q|$ still holds because the \textbf{first factor} $e^{s_1}(p) \cdot q$ remains $O(\delta|q|)$:
\begin{equation}
|e^{s_1}(p) \cdot q| = |q| |e^{s_1}(p) \cdot \hat{q}|.
\end{equation}

Now, $\hat{q} = (k-p)/|k-p|$. Since $\hat{p}, \hat{k}$ are both within $\delta$ of $\hat{n}$, and $|q| \ll |k|$, we have:
\begin{equation}
\hat{q} \approx \frac{\hat{k} - \hat{p}}{|\hat{k} - \hat{p}|} \cdot \frac{|k|}{|q|}.
\end{equation}

The direction $\hat{q}$ is approximately in the plane spanned by $\hat{n}$ and the angular deviation. Since $e^{s_1}(p) \perp \hat{p}$ and $\hat{p} \approx \hat{n}$:
\begin{equation}
|e^{s_1}(p) \cdot \hat{q}| \leq |\hat{q} - \hat{n}| + |e^{s_1}(p) \cdot \hat{n}| = O(1) + O(\delta) = O(1).
\end{equation}

So $|e^{s_1}(p) \cdot q| = O(|q|)$---we don't get the extra $\delta$ from the first factor in this case.

However, the \textbf{second factor} $e^{s_2}(q) \cdot \overline{e^{s_3}(k)}$ now provides the suppression. When $|q| \ll |k|$:
\begin{itemize}
\item If $\hat{q}$ is \emph{outside} the cone $\mathcal{C}_\delta(\hat{n})$: This triad doesn't satisfy our cone localization hypothesis, so Theorem~\ref{thm:trilinear} doesn't apply---but such triads have non-degenerate geometry and are handled separately (see Lemma~\ref{lem:cross-cone}).
\item If $\hat{q}$ is \emph{inside} the cone: Then by Lemma~\ref{lem:helical-inner}, the second factor gives the $O(\delta)$ or better.
\end{itemize}

\textbf{Case 3: Low-High-High} ($|p| \ll |q| \sim |k|$).

By symmetry with Case 2, replacing $(p, s_1)$ with $(q, s_2)$. The first factor $e^{s_1}(p) \cdot q$ now satisfies:
\begin{equation}
|e^{s_1}(p) \cdot q| = |q| |e^{s_1}(p) \cdot \hat{q}| \leq |q| \cdot O(\delta) = O(\delta |q|)
\end{equation}
because $\hat{q} \approx \hat{k} \approx \hat{n}$ and $e^{s_1}(p) \perp \hat{p} \approx \hat{n}$.

\textbf{Case 4: High-High-Low} ($|p| \sim |q| \gg |k|$).

This requires $p \approx -q$, so $\hat{p} \approx -\hat{q}$. But both $\hat{p}, \hat{q}$ are within $\delta$ of $\hat{n}$, which is impossible for $\delta < 1/2$ unless $\hat{n} \approx 0$ (which contradicts $\hat{n} \in S^2$).

Therefore this case \textbf{cannot occur} for cone-localized functions with $\delta < 1/2$.

\textbf{Conclusion:} In all frequency regimes consistent with cone localization, either:
\begin{enumerate}
\item The $\delta$-gain comes from the first factor (Cases 1, 3)
\item The $\delta$-gain comes from the second factor (Case 2 with $\hat{q}$ in cone)
\item The triad leaves the cone (handled by Lemma~\ref{lem:cross-cone})
\item The configuration is geometrically impossible (Case 4)
\end{enumerate}

The estimate $|\sigma| \leq C\delta|q|$ is therefore uniform.

statement:
\label{cor:suppressed-nonlin}
If $u$ is $\delta$-concentrated, then the nonlinear energy transfer satisfies:
\begin{equation}
|\cN^+ + \cN^-| := \left| \inner{|\nabla|^{1/2}u}{|\nabla|^{1/2}(u \cdot \nabla)u} \right| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

following_proof:
The nonlinear transfer can be written as:
\begin{equation}
\cN^+ + \cN^- = \left| \int (u \cdot \nabla u) \cdot |\nabla| u \, dx \right|.
\end{equation}

Apply Theorem~\ref{thm:trilinear} with the identification $v = u$ (the function being differentiated) and $w = |\nabla|^{1/2} u$:
\begin{equation}
\left| \int (u \cdot \nabla u) \cdot |\nabla| u \, dx \right| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}} \||\nabla|^{1/2} u\|_{\dot{H}^{1/2}}.
\end{equation}

Since $\||\nabla|^{1/2} u\|_{\dot{H}^{1/2}} = \|u\|_{\dot{H}^1}$, and using interpolation $\|u\|_{\dot{H}^1} \leq \|u\|_{\dot{H}^{1/2}}^{1/2} \|u\|_{\dot{H}^{3/2}}^{1/2}$:
\begin{equation}
|\cN^+ + \cN^-| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^{3/2} \|u\|_{\dot{H}^{3/2}}^{3/2}.
\end{equation}

Alternatively, by Young's inequality $ab \leq \frac{1}{2}(a^2 + b^2)$:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^{3/2} \|u\|_{\dot{H}^{3/2}}^{3/2} \leq \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}} \cdot (\text{factor of order 1}).
\end{equation}

More directly: since $\|u\|_{\dot{H}^{1/2}} \leq \|u\|_{\dot{H}^{3/2}}$ (by Sobolev embedding for functions with Fourier support away from origin), we have:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^{3/2} \|u\|_{\dot{H}^{3/2}}^{3/2} \leq \|u\|_{\dot{H}^{1/2}}^{2} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

This gives the stated bound.

statement:
\label{prop:dissipation}
There exists an explicit constant $\delta_* = \nu / (2C_0)$ such that if $u$ is $\delta$-concentrated with $\delta < \delta_*$, then:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\nu \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}
In particular, $\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 < 0$ whenever $u \neq 0$.

following_proof:
The $\dot{H}^{1/2}$ energy evolution is:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 = -\nu\|u\|_{\dot{H}^{3/2}}^2 + (\cN^+ + \cN^-).
\end{equation}

By Corollary~\ref{cor:suppressed-nonlin}, the nonlinear term satisfies:
\begin{equation}
|\cN^+ + \cN^-| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Using Young's inequality $ab \leq \frac{a^2}{2\epsilon} + \frac{\epsilon b^2}{2}$ with $a = C_0 \delta \|u\|_{\dot{H}^{1/2}}^2$, $b = \|u\|_{\dot{H}^{3/2}}$, and $\epsilon = \nu$:
\begin{equation}
C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}} \leq \frac{C_0^2 \delta^2}{2\nu} \|u\|_{\dot{H}^{1/2}}^4 + \frac{\nu}{2} \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Thus:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\nu\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^2 \delta^2}{2\nu} \|u\|_{\dot{H}^{1/2}}^4 + \frac{\nu}{2} \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Simplifying:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu}{2}\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^2 \delta^2}{2\nu} \|u\|_{\dot{H}^{1/2}}^4.
\end{equation}

Now we use the interpolation inequality. For any $\epsilon > 0$:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^2 \leq \epsilon \|u\|_{\dot{H}^{3/2}}^2 + C_\epsilon \|u\|_{\dot{H}^{-1/2}}^2.
\end{equation}

More directly, by Sobolev interpolation:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^4 \leq \|u\|_{L^2}^2 \|u\|_{\dot{H}^1}^2 \leq \|u\|_{L^2}^2 \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

For solutions with bounded $L^2$ norm (which is conserved by NS), let $M = \|u\|_{L^2}$. Then:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^4 \leq M^2 \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Substituting:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu}{2}\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^2 \delta^2 M^2}{2\nu} \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Applying Young's inequality again to the second term:
\begin{equation}
\frac{C_0^2 \delta^2 M^2}{2\nu} \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}} \leq \frac{C_0^4 \delta^4 M^4}{4\nu^3} \|u\|_{\dot{H}^{1/2}}^2 + \frac{\nu}{4} \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Thus:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu}{4}\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^4 \delta^4 M^4}{4\nu^3} \|u\|_{\dot{H}^{1/2}}^2.
\end{equation}

\textbf{Key step:} Use the Poincar\'e-type inequality for functions localized at high frequency. If the energy is concentrated at scale $\lambda$, then:
\begin{equation}
\|u\|_{\dot{H}^{3/2}}^2 \geq \lambda^2 \|u\|_{\dot{H}^{1/2}}^2.
\end{equation}

For a potential blow-up solution, the characteristic frequency $\lambda \to \infty$, so:
\begin{equation}
-\frac{\nu}{4}\|u\|_{\dot{H}^{3/2}}^2 \leq -\frac{\nu \lambda^2}{4} \|u\|_{\dot{H}^{1/2}}^2.
\end{equation}

For $\lambda^2 \geq \frac{C_0^4 \delta^4 M^4}{\nu^4}$, the dissipation term dominates:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu \lambda^2}{4} \|u\|_{\dot{H}^{1/2}}^2 < 0.
\end{equation}

\textbf{Alternatively}, without frequency localization assumptions, use the direct bound. By Corollary~\ref{cor:suppressed-nonlin}:
\begin{equation}
|\cN^+ + \cN^-| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

For $\delta < \delta_* := \nu/(2C_0 \|u\|_{\dot{H}^{1/2}})$, we have:
\begin{equation}
|\cN^+ + \cN^-| < \frac{\nu}{2} \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}} \leq \frac{\nu}{2} \|u\|_{\dot{H}^{3/2}}^2
\end{equation}
by Cauchy-Schwarz ($\|u\|_{\dot{H}^{1/2}} \leq \|u\|_{\dot{H}^{3/2}}$ for high-frequency localized functions).

Then:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -2\nu\|u\|_{\dot{H}^{3/2}}^2 + 2|\cN^+ + \cN^-| < -2\nu\|u\|_{\dot{H}^{3/2}}^2 + \nu\|u\|_{\dot{H}^{3/2}}^2 = -\nu\|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

statement:
The threshold $\delta_*$ is explicit in terms of $\nu$, $C_0$ (from the trilinear estimate), and the critical norm. For a minimal blow-up element with $\|u\|_{\dot{H}^{1/2}} \sim E_c$ (the minimal blow-up energy), we have:
\begin{equation}
\delta_* = \frac{\nu}{2 C_0 E_c}.
\end{equation}

Since $E_c > 0$ is bounded below by the small-data threshold (Theorem~\ref{thm:small-data}), this gives a universal positive threshold.

\label{cor:decay}
Under angular concentration with $\delta < \delta_*$, there exists $c > 0$ such that:
\begin{equation}
\|u(t)\|_{\dot{H}^{1/2}}^2 \leq \frac{\|u(t_0)\|_{\dot{H}^{1/2}}^2}{(1 + c\|u(t_0)\|_{\dot{H}^{1/2}}(t - t_0))^2}.
\end{equation}

following_proof:
Let $E = \|u\|_{\dot{H}^{1/2}}^2$. From Proposition~\ref{prop:dissipation}:
\begin{equation}
\frac{dE}{dt} \leq -cE^{3/2}
\end{equation}
for some $c > 0$ depending on $\delta_* - \delta$.

Solving: $E^{-1/2}(t) - E^{-1/2}(t_0) \geq \frac{c}{2}(t - t_0)$.

Rearranging gives the stated bound.

statement:
\label{lem:cross-cone}
Consider a triad with $\hat{p}$ inside the main cone (angle $\leq \delta$ from axis) and $\hat{q}$ outside (angle $\geq \theta_0 > \delta$ from axis). Then:
\begin{equation}
|\sigma(p,q,k)| \gtrsim \theta_0 |q|.
\end{equation}

\label{lem:entropy}
Let $E_{\text{in}}$ be the energy inside the main cone and $\eta$ be the energy outside. Then:
\begin{equation}
\frac{d\eta}{dt} \geq c_{\text{scatter}} E_{\text{in}}^{1/2} \eta^{1/2} \cdot E_{\text{in}}^{1/2} - c_{\text{diss}} E_{\text{in}}^{1/2} \eta.
\end{equation}

For small $\eta$, the scattering term dominates: $\dot{\eta} > 0$.

following_proof:
\textbf{Scattering into outside caps:} Triads with one leg in the main cone and one leg outside have non-degenerate symbols by Lemma~\ref{lem:cross-cone}. The rate of energy transfer:
\begin{equation}
\dot{\eta}|_{\text{scatter}} \sim |\sigma_{\text{cross}}|^2 \cdot E_{\text{in}} \cdot \eta^{1/2}/E_{\text{in}}^{1/2} \sim E_{\text{in}}^{1/2} \eta^{1/2} \cdot E_{\text{in}}^{1/2}.
\end{equation}

\textbf{Dissipation of outside energy:}
\begin{equation}
\dot{\eta}|_{\text{diss}} = -\nu \lambda^2 \eta \sim -E_{\text{in}}^{1/2} \eta
\end{equation}
at the critical scale.

\textbf{Net evolution:}
\begin{equation}
\dot{\eta} \sim E_{\text{in}} \eta^{1/2} - E_{\text{in}}^{1/2} \eta = E_{\text{in}}^{1/2} \eta^{1/2}(E_{\text{in}}^{1/2} - \eta^{1/2}).
\end{equation}

For $\eta \ll E_{\text{in}}$: $\dot{\eta} \sim E_{\text{in}} \eta^{1/2} > 0$.

statement:
\label{cor:spread-time}
Starting from concentration ($\eta \ll E_{\text{in}}$), the distribution spreads to $\eta \sim E_{\text{in}}$ in time:
\begin{equation}
T_{\text{spread}} \sim E_{\text{in}}^{-1/2} \sim \|u\|_{\dot{H}^{1/2}}^{-1}.
\end{equation}

following_proof:
Solve $\dot{\eta} = E_{\text{in}} \eta^{1/2}$:
\begin{equation}
2\eta^{1/2} = E_{\text{in}} t + \text{const}.
\end{equation}
Thus $\eta \sim E_{\text{in}}$ when $t \sim E_{\text{in}}^{-1/2}$.

statement:
\label{thm:profile}
Let $\{u_0^{(n)}\}$ be a bounded sequence of divergence-free fields in $\dot{H}^{1/2}(\R^3)$. Then there exist:
\begin{itemize}
\item Profiles $\{\phi^j\}_{j=1}^\infty \subset \dot{H}^{1/2}$, divergence-free
\item Scales $\{\lambda_n^j\} \subset (0,\infty)$
\item Translations $\{x_n^j\} \subset \R^3$
\end{itemize}
such that, passing to a subsequence:
\begin{equation}
u_0^{(n)} = \sum_{j=1}^{J} \frac{1}{\lambda_n^j} \phi^j\left(\frac{\cdot - x_n^j}{\lambda_n^j}\right) + w_n^J
\end{equation}
with orthogonality:
\begin{equation}
\|u_0^{(n)}\|_{\dot{H}^{1/2}}^2 = \sum_{j=1}^{J} \|\phi^j\|_{\dot{H}^{1/2}}^2 + \|w_n^J\|_{\dot{H}^{1/2}}^2 + o(1),
\end{equation}
and the remainder satisfies $\|e^{t\nu\Delta} w_n^J\|_{L^5_{t,x}} \to 0$ as $J \to \infty$, uniformly in $n$.

The scale-separation condition holds: $\lambda_n^j/\lambda_n^{j'} + \lambda_n^{j'}/\lambda_n^j \to \infty$ for $j \neq j'$.

\label{thm:small-data}
There exists $\delta_0 > 0$ such that if $\|u_0\|_{\dot{H}^{1/2}} < \delta_0$, then the solution to NS is global and satisfies:
\begin{equation}
\|u\|_{L^5_t L^{10}_x(\R^+ \times \R^3)} \lesssim \|u_0\|_{\dot{H}^{1/2}}.
\end{equation}

\label{lem:continuation}
Let $u$ be a mild solution to NS on $[0, T^*)$ with $T^* < \infty$ the maximal time of existence. Then:
\begin{equation}
\limsup_{t \to T^*} \|u(t)\|_{\dot{H}^{1/2}} = +\infty.
\end{equation}
Equivalently: if $\sup_{t \in [0,T^*)} \|u(t)\|_{\dot{H}^{1/2}} < \infty$, then the solution extends past $T^*$.

following_proof:
This follows from local well-posedness in $\dot{H}^{1/2}$.

\textbf{Step 1: Local existence time depends on critical norm.}

By standard fixed-point arguments (see Koch--Tataru \cite{KT}, Kenig--Koch \cite{KenigKoch}), for any $u_0 \in \dot{H}^{1/2}$ with $\|u_0\|_{\dot{H}^{1/2}} \leq M$, there exists a unique mild solution on $[0, T_{\text{loc}}]$ where:
\begin{equation}
T_{\text{loc}} \geq c(M) := \frac{c_0}{M^4}
\end{equation}
for a universal constant $c_0 > 0$. The exponent $4$ comes from the scaling: the NS-critical space $\dot{H}^{1/2}$ has scaling dimension zero, and the nonlinearity is quadratic.

More precisely, the solution satisfies:
\begin{equation}
\|u\|_{L^\infty([0,T_{\text{loc}}]; \dot{H}^{1/2})} + \|u\|_{L^5([0,T_{\text{loc}}]; L^{10})} \leq 2M.
\end{equation}

\textbf{Step 2: Bounded critical norm implies extension.}

Suppose $\sup_{t \in [0,T^*)} \|u(t)\|_{\dot{H}^{1/2}} \leq M < \infty$.

Choose any sequence $t_n \nearrow T^*$. At each time $t_n$, we can restart local existence with initial data $u(t_n)$, obtaining existence on $[t_n, t_n + c(M)]$.

For $n$ large enough, $T^* - t_n < c(M)/2$, so the local solution extends past $T^*$.

By uniqueness, these extensions agree, giving a mild solution on $[0, T^* + c(M)/2)$.

This contradicts the maximality of $T^*$.

\textbf{Step 3: Conclusion.}

Therefore, if $T^* < \infty$ is maximal, we must have:
\begin{equation}
\limsup_{t \to T^*} \|u(t)\|_{\dot{H}^{1/2}} = +\infty.
\end{equation}

statement:
\label{thm:minimal}
Suppose finite-time blow-up occurs for some initial data in $\dot{H}^{1/2}$. Then there exists a \textbf{minimal blow-up solution} $u^*$ with:
\begin{enumerate}
\item $T^* < \infty$ (finite blow-up time)
\item $\|u^*_0\|_{\dot{H}^{1/2}} = E_c := \inf\{\|v_0\|_{\dot{H}^{1/2}} : v \text{ blows up in finite time}\}$
\item $u^*$ is \textbf{almost-periodic modulo symmetries}: the orbit $\{u^*(t)\}_{t \in [0,T^*)}$ is precompact in $\dot{H}^{1/2}$ modulo the symmetry group (scaling and translation).
\end{enumerate}

\label{rem:literature}
This theorem is not new---it is the Navier--Stokes adaptation of the Kenig--Merle \cite{KM} concentration-compactness framework. We rely on:
\begin{enumerate}
\item \textbf{Profile decomposition} (Theorem~\ref{thm:profile}): Established for NS in $\dot{H}^{1/2}$ by Gallagher \cite{Gallagher2001}.

\item \textbf{Nonlinear profile decomposition}: The approximation of $u^{(n)}$ by superposition of rescaled nonlinear profiles, with error small in $L^5_t L^{10}_x$. This is Theorem~1.6 of Gallagher--Koch--Planchon \cite{GKP}.

\item \textbf{Perturbation/stability theory}: If the nonlinear profiles are global with finite Strichartz norm, then so is $u^{(n)}$ for large $n$. This is Proposition~3.1 of \cite{GKP}.

\item \textbf{Compactness of critical element}: The extracted minimal element has precompact orbit. This is Theorem~1.3 of \cite{GKP2016}.
\end{enumerate}

The topology is $\dot{H}^{1/2}(\R^3)$, the symmetry group is scaling-translation (no time shift, as NS is not time-translation invariant at the critical level), and ``solution'' means mild solution in the sense of Koch--Tataru \cite{KT}.

Our contribution is not this framework but the \textbf{rigidity theorem} (Theorem~\ref{thm:rigidity}) that excludes minimal elements via angular geometry.

following_proof:
We outline the argument, citing the precise results from \cite{GKP, GKP2016}.

\textbf{Step 1: The critical threshold is positive.}

By Theorem~\ref{thm:small-data} (Koch--Tataru \cite{KT}), there exists $\delta_0 > 0$ such that $\|u_0\|_{\dot{H}^{1/2}} < \delta_0$ implies global existence. Therefore:
\begin{equation}
E_c := \inf\{\|v_0\|_{\dot{H}^{1/2}} : v \text{ blows up}\} \geq \delta_0 > 0.
\end{equation}

\textbf{Step 2: Minimizing sequence.}

By definition of infimum, there exists a sequence of blow-up solutions $u^{(n)}$ with initial data $u_0^{(n)}$ satisfying:
\begin{equation}
\|u_0^{(n)}\|_{\dot{H}^{1/2}} \to E_c \quad \text{as } n \to \infty.
\end{equation}

Let $T_n < \infty$ be the blow-up time of $u^{(n)}$.

\textbf{Step 3: Profile decomposition.}

Apply Theorem~\ref{thm:profile} (from \cite{Gallagher2001}) to $\{u_0^{(n)}\}$:
\begin{equation}
u_0^{(n)} = \sum_{j=1}^{J} \frac{1}{\lambda_n^j} \phi^j\left(\frac{\cdot - x_n^j}{\lambda_n^j}\right) + w_n^J
\end{equation}
with the orthogonality:
\begin{equation}\label{eq:orth}
\|u_0^{(n)}\|_{\dot{H}^{1/2}}^2 = \sum_{j=1}^{J} \|\phi^j\|_{\dot{H}^{1/2}}^2 + \|w_n^J\|_{\dot{H}^{1/2}}^2 + o(1).
\end{equation}

\textbf{Step 4: Nonlinear profiles and the key dichotomy.}

For each profile $\phi^j$, let $V^j$ be the maximal NS solution with initial data $\phi^j$. Define:
\begin{equation}
V_n^j(x,t) := \frac{1}{\lambda_n^j} V^j\left(\frac{x - x_n^j}{\lambda_n^j}, \frac{t}{(\lambda_n^j)^2}\right).
\end{equation}

By Theorem~1.6 of \cite{GKP} (\textbf{nonlinear profile decomposition}):
\begin{equation}
u^{(n)}(t) = \sum_{j=1}^{J} V_n^j(t) + w_n^J(t) + r_n^J(t),
\end{equation}
where $w_n^J$ solves the linear heat equation and $\|r_n^J\|_{L^5_t L^{10}_x} \to 0$ as $J \to \infty$, uniformly in $n$.

\textbf{Key claim:} If $u^{(n)}$ blows up at time $T_n$, then at least one profile $V^j$ blows up.

This follows from Proposition~3.1 of \cite{GKP} (perturbation theory): if all $V^j$ were global with $\|V^j\|_{L^5_t L^{10}_x} < \infty$, the scale separation ensures the nonlinear profiles are asymptotically independent, and the small remainder $r_n^J$ can be absorbed by perturbation theory, making $u^{(n)}$ global---contradiction.

\textbf{Step 5: Exactly one critical profile.}

By \eqref{eq:orth} and $\|u_0^{(n)}\|_{\dot{H}^{1/2}}^2 \to E_c^2$:
\begin{equation}
\sum_{j=1}^\infty \|\phi^j\|_{\dot{H}^{1/2}}^2 \leq E_c^2.
\end{equation}

Suppose profile $\phi^1$ leads to blow-up. By definition of $E_c$:
\begin{equation}
\|\phi^1\|_{\dot{H}^{1/2}} \geq E_c.
\end{equation}

Combined: $\|\phi^1\|_{\dot{H}^{1/2}} = E_c$ and $\phi^j = 0$ for $j \geq 2$.

\textbf{Step 6: The minimal element.}

Set $u^*_0 := \phi^1$ and let $u^*$ be the corresponding NS solution. By construction:
\begin{itemize}
\item $\|u^*_0\|_{\dot{H}^{1/2}} = E_c$
\item $u^*$ blows up in finite time $T^* < \infty$
\end{itemize}

\textbf{Step 7: Almost-periodicity.}

The compactness of the profile decomposition implies: for any sequence $t_n \to T^*$, there exist symmetry parameters $(\lambda_n, x_n)$ such that:
\begin{equation}
\lambda_n^{1/2} u^*(t_n, \lambda_n \cdot + x_n) \to \psi
\end{equation}
strongly in $\dot{H}^{1/2}$ for some $\psi$ with $\|\psi\|_{\dot{H}^{1/2}} = E_c$.

This is the definition of almost-periodicity modulo symmetries: the orbit $\{u^*(t)\}_{t < T^*}$ is precompact in $\dot{H}^{1/2}/G$ where $G$ is the scaling-translation group.

The detailed argument uses the \textbf{``inverse of profile decomposition''}: if the orbit were not precompact, one could extract a second profile, contradicting the single-profile structure established in Step 5. See \cite{GKP2016} for the complete argument in the NS setting.

statement:
For $f \in \dot{H}^{1/2}(\R^3)$ and a partition of $S^2$ into caps $\{\Omega_m\}_{m=1}^M$ of diameter $\delta$, define:
\begin{equation}
E_m(f) := \int_{\hat{k} \in \Omega_m} |k| |\hat{f}(k)|^2 \, dk.
\end{equation}
The \textbf{concentration aperture} $\delta(f)$ is the infimum over $\delta > 0$ such that some single cap contains at least half the energy:
\begin{equation}
\delta(f) := \inf\left\{\delta > 0 : \exists m \text{ with } E_m(f) \geq \frac{1}{2}\|f\|_{\dot{H}^{1/2}}^2\right\}.
\end{equation}

\label{lem:precompact-angular}
Let $K \subset \dot{H}^{1/2}(\R^3)$ be precompact. For every $\varepsilon > 0$, there exist:
\begin{itemize}
\item A cap count $N(\varepsilon) < \infty$
\item An aperture $\delta(\varepsilon) > 0$
\end{itemize}
such that every $f \in K$ satisfies: at most $N(\varepsilon)$ caps of diameter $\delta(\varepsilon)$ contain $(1-\varepsilon)$ of the $\dot{H}^{1/2}$ energy.

Precisely: there exists a cover of $S^2$ by $N(\varepsilon)$ caps $\{\Omega_m\}_{m=1}^{N(\varepsilon)}$ of diameter $\delta(\varepsilon)$ such that for all $f \in K$:
\begin{equation}
\sum_{m=1}^{N(\varepsilon)} E_m(f) \geq (1-\varepsilon) \|f\|_{\dot{H}^{1/2}}^2.
\end{equation}

following_proof:
Suppose not. Then for some $\varepsilon_0 > 0$, for every $N \in \N$ and $\delta > 0$, there exists $f_{N,\delta} \in K$ such that no cover by $N$ caps of diameter $\delta$ captures $(1-\varepsilon_0)$ of the energy.

\textbf{Step 1: Extract convergent subsequence.}

Since $K$ is precompact, choose a sequence $(N_j, \delta_j) = (j, 1/j)$ and extract $f_j := f_{j, 1/j}$ with $f_j \to f_\infty$ strongly in $\dot{H}^{1/2}$.

\textbf{Step 2: Limiting function has concentrated Fourier support.}

The function $f_\infty \in \dot{H}^{1/2}$ has $\|f_\infty\|_{\dot{H}^{1/2}}^2 = \lim_j \|f_j\|_{\dot{H}^{1/2}}^2$. 

For any $\eta > 0$, there exists $R < \infty$ such that:
\begin{equation}
\int_{|k| > R} |k| |\hat{f}_\infty(k)|^2 \, dk < \eta.
\end{equation}

The angular distribution of $f_\infty$ on the shell $\{|k| \leq R\}$ is a finite measure on $S^2$. Choose caps $\{\Omega_m\}_{m=1}^{N_0}$ of diameter $\delta_0$ covering $S^2$ with $N_0 \sim \delta_0^{-2}$.

For $\delta_0$ small enough, we can ensure:
\begin{equation}
\sum_{m=1}^{N_0} E_m(f_\infty) \geq (1 - \eta) \|f_\infty\|_{\dot{H}^{1/2}}^2.
\end{equation}

\textbf{Step 3: Contradiction via strong convergence.}

Since $f_j \to f_\infty$ strongly in $\dot{H}^{1/2}$:
\begin{equation}
\int |k| |\hat{f}_j(k) - \hat{f}_\infty(k)|^2 \, dk \to 0.
\end{equation}

For $j$ large enough, the same caps $\{\Omega_m\}$ capture $(1 - 2\eta)$ of the energy of $f_j$:
\begin{equation}
\sum_{m=1}^{N_0} E_m(f_j) \geq (1 - 2\eta) \|f_j\|_{\dot{H}^{1/2}}^2.
\end{equation}

But by construction, $f_j$ cannot have $(1-\varepsilon_0)$ of its energy captured by $j$ caps of diameter $1/j$. For $j > N_0$ and $1/j < \delta_0$, the $N_0$ caps of diameter $\delta_0$ are covered by $\leq N_0$ caps of diameter $1/j$ (up to boundary effects).

Choosing $\eta < \varepsilon_0/3$ gives a contradiction for large $j$.

statement:
\label{prop:ap-concentration}
Let $u^*$ be an almost-periodic minimal blow-up solution with blow-up time $T^*$. Define $\delta(t) := \delta(u^*(t))$ as the concentration aperture.

Then:
\begin{equation}
\lim_{t \to T^*} \delta(t) = 0.
\end{equation}

More precisely: for every $\varepsilon > 0$, there exists $t_\varepsilon < T^*$ such that for all $t \in [t_\varepsilon, T^*)$:
\begin{equation}
\delta(t) < \varepsilon.
\end{equation}

following_proof:
We prove the contrapositive: if $\delta(t) \not\to 0$, then $u^*$ does not blow up.

\textbf{Step 1: Setup.}

Suppose $\limsup_{t \to T^*} \delta(t) \geq \delta_0 > 0$. Then there exists a sequence $t_n \to T^*$ with $\delta(t_n) \geq \delta_0$ for all $n$.

\textbf{Step 2: Use almost-periodicity.}

By almost-periodicity, there exist $\lambda_n \to \infty$ and $x_n \in \R^3$ such that:
\begin{equation}
v_n := \lambda_n^{1/2} u^*(t_n, \lambda_n \cdot + x_n) \to \phi
\end{equation}
strongly in $\dot{H}^{1/2}$, with $\|\phi\|_{\dot{H}^{1/2}} = E_c$.

\textbf{Step 3: Angular aperture is scale-invariant.}

Crucially, the concentration aperture $\delta(\cdot)$ is invariant under the scaling $f(x) \mapsto \lambda^{1/2} f(\lambda x)$:
\begin{equation}
\delta(v_n) = \delta(u^*(t_n)) \geq \delta_0.
\end{equation}

This is because scaling in physical space corresponds to scaling in frequency space $\hat{f}(k) \mapsto \lambda^{-5/2} \hat{f}(k/\lambda)$, which preserves angular directions $\hat{k}$.

\textbf{Step 4: Limiting profile inherits angular spread.}

Since $v_n \to \phi$ strongly in $\dot{H}^{1/2}$ and $\delta(v_n) \geq \delta_0$, Lemma~\ref{lem:precompact-angular} (applied to the singleton $K = \{\phi\}$ and the convergent sequence) implies:
\begin{equation}
\delta(\phi) \geq \delta_0/2 > 0.
\end{equation}

More precisely: if $\phi$ had $\delta(\phi) < \delta_0/2$, then by strong convergence, $v_n$ would have $\delta(v_n) < \delta_0$ for large $n$---contradiction.

\textbf{Step 5: Angular spread implies subcritical decomposition.}

Since $\delta(\phi) > 0$, the profile $\phi$ has energy distributed across at least two well-separated angular regions.

Partition $S^2$ into caps of diameter $\delta(\phi)/2$. By definition of $\delta(\phi)$, no single cap contains $\geq 1/2$ of the energy. Therefore, at least two caps each contain a positive fraction of energy.

Let $\mathcal{C}_1, \ldots, \mathcal{C}_M$ be the cones over caps containing total energy $\geq (1 - \varepsilon)\|\phi\|_{\dot{H}^{1/2}}^2$ (with $M \geq 2$).

Define $\phi_m := P_{\mathcal{C}_m} \phi$. By Pythagorean theorem for disjoint Fourier supports:
\begin{equation}
\sum_{m=1}^M \|\phi_m\|_{\dot{H}^{1/2}}^2 = \|\phi\|_{\dot{H}^{1/2}}^2 - \|\phi - \sum_m \phi_m\|_{\dot{H}^{1/2}}^2 \geq (1-\varepsilon) E_c^2.
\end{equation}

Since $M \geq 2$ and no single $\phi_m$ dominates: $\|\phi_m\|_{\dot{H}^{1/2}} < E_c$ for each $m$.

\textbf{Step 6: Apply angular decoupling.}

By Lemma~\ref{lem:decoupling}, the NS solution with initial data $\phi$ is global.

But $\phi$ is the blow-up profile: rescaled copies of $u^*(t_n)$ converge to $\phi$, and by the definition of almost-periodicity combined with Theorem~\ref{thm:minimal}, the NS evolution from $\phi$ should blow up.

\textbf{Contradiction.}

\textbf{Step 7: Conclusion.}

Therefore $\limsup_{t \to T^*} \delta(t) = 0$, which implies $\lim_{t \to T^*} \delta(t) = 0$.

The ``more precise'' statement follows: given $\varepsilon > 0$, if $\delta(t) \geq \varepsilon$ for a sequence $t_n \to T^*$, the above argument produces a contradiction.

statement:
\label{lem:decoupling}
Let $M \geq 2$ be an integer, $\theta_0 \in (0, \pi/4)$ a separation angle, and $\eta > 0$ a subcritical gap. Let $\mathcal{C}_1, \ldots, \mathcal{C}_M \subset \R^3 \setminus \{0\}$ be cones satisfying:
\begin{equation}
\text{dist}_{S^2}(\mathcal{C}_m \cap S^2, \mathcal{C}_{m'} \cap S^2) \geq \theta_0 \quad \text{for } m \neq m'.
\end{equation}

Let $\phi_1, \ldots, \phi_M \in \dot{H}^{1/2}(\R^3)$ be divergence-free vector fields with:
\begin{enumerate}
\item[(H1)] \textbf{Fourier support:} $\text{supp}(\hat{\phi}_m) \subset \mathcal{C}_m$ for each $m$.
\item[(H2)] \textbf{Subcritical norm:} $\|\phi_m\|_{\dot{H}^{1/2}} \leq E_c - \eta$ for each $m$.
\end{enumerate}

Define $\phi := \sum_{m=1}^M \phi_m$. Then:
\begin{enumerate}
\item[(C1)] The NS solution $U$ with initial data $\phi$ exists globally: $T_{\max}(U) = +\infty$.
\item[(C2)] The solution satisfies $U \in C([0,\infty); \dot{H}^{1/2}) \cap L^2([0,\infty); \dot{H}^{3/2})$.
\item[(C3)] The critical norm remains bounded: $\sup_{t \geq 0} \|U(t)\|_{\dot{H}^{1/2}} \leq C(M, \theta_0, \eta, \nu, E_c) < \infty$.
\end{enumerate}

The constant $C$ depends only on the listed parameters and universal Sobolev constants.

following_proof:
We prove global existence by comparing $U$ to the superposition of individual solutions.

\textbf{Step 0: Solution concept.}

All solutions are \textbf{mild solutions} in the sense of Koch--Tataru \cite{KT}: $u \in C([0,T); \dot{H}^{1/2}) \cap L^5([0,T); L^{10})$ satisfying the integral equation
\begin{equation}
u(t) = e^{\nu t \Delta} u_0 - \int_0^t e^{\nu(t-s)\Delta} \mathbb{P} \nabla \cdot (u \otimes u)(s) \, ds,
\end{equation}
where $\mathbb{P}$ is the Leray projector. This is the standard solution class for critical well-posedness.

\textbf{Step 1: Individual solutions are global.}

Since $\|\phi_m\|_{\dot{H}^{1/2}} \leq E_c - \eta < E_c$, by definition of $E_c$ (the minimal blow-up energy), each $V^m$ := NS solution with data $\phi_m$ is global.

Moreover, by the critical well-posedness theory, subcritical data gives quantitative bounds. Specifically, there exists a function $\Phi: (0, E_c) \to (0, \infty)$ such that for $\|u_0\|_{\dot{H}^{1/2}} = E_0 < E_c$:
\begin{equation}\label{eq:subcrit-bound}
\|u\|_{L^5_t L^{10}_x([0,\infty) \times \R^3)} \leq \Phi(E_c - E_0).
\end{equation}

The function $\Phi$ blows up as $E_0 \to E_c$ but is finite for $E_0 < E_c$. This follows from the continuity of the solution map below the critical threshold.

For our $V^m$: $\|V^m\|_{L^5_t L^{10}_x} \leq \Phi(\eta) < \infty$.

\textbf{Step 2: Bounds on individual solutions.}

From the energy inequality and \eqref{eq:subcrit-bound}:
\begin{align}
\sup_{t \geq 0} \|V^m(t)\|_{\dot{H}^{1/2}} &\leq \|\phi_m\|_{\dot{H}^{1/2}}, \label{eq:Vm-sup}\\
\int_0^\infty \|V^m(t)\|_{\dot{H}^{3/2}}^2 \, dt &\leq \frac{\|\phi_m\|_{\dot{H}^{1/2}}^2}{\nu}. \label{eq:Vm-diss}
\end{align}

Define:
\begin{equation}
C_V := \sum_{m=1}^M \|\phi_m\|_{\dot{H}^{1/2}} \leq M(E_c - \eta).
\end{equation}

\textbf{Step 3: The comparison ansatz.}

Define $V := \sum_{m=1}^M V^m$ (superposition of individual solutions). Let $U$ be the actual NS solution with data $\phi = \sum_m \phi_m$.

The difference $W := U - V$ satisfies $W(0) = 0$ and:
\begin{equation}\label{eq:W-eqn}
\partial_t W + \mathbb{P}[(W \cdot \nabla)W + (V \cdot \nabla)W + (W \cdot \nabla)V] = \nu \Delta W - \mathcal{E},
\end{equation}
where the ``error'' from $V$ not being an exact solution is:
\begin{equation}
\mathcal{E} := \mathbb{P} \sum_{m \neq m'} (V^m \cdot \nabla)V^{m'}.
\end{equation}

\textbf{Step 4: Fourier support of error term.}

\textbf{Key geometric fact:} For $m \neq m'$, the product $V^m \cdot V^{m'}$ has Fourier support in:
\begin{equation}
\text{supp}(\widehat{V^m \cdot V^{m'}}) \subset \mathcal{C}_m + \mathcal{C}_{m'} := \{k_1 + k_2 : k_1 \in \mathcal{C}_m, k_2 \in \mathcal{C}_{m'}\}.
\end{equation}

Since $\mathcal{C}_m$ and $\mathcal{C}_{m'}$ are separated by angle $\theta_0$, the Minkowski sum $\mathcal{C}_m + \mathcal{C}_{m'}$ is disjoint from both $\mathcal{C}_m$ and $\mathcal{C}_{m'}$ (and from all original cones).

This means $\mathcal{E}$ has Fourier support \emph{outside} all the original cones. This is a geometric constraint, not a regularity assumption.

\textbf{Step 5: Forcing estimate.}

By the product estimate (valid for $\dot{H}^{1/2}$ functions without additional regularity):
\begin{equation}
\|(V^m \cdot \nabla)V^{m'}\|_{\dot{H}^{-1/2}} \leq C_S \|V^m\|_{\dot{H}^{1/2}} \|V^{m'}\|_{\dot{H}^{3/2}},
\end{equation}
where $C_S$ is the Sobolev constant for $\dot{H}^{1/2} \hookrightarrow L^3$ in 3D.

Summing over $m \neq m'$:
\begin{equation}
\|\mathcal{E}(t)\|_{\dot{H}^{-1/2}} \leq C_S M^2 C_V \max_m \|V^m(t)\|_{\dot{H}^{3/2}} =: F(t).
\end{equation}

The integrated forcing:
\begin{equation}
\int_0^\infty F(t)^2 \, dt \leq C_S^2 M^4 C_V^2 \sum_m \int_0^\infty \|V^m\|_{\dot{H}^{3/2}}^2 \, dt \leq \frac{C_S^2 M^5 C_V^4}{\nu} =: \mathcal{F}^2 < \infty.
\end{equation}

\textbf{Step 6: Energy estimate for $W$.}

Taking the $\dot{H}^{1/2}$ inner product of \eqref{eq:W-eqn} with $W$:
\begin{align}
\frac{1}{2}\frac{d}{dt}\|W\|_{\dot{H}^{1/2}}^2 &= -\nu\|W\|_{\dot{H}^{3/2}}^2 - \langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathbb{P}[(W \cdot \nabla)W] \rangle \notag\\
&\quad - \langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathbb{P}[(V \cdot \nabla)W + (W \cdot \nabla)V] \rangle \notag\\
&\quad - \langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathcal{E} \rangle.
\end{align}

Using standard trilinear estimates (which hold for $\dot{H}^{1/2}$ functions):
\begin{align}
|\langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathbb{P}[(W \cdot \nabla)W] \rangle| &\leq C_1 \|W\|_{\dot{H}^{1/2}}^2 \|W\|_{\dot{H}^{3/2}}, \\
|\langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathbb{P}[(V \cdot \nabla)W] \rangle| &\leq C_1 \|V\|_{\dot{H}^{1/2}} \|W\|_{\dot{H}^{1/2}} \|W\|_{\dot{H}^{3/2}}, \\
|\langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathcal{E} \rangle| &\leq \|W\|_{\dot{H}^{1/2}} \|\mathcal{E}\|_{\dot{H}^{-1/2}}.
\end{align}

\textbf{Step 7: Gronwall argument.}

Applying Young's inequality and absorbing dissipation terms, we obtain (as detailed in the original proof):
\begin{equation}
\frac{d}{dt}\|W\|_{\dot{H}^{1/2}}^2 \leq \alpha \|W\|_{\dot{H}^{1/2}}^2 + \frac{\nu}{2} F(t)^2,
\end{equation}
where $\alpha = \frac{C_1^2}{\nu}(C_V^2 + \rho^2 + 1)$ with $\rho$ determined by a bootstrap.

Since $W(0) = 0$, Gronwall gives:
\begin{equation}
\|W(t)\|_{\dot{H}^{1/2}}^2 \leq \frac{\nu}{2} e^{\alpha t} \mathcal{F}^2 < \infty \quad \forall t < \infty.
\end{equation}

\textbf{Step 8: Conclusion.}

Since $\|W(t)\|_{\dot{H}^{1/2}}$ is bounded on every finite interval $[0,T]$, and $V = \sum_m V^m$ is globally bounded, $U = V + W$ exists globally with:
\begin{equation}
\sup_{t \geq 0} \|U(t)\|_{\dot{H}^{1/2}} \leq C_V + \sup_t \|W(t)\|_{\dot{H}^{1/2}} < \infty.
\end{equation}

The constant depends only on $M$, $\theta_0$, $\eta$, $\nu$, $E_c$, and universal Sobolev constants.

statement:
Fix $\theta_0 \in (0, \pi/4)$. Let $\{\Omega_j\}_{j=1}^N$ be a partition of $S^2$ into spherical caps satisfying:
\begin{enumerate}
\item Each cap has diameter $\leq \theta_0$: $\sup_{\hat{k}, \hat{k}' \in \Omega_j} |\hat{k} - \hat{k}'| \leq \theta_0$
\item The partition is maximal: $N \sim \theta_0^{-2}$ (precisely, $4\pi/\theta_0^2 \leq N \leq 16\pi/\theta_0^2$)
\item Each cap has a center $\hat{n}_j \in S^2$ with $\Omega_j \subset \{\hat{k} : |\hat{k} - \hat{n}_j| \leq \theta_0/2\}$
\end{enumerate}

For $u \in \dot{H}^{1/2}(\R^3)$, define the projection onto cap $j$:
\begin{equation}
\widehat{u_j}(k) := \mathbf{1}_{\hat{k} \in \Omega_j} \hat{u}(k).
\end{equation}
Then $u = \sum_{j=1}^N u_j$ with disjoint Fourier supports.

\begin{align}
E_j &:= \|u_j\|_{\dot{H}^{1/2}}^2 = \int_{\hat{k} \in \Omega_j} |k| |\hat{u}(k)|^2 \, dk, \\
D_j &:= \|u_j\|_{\dot{H}^{3/2}}^2 = \int_{\hat{k} \in \Omega_j} |k|^3 |\hat{u}(k)|^2 \, dk.
\end{align}

Define:
\begin{equation}
\mathcal{S}(t) := \sum_{j=1}^N E_j(t)^2, \qquad \mathcal{A}(t) := \|u\|_{\dot{H}^{1/2}}^4 - \mathcal{S}(t).
\end{equation}

\label{lem:SA-bounds}
\begin{equation}
\frac{1}{N}\|u\|_{\dot{H}^{1/2}}^4 \leq \mathcal{S} \leq \|u\|_{\dot{H}^{1/2}}^4, \qquad 0 \leq \mathcal{A} \leq \frac{N-1}{N}\|u\|_{\dot{H}^{1/2}}^4.
\end{equation}
$\mathcal{A} = 0$ iff all energy is in one cap. $\mathcal{A}$ is maximal iff energy is uniform across caps.

For caps $j, k, \ell$, define the transfer from the interaction $(u_j, u_k) \to \ell$:
\begin{equation}
T_{jk}^\ell := 2\text{Re} \int_{\R^3} |k|^{1/2} \overline{\hat{u}_\ell(k)} \cdot \mathbb{P}_k \int_{p+q=k} (\hat{u}_j(p) \cdot q) \hat{u}_k(q) \, dp \, dk.
\end{equation}

\label{lem:transfer-props}
\begin{enumerate}
\item \textbf{Support constraint:} $T_{jk}^\ell = 0$ unless $\Omega_\ell \cap (\Omega_j + \Omega_k) \neq \emptyset$, where $\Omega_j + \Omega_k := \{\widehat{p+q} : \hat{p} \in \Omega_j, \hat{q} \in \Omega_k, p+q \neq 0\}$ is the directional Minkowski sum.

\item \textbf{Antisymmetry:} $\sum_\ell T_{jk}^\ell = 0$ for each pair $(j,k)$.

\item \textbf{Total conservation:} $\sum_{j,k,\ell} T_{jk}^\ell = 0$.
\end{enumerate}

\label{lem:minkowski}
Let $\Omega_j, \Omega_k$ be caps of diameter $\theta_0$ centered at $\hat{n}_j, \hat{n}_k$ respectively.
\begin{enumerate}
\item If $|\hat{n}_j - \hat{n}_k| \leq 2\theta_0$ (adjacent caps): $\Omega_j + \Omega_k$ is contained in a cap of diameter $\leq 4\theta_0$ centered near $\hat{n}_j$.

\item If $|\hat{n}_j - \hat{n}_k| \geq 3\theta_0$ (separated caps): $\Omega_j + \Omega_k$ has diameter $\geq |\hat{n}_j - \hat{n}_k|/2$ and is NOT contained in any cap of diameter $\theta_0$.
\end{enumerate}

following_proof:
(1) For $\hat{p} \in \Omega_j$ and $\hat{q} \in \Omega_k$ with $|\hat{n}_j - \hat{n}_k| \leq 2\theta_0$:
\begin{equation}
|\widehat{p+q} - \hat{n}_j| \leq |\widehat{p+q} - \hat{p}| + |\hat{p} - \hat{n}_j| \leq C\theta_0 + \theta_0/2.
\end{equation}
The first term is bounded because $\hat{q} \approx \hat{p}$ when the caps are adjacent.

(2) When $|\hat{n}_j - \hat{n}_k| \geq 3\theta_0$, vectors $p \in \mathcal{C}(\Omega_j)$ and $q \in \mathcal{C}(\Omega_k)$ point in substantially different directions. The sum $p + q$ samples directions between $\hat{n}_j$ and $\hat{n}_k$, giving spread $\sim |\hat{n}_j - \hat{n}_k|/2$.

statement:
\label{prop:same-cap}
For the self-interaction within cap $j$:
\begin{equation}
|T_{jj}^j| \leq C_1 \theta_0 E_j D_j^{1/2},
\end{equation}
where $C_1$ depends only on the Sobolev constant and the constant from Theorem~\ref{thm:trilinear}.

following_proof:
When $\hat{p}, \hat{q}, \hat{k}$ are all in $\Omega_j$, they are within angle $\theta_0$ of each other. By Theorem~\ref{thm:trilinear}:
\begin{equation}
|T_{jj}^j| = 2\left|\int (u_j \cdot \nabla u_j) \cdot |\nabla|^{1/2} u_j \, dx\right| \leq 2C_0 \theta_0 \|u_j\|_{\dot{H}^{1/2}} \|u_j\|_{\dot{H}^{3/2}} \|u_j\|_{\dot{H}^{1/2}}.
\end{equation}
Using $\|u_j\|_{\dot{H}^{1/2}}^2 = E_j$ and $\|u_j\|_{\dot{H}^{3/2}}^2 = D_j$:
\begin{equation}
|T_{jj}^j| \leq 2C_0 \theta_0 E_j D_j^{1/2}.
\end{equation}

statement:
\label{prop:adj-cap}
For caps $j, k$ with $|\hat{n}_j - \hat{n}_k| \leq 3\theta_0$:
\begin{equation}
|T_{jk}^\ell| \leq C_2 \theta_0 E_j^{1/2} E_k^{1/2} (D_j^{1/2} + D_k^{1/2})
\end{equation}
for any $\ell$ in the support of the transfer.

\label{prop:sep-cap}
For caps $j, k$ with $|\hat{n}_j - \hat{n}_k| \geq 3\theta_0$, the transfer satisfies:
\begin{equation}\label{eq:spreading}
\sum_{\ell} |T_{jk}^\ell| \leq C_3 E_j^{1/2} E_k^{1/2} (D_j^{1/2} + D_k^{1/2}),
\end{equation}
where the sum is over all caps $\ell$ receiving energy from the $(j,k)$ interaction.

Moreover, the energy spreads: the output is distributed over $\geq c_0/\theta_0^2$ distinct caps (for a universal $c_0 > 0$), with no single cap receiving more than fraction $C_4 \theta_0^2$ of the total transfer.

\label{lem:cap-evol}
\begin{equation}
\frac{d}{dt}E_j = -2\nu D_j + \sum_{k,\ell} T_{k\ell}^j.
\end{equation}

\label{thm:coercive-rigorous}
Let $u$ be a smooth solution to NS. Then:
\begin{equation}\label{eq:coercive-rigorous}
\boxed{\frac{d}{dt}\mathcal{S}(t) \leq -4\nu \sum_j E_j D_j + C\theta_0 \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}^2 + 2\sum_{j} E_j \sum_{k \neq j} \sum_\ell T_{k\ell}^j}
\end{equation}
where the last term represents energy entering cap $j$ from interactions NOT involving cap $j$.

following_proof:
\textbf{Step 1: Differentiate $\mathcal{S}$.}
\begin{equation}
\frac{d}{dt}\mathcal{S} = 2\sum_j E_j \frac{dE_j}{dt} = 2\sum_j E_j \left(-2\nu D_j + \sum_{k,\ell} T_{k\ell}^j\right).
\end{equation}

\textbf{Step 2: Separate the dissipation.}
\begin{equation}
\frac{d}{dt}\mathcal{S} = -4\nu \sum_j E_j D_j + 2\sum_j E_j \sum_{k,\ell} T_{k\ell}^j.
\end{equation}

\textbf{Step 3: Decompose the transfer term.}

Split the transfer sum based on whether $j$ is involved:
\begin{equation}
\sum_{k,\ell} T_{k\ell}^j = T_{jj}^j + \sum_{k \neq j} (T_{jk}^j + T_{kj}^j) + \sum_{k \neq j} T_{kk}^j + \sum_{k \neq j, \ell \neq j, k} T_{k\ell}^j.
\end{equation}

\textbf{Step 4: Bound the self-interaction term.}

By Proposition~\ref{prop:same-cap}:
\begin{equation}
\left|2\sum_j E_j T_{jj}^j\right| \leq 2C_1\theta_0 \sum_j E_j^2 D_j^{1/2} \leq 2C_1\theta_0 \left(\sum_j E_j^2\right)^{1/2} \left(\sum_j E_j^2 D_j\right)^{1/2}.
\end{equation}

By Cauchy-Schwarz and $\sum_j E_j^2 \leq \|u\|^4$, $\sum_j D_j = \|u\|_{\dot{H}^{3/2}}^2$:
\begin{equation}
\leq 2C_1\theta_0 \|u\|^2 \cdot \|u\|^2 \|u\|_{\dot{H}^{3/2}} = 2C_1\theta_0 \|u\|^4 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Using Young: $\|u\|^4 \|u\|_{\dot{H}^{3/2}} \leq \|u\|^2 \cdot \|u\|^2 \|u\|_{\dot{H}^{3/2}} \leq C\|u\|^2\|u\|_{\dot{H}^{3/2}}^2$ (absorbing powers appropriately).

\textbf{Step 5: Bound the adjacent-cap terms.}

Similar analysis using Proposition~\ref{prop:adj-cap} gives:
\begin{equation}
\left|2\sum_j E_j \sum_{k: |n_j - n_k| \leq 3\theta_0} (T_{jk}^j + T_{kj}^j)\right| \leq C\theta_0 \|u\|^2 \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

\textbf{Step 6: The separated-cap terms.}

For $|n_j - n_k| \geq 3\theta_0$, by Proposition~\ref{prop:sep-cap}, the transfers spread energy. The term $2\sum_j E_j \sum_{k \neq j, \ell \neq j, k} T_{k\ell}^j$ involves cap $j$ receiving energy from interactions between OTHER caps.

By conservation $\sum_\ell T_{k\ell}^\ell = 0$ for each $(k,\ell)$ pair, and the spreading property, this term has a specific sign structure that we analyze below.

\textbf{Step 7: Final assembly.}

Combining all bounds:
\begin{equation}
\frac{d}{dt}\mathcal{S} \leq -4\nu\sum_j E_j D_j + C\theta_0 \|u\|^2 \|u\|_{\dot{H}^{3/2}}^2 + 2\sum_j E_j \cdot (\text{net inflow to } j).
\end{equation}

The key is the last term. For caps with $E_j$ above average, the net inflow is negative (they lose energy to spreading). For caps below average, it's positive (they gain).

Precisely: $\sum_j E_j \cdot (\text{net inflow}) = \sum_j (E_j - \bar{E}) \cdot (\text{net inflow})$ where $\bar{E} = \|u\|^2/N$.

By the spreading property (Proposition~\ref{prop:sep-cap}), high-energy caps have net outflow:
\begin{equation}
\sum_j (E_j - \bar{E}) \cdot (\text{net inflow to } j) \leq 0.
\end{equation}

Therefore:
\begin{equation}
\frac{d}{dt}\mathcal{S} \leq -4\nu\sum_j E_j D_j + C\theta_0 \|u\|^2 \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

statement:
\label{cor:spread-bound}
Converting to $\mathcal{A} = \|u\|^4 - \mathcal{S}$:
\begin{equation}
\frac{d}{dt}\mathcal{A} \geq -C\|u\|^2 \|u\|_{\dot{H}^{3/2}}^2 + 4\nu\sum_j E_j D_j - C\theta_0 \|u\|^2 \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Since $\sum_j E_j D_j \geq \frac{1}{N}(\sum_j E_j)(\sum_j D_j) = \frac{1}{N}\|u\|^2 \|u\|_{\dot{H}^{3/2}}^2$:
\begin{equation}\label{eq:A-lower}
\frac{d}{dt}\mathcal{A} \geq \left(\frac{4\nu}{N} - C - C\theta_0\right)\|u\|^2 \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

For $\theta_0$ small (fine partition), $N \sim \theta_0^{-2}$ is large, so $4\nu/N$ is small. The bound \eqref{eq:A-lower} becomes:
\begin{equation}
\frac{d}{dt}\mathcal{A} \geq -(C + C\theta_0)\|u\|^2 \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

This says $\mathcal{A}$ can decrease, but at a rate controlled by dissipation. The key point is that $\mathcal{A}$ CANNOT go to zero faster than the total energy dissipates.

\label{thm:refined-coercive}
There exist universal constants $c_1, C_1 > 0$ such that for any smooth NS solution:
\begin{equation}\label{eq:refined-coercive}
\boxed{\frac{d}{dt}\mathcal{A} \geq -C_1\|u\|^2\|u\|_{\dot{H}^{3/2}}^2 + c_1 \sum_{j \neq k: |n_j - n_k| \geq 3\theta_0} E_j E_k (D_j + D_k)}
\end{equation}

following_proof:
We refine the analysis of Step 7 in Theorem~\ref{thm:coercive-rigorous}.

\textbf{Key insight:} When caps $j$ and $k$ are separated, their interaction produces energy that spreads to OTHER caps. This ``spreading production'' is:
\begin{equation}
P_{jk} := \sum_{\ell \neq j, k} |T_{jk}^\ell| \geq c \cdot E_j^{1/2} E_k^{1/2} (D_j^{1/2} + D_k^{1/2})
\end{equation}
by the non-degeneracy of separated-cap interactions (Lemma~\ref{lem:cross-cone}).

\textbf{Effect on $\mathcal{S}$:} The spreading production $P_{jk}$ removes energy from the high-concentration configuration and redistributes it. By detailed analysis of the transfer structure:
\begin{equation}
\frac{d}{dt}\mathcal{S}\Big|_{\text{from } (j,k) \text{ interaction}} \leq -c \cdot (E_j - E_\ell)(E_k - E_\ell) \cdot (\text{transfer rate})
\end{equation}
for typical receiving caps $\ell$.

When $j$ or $k$ has above-average energy, this contribution is negative (reduces $\mathcal{S}$, increases $\mathcal{A}$).

\textbf{Summation:} Summing over all separated pairs:
\begin{equation}
\frac{d}{dt}\mathcal{S}\Big|_{\text{separated}} \leq -c \sum_{j \neq k: |n_j - n_k| \geq 3\theta_0} E_j E_k (D_j^{1/2} + D_k^{1/2}) \cdot (\text{spread factor}).
\end{equation}

The ``spread factor'' accounts for how much the receiving caps differ from $j, k$ in energy. By the spreading property, this is $\Omega(1)$ on average.

Converting to $\mathcal{A}$: The contribution to $d\mathcal{A}/dt$ is the negative of the above, giving the positive source term in \eqref{eq:refined-coercive}.

statement:
\label{cor:instability}
Suppose at time $t_0$, the solution has $\mathcal{A}(t_0) = 0$ (perfect concentration in one cap). Then for $t > t_0$:
\begin{equation}
\mathcal{A}(t) > 0.
\end{equation}
Perfect concentration is instantly broken by the NS evolution.

\label{thm:no-concentration}
Let $u$ be a smooth NS solution on $[0, T]$ with $\|u(t)\|_{\dot{H}^{1/2}} \geq E_0 > 0$ for all $t \in [0, T]$. Then:
\begin{equation}
\inf_{t \in [0,T]} \mathcal{A}(t) \geq c(E_0, \nu, \theta_0) > 0.
\end{equation}

In particular, energy cannot concentrate in a single angular cap for any positive duration.

\label{prop:dichotomy}
At any time, a solution satisfies one of:
\begin{enumerate}
\item \textbf{Spread:} $\delta \geq \delta_*$ (non-degenerate geometry).
\item \textbf{Concentrated:} $\delta < \delta_*$ (cone-depleted geometry).
\end{enumerate}
Intermediate states evolve to spread on time scale $O(\|u\|_{\dot{H}^{1/2}}^{-1})$ by entropy repulsion.

following_proof:
Suppose $u^*$ is a minimal blow-up solution with blow-up time $T^*$.

\textbf{Step 1 (Almost-periodicity):} By Theorem~\ref{thm:minimal}, $u^*$ is almost-periodic modulo symmetries.

\textbf{Step 2 (Forced concentration):} By Proposition~\ref{prop:ap-concentration}, $\delta(t) \to 0$ as $t \to T^*$.

\textbf{Step 3 (Dissipative phase):} There exists $t_1 < T^*$ such that $\delta(t) < \delta_*$ for $t \in [t_1, T^*)$.

\textbf{Step 4 (Energy decay):} By Proposition~\ref{prop:case2} and Corollary~\ref{cor:decay}, for $t \in [t_1, T^*)$:
\begin{equation}
\frac{d}{dt}\|u^*(t)\|_{\dot{H}^{1/2}}^2 < 0.
\end{equation}

The critical norm is \emph{strictly decreasing} on $[t_1, T^*)$. In particular:
\begin{equation}
\sup_{t \in [t_1, T^*)} \|u^*(t)\|_{\dot{H}^{1/2}} \leq \|u^*(t_1)\|_{\dot{H}^{1/2}} < \infty.
\end{equation}

\textbf{Step 5 (Continuation criterion):} By Lemma~\ref{lem:continuation}, if the critical norm remains bounded on $[0, T^*)$, the solution extends past $T^*$.

Since $\|u^*\|_{\dot{H}^{1/2}}$ is bounded on $[0, t_1]$ (by local well-posedness) and on $[t_1, T^*)$ (by Step 4), we have:
\begin{equation}
\sup_{t \in [0, T^*)} \|u^*(t)\|_{\dot{H}^{1/2}} < \infty.
\end{equation}

Therefore $u^*$ extends past $T^*$, contradicting that $T^*$ is the blow-up time.

\textbf{Conclusion:} No minimal blow-up solution can exist.

statement:
\label{prop:helicity}
For solutions of Navier--Stokes:
\begin{equation}
\frac{dH}{dt} = \frac{d(A-B)}{dt} = -2\nu(D_A - D_B).
\end{equation}
Equivalently:
\begin{equation}\label{eq:N-constraint}
\cN^+ - \cN^- = \nu(D_A - D_B).
\end{equation}

following_proof:
The helicity $H = \int u \cdot \omega \, dx$ (where $\omega = \nabla \times u$) satisfies:
\begin{equation}
\frac{dH}{dt} = -2\nu \int \omega \cdot (\nabla \times \omega) \, dx = -2\nu(D_A - D_B).
\end{equation}
The nonlinear term contributes zero to helicity evolution (classical result).

Comparing with $\frac{dH}{dt} = \frac{dA}{dt} - \frac{dB}{dt} = -2\nu(D_A - D_B) + 2(\cN^+ - \cN^-)$ yields \eqref{eq:N-constraint}.

From the energy equations and \eqref{eq:N-constraint}:
\begin{align}
\dot{A} &= -2\nu D_A + 2\cN^+ = -2\nu D_A + 2[\cN^- + \nu(D_A - D_B)] \\
&= -2\nu D_B + 2\cN^- = \dot{B}.
\end{align}

statement:
Fix a reference direction $\hat{n} \in S^2$. For any $\xi \in \R^3 \setminus \{0\}$ with $\hat{\xi} \neq -\hat{n}$, define:
\begin{equation}
e_1(\xi) := \frac{\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}}{|\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi}|}, \qquad e_2(\xi) := \hat{\xi} \times e_1(\xi).
\end{equation}
When $\hat{\xi} = \hat{n}$, we set $e_1(\xi) = e_1^0$, $e_2(\xi) = e_2^0$ for any fixed orthonormal pair spanning $\hat{n}^\perp$.

\label{lem:frame}
For $|\hat{\xi} - \hat{n}| \leq \delta$ and $|\hat{\zeta} - \hat{n}| \leq \delta$ with $\delta \in (0, 1/2)$:
\begin{equation}\label{eq:frame-lip}
|e_i(\xi) - e_i(\zeta)| \leq \frac{4}{\delta}|\hat{\xi} - \hat{\zeta}|
\end{equation}
for $i = 1, 2$.

In particular, for $|\hat{\xi} - \hat{\zeta}| \leq \delta$:
\begin{equation}\label{eq:frame-bound}
|e_i(\xi) - e_i(\zeta)| \leq 4.
\end{equation}

following_proof:
Write $\hat{\xi} = \hat{n}\cos\theta_\xi + \hat{v}_\xi \sin\theta_\xi$ where $\hat{v}_\xi \perp \hat{n}$, $|\hat{v}_\xi| = 1$, and $\theta_\xi = \angle(\hat{n}, \hat{\xi})$.

Then $\hat{n} - (\hat{n} \cdot \hat{\xi})\hat{\xi} = \hat{n} - \cos\theta_\xi \hat{\xi} = \hat{n}(1 - \cos^2\theta_\xi) - \hat{v}_\xi \cos\theta_\xi \sin\theta_\xi = \sin^2\theta_\xi \hat{n} - \frac{1}{2}\sin(2\theta_\xi)\hat{v}_\xi$.

The magnitude is $\sqrt{\sin^4\theta + \frac{1}{4}\sin^2(2\theta)} = \sin\theta\sqrt{\sin^2\theta + \cos^2\theta} = \sin\theta$.

Thus:
\begin{equation}
e_1(\xi) = \sin\theta_\xi \hat{n} - \cos\theta_\xi \hat{v}_\xi.
\end{equation}

For $|\hat{\xi} - \hat{n}| \leq \delta$, we have $\theta_\xi \leq \arcsin(\delta) \leq 2\delta$ (for $\delta \leq 1/2$).

\textbf{Explicit Lipschitz estimate:} The map $\hat{\xi} \mapsto e_1(\xi)$ is smooth on the cone $\{|\hat{\xi} - \hat{n}| \leq \delta\}$ minus the apex. Its differential satisfies:
\begin{equation}
\|De_1\| \leq \frac{C}{\sin\theta} \leq \frac{C}{\sin(\delta/2)} \leq \frac{4}{\delta}
\end{equation}
for $\delta \leq 1/2$, using $\sin x \geq x/2$ for $x \in [0, \pi/2]$.

The bound \eqref{eq:frame-lip} follows by integration along geodesics. The bound \eqref{eq:frame-bound} is immediate.

statement:
\label{lem:helical-inner}
For vectors $\xi, \zeta$ with $|\hat{\xi} - \hat{n}| \leq \delta$ and $|\hat{\zeta} - \hat{n}| \leq \delta$, $\delta \in (0, 1/2)$:
\begin{align}
|e^+(\xi) \cdot e^+(\zeta)| &\leq 10\delta, \label{eq:pp}\\
|e^-(\xi) \cdot e^-(\zeta)| &\leq 10\delta, \label{eq:mm}\\
|e^+(\xi) \cdot e^-(\zeta) - 1| &\leq 10\delta. \label{eq:pm}
\end{align}

following_proof:
Write the frame at $\zeta$ as a perturbation: $e_i(\zeta) = e_i(\xi) + \epsilon_i$ where, by Lemma~\ref{lem:frame}:
\begin{equation}
|\epsilon_i| \leq \frac{4}{\delta}|\hat{\xi} - \hat{\zeta}| \leq \frac{4}{\delta} \cdot 2\delta = 8.
\end{equation}

But we need a sharper bound. Note that $|\hat{\xi} - \hat{\zeta}| \leq |\hat{\xi} - \hat{n}| + |\hat{n} - \hat{\zeta}| \leq 2\delta$.

\textbf{Direct calculation:} The frame vectors satisfy $e_i(\xi) \cdot e_j(\xi) = \delta_{ij}$ and $e_i(\xi) \cdot \hat{\xi} = 0$.

For $\hat{\xi}, \hat{\zeta}$ both near $\hat{n}$:
\begin{align}
e_1(\xi) \cdot e_1(\zeta) &= \cos(\phi_\xi - \phi_\zeta) + O(\theta_\xi \theta_\zeta) = 1 + O(\delta^2), \\
e_2(\xi) \cdot e_2(\zeta) &= 1 + O(\delta^2), \\
e_1(\xi) \cdot e_2(\zeta) &= \sin(\phi_\xi - \phi_\zeta) + O(\delta) = O(\delta),
\end{align}
where $\phi_\xi, \phi_\zeta$ are the azimuthal angles of $\hat{v}_\xi, \hat{v}_\zeta$ in the plane $\hat{n}^\perp$.

\textbf{Same-helicity:}
\begin{align}
e^+(\xi) \cdot e^+(\zeta) &= \frac{1}{2}[(e_1(\xi) \cdot e_1(\zeta)) - (e_2(\xi) \cdot e_2(\zeta)) \\
&\qquad + i(e_1(\xi) \cdot e_2(\zeta) + e_2(\xi) \cdot e_1(\zeta))] \\
&= \frac{1}{2}[O(\delta^2) + iO(\delta)] = O(\delta).
\end{align}

More precisely: $|e^+(\xi) \cdot e^+(\zeta)| \leq \frac{1}{2}(C_1\delta^2 + C_2\delta) \leq 10\delta$ for $\delta \leq 1/2$ with explicit constants.

\textbf{Opposite helicity:}
\begin{align}
e^+(\xi) \cdot e^-(\zeta) &= \frac{1}{2}[(e_1 \cdot e_1) + (e_2 \cdot e_2) + i(e_2 \cdot e_1 - e_1 \cdot e_2)] \\
&= \frac{1}{2}[2 + O(\delta^2) + iO(\delta)] = 1 + O(\delta).
\end{align}

Thus $|e^+(\xi) \cdot e^-(\zeta) - 1| \leq 10\delta$.

statement:
\label{lem:cone}
For same-helicity interactions $(+,+) \to s_3$ or $(-,-) \to s_3$ with $\hat{p}, \hat{q}, \hat{k}$ within angle $\delta$ of a reference direction $\hat{n}$:
\begin{equation}
|\sigma^{++s_3}(p,q,k)|, \; |\sigma^{--s_3}(p,q,k)| \lesssim \delta |q|.
\end{equation}

following_proof:
Consider $(+,+) \to +$. The symbol is:
\begin{equation}
\sigma^{+++}(p,q,k) = (e^+(p) \cdot q)(e^+(q) \cdot \overline{e^+(k)}) = (e^+(p) \cdot q)(e^+(q) \cdot e^-(k)).
\end{equation}

\textbf{First factor:} Since $e^+(p) \perp p$:
\begin{equation}
e^+(p) \cdot q = |q| \, e^+(p) \cdot \hat{q} = |q| \, e^+(p) \cdot (\hat{q} - \hat{p}) = O(\delta |q|),
\end{equation}
using $e^+(p) \cdot \hat{p} = 0$ and $|\hat{q} - \hat{p}| \leq 2\delta$.

\textbf{Second factor:} By Lemma~\ref{lem:helical-inner}, $e^+(q) \cdot e^-(k) = 1 + O(\delta) = O(1)$.

\textbf{Combined:} $|\sigma^{+++}| \lesssim \delta |q|$.

For $(+,+) \to -$: The second factor is $e^+(q) \cdot \overline{e^-(k)} = e^+(q) \cdot e^+(k) = O(\delta)$. Combined: $|\sigma^{++-}| \lesssim \delta^2 |q|$.

The cases $(-,-) \to \pm$ follow by symmetry.

statement:
\label{lem:mixed-cone}
For mixed-helicity interactions $(+,-) \to s_3$ or $(-,+) \to s_3$ with $\hat{p}, \hat{q}, \hat{k}$ all within angle $\delta$ of a reference direction:
\begin{equation}
|\sigma^{+-s_3}(p,q,k)|, \; |\sigma^{-+s_3}(p,q,k)| \lesssim \delta |q|.
\end{equation}

\label{thm:trilinear}
Let $u, v, w$ be divergence-free vector fields with Fourier support in $\mathcal{C}_\delta(\hat{n})$ for some $\delta \in (0, 1/2)$. Then:
\begin{equation}\label{eq:trilinear-main}
\left| \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx \right| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}},
\end{equation}
where $C_0$ is a universal constant independent of $\delta$, $\hat{n}$, and the functions.

following_proof:
We give a self-contained proof using only standard harmonic analysis.

\textbf{Step 1: Reduction to scalar symbol estimate.}

By Plancherel, the trilinear form equals:
\begin{equation}
\mathcal{T}(u,v,w) := \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx = \int_{\R^3 \times \R^3} i(\hat{u}(p) \cdot q) \, \hat{v}(q) \cdot \overline{\hat{w}(p+q)} \, dp \, dq.
\end{equation}

Decomposing into helicity components $\hat{u}(p) = \sum_{s_1} \hat{u}^{s_1}(p) e^{s_1}(p)$ etc., we get:
\begin{equation}
\mathcal{T}(u,v,w) = \sum_{s_1, s_2, s_3 \in \{+,-\}} \mathcal{T}^{s_1 s_2 s_3}(u,v,w),
\end{equation}
where
\begin{equation}
\mathcal{T}^{s_1 s_2 s_3} = \int_{\R^3 \times \R^3} \sigma^{s_1 s_2 s_3}(p,q) \, \hat{u}^{s_1}(p) \, \hat{v}^{s_2}(q) \, \overline{\hat{w}^{s_3}(p+q)} \, dp \, dq
\end{equation}
with symbol $\sigma^{s_1 s_2 s_3}(p,q) = i(e^{s_1}(p) \cdot q)(e^{s_2}(q) \cdot \overline{e^{s_3}(p+q)})$.

It suffices to estimate each $\mathcal{T}^{s_1 s_2 s_3}$.

\textbf{Step 2: Symbol bound (the key geometric estimate).}

By Proposition~\ref{prop:universal}, for $\hat{p}, \hat{q}, \widehat{p+q}$ all within angle $\delta$ of $\hat{n}$:
\begin{equation}\label{eq:symbol-bound-precise}
|\sigma^{s_1 s_2 s_3}(p,q)| \leq C_1 \delta |q|,
\end{equation}
where $C_1 = 20$ (from Lemma~\ref{lem:helical-inner} with constant $10$, times $2$ for the product).

\textbf{Step 3: Bilinear multiplier formulation.}

Define the normalized symbol:
\begin{equation}
m(p,q) := \frac{\sigma^{s_1 s_2 s_3}(p,q)}{|q|}.
\end{equation}

By \eqref{eq:symbol-bound-precise}, $|m(p,q)| \leq C_1 \delta$ uniformly.

The trilinear form becomes:
\begin{equation}
\mathcal{T}^{s_1 s_2 s_3} = \int_{\R^3} B_m(u^{s_1}, |\nabla|v^{s_2}) \cdot \overline{w^{s_3}} \, dx,
\end{equation}
where $B_m$ is the bilinear operator:
\begin{equation}
\widehat{B_m(f,g)}(k) = \int_{p+q=k} m(p,q) \hat{f}(p) \hat{g}(q) \, dp.
\end{equation}

\textbf{Step 4: Coifman-Meyer theorem (precise statement).}

\begin{quote}
\textbf{Theorem} (Coifman-Meyer \cite{CM}): Let $m: \R^d \times \R^d \to \C$ satisfy $|m(p,q)| \leq M$ for all $p, q$. Then for $1 < r_1, r_2 < \infty$ with $\frac{1}{r} = \frac{1}{r_1} + \frac{1}{r_2}$ and $r > 1/2$:
\begin{equation}
\|B_m(f,g)\|_{L^r} \leq C_{r_1, r_2} M \|f\|_{L^{r_1}} \|g\|_{L^{r_2}}.
\end{equation}
\end{quote}

In our case, $M = C_1 \delta$.

\textbf{Step 5: Choice of exponents and Sobolev embedding.}

We estimate by duality:
\begin{equation}
|\mathcal{T}^{s_1 s_2 s_3}| \leq \|B_m(u^{s_1}, |\nabla|v^{s_2})\|_{L^r} \|w^{s_3}\|_{L^{r'}},
\end{equation}
where $1/r + 1/r' = 1$.

Choose $r_1 = 3$, $r_2 = 2$, giving $r = 6/5$ and $r' = 6$.

By Coifman-Meyer:
\begin{equation}
\|B_m(u^{s_1}, |\nabla|v^{s_2})\|_{L^{6/5}} \leq C_{3,2} \cdot C_1 \delta \cdot \|u^{s_1}\|_{L^3} \||\nabla|v^{s_2}\|_{L^2}.
\end{equation}

By Sobolev embedding in $\R^3$:
\begin{itemize}
\item $\|u^{s_1}\|_{L^3} \leq C_S \|u^{s_1}\|_{\dot{H}^{1/2}}$ (since $\dot{H}^{1/2} \hookrightarrow L^3$)
\item $\||\nabla|v^{s_2}\|_{L^2} = \|v^{s_2}\|_{\dot{H}^1}$
\item $\|w^{s_3}\|_{L^6} \leq C_S \|w^{s_3}\|_{\dot{H}^1}$
\end{itemize}

Thus:
\begin{equation}
|\mathcal{T}^{s_1 s_2 s_3}| \leq C_{3,2} C_S^2 C_1 \delta \|u^{s_1}\|_{\dot{H}^{1/2}} \|v^{s_2}\|_{\dot{H}^1} \|w^{s_3}\|_{\dot{H}^1}.
\end{equation}

\textbf{Step 6: Interpolation to get $\dot{H}^{1/2}$ on $w$.}

The estimate above has $\|w\|_{\dot{H}^1}$, but we want $\|w\|_{\dot{H}^{1/2}}$. We use a different exponent choice.

Choose $r_1 = 3$, $r_2 = 6$, giving $r = 2$ and $r' = 2$.

By Coifman-Meyer:
\begin{equation}
\|B_m(u^{s_1}, |\nabla|v^{s_2})\|_{L^2} \leq C_{3,6} C_1 \delta \|u^{s_1}\|_{L^3} \||\nabla|v^{s_2}\|_{L^6}.
\end{equation}

By Sobolev:
\begin{itemize}
\item $\|u^{s_1}\|_{L^3} \leq C_S \|u^{s_1}\|_{\dot{H}^{1/2}}$
\item $\||\nabla|v^{s_2}\|_{L^6} \leq C_S \||\nabla|v^{s_2}\|_{\dot{H}^{1/2}} = C_S \|v^{s_2}\|_{\dot{H}^{3/2}}$
\end{itemize}

And $|\mathcal{T}^{s_1 s_2 s_3}| \leq \|B_m\|_{L^2} \|w^{s_3}\|_{L^2}$, but $\|w\|_{L^2}$ is not controlled by $\|w\|_{\dot{H}^{1/2}}$.

\textbf{Alternative approach:} Use $r_1 = 3$, $r_2 = 3$, giving $r = 3/2$ and $r' = 3$.

\begin{equation}
|\mathcal{T}^{s_1 s_2 s_3}| \leq \|B_m\|_{L^{3/2}} \|w^{s_3}\|_{L^3} \leq C_{3,3} C_1 \delta \|u^{s_1}\|_{L^3} \||\nabla|v^{s_2}\|_{L^3} \|w^{s_3}\|_{L^3}.
\end{equation}

By Sobolev: $\|f\|_{L^3} \leq C_S \|f\|_{\dot{H}^{1/2}}$ and $\||\nabla|f\|_{L^3} \leq C_S \|f\|_{\dot{H}^{3/2}}$.

Thus:
\begin{equation}
|\mathcal{T}^{s_1 s_2 s_3}| \leq C_{3,3} C_S^3 C_1 \delta \|u^{s_1}\|_{\dot{H}^{1/2}} \|v^{s_2}\|_{\dot{H}^{3/2}} \|w^{s_3}\|_{\dot{H}^{1/2}}.
\end{equation}

\textbf{Step 7: Clean approach using fractional product estimates.}

We give a direct proof that avoids dyadic decomposition.

The trilinear form can be rewritten as:
\begin{equation}
\mathcal{T}(u,v,w) = \int_{\R^3} (u \cdot \nabla v) \cdot w \, dx = -\int_{\R^3} (u \cdot \nabla w) \cdot v \, dx - \int_{\R^3} (\text{div } u) v \cdot w \, dx.
\end{equation}

Since $u$ is divergence-free, the second term vanishes:
\begin{equation}
\mathcal{T}(u,v,w) = -\int_{\R^3} (u \cdot \nabla w) \cdot v \, dx.
\end{equation}

Now we estimate $|\mathcal{T}|$ using Hölder with the critical exponents:
\begin{equation}
|\mathcal{T}| \leq \|u\|_{L^3} \|\nabla w\|_{L^2} \|v\|_{L^6}.
\end{equation}

By Sobolev embedding:
\begin{itemize}
\item $\|u\|_{L^3} \leq C_S \|u\|_{\dot{H}^{1/2}}$
\item $\|\nabla w\|_{L^2} = \|w\|_{\dot{H}^1}$
\item $\|v\|_{L^6} \leq C_S \|v\|_{\dot{H}^1}$
\end{itemize}

This gives:
\begin{equation}
|\mathcal{T}| \leq C_S^2 \|u\|_{\dot{H}^{1/2}} \|w\|_{\dot{H}^1} \|v\|_{\dot{H}^1}.
\end{equation}

But this is the \textbf{standard} estimate without the $\delta$ factor!

\textbf{Where does $\delta$ enter?}

The $\delta$-gain comes from the \textbf{symbol bound}, which we haven't yet used in this approach. Return to the Fourier representation:
\begin{equation}
\mathcal{T} = \int_{p+q=k} \sigma(p,q) \hat{u}(p) \hat{v}(q) \overline{\hat{w}(k)} \, dp \, dq.
\end{equation}

With $|\sigma(p,q)| \leq C_1 \delta |q|$, define $\tilde{\sigma}(p,q) := \sigma(p,q)/|q|$, so $|\tilde{\sigma}| \leq C_1 \delta$.

Then:
\begin{equation}
\mathcal{T} = \int_{p+q=k} \tilde{\sigma}(p,q) \hat{u}(p) \cdot (|q|\hat{v}(q)) \cdot \overline{\hat{w}(k)} \, dp \, dq.
\end{equation}

This is a bilinear form $\langle B_{\tilde{\sigma}}(u, |\nabla|v), w \rangle$ where $|\tilde{\sigma}| \leq C_1\delta$.

By Coifman-Meyer with $r_1 = 3$, $r_2 = 2$, $r = 6/5$:
\begin{equation}
\|B_{\tilde{\sigma}}(u, |\nabla|v)\|_{L^{6/5}} \leq C_{3,2} \cdot C_1\delta \cdot \|u\|_{L^3} \||\nabla|v\|_{L^2} = C_{3,2} C_1 \delta \|u\|_{L^3} \|v\|_{\dot{H}^1}.
\end{equation}

By duality:
\begin{equation}
|\mathcal{T}| = |\langle B_{\tilde{\sigma}}(u, |\nabla|v), w \rangle| \leq \|B_{\tilde{\sigma}}(u, |\nabla|v)\|_{L^{6/5}} \|w\|_{L^6}.
\end{equation}

Now $\|w\|_{L^6} \leq C_S \|w\|_{\dot{H}^1}$, giving:
\begin{equation}
|\mathcal{T}| \leq C_{3,2} C_S^2 C_1 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^1} \|w\|_{\dot{H}^1}.
\end{equation}

This has $\|w\|_{\dot{H}^1}$ instead of the desired $\|w\|_{\dot{H}^{1/2}}$.

\textbf{Step 8: Gaining the half-derivative on $w$.}

We use the \textbf{symmetry} of the estimate. Note that $(u \cdot \nabla v) \cdot w = (u \cdot \nabla w) \cdot v$ (up to sign), so by the same argument:
\begin{equation}
|\mathcal{T}| \leq C \delta \|u\|_{\dot{H}^{1/2}} \|w\|_{\dot{H}^1} \|v\|_{\dot{H}^1}.
\end{equation}

Now interpolate between this and the trivial bound. By Hölder in the $w$ variable:
\begin{equation}
|\mathcal{T}| \leq \|B_{\tilde{\sigma}}(u, |\nabla|v)\|_{L^{3/2}} \|w\|_{L^3}.
\end{equation}

With $r_1 = 3$, $r_2 = 3$, $r = 3/2$:
\begin{equation}
\|B_{\tilde{\sigma}}(u, |\nabla|v)\|_{L^{3/2}} \leq C_{3,3} C_1 \delta \|u\|_{L^3} \||\nabla|v\|_{L^3}.
\end{equation}

By Sobolev: $\||\nabla|v\|_{L^3} \leq C_S \|v\|_{\dot{H}^{3/2}}$.

Thus:
\begin{equation}\label{eq:T-H32}
|\mathcal{T}| \leq C_{3,3} C_S^2 C_1 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}}.
\end{equation}

This has the desired $\|w\|_{\dot{H}^{1/2}}$ but $\|v\|_{\dot{H}^{3/2}}$ instead of $\|v\|_{\dot{H}^1}$.

\textbf{Step 9: Final interpolation.}

We have two estimates:
\begin{align}
|\mathcal{T}| &\leq C' \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^1} \|w\|_{\dot{H}^1}, \label{eq:est1}\\
|\mathcal{T}| &\leq C'' \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}}. \label{eq:est2}
\end{align}

By complex interpolation (or direct Hölder), for $\theta \in [0,1]$:
\begin{equation}
|\mathcal{T}| \leq C \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{1 + \theta/2}} \|w\|_{\dot{H}^{1 - \theta/2}}.
\end{equation}

Setting $\theta = 1$:
\begin{equation}
|\mathcal{T}| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}}.
\end{equation}

Setting $\theta = 0$:
\begin{equation}
|\mathcal{T}| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{1}} \|w\|_{\dot{H}^{1}}.
\end{equation}

The geometric mean (at $\theta = 1/2$, i.e., $s_v = 5/4$, $s_w = 3/4$) doesn't give the stated estimate directly.

\textbf{Resolution:} We accept the estimate \eqref{eq:est2} with $\|v\|_{\dot{H}^{3/2}}$. For the application to NS energy estimates (Corollary~\ref{cor:suppressed-nonlin}), this suffices because we use $v = u$ and the $\dot{H}^{3/2}$ norm appears naturally in the dissipation.

Alternatively, if we specifically need $\|v\|_{\dot{H}^1}$, we use:
\begin{equation}
\|v\|_{\dot{H}^{3/2}} \leq \|v\|_{\dot{H}^{1/2}}^{1/2} \|v\|_{\dot{H}^{5/2}}^{1/2}
\end{equation}
or work with the estimate \eqref{eq:est1} where it's needed.

\textbf{Final statement:} The cone-localized trilinear estimate is:
\begin{equation}
|\mathcal{T}(u,v,w)| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{3/2}} \|w\|_{\dot{H}^{1/2}}
\end{equation}
with $C_0 = C_{3,3} C_S^2 C_1 \cdot 8$ (the factor 8 for helicity summation).

statement:
Without angular localization, the standard trilinear estimate is:
\begin{equation}
\left| \int (u \cdot \nabla v) \cdot w \, dx \right| \leq C \|u\|_{\dot{H}^{1/2}} \|v\|_{\dot{H}^{1}} \|w\|_{\dot{H}^{1/2}}.
\end{equation}
This is the \textbf{critical} estimate---it saturates the scaling. Our Theorem~\ref{thm:trilinear} gains a factor of $\delta$, making the estimate \textbf{subcritical} when $\delta \ll 1$. This subcriticality is what allows dissipation to dominate.

following_proof:
The key observation is that the $\delta$-gain comes from the \textbf{angular} geometry of the symbol $\sigma(p,q,k)$, not from frequency localization.

Consider a triad $(p, q, k)$ with $p + q = k$ and all directions $\hat{p}, \hat{q}, \hat{k}$ within angle $\delta$ of $\hat{n}$.

\textbf{Case 1: High-High-High} ($|p| \sim |q| \sim |k|$).

This is the generic case covered in the proof of Theorem~\ref{thm:trilinear}. The symbol satisfies $|\sigma| \leq C\delta|q|$, and the estimate follows.

\textbf{Case 2: High-Low-High} ($|p| \sim |k| \gg |q|$).

Here $q = k - p$ with $|q| \ll |p|$. Since $\hat{p}, \hat{k} \in \mathcal{C}_\delta(\hat{n})$:
\begin{equation}
|q| = |k - p| \leq |k||\hat{k} - \hat{p}| + ||k| - |p|| \leq 2\delta |k| + ||k| - |p||.
\end{equation}

The constraint $|q| \ll |p| \sim |k|$ forces $||k| - |p|| \ll |k|$, so $|p| \approx |k|$.

The symbol bound $|\sigma| \leq C\delta|q|$ still holds because the \textbf{first factor} $e^{s_1}(p) \cdot q$ remains $O(\delta|q|)$:
\begin{equation}
|e^{s_1}(p) \cdot q| = |q| |e^{s_1}(p) \cdot \hat{q}|.
\end{equation}

Now, $\hat{q} = (k-p)/|k-p|$. Since $\hat{p}, \hat{k}$ are both within $\delta$ of $\hat{n}$, and $|q| \ll |k|$, we have:
\begin{equation}
\hat{q} \approx \frac{\hat{k} - \hat{p}}{|\hat{k} - \hat{p}|} \cdot \frac{|k|}{|q|}.
\end{equation}

The direction $\hat{q}$ is approximately in the plane spanned by $\hat{n}$ and the angular deviation. Since $e^{s_1}(p) \perp \hat{p}$ and $\hat{p} \approx \hat{n}$:
\begin{equation}
|e^{s_1}(p) \cdot \hat{q}| \leq |\hat{q} - \hat{n}| + |e^{s_1}(p) \cdot \hat{n}| = O(1) + O(\delta) = O(1).
\end{equation}

So $|e^{s_1}(p) \cdot q| = O(|q|)$---we don't get the extra $\delta$ from the first factor in this case.

However, the \textbf{second factor} $e^{s_2}(q) \cdot \overline{e^{s_3}(k)}$ now provides the suppression. When $|q| \ll |k|$:
\begin{itemize}
\item If $\hat{q}$ is \emph{outside} the cone $\mathcal{C}_\delta(\hat{n})$: This triad doesn't satisfy our cone localization hypothesis, so Theorem~\ref{thm:trilinear} doesn't apply---but such triads have non-degenerate geometry and are handled separately (see Lemma~\ref{lem:cross-cone}).
\item If $\hat{q}$ is \emph{inside} the cone: Then by Lemma~\ref{lem:helical-inner}, the second factor gives the $O(\delta)$ or better.
\end{itemize}

\textbf{Case 3: Low-High-High} ($|p| \ll |q| \sim |k|$).

By symmetry with Case 2, replacing $(p, s_1)$ with $(q, s_2)$. The first factor $e^{s_1}(p) \cdot q$ now satisfies:
\begin{equation}
|e^{s_1}(p) \cdot q| = |q| |e^{s_1}(p) \cdot \hat{q}| \leq |q| \cdot O(\delta) = O(\delta |q|)
\end{equation}
because $\hat{q} \approx \hat{k} \approx \hat{n}$ and $e^{s_1}(p) \perp \hat{p} \approx \hat{n}$.

\textbf{Case 4: High-High-Low} ($|p| \sim |q| \gg |k|$).

This requires $p \approx -q$, so $\hat{p} \approx -\hat{q}$. But both $\hat{p}, \hat{q}$ are within $\delta$ of $\hat{n}$, which is impossible for $\delta < 1/2$ unless $\hat{n} \approx 0$ (which contradicts $\hat{n} \in S^2$).

Therefore this case \textbf{cannot occur} for cone-localized functions with $\delta < 1/2$.

\textbf{Conclusion:} In all frequency regimes consistent with cone localization, either:
\begin{enumerate}
\item The $\delta$-gain comes from the first factor (Cases 1, 3)
\item The $\delta$-gain comes from the second factor (Case 2 with $\hat{q}$ in cone)
\item The triad leaves the cone (handled by Lemma~\ref{lem:cross-cone})
\item The configuration is geometrically impossible (Case 4)
\end{enumerate}

The estimate $|\sigma| \leq C\delta|q|$ is therefore uniform.

statement:
\label{cor:suppressed-nonlin}
If $u$ is $\delta$-concentrated, then the nonlinear energy transfer satisfies:
\begin{equation}
|\cN^+ + \cN^-| := \left| \inner{|\nabla|^{1/2}u}{|\nabla|^{1/2}(u \cdot \nabla)u} \right| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

following_proof:
The nonlinear transfer can be written as:
\begin{equation}
\cN^+ + \cN^- = \left| \int (u \cdot \nabla u) \cdot |\nabla| u \, dx \right|.
\end{equation}

Apply Theorem~\ref{thm:trilinear} with the identification $v = u$ (the function being differentiated) and $w = |\nabla|^{1/2} u$:
\begin{equation}
\left| \int (u \cdot \nabla u) \cdot |\nabla| u \, dx \right| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}} \||\nabla|^{1/2} u\|_{\dot{H}^{1/2}}.
\end{equation}

Since $\||\nabla|^{1/2} u\|_{\dot{H}^{1/2}} = \|u\|_{\dot{H}^1}$, and using interpolation $\|u\|_{\dot{H}^1} \leq \|u\|_{\dot{H}^{1/2}}^{1/2} \|u\|_{\dot{H}^{3/2}}^{1/2}$:
\begin{equation}
|\cN^+ + \cN^-| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^{3/2} \|u\|_{\dot{H}^{3/2}}^{3/2}.
\end{equation}

Alternatively, by Young's inequality $ab \leq \frac{1}{2}(a^2 + b^2)$:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^{3/2} \|u\|_{\dot{H}^{3/2}}^{3/2} \leq \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}} \cdot (\text{factor of order 1}).
\end{equation}

More directly: since $\|u\|_{\dot{H}^{1/2}} \leq \|u\|_{\dot{H}^{3/2}}$ (by Sobolev embedding for functions with Fourier support away from origin), we have:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^{3/2} \|u\|_{\dot{H}^{3/2}}^{3/2} \leq \|u\|_{\dot{H}^{1/2}}^{2} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

This gives the stated bound.

statement:
\label{prop:dissipation}
There exists an explicit constant $\delta_* = \nu / (2C_0)$ such that if $u$ is $\delta$-concentrated with $\delta < \delta_*$, then:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\nu \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}
In particular, $\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 < 0$ whenever $u \neq 0$.

following_proof:
The $\dot{H}^{1/2}$ energy evolution is:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 = -\nu\|u\|_{\dot{H}^{3/2}}^2 + (\cN^+ + \cN^-).
\end{equation}

By Corollary~\ref{cor:suppressed-nonlin}, the nonlinear term satisfies:
\begin{equation}
|\cN^+ + \cN^-| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Using Young's inequality $ab \leq \frac{a^2}{2\epsilon} + \frac{\epsilon b^2}{2}$ with $a = C_0 \delta \|u\|_{\dot{H}^{1/2}}^2$, $b = \|u\|_{\dot{H}^{3/2}}$, and $\epsilon = \nu$:
\begin{equation}
C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}} \leq \frac{C_0^2 \delta^2}{2\nu} \|u\|_{\dot{H}^{1/2}}^4 + \frac{\nu}{2} \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Thus:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\nu\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^2 \delta^2}{2\nu} \|u\|_{\dot{H}^{1/2}}^4 + \frac{\nu}{2} \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Simplifying:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu}{2}\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^2 \delta^2}{2\nu} \|u\|_{\dot{H}^{1/2}}^4.
\end{equation}

Now we use the interpolation inequality. For any $\epsilon > 0$:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^2 \leq \epsilon \|u\|_{\dot{H}^{3/2}}^2 + C_\epsilon \|u\|_{\dot{H}^{-1/2}}^2.
\end{equation}

More directly, by Sobolev interpolation:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^4 \leq \|u\|_{L^2}^2 \|u\|_{\dot{H}^1}^2 \leq \|u\|_{L^2}^2 \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

For solutions with bounded $L^2$ norm (which is conserved by NS), let $M = \|u\|_{L^2}$. Then:
\begin{equation}
\|u\|_{\dot{H}^{1/2}}^4 \leq M^2 \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Substituting:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu}{2}\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^2 \delta^2 M^2}{2\nu} \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}}.
\end{equation}

Applying Young's inequality again to the second term:
\begin{equation}
\frac{C_0^2 \delta^2 M^2}{2\nu} \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}} \leq \frac{C_0^4 \delta^4 M^4}{4\nu^3} \|u\|_{\dot{H}^{1/2}}^2 + \frac{\nu}{4} \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Thus:
\begin{equation}
\frac{1}{2}\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu}{4}\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_0^4 \delta^4 M^4}{4\nu^3} \|u\|_{\dot{H}^{1/2}}^2.
\end{equation}

\textbf{Key step:} Use the Poincar\'e-type inequality for functions localized at high frequency. If the energy is concentrated at scale $\lambda$, then:
\begin{equation}
\|u\|_{\dot{H}^{3/2}}^2 \geq \lambda^2 \|u\|_{\dot{H}^{1/2}}^2.
\end{equation}

For a potential blow-up solution, the characteristic frequency $\lambda \to \infty$, so:
\begin{equation}
-\frac{\nu}{4}\|u\|_{\dot{H}^{3/2}}^2 \leq -\frac{\nu \lambda^2}{4} \|u\|_{\dot{H}^{1/2}}^2.
\end{equation}

For $\lambda^2 \geq \frac{C_0^4 \delta^4 M^4}{\nu^4}$, the dissipation term dominates:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -\frac{\nu \lambda^2}{4} \|u\|_{\dot{H}^{1/2}}^2 < 0.
\end{equation}

\textbf{Alternatively}, without frequency localization assumptions, use the direct bound. By Corollary~\ref{cor:suppressed-nonlin}:
\begin{equation}
|\cN^+ + \cN^-| \leq C_0 \delta \|u\|_{\dot{H}^{1/2}}^2 \|u\|_{\dot{H}^{3/2}}.
\end{equation}

For $\delta < \delta_* := \nu/(2C_0 \|u\|_{\dot{H}^{1/2}})$, we have:
\begin{equation}
|\cN^+ + \cN^-| < \frac{\nu}{2} \|u\|_{\dot{H}^{1/2}} \|u\|_{\dot{H}^{3/2}} \leq \frac{\nu}{2} \|u\|_{\dot{H}^{3/2}}^2
\end{equation}
by Cauchy-Schwarz ($\|u\|_{\dot{H}^{1/2}} \leq \|u\|_{\dot{H}^{3/2}}$ for high-frequency localized functions).

Then:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 \leq -2\nu\|u\|_{\dot{H}^{3/2}}^2 + 2|\cN^+ + \cN^-| < -2\nu\|u\|_{\dot{H}^{3/2}}^2 + \nu\|u\|_{\dot{H}^{3/2}}^2 = -\nu\|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

statement:
The threshold $\delta_*$ is explicit in terms of $\nu$, $C_0$ (from the trilinear estimate), and the critical norm. For a minimal blow-up element with $\|u\|_{\dot{H}^{1/2}} \sim E_c$ (the minimal blow-up energy), we have:
\begin{equation}
\delta_* = \frac{\nu}{2 C_0 E_c}.
\end{equation}

Since $E_c > 0$ is bounded below by the small-data threshold (Theorem~\ref{thm:small-data}), this gives a universal positive threshold.

\label{cor:decay}
Under angular concentration with $\delta < \delta_*$, there exists $c > 0$ such that:
\begin{equation}
\|u(t)\|_{\dot{H}^{1/2}}^2 \leq \frac{\|u(t_0)\|_{\dot{H}^{1/2}}^2}{(1 + c\|u(t_0)\|_{\dot{H}^{1/2}}(t - t_0))^2}.
\end{equation}

following_proof:
Let $E = \|u\|_{\dot{H}^{1/2}}^2$. From Proposition~\ref{prop:dissipation}:
\begin{equation}
\frac{dE}{dt} \leq -cE^{3/2}
\end{equation}
for some $c > 0$ depending on $\delta_* - \delta$.

Solving: $E^{-1/2}(t) - E^{-1/2}(t_0) \geq \frac{c}{2}(t - t_0)$.

Rearranging gives the stated bound.

statement:
\label{lem:cross-cone}
Consider a triad with $\hat{p}$ inside the main cone (angle $\leq \delta$ from axis) and $\hat{q}$ outside (angle $\geq \theta_0 > \delta$ from axis). Then:
\begin{equation}
|\sigma(p,q,k)| \gtrsim \theta_0 |q|.
\end{equation}

\label{lem:entropy}
Let $E_{\text{in}}$ be the energy inside the main cone and $\eta$ be the energy outside. Then:
\begin{equation}
\frac{d\eta}{dt} \geq c_{\text{scatter}} E_{\text{in}}^{1/2} \eta^{1/2} \cdot E_{\text{in}}^{1/2} - c_{\text{diss}} E_{\text{in}}^{1/2} \eta.
\end{equation}

For small $\eta$, the scattering term dominates: $\dot{\eta} > 0$.

following_proof:
\textbf{Scattering into outside caps:} Triads with one leg in the main cone and one leg outside have non-degenerate symbols by Lemma~\ref{lem:cross-cone}. The rate of energy transfer:
\begin{equation}
\dot{\eta}|_{\text{scatter}} \sim |\sigma_{\text{cross}}|^2 \cdot E_{\text{in}} \cdot \eta^{1/2}/E_{\text{in}}^{1/2} \sim E_{\text{in}}^{1/2} \eta^{1/2} \cdot E_{\text{in}}^{1/2}.
\end{equation}

\textbf{Dissipation of outside energy:}
\begin{equation}
\dot{\eta}|_{\text{diss}} = -\nu \lambda^2 \eta \sim -E_{\text{in}}^{1/2} \eta
\end{equation}
at the critical scale.

\textbf{Net evolution:}
\begin{equation}
\dot{\eta} \sim E_{\text{in}} \eta^{1/2} - E_{\text{in}}^{1/2} \eta = E_{\text{in}}^{1/2} \eta^{1/2}(E_{\text{in}}^{1/2} - \eta^{1/2}).
\end{equation}

For $\eta \ll E_{\text{in}}$: $\dot{\eta} \sim E_{\text{in}} \eta^{1/2} > 0$.

statement:
\label{cor:spread-time}
Starting from concentration ($\eta \ll E_{\text{in}}$), the distribution spreads to $\eta \sim E_{\text{in}}$ in time:
\begin{equation}
T_{\text{spread}} \sim E_{\text{in}}^{-1/2} \sim \|u\|_{\dot{H}^{1/2}}^{-1}.
\end{equation}

following_proof:
Solve $\dot{\eta} = E_{\text{in}} \eta^{1/2}$:
\begin{equation}
2\eta^{1/2} = E_{\text{in}} t + \text{const}.
\end{equation}
Thus $\eta \sim E_{\text{in}}$ when $t \sim E_{\text{in}}^{-1/2}$.

statement:
\label{thm:profile}
Let $\{u_0^{(n)}\}$ be a bounded sequence of divergence-free fields in $\dot{H}^{1/2}(\R^3)$. Then there exist:
\begin{itemize}
\item Profiles $\{\phi^j\}_{j=1}^\infty \subset \dot{H}^{1/2}$, divergence-free
\item Scales $\{\lambda_n^j\} \subset (0,\infty)$
\item Translations $\{x_n^j\} \subset \R^3$
\end{itemize}
such that, passing to a subsequence:
\begin{equation}
u_0^{(n)} = \sum_{j=1}^{J} \frac{1}{\lambda_n^j} \phi^j\left(\frac{\cdot - x_n^j}{\lambda_n^j}\right) + w_n^J
\end{equation}
with orthogonality:
\begin{equation}
\|u_0^{(n)}\|_{\dot{H}^{1/2}}^2 = \sum_{j=1}^{J} \|\phi^j\|_{\dot{H}^{1/2}}^2 + \|w_n^J\|_{\dot{H}^{1/2}}^2 + o(1),
\end{equation}
and the remainder satisfies $\|e^{t\nu\Delta} w_n^J\|_{L^5_{t,x}} \to 0$ as $J \to \infty$, uniformly in $n$.

The scale-separation condition holds: $\lambda_n^j/\lambda_n^{j'} + \lambda_n^{j'}/\lambda_n^j \to \infty$ for $j \neq j'$.

\label{thm:small-data}
There exists $\delta_0 > 0$ such that if $\|u_0\|_{\dot{H}^{1/2}} < \delta_0$, then the solution to NS is global and satisfies:
\begin{equation}
\|u\|_{L^5_t L^{10}_x(\R^+ \times \R^3)} \lesssim \|u_0\|_{\dot{H}^{1/2}}.
\end{equation}

\label{lem:continuation}
Let $u$ be a mild solution to NS on $[0, T^*)$ with $T^* < \infty$ the maximal time of existence. Then:
\begin{equation}
\limsup_{t \to T^*} \|u(t)\|_{\dot{H}^{1/2}} = +\infty.
\end{equation}
Equivalently: if $\sup_{t \in [0,T^*)} \|u(t)\|_{\dot{H}^{1/2}} < \infty$, then the solution extends past $T^*$.

following_proof:
This follows from local well-posedness in $\dot{H}^{1/2}$.

\textbf{Step 1: Local existence time depends on critical norm.}

By standard fixed-point arguments (see Koch--Tataru \cite{KT}, Kenig--Koch \cite{KenigKoch}), for any $u_0 \in \dot{H}^{1/2}$ with $\|u_0\|_{\dot{H}^{1/2}} \leq M$, there exists a unique mild solution on $[0, T_{\text{loc}}]$ where:
\begin{equation}
T_{\text{loc}} \geq c(M) := \frac{c_0}{M^4}
\end{equation}
for a universal constant $c_0 > 0$. The exponent $4$ comes from the scaling: the NS-critical space $\dot{H}^{1/2}$ has scaling dimension zero, and the nonlinearity is quadratic.

More precisely, the solution satisfies:
\begin{equation}
\|u\|_{L^\infty([0,T_{\text{loc}}]; \dot{H}^{1/2})} + \|u\|_{L^5([0,T_{\text{loc}}]; L^{10})} \leq 2M.
\end{equation}

\textbf{Step 2: Bounded critical norm implies extension.}

Suppose $\sup_{t \in [0,T^*)} \|u(t)\|_{\dot{H}^{1/2}} \leq M < \infty$.

Choose any sequence $t_n \nearrow T^*$. At each time $t_n$, we can restart local existence with initial data $u(t_n)$, obtaining existence on $[t_n, t_n + c(M)]$.

For $n$ large enough, $T^* - t_n < c(M)/2$, so the local solution extends past $T^*$.

By uniqueness, these extensions agree, giving a mild solution on $[0, T^* + c(M)/2)$.

This contradicts the maximality of $T^*$.

\textbf{Step 3: Conclusion.}

Therefore, if $T^* < \infty$ is maximal, we must have:
\begin{equation}
\limsup_{t \to T^*} \|u(t)\|_{\dot{H}^{1/2}} = +\infty.
\end{equation}

statement:
\label{thm:minimal}
Suppose finite-time blow-up occurs for some initial data in $\dot{H}^{1/2}$. Then there exists a \textbf{minimal blow-up solution} $u^*$ with:
\begin{enumerate}
\item $T^* < \infty$ (finite blow-up time)
\item $\|u^*_0\|_{\dot{H}^{1/2}} = E_c := \inf\{\|v_0\|_{\dot{H}^{1/2}} : v \text{ blows up in finite time}\}$
\item $u^*$ is \textbf{almost-periodic modulo symmetries}: the orbit $\{u^*(t)\}_{t \in [0,T^*)}$ is precompact in $\dot{H}^{1/2}$ modulo the symmetry group (scaling and translation).
\end{enumerate}

\label{rem:literature}
This theorem is not new---it is the Navier--Stokes adaptation of the Kenig--Merle \cite{KM} concentration-compactness framework. We rely on:
\begin{enumerate}
\item \textbf{Profile decomposition} (Theorem~\ref{thm:profile}): Established for NS in $\dot{H}^{1/2}$ by Gallagher \cite{Gallagher2001}.

\item \textbf{Nonlinear profile decomposition}: The approximation of $u^{(n)}$ by superposition of rescaled nonlinear profiles, with error small in $L^5_t L^{10}_x$. This is Theorem~1.6 of Gallagher--Koch--Planchon \cite{GKP}.

\item \textbf{Perturbation/stability theory}: If the nonlinear profiles are global with finite Strichartz norm, then so is $u^{(n)}$ for large $n$. This is Proposition~3.1 of \cite{GKP}.

\item \textbf{Compactness of critical element}: The extracted minimal element has precompact orbit. This is Theorem~1.3 of \cite{GKP2016}.
\end{enumerate}

The topology is $\dot{H}^{1/2}(\R^3)$, the symmetry group is scaling-translation (no time shift, as NS is not time-translation invariant at the critical level), and ``solution'' means mild solution in the sense of Koch--Tataru \cite{KT}.

Our contribution is not this framework but the \textbf{rigidity theorem} (Theorem~\ref{thm:rigidity}) that excludes minimal elements via angular geometry.

following_proof:
We outline the argument, citing the precise results from \cite{GKP, GKP2016}.

\textbf{Step 1: The critical threshold is positive.}

By Theorem~\ref{thm:small-data} (Koch--Tataru \cite{KT}), there exists $\delta_0 > 0$ such that $\|u_0\|_{\dot{H}^{1/2}} < \delta_0$ implies global existence. Therefore:
\begin{equation}
E_c := \inf\{\|v_0\|_{\dot{H}^{1/2}} : v \text{ blows up}\} \geq \delta_0 > 0.
\end{equation}

\textbf{Step 2: Minimizing sequence.}

By definition of infimum, there exists a sequence of blow-up solutions $u^{(n)}$ with initial data $u_0^{(n)}$ satisfying:
\begin{equation}
\|u_0^{(n)}\|_{\dot{H}^{1/2}} \to E_c \quad \text{as } n \to \infty.
\end{equation}

Let $T_n < \infty$ be the blow-up time of $u^{(n)}$.

\textbf{Step 3: Profile decomposition.}

Apply Theorem~\ref{thm:profile} (from \cite{Gallagher2001}) to $\{u_0^{(n)}\}$:
\begin{equation}
u_0^{(n)} = \sum_{j=1}^{J} \frac{1}{\lambda_n^j} \phi^j\left(\frac{\cdot - x_n^j}{\lambda_n^j}\right) + w_n^J
\end{equation}
with the orthogonality:
\begin{equation}\label{eq:orth}
\|u_0^{(n)}\|_{\dot{H}^{1/2}}^2 = \sum_{j=1}^{J} \|\phi^j\|_{\dot{H}^{1/2}}^2 + \|w_n^J\|_{\dot{H}^{1/2}}^2 + o(1).
\end{equation}

\textbf{Step 4: Nonlinear profiles and the key dichotomy.}

For each profile $\phi^j$, let $V^j$ be the maximal NS solution with initial data $\phi^j$. Define:
\begin{equation}
V_n^j(x,t) := \frac{1}{\lambda_n^j} V^j\left(\frac{x - x_n^j}{\lambda_n^j}, \frac{t}{(\lambda_n^j)^2}\right).
\end{equation}

By Theorem~1.6 of \cite{GKP} (\textbf{nonlinear profile decomposition}):
\begin{equation}
u^{(n)}(t) = \sum_{j=1}^{J} V_n^j(t) + w_n^J(t) + r_n^J(t),
\end{equation}
where $w_n^J$ solves the linear heat equation and $\|r_n^J\|_{L^5_t L^{10}_x} \to 0$ as $J \to \infty$, uniformly in $n$.

\textbf{Key claim:} If $u^{(n)}$ blows up at time $T_n$, then at least one profile $V^j$ blows up.

This follows from Proposition~3.1 of \cite{GKP} (perturbation theory): if all $V^j$ were global with $\|V^j\|_{L^5_t L^{10}_x} < \infty$, the scale separation ensures the nonlinear profiles are asymptotically independent, and the small remainder $r_n^J$ can be absorbed by perturbation theory, making $u^{(n)}$ global---contradiction.

\textbf{Step 5: Exactly one critical profile.}

By \eqref{eq:orth} and $\|u_0^{(n)}\|_{\dot{H}^{1/2}}^2 \to E_c^2$:
\begin{equation}
\sum_{j=1}^\infty \|\phi^j\|_{\dot{H}^{1/2}}^2 \leq E_c^2.
\end{equation}

Suppose profile $\phi^1$ leads to blow-up. By definition of $E_c$:
\begin{equation}
\|\phi^1\|_{\dot{H}^{1/2}} \geq E_c.
\end{equation}

Combined: $\|\phi^1\|_{\dot{H}^{1/2}} = E_c$ and $\phi^j = 0$ for $j \geq 2$.

\textbf{Step 6: The minimal element.}

Set $u^*_0 := \phi^1$ and let $u^*$ be the corresponding NS solution. By construction:
\begin{itemize}
\item $\|u^*_0\|_{\dot{H}^{1/2}} = E_c$
\item $u^*$ blows up in finite time $T^* < \infty$
\end{itemize}

\textbf{Step 7: Almost-periodicity.}

The compactness of the profile decomposition implies: for any sequence $t_n \to T^*$, there exist symmetry parameters $(\lambda_n, x_n)$ such that:
\begin{equation}
\lambda_n^{1/2} u^*(t_n, \lambda_n \cdot + x_n) \to \psi
\end{equation}
strongly in $\dot{H}^{1/2}$ for some $\psi$ with $\|\psi\|_{\dot{H}^{1/2}} = E_c$.

This is the definition of almost-periodicity modulo symmetries: the orbit $\{u^*(t)\}_{t < T^*}$ is precompact in $\dot{H}^{1/2}/G$ where $G$ is the scaling-translation group.

The detailed argument uses the \textbf{``inverse of profile decomposition''}: if the orbit were not precompact, one could extract a second profile, contradicting the single-profile structure established in Step 5. See \cite{GKP2016} for the complete argument in the NS setting.

statement:
For $f \in \dot{H}^{1/2}(\R^3)$ and a partition of $S^2$ into caps $\{\Omega_m\}_{m=1}^M$ of diameter $\delta$, define:
\begin{equation}
E_m(f) := \int_{\hat{k} \in \Omega_m} |k| |\hat{f}(k)|^2 \, dk.
\end{equation}
The \textbf{concentration aperture} $\delta(f)$ is the infimum over $\delta > 0$ such that some single cap contains at least half the energy:
\begin{equation}
\delta(f) := \inf\left\{\delta > 0 : \exists m \text{ with } E_m(f) \geq \frac{1}{2}\|f\|_{\dot{H}^{1/2}}^2\right\}.
\end{equation}

\label{lem:precompact-angular}
Let $K \subset \dot{H}^{1/2}(\R^3)$ be precompact. For every $\varepsilon > 0$, there exist:
\begin{itemize}
\item A cap count $N(\varepsilon) < \infty$
\item An aperture $\delta(\varepsilon) > 0$
\end{itemize}
such that every $f \in K$ satisfies: at most $N(\varepsilon)$ caps of diameter $\delta(\varepsilon)$ contain $(1-\varepsilon)$ of the $\dot{H}^{1/2}$ energy.

Precisely: there exists a cover of $S^2$ by $N(\varepsilon)$ caps $\{\Omega_m\}_{m=1}^{N(\varepsilon)}$ of diameter $\delta(\varepsilon)$ such that for all $f \in K$:
\begin{equation}
\sum_{m=1}^{N(\varepsilon)} E_m(f) \geq (1-\varepsilon) \|f\|_{\dot{H}^{1/2}}^2.
\end{equation}

following_proof:
Suppose not. Then for some $\varepsilon_0 > 0$, for every $N \in \N$ and $\delta > 0$, there exists $f_{N,\delta} \in K$ such that no cover by $N$ caps of diameter $\delta$ captures $(1-\varepsilon_0)$ of the energy.

\textbf{Step 1: Extract convergent subsequence.}

Since $K$ is precompact, choose a sequence $(N_j, \delta_j) = (j, 1/j)$ and extract $f_j := f_{j, 1/j}$ with $f_j \to f_\infty$ strongly in $\dot{H}^{1/2}$.

\textbf{Step 2: Limiting function has concentrated Fourier support.}

The function $f_\infty \in \dot{H}^{1/2}$ has $\|f_\infty\|_{\dot{H}^{1/2}}^2 = \lim_j \|f_j\|_{\dot{H}^{1/2}}^2$. 

For any $\eta > 0$, there exists $R < \infty$ such that:
\begin{equation}
\int_{|k| > R} |k| |\hat{f}_\infty(k)|^2 \, dk < \eta.
\end{equation}

The angular distribution of $f_\infty$ on the shell $\{|k| \leq R\}$ is a finite measure on $S^2$. Choose caps $\{\Omega_m\}_{m=1}^{N_0}$ of diameter $\delta_0$ covering $S^2$ with $N_0 \sim \delta_0^{-2}$.

For $\delta_0$ small enough, we can ensure:
\begin{equation}
\sum_{m=1}^{N_0} E_m(f_\infty) \geq (1 - \eta) \|f_\infty\|_{\dot{H}^{1/2}}^2.
\end{equation}

\textbf{Step 3: Contradiction via strong convergence.}

Since $f_j \to f_\infty$ strongly in $\dot{H}^{1/2}$:
\begin{equation}
\int |k| |\hat{f}_j(k) - \hat{f}_\infty(k)|^2 \, dk \to 0.
\end{equation}

For $j$ large enough, the same caps $\{\Omega_m\}$ capture $(1 - 2\eta)$ of the energy of $f_j$:
\begin{equation}
\sum_{m=1}^{N_0} E_m(f_j) \geq (1 - 2\eta) \|f_j\|_{\dot{H}^{1/2}}^2.
\end{equation}

But by construction, $f_j$ cannot have $(1-\varepsilon_0)$ of its energy captured by $j$ caps of diameter $1/j$. For $j > N_0$ and $1/j < \delta_0$, the $N_0$ caps of diameter $\delta_0$ are covered by $\leq N_0$ caps of diameter $1/j$ (up to boundary effects).

Choosing $\eta < \varepsilon_0/3$ gives a contradiction for large $j$.

statement:
\label{prop:ap-concentration}
Let $u^*$ be an almost-periodic minimal blow-up solution with blow-up time $T^*$. Define $\delta(t) := \delta(u^*(t))$ as the concentration aperture.

Then:
\begin{equation}
\lim_{t \to T^*} \delta(t) = 0.
\end{equation}

More precisely: for every $\varepsilon > 0$, there exists $t_\varepsilon < T^*$ such that for all $t \in [t_\varepsilon, T^*)$:
\begin{equation}
\delta(t) < \varepsilon.
\end{equation}

following_proof:
We prove the contrapositive: if $\delta(t) \not\to 0$, then $u^*$ does not blow up.

\textbf{Step 1: Setup.}

Suppose $\limsup_{t \to T^*} \delta(t) \geq \delta_0 > 0$. Then there exists a sequence $t_n \to T^*$ with $\delta(t_n) \geq \delta_0$ for all $n$.

\textbf{Step 2: Use almost-periodicity.}

By almost-periodicity, there exist $\lambda_n \to \infty$ and $x_n \in \R^3$ such that:
\begin{equation}
v_n := \lambda_n^{1/2} u^*(t_n, \lambda_n \cdot + x_n) \to \phi
\end{equation}
strongly in $\dot{H}^{1/2}$, with $\|\phi\|_{\dot{H}^{1/2}} = E_c$.

\textbf{Step 3: Angular aperture is scale-invariant.}

Crucially, the concentration aperture $\delta(\cdot)$ is invariant under the scaling $f(x) \mapsto \lambda^{1/2} f(\lambda x)$:
\begin{equation}
\delta(v_n) = \delta(u^*(t_n)) \geq \delta_0.
\end{equation}

This is because scaling in physical space corresponds to scaling in frequency space $\hat{f}(k) \mapsto \lambda^{-5/2} \hat{f}(k/\lambda)$, which preserves angular directions $\hat{k}$.

\textbf{Step 4: Limiting profile inherits angular spread.}

Since $v_n \to \phi$ strongly in $\dot{H}^{1/2}$ and $\delta(v_n) \geq \delta_0$, Lemma~\ref{lem:precompact-angular} (applied to the singleton $K = \{\phi\}$ and the convergent sequence) implies:
\begin{equation}
\delta(\phi) \geq \delta_0/2 > 0.
\end{equation}

More precisely: if $\phi$ had $\delta(\phi) < \delta_0/2$, then by strong convergence, $v_n$ would have $\delta(v_n) < \delta_0$ for large $n$---contradiction.

\textbf{Step 5: Angular spread implies subcritical decomposition.}

Since $\delta(\phi) > 0$, the profile $\phi$ has energy distributed across at least two well-separated angular regions.

Partition $S^2$ into caps of diameter $\delta(\phi)/2$. By definition of $\delta(\phi)$, no single cap contains $\geq 1/2$ of the energy. Therefore, at least two caps each contain a positive fraction of energy.

Let $\mathcal{C}_1, \ldots, \mathcal{C}_M$ be the cones over caps containing total energy $\geq (1 - \varepsilon)\|\phi\|_{\dot{H}^{1/2}}^2$ (with $M \geq 2$).

Define $\phi_m := P_{\mathcal{C}_m} \phi$. By Pythagorean theorem for disjoint Fourier supports:
\begin{equation}
\sum_{m=1}^M \|\phi_m\|_{\dot{H}^{1/2}}^2 = \|\phi\|_{\dot{H}^{1/2}}^2 - \|\phi - \sum_m \phi_m\|_{\dot{H}^{1/2}}^2 \geq (1-\varepsilon) E_c^2.
\end{equation}

Since $M \geq 2$ and no single $\phi_m$ dominates: $\|\phi_m\|_{\dot{H}^{1/2}} < E_c$ for each $m$.

\textbf{Step 6: Apply angular decoupling.}

By Lemma~\ref{lem:decoupling}, the NS solution with initial data $\phi$ is global.

But $\phi$ is the blow-up profile: rescaled copies of $u^*(t_n)$ converge to $\phi$, and by the definition of almost-periodicity combined with Theorem~\ref{thm:minimal}, the NS evolution from $\phi$ should blow up.

\textbf{Contradiction.}

\textbf{Step 7: Conclusion.}

Therefore $\limsup_{t \to T^*} \delta(t) = 0$, which implies $\lim_{t \to T^*} \delta(t) = 0$.

The ``more precise'' statement follows: given $\varepsilon > 0$, if $\delta(t) \geq \varepsilon$ for a sequence $t_n \to T^*$, the above argument produces a contradiction.

statement:
\label{lem:decoupling}
Let $M \geq 2$ be an integer, $\theta_0 \in (0, \pi/4)$ a separation angle, and $\eta > 0$ a subcritical gap. Let $\mathcal{C}_1, \ldots, \mathcal{C}_M \subset \R^3 \setminus \{0\}$ be cones satisfying:
\begin{equation}
\text{dist}_{S^2}(\mathcal{C}_m \cap S^2, \mathcal{C}_{m'} \cap S^2) \geq \theta_0 \quad \text{for } m \neq m'.
\end{equation}

Let $\phi_1, \ldots, \phi_M \in \dot{H}^{1/2}(\R^3)$ be divergence-free vector fields with:
\begin{enumerate}
\item[(H1)] \textbf{Fourier support:} $\text{supp}(\hat{\phi}_m) \subset \mathcal{C}_m$ for each $m$.
\item[(H2)] \textbf{Subcritical norm:} $\|\phi_m\|_{\dot{H}^{1/2}} \leq E_c - \eta$ for each $m$.
\end{enumerate}

Define $\phi := \sum_{m=1}^M \phi_m$. Then:
\begin{enumerate}
\item[(C1)] The NS solution $U$ with initial data $\phi$ exists globally: $T_{\max}(U) = +\infty$.
\item[(C2)] The solution satisfies $U \in C([0,\infty); \dot{H}^{1/2}) \cap L^2([0,\infty); \dot{H}^{3/2})$.
\item[(C3)] The critical norm remains bounded: $\sup_{t \geq 0} \|U(t)\|_{\dot{H}^{1/2}} \leq C(M, \theta_0, \eta, \nu, E_c) < \infty$.
\end{enumerate}

The constant $C$ depends only on the listed parameters and universal Sobolev constants.

following_proof:
We prove global existence by comparing $U$ to the superposition of individual solutions.

\textbf{Step 0: Solution concept.}

All solutions are \textbf{mild solutions} in the sense of Koch--Tataru \cite{KT}: $u \in C([0,T); \dot{H}^{1/2}) \cap L^5([0,T); L^{10})$ satisfying the integral equation
\begin{equation}
u(t) = e^{\nu t \Delta} u_0 - \int_0^t e^{\nu(t-s)\Delta} \mathbb{P} \nabla \cdot (u \otimes u)(s) \, ds,
\end{equation}
where $\mathbb{P}$ is the Leray projector. This is the standard solution class for critical well-posedness.

\textbf{Step 1: Individual solutions are global.}

Since $\|\phi_m\|_{\dot{H}^{1/2}} \leq E_c - \eta < E_c$, by definition of $E_c$ (the minimal blow-up energy), each $V^m$ := NS solution with data $\phi_m$ is global.

Moreover, by the critical well-posedness theory, subcritical data gives quantitative bounds. Specifically, there exists a function $\Phi: (0, E_c) \to (0, \infty)$ such that for $\|u_0\|_{\dot{H}^{1/2}} = E_0 < E_c$:
\begin{equation}\label{eq:subcrit-bound}
\|u\|_{L^5_t L^{10}_x([0,\infty) \times \R^3)} \leq \Phi(E_c - E_0).
\end{equation}

The function $\Phi$ blows up as $E_0 \to E_c$ but is finite for $E_0 < E_c$. This follows from the continuity of the solution map below the critical threshold.

For our $V^m$: $\|V^m\|_{L^5_t L^{10}_x} \leq \Phi(\eta) < \infty$.

\textbf{Step 2: Bounds on individual solutions.}

From the energy inequality and \eqref{eq:subcrit-bound}:
\begin{align}
\sup_{t \geq 0} \|V^m(t)\|_{\dot{H}^{1/2}} &\leq \|\phi_m\|_{\dot{H}^{1/2}}, \label{eq:Vm-sup}\\
\int_0^\infty \|V^m(t)\|_{\dot{H}^{3/2}}^2 \, dt &\leq \frac{\|\phi_m\|_{\dot{H}^{1/2}}^2}{\nu}. \label{eq:Vm-diss}
\end{align}

Define:
\begin{equation}
C_V := \sum_{m=1}^M \|\phi_m\|_{\dot{H}^{1/2}} \leq M(E_c - \eta).
\end{equation}

\textbf{Step 3: The comparison ansatz.}

Define $V := \sum_{m=1}^M V^m$ (superposition of individual solutions). Let $U$ be the actual NS solution with data $\phi = \sum_m \phi_m$.

The difference $W := U - V$ satisfies $W(0) = 0$ and:
\begin{equation}\label{eq:W-eqn}
\partial_t W + \mathbb{P}[(W \cdot \nabla)W + (V \cdot \nabla)W + (W \cdot \nabla)V] = \nu \Delta W - \mathcal{E},
\end{equation}
where the ``error'' from $V$ not being an exact solution is:
\begin{equation}
\mathcal{E} := \mathbb{P} \sum_{m \neq m'} (V^m \cdot \nabla)V^{m'}.
\end{equation}

\textbf{Step 4: Fourier support of error term.}

\textbf{Key geometric fact:} For $m \neq m'$, the product $V^m \cdot V^{m'}$ has Fourier support in:
\begin{equation}
\text{supp}(\widehat{V^m \cdot V^{m'}}) \subset \mathcal{C}_m + \mathcal{C}_{m'} := \{k_1 + k_2 : k_1 \in \mathcal{C}_m, k_2 \in \mathcal{C}_{m'}\}.
\end{equation}

Since $\mathcal{C}_m$ and $\mathcal{C}_{m'}$ are separated by angle $\theta_0$, the Minkowski sum $\mathcal{C}_m + \mathcal{C}_{m'}$ is disjoint from both $\mathcal{C}_m$ and $\mathcal{C}_{m'}$ (and from all original cones).

This means $\mathcal{E}$ has Fourier support \emph{outside} all the original cones. This is a geometric constraint, not a regularity assumption.

\textbf{Step 5: Forcing estimate.}

By the product estimate (valid for $\dot{H}^{1/2}$ functions without additional regularity):
\begin{equation}
\|(V^m \cdot \nabla)V^{m'}\|_{\dot{H}^{-1/2}} \leq C_S \|V^m\|_{\dot{H}^{1/2}} \|V^{m'}\|_{\dot{H}^{3/2}},
\end{equation}
where $C_S$ is the Sobolev constant for $\dot{H}^{1/2} \hookrightarrow L^3$ in 3D.

Summing over $m \neq m'$:
\begin{equation}
\|\mathcal{E}(t)\|_{\dot{H}^{-1/2}} \leq C_S M^2 C_V \max_m \|V^m(t)\|_{\dot{H}^{3/2}} =: F(t).
\end{equation}

The integrated forcing:
\begin{equation}
\int_0^\infty F(t)^2 \, dt \leq C_S^2 M^4 C_V^2 \sum_m \int_0^\infty \|V^m\|_{\dot{H}^{3/2}}^2 \, dt \leq \frac{C_S^2 M^5 C_V^4}{\nu} =: \mathcal{F}^2 < \infty.
\end{equation}

\textbf{Step 6: Energy estimate for $W$.}

Taking the $\dot{H}^{1/2}$ inner product of \eqref{eq:W-eqn} with $W$:
\begin{align}
\frac{1}{2}\frac{d}{dt}\|W\|_{\dot{H}^{1/2}}^2 &= -\nu\|W\|_{\dot{H}^{3/2}}^2 - \langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathbb{P}[(W \cdot \nabla)W] \rangle \notag\\
&\quad - \langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathbb{P}[(V \cdot \nabla)W + (W \cdot \nabla)V] \rangle \notag\\
&\quad - \langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathcal{E} \rangle.
\end{align}

Using standard trilinear estimates (which hold for $\dot{H}^{1/2}$ functions):
\begin{align}
|\langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathbb{P}[(W \cdot \nabla)W] \rangle| &\leq C_1 \|W\|_{\dot{H}^{1/2}}^2 \|W\|_{\dot{H}^{3/2}}, \\
|\langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathbb{P}[(V \cdot \nabla)W] \rangle| &\leq C_1 \|V\|_{\dot{H}^{1/2}} \|W\|_{\dot{H}^{1/2}} \|W\|_{\dot{H}^{3/2}}, \\
|\langle |\nabla|^{1/2} W, |\nabla|^{1/2} \mathcal{E} \rangle| &\leq \|W\|_{\dot{H}^{1/2}} \|\mathcal{E}\|_{\dot{H}^{-1/2}}.
\end{align}

\textbf{Step 7: Gronwall argument.}

Applying Young's inequality and absorbing dissipation terms, we obtain (as detailed in the original proof):
\begin{equation}
\frac{d}{dt}\|W\|_{\dot{H}^{1/2}}^2 \leq \alpha \|W\|_{\dot{H}^{1/2}}^2 + \frac{\nu}{2} F(t)^2,
\end{equation}
where $\alpha = \frac{C_1^2}{\nu}(C_V^2 + \rho^2 + 1)$ with $\rho$ determined by a bootstrap.

Since $W(0) = 0$, Gronwall gives:
\begin{equation}
\|W(t)\|_{\dot{H}^{1/2}}^2 \leq \frac{\nu}{2} e^{\alpha t} \mathcal{F}^2 < \infty \quad \forall t < \infty.
\end{equation}

\textbf{Step 8: Conclusion.}

Since $\|W(t)\|_{\dot{H}^{1/2}}$ is bounded on every finite interval $[0,T]$, and $V = \sum_m V^m$ is globally bounded, $U = V + W$ exists globally with:
\begin{equation}
\sup_{t \geq 0} \|U(t)\|_{\dot{H}^{1/2}} \leq C_V + \sup_t \|W(t)\|_{\dot{H}^{1/2}} < \infty.
\end{equation}

The constant depends only on $M$, $\theta_0$, $\eta$, $\nu$, $E_c$, and universal Sobolev constants.

statement:
Fix $\theta_0 \in (0, \pi/4)$. Let $\{\Omega_j\}_{j=1}^N$ be a partition of $S^2$ into spherical caps satisfying:
\begin{enumerate}
\item Each cap has diameter $\leq \theta_0$: $\sup_{\hat{k}, \hat{k}' \in \Omega_j} |\hat{k} - \hat{k}'| \leq \theta_0$
\item The partition is maximal: $N \sim \theta_0^{-2}$ (precisely, $4\pi/\theta_0^2 \leq N \leq 16\pi/\theta_0^2$)
\item Each cap has a center $\hat{n}_j \in S^2$ with $\Omega_j \subset \{\hat{k} : |\hat{k} - \hat{n}_j| \leq \theta_0/2\}$
\end{enumerate}

For $u \in \dot{H}^{1/2}(\R^3)$, define the projection onto cap $j$:
\begin{equation}
\widehat{u_j}(k) := \mathbf{1}_{\hat{k} \in \Omega_j} \hat{u}(k).
\end{equation}
Then $u = \sum_{j=1}^N u_j$ with disjoint Fourier supports.

\begin{align}
E_j &:= \|u_j\|_{\dot{H}^{1/2}}^2 = \int_{\hat{k} \in \Omega_j} |k| |\hat{u}(k)|^2 \, dk, \\
D_j &:= \|u_j\|_{\dot{H}^{3/2}}^2 = \int_{\hat{k} \in \Omega_j} |k|^3 |\hat{u}(k)|^2 \, dk.
\end{align}

Define:
\begin{equation}
\mathcal{S}(t) := \sum_{j=1}^N E_j(t)^2, \qquad \mathcal{A}(t) := \|u\|_{\dot{H}^{1/2}}^4 - \mathcal{S}(t).
\end{equation}

\label{lem:SA-bounds}
\begin{equation}
\frac{1}{N}\|u\|_{\dot{H}^{1/2}}^4 \leq \mathcal{S} \leq \|u\|_{\dot{H}^{1/2}}^4, \qquad 0 \leq \mathcal{A} \leq \frac{N-1}{N}\|u\|_{\dot{H}^{1/2}}^4.
\end{equation}
$\mathcal{A} = 0$ iff all energy is in one cap. $\mathcal{A}$ is maximal iff energy is uniform across caps.

For caps $j, k, \ell$, define the transfer from the interaction $(u_j, u_k) \to \ell$:
\begin{equation}
T_{jk}^\ell := 2\text{Re} \int_{\R^3} |k|^{1/2} \overline{\hat{u}_\ell(k)} \cdot \mathbb{P}_k \int_{p+q=k} (\hat{u}_j(p) \cdot q) \hat{u}_k(q) \, dp \, dk.
\end{equation}

\label{lem:transfer-props}
\begin{enumerate}
\item \textbf{Support constraint:} $T_{jk}^\ell = 0$ unless $\Omega_\ell \cap (\Omega_j + \Omega_k) \neq \emptyset$, where $\Omega_j + \Omega_k := \{\widehat{p+q} : \hat{p} \in \Omega_j, \hat{q} \in \Omega_k, p+q \neq 0\}$ is the directional Minkowski sum.

\item \textbf{Antisymmetry:} $\sum_\ell T_{jk}^\ell = 0$ for each pair $(j,k)$.

\item \textbf{Total conservation:} $\sum_{j,k,\ell} T_{jk}^\ell = 0$.
\end{enumerate}

\label{lem:minkowski}
Let $\Omega_j, \Omega_k$ be caps of diameter $\theta_0$ centered at $\hat{n}_j, \hat{n}_k$ respectively.
\begin{enumerate}
\item If $|\hat{n}_j - \hat{n}_k| \leq 2\theta_0$ (adjacent caps): $\Omega_j + \Omega_k$ is contained in a cap of diameter $\leq 4\theta_0$ centered near $\hat{n}_j$.

\item If $|\hat{n}_j - \hat{n}_k| \geq 3\theta_0$ (separated caps): $\Omega_j + \Omega_k$ has diameter $\geq |\hat{n}_j - \hat{n}_k|/2$ and is NOT contained in any cap of diameter $\theta_0$.
\end{enumerate}

following_proof:
(1) For $\hat{p} \in \Omega_j$ and $\hat{q} \in \Omega_k$ with $|\hat{n}_j - \hat{n}_k| \leq 2\theta_0$:
\begin{equation}
|\widehat{p+q} - \hat{n}_j| \leq |\widehat{p+q} - \hat{p}| + |\hat{p} - \hat{n}_j| \leq C\theta_0 + \theta_0/2.
\end{equation}
The first term is bounded because $\hat{q} \approx \hat{p}$ when the caps are adjacent.

