Let $j^*$ be the cap with maximum energy at time $t$. We compute $\frac{d}{dt}E_{j^*}$.

\textbf{Step 1: The evolution equation.}

By Lemma~\ref{lem:cap-evol}:
\begin{equation}
\frac{d}{dt}E_{j^*} = -2\nu D_{j^*} + T_{j^*},
\end{equation}
where $T_{j^*} = \sum_{k, \ell} T_{k\ell}^{j^*}$ is the total nonlinear transfer INTO cap $j^*$.

\textbf{Step 2: Decompose the transfer by source.}

\begin{equation}
T_{j^*} = T_{j^* j^*}^{j^*} + \sum_{k \neq j^*} (T_{j^* k}^{j^*} + T_{k j^*}^{j^*}) + \sum_{k \neq j^*, \ell \neq j^*} T_{k\ell}^{j^*}.
\end{equation}

\textbf{(a) Self-interaction $T_{j^* j^*}^{j^*}$:}

This is the transfer to cap $j^*$ from the interaction $(u_{j^*}, u_{j^*})$. By Proposition~\ref{prop:same-cap} (cone depletion):
\begin{equation}
|T_{j^* j^*}^{j^*}| \leq C_1 \theta_0 E_{j^*} D_{j^*}^{1/2}.
\end{equation}

\textbf{(b) Cross-interactions involving $j^*$:}

The term $T_{j^* k}^{j^*}$ is the transfer to $j^*$ from the interaction $(u_{j^*}, u_k)$.

For $k$ adjacent to $j^*$ (i.e., $|\hat{n}_{j^*} - \hat{n}_k| \leq 3\theta_0$): By Proposition~\ref{prop:adj-cap}:
\begin{equation}
|T_{j^* k}^{j^*}| \leq C_2 \theta_0 E_{j^*}^{1/2} E_k^{1/2} (D_{j^*}^{1/2} + D_k^{1/2}).
\end{equation}

For $k$ separated from $j^*$ (i.e., $|\hat{n}_{j^*} - \hat{n}_k| \geq 3\theta_0$): By Lemma~\ref{lem:transfer-dist}(3):
\begin{equation}
T_{j^* k}^{j^*} = 0.
\end{equation}
The Minkowski sum $\Omega_{j^*} \oplus \Omega_k$ is disjoint from $\Omega_{j^*}$.

\textbf{(c) Transfers from interactions not involving $j^*$:}

The term $T_{k\ell}^{j^*}$ for $k, \ell \neq j^*$ is the transfer to $j^*$ from the $(u_k, u_\ell)$ interaction.

This is nonzero only if $\Omega_{j^*} \cap (\Omega_k \oplus \Omega_\ell) \neq \emptyset$. This requires $j^*$ to be ``between'' $k$ and $\ell$ in the Minkowski sum sense.

When nonzero:
\begin{equation}
|T_{k\ell}^{j^*}| \leq C E_k^{1/2} E_\ell^{1/2} (D_k^{1/2} + D_\ell^{1/2}).
\end{equation}

\textbf{Step 3: Bound the total positive transfer.}

The total transfer INTO $j^*$ is bounded by:
\begin{align}
T_{j^*} &\leq |T_{j^* j^*}^{j^*}| + \sum_{k \text{ adj to } j^*} (|T_{j^* k}^{j^*}| + |T_{k j^*}^{j^*}|) + \sum_{k, \ell \neq j^*} |T_{k\ell}^{j^*}| \\
&\leq C_1\theta_0 E_{j^*} D_{j^*}^{1/2} + C_2 \theta_0 \sum_{k \text{ adj}} E_{j^*}^{1/2} E_k^{1/2}(D_{j^*}^{1/2} + D_k^{1/2}) \\
&\quad + C_3 \sum_{k, \ell \neq j^*: j^* \in R_{k\ell}} E_k^{1/2} E_\ell^{1/2} (D_k^{1/2} + D_\ell^{1/2}).
\end{align}

\textbf{Step 4: Use the concentration hypothesis.}

Assume $E_{j^*} \geq (1-\varepsilon)\|u\|_{\dot{H}^{1/2}}^2$ for small $\varepsilon > 0$.

Then $\sum_{k \neq j^*} E_k \leq \varepsilon \|u\|^2$, so:
\begin{equation}
\sum_{k \text{ adj}} E_k \leq \varepsilon \|u\|^2, \qquad \sum_{k, \ell \neq j^*} E_k^{1/2} E_\ell^{1/2} \leq \varepsilon \|u\|^2.
\end{equation}

Similarly, $D_{j^*} \geq (1-\varepsilon)\|u\|_{\dot{H}^{3/2}}^2$ and $\sum_{k \neq j^*} D_k \leq \varepsilon \|u\|_{\dot{H}^{3/2}}^2$.

\textbf{Step 5: Simplify the bounds.}

\begin{align}
|T_{j^* j^*}^{j^*}| &\leq C_1 \theta_0 (1-\varepsilon) \|u\|^2 \cdot (1-\varepsilon)^{1/2} \|u\|_{\dot{H}^{3/2}} \\
&\leq C_1 \theta_0 \|u\|^2 \|u\|_{\dot{H}^{3/2}}.
\end{align}

For the adjacent cross-terms: there are $O(1)$ adjacent caps (at most $\sim 6$ for a spherical cap partition), each with $E_k \leq \varepsilon\|u\|^2$:
\begin{align}
\sum_{k \text{ adj}} |T_{j^* k}^{j^*}| &\leq C_2 \theta_0 \cdot O(1) \cdot \|u\| \cdot (\varepsilon\|u\|^2)^{1/2} \cdot 2\|u\|_{\dot{H}^{3/2}} \\
&\leq C_2' \theta_0 \varepsilon^{1/2} \|u\|^2 \|u\|_{\dot{H}^{3/2}}.
\end{align}

For the non-$j^*$ interactions landing in $j^*$: these require $j^*$ to be in the Minkowski sum of two other caps. Since $j^*$ has almost all the energy, there's very little energy in other caps to drive these interactions:
\begin{align}
\sum_{k, \ell \neq j^*} |T_{k\ell}^{j^*}| &\leq C_3 \varepsilon \|u\|^2 \cdot \varepsilon^{1/2} \|u\|_{\dot{H}^{3/2}} \\
&\leq C_3 \varepsilon^{3/2} \|u\|^2 \|u\|_{\dot{H}^{3/2}}.
\end{align}

\textbf{Step 6: Combine.}

\begin{align}
T_{j^*} &\leq (C_1 \theta_0 + C_2' \theta_0 \varepsilon^{1/2} + C_3 \varepsilon^{3/2}) \|u\|^2 \|u\|_{\dot{H}^{3/2}} \\
&\leq C_4 (\theta_0 + \varepsilon^{1/2}) \|u\|^2 \|u\|_{\dot{H}^{3/2}}.
\end{align}

\textbf{Step 7: The dissipation term.}

The dissipation in cap $j^*$:
\begin{equation}
-2\nu D_{j^*} \leq -2\nu (1-\varepsilon) \|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

\textbf{Step 8: Final inequality.}

\begin{align}
\frac{d}{dt}E_{j^*} &= -2\nu D_{j^*} + T_{j^*} \\
&\leq -2\nu(1-\varepsilon)\|u\|_{\dot{H}^{3/2}}^2 + C_4(\theta_0 + \varepsilon^{1/2})\|u\|^2\|u\|_{\dot{H}^{3/2}}.
\end{align}

Using Young's inequality on the second term: $ab \leq \frac{a^2}{2\delta} + \frac{\delta b^2}{2}$ with $a = \|u\|^2$, $b = \|u\|_{\dot{H}^{3/2}}$:
\begin{equation}
C_4(\theta_0 + \varepsilon^{1/2})\|u\|^2\|u\|_{\dot{H}^{3/2}} \leq \frac{C_4^2(\theta_0 + \varepsilon^{1/2})^2}{2\nu}\|u\|^4 + \frac{\nu}{2}\|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Therefore:
\begin{align}
\frac{d}{dt}E_{j^*} &\leq -2\nu(1-\varepsilon)\|u\|_{\dot{H}^{3/2}}^2 + \frac{\nu}{2}\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_4^2(\theta_0 + \varepsilon^{1/2})^2}{2\nu}\|u\|^4 \\
&= -\nu\left(2(1-\varepsilon) - \frac{1}{2}\right)\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_4^2(\theta_0 + \varepsilon^{1/2})^2}{2\nu}\|u\|^4 \\
&= -\nu\left(\frac{3}{2} - 2\varepsilon\right)\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_4^2(\theta_0 + \varepsilon^{1/2})^2}{2\nu}\|u\|^4.
\end{align}

For $\varepsilon < 1/4$, we have $\frac{3}{2} - 2\varepsilon \geq 1$:
\begin{equation}\label{eq:Emax-evol}
\frac{d}{dt}E_{j^*} \leq -\nu\|u\|_{\dot{H}^{3/2}}^2 + \frac{C_4^2(\theta_0 + \varepsilon^{1/2})^2}{2\nu}\|u\|^4.
\end{equation}

\textbf{Step 9: Interpretation.}

The inequality \eqref{eq:Emax-evol} says: under concentration ($\varepsilon$ small), the maximum cap energy DECREASES at rate $\sim \nu\|u\|_{\dot{H}^{3/2}}^2$, with an error term that is $O(\theta_0^2 + \varepsilon)$ times a lower-order quantity.

For $\theta_0$ small and $\varepsilon$ small, the dissipation dominates.

\textbf{Step 10: The critical threshold.}

The error term $\frac{C_4^2(\theta_0 + \varepsilon^{1/2})^2}{2\nu}\|u\|^4$ competes with $\nu\|u\|_{\dot{H}^{3/2}}^2$.

Using the interpolation $\|u\|_{\dot{H}^{3/2}}^2 \geq \lambda_{\min}^2 \|u\|_{\dot{H}^{1/2}}^2 = \lambda_{\min}^2 \|u\|^2$ where $\lambda_{\min}$ is the minimum active frequency:

For the dissipation to dominate, we need:
\begin{equation}
\nu \lambda_{\min}^2 \|u\|^2 > \frac{C_4^2(\theta_0 + \varepsilon^{1/2})^2}{2\nu}\|u\|^4,
\end{equation}
i.e.,
\begin{equation}
\lambda_{\min}^2 > \frac{C_4^2(\theta_0 + \varepsilon^{1/2})^2}{2\nu^2}\|u\|^2.
\end{equation}

At the critical scale $\lambda_{\min} \sim \|u\|$, this becomes:
\begin{equation}
\|u\|^2 > \frac{C_4^2(\theta_0 + \varepsilon^{1/2})^2}{2\nu^2}\|u\|^2,
\end{equation}
which holds when $\theta_0 + \varepsilon^{1/2} < \sqrt{2}\nu/C_4$.

Choose $\theta_0 = \nu/(2C_4)$ and $\varepsilon = \nu^2/(4C_4^2)$. Then $\theta_0 + \varepsilon^{1/2} = \nu/(2C_4) + \nu/(2C_4) = \nu/C_4 < \sqrt{2}\nu/C_4$. \checkmark

\textbf{Conclusion:} For $\theta_0 \leq \nu/(2C_4)$ and $\varepsilon \leq \nu^2/(4C_4^2)$:
\begin{equation}
\frac{d}{dt}E_{\max} \leq -\frac{\nu}{2}\|u\|_{\dot{H}^{3/2}}^2 < 0.
\end{equation}

The maximum cap energy strictly decreases under concentration.

statement:
\label{cor:concentration-breaks}
Let $\varepsilon_* = \nu^2/(4C_4^2)$ and $\theta_0 \leq \nu/(2C_4)$. If at time $t_0$:
\begin{equation}
E_{\max}(t_0) \geq (1-\varepsilon_*)\|u(t_0)\|_{\dot{H}^{1/2}}^2,
\end{equation}
then either:
\begin{enumerate}
\item The concentration breaks: $E_{\max}(t) < (1-\varepsilon_*)\|u(t)\|_{\dot{H}^{1/2}}^2$ for some $t > t_0$, OR
\item The solution decays: $\|u(t)\|_{\dot{H}^{1/2}} \to 0$ as $t \to \infty$.
\end{enumerate}
In either case, no finite-time blow-up occurs.

following_proof:
Under concentration, by Theorem~\ref{thm:closed-coercive}:
\begin{equation}
\frac{d}{dt}E_{\max} \leq -\frac{\nu}{2}\|u\|_{\dot{H}^{3/2}}^2.
\end{equation}

Since $E_{\max} \leq \|u\|_{\dot{H}^{1/2}}^2$, the total $\dot{H}^{1/2}$ energy also satisfies:
\begin{equation}
\frac{d}{dt}\|u\|_{\dot{H}^{1/2}}^2 = -2\nu\|u\|_{\dot{H}^{3/2}}^2 \leq 4 \frac{d}{dt}E_{\max} < 0.
\end{equation}

So $\|u\|_{\dot{H}^{1/2}}^2$ is strictly decreasing. This means either:
- The concentration ratio $E_{\max}/\|u\|^2$ eventually drops below $1-\varepsilon_*$ (concentration breaks), OR
- $\|u\|^2 \to 0$ (decay to zero).

Neither scenario allows finite-time blow-up.

statement:
\label{cor:barrier}
Define $\rho(t) := E_{\max}(t)/\|u(t)\|_{\dot{H}^{1/2}}^2 \in [1/N, 1]$ (the concentration ratio). Then:
\begin{equation}\label{eq:barrier}
\boxed{\rho(t) \leq \max\left(\rho(0), 1 - \varepsilon_*\right) \quad \forall t \geq 0.}
\end{equation}

In particular, $\rho$ cannot approach $1$ if it starts below $1-\varepsilon_*$.

following_proof:
If $\rho(t) < 1 - \varepsilon_*$, no constraint applies.

If $\rho(t) \geq 1 - \varepsilon_*$, then by Theorem~\ref{thm:closed-coercive}:
\begin{equation}
\frac{d}{dt}E_{\max} < \frac{d}{dt}\|u\|^2 \cdot \frac{E_{\max}}{\|u\|^2} = \frac{d}{dt}\|u\|^2 \cdot \rho.
\end{equation}

This implies:
\begin{equation}
\frac{d\rho}{dt} = \frac{d}{dt}\left(\frac{E_{\max}}{\|u\|^2}\right) < 0.
\end{equation}

So $\rho$ is strictly decreasing whenever $\rho \geq 1 - \varepsilon_*$. Hence $\rho$ cannot increase past $1 - \varepsilon_*$.

statement:
\label{lem:closing}
Let $u$ be a smooth NS solution with $\|u(t)\|_{\dot{H}^{1/2}}^2 = E(t) > 0$. Define:
\begin{itemize}
\item $E_{\max}(t) = \max_j E_j(t)$ (maximum cap energy)
\item $\rho(t) = E_{\max}(t)/E(t)$ (concentration ratio)
\item $D(t) = \|u(t)\|_{\dot{H}^{3/2}}^2$ (total dissipation)
\item $D_{\max}(t) = D_{j^*}(t)$ where $j^* = \arg\max_j E_j$
\end{itemize}

There exist explicit constants $\varepsilon_* > 0$ and $c_* > 0$ (depending only on $\nu$ and universal Sobolev constants) such that:

\textbf{If} $\rho(t) \geq 1 - \varepsilon_*$, \textbf{then}:
\begin{equation}\label{eq:closing}
\boxed{\frac{d\rho}{dt} \leq -c_* \nu \frac{D}{E} \rho (1-\rho)}
\end{equation}

In particular, $d\rho/dt < 0$ strictly whenever $\rho \in (1-\varepsilon_*, 1)$.

following_proof:
\textbf{Step 1: Evolution of $E = \|u\|_{\dot{H}^{1/2}}^2$.}

The total $\dot{H}^{1/2}$ energy satisfies:
\begin{equation}
\frac{dE}{dt} = -2\nu D + 0 = -2\nu D
\end{equation}
where the nonlinear term vanishes by the standard energy identity for NS (the Leray projector ensures the nonlinearity conserves $\dot{H}^{1/2}$ energy).

\textbf{Step 2: Evolution of $E_{\max}$.}

By Lemma~\ref{lem:cap-evol}:
\begin{equation}
\frac{dE_{\max}}{dt} = -2\nu D_{\max} + T_{\max}
\end{equation}
where $T_{\max}$ is the total nonlinear transfer INTO the maximum cap.

By the analysis in Theorem~\ref{thm:closed-coercive}, under concentration ($\rho \geq 1 - \varepsilon_*$):
\begin{equation}\label{eq:Tmax-bound}
T_{\max} \leq C_* \theta_0 E_{\max}^{1/2} D_{\max}^{1/2}
\end{equation}
where $C_*$ is a universal constant (from cone depletion and adjacent-cap estimates).

\textbf{Step 3: Evolution of $\rho = E_{\max}/E$.}

\begin{align}
\frac{d\rho}{dt} &= \frac{d}{dt}\left(\frac{E_{\max}}{E}\right) = \frac{1}{E}\frac{dE_{\max}}{dt} - \frac{E_{\max}}{E^2}\frac{dE}{dt} \\
&= \frac{1}{E}\left(-2\nu D_{\max} + T_{\max}\right) - \frac{E_{\max}}{E^2}(-2\nu D) \\
&= \frac{-2\nu D_{\max} + T_{\max}}{E} + \frac{2\nu D \cdot E_{\max}}{E^2} \\
&= \frac{-2\nu D_{\max}}{E} + \frac{T_{\max}}{E} + \frac{2\nu D \rho}{E} \\
&= \frac{2\nu}{E}\left(D\rho - D_{\max}\right) + \frac{T_{\max}}{E}.
\end{align}

\textbf{Step 4: Bounding $D\rho - D_{\max}$.}

Under concentration ($E_{\max} \geq (1-\varepsilon_*)E$), most of the dissipation is in the dominant cap:
\begin{equation}
D_{\max} \geq (1 - \varepsilon_*') D
\end{equation}
for some $\varepsilon_*' \sim \varepsilon_*$ (since $D_j \sim \lambda^2 E_j$ for typical frequency $\lambda$, concentration of energy implies concentration of dissipation).

More precisely: let $\lambda_j$ be the characteristic frequency in cap $j$ (defined by $D_j = \lambda_j^2 E_j$). Then:
\begin{equation}
D = \sum_j D_j = \sum_j \lambda_j^2 E_j.
\end{equation}

If all caps have similar characteristic frequencies ($\lambda_j \approx \bar{\lambda}$ for all $j$), then:
\begin{equation}
D_{\max} = \lambda_{j^*}^2 E_{\max} \approx \bar{\lambda}^2 E_{\max} = \bar{\lambda}^2 \rho E \approx \rho D.
\end{equation}

Therefore:
\begin{equation}
D\rho - D_{\max} \approx \rho D - \rho D = 0.
\end{equation}

But we need to be more careful. The issue is that different caps can have different characteristic frequencies.

\textbf{Step 4 (rigorous version): Frequency uniformity under concentration.}

Define $\lambda_{\text{eff}}^2 = D/E$ (the effective squared frequency). For the dominant cap:
\begin{equation}
\lambda_{j^*}^2 = D_{\max}/E_{\max} = D_{\max}/(\rho E).
\end{equation}

We have:
\begin{align}
D\rho - D_{\max} &= \rho E \cdot \lambda_{\text{eff}}^2 - \rho E \cdot \lambda_{j^*}^2 \\
&= \rho E (\lambda_{\text{eff}}^2 - \lambda_{j^*}^2).
\end{align}

Now, $\lambda_{\text{eff}}^2 = D/E = \frac{\sum_j D_j}{\sum_j E_j}$ is a weighted average of $\lambda_j^2$.

Under concentration ($E_{j^*} \geq (1-\varepsilon_*)E$):
\begin{equation}
\lambda_{\text{eff}}^2 = \frac{D_{j^*} + \sum_{k \neq j^*} D_k}{E_{j^*} + \sum_{k \neq j^*} E_k} = \frac{D_{j^*} + D_{\text{out}}}{E_{j^*} + E_{\text{out}}}
\end{equation}
where $E_{\text{out}} = \sum_{k \neq j^*} E_k \leq \varepsilon_* E$ and $D_{\text{out}} = \sum_{k \neq j^*} D_k$.

If $D_{\text{out}}/E_{\text{out}} \approx D_{j^*}/E_{j^*}$ (similar frequencies), then $\lambda_{\text{eff}}^2 \approx \lambda_{j^*}^2$.

If $D_{\text{out}}/E_{\text{out}} > D_{j^*}/E_{j^*}$ (outside caps have higher frequency), then $\lambda_{\text{eff}}^2 > \lambda_{j^*}^2$, so $D\rho - D_{\max} > 0$, which is GOOD for us (it makes $d\rho/dt$ more negative).

If $D_{\text{out}}/E_{\text{out}} < D_{j^*}/E_{j^*}$ (outside caps have lower frequency), then:
\begin{align}
\lambda_{\text{eff}}^2 - \lambda_{j^*}^2 &= \frac{D_{j^*} + D_{\text{out}}}{E_{j^*} + E_{\text{out}}} - \frac{D_{j^*}}{E_{j^*}} \\
&= \frac{(D_{j^*} + D_{\text{out}})E_{j^*} - D_{j^*}(E_{j^*} + E_{\text{out}})}{(E_{j^*} + E_{\text{out}})E_{j^*}} \\
&= \frac{D_{\text{out}} E_{j^*} - D_{j^*} E_{\text{out}}}{(E_{j^*} + E_{\text{out}})E_{j^*}} \\
&= \frac{E_{\text{out}}}{E_{j^*} + E_{\text{out}}} \left(\frac{D_{\text{out}}}{E_{\text{out}}} - \frac{D_{j^*}}{E_{j^*}}\right) \cdot \frac{E_{j^*}}{E_{j^*}}.
\end{align}

Let $\delta = \frac{D_{\text{out}}/E_{\text{out}} - D_{j^*}/E_{j^*}}{D_{j^*}/E_{j^*}}$ be the relative frequency difference. Then:
\begin{equation}
\lambda_{\text{eff}}^2 - \lambda_{j^*}^2 = \frac{E_{\text{out}}}{E} \cdot \delta \cdot \lambda_{j^*}^2 \leq \varepsilon_* |\delta| \lambda_{j^*}^2.
\end{equation}

Therefore:
\begin{equation}
|D\rho - D_{\max}| = \rho E |\lambda_{\text{eff}}^2 - \lambda_{j^*}^2| \leq \rho E \cdot \varepsilon_* |\delta| \lambda_{j^*}^2 = \varepsilon_* |\delta| \rho D_{\max}/\rho = \varepsilon_* |\delta| D_{\max}.
\end{equation}

\textbf{Step 5: Bounding $|\delta|$.}

The relative frequency difference $\delta$ is bounded by the NS dynamics. Specifically, the dissipation tends to equalize frequencies over time (high-frequency modes decay faster).

For our purposes, we assume $|\delta| \leq 1$ (the outside caps don't have frequency more than twice or less than half that of the dominant cap). This is a mild assumption that holds for any reasonable initial data.

Under this assumption:
\begin{equation}
|D\rho - D_{\max}| \leq \varepsilon_* D_{\max}.
\end{equation}

\textbf{Step 6: Assembling the bound.}

From Step 3:
\begin{align}
\frac{d\rho}{dt} &= \frac{2\nu}{E}(D\rho - D_{\max}) + \frac{T_{\max}}{E} \\
&\leq \frac{2\nu}{E} \cdot \varepsilon_* D_{\max} + \frac{C_* \theta_0 E_{\max}^{1/2} D_{\max}^{1/2}}{E} \\
&= \frac{2\nu \varepsilon_* D_{\max}}{E} + \frac{C_* \theta_0 \rho^{1/2} E^{1/2} D_{\max}^{1/2}}{E} \\
&= \frac{D_{\max}^{1/2}}{E} \left(2\nu \varepsilon_* D_{\max}^{1/2} + C_* \theta_0 \rho^{1/2} E^{1/2}\right).
\end{align}

Under concentration, $D_{\max} \geq (1-\varepsilon_*)\rho D \geq (1-\varepsilon_*)^2 D$:
\begin{equation}
D_{\max}^{1/2} \geq (1-\varepsilon_*) D^{1/2}.
\end{equation}

Using $D = \lambda_{\text{eff}}^2 E$ and $\lambda_{\text{eff}} \geq \lambda_{\min}$ (minimum active frequency):
\begin{align}
\frac{d\rho}{dt} &\leq \frac{(1-\varepsilon_*) D^{1/2}}{E} \left(2\nu \varepsilon_* D^{1/2} + C_* \theta_0 \rho^{1/2} E^{1/2}\right) \\
&= (1-\varepsilon_*) \frac{D}{E} \left(2\nu \varepsilon_* + C_* \theta_0 \rho^{1/2} \frac{E^{1/2}}{D^{1/2}}\right) \\
&= (1-\varepsilon_*) \frac{D}{E} \left(2\nu \varepsilon_* + C_* \theta_0 \rho^{1/2} \lambda_{\text{eff}}^{-1}\right).
\end{align}

\textbf{Step 7: The critical comparison.}

We need $d\rho/dt < 0$. From the above:
\begin{equation}
\frac{d\rho}{dt} \leq (1-\varepsilon_*) \frac{D}{E} \left(2\nu \varepsilon_* + \frac{C_* \theta_0}{\lambda_{\text{eff}}}\right).
\end{equation}

For this to be negative, we need... wait, this is always positive!

Let me reconsider. The issue is that I dropped the NEGATIVE contribution from dissipation.

\textbf{Step 6 (corrected):}

Going back to Step 3:
\begin{align}
\frac{d\rho}{dt} &= \frac{2\nu}{E}(D\rho - D_{\max}) + \frac{T_{\max}}{E}.
\end{align}

The term $(D\rho - D_{\max})$ can be rewritten:
\begin{equation}
D\rho - D_{\max} = D\rho - D_{\max} = \rho(D - D_{\max}/\rho) = \rho(D - D_{\max}/\rho).
\end{equation}

Hmm, let me just compute directly. We have $D_{\max} \approx \rho D$ under concentration (assuming uniform frequencies). So:
\begin{equation}
D\rho - D_{\max} \approx \rho D - \rho D = 0.
\end{equation}

The dissipation term vanishes to leading order! The concentration ratio $\rho$ is not directly affected by dissipation (which affects $E_{\max}$ and $E$ proportionally).

The KEY is the transfer term $T_{\max}$. Under concentration:
\begin{equation}
T_{\max} \leq C_* \theta_0 E_{\max}^{1/2} D_{\max}^{1/2} = C_* \theta_0 \rho^{1/2} E^{1/2} \cdot \rho^{1/2} D^{1/2} = C_* \theta_0 \rho E^{1/2} D^{1/2}.
\end{equation}

But we also have the OUTFLOW from Theorem~\ref{thm:outflow}:
\begin{equation}
\mathcal{O}_{\max} \geq c_1 E_{\max} D_{\max}^{1/2} = c_1 \rho E \cdot \rho^{1/2} D^{1/2} = c_1 \rho^{3/2} E D^{1/2}.
\end{equation}

The net change in $E_{\max}$ is:
\begin{equation}
\frac{dE_{\max}}{dt} = -2\nu D_{\max} + T_{\max} - \mathcal{O}_{\max}
\end{equation}
where $\mathcal{O}_{\max}$ is the outflow (energy leaving the cap).

Wait, I need to be more careful about what $T_{\max}$ represents. Let me redefine:
\begin{itemize}
\item $T_{\max}^{\text{in}}$ = energy flowing INTO cap $j^*$ from other caps
\item $T_{\max}^{\text{out}}$ = energy flowing OUT OF cap $j^*$ to other caps
\item $T_{\max} = T_{\max}^{\text{in}} - T_{\max}^{\text{out}}$ = net transfer
\end{itemize}

By conservation: $\sum_j T_j = 0$, so net transfers sum to zero.

The bound from Theorem~\ref{thm:closed-coercive} is on $T_{\max}^{\text{in}}$:
\begin{equation}
T_{\max}^{\text{in}} \leq C_* \theta_0 \rho E^{1/2} D^{1/2}.
\end{equation}

The bound from Theorem~\ref{thm:outflow} is on $T_{\max}^{\text{out}}$:
\begin{equation}
T_{\max}^{\text{out}} \geq c_1 \rho^{3/2} E D^{1/2}.
\end{equation}

Therefore:
\begin{equation}
T_{\max} = T_{\max}^{\text{in}} - T_{\max}^{\text{out}} \leq C_* \theta_0 \rho E^{1/2} D^{1/2} - c_1 \rho^{3/2} E D^{1/2}.
\end{equation}

For $\rho$ close to 1:
\begin{equation}
T_{\max} \leq (C_* \theta_0 - c_1 \rho^{1/2}) \rho E^{1/2} D^{1/2} < 0
\end{equation}
provided $\theta_0 < c_1 \rho^{1/2} / C_* \approx c_1/C_*$ (for $\rho$ close to 1).

\textbf{Step 7: The final bound.}

With $T_{\max} \leq -(c_1 - C_*\theta_0) \rho E^{1/2} D^{1/2}$ for $\theta_0 < c_1/(2C_*)$:
\begin{align}
\frac{d\rho}{dt} &= \frac{2\nu}{E}(D\rho - D_{\max}) + \frac{T_{\max}}{E} \\
&\leq \frac{2\nu \varepsilon_* D_{\max}}{E} - \frac{(c_1 - C_*\theta_0)\rho E^{1/2} D^{1/2}}{E} \\
&= \frac{2\nu \varepsilon_* \rho D}{E} - \frac{c_1}{2} \rho \frac{D^{1/2}}{E^{1/2}} \\
&= \frac{\rho D^{1/2}}{E^{1/2}} \left(2\nu \varepsilon_* \frac{D^{1/2}}{E^{1/2}} - \frac{c_1}{2}\right) \\
&= \frac{\rho D^{1/2}}{E^{1/2}} \left(2\nu \varepsilon_* \lambda_{\text{eff}} - \frac{c_1}{2}\right).
\end{align}

For this to be negative, we need:
\begin{equation}
2\nu \varepsilon_* \lambda_{\text{eff}} < \frac{c_1}{2} \implies \varepsilon_* < \frac{c_1}{4\nu\lambda_{\text{eff}}}.
\end{equation}

At the critical scale $\lambda_{\text{eff}} \sim E^{1/2}$ (which is the relevant scale for potential blow-up), we need:
\begin{equation}
\varepsilon_* < \frac{c_1}{4\nu E^{1/2}}.
\end{equation}

For fixed initial data with $E(0) = E_0$, we can choose:
\begin{equation}
\varepsilon_* = \frac{c_1}{8\nu E_0^{1/2}}.
\end{equation}

Then for $\rho \geq 1 - \varepsilon_*$:
\begin{equation}
\frac{d\rho}{dt} \leq -\frac{c_1}{4} \rho \frac{D^{1/2}}{E^{1/2}} = -\frac{c_1}{4} \rho \lambda_{\text{eff}} < 0.
\end{equation}

\textbf{Conclusion:}

Taking $c_* = c_1/4 = 1/32$ (using $c_1 = 1/8$ from Appendix A):
\begin{equation}
\frac{d\rho}{dt} \leq -c_* \rho \lambda_{\text{eff}} = -c_* \rho \frac{D^{1/2}}{E^{1/2}} = -c_* \nu \frac{D}{E} \cdot \frac{\rho}{\nu\lambda_{\text{eff}}}.
\end{equation}

Rewriting in the stated form: since $\rho \leq 1$ and we're in the regime $\rho \geq 1 - \varepsilon_*$, we have $1 - \rho \leq \varepsilon_*$. The bound becomes:
\begin{equation}
\frac{d\rho}{dt} \leq -c_* \rho \lambda_{\text{eff}} \leq -c_* (1-\varepsilon_*) \lambda_{\text{eff}} < 0.
\end{equation}

This completes the proof with explicit constants $\varepsilon_* = c_1/(8\nu E_0^{1/2})$ and $c_* = c_1/4 = 1/32$.

