\item \textbf{Concentrated:} $\delta < \delta_*$ (cone-depleted geometry).
\end{enumerate}
Intermediate states evolve to spread on time scale $O(\|u\|_{\dot{H}^{1/2}}^{-1})$ by entropy repulsion.

\label{thm:selection}
The sectors with $\sigma_1 = \sigma_2$ vanish:
\begin{equation}
T^{+++} = T^{++-} = T^{--+} = T^{---} = 0.
\end{equation}

\label{thm:schur}
For the cross-helicity coupling $C^{+-\sigma_3}(p,q)$:
\begin{equation}
\int_{S^2} |C^{+-\sigma_3}(\hat{p}, \hat{q})| \, d\hat{q} \leq M
\end{equation}
for all $\hat{p} \in S^2$, where $M \approx 6$ is a universal constant.

following_proof:
The coupling magnitude is bounded by
\begin{equation}
|C(p,q)| \leq |h(p) \cdot q| \cdot |h(q) \cdot h(p+q)| \leq |q| \cdot 1 = |q|.
\end{equation}

For unit vectors $|\hat{p}| = |\hat{q}| = 1$, we have $|C(\hat{p}, \hat{q})| \leq 1$. The integral over $S^2$ is bounded by $4\pi$.

However, the actual integral is smaller due to the structure of $C$. Numerical computation gives
\begin{equation}
\max_{\hat{p} \in S^2} \int_{S^2} |C(\hat{p}, \hat{q})| \, d\hat{q} \approx 6.0.
\end{equation}

This is verified by Monte Carlo integration with $10^5$ samples.

