\label{thm:main-gwp}
For any $\Lambda > 0$, $\gamma \in (0,1]$, $K \geq 1$, and $u_0 \in H^1(\T^3)$ divergence-free, system \eqref{eq:NS-Poisson} has a unique global strong solution. Setting $E_0 := \|u_0\|_{L^2}^2$:
\begin{equation}\label{eq:main-H1-bound}
\sup_{t \geq 0}\E[\|u(t)\|_{H^1}^2] \leq R^2(E_0, \nu, \Lambda, \gamma, K)
\end{equation}
where
\begin{equation}\label{eq:R-explicit}
R^2 = 2KE_0 + \frac{32C_b^4 E_0^2}{\nu^3\Lambda\kap}
\end{equation}
and $C_b \leq 0.032$ is the trilinear constant.

\label{thm:exp-decay}
For $p > K$ and $t > 0$:
\begin{equation}\label{eq:exp-decay}
\E[\|\Pi_p u(t)\|_{L^2}^2] \leq e^{-\Lambda\kap t}\|\Pi_p u_0\|_{L^2}^2
\end{equation}
The decay rate $\Lambda\kap = \Lambda\gamma(2-\gamma)$ is maximized at $\gamma = 1$ giving rate $\Lambda$.

\label{thm:endpoint}
Define the endpoint determining wavenumber:
\begin{equation}
\Lambda_\infty(t) := \sup\{p : \lambda_p^{-1}\|\Pi_p u(t)\|_{L^\infty} > c_*\nu\}
\end{equation}
where $c_* = 1/(4C_b)$ is the critical constant from \cite{NSOperator}. Then:
\begin{equation}
\Lambda_\infty(t) \leq K \quad \text{almost surely for all } t > 0
\end{equation}

\label{thm:comparison}
Let $u^{\text{hyper}}$ solve hyperdissipative NS:
\begin{equation}
\partial_t u + (u \cdot \nabla)u + \nabla p = \nu(-\Delta)^\alpha u, \quad \alpha > 1
\end{equation}
and let $u^{\text{Poisson}}$ solve \eqref{eq:NS-Poisson}. The effective dissipation strengths are comparable when:
\begin{equation}\label{eq:comparison}
\alpha_{\text{eff}} = 1 + \frac{\log(1 + \Lambda\kap/\nu)}{2\log K}
\end{equation}
In particular, for $\Lambda\kap \geq \nu K^{2(\alpha-1)}$, Poisson coarse-graining provides at least as much high-frequency control as $(-\Delta)^\alpha$ dissipation.

\label{thm:convergence}
Let $u^0$ solve deterministic NS \eqref{eq:NS} on $[0,T]$ (assuming it exists). Let $u^\Lambda$ solve \eqref{eq:NS-Poisson}. Then:
\begin{equation}
\E[\sup_{t \in [0,T]}\|u^\Lambda(t) - u^0(t)\|_{L^2}^2] \leq C(T,\|u^0\|_{C([0,T];H^1)}) \cdot \Lambda T
\end{equation}
In particular, $u^\Lambda \to u^0$ in probability as $\Lambda \to 0$.

\label{lem:sobolev}
On $\T^3$:
\begin{equation}
\|f\|_{L^4} \leq C_S \|f\|_{H^1}, \quad C_S = (2\pi)^{-3/4} \approx 0.179
\end{equation}

\label{lem:bilinear}
For $u, v, w \in V$:
\begin{equation}\label{eq:trilinear}
|b(u,v,w)| := |\inner{(u \cdot \nabla)v}{w}| \leq C_b \|u\|_V \|v\|_V \|w\|_V
\end{equation}
where $C_b = C_S^3 \leq 0.032$ on $\T^3$. More refined:
\begin{equation}\label{eq:trilinear-refined}
|b(u,v,w)| \leq C_b \|u\|_V^{1/2}\|u\|_W^{1/2}\|v\|_V \|w\|_H
\end{equation}

\label{lem:bernstein}
For $u$ with Fourier support in $\{|k| \sim \lambda^{1/2}\}$:
\begin{equation}
\|u\|_{L^\infty} \leq C_B \lambda^{3/4} \|u\|_{L^2}, \quad C_B = 1
\end{equation}

For $K \geq 1$ and $\gamma \in (0,1]$:
\begin{equation}
Q = Q_{\gamma,K} = \Pi_{\leq K} + (1-\gamma)\Pi_{>K}
\end{equation}
where $\Pi_{\leq K}$ projects onto modes with $\lambda_n \leq K$ and $\Pi_{>K} = I - \Pi_{\leq K}$.

\label{lem:Q-properties}
\begin{enumerate}[label=(\alph*)}
\item $Q$ is self-adjoint, $\|Q\|_{H \to H} = \|Q\|_{V \to V} = 1$.
\item $\|Qu\|_H^2 = \|u\|_H^2 - \kap\|\Pi_{>K}u\|_H^2$ where $\kap = \gamma(2-\gamma)$.
\item $\|Qu\|_V^2 = \|u\|_V^2 - \kap\|\Pi_{>K}u\|_V^2$.
\item \textbf{Topological cancellation}: $\nabla Q = Q\nabla$ (commutation with derivatives).
\end{enumerate}

\label{thm:L2-energy}
Almost surely, for all $t \geq 0$:
\begin{equation}\label{eq:L2-pathwise}
\|u(t)\|_H^2 + 2\nu\int_0^t \|u(s)\|_V^2 ds + \kap\sum_{\tau_n \leq t}\|\Pi_{>K}u(\tau_n^-)\|_H^2 = \|u_0\|_H^2
\end{equation}
Taking expectations:
\begin{equation}\label{eq:L2-expectation}
\E[\|u(t)\|_H^2] + 2\nu\int_0^t \E[\|u(s)\|_V^2]ds + \Lambda\kap\int_0^t \E[\|\Pi_{>K}u(s)\|_H^2]ds = E_0
\end{equation}

