\begin{equation}
|\cS_{\mathrm{cross}}^{\mathrm{near}}|
\leq 4C\cdot\frac{2\sqrt{J}}{e}\cdot\delta\cdot\frac{D}{E}
= \frac{8C\sqrt{J}}{e}\,\delta\,\frac{D}{E}.
\end{equation}

