- \cS_{\mathrm{diss}},
\end{equation}
where
\begin{align}
\cS_{\mathrm{nonlin}}
&= \frac{2}{E}\sum_{j=1}^J
(\cN_j - p_j\cN)\log\frac{1}{p_j},
\label{eq:S-nonlin}\\
\cS_{\mathrm{diss}}
&= \frac{2\nu}{E}\sum_{j=1}^J
(D_j - p_j D)\log\frac{1}{p_j},
\label{eq:S-diss}
\end{align}
