= -2\nu\,\frac{D}{E}(V_{\alpha+1} - V_\alpha)
\leq 0 \quad\text{for all } \alpha \geq 1.
\end{equation}

\label{prop:covariance}
The cross-entropy ratio $\Phi = H/\cS$ satisfies:
\begin{equation}\label{eq:Phi-cov}
\Phi - 1 = \frac{\mathrm{Cov}_p(r_j,\,
\log(1/p_j))}{\cS},
\end{equation}
where $\mathrm{Cov}_p$ denotes covariance under the
energy distribution~$\{p_j\}$.

