\begin{equation}\label{eq:Phi-cov}
\Phi - 1 = \frac{\mathrm{Cov}_p(r_j,\,
\log(1/p_j))}{\cS},
\end{equation}
where $\mathrm{Cov}_p$ denotes covariance under the
energy distribution~$\{p_j\}$.

