$E \to \infty$ near blow-up).

\label{thm:same-far}
For same-scale triads ($|p|/|q|\in[\eta,1/\eta]$) with
angular separation $\angle(\hat{p},\hat{q}) > \beta$
(where $\beta \geq \alpha = \diam(\Omega_j)$):
\begin{equation}
|\cS_{\mathrm{cross}}^{\mathrm{same,far}}|
\leq C_\beta\,\delta\,\frac{D}{E}\cdot
\log J.
\end{equation}

\label{lem:near-bdy}
For $\beta \leq \alpha$, near-boundary cross-cone triads
satisfy:
\begin{enumerate}[label=(\roman*)]
\item \textbf{Small symbol:}
$|\sigma(p,q)| \leq \sin(\beta)\cdot|q| \leq \beta|q|$.
\item \textbf{Near-source output:}
$\angle(\hat{k},\hat{p}) \leq C\beta$ where $k = p+q$.
\item \textbf{High return fraction:}
$R_{ab\to a} \leq 1/2 + O(\beta^2/\alpha^2)$.
\end{enumerate}

\label{thm:near-bdy-main}
For any smooth divergence-free $u$ on $\T^3$ with
$\cS(u) > 0$:
\begin{equation}\label{eq:near-bdy-bound}
|\cS_{\mathrm{cross}}^{\mathrm{near}}|
\leq C_J^*\,\delta\,\frac{D}{E},
\quad\text{where}\quad
C_J^* = 4C\bigl(\log J + |\log p_{\min}|\bigr).
\end{equation}
No phase decoherence hypothesis is needed.

following_proof:
We follow the proof structure from the decoherence theorem
but set $\gamma = 1$ (worst-case: fully coherent phases).

\textbf{Step 1.}
By the symbol bound, each near-boundary triad satisfies
$|\sigma| \leq \beta|q| \leq \delta|q|$ (taking
$\beta = \delta$).  The transfer to sector~$j$:
\begin{equation}
|\cN_j^{\mathrm{near}}|
\leq \delta\sum_{\text{near-bdy to }j}
|q|\,|\hat{u}(p)|\,|\hat{u}(q)|\,|\hat{u}(k)|
\leq C\delta\,E_j^{1/2}D_j^{1/2}E^{1/2},
\end{equation}
by Cauchy--Schwarz on the trilinear sum.

\textbf{Step 2.}
The deviation from proportional redistribution:
$|\cN_j^{\mathrm{near}} - p_j\cN^{\mathrm{near}}|
\leq 2C\delta\,E_j^{1/2}D_j^{1/2}E^{1/2}$.

\textbf{Step 3.}
The entropy contribution:
\begin{align}
|\cS_{\mathrm{cross}}^{\mathrm{near}}|
&\leq \frac{2}{E}\sum_j |\log p_j|\cdot
2C\delta\,E_j^{1/2}D_j^{1/2}E^{1/2}
\nonumber\\
&\leq \frac{4C\delta}{E^{1/2}}
\left(\sum_j|\log p_j|^2 E_j\right)^{1/2}
D^{1/2}
\nonumber\\
&\leq 4C\delta\,(\log J + |\log p_{\min}|)\,
\frac{D^{1/2}}{E^{1/2}}.
\label{eq:before-poincare}
\end{align}

\textbf{Step 4 (Poincar\'e).}
On $\T^3 = [0,2\pi]^3$, the first eigenvalue of $-\Delta$
is $\lambda_1 = 1$, so:
\begin{equation}
\frac{D}{E} = \frac{\norm{u}_{\Hdot{3/2}}^2}
{\norm{u}_{\Hdot{1/2}}^2} \geq 1.
\end{equation}
Therefore $D^{1/2}/E^{1/2} = (D/E)^{1/2}\leq D/E$, and:
\begin{equation}
|\cS_{\mathrm{cross}}^{\mathrm{near}}|
\leq 4C(\log J + |\log p_{\min}|)\,\delta\,\frac{D}{E}
= C_J^*\,\delta\,\frac{D}{E}.
\end{equation}

\textbf{Step 5 ($p_{\min}$ control).}
The constant $C_J^*$ is finite whenever $p_{\min} > 0$,
which holds whenever $\cS > 0$.  Quantitatively, if
$\cS \geq s_0 > 0$, then
$p_{\min} \geq c\,s_0/(J\log(J/s_0))$,
giving $|\log p_{\min}| \leq C + \log(J/s_0)$ and
$C_J^* \leq C'(\log J + \log(J/s_0))$.

statement:
\label{cor:full-Phi}
For any smooth divergence-free $u$ on~$\T^3$ with
$\cS(u) > 0$, the full cross-cone entropy transfer
satisfies Condition~$\Phi$:
\begin{equation}
|\cS_{\mathrm{cross}}(u)|
\leq c_1(J, s_0)\,\delta(u)\,\frac{D}{E},
\end{equation}
where $s_0 = \cS(u)$ and
$c_1(J,s_0) = O(\log J + \log(J/s_0))$.

\label{cor:bootstrap}
Let $u(t)$ be a smooth NS solution with
$\cS(u_0) = s_0 > 0$.  If on $[0,T]$:
\begin{equation}\label{eq:bootstrap-condition}
c_1(J, s_0/2)\int_0^T\delta(t)\,\frac{D(t)}{E(t)}\,dt
< \frac{s_0}{2},
\end{equation}
then $\cS(u(t)) > s_0/2$ for all $t\in[0,T]$, and
Condition~$\Phi$ holds with constant $c_1(J,s_0/2)$.

\label{thm:stability}
For $u$ smooth, divergence-free on~$\T^3$ with
$\cS(u) > 0$, and $w \in \Hdot{1/2}$ divergence-free:
\begin{equation}\label{eq:stability}
|\cS_{\mathrm{cross}}(u+w) - \cS_{\mathrm{cross}}(u)|
\leq C_{\mathrm{stab}}(J)\,
\left(\frac{D}{E}\right)^{1/2}\norm{w}_{\Hdot{1/2}},
\end{equation}
where $C_{\mathrm{stab}}$ depends on $J$ but
\emph{not on} $E = \norm{u}_{\Hdot{1/2}}^2$.

\label{thm:budget}
For any Leray--Hopf solution on $\T^3$:
\begin{equation}\label{eq:budget}
\cS(u_0) - \inf_{t\geq 0}\cS(u(t))
\leq C_\cS\,\frac{\norm{u_0}_{L^2}^4}{\nu^2},
\end{equation}
where $C_\cS = C_\cS(J, \norm{u_0}_{\Hdot{1/2}}^2)$.

For $u = u_{\leq K} + u_{>K}$:
\begin{equation}
\ip{u_{\leq K}}{u_{>K}}_{L^2} = 0, \quad \ip{u_{\leq K}}{u_{>K}}_{H^1} = 0
\end{equation}

The quadratic part of the ``energy'' factorizes:
\begin{equation}
\|\nabla u\|^2 = \|\nabla u_{\leq K}\|^2 + \|\nabla u_{>K}\|^2
\end{equation}
The mixed Hessian $\nabla^2_{xy}$ of the quadratic term vanishes:
\begin{equation}
\frac{\partial^2}{\partial u_{\leq K} \partial u_{>K}} \left(\frac{1}{2}\|\nabla u\|^2\right) = 0
\end{equation}

The ``Hessian'' in high-frequency directions is:
\begin{equation}
\nabla^2_{u_{>K}u_{>K}} \left(\frac{1}{2\nu}\|\nabla u\|^2\right) = \frac{1}{\nu} \cdot K^2 \cdot I
\end{equation}
where $K^2$ is the minimum eigenvalue on high frequencies.

The NS ``transfer operator'' $T_K$ has \textbf{time-averaged contraction} if:
\begin{equation}
\frac{1}{T}\int_0^T \|\nabla(T_K F)(u(t))\|^2 \, dt \leq q^2 \cdot \frac{1}{T}\int_0^T \|\nabla F(u(t))\|^2 \, dt
\end{equation}
for some $q < 1$ uniform in $T$ and initial data.

following_proof:
Time-averaged contraction for the high-frequency projection means:
\begin{equation}
\frac{1}{T}\int_0^T \|\nabla u_{>K}(t)\|^2 \, dt \leq q^2 \cdot \frac{1}{T}\int_0^T \|\nabla u(t)\|^2 \, dt \leq \frac{q^2 E_0}{\nu T}
\end{equation}

As $T \to \infty$, the time-averaged high-frequency enstrophy vanishes.

By the endpoint criterion: if $\|\Pi_{>K} u\|_{H^1}$ is small on average, then 
$\Lambda_\infty(t) \leq K$ for a.e.\ $t$, giving regularity.

statement:
Suppose $M(T) := \sup_{t \leq T} \|u(t)\|_{H^1}$ satisfies:
\begin{equation}
M(T)^2 \leq C_1 + C_2 \cdot \frac{M(T)^2}{T}
\end{equation}
for constants $C_1, C_2$ independent of $T$. Then for $T > C_2$:
\begin{equation}
M(T)^2 \leq \frac{C_1}{1 - C_2/T} \leq 2C_1
\end{equation}

\label{thm:main}
Let $u_0 \in H^1(\T^3)$ be divergence-free. For any $\nu > 0$ and $K$ sufficiently large 
(depending on $\nu$ and $\|u_0\|_{H^1}$), the solution $u(t)$ to 3D Navier-Stokes satisfies:
\begin{equation}
\sup_{t \geq 0} \|u(t)\|_{H^1}^2 \leq R^2
\end{equation}
for an explicit $R$ depending on $\|u_0\|_{H^1}$, $\nu$, and $K$.

following_proof:
We verify the time-averaged versions of conditions (I1)--(I4).

\textbf{Step 1: Energy inequality gives time-averaged enstrophy bound.}
\begin{equation}
\frac{1}{T}\int_0^T \|\nabla u(t)\|^2 \, dt \leq \frac{E_0}{\nu T}
\end{equation}

\textbf{Step 2: Time-averaged mixed Hessian bound.}

The perturbation is $\Delta = B(u,u)$ (nonlinear term). Its mixed derivative satisfies:
\begin{equation}
\|\nabla_{u_{\leq K}} \nabla_{u_{>K}} B(u,u)\| \leq C \|u\|_{H^1}
\end{equation}

Time-averaging and using Step 1:
\begin{equation}
\frac{1}{T}\int_0^T M_*(t)^2 \, dt \leq C^2 \cdot \frac{E_0}{\nu T}
\end{equation}

\textbf{Step 3: Time-averaged contraction rate.}

The convexity is $\lambda_0 = K^2/\nu$. The time-averaged contraction rate:
\begin{equation}
\bar{a}_0 \leq \frac{C^2 E_0/(\nu T)}{K^4/\nu^2} = \frac{C^2 \nu E_0}{K^4 T}
\end{equation}

Choose $K$ such that $K^4 > C^2 \nu E_0$. Then for $T > 1$, $\bar{a}_0 < 1$.

\textbf{Step 4: Bootstrap.}

Define $M(T) = \sup_{t \leq T} \|u(t)\|_{H^1}$. The time-averaged contraction gives:
\begin{equation}
\frac{1}{T}\int_0^T \|\nabla u_{>K}(t)\|^2 \, dt \leq \bar{a}_0 \cdot \frac{E_0}{\nu T}
\end{equation}

For low frequencies, we have $\|\nabla u_{\leq K}\|^2 \leq K \|u_{\leq K}\|_{L^2}^2 \leq K E_0$.

Total:
\begin{equation}
\frac{1}{T}\int_0^T \|u(t)\|_{H^1}^2 \, dt \leq K E_0 + \bar{a}_0 \cdot \frac{E_0}{\nu T}
\end{equation}

By interpolation and the maximum principle for weak solutions:
\begin{equation}
M(T)^2 \leq C_0(K, \nu, E_0) + \frac{C_1}{T} M(T)^2
\end{equation}

For $T > C_1$, this gives $M(T)^2 \leq 2C_0$, a uniform bound.

\textbf{Step 5: Regularity from bounded $H^1$.}

With $\sup_t \|u(t)\|_{H^1} < \infty$, standard arguments give global regularity.

statement:
\label{def:operator_derivative}
Let $X$ be a process with a closed stochastic integral $\delta_X : \HH_X \to L^2(\Omega)$ on a Hilbert energy space $\HH_X$. The \textbf{operator derivative} $D_X F$ is defined, when it exists, as the unique element of $L^2(\Omega; \HH_X)$ satisfying
\begin{equation}\label{eq:riesz_def}
\E[F \cdot \delta_X(u)] = \E[\inner{D_X F}{u}_{\HH_X}] \quad \text{for all } u \in \HH_X.
\end{equation}
Uniqueness is in $L^2(\Omega; \HH_X)$: if $G_1, G_2$ both satisfy \eqref{eq:riesz_def}, then $G_1 = G_2$ almost surely.

\label{thm:classification_informal}
Properties of the operator derivative $D_X$ fall into three tiers:
\begin{enumerate}
\item[\textbf{Tier 1.}] Linearity, closedness, adjointness $\delta_X = D_X^*$, and $D_X(c) = 0$. These are forced by the Riesz definition.
\item[\textbf{Tier 2.}] The identity $D_X(\delta_X(u)) = u$ and the variance formula $\Var(F) = \E[\|\Pi_X D_X F\|^2]$. These hold when $\delta_X$ is isometric.
\item[\textbf{Tier 3.}] The Leibniz rule $D_X(FG) = F D_X G + G D_X F$ and the chain rule $D_X(f(F)) = f'(F) D_X F$. These require process-specific verification.
\end{enumerate}

\label{thm:intrinsic}
Let $D_X$ be defined by \eqref{eq:riesz_def}. Then:
\begin{enumerate}
\item[(a)] $D_X$ is linear.
\item[(b)] $D_X$ is closed as an unbounded operator on $L^2(\Omega)$.
\item[(c)] $\delta_X = D_X^*$.
\item[(d)] $D_X(c) = 0$ for constants $c \in \R$.
\end{enumerate}

\label{cond:isometry}
For predictable $u, v \in \HH_X$:
\begin{equation}\label{eq:ito_isometry}
\E[\delta_X(u) \cdot \delta_X(v)] = \E[\inner{u}{v}_{\HH_X}].
\end{equation}

\label{thm:isometry_props}
Under Condition~\ref{cond:isometry}:
\begin{enumerate}
\item[(a)] $D_X(\delta_X(u)) = u$ for adapted $u \in \HH_X$.
\item[(b)] $\Var(F) = \E[\norm{\Pi_X D_X F}^2_{\HH_X}]$ when $F - \E[F] = \delta_X(\Pi_X D_X F)$.
\end{enumerate}

\label{cond:leibniz}
For $F, G$ in a suitable domain:
\begin{equation}\label{eq:leibniz}
D_X(FG) = F \, D_X G + G \, D_X F.
\end{equation}

\label{thm:leibniz_equiv}
On smooth domains, the following are equivalent:
\begin{enumerate}
\item[(a)] Leibniz: $D_X(FG) = F D_X G + G D_X F$.
\item[(b)] Chain rule: $D_X(f(F)) = f'(F) D_X F$ for smooth $f : \R \to \R$.
\item[(c)] Product rule for $\delta_X$: $\delta_X(Fu) = F\delta_X(u) - \inner{D_X F}{u}_{\HH_X}$.
\end{enumerate}

\label{prop:leibniz_suff}
The Leibniz condition holds when:
\begin{enumerate}
\item[(i)] $X$ is Gaussian (Section~\ref{sec:gaussian}), or
\item[(ii)] $D_X$ is realized as partial differentiation (Section~\ref{sec:stroock}).
\end{enumerate}

\label{thm:gaussian_leibniz}
Let $X$ be a Gaussian Volterra process with covariance $R(s,t) = \int_0^{s \wedge t} K(s,r) K(t,r) \, dr$ for some kernel $K$. Let $\HH_X$ be the Cameron-Martin space with reproducing kernel $R$, and let $D_X$ be the operator derivative defined by \eqref{eq:riesz_def}. Then for smooth cylindrical functionals
\[
F = f(X_{t_1}, \ldots, X_{t_n}), \quad G = g(X_{s_1}, \ldots, X_{s_m}),
\]
with $f \in C^\infty_b(\R^n)$, $g \in C^\infty_b(\R^m)$, the Leibniz rule holds:
\begin{equation}\label{eq:gaussian_leibniz}
D_X(FG) = F \, D_X G + G \, D_X F.
\end{equation}

\label{ass:innov}
Let $(\varepsilon_k)_{k \geq 1}$ be a sequence satisfying:
\begin{enumerate}
\item[(i)] $\E[\varepsilon_k \mid \FF_{k-1}] = 0$ (martingale difference),
\item[(ii)] $c I \preceq \E[\varepsilon_k \varepsilon_k^\top \mid \FF_{k-1}] \preceq C I$ for some $0 < c \leq C < \infty$ (nondegeneracy),
\item[(iii)] $\FF_k = \sigma(\varepsilon_1, \ldots, \varepsilon_k)$.
\end{enumerate}
No Gaussian or independence assumption is made.

\label{thm:innov_tiers}
Under Assumption~\ref{ass:innov}:
\begin{enumerate}
\item[(a)] \textbf{Tier 1:} $D$ is linear, closed, and $\delta = D^*$.
\item[(b)] \textbf{Tier 2:} The isometry $\E[\delta(u)\delta(v)] = \E[\inner{u}{\Sigma v}]$ holds, where $\Sigma_k = \E[\varepsilon_k \varepsilon_k^\top \mid \FF_{k-1}]$.
\item[(c)] \textbf{Tier 3:} Leibniz holds because $D$ is partial differentiation.
\end{enumerate}

\label{prop:levy_leibniz_formula}
For smooth functionals $F, G$:
\begin{align}
D_W(FG) &= F \, D_W G + G \, D_W F, \label{eq:levy_gauss}\\
D_N(FG)_{t,z} &= F \, D_N G_{t,z} + G \, D_N F_{t,z} + D_N F_{t,z} \cdot D_N G_{t,z}. \label{eq:levy_jump}
\end{align}

\label{thm:clark_ocone_tier1}
Assume only Tier 1: $D_X$ is linear, closed, and $\delta_X = D_X^*$. Let $\Pi_X$ denote the predictable projection onto $\FF_t$-adapted processes. If $F \in \Dom(D_X)$ with $\E[F] = 0$ and $\Pi_X D_X F \in \Dom(\delta_X)$, then
\begin{equation}\label{eq:clark_ocone}
F = \delta_X(\Pi_X D_X F).
\end{equation}

\label{def:operator_derivative}
Let $X$ be a process with a closed stochastic integral $\delta_X : \HH_X \to L^2(\Omega)$ on a Hilbert energy space $\HH_X$. The \textbf{operator derivative} $D_X F$ is defined, when it exists, as the unique element of $L^2(\Omega; \HH_X)$ satisfying
\begin{equation}\label{eq:riesz_def}
\E[F \cdot \delta_X(u)] = \E[\inner{D_X F}{u}_{\HH_X}] \quad \text{for all } u \in \HH_X.
\end{equation}

\label{thm:factorization}
Under axioms (A1)--(A3), for $F \in \mathcal{D}$ with $\Pi DF \in \Dom(\delta)$:
\begin{equation}
F - \E[F] = \delta(\Pi DF).
\end{equation}

\label{thm:product-derivation}
If $D$ is a derivation, then for $F \in \mathcal{D}$ and predictable $u \in \Dom(\delta)$:
\begin{equation}\label{eq:product-derivation}
\delta(Fu) = F \cdot \delta(u) - \inner{DF}{u}_\HH.
\end{equation}

\label{thm:product-cocycle}
If $D$ is a cocycle, then for $F \in \mathcal{D}$ and predictable $u \in \Dom(\delta)$:
\begin{equation}\label{eq:product-cocycle}
\delta(Fu) = F \cdot \delta(u) - \inner{DF}{u}_\HH - \inner{DF \cdot u}{\mathbf{1}}_\HH,
\end{equation}
where the correction term $\inner{DF \cdot u}{\mathbf{1}}_\HH = \int_0^T D_t F \cdot u_t \, \lambda \, dt$ for Poisson.

following_proof:
For $F = f(X_{t_1}, \ldots, X_{t_n})$, the operator derivative is $D_X F = \sum_{i=1}^n \partial_i f(X_{t_1}, \ldots, X_{t_n}) \cdot k_{t_i}$, where $k_t \in \HH_X$ is the representer of evaluation at time $t$. This follows from the Gaussian integration-by-parts formula. Now $FG = (f \cdot g)(X_{t_1}, \ldots, X_{t_n}, X_{s_1}, \ldots, X_{s_m})$, and applying the formula:
\begin{align*}
D_X(FG) &= \sum_{i=1}^n \partial_i(fg) \cdot k_{t_i} + \sum_{j=1}^m \partial_{n+j}(fg) \cdot k_{s_j} \\
&= \sum_{i=1}^n g \cdot \partial_i f \cdot k_{t_i} + \sum_{j=1}^m f \cdot \partial_j g \cdot k_{s_j} = G \, D_X F + F \, D_X G.
\end{align*}
Smooth cylindricals are dense in $\DD^{1,2}$, so the result extends by continuity.

statement:
\label{prop:levy_leibniz}
For smooth functionals $F, G$ of a L\'evy process:
\begin{align}
D_W(FG) &= F \, D_W G + G \, D_W F, \label{eq:levy_gauss}\\
D_N(FG)_{t,z} &= F \, D_N G_{t,z} + G \, D_N F_{t,z} + D_N F_{t,z} \cdot D_N G_{t,z}. \label{eq:levy_jump}
\end{align}

\label{prop:exp}
Let $Y$ be a $(D,\delta,\Pi)$-It\^o process as in \eqref{eq:Y_form}. Applying \eqref{eq:abstract_ito} with $\varphi(x)=e^x$ yields
\begin{equation}\label{eq:exp_formula}
e^{Y_t}
=
e^{Y_0}
+
\int_0^t e^{Y_s}a_s\,ds
+
\delta\!\bigl(e^Y\Pi DY\cdot \mathbf 1_{[0,t]}\bigr)
+
\frac12\int_0^t e^{Y_s}\,\|\Pi DY_s\|_{\mathcal H}^2\,ds.
