\cE^{(D,\Pi)}(M)_t := \exp\!\left(M_t - \frac12\langle M\rangle_t^{(D,\Pi)}\right).
\end{equation}

\label{prop:exp}
Under \eqref{eq:abstract_ito}, taking $\varphi(x)=e^x$ yields
\begin{equation}\label{eq:exp_formula}
e^{Y_t}
=
e^{Y_0}
+
\int_0^t e^{Y_s}a_s\,ds
+
