\label{def:usual-conditions}
A filtration $(\Ft)_{t \in [0,T]}$ satisfies the \emph{usual conditions} if:
\begin{enumerate}[(i)]
\item \textbf{Completeness:} $\mathcal{F}_0$ contains all $\Prob$-null sets of $\mathcal{F}$.
\item \textbf{Right-continuity:} $\Ft = \mathcal{F}_{t+} := \bigcap_{s > t} \Fs$ for all $t \in [0,T)$.
\end{enumerate}

\label{def:predictable}
A stochastic process $(X_t)_{t \in [0,T]}$ is \emph{predictable} if it is measurable with respect to the \emph{predictable $\sigma$-algebra} $\mathcal{P}$ on $[0,T] \times \Omega$, defined as the $\sigma$-algebra generated by all left-continuous adapted processes.

Equivalently, $\mathcal{P}$ is generated by sets of the form $\{0\} \times A$ with $A \in \mathcal{F}_0$, and $(s,t] \times A$ with $0 \leq s < t \leq T$ and $A \in \Fs$.

\label{def:cadlag}
A function $f: [0,T] \to \R^d$ is:
\begin{enumerate}[(i)]
\item \emph{C\`adl\`ag} (right-continuous with left limits) if $\lim_{s \downarrow t} f(s) = f(t)$ for all $t \in [0,T)$ and $\lim_{s \uparrow t} f(s)$ exists in $\R^d$ for all $t \in (0,T]$.
\item \emph{C\`agl\`ad} (left-continuous with right limits) if $\lim_{s \uparrow t} f(s) = f(t)$ for all $t \in (0,T]$ and $\lim_{s \downarrow t} f(s)$ exists in $\R^d$ for all $t \in [0,T)$.
\end{enumerate}

\label{def:lebesgue}
For a measure space $(S, \Sigma, \mu)$ and $p \in [1,\infty]$:
\begin{enumerate}[(i)]
\item $\Lp{p}(S, \Sigma, \mu)$ denotes the space of (equivalence classes of) measurable functions $f: S \to \R$ with $\norm{f}_{\Lp{p}} < \infty$, where
\[
\norm{f}_{\Lp{p}} := \begin{cases}
\left(\int_S |f|^p \, d\mu\right)^{1/p} & \text{if } p < \infty,\\
\esssup_{s \in S} |f(s)| & \text{if } p = \infty.
\end{cases}
\]
\item When $(S, \Sigma, \mu) = (\Omega, \mathcal{F}, \Prob)$, we write $\Lp{p}(\Omega) := \Lp{p}(\Omega, \mathcal{F}, \Prob)$.
\item When $(S, \Sigma, \mu) = ([0,T], \mathcal{B}([0,T]), \lambda)$ with $\lambda$ Lebesgue measure, we write $\Lp{p}([0,T]) := \Lp{p}([0,T], \mathcal{B}([0,T]), \lambda)$.
\end{enumerate}

\label{def:divergence}
The \emph{divergence operator} (or \emph{Skorokhod integral}) $\delta$ is the adjoint of $D$. That is, $\delta: \Dom(\delta) \subset \Lp{2}(\Omega; \mathcal{H}) \to \Lp{2}(\Omega)$ is defined as follows.

An element $u \in \Lp{2}(\Omega; \mathcal{H})$ belongs to $\Dom(\delta)$ if there exists $c > 0$ such that
\[
\bigl|\E[\ip{DF}{u}_{\mathcal{H}}]\bigr| \leq c \norm{F}_{\Lp{2}(\Omega)} \quad \text{for all } F \in \mathcal{S}.
\]
For such $u$, $\delta(u) \in \Lp{2}(\Omega)$ is the unique element satisfying
\begin{equation}\label{eq:adjointness}
\E[F \cdot \delta(u)] = \E[\ip{DF}{u}_{\mathcal{H}}] \quad \text{for all } F \in \mathbb{D}^{1,2}.
\end{equation}

\label{thm:gaussian-identity}
Let $W: \mathcal{H} \to \Lp{2}(\Omega)$ be an isonormal Gaussian process over a separable Hilbert space $\mathcal{H}$, with associated Malliavin derivative $D$, divergence $\delta$, and predictable projection $\Pi$. Then for every $F \in \mathbb{D}^{1,2}$:
\begin{equation}\label{eq:gaussian-identity}
(\Id - \E)F = \delta(\Pi DF).
\end{equation}
In other words, $F - \E[F] = \delta(\Pi DF)$ holds $\Prob$-a.s.

\label{def:operator-covariant}
Let $X$ be a square-integrable process with energy space $\mathcal{H}_X$ and stochastic integral $\delta_X: \Dom(\delta_X) \to \Lp{2}(\Omega)$. A random variable $F \in \Lp{2}(\Omega)$ is \emph{operator--covariantly differentiable with respect to $X$} if there exists a unique element $D_X F \in \Lp{2}_X$ such that
\begin{equation}\label{eq:riesz-def}
\E[F \cdot \delta_X(u)] = \E[\ip{D_X F}{u}_{\mathcal{H}_X}] \quad \text{for all } u \in \Dom(\delta_X).
\end{equation}
The (possibly unbounded) operator $D_X: \Dom(D_X) \subset \Lp{2}(\Omega) \to \Lp{2}_X$ is called the \emph{operator--covariant derivative}.

\label{thm:unified-clark-ocone}
Let $X$ be a square-integrable martingale with stochastic integral $\delta_X$ defined on its energy space $\mathcal{H}_X$ and predictable projection $\Pi_X$. Then for all $F \in \Lp{2}(\Omega)$:
\begin{equation}\label{eq:unified-clark-ocone}
F = \E[F] + \delta_X(\Pi_X D_X F) = \E[F] + \int_0^T (\Pi_X D_X F)_t \, dX_t.
\end{equation}

\label{prop:backward-kolmogorov}
Under the above conditions, $u \in C^{1,2}([0,T) \times \R^d)$ and satisfies
\begin{equation}\label{eq:backward-kolmogorov}
\partial_t u + \mathcal{L} u = 0 \quad \text{on } [0,T) \times \R^d, \qquad u(T,x) = f(x),
\end{equation}
where $\mathcal{L}$ is the infinitesimal generator of $X$:
\[
\mathcal{L} := \frac{1}{2} \sum_{i,j=1}^d (\sigma \sigma^\top)_{ij}(x) \partial_{x_i} \partial_{x_j} + \sum_{i=1}^d b_i(x) \partial_{x_i}.
\]

\label{def:dupire}
For a non-anticipative functional $U: [0,T] \times C([0,T]; \R^d) \to \R$:
\begin{enumerate}[(i)]
\item The \emph{horizontal derivative} is $\partial_t U(t, \omega) := \lim_{h \to 0^+} \frac{1}{h}[U(t+h, \omega_{\cdot \wedge t}) - U(t, \omega)]$.
\item The \emph{vertical derivative} is $\nabla_\omega U(t, \omega) := \lim_{h \to 0} \frac{1}{h}[U(t, \omega + h \mathbf{1}_{[t,T]}) - U(t, \omega)]$.
\end{enumerate}

\label{prop:variable-heat}
The function $u$ satisfies the variable-coefficient heat equation:
\begin{equation}\label{eq:variable-heat}
\partial_t u(t,x) = \frac{1}{2}\bigl(\alpha^2 + 2H \beta^2 t^{2H-1}\bigr) \Delta u(t,x), \quad u(0,x) = f(x).
\end{equation}

\label{thm:mixed-generator}
For $t > 0$ and $x \in \R^d$, $u$ solves the local--nonlocal Cauchy problem:
\begin{equation}\label{eq:mixed-cauchy}
\partial_t u(t,x) = \frac{\alpha^2}{2} \Delta u(t,x) - \beta^\gamma c_\gamma (-\Delta)^{\gamma/2} u(t,x), \quad u(0,x) = f(x).
\end{equation}

\label{ex:cm-bm}
For standard Brownian motion with $R(s,t) = s \wedge t$, the RKHS is
\[
\mathcal{H}_{1/2} = \{h \in C([0,T]) : h(0) = 0, \, h \text{ abs.\ cont.}, \, h' \in \Lp{2}([0,T])\}
\]
with inner product $\ip{h}{g}_{\mathcal{H}_{1/2}} = \int_0^T h'(r) g'(r) \, dr$. The evaluation representer is $k_t(s) = s \wedge t$, so $k'_t(s) = \mathbf{1}_{[0,t]}(s)$ and $\norm{k_t}_{\mathcal{H}_{1/2}} = \sqrt{t}$.

\label{def:usual-conditions}
A filtration $(\Ft)_{t \in [0,T]}$ satisfies the \emph{usual conditions} if:
\begin{enumerate}[(i)]
\item \textbf{Completeness:} $\mathcal{F}_0$ contains all $\Prob$-null sets of $\mathcal{F}$.
\item \textbf{Right-continuity:} $\Ft = \mathcal{F}_{t+} := \bigcap_{s > t} \Fs$ for all $t \in [0,T)$.
\end{enumerate}

\label{def:simple-predictable}
A \emph{simple predictable process} is $u_t(\omega) = \sum_{j=0}^{n-1} \xi_j(\omega) \mathbf{1}_{(t_j, t_{j+1}]}(t)$,
where $0 = t_0 < t_1 < \cdots < t_n = T$ and each $\xi_j$ is bounded and $\mathcal{F}_{t_j}$-measurable.

\label{def:operator-covariant}
Let $X$ be a square-integrable process with energy space $\mathcal{H}_X$ and stochastic integral $\delta_X: \mathcal{H}_X \to \Lp{2}(\Omega)$. For $F \in \Lp{2}(\Omega)$, the \emph{operator--covariant derivative} $D_X F \in \mathcal{H}_X$ is the unique element satisfying
\begin{equation}\label{eq:riesz-def}
\E[F \cdot \delta_X(u)] = \ip{D_X F}{u}_{\mathcal{H}_X} \quad \text{for all } u \in \mathcal{H}_X.
\end{equation}
The operator $D_X: \Lp{2}(\Omega) \to \mathcal{H}_X$ is called the \emph{operator--covariant derivative}.

\label{thm:unified-clark-ocone}
Let $X$ be a square-integrable process with natural filtration $(\Ft^X)_{t \in [0,T]}$, energy space $\mathcal{H}_X$, stochastic integral $\delta_X$, predictable projection $\Pi_X$, and operator--covariant derivative $D_X = \delta_X^*$. Assume $\delta_X$ is isometric on predictable processes and that $X$ has the representation property: every $\mathcal{F}_T^X$-measurable $\tilde{F} \in \Lp{2}(\Omega)$ with $\E[\tilde{F}] = 0$ can be written as $\tilde{F} = \delta_X(v)$ for some predictable $v \in \mathcal{H}_X$. Then for all $\mathcal{F}_T^X$-measurable $F \in \Lp{2}(\Omega)$:
\begin{equation}\label{eq:unified-clark-ocone}
F = \E[F] + \delta_X(\Pi_X D_X F) = \E[F] + \int_0^T (\Pi_X D_X F)_t \, dX_t.
\end{equation}
Equivalently, the operator identity $(\Id - \E) = \delta_X \circ \Pi_X \circ D_X$ holds on $\Lp{2}(\Omega, \mathcal{F}_T^X, \Prob)$.

\label{prop:backward-kolmogorov}
The function $u$ satisfies $\partial_t u + \mathcal{L} u = 0$ on $[0,T) \times \R^d$ with $u(T,x) = f(x)$, where
\[
\mathcal{L} := \frac{1}{2} \sum_{i,j} (\sigma \sigma^\top)_{ij}(x) \partial_{x_i} \partial_{x_j} + \sum_i b_i(x) \partial_{x_i}
\]
is the infinitesimal generator of $X$.

