\item \emph{Representation property:} Every $\mathcal{F}_T^X$-measurable $\tilde{F} \in \Lp{2}(\Omega)$ with $\E[\tilde{F}] = 0$ can be written as $\tilde{F} = \delta_X(v)$ for some predictable $v \in \mathcal{H}_X$.
\end{enumerate}
Then for all $\mathcal{F}_T^X$-measurable $F \in \Lp{2}(\Omega)$:
\begin{equation}\label{eq:unified-clark-ocone}
F = \E[F] + \delta_X(\Pi_X D_X F) = \E[F] + \int_0^T (\Pi_X D_X F)_t \, dX_t, \quad \Prob\text{-a.s.}
\end{equation}
Equivalently, the operator identity $(\Id - \E) = \delta_X \circ \Pi_X \circ D_X$ holds on $\Lp{2}(\Omega, \mathcal{F}_T^X, \Prob)$.

\label{ex:general-martingale}
Let $X$ be a continuous square-integrable martingale on $(\Omega, \mathcal{F}, \Prob)$ with quadratic variation $\langle X \rangle$ and the martingale representation property (i.e., every $\mathcal{F}_T^X$-measurable $F \in \Lp{2}(\Omega)$ with $\E[F] = 0$ can be written as a stochastic integral with respect to $X$). The energy space $\mathcal{H}_X$ consists of predictable processes $u = (u_t)_{t \in [0,T]}$ with $\E[\int_0^T u_t^2 \, d\langle X \rangle_t] < \infty$. Since $\mathcal{H}_X$ already consists of predictable processes, $\Pi_X = \Id$ and the operator--covariant derivative $D_X$ satisfies
\[
F = \E[F] + \int_0^T (D_X F)_t \, dX_t, \quad \Prob\text{-a.s.}
\]
for all $\mathcal{F}_T^X$-measurable $F \in \Lp{2}(\Omega)$.

\label{def:mixed-energy}
$\mathcal{H}_X := \mathcal{H}_B \oplus \mathcal{H}_{B^H}$ with inner product
\[
\ip{(u,v)}{(u',v')}_{\mathcal{H}_X} := \ip{u}{u'}_{\mathcal{H}_B} + \ip{v}{v'}_{\mathcal{H}_{B^H}}
\]
for $(u,v), (u',v') \in \mathcal{H}_X$.

\label{def:operator-covariant}
Let $X$ be a square-integrable process with energy space $\mathcal{H}_X$ and stochastic integral $\delta_X: \mathcal{H}_X \to \Lp{2}(\Omega)$. For $F \in \Lp{2}(\Omega)$, the \emph{operator--covariant derivative} $D_X F \in \mathcal{H}_X$ is the unique element satisfying
\begin{equation}\label{eq:riesz-def}
\E[F \cdot \delta_X(u)] = \ip{D_X F}{u}_{\mathcal{H}_X} \quad \text{for all } u \in \mathcal{H}_X.
\end{equation}
The operator $D_X: \Lp{2}(\Omega) \to \mathcal{H}_X$ is called the \emph{operator--covariant derivative}.

\label{thm:unified-clark-ocone}
Let $X$ be a square-integrable process on a complete probability space $(\Omega, \mathcal{F}, \Prob)$ with natural filtration $(\Ft^X)_{t \in [0,T]}$ satisfying the usual conditions. Let $\mathcal{H}_X$ be an energy space for $X$ (Definition~\ref{def:energy-space}) with stochastic integral $\delta_X$, predictable projection $\Pi_X$ (Definition~\ref{def:pred-proj-X}), and operator--covariant derivative $D_X = \delta_X^*$ (Definition~\ref{def:operator-covariant}). Assume:
\begin{enumerate}[(i)]
\item \emph{Centered integrals:} $\E[\delta_X(u)] = 0$ for all $u \in \mathcal{H}_X$.
\item \emph{Isometry on predictable processes:} $\E[|\delta_X(u)|^2] = \norm{u}_{\mathcal{H}_X}^2$ for predictable $u \in \mathcal{H}_X$. (By polarization, this implies $\E[\delta_X(v) \cdot \delta_X(u)] = \ip{v}{u}_{\mathcal{H}_X}$ for predictable $v, u$.)
\item \emph{Representation property:} Every $\mathcal{F}_T^X$-measurable $\tilde{F} \in \Lp{2}(\Omega)$ with $\E[\tilde{F}] = 0$ can be written as $\tilde{F} = \delta_X(v)$ for some predictable $v \in \mathcal{H}_X$.
\end{enumerate}
Then for all $\mathcal{F}_T^X$-measurable $F \in \Lp{2}(\Omega)$:
\begin{equation}\label{eq:unified-clark-ocone}
F = \E[F] + \delta_X(\Pi_X D_X F) = \E[F] + \int_0^T (\Pi_X D_X F)_t \, dX_t, \quad \Prob\text{-a.s.}
\end{equation}
Equivalently, the operator identity $(\Id - \E) = \delta_X \circ \Pi_X \circ D_X$ holds on $\Lp{2}(\Omega, \mathcal{F}_T^X, \Prob)$.

\label{def:fbm}
\emph{Fractional Brownian motion} $(B^H_t)_{t \in [0,T]}$ with \emph{Hurst parameter} $H \in (0,1)$ is the centered Gaussian process with covariance function $R_H: [0,T] \times [0,T] \to \R$ given by
\[
R_H(s,t) := \Cov(B^H_s, B^H_t) = \frac{1}{2}(s^{2H} + t^{2H} - |t-s|^{2H}) \quad \text{for } s, t \in [0,T].
\]
The case $H = 1/2$ recovers standard Brownian motion. For $H \neq 1/2$, fractional Brownian motion is:
\begin{enumerate}[(i)]
\item \emph{Not a semimartingale} (so classical It\^o calculus does not apply directly);
\item \emph{Non-Markovian} (the increments exhibit long-range dependence for $H > 1/2$ and negative correlation for $H < 1/2$).
\end{enumerate}

\label{ex:general-martingale}
Let $X$ be a continuous square-integrable martingale on a complete probability space $(\Omega, \mathcal{F}, \Prob)$ with quadratic variation $\langle X \rangle$ and the martingale representation property (i.e., every $\mathcal{F}_T^X$-measurable $F \in \Lp{2}(\Omega)$ with $\E[F] = 0$ can be written as a stochastic integral with respect to $X$). The energy space $\mathcal{H}_X$ consists of predictable processes $u = (u_t)_{t \in [0,T]}$ with $\E[\int_0^T u_t^2 \, d\langle X \rangle_t] < \infty$. Since $\mathcal{H}_X$ already consists of predictable processes, $\Pi_X = \Id$ and the operator--covariant derivative $D_X$ satisfies
\[
F = \E[F] + \int_0^T (D_X F)_t \, dX_t, \quad \Prob\text{-a.s.}
\]
for all $\mathcal{F}_T^X$-measurable $F \in \Lp{2}(\Omega)$.

\label{def:dupire}
For a non-anticipative functional $U$:
\begin{enumerate}[(i)]
\item \emph{Horizontal derivative:} $\partial_t U(t, \omega) := \lim_{h \to 0^+} \frac{1}{h}[U(t+h, \omega_{\cdot \wedge t}) - U(t, \omega)]$.
\item \emph{Vertical derivative:} $\nabla_\omega U(t, \omega) := \lim_{h \to 0} \frac{1}{h}[U(t, \omega + h \mathbf{1}_{[t,T]}) - U(t, \omega)]$.
\end{enumerate}

\label{def:triple}
A \emph{causal derivation-divergence triple} is $(D, \delta, \Pi)$ where:
\begin{enumerate}
\item $D : \Dom(D) \subset L^2(\Omega) \to L^2(\Omega; H)$ is a densely-defined closed linear operator (the \emph{derivation}) with $1 \in \Dom(D)$ and $D1 = 0$.

\item $\delta : \Dom(\delta) \subset L^2(\Omega; H) \to L^2(\Omega)$ is the Hilbert space adjoint of $D$ (the \emph{divergence}):
\begin{equation}\label{eq:adjoint}
\E[F \delta(u)] = \E[\ip{DF}{u}_H], \quad F \in \Dom(D),\; u \in \Dom(\delta).
\end{equation}

\item $\Pi : L^2(\Omega; H) \to L^2(\Omega; H)$ is a bounded projection (``causal'' or ``predictable'') with $\Pi^2 = \Pi$.
\end{enumerate}

\label{ass:chain-rule}
There exists a subalgebra $\mathcal{A} \subset \Dom(D)$ dense in $L^2(\Omega)$ and stable under multiplication such that for $F \in \mathcal{A}$ and $\varphi \in C_b^1(\R)$,
\begin{equation}\label{eq:chain-rule}
D(\varphi(F)) = \varphi'(F) DF.
\end{equation}
For $\varphi \in C_b^1(\R^n)$ and $F = (F_1, \ldots, F_n)$ with $F_i \in \mathcal{A}$,
\[
D(\varphi(F)) = \sum_{i=1}^n \partial_i \varphi(F) DF_i.
\]

\label{ass:factorization}
For $F \in \mathcal{A}$,
\begin{equation}\label{eq:factorization}
(\Id - \E)F = \delta(\Pi DF).
\end{equation}

\label{def:intrinsic-bracket}
Let $Y = (Y_t)_{t \in [0,T]}$ be such that $Y_t \in \Dom(D)$ for a.e.\ $t$ and $t \mapsto \Pi DY_t$ lies in $L^2([0,T] \times \Omega; H)$. Define the \emph{intrinsic bracket}
\begin{equation}\label{eq:intrinsic-bracket}
\bracket{Y}_t^{(D,\Pi)} := \int_0^t \norm{\Pi DY_s}_H^2\, ds.
\end{equation}

\label{def:ito-process}
A real process $Y = (Y_t)_{t \in [0,T]}$ is called a \emph{$(D,\delta,\Pi)$-It\^o process} if:
\begin{enumerate}
\item $t \mapsto Y_t$ is $L^2(\Omega)$-continuous and $Y_t \in \Dom(D)$ for each $t \in [0,T]$.

\item There exists $a \in L^2([0,T] \times \Omega)$ (the \emph{drift}) such that for all $t \in [0,T]$,
\begin{equation}\label{eq:ito-decomposition}
Y_t = Y_0 + \int_0^t a_s\, ds + \delta(\Pi DY \cdot \mathbf{1}_{[0,t]}),
\end{equation}
where the equality holds in $L^2(\Omega)$.

\item The map $t \mapsto \Pi DY_t$ lies in $L^2([0,T] \times \Omega; H)$.
\end{enumerate}

\label{rmk:existence}
The decomposition~\eqref{eq:ito-decomposition} is a \emph{definition} of the class, not a theorem asserting existence. We do not claim that every $L^2$-continuous process admits this form. Rather:
\begin{enumerate}
\item[(a)] For Volterra Gaussian processes (Section~\ref{sec:volterra}), existence of the decomposition follows from the Malliavin calculus construction.
\item[(b)] For other processes, one must either verify the decomposition directly or work within a class where it is known to hold.
\end{enumerate}
The theorems in this paper apply to processes \emph{given} to satisfy Definition~\ref{def:ito-process}. Verifying that a specific process satisfies the definition is a separate task, carried out explicitly for Volterra Gaussian processes in Section~\ref{sec:volterra}.

\label{ass:holder}
Let $Y$ be a $(D,\delta,\Pi)$-It\^o process with associated Hurst parameter $H < \frac{1}{4}$. We assume:
\begin{enumerate}
\item The map $t \mapsto DY_t$ is H\"older continuous in $H$ with exponent $\gamma > \frac{1}{4} - H$:
\[
\E[\norm{DY_t - DY_s}_H^2] \leq C |t-s|^{2\gamma}, \quad \gamma > \frac{1}{4} - H.
\]

\item The drift satisfies $\int_0^T |a_s|^p\, ds < \infty$ almost surely for some $p > \frac{2}{2H}$.

\item For $F \in C_b^1(\R)$, the product $F(Y_s) \Pi DY_s$ lies in $L^2([0,T] \times \Omega; H) \cap \Dom(\delta)$.
\end{enumerate}

\label{thm:product-rule}
Let $(D, \delta, \Pi)$ satisfy Assumptions~\ref{ass:chain-rule}--\ref{ass:orthogonal}. Let $F \in \Dom(D)$ and $u \in \Dom(\delta)$. Assume the pointwise product $Fu : \Omega \to H$ (given by $(Fu)(\omega) := F(\omega) u(\omega)$) satisfies:
\begin{enumerate}
\item $Fu \in L^2(\Omega; H)$,
\item $Fu \in \Dom(\delta)$.
\end{enumerate}
Then
\begin{equation}\label{eq:product-rule}
\delta(Fu) = F\delta(u) - \ip{DF}{u}_H \quad \text{in } L^2(\Omega).
\end{equation}

\label{lem:orthogonal}
Under Assumption~\ref{ass:orthogonal}, for $F \in \Dom(D)$,
\begin{equation}\label{eq:orthogonal-identity}
\ip{DF}{\Pi DF}_H = \norm{\Pi DF}_H^2.
\end{equation}

\label{thm:ito}
Let $(D, \delta, \Pi)$ satisfy Assumptions~\ref{ass:chain-rule}--\ref{ass:orthogonal}. Let $Y$ be a $(D,\delta,\Pi)$-It\^o process with drift $a$:
\begin{equation}\label{eq:Y-decomp}
Y_t = Y_0 + \int_0^t a_s\, ds + \delta(\Pi DY \cdot \mathbf{1}_{[0,t]}).
\end{equation}
For processes with Hurst parameter $H < \frac{1}{4}$, assume additionally that Assumption~\ref{ass:holder} holds.

Let $\varphi \in C_b^2(\R)$. Then for all $t \in [0,T]$,
\begin{equation}\label{eq:ito-formula}
\varphi(Y_t) = \varphi(Y_0) + \int_0^t \varphi'(Y_s) a_s\, ds + \delta(\varphi'(Y) \Pi DY \cdot \mathbf{1}_{[0,t]}) + \frac{1}{2} \int_0^t \varphi''(Y_s) \norm{\Pi DY_s}_H^2\, ds,
\end{equation}
where the equality holds in $L^2(\Omega)$. Equivalently, in terms of the intrinsic bracket,
\begin{equation}\label{eq:ito-bracket}
\varphi(Y_t) = \varphi(Y_0) + \int_0^t \varphi'(Y_s) a_s\, ds + \delta(\varphi'(Y) \Pi DY \cdot \mathbf{1}_{[0,t]}) + \frac{1}{2} \int_0^t \varphi''(Y_s)\, d\bracket{Y}_s^{(D,\Pi)}.
\end{equation}

\label{lem:remainder}
For $\varphi \in C_b^2(\R)$ and $Y$ a $(D,\delta,\Pi)$-It\^o process,
\[
\varphi(Y_{t_{k+1}^n}) - \varphi(Y_{t_k^n}) = \varphi'(Y_{t_k^n})(Y_{t_{k+1}^n} - Y_{t_k^n}) + \frac{1}{2} \varphi''(Y_{t_k^n})(Y_{t_{k+1}^n} - Y_{t_k^n})^2 + R_k,
\]
where the remainder satisfies
\begin{equation}\label{eq:remainder-bound}
\E[R_k^2] \leq C (\Delta t_n)^\alpha, \quad \alpha := \min\{3, 2H+2\},
\end{equation}
for some constant $C$ depending on $\norm{\varphi''}_\infty$, $\norm{\varphi'''}_\infty$, and the regularity of $Y$.

\label{lem:skorokhod}
Let $(D, \delta, \Pi)$ satisfy Assumptions~\ref{ass:chain-rule}--\ref{ass:orthogonal}. Let $u \in L^2([0,T] \times \Omega; H) \cap \Dom(\delta)$ be such that:
\begin{enumerate}
\item $u$ is adapted: $u_s \in H_s$ for a.e.\ $s$ (where $H_s$ is the adapted subspace at time $s$).
\item The map $s \mapsto u_s$ is H\"older continuous in $L^2(\Omega; H)$ with exponent $\gamma \geq H$.
\end{enumerate}
Then for any interval $[t_k, t_{k+1}]$,
\begin{equation}\label{eq:skorokhod-isometry}
\E\left[ (\delta(u \cdot \mathbf{1}_{(t_k, t_{k+1}]}))^2 \right] = \E\left[ \int_{t_k}^{t_{k+1}} \norm{u_s}_H^2\, ds \right] + O((\Delta t)^{2H+1}),
\end{equation}
where $\Delta t := t_{k+1} - t_k$.

\label{thm:ito-multi}
Let $Y = (Y^1, \ldots, Y^n)$ where each $Y^i$ is a $(D,\delta,\Pi)$-It\^o process:
\[
Y_t^i = Y_0^i + \int_0^t a_s^i\, ds + \delta(\Pi DY^i \cdot \mathbf{1}_{[0,t]}).
\]
Let $\varphi \in C_b^2(\R^n)$. Then
\begin{align}
\varphi(Y_t) &= \varphi(Y_0) + \sum_{i=1}^n \int_0^t \partial_i \varphi(Y_s) a_s^i\, ds + \sum_{i=1}^n \delta(\partial_i \varphi(Y) \Pi DY^i \cdot \mathbf{1}_{[0,t]}) \notag\\
&\quad + \frac{1}{2} \sum_{i,j=1}^n \int_0^t \partial_i \partial_j \varphi(Y_s) \ip{\Pi DY_s^i}{\Pi DY_s^j}_H\, ds. \label{eq:ito-multi}
\end{align}

\label{def:DU-conditions}
A Volterra kernel $K$ satisfies the \emph{Decreusefond--\"Ust\"unel conditions} \cite{Decreusefond1999} if:
\begin{enumerate}
\item $\int_0^T \int_0^t K(t,s)^2\, ds\, dt < \infty$.
\item There exists $H \in (0,1)$ such that $|K(t,s)| \leq C |t-s|^{H - 1/2}$ for $s < t$.
\item $K$ has sufficient regularity for Malliavin calculus: specifically, the fractional derivative $\partial_t K(t,s)$ exists and satisfies integrability conditions ensuring $\Dom(\delta_X)$ is dense.
\end{enumerate}

\label{def:cameron-martin}
The Cameron-Martin space $H_X$ is the completion of
\[
H_0 := \{K(t, \cdot) : t \in [0,T]\}
\]
under the inner product
\begin{equation}\label{eq:CM-inner-product}
\ip{K(t,\cdot)}{K(u,\cdot)}_{H_X} := R_X(t,u).
\end{equation}
The canonical representer $k_t \in H_X$ satisfies $\ip{h}{k_t}_{H_X} = h(t)$ for all $h \in H_X$.

\label{def:normalized-CM}
For fractional Brownian motion with $H \in (0,1)$, we normalize the Cameron-Martin space $H_H$ so that
\begin{equation}\label{eq:normalization}
\norm{k_t}_{H_H}^2 = 2H t^{2H-1}.
\end{equation}
This normalization ensures
\begin{equation}\label{eq:bracket-integral}
\int_0^t \norm{k_s}_{H_H}^2\, ds = 2H \int_0^t s^{2H-1}\, ds = t^{2H}.
\end{equation}

\label{lem:fBM-bracket}
With the normalization of Definition~\ref{def:normalized-CM},
\begin{equation}\label{eq:fBM-bracket}
\bracket{B^H}_t^{(D_H, \Pi_H)} = t^{2H}.
\end{equation}

\label{def:triple}
A \emph{causal derivation--divergence triple} is $(D,\delta,\Pi)$ where:
\begin{enumerate}[label=(\arabic*)]
\item $D: \Dom(D) \subset L^2(\Omega) \to L^2(\Omega;\HH)$ is a densely-defined closed linear operator (the \emph{derivation}) with $\mathbf{1}\in\Dom(D)$ and $D\mathbf{1}=0$.
\item $\delta: \Dom(\delta) \subset L^2(\Omega;\HH) \to L^2(\Omega)$ is the Hilbert space adjoint of $D$ (the \emph{divergence}):
\begin{equation}\label{eq:adjoint}
\mathbb{E}[F\delta(u)] = \mathbb{E}[\inner{DF}{u}_\HH], \qquad F \in \Dom(D),\; u \in \Dom(\delta).
\end{equation}
\item $\Pi: L^2(\Omega;\HH) \to L^2(\Omega;\HH)$ is a bounded projection (``causal'' or ``predictable'') with $\Pi^2 = \Pi$.
\end{enumerate}

\label{ass:chain}
There exists a subalgebra $\AAA \subset \Dom(D)$ dense in $L^2(\Omega)$ and stable under multiplication such that for $F\in\AAA$ and $\varphi\in C^1_b(\mathbb{R})$,
\begin{equation}\label{eq:chain}
D(\varphi(F)) = \varphi'(F)DF.
\end{equation}
For $\varphi\in C^1_b(\mathbb{R}^n)$ and $F=(F_1,\ldots,F_n)$ with $F_i\in\AAA$,
$D(\varphi(F)) = \sum_{i=1}^n \partial_i\varphi(F)\,DF_i$.

\label{ass:factor}
For $F\in\AAA$,
\begin{equation}\label{eq:factor}
(\Id - \mathbb{E})F = \delta(\Pi DF).
\end{equation}

\label{def:bracket}
Let $Y = (Y_t)_{t\in[0,T]}$ be such that $Y_t\in\Dom(D)$ for a.e.\ $t$ and $t\mapsto \Pi DY_t$ lies in $L^2([0,T]\times\Omega;\HH)$. Define the \emph{energy function}
\begin{equation}\label{eq:energy}
\Gamma^Y(t) := \norm{\Pi DY_t}_\HH^2
\end{equation}
and the \emph{intrinsic bracket}
\begin{equation}\label{eq:bracket}
\langle Y\rangle^{(D,\Pi)}_t := \Gamma^Y(t) = \norm{\Pi DY_t}_\HH^2.
\end{equation}
For centered Gaussian processes, $\Gamma^Y(t) = \mathbb{E}[Y_t^2]$.

\label{def:Ito}
A real process $Y = (Y_t)_{t\in[0,T]}$ is called a \emph{$(D,\delta,\Pi)$-It\^o process} if:
\begin{enumerate}[label=(\arabic*)]
\item $t\mapsto Y_t$ is $L^2(\Omega)$-continuous and $Y_t\in\Dom(D)$ for each $t\in[0,T]$.
\item There exists $a\in L^2([0,T]\times\Omega)$ (the \emph{drift}) such that for all $t\in[0,T]$,
\begin{equation}\label{eq:decomp}
Y_t = Y_0 + \int_0^t a_s\,ds + \delta(\Pi DY\cdot\mathbf{1}_{[0,t]}),
\end{equation}
where the equality holds in $L^2(\Omega)$.
\item The map $t\mapsto \Pi DY_t$ lies in $L^2([0,T]\times\Omega;\HH)$.
\end{enumerate}

\label{rem:existence}
The decomposition~\eqref{eq:decomp} is a \emph{definition} of the class, not a theorem asserting existence. We do not claim that every $L^2$-continuous process admits this form. Rather:
\begin{enumerate}[label=(\alph*)]
\item For Volterra Gaussian processes (Section~\ref{sec:volterra}), existence of the decomposition follows from the Malliavin calculus construction.
\item For other processes, one must either verify the decomposition directly or work within a class where it is known to hold.
\end{enumerate}

\label{thm:product}
Let $(D,\delta,\Pi)$ satisfy Assumptions~\ref{ass:chain}--\ref{ass:ortho}. Let $F\in\Dom(D)$ and $u\in\Dom(\delta)$. Assume the pointwise product $Fu:\Omega\to\HH$ (given by $(Fu)(\omega):=F(\omega)u(\omega)$) satisfies:
\begin{enumerate}[label=(\arabic*)]
\item $Fu\in L^2(\Omega;\HH)$,
\item $Fu\in\Dom(\delta)$.
\end{enumerate}
Then
\begin{equation}\label{eq:productrule}
\delta(Fu) = F\delta(u) - \inner{DF}{u}_\HH \qquad \text{in } L^2(\Omega).
\end{equation}

following_proof:
By definition, $Fu\in\Dom(\delta)$ iff there exists $\xi\in L^2(\Omega)$ such that $\mathbb{E}[\inner{DG}{Fu}_\HH] = \mathbb{E}[G\xi]$ for all $G\in\Dom(D)$. This is equivalent to continuity of $\Phi_u$ (by Riesz representation). If $F\in L^\infty(\Omega)$, then
$|\mathbb{E}[\inner{DG}{Fu}_\HH]| \leq 
orm{F}_{L^\infty}
orm{DG}_{L^2(\Omega;\HH)}
orm{u}_{L^2(\Omega;\HH)}$,
which is continuous in the graph norm.

