\label{lem:ortho}
Under Assumption~\ref{ass:ortho}, for $F\in\Dom(D)$,
\begin{equation}\label{eq:ortho}
\inner{DF}{\Pi DF}_\HH = \norm{\Pi DF}_\HH^2.
\end{equation}

\label{thm:main}
Let $(D,\delta,\Pi)$ satisfy Assumptions~\ref{ass:chain}--\ref{ass:energy}. Let $Y$ be a $(D,\delta,\Pi)$-It\^o process with drift $a$:
\begin{equation}\label{eq:Ydecomp}
Y_t = Y_0 + \int_0^t a_s\,ds + \delta(\Pi DY\cdot\mathbf{1}_{[0,t]}).
\end{equation}
For processes with regularity exponent $H < \tfrac{1}{4}$ (in the sense of Assumption~\ref{ass:Holder}), assume additionally that Assumption~\ref{ass:Holder} holds. Let $\varphi\in C^3_b(\mathbb{R})$. Then for all $t\in[0,T]$,
\begin{equation}\label{eq:Ito}
\varphi(Y_t) = \varphi(Y_0) + \int_0^t \varphi'(Y_s)a_s\,ds + \delta(\varphi'(Y)\Pi DY\cdot\mathbf{1}_{[0,t]}) + \frac{1}{2}\int_0^t \varphi''(Y_s)\,d\Gamma^Y(s),
\end{equation}
where $\Gamma^Y(s) = \norm{\Pi DY_s}_\HH^2$ is the energy function (Definition~\ref{def:bracket}), the last integral is a Stieltjes integral against the bounded variation measure $d\Gamma^Y$, and the equality holds in $L^2(\Omega)$. When $\Gamma^Y$ is absolutely continuous with density $\dot{\Gamma}^Y$, the correction reduces to $\frac{1}{2}\int_0^t \varphi''(Y_s)\dot{\Gamma}^Y(s)\,ds$.

\label{thm:characterization}
Let $(D,\delta,\Pi)$ satisfy Assumptions~\ref{ass:chain}--\ref{ass:energy}. Suppose $\nu$ is a signed Borel measure on $[0,T]$ (possibly $\omega$-dependent) such that for all $\varphi\in C^3_b(\mathbb{R})$ and all $(D,\delta,\Pi)$-It\^o processes $Y$ with drift $a$,
\begin{equation}\label{eq:Qformula}
\varphi(Y_t) = \varphi(Y_0) + \int_0^t \varphi'(Y_s)a_s\,ds + \delta(\varphi'(Y)\Pi DY\cdot\mathbf{1}_{[0,t]}) + \frac{1}{2}\int_0^t \varphi''(Y_s)\,d\nu(s)
\end{equation}
holds in $L^2(\Omega)$ for all $t\in[0,T]$. Then $\nu = \Gamma^Y$ (i.e., $d\nu = d\Gamma^Y$) on $[0,T]$, $P$-a.s.

