holds in $L^2(\Omega)$ for all $t\in[0,T]$. Then $Q_s = \norm{\Pi DY_s}_\HH^2$ for a.e.\ $s\in[0,T]$, $P$-a.s.

\label{thm:multi}
Let $Y = (Y^1,\ldots,Y^n)$ where each $Y^i$ is a $(D,\delta,\Pi)$-It\^o process:
$Y^i_t = Y^i_0 + \int_0^t a^i_s\,ds + \delta(\Pi DY^i\cdot\mathbf{1}_{[0,t]})$.
Let $\varphi\in C^3_b(\mathbb{R}^n)$. Then
\begin{align*}
\varphi(Y_t) &= \varphi(Y_0) + \sum_{i=1}^n \int_0^t \partial_i\varphi(Y_s)a^i_s\,ds + \sum_{i=1}^n \delta(\partial_i\varphi(Y)\Pi DY^i\cdot\mathbf{1}_{[0,t]})\\
&\quad + \frac{1}{2}\sum_{i,j=1}^n \int_0^t \partial_i\partial_j\varphi(Y_s)\inner{\Pi DY^i_s}{\Pi DY^j_s}_\HH\,ds.
\end{align*}

\label{def:DU}
A Volterra kernel $K$ satisfies the \emph{Decreusefond--\"Ust\"unel conditions} \cite{DU} if:
(1)~$\int_0^T\int_0^t K(t,s)^2\,ds\,dt < \infty$;
(2)~there exists $H\in(0,1)$ such that $|K(t,s)|\leq C|t-s|^{H-1/2}$ for $s<t$;
(3)~$\partial_t K(t,s)$ exists and satisfies integrability conditions ensuring $\Dom(\delta^X)$ is dense.

\label{prop:fixeddriver}
Let $M$ be a continuous square-integrable martingale with bracket measure $\mu$ (i.e., $\langle M\rangle_t = \int_0^t d\mu_s$). Let $K_1,K_2$ be two causal Volterra kernels such that the process $X_t := \int_0^t K_1(t,s)\,dM_s$ also satisfies
\begin{equation}\label{eq:sameprocess}
X_t = \int_0^t K_2(t,s)\,dM_s \quad \text{for all } t\in[0,T],\;\text{a.s.}
\end{equation}
Assume both kernels satisfy the Decreusefond--\"Ust\"unel conditions with respect to $\mu$. Then
\begin{equation}\label{eq:bracketinvariance}
\langle X\rangle^{(D^{K_1},\Pi^{K_1})}_t = \langle X\rangle^{(D^{K_2},\Pi^{K_2})}_t \quad \text{for all } t\in[0,T].
\end{equation}

\label{rem:diffdriver}
Different driver--kernel pairs produce different operator triples $(D^K,\delta^K,\Pi^K)$ and $(D^{\widetilde{K}},\delta^{\widetilde{K}},\Pi^{\widetilde{K}})$. These triples encode different decompositions of the noise: the ``fresh-noise'' component $\Pi DX_s$ depends on which filtration (hence which driver) is used. Accordingly, the intrinsic bracket $\langle X\rangle^{(D^K,\Pi^K)}_t$ may differ from $\langle X\rangle^{(D^{\widetilde{K}},\Pi^{\widetilde{K}})}_t$.

This is not a defect. The intrinsic bracket records the energy structure of a specific noise decomposition. Different decompositions carry different physical content, and the bracket faithfully reflects this. An analogy: in differential geometry, the Christoffel symbols depend on the coordinate chart, but the curvature they encode does not. Here, the bracket depends on the representation, but the Hurst exponent it encodes does not (Proposition~\ref{prop:Hurstinvariant}).

\label{prop:approx}
Let $K_n$ be a sequence of Volterra kernels converging to $K$ in $L^2(\mu)$, where $\mu$ is the measure on $\{(t,s): 0\leq s\leq t\leq T\}$ given by $d\mu = ds\,dt$. Assume each $K_n$ and $K$ satisfy the Decreusefond--\"Ust\"unel conditions with uniform bounds. Let $X^{(n)}_t = \int_0^t K_n(t,s)\,dW_s$ and $X_t = \int_0^t K(t,s)\,dW_s$. Then:
\begin{enumerate}[label=(\roman*)]
\item $\langle X^{(n)}\rangle^{(D^{K_n},\Pi^{K_n})}_t \to \langle X\rangle^{(D^K,\Pi^K)}_t$ in $L^1(\Omega)$ for each $t$.
\item The It\^o formula for $X^{(n)}$ converges term-by-term to the It\^o formula for $X$.
\end{enumerate}

\label{def:triple}
A \emph{causal derivation-divergence triple} is $(D, \delta, \Pi)$ where:
\begin{enumerate}
\item $D: \Dom(D) \subset \Lp{2}(\Omega) \to \Lp{2}(\Omega; \HH)$ is a densely-defined closed linear operator (the \emph{derivation}) with $1 \in \Dom(D)$ and $D1 = 0$.

\item $\delta: \Dom(\delta) \subset \Lp{2}(\Omega; \HH) \to \Lp{2}(\Omega)$ is the Hilbert space adjoint of $D$ (the \emph{divergence}):
\begin{equation}\label{eq:adjoint}
\E[F \delta(u)] = \E[\ip{DF}{u}_{\HH}], \quad F \in \Dom(D), \, u \in \Dom(\delta).
\end{equation}

\item $\Pi: \Lp{2}(\Omega; \HH) \to \Lp{2}(\Omega; \HH)$ is a bounded projection (``causal'' or ``predictable'') with $\Pi^2 = \Pi$.
\end{enumerate}

\label{ass:chain-rule}
There exists a subalgebra $\mathcal{A} \subset \Dom(D)$ dense in $\Lp{2}(\Omega)$ and stable under multiplication such that for $F \in \mathcal{A}$ and $\phi \in C_b^1(\R)$,
\begin{equation}\label{eq:chain-rule}
D(\phi(F)) = \phi'(F) DF.
\end{equation}
For $\phi \in C_b^1(\R^n)$ and $F = (F_1, \ldots, F_n)$ with $F_i \in \mathcal{A}$,
\[
D(\phi(F)) = \sum_{i=1}^n \partial_i \phi(F) DF_i.
\]

\label{ass:factorization}
For $F \in \mathcal{A}$,
\begin{equation}\label{eq:factorization}
(\Id - \E)F = \delta(\Pi DF).
\end{equation}

\label{def:intrinsic-bracket}
Let $Y = (Y_t)_{t \in [0,T]}$ be such that $Y_t \in \Dom(D)$ for a.e.\ $t$ and $t \mapsto \Pi DY_t$ lies in $\Lp{2}([0,T] \times \Omega; \HH)$. Define the \emph{intrinsic bracket}
\begin{equation}\label{eq:intrinsic-bracket}
\ibracket{Y}_t := \int_0^t \norm{\Pi DY_s}_{\HH}^2 \, ds.
\end{equation}

\label{def:ito-process}
A real process $Y = (Y_t)_{t \in [0,T]}$ is called a \emph{$(D, \delta, \Pi)$-It\^o process} if:
\begin{enumerate}
\item $t \mapsto Y_t$ is $\Lp{2}(\Omega)$-continuous and $Y_t \in \Dom(D)$ for each $t \in [0,T]$.

\item There exists $a \in \Lp{2}([0,T] \times \Omega)$ (the \emph{drift}) such that for all $t \in [0,T]$,
\begin{equation}\label{eq:ito-decomposition}
Y_t = Y_0 + \int_0^t a_s \, ds + \delta(\Pi DY \cdot \mathbf{1}_{[0,t]}),
\end{equation}
where the equality holds in $\Lp{2}(\Omega)$.

\item The map $t \mapsto \Pi DY_t$ lies in $\Lp{2}([0,T] \times \Omega; \HH)$.
\end{enumerate}

\label{ass:holder}
Let $Y$ be a $(D, \delta, \Pi)$-It\^o process with associated Hurst parameter $H < \tfrac{1}{4}$. We assume:
\begin{enumerate}
\item The map $t \mapsto DY_t$ is H\"older continuous in $\HH$ with exponent $\gamma > \tfrac{1}{4} - H$:
\[
\E[\norm{DY_t - DY_s}_{\HH}^2] \leq C |t - s|^{2\gamma}, \quad \gamma > \tfrac{1}{4} - H.
\]

\item The drift satisfies $\int_0^T |a_s|^p \, ds < \infty$ almost surely for some $p > \tfrac{2}{2H}$.

\item For $F \in C_b^1(\R)$, the product $F(Y_s) \Pi DY_s$ lies in $\Lp{2}([0,T] \times \Omega; \HH) \cap \Dom(\delta)$.
\end{enumerate}

\label{thm:product-rule}
Let $(D, \delta, \Pi)$ satisfy Assumptions~\ref{ass:chain-rule}--\ref{ass:orthogonal}. Let $F \in \Dom(D)$ and $u \in \Dom(\delta)$. Assume the pointwise product $Fu: \Omega \to \HH$ (given by $(Fu)(\omega) := F(\omega) u(\omega)$) satisfies:
\begin{enumerate}
\item $Fu \in \Lp{2}(\Omega; \HH)$,
\item $Fu \in \Dom(\delta)$.
\end{enumerate}
Then
\begin{equation}\label{eq:product-rule}
\delta(Fu) = F\delta(u) - \ip{DF}{u}_{\HH} \quad \text{in } \Lp{2}(\Omega).
\end{equation}

\label{lem:orthogonal-identity}
Under Assumption~\ref{ass:orthogonal}, for $F \in \Dom(D)$,
\begin{equation}\label{eq:orthogonal-identity}
\ip{DF}{\Pi DF}_{\HH} = \norm{\Pi DF}_{\HH}^2.
\end{equation}

\label{thm:operator-ito}
Let $(D, \delta, \Pi)$ satisfy Assumptions~\ref{ass:chain-rule}--\ref{ass:orthogonal}. Let $Y$ be a $(D, \delta, \Pi)$-It\^o process with drift $a$:
\begin{equation}\label{eq:Y-decomposition}
Y_t = Y_0 + \int_0^t a_s \, ds + \delta(\Pi DY \cdot \mathbf{1}_{[0,t]}).
\end{equation}
For processes with Hurst parameter $H < \tfrac{1}{4}$, assume additionally that Assumption~\ref{ass:holder} holds.

Let $\phi \in C_b^3(\R)$. Then for all $t \in [0,T]$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) = \phi(Y_0) + \int_0^t \phi'(Y_s) a_s \, ds + \delta(\phi'(Y) \Pi DY \cdot \mathbf{1}_{[0,t]}) + \frac{1}{2} \int_0^t \phi''(Y_s) \norm{\Pi DY_s}_{\HH}^2 \, ds,
\end{equation}
where the equality holds in $\Lp{2}(\Omega)$. Equivalently, in terms of the intrinsic bracket,
\begin{equation}\label{eq:operator-ito-bracket}
\phi(Y_t) = \phi(Y_0) + \int_0^t \phi'(Y_s) a_s \, ds + \delta(\phi'(Y) \Pi DY \cdot \mathbf{1}_{[0,t]}) + \frac{1}{2} \int_0^t \phi''(Y_s) \, d\ibracket{Y}_s.
\end{equation}

\label{lem:remainder}
For $\phi \in C_b^3(\R)$ and $Y$ a $(D, \delta, \Pi)$-It\^o process,
\[
\phi(Y_{t_{k+1}^n}) - \phi(Y_{t_k^n}) = \phi'(Y_{t_k^n})(Y_{t_{k+1}^n} - Y_{t_k^n}) + \frac{1}{2} \phi''(Y_{t_k^n})(Y_{t_{k+1}^n} - Y_{t_k^n})^2 + R_k,
\]
where the remainder satisfies
\begin{equation}\label{eq:remainder-bound}
\E[R_k^2] \leq C (\Delta t_n)^\alpha, \quad \alpha := \min\{3, 2H + 2\},
\end{equation}
for some constant $C$ depending on $\norm{\phi''}_\infty$, $\norm{\phi'''}_\infty$, and the regularity of $Y$.

\label{lem:skorokhod-isometry}
Let $(D, \delta, \Pi)$ satisfy Assumptions~\ref{ass:chain-rule}--\ref{ass:orthogonal}. Let $u \in \Lp{2}([0,T] \times \Omega; \HH) \cap \Dom(\delta)$ be such that:
\begin{enumerate}
\item $u$ is adapted: $\Pi u_s = u_s$ for a.e.\ $s$ (i.e., $u_s$ lies in the range of the predictable projection $\Pi$ at time $s$).
\item The map $s \mapsto u_s$ is H\"older continuous in $\Lp{2}(\Omega; \HH)$ with exponent $\gamma \geq H$.
\end{enumerate}
Then for any interval $[t_k, t_{k+1}]$,
\begin{equation}\label{eq:skorokhod-isometry}
\E[(\delta(u \cdot \mathbf{1}_{(t_k, t_{k+1}]}))^2] = \E\left[\int_{t_k}^{t_{k+1}} \norm{u_s}_{\HH}^2 \, ds\right] + O((\Delta t)^{2H+1}),
\end{equation}
where $\Delta t := t_{k+1} - t_k$.

\label{thm:multivariate-ito}
Let $Y = (Y^1, \ldots, Y^n)$ where each $Y^i$ is a $(D, \delta, \Pi)$-It\^o process:
\[
Y^i_t = Y^i_0 + \int_0^t a^i_s \, ds + \delta(\Pi DY^i \cdot \mathbf{1}_{[0,t]}).
\]
Let $\phi \in C_b^3(\R^n)$. Then
\begin{align}
\phi(Y_t) &= \phi(Y_0) + \sum_{i=1}^n \int_0^t \partial_i \phi(Y_s) a^i_s \, ds + \sum_{i=1}^n \delta(\partial_i \phi(Y) \Pi DY^i \cdot \mathbf{1}_{[0,t]}) \nonumber \\
&\quad + \frac{1}{2} \sum_{i,j=1}^n \int_0^t \partial_i \partial_j \phi(Y_s) \ip{\Pi DY^i_s}{\Pi DY^j_s}_{\HH} \, ds. \label{eq:multivariate-ito}
\end{align}

\label{def:DU-conditions}
A Volterra kernel $K$ satisfies the \emph{Decreusefond--\"Ust\"unel conditions} \cite{DecrUstunel1999} if:
\begin{enumerate}
\item $\int_0^T \int_0^t K(t,s)^2 \, ds \, dt < \infty$.

\item There exists $H \in (0,1)$ such that $|K(t,s)| \leq C |t - s|^{H - 1/2}$ for $s < t$.

\item $K$ has sufficient regularity for Malliavin calculus: specifically, the fractional derivative $\partial_t K(t,s)$ exists and satisfies integrability conditions ensuring $\Dom(\delta_X)$ is dense.
\end{enumerate}

\label{def:cameron-martin}
The \emph{Cameron--Martin space} $\HH_X$ is the completion of
\[
\HH_0 := \{K(t, \cdot) : t \in [0,T]\}
\]
under the inner product
\begin{equation}\label{eq:CM-inner-product}
\ip{K(t, \cdot)}{K(u, \cdot)}_{\HH_X} := R_X(t, u).
\end{equation}
The canonical representer $k_t \in \HH_X$ satisfies $\ip{h}{k_t}_{\HH_X} = h(t)$ for all $h \in \HH_X$.

\label{def:normalized-CM}
For fractional Brownian motion with $H \in (0,1)$, we normalize the Cameron--Martin space $\HH_H$ so that the representer $k_t := D_H B^H_t$ satisfies
\begin{equation}\label{eq:representer-norm}
\norm{k_t}_{\HH_H}^2 = 2H t^{2H-1}.
\end{equation}
This normalization ensures
\begin{equation}\label{eq:bracket-integral}
\int_0^t \norm{k_s}_{\HH_H}^2 \, ds = 2H \int_0^t s^{2H-1} \, ds = t^{2H}.
\end{equation}

\label{lem:fBM-bracket}
With the normalization of Definition~\ref{def:normalized-CM},
\begin{equation}\label{eq:fBM-bracket}
\ibracket{B^H}_t = t^{2H}.
\end{equation}

\label{def:triple}
A \emph{causal derivation-divergence triple} is $(D, \delta, \Pi)$ where:
\begin{enumerate}
\item $D: \Dom(D) \subset \Lp{2}(\Omega) \to \Lp{2}(\Omega; \HH)$ is a densely-defined closed linear operator (the \emph{derivation}) with $1 \in \Dom(D)$ and $D1 = 0$.

