\begin{equation}\label{eq:remainder-bound}
\E[R_k^2] \leq C (\Delta t_n)^\alpha, \quad \alpha := \min\{3, 2H+2\},
\end{equation}
for some constant $C$ depending on $\norm{\varphi''}_\infty$, $\norm{\varphi'''}_\infty$, and the regularity of $Y$.

