\item Each monomial $x^i$ pairs nontrivially only with the residue class $-i \bmod p$, and a nonzero partner always exists; the form is non-degenerate on the full polynomial space.
\item The self-pairing $\langle x^i, x^i\rangle = \E[X_T^{2i}]$ is nonzero iff $p \mid 2i$: for odd $p$ iff $p \mid i$, for even $p$ iff $\tfrac{p}{2} \mid i$.
\item For even $p$, the residue classes $\rho$ and $p-\rho$ with $\rho \not\equiv 0, \tfrac{p}{2}$ are each totally isotropic ($\langle x^i, x^{i'}\rangle = 0$ for $i \equiv i' \equiv \rho$) and pair only with one another, a hyperbolic coupling. For $p=4$ the classes $\rho=1$ and $\rho=3$ are isotropic and dual to each other; e.g. $\E[A_1^2] = \E[X_T^2] = 0$ while $\E[A_1 A_3] = \E[X_T^4] = 24 c_4 T \neq 0$.
\end{enumerate}
In all cases the form is non-degenerate, and the Appell system admits a biorthogonal dual basis $\{A_n^\ast\}$ with $\E[A_n A_m^\ast] = \delta_{nm}$; the dual partner $A_n^\ast$ lies in the coupled residue class $-n \bmod p$ and is therefore non-local in degree.

\label{prop:obs-ito}
Let $X$ be the order-$p$ pseudo-process. For every $f$ in the test class,
\begin{equation}
\label{eq:obs-ito-p}
\frac{d}{dt}\,\E[f(X_t)] = c_p\,\E\bigl[f^{(p)}(X_t)\bigr].
\end{equation}
The observable correction operator is $\mathcal G = c_p\,\partial_x^p$, of order $p$.

\label{def:carre-p}
The order-$p$ carr\'e du champ is the fully polarized leading symbol of the observable correction operator $\mathcal G = c_p\,\partial_x^p$: the symmetric $p$-linear form
\begin{equation}
\Gamma^{(p)}(f_1,\ldots,f_p) := c_p\, p!\, \prod_{i=1}^p f_i'(x),
\end{equation}
with diagonal value $\Gamma^{(p)} := \Gamma^{(p)}(x,\ldots,x) = c_p\, p!$ (taking $f_i(x)=x$).

\label{prop:carre-correction}
The It\^o-$p$ correction term equals $\tfrac{1}{p!}f^{(p)}(X)\,\Gamma^{(p)}$:
\begin{equation}
c_p\,f^{(p)}(X_s)\, ds = \frac{1}{p!}\,f^{(p)}(X_s)\,\Gamma^{(p)}\, ds.
\end{equation}
For $p=2$ with the Brownian normalization $c_2 = \tfrac12$, this is $\Gamma^{(2)} = 1$ and the correction $\tfrac12 f''(X)\,ds = \tfrac12 f''(X)\,d\langle X\rangle_s$ — the classical quadratic-variation It\^o correction, with $\Gamma^{(2)}$ the quadratic-variation density.

\label{thm:operator-ito}
Let $X$ be the order-$p$ pseudo-process. For $f$ in the test class,
\begin{equation}
\label{eq:operator-ito-p}
f(X_T) - f(X_0) = \delta\bigl(f'(X_\bullet)\bigr) + \frac{1}{p!}\int_0^T f^{(p)}(X_s)\,\Gamma^{(p)}\, ds,
\end{equation}
where $\delta(f'(X_\bullet)) = \int_0^T f'(X_s)\,dX_s$ is the divergence (martingale part) and the second term is the order-$p$ energy contraction. Moreover, the correction term is the \emph{unique} adapted process of the form $\int_0^t \phi(X_s)\,ds$ for which the remainder $f(X_t) - f(X_0) - \int_0^t \phi(X_s)\,ds$ is centered; necessarily $\phi = c_p f^{(p)} = \tfrac{1}{p!}f^{(p)}\Gamma^{(p)}$.

\label{def:operator_derivative}
The \emph{operator derivative} $D_X F$ is defined, when it exists, as the unique element of $\Lp{2}(\Omega; \HH_X)$ satisfying
\begin{equation}\label{eq:riesz_def}
\E[F \cdot \delta_X(u)] = \E[\ip{D_X F}{u}_{\HH_X}] \quad \text{for all } u \in \HH_X.
\end{equation}

\label{thm:tier1_inevitable}
Let $\HH$ be a Hilbert space, $\delta: \HH \to \Lp{2}(\Omega)$ a closed linear operator with $\E[\delta(u)] = 0$ for all $u \in \HH$. Define $D: \Dom(D) \subset \Lp{2}(\Omega) \to \Lp{2}(\Omega; \HH)$ by the Riesz condition \eqref{eq:riesz_def}. Then:
\begin{enumerate}[label=(\alph*)}
    \item \textbf{Linearity:} $D(\alpha F + \beta G) = \alpha DF + \beta DG$.
    \item \textbf{Closedness:} $D$ is a closed operator.
    \item \textbf{Adjointness:} $\delta = D^*$ as unbounded operators.
    \item \textbf{Constants:} $D(c) = 0$ for any constant $c \in \R$.
    \item \textbf{Uniqueness:} $D$ is the unique operator satisfying \eqref{eq:riesz_def}.
\end{enumerate}

\label{thm:representation}
Assume $X$ has the representation property: every $\FF_T^X$-measurable $F \in \Lp{2}(\Omega)$ satisfies $F - \E[F] \in \mathrm{Range}(\delta_X)$. Then
\begin{equation}\label{eq:clark_ocone}
F = \E[F] + \delta_X(\Pi_X D_X F).
\end{equation}

\label{def:isometry}
The stochastic integral $\delta_X$ is \emph{isometric} if for all predictable $u, v \in \HH_X$:
\begin{equation}\label{eq:isometry}
\E[\delta_X(u) \cdot \delta_X(v)] = \E[\ip{u}{v}_{\HH_X}].
\end{equation}

\begin{itemize}
    \item Brownian motion: It\^o isometry $\E[(\int u \, dW)(\int v \, dW)] = \E[\int uv \, dt]$.
    \item Square-integrable martingales: $\E[(\int u \, dM)(\int v \, dM)] = \E[\int uv \, d\langle M \rangle]$.
    \item Discrete innovations with identity covariance.
\end{itemize}

\begin{itemize}
    \item Fractional Brownian motion with $H \neq 1/2$: the Skorokhod integral is not isometric.
    \item Volterra processes with non-identity kernel.
\end{itemize}

\label{thm:tier2_equivalence}
Assume $\delta_X$ is isometric. Then:
\begin{enumerate}[label=(\alph*)]
    \item $D_X(\delta_X(u)) = u$ for predictable $u \in \HH_X$.
    \item $\Var(F) = \E[\norm{\Pi_X D_X F}_{\HH_X}^2]$ when $F - \E[F] = \delta_X(\Pi_X D_X F)$.
\end{enumerate}

\label{thm:variance_correction}
Let $X$ be a Gaussian process with covariance $R(s,t) = \E[X_s X_t]$ and Cameron-Martin space $\HH_X$. For $F \in \Lp{2}(\Omega)$ with $F - \E[F] = \delta_X(\Pi_X D_X F)$:
\begin{equation}\label{eq:variance_corrected}
\Var(F) = \E\left[ \int_0^T \int_0^T (\Pi_X D_X F)_s (\Pi_X D_X F)_t \, R(ds, dt) \right],
\end{equation}
where $R(ds, dt)$ denotes integration against the covariance measure.

\label{def:leibniz}
The operator derivative $D_X$ satisfies the \emph{Leibniz condition} if for $F, G$ in a suitable domain:
\begin{equation}\label{eq:leibniz}
D_X(FG) = F D_X G + G D_X F.
\end{equation}

\label{thm:leibniz_levy}
Let $X$ be a L\'evy process with Gaussian component $W$ and compensated jump measure $\tilde{N}$. The operator derivative splits as $D_X = D_W + D_N$, where:
\begin{enumerate}[label=(\alph*)]
    \item $D_W$ (Gaussian part) satisfies standard Leibniz: $D_W(FG) = F D_W G + G D_W F$.
    \item $D_N$ (jump part) satisfies modified Leibniz:
    \begin{equation}\label{eq:leibniz_jump}
    D_N(FG)_{t,z} = F D_N G_{t,z} + G D_N F_{t,z} + D_N F_{t,z} \cdot D_N G_{t,z}.
    \end{equation}
\end{enumerate}

\label{thm:representation_survives}
Let $X$ be a process with closed stochastic integral $\delta_X$ satisfying the representation property. Then for any $\FF_T^X$-measurable $F \in \Lp{2}(\Omega)$:
\[
F = \E[F] + \delta_X(\Pi_X D_X F)
\]
regardless of whether:
\begin{itemize}
    \item $\delta_X$ is isometric (Tier 2);
    \item $D_X$ satisfies Leibniz (Tier 3);
    \item $X$ is Markov;
    \item $X$ is a semimartingale.
\end{itemize}

For fBM with any Hurst parameter $H \in (0,1)$:
\[
F = \E[F] + \int_0^T (\Pi_H D_H F)_t \, dB_t^H.
\]
This holds even though:
\begin{itemize}
    \item The It\^o isometry fails for $H \neq 1/2$ (Tier 2 fails);
    \item fBM is not a semimartingale for $H \neq 1/2$.
\end{itemize}

\label{thm:energy_correction}
Let $X_t$ be a solution of an SPDE driven by a Gaussian process with covariance kernel $R$. Then the energy $\mathcal{E}(t) = \E[\norm{X_t}^2]$ satisfies:
\begin{equation}\label{eq:energy_memory}
\mathcal{E}(t) = \norm{S_t f}^2 + \int_0^t \int_0^t K(t-r) K(t-s) \, R(dr, ds),
\end{equation}
where $S_t$ is the solution semigroup, $K$ is the memory kernel, and $R(dr, ds)$ is the covariance measure.

When $R(dr, ds) = \delta(r-s) dr$ (white noise / Brownian motion), this reduces to the standard energy identity:
\[
\mathcal{E}(t) = \norm{S_t f}^2 + \int_0^t K(t-r)^2 \, dr.
\]

\label{thm:ito_jump}\label{thm:ito_correction}
Let $X = W + J$ where $W$ is Brownian and $J$ is a pure jump process with L\'evy measure $\nu$. For $f \in C^2(\R)$:
\begin{align*}
f(X_t) &= f(X_0) + \int_0^t f'(X_{s-}) \, dW_s + \frac{1}{2} \int_0^t f''(X_s) \, ds \\
&\quad + \int_0^t \int_\R \left[ f(X_{s-} + z) - f(X_{s-}) - f'(X_{s-}) z \right] \tilde{N}(ds, dz).
\end{align*}
The term in brackets is the \emph{jump correction}---it cannot be written as $f'(X) dJ$ because jumps cause discrete changes.

\label{prop:semigroup_properties}
The family $(\Sg)_{t \geq 0}$ satisfies:
\begin{enumerate}[label=(\alph*)]
    \item $S_0^{(H_1,H_2)} = I$ (identity);
    \item $\norm{\Sg f}_{\Lp{2}} \leq \norm{f}_{\Lp{2}}$ for all $t \geq 0$ (contraction);
    \item $u(t) = \Sg f$ solves $\CapD u = A_{H_1} u$ with $u(0) = f$ in the classical sense for $f \in \Hs{2H_1}(\R)$.
\end{enumerate}

\label{def:kernel}
For $H_2 \in (0, 1/2)$, define the \emph{memory kernel}
\[
K_{H_2}(t) = \frac{t^{2H_2 - 1}}{\Gamma(2H_2)}, \qquad t > 0.
\]

\label{def:mild}
A stochastic process $(X_t)_{t \geq 0}$ is a \emph{mild solution} of \eqref{eq:main} if it is $(\Ft_t)$-adapted, has paths in $C([0,T]; \Lp{2}(\R))$ almost surely, and satisfies
\begin{equation}\label{eq:mild}
X_t = \Sg f + \int_0^t K_{H_2}(t-s) \, S_{t-s}^{(H_1,H_2)} \, dB_s
\end{equation}
for all $t \in [0,T]$, where the stochastic integral is interpreted in the $\Lp{2}(\R)$-valued It\^o sense.

\label{prop:ML_basic}
Let $\alpha \in (0,1)$. The Mittag-Leffler function $E_\alpha: \mathbb{C} \to \mathbb{C}$ satisfies:
\begin{enumerate}[label=(\alph*)]
    \item $E_\alpha(0) = 1$;
    \item $E_1(z) = e^z$;
    \item $E_\alpha(-t)$ is completely monotone for $t \geq 0$: $(-1)^n \frac{d^n}{dt^n} E_\alpha(-t) \geq 0$;
    \item $0 < E_\alpha(-t) \leq 1$ for all $t \geq 0$.
\end{enumerate}

\label{prop:ML_asymp}
For $\alpha \in (0,1)$ and $t > 0$:
\begin{enumerate}[label=(\alph*)]
    \item As $t \to 0^+$: $E_\alpha(-t) = 1 - \frac{t}{\Gamma(1+\alpha)} + O(t^2)$;
    \item As $t \to \infty$: $E_\alpha(-t) = \frac{t^{-1}}{\Gamma(1-\alpha)} + O(t^{-2})$.
\end{enumerate}

\label{prop:caputo_props}
Let $\alpha \in (0,1)$. The Caputo derivative $\partial_t^\alpha$ satisfies:
\begin{enumerate}[label=(\alph*)]
    \item \textbf{Linearity:} $\partial_t^\alpha(au + bv) = a \partial_t^\alpha u + b \partial_t^\alpha v$;
    \item \textbf{Constants:} $\partial_t^\alpha c = 0$ for any constant $c$;
    \item \textbf{Power functions:} For $\beta > 0$, $\partial_t^\alpha t^\beta = \frac{\Gamma(\beta+1)}{\Gamma(\beta+1-\alpha)} t^{\beta - \alpha}$;
    \item \textbf{Laplace transform:} $\mathcal{L}[\partial_t^\alpha u](s) = s^\alpha \mathcal{L}[u](s) - s^{\alpha-1} u(0)$.
\end{enumerate}

\label{thm:frac_sg_props}
Let $H_1, H_2 \in (0,1)$ with $2H_2 < 1$. Define
\[
\Sg f = \mathcal{F}^{-1}\left[ E_{2H_2}(-c_{H_1} \abs{\xi}^{2H_1} t^{2H_2}) \hat{f}(\xi) \right].
\]
Then:
\begin{enumerate}[label=(\alph*)]
    \item \textbf{Well-defined:} $\Sg: \Lp{2}(\R) \to \Lp{2}(\R)$ is a bounded linear operator for each $t \geq 0$;
    \item \textbf{Initial condition:} $S_0^{(H_1,H_2)} = I$;
    \item \textbf{Contraction:} $\norm{\Sg f}_2 \leq \norm{f}_2$ for all $t \geq 0$;
    \item \textbf{Strong continuity:} $t \mapsto \Sg f$ is continuous from $[0,\infty)$ to $\Lp{2}(\R)$;
    \item \textbf{Solves the homogeneous equation:} For $f \in \Hs{2H_1}(\R)$, $u(t) = \Sg f$ satisfies
    \[
    \partial_t^{2H_2} u(t) = A_{H_1} u(t), \qquad u(0) = f.
    \]
\end{enumerate}

\label{def:cylindrical}
A \emph{cylindrical Brownian motion} on $\Lp{2}(\R)$ is a family $(B_t)_{t \geq 0}$ of bounded linear operators from $\Lp{2}(\R)$ to $\Lp{2}(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)]
    \item For each $h \in \Lp{2}(\R)$, $(B_t h)_{t \geq 0}$ is a real-valued Brownian motion with $\E[(B_t h)^2] = t \norm{h}_2^2$;
    \item For $h_1, h_2 \in \Lp{2}(\R)$, $\E[B_t h_1 \cdot B_s h_2] = (t \wedge s) \ip{h_1}{h_2}$.
\end{enumerate}

\label{thm:existence}
Let $f \in \Lp{2}(\R)$ and $H_1 \in (0,1)$, $H_2 \in (0,1/2)$. Then the mild equation
\begin{equation}\label{eq:mild_repeat}
X_t = \Sg f + \int_0^t K_{H_2}(t-s) S_{t-s}^{(H_1,H_2)} \, dB_s
\end{equation}
admits a unique solution $X \in \Lp{2}(\Omega; C([0,T]; \Lp{2}(\R)))$ for any $T > 0$. Moreover,
\[
\sup_{t \in [0,T]} \E\left[ \norm{X_t}_2^2 \right] < \infty.
\]

\label{thm:spectral}
Let $X_t$ be the mild solution of \eqref{eq:mild_repeat}. Then for each $\xi \in \R$, the Fourier transform $\hat{X}(t,\xi)$ satisfies
\begin{equation}\label{eq:fourier_solution}
\hat{X}(t,\xi) = E_{2H_2}(-\lambda_\xi t^{2H_2}) \hat{f}(\xi) + \int_0^t (t-s)^{2H_2-1} E_{2H_2, 2H_2}(-\lambda_\xi (t-s)^{2H_2}) \, d\hat{B}(s,\xi),
\end{equation}
where $\lambda_\xi = c_{H_1}\abs{\xi}^{2H_1}$ and $E_{\alpha,\beta}$ is the two-parameter Mittag-Leffler function.

\label{thm:energy}
Let $X_t$ be the mild solution of \eqref{eq:mild_repeat}. Then
\begin{equation}\label{eq:energy_identity}
\mathcal{E}(t) = \norm{\Sg f}_2^2 + \int_0^t K_{H_2}(t-s)^2 \, \mathcal{I}(t-s) \, ds,
\end{equation}
where
\[
\mathcal{I}(r) := \int_\R E_{2H_2}(-c_{H_1}\abs{\xi}^{2H_1} r^{2H_2})^2 \, d\xi = C_{H_1, H_2} \, r^{-H_2/H_1}
\]
for an explicit constant $C_{H_1, H_2} > 0$.

\label{cor:energy_growth}
The energy satisfies
\[
\mathcal{E}(t) \leq \norm{f}_2^2 + C \, t^{4H_2 - 1 - H_2/H_1}
\]
for $t \geq 1$, where the exponent $4H_2 - 1 - H_2/H_1$ determines whether energy grows, decays, or remains bounded.

following_proof:
The deterministic part satisfies $\norm{\Sg f}_2 \leq \norm{f}_2$. For the stochastic part:
\begin{align*}
\int_0^t K_{H_2}(r)^2 \mathcal{I}(r) \, dr &= C_{H_1,H_2} \int_0^t \frac{r^{2(2H_2-1)}}{r^{H_2/H_1}} \, dr \\
&= C_{H_1,H_2} \int_0^t r^{4H_2 - 2 - H_2/H_1} \, dr \\
&= C_{H_1,H_2} \cdot \frac{t^{4H_2 - 1 - H_2/H_1}}{4H_2 - 1 - H_2/H_1}
\end{align*}
when $4H_2 - 1 - H_2/H_1 \neq 0$.

Formally, using the equation $\partial_t^{2H_2} u = A_{H_1} u$:
\begin{align*}
\partial_t^{2H_2} \norm{u}_2^2 &= 2 \ip{\partial_t^{2H_2} u}{u} = 2 \ip{A_{H_1} u}{u} = -2 c_{H_1} \ip{(-\Delta)^{H_1} u}{u} = -2 \mathcal{D}_{H_1}[u].
\end{align*}
The rigorous justification requires care with the fractional chain rule; see \cite{KilbasST2006}, Section 2.7.

statement:
\label{thm:regularity}
Let $X_t$ be the mild solution with $f \in \Lp{2}(\R)$. For any $t > 0$ and $s \geq 0$, $X_t \in \Hs{s}(\R)$ almost surely. More precisely, for $s \in [0, 2H_1]$:
\begin{equation}\label{eq:sobolev_bound}
\E\left[ \norm{X_t}_{\Hs{s}}^2 \right] \leq C_s \left( t^{-s/H_1} \norm{f}_2^2 + t^{4H_2 - 1 - (s+H_2)/H_1} \right).
\end{equation}

following_proof:
We bound the Sobolev norm via Fourier analysis.

\medskip
\noindent\textbf{Step 1: Deterministic part.}

For $u(t) = \Sg f$:
\begin{align*}
\norm{u(t)}_{\Hs{s}}^2 &= \int_\R (1 + \abs{\xi}^2)^s \abs{E_{2H_2}(-c_{H_1}\abs{\xi}^{2H_1} t^{2H_2})}^2 \abs{\hat{f}(\xi)}^2 \, d\xi.
\end{align*}
For small $\abs{\xi}$ (say $\abs{\xi} \leq t^{-H_2/H_1}$), use $E_{2H_2} \leq 1$:
\[
\int_{\abs{\xi} \leq t^{-H_2/H_1}} (1 + \abs{\xi}^2)^s \abs{\hat{f}(\xi)}^2 \, d\xi \leq (1 + t^{-2H_2/H_1})^s \norm{f}_2^2.
\]
For large $\abs{\xi}$ (i.e., $\abs{\xi} > t^{-H_2/H_1}$), use $E_{2H_2}(-\tau) \leq C(1+\tau)^{-1}$:
\begin{align*}
\abs{\xi}^{2s} E_{2H_2}(-c_{H_1}\abs{\xi}^{2H_1} t^{2H_2})^2 &\leq C^2 \abs{\xi}^{2s} (c_{H_1}\abs{\xi}^{2H_1} t^{2H_2})^{-2} \\
&= \frac{C^2}{c_{H_1}^2 t^{4H_2}} \abs{\xi}^{2s - 4H_1}.
\end{align*}
For $s \leq 2H_1$, this is bounded by $C t^{-4H_2} \abs{\xi}^{-2(2H_1-s)}$, which is integrable for $\abs{\xi} > 1$ when $2H_1 - s < 1/2$. For general $s \leq 2H_1$, we obtain
\[
\norm{u(t)}_{\Hs{s}}^2 \leq C_s t^{-2sH_2/H_1} \norm{f}_2^2.
\]

\medskip
\noindent\textbf{Step 2: Stochastic part.}

Let $I_t = \int_0^t K_{H_2}(t-r) S_{t-r}^{(H_1,H_2)} \, dB_r$. By It\^o isometry in $\Hs{s}$:
\begin{align*}
\E[\norm{I_t}_{\Hs{s}}^2] &= \int_0^t K_{H_2}(r)^2 \int_\R (1+\abs{\xi}^2)^s E_{2H_2}(-c_{H_1}\abs{\xi}^{2H_1} r^{2H_2})^2 \, d\xi \, dr.
\end{align*}
Using the scaling argument from the energy proof, the inner integral behaves like $r^{-(s+H_2)/H_1}$ for small $r$. Thus:
\begin{align*}
\E[\norm{I_t}_{\Hs{s}}^2] &\lesssim \int_0^t r^{2(2H_2-1)} r^{-(s+H_2)/H_1} \, dr \\
&= \int_0^t r^{4H_2 - 2 - (s+H_2)/H_1} \, dr.
\end{align*}
This converges for $4H_2 - 2 - (s+H_2)/H_1 > -1$, i.e., $4H_2 - 1 > (s+H_2)/H_1$, which restricts the admissible regularity $s$.

\medskip
\noindent\textbf{Step 3: Combining bounds.}

Adding the deterministic and stochastic contributions yields \eqref{eq:sobolev_bound}.

statement:
\label{thm:asymptotics}
Let $f \in \Lp{1}(\R) \cap \Lp{2}(\R)$. Then the deterministic evolution satisfies:
\begin{enumerate}[label=(\alph*)]
    \item \textbf{$\Lp{2}$ decay:}
    \[
    \norm{\Sg f}_2 \sim C_{H_1,H_2} \, t^{-H_2/(2H_1)} \norm{f}_1 \quad \text{as } t \to \infty.
    \]
    \item \textbf{$\Lp{\infty}$ decay:}
    \[
    \norm{\Sg f}_\infty \leq C \, t^{-H_2/H_1} \norm{f}_1 \quad \text{for } t \geq 1.
    \]
\end{enumerate}

\label{def:resolvent}
A family of bounded linear operators $(R_t)_{t \geq 0}$ on $H$ is called a \emph{resolvent family} (or solution family) for the abstract fractional Cauchy problem
\[
\partial_t^\alpha u(t) = A u(t), \qquad u(0) = f,
\]
if:
\begin{enumerate}[label=(\roman*)]
    \item $R_0 = I$;
    \item $t \mapsto R_t f$ is continuous for each $f \in H$;
    \item For $f \in D(A)$, $R_t f \in D(A)$, $A R_t f = R_t A f$, and
    \[
    R_t f = f + \frac{1}{\Gamma(\alpha)} \int_0^t (t-s)^{\alpha-1} A R_s f \, ds.
    \]
\end{enumerate}

following_proof:
For $f \in \Hs{2H_1}$, using $E_{2H_2}(-\lambda t^{2H_2}) = 1 - \frac{\lambda t^{2H_2}}{\Gamma(1+2H_2)} + O(t^{4H_2})$:
\begin{align*}
\frac{\Sg f - f}{t^{2H_2}} &= \mathcal{F}^{-1}\left[ \frac{E_{2H_2}(-c_{H_1}\abs{\xi}^{2H_1} t^{2H_2}) - 1}{t^{2H_2}} \hat{f}(\xi) \right] \\
&\to \mathcal{F}^{-1}\left[ \frac{-c_{H_1}\abs{\xi}^{2H_1}}{\Gamma(1+2H_2)} \hat{f}(\xi) \right] = \frac{A_{H_1} f}{\Gamma(1+2H_2)}
\end{align*}
as $t \to 0^+$, by dominated convergence (using $f \in \Hs{2H_1}$).

statement:
\label{thm:analyticity}
The resolvent family $(S_t^{(H_1,H_2)})_{t \geq 0}$ extends to an analytic family in a sector:
\[
\Sigma_\theta := \{ z \in \mathbb{C} : z \neq 0, \abs{\arg z} < \theta \}
\]
for some $\theta > 0$ depending on $H_2$.

\label{thm:correct_energy}
For $U_t$ given by \eqref{eq:mild_solution},
\begin{equation}\label{eq:correct_energy}
\E[|U_t|^2] = \int_0^t \int_0^t e^{-\lambda(t-s)} e^{-\lambda(t-r)} \, dR_H(s,r),
\end{equation}
where $dR_H(s,r)$ denotes integration against the covariance measure. Explicitly,
\begin{equation}\label{eq:correct_energy_explicit}
\E[|U_t|^2] = H(2H-1) \int_0^t \int_0^t e^{-\lambda(2t-s-r)} |s-r|^{2H-2} \, ds \, dr + \text{boundary terms}.
\end{equation}
For $H = 1/2$, the double integral collapses to a single integral (It\^o isometry).

\label{thm:no_derivation}
Let $X$ be a pure jump process with $\Prob(J_k \neq 0) > 0$. There exists no linear operator
\[
D: \AAA \to \Lp{2}(\Omega; \HH)
\]
defined on a dense algebra $\AAA$ of $X$-measurable functionals such that:
\begin{enumerate}[label=(\roman*)]
    \item $D$ agrees with the difference operator on linear functionals: $D(X_T) = $ ``add-a-jump'' in the sense of \eqref{eq:difference_op};
    \item $D$ satisfies the Leibniz rule: $D(FG) = F \cdot DG + G \cdot DF$.
\end{enumerate}

following_proof:
Suppose such a $D$ exists. Take $F = G = X_T \in \AAA$. By condition (ii):
\begin{equation}\label{eq:leibniz_applied}
D(X_T^2) = X_T \cdot D(X_T) + X_T \cdot D(X_T) = 2 X_T \cdot D(X_T).
\end{equation}

But by condition (i), $D$ must act as the difference operator on polynomial functionals (by density and linearity). Applying the difference operator to $F = X_T^2$:
\begin{align}
(D_N(X_T^2))_{t,z} &= (X_T + z)^2 - X_T^2 \notag \\
&= X_T^2 + 2 X_T z + z^2 - X_T^2 \notag \\
&= 2 X_T z + z^2 \notag \\
&= 2 X_T \cdot (D_N X_T)_{t,z} + z^2. \label{eq:actual_difference}
\end{align}

Comparing \eqref{eq:leibniz_applied} and \eqref{eq:actual_difference}:
\[
2 X_T \cdot D(X_T) = 2 X_T \cdot D(X_T) + z^2.
\]
This requires $z^2 = 0$ for all jump sizes $z$. But $\Prob(J_k \neq 0) > 0$ by assumption, so there exist $z \neq 0$. Contradiction.

statement:
\label{cor:ito_jumps}
For a L\'evy process $X$ and $f \in C^2(\R)$, the It\^o formula must include the jump correction:
\begin{align*}
f(X_t) &= f(X_0) + \int_0^t f'(X_{s-}) \, dX_s^c + \frac{1}{2} \int_0^t f''(X_s) \, d[X^c]_s \\
&\quad + \sum_{0 < s \leq t} \left[ f(X_s) - f(X_{s-}) - f'(X_{s-}) \Delta X_s \right],
\end{align*}
where $X^c$ is the continuous part and the sum is over jump times. The bracketed term is exactly $\frac{1}{2} f''(\xi_s) (\Delta X_s)^2$ for some $\xi_s$ between $X_{s-}$ and $X_s$---the ``correction'' that cannot be absorbed into the other terms.

\label{conj:nongaussian}
Let $M$ be a continuous martingale that is not Gaussian. The operator derivative $D_M$ is well-defined via Riesz duality. Does $D_M$ satisfy the Leibniz rule?

Neither the Gaussian integration-by-parts formula (which gives Leibniz for Gaussian processes) nor the algebraic argument (which gives Leibniz for discrete innovations) applies. This is the main open problem in the tier classification.

