\label{rem:scope}
For completeness, we note what the operator framework does \textbf{not} simplify:
\begin{itemize}
\item \textbf{Rough differential equations:} For solving $dY_t = b(Y_t) dB^H_t$ with $H \leq \frac{1}{3}$, rough path lifts (including Lévy area) are still required. Our framework addresses change-of-variables, not integration theory for RDEs.
\item \textbf{Pathwise properties:} Our results hold in $L^2(\Omega)$. Almost-sure path regularity requires additional arguments.
\end{itemize}

\label{def:triple}
A triple $(D, \delta, \Pi)$ where:
\begin{enumerate}
\item $D : \Dom(D) \subset L^2(\Omega) \to L^2(\Omega; H)$ is a densely-defined closed derivation with $D\mathbf{1} = 0$.
\item $\delta : \Dom(\delta) \subset L^2(\Omega; H) \to L^2(\Omega)$ is the Hilbert adjoint of $D$:
\[\E[F \delta(u)] = \E[\inner{DF}{u}_H], \quad F \in \Dom(D), u \in \Dom(\delta).\]
\item $\Pi : L^2(\Omega; H) \to L^2(\Omega; H)$ is an orthogonal projection.
\end{enumerate}

\label{ass:holder_rough}
For $Y$ with Hurst parameter $H < \frac{1}{4}$:
\begin{enumerate}
\item $\E[\norm{D Y_t - D Y_s}_H^2] \leq C |t - s|^{2\gamma}$ for $\gamma > \frac{1}{4} - H$.
\item $\int_0^T |a_s|^p\, ds < \infty$ a.s.\ for some $p > \frac{2}{2H}$.
\item For $F \in C_b^1(\R)$, the map $s \mapsto F(Y_s) \Pi D Y_s$ lies in $\Dom(\delta)$.
\end{enumerate}

\label{thm:product_rule}
Let $F \in \Dom(D)$ and $u \in \Dom(\delta)$ with $Fu \in \Dom(\delta)$. Then
\[\delta(Fu) = F \delta(u) - \inner{DF}{u}_H \quad \text{in } L^2(\Omega).\]

\label{thm:main_ito}
Let $Y$ be a $(D, \delta, \Pi)$-Itô process with drift $a$, and $\varphi \in C_b^2(\R)$. For $H < \frac{1}{4}$, assume Assumption~\ref{ass:holder_rough}. Then
\begin{multline*}
\varphi(Y_t) = \varphi(Y_0) + \int_0^t \varphi'(Y_s) a_s\, ds + \delta(\varphi'(Y) \Pi D Y \cdot \mathbf{1}_{[0,t]})\\
+ \frac{1}{2} \int_0^t \varphi''(Y_s) \norm{\Pi D Y_s}_H^2\, ds.
\end{multline*}

\label{thm:discretization_convergence}
For the Riemann sum approximation
\begin{multline*}
S_n(t) := \varphi(Y_0) + \sum_{k} \left[ \varphi'(Y_{t_k}) \int_{t_k}^{t_{k+1}} a_s\, ds + \varphi'(Y_{t_k}) \delta(\Pi D Y \cdot \mathbf{1}_{(t_k, t_{k+1}]})\right.\\
\left. + \frac{1}{2} \varphi''(Y_{t_k}) \int_{t_k}^{t_{k+1}} \norm{\Pi D Y_s}_H^2\, ds \right],
\end{multline*}
we have
\[\norm{\varphi(Y_t) - S_n(t)}_{L^2} \leq C (\Delta t)^{\alpha/2}, \quad \alpha = \min\{3, 2H+2\}.\]

\label{def:normalized_rkhs}
For $B^H$, normalize $H_H$ so that $\norm{k_t}_{H_H}^2 = 2H t^{2H-1}$, ensuring
\[\int_0^t \norm{k_s}_{H_H}^2 ds = t^{2H}.\]

\label{def:operator_deriv}
Let $X$ be a process with a closed stochastic integral $\delta_X \colon \HX \to L^2(\Omega)$ on a real separable Hilbert space~$\HX$ (called the \emph{energy space}). For $F \in L^2(\Omega)$ such that the functional $u \mapsto \E[F \cdot \delta_X(u)]$ is continuous on~$\HX$, the \emph{operator derivative} $D_X F$ is defined as the unique element of $L^2(\Omega; \HX)$ satisfying
\begin{equation}\label{eq:adjoint_def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HX}] \quad \text{for all } u \in \HX.
\end{equation}
Uniqueness holds in $L^2(\Omega; \HX)$: if $G_1, G_2$ both satisfy~\eqref{eq:adjoint_def}, then $G_1 = G_2$ almost surely. Existence follows from the Riesz representation theorem when the functional $u \mapsto \E[F \cdot \delta_X(u)]$ is continuous on~$\HX$; this holds automatically when $\delta_X$ is continuous (e.g., bounded or isometric).

\label{cond:isometry}
The stochastic integral $\delta_X$ satisfies: for predictable $u, v \in \HX$,
\begin{equation}\label{eq:isometry}
\E[\delta_X(u) \cdot \delta_X(v)] = \E[\langle u, v \rangle_{\HX}].
\end{equation}

\label{rem:isometry_examples}
Condition~\ref{cond:isometry} holds for: Brownian motion (It\^o isometry), square-integrable martingales (by the definition of the energy space norm via $\langle M \rangle$), and discrete innovations with identity covariance.

It fails for: fractional Brownian motion with $H \neq 1/2$ (the divergence integral is not isometric on the Cameron--Martin space $\HH$).

\label{cond:leibniz}
For $F, G$ in a suitable domain (e.g., smooth cylindrical functionals or $\mathbb{D}^{1,2} \cap L^4(\Omega)$ in the Gaussian case):
\begin{equation}\label{eq:leibniz}
D_X(FG) = F\, D_X G + G\, D_X F.
\end{equation}

\label{prop:leibniz_sufficient}
The Leibniz condition (Condition~\ref{cond:leibniz}) holds when:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $X$ is Gaussian (Section~\ref{sec:gaussian}).
\item $D_X$ is realized as partial differentiation with respect to independent innovations (Section~\ref{sec:discrete}).
\end{enumerate}

\label{thm:gaussian}
Let $X$ be a Gaussian process with Cameron--Martin space~$\HX$ and Malliavin derivative $D^{\Mall}$ defined on the Malliavin--Sobolev space $\mathbb{D}^{1,2}$. Then:
\begin{enumerate}[label=\textup{(\alph*)}]
\item $D_X$ agrees with $D^{\Mall}$ on $\mathbb{D}^{1,2}$.
\item All three tiers hold.
\end{enumerate}

\label{thm:leibniz_gaussian}
Let $X$ be a Gaussian Volterra process with covariance $R(s,t) = \int_0^{s \wedge t} K(s,r) K(t,r)\, dr$. Let $\HX$ be the Cameron--Martin space with reproducing kernel~$R$, and let $D_X$ be the operator derivative defined by~\eqref{eq:adjoint_def}. Then for smooth cylindrical functionals
\[
F = f(X_{t_1}, \ldots, X_{t_n}), \quad G = g(X_{s_1}, \ldots, X_{s_m}),
\]
with $f \in C_b^\infty(\R^n)$, $g \in C_b^\infty(\R^m)$, the Leibniz rule holds:
\begin{equation}\label{eq:leibniz_gaussian}
D_X(FG) = F\, D_X G + G\, D_X F.
\end{equation}

\label{prop:levy_modified}
For smooth functionals $F, G$ of a L\'evy process:
\begin{align}
D^W(FG) &= F\, D^W G + G\, D^W F, \label{eq:levy_gaussian_leibniz} \\
D^{\widetilde{\mathcal{N}}}(FG)_{t,z} &= F\, D^{\widetilde{\mathcal{N}}} G_{t,z} + G\, D^{\widetilde{\mathcal{N}}} F_{t,z} + D^{\widetilde{\mathcal{N}}} F_{t,z} \cdot D^{\widetilde{\mathcal{N}}} G_{t,z}. \label{eq:levy_jump_leibniz}
\end{align}
The Gaussian component~\eqref{eq:levy_gaussian_leibniz} satisfies the standard Leibniz rule. The jump component~\eqref{eq:levy_jump_leibniz} has a correction term $D^{\widetilde{\mathcal{N}}} F \cdot D^{\widetilde{\mathcal{N}}} G$ arising from the discrete nature of jumps.

\label{def:operator_deriv}
For $F \in L^2(\Omega)$ such that the functional $u \mapsto \E[F \cdot \delta_X(u)]$ is continuous on~$\HX$, the \emph{operator derivative} $D_X F$ is the unique element of $L^2(\Omega; \HX)$ satisfying
\begin{equation}\label{eq:adjoint_def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HX}] \quad \text{for all } u \in \HX.
\end{equation}
Existence follows from the Riesz representation theorem; uniqueness holds in $L^2(\Omega; \HX)$.

\label{thm:CO}
Let $X$ have energy space $\HX$, stochastic integral $\delta_X$, and operator derivative $D_X = \delta_X^*$. Let $\Pi_X$ denote the orthogonal projection onto predictable elements in~$\HX$. Assume:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \textup{Centered integrals:} $\E[\delta_X(u)] = 0$ for all $u \in \HX$.
\item \textup{Isometry on predictable processes:} $\E[|\delta_X(u)|^2] = \|u\|_{\HX}^2$ for predictable $u$.
\item \textup{Predictable representation property (PRP):} Every $\mathcal{F}_T^X$-measurable, centered $\tilde{F} \in L^2(\Omega)$ has the form $\tilde{F} = \delta_X(v)$ for some predictable $v \in \HX$.
\end{enumerate}
Then for all $\mathcal{F}_T^X$-measurable $F \in L^2(\Omega)$:
\begin{equation}\label{eq:CO}
F = \E[F] + \delta_X(\Pi_X D_X F) = \E[F] + \int_0^T (\Pi_X D_X F)_t\, dX_t.
\end{equation}

\label{cond:isometry}
For predictable $u, v \in \HX$:
\begin{equation}\label{eq:isometry}
\E[\delta_X(u) \cdot \delta_X(v)] = \E[\langle u, v \rangle_{\HX}].
\end{equation}

\label{prop:isometry_props}
Assume Condition~\ref{cond:isometry}. Then:
\begin{enumerate}[label=\textup{(\alph*)}]
\item $D_X(\delta_X(u)) = u$ for predictable $u \in \HX$.
\item $\Var(F) = \E[\|\Pi_X D_X F\|_{\HX}^2]$ when $F - \E[F] = \delta_X(\Pi_X D_X F)$.
\end{enumerate}

\label{cond:leibniz}
For $F, G$ in a suitable domain:
\begin{equation}\label{eq:leibniz}
D_X(FG) = F\, D_X G + G\, D_X F.
\end{equation}

following_proof:
\emph{Step 1: Explicit formula.} For $F = f(X_{t_1}, \ldots, X_{t_n})$:
\begin{equation}\label{eq:DX_cylindrical}
D_X F = \sum_{i=1}^n \partial_i f(X_{t_1}, \ldots, X_{t_n}) \cdot k_{t_i}.
\end{equation}
To verify, check~\eqref{eq:adjoint_def}: the Gaussian integration-by-parts formula $\E[X_t \cdot h(X)] = \sum_j R(t,t_j)\,\E[\partial_j h(X)]$ gives
\[
\E[F \cdot \delta_X(u)] = \sum_{i=1}^n \E[\partial_i f(X_{t_1}, \ldots, X_{t_n})] \cdot \langle k_{t_i}, u \rangle_{\HX} = \E[\langle D_X F, u \rangle_{\HX}].
\]

\emph{Step 2: Leibniz from the explicit formula.} View $FG = (f \cdot g)(X_{t_1}, \ldots, X_{t_n}, X_{s_1}, \ldots, X_{s_m})$ as a function of $n+m$ variables:
\begin{align*}
D_X(FG) &= \sum_{i=1}^n g\, \partial_i f \cdot k_{t_i} + \sum_{j=1}^m f\, \partial_j g \cdot k_{s_j} = G\, D_X F + F\, D_X G.
\end{align*}

\emph{Step 3: Extension.} Cylindricals are dense in $\mathbb{D}^{1,2}$. Both sides of the Leibniz rule are continuous in the $\mathbb{D}^{1,2}$ topology by H\"older's inequality and closedness of $D_X$, so the rule extends to $\mathbb{D}^{1,2} \cap L^4(\Omega)$.

