\label{def:triple}
A \emph{causal derivation-divergence triple} is $(D, \delta, \Pi)$ where:
\begin{enumerate}
\item $D: \mathrm{Dom}(D) \subset L^2(\Omega) \to L^2(\Omega; H)$ is a densely-defined closed linear operator with $1 \in \mathrm{Dom}(D)$ and $D1 = 0$.
\item $\delta: \mathrm{Dom}(\delta) \subset L^2(\Omega; H) \to L^2(\Omega)$ is the Hilbert space adjoint of $D$:
\[
\mathbb{E}[F \delta(u)] = \mathbb{E}[\langle DF, u \rangle_H], \quad F \in \mathrm{Dom}(D), \, u \in \mathrm{Dom}(\delta).
\]
\item $\Pi: L^2(\Omega; H) \to L^2(\Omega; H)$ is a bounded orthogonal projection ($\Pi^2 = \Pi = \Pi^*$).
\end{enumerate}

\label{def:factorization}
The triple $(D, \delta, \Pi)$ satisfies the \emph{factorization property} if for all $F$ in a dense subspace of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization2}
(\mathrm{Id} - \mathbb{E})F = \delta(\Pi DF).
\end{equation}

The holomorphic projection $\Pi^{1,0}$ and the predictable projection $P_{\mathcal{A}}$ act on different aspects of the structure:
\begin{itemize}
\item $P_{\mathcal{A}}$ projects onto \emph{adapted} processes (respects time/causality).
\item $\Pi^{1,0}$ projects onto \emph{holomorphic} directions (respects complex structure).
\end{itemize}
These are independent constraints. A process can be adapted but not holomorphic, holomorphic but not adapted, both, or neither.

For $F \in \mathbb{D}^{1,2}$, define
\begin{equation}\label{eq:cauchy}
\mathcal{C}_{\mathrm{stoch}}[F] := D^* \Pi^{1,0} P_{\mathcal{A}_{\mathbb{C}}} D F,
\end{equation}
where $P_{\mathcal{A}_{\mathbb{C}}}$ is the predictable projection on $L^2(\Omega; H_{\mathbb{C}})$ and $\Pi^{1,0}$ is the holomorphic projection.

\label{prob:moduli}
Characterize all triples $(D, \delta, \Pi)$ satisfying:
\begin{enumerate}
\item $D$ is a closed derivation on $L^2(\Omega)$ valued in $L^2(\Omega; H)$.
\item $\delta = D^*$.
\item $\Pi$ is an orthogonal projection on $L^2(\Omega; H)$.
\item The factorization $(\mathrm{Id} - \mathbb{E})F = \delta(\Pi DF)$ holds on a dense subspace.
\item The chain rule $D(\varphi(F)) = \varphi'(F) DF$ holds for smooth $\varphi$.
\end{enumerate}

\label{conj:moduli}
The space of compatible projections $\Pi$ for a given $(D, \delta)$ pair is:
\begin{enumerate}
\item Non-empty (the predictable projection always works for Gaussian processes).
\item Finite-dimensional in a suitable sense (parametrized by choices of filtration and/or complex structure).
\item Connected to representation-theoretic data (subalgebras, polarizations, etc.).
\end{enumerate}

\label{conj:quantum}
There exist triples $(D, \delta, \Pi)$ in non-commutative probability spaces that:
\begin{enumerate}
\item Satisfy the factorization axioms.
\item Have no classical (commutative) analogue.
\item Correspond to projections onto subalgebras that are neither ``past'' nor ``future'' in any classical sense.
\end{enumerate}

\label{thm:intro-local}
Let $\nu$ be a probability measure on a compact Riemannian manifold $M$ with 
$\Ric_M \geq \rho$. Suppose:
\begin{enumerate}
\item[(LC)] There exists $\Omega_g \subseteq M$ with $\Hess(V) \geq \kappa$ on $\Omega_g$
and $\nu(\Omega_g^c) \leq \varepsilon$.
\end{enumerate}
Then the spectral gap of $\nu$ satisfies
\[
\lambda_1(\nu) \geq \frac{\rho + \kappa}{C(1 + \sqrt{\varepsilon})}
\]
for an explicit constant $C$ depending only on dimension.

The operator $T: L^2(\mu) \to L^2(\mu_\partial)$ is defined by
\begin{equation}\label{eq:block-operator}
(Tf)(x) = \E_{\nu_x}[f] = \int_{M_{\mathrm{int}}} f(x, y) \, \nu_x(dy).
\end{equation}

The system $(A, v)$ satisfies \emph{topological cancellation} if
\begin{equation}\label{eq:TC}
A^\top v = 0
\end{equation}
where we identify $v$ with a vector in $\R^m$ (the ``uniform mode'').

\label{thm:mixed-hessian}
If $(A, v)$ satisfies topological cancellation, then
\begin{equation}\label{eq:mixed-zero}
\nabla^2_{xy} V^{(0)} = 0.
\end{equation}

\label{thm:grad-decomp}
Let $f: M \to \R$ be smooth. Under topological cancellation:
\begin{equation}\label{eq:grad-formula}
\nabla_x(Tf) = \E_{\nu_x}[\nabla_x f] - \Cov_{\nu_x}(\nabla_x \Delta, f)
\end{equation}
where the covariance involves only the perturbation $\Delta$, not the quadratic part $V^{(0)}$.

\label{thm:localized-BE}
Let $(M, g)$ be a compact connected Riemannian manifold of dimension $n$ with 
$\Ric_M \geq \rho$ and $\diam(M) \leq D$. Let $\nu(dy) \propto e^{-V(y)} dy$ be a 
probability measure. Suppose there exists $\Omega_g \subseteq M$ such that:
\begin{enumerate}
\item[(a)] $\Hess(V)(y) \geq \kappa \cdot g(y)$ for all $y \in \Omega_g$, for some $\kappa > 0$.
\item[(b)] $\nu(\Omega_g^c) \leq \varepsilon$ for some $\varepsilon \in (0, 1/4)$.
\end{enumerate}
Then:
\begin{equation}\label{eq:localized-gap}
\lambda_1(\nu) \geq \frac{\rho + \kappa}{4(1 + C_S(\rho + \kappa)\sqrt{\varepsilon})}
\end{equation}
where $C_S = C_S(n, \rho, D)$ is a Sobolev constant depending only on the geometry of $M$.

\label{thm:main-contraction}
Suppose:
\begin{enumerate}
\item[(TC)] Topological cancellation: $A^\top v = 0$.
\item[(LC)] Localized convexity: $\Hess_{yy}(V) \geq \kappa$ on $\Omega_g$ with $\nu_x(\Omega_g^c) \leq \varepsilon$ for all $x$.
\item[(GC)] Geometric contraction: $\norm{D\Phi} \leq \alpha$ for the block-lift map $\Phi$.
\item[(PC)] Perturbation control: $\norm{\nabla_x \Delta}_{L^2(\nu_x)} \leq \eta$ and $\norm{\nabla_y \nabla_x \Delta}_{L^2(\nu_x)} \leq \sigma$ for all $x$.
\end{enumerate}
Then for $f$ smooth:
\begin{equation}\label{eq:contraction-bound}
\norm{\nabla_x(Tf)}_{L^2(\mu_\partial)} \leq q \norm{\nabla f}_{L^2(\mu)}
\end{equation}
where
\begin{equation}\label{eq:q-formula}
q = \alpha + \frac{\sigma}{\sqrt{\lambda_1(\nu_x)}} \leq \alpha + \frac{C\sigma}{\sqrt{\kappa}}
\end{equation}
and $C$ depends on the Sobolev constant.

Applying~\eqref{eq:diff} before the attention layers:
\textnormal{(i)}~costs $O(L)$, negligible relative to
$O(L^2)$ attention;
