\label{def:filtered_query}
Let $q = W_q\, h_t \in \R^d$ be a projection of the
current context summary $h_t$, and
$k_j = W_k\, v^{(j)} \in \R^d$ a projection of
stored embedding $v^{(j)}$, with learned
$W_q, W_k \in \R^{d \times d}$.  The
relevance-filtered query returns
\begin{equation}\label{eq:filtered_query}
\tilde{\mu}_k(t) = \sum_{j=1}^M
\underbrace{r_j}_{\text{content}}
\cdot\;
\underbrace{E_\alpha(-\lambda_k(t-s_j)^\alpha)}_{\text{temporal}}
\cdot\; \hat{m}_k^{(j)},
\end{equation}
where $r_j = \mathrm{softmax}_j(q \cdot k_j / \sqrt{d})$
are the content-relevance weights.

\label{def:jump_detect}
An input $v_t$ is classified as a \emph{jump} if
\begin{equation}\label{eq:jump_detect}
\norm{v_t - \bar{\mu}(t)} > \tau_{\mathrm{jump}},
\end{equation}
where $\bar{\mu}(t)$ is the current memory summary
(\Cref{def:filtered_query}) and
$\tau_{\mathrm{jump}} > 0$ is a threshold (fixed or
learned).  The distance measures the surprise of the
new input relative to the memory state.

