A \emph{derivative-divergence pair} $(D, \delta)$ consists of:
\begin{enumerate}
\item A closed densely-defined operator $D: \mathrm{Dom}(D) \subset L^2(\Omega) \to L^2(\Omega; \cH)$
\item Its adjoint $\delta = D^*: \mathrm{Dom}(\delta) \subset L^2(\Omega; \cH) \to L^2(\Omega)$
\end{enumerate}
satisfying the integration-by-parts relation
\begin{equation}
\E[F \cdot \delta(u)] = \E[\ip{DF}{u}_\cH]
\end{equation}
for $F \in \mathrm{Dom}(D)$ and $u \in \mathrm{Dom}(\delta)$.

A projection $\Pi$ is \emph{compatible} with $(D, \delta)$ if
\begin{equation}
(\mathrm{Id} - \E)F = \delta(\Pi D F)
\end{equation}
for all $F$ in a dense subspace of $L^2(\Omega)$.

The \emph{curvature} of a projection $\Pi$ with respect to $D$ is
\begin{equation}
\Omega_\Pi := [D, \Pi] = D\Pi - \Pi D
\end{equation}
as an operator on appropriate domains.

The \emph{curvature norm} is
\begin{equation}
\norm{\Omega_\Pi} := \sup_{\norm{u} = 1} \norm{[D, \Pi] u}
\end{equation}

The projection has \emph{convexity} $\lambda > 0$ if the conditional measure $\mu(\cdot | x)$ is $\lambda$-log-concave:
\begin{equation}
\nabla^2_{yy} (-\log \mu) \succeq \lambda I
\end{equation}

\label{thm:contraction}
Suppose $\Pi$ has convexity $\lambda > 0$ and curvature bound $\norm{\Omega_\Pi} \leq M$. Then for the boundary derivative $D_\partial$:
\begin{equation}
\norm{D_\partial(\Pi f)} \leq q \norm{D_\partial f}
\end{equation}
where
\begin{equation}
q = \frac{M^2}{\lambda + M^2} < 1
\end{equation}

following_proof:
By the Brascamp-Lieb inequality, for log-concave $\mu$:
\begin{equation}
\Var_\mu(g) \leq \frac{1}{\lambda} \E_\mu[\norm{\nabla_y g}^2]
\end{equation}

Differentiating the projection:
\begin{equation}
D_\partial(\Pi f) = \Pi(D_\partial f) + \Omega_\Pi f
\end{equation}

The first term preserves the gradient norm. The second term (the curvature contribution) satisfies:
\begin{equation}
\norm{\Omega_\Pi f} \leq M \cdot \frac{1}{\sqrt{\lambda}} \norm{D_y f}
\end{equation}

The Schur complement formula for the effective boundary Hessian gives:
\begin{equation}
\norm{D_\partial(\Pi f)}^2 \leq \left(1 - \frac{\lambda}{\lambda + M^2}\right) \norm{Df}^2
\end{equation}

Taking square roots yields the contraction rate $q$.

statement:
\begin{equation}
\norm{D(\Pi^{(n)} f)} \leq q^n \norm{Df}
\end{equation}

\label{thm:clustering}
Let $f, g$ be observables localized at distance $r$ (separated by $n \sim r$ projection steps). Then:
\begin{equation}
|\Cov(f, g)| \leq C q^n \norm{Df} \norm{Dg} \leq C e^{-mr} \norm{Df} \norm{Dg}
\end{equation}
where $m = -\log q > 0$.

following_proof:
The covariance factors through the $n$-step projection:
\begin{equation}
\Cov(f, g) = \Cov(f, \Pi^{(n)} g)
\end{equation}

By the Poincaré inequality and iterated contraction:
\begin{equation}
|\Cov(f, g)| \leq \norm{f - \E f} \cdot \norm{\Pi^{(n)} g - \E g} \leq C \norm{Df} \cdot q^n \norm{Dg}
\end{equation}

