\label{cor:gap}
If $q < 1$ uniformly across all scales, then the system has a spectral gap
\begin{equation}
m = -\log q > 0
\end{equation}

\label{def:axioms}
The operators $(D, P_t, Q_t, C_t, \Pi)$ satisfy:
\begin{enumerate}[label=\textbf{(A\arabic*)}]
\item \textbf{Decomposition:}
  $D(\E_t F) = P_t(DF) + C_t(F)$
  for all $F \in \Dom(D)$.
\item \textbf{Causal range of $P_t$:}
  $(I - Q_t)P_t = 0$---the predictable part is
  supported on the past.
\item \textbf{Causal range of conditioned derivative:}
  $(I - Q_t)D(\E_t F) = 0$---conditioning on
  $\FF_t$ produces a past-supported derivative.
\item \textbf{Relative defect bound:}
  $\norm{C_t(F)} \leq K(t)\,\norm{P_t(DF)}$
  for a function $K: [0,T] \to [0,\infty)$.
\item \textbf{Past nondegeneracy:}
  $\inf_{\norm{h}=1,\, h \in \Ran(Q_t)}
  \norm{\Pi h} \geq \gamma(t) > 0$---the
  projection $\Pi$ does not annihilate past
  directions.
\item \textbf{Controllability:} for every direction
  in $\Ran((I-Q_t)\Pi)$, there exist near-extremizers
  in $\Dom(D)$ that align both $P_t(DF)$ and
  $C_t(F)$ with that direction.
\end{enumerate}

\label{def:leakage}
$L(\Pi; t) := \norm{(I - Q_t)\Pi}_{\op}$.
Zero leakage: $\Ran(\Pi) \subset \Ran(Q_t)$.

\label{lem:support}
Under (A1)--(A3): $(I - Q_t)C_t(F) = 0$ for all
$F \in \Dom(D)$.

