The \emph{transfer operator} $T: L^2(\partial B) \to L^2(\partial B)$ is
\begin{equation}
(Tf)(x) = \int f(x,y) \, \mu_B(dy | x)
\end{equation}
where $\mu_B(\cdot | x)$ is the conditional measure on interior variables given boundary $x$.

\label{prop:factorization}
The transfer operator satisfies
\begin{equation}
(\mathrm{Id} - \E_B) = \delta_\partial \, T \, D_\partial
\end{equation}
where $D_\partial$ is the boundary derivative and $\delta_\partial = D_\partial^*$.

The \emph{curvature} of the transfer operator is
\begin{equation}
\Omega_T := [D_\partial, T] = D_\partial T - T D_\partial
\end{equation}

\label{prop:curvature-hessian}
The curvature norm satisfies
\begin{equation}
\norm{\Omega_T} \leq \frac{1}{\lambda} \norm{\nabla^2_{xy} V}
\end{equation}
where $\lambda$ is the convexity of $V$ in $y$.

\label{lem:cancel}
For the incidence matrix $A$ and boundary coupling vector $v$:
\begin{equation}
A^\top v = 0
\end{equation}

following_proof:
Each interior edge $i$ appears in exactly two plaquettes, with opposite orientations. Let these plaquettes be $p^+$ and $p^-$. Then:
\begin{equation}
(A^\top v)_i = \sum_p A_{pi} v_p = A_{p^+,i} \cdot 1 + A_{p^-,i} \cdot 1 = (+1) + (-1) = 0
\end{equation}

