\label{thmA}
For the forward process~\eqref{eq:forward-intro} with deterministic initial condition $X_0 = x_0$:
\begin{enumerate}[label=(\roman*), leftmargin=2em]
\item $D_{\BH} X_t = \varphi_t$ with $\varphi_t(s) := \mathbf{1}_{[0,t]}(s)\, g(s)\, c(t)/c(s)$;
\item $\Pi_{\BH} D_{\BH} X_t = \varphi_t$ (already predictable);
\item The intrinsic bracket is $\langle X \rangle_t^{(D,\Pi)} = \|\varphi_t\|^2_{\HH}$;
\item The conditional law is $X_t \mid X_0 = x_0 \sim \mathcal{N}(c(t) x_0, \|\varphi_t\|^2_{\HH})$.
\end{enumerate}
The identity $\langle X \rangle_t^{(D,\Pi)} = \|\varphi_t\|^2_{\HH}$ holds uniformly for $H \in (0,1)$.

\label{thmB}
Let $p_t$ denote the marginal density of $X_t$ under~\eqref{eq:forward-intro}, and write $m(x,t) := \E[X_0 \mid X_t = x]$. Then
\begin{equation}\label{eq:score-exact}
  \nabla_x \log p_t(x) \;=\; -\,\frac{x - c(t)\, m(x,t)}{\|\varphi_t\|^2_{\HH}}.
\end{equation}
The denominator $\|\varphi_t\|^2_{\HH}$ is the intrinsic bracket of Theorem~\ref{thmA}; the numerator is Tweedie's formula. Both objects are operator-derivative-native: the bracket is $\|\Pi_{\BH} D_{\BH} X_t\|^2_{\HH}$, and $m(x,t)$ is an orthogonal projection in $L^2$.

\label{thmC}
Let $\MAfbm$ be the Markov approximation of $B^H$ with $K$ OU processes~\cite{Harms2019,Daems2023}, and let $\alpha^K(t,s)$ denote the reparameterization kernel of~\cite[Proposition~1]{Nobis2023GFDM}, so that
\[
  X^K_t = c(t) x_0 + \int_0^t \alpha^K(t,s)\, dB_s, \qquad X^K_t \mid x_0 \sim \mathcal{N}(c(t) x_0, \sigma^2_K(t)),
\]
where $B$ is the underlying standard Brownian motion and $\sigma^2_K(t) := \int_0^t \alpha^K(t,s)^2\,ds$. Let $\beta(t,\cdot)$ be the Volterra transfer of $\varphi_t$ satisfying $\int_0^t \varphi_t(s)\, dB^H_s = \int_0^t \beta(t,s)\, dB_s$. Then:
\begin{enumerate}[label=(\roman*), leftmargin=2em]
\item $\alpha^K(t,\cdot) \to \beta(t,\cdot)$ in $L^2([0,t])$ as $K \to \infty$, with convergence rate given by the Bayer--Breneis estimates~\cite[Theorem~2.15]{BayerBreneis2023};
\item $\sigma^2_K(t) \to \|\varphi_t\|^2_{\HH}$ at the same rate;
\item The GFDM score $\nabla_x \log p^K_t(x)$ converges pointwise to the exact score~\eqref{eq:score-exact}.
\end{enumerate}
The $K \to \infty$ limit of the GFDM reverse-time dynamics equals the exact reverse-time dynamics of the true-fBM-driven forward~\eqref{eq:forward-intro}.

\label{prop:marginal-FKE}
Assume $v(t) := \|\varphi_t\|^2_{\HH}$ is $C^1$ on $(0,T]$ with $v'(t) > 0$, and $p_0$ admits a density with sufficiently fast tail decay so that differentiation under the integral is justified. Then the marginal density $p_t$ of $X_t$ under~\eqref{eq:forward-intro} satisfies
\begin{equation}\label{eq:marginal-FKE}
  \partial_t p_t(x) \;=\; -\mu(t)\,\partial_x\!\left[ c(t)\, m(x,t)\, p_t(x) \right] \;+\; \tfrac{1}{2}\, v'(t)\, \partial_x^2 p_t(x),
\end{equation}
where $m(x,t) = \E[X_0 \mid X_t = x]$ and $c(t) m(x,t) = \E[c(t) X_0 \mid X_t = x]$.

\label{thm:reverse-sde}
Under the hypotheses of Proposition~\ref{prop:marginal-FKE}:

\medskip\noindent\emph{(i) Markov auxiliary.} The Markov SDE
\begin{equation}\label{eq:markov-aux}
  d\widetilde{X}_t = \mu(t)\, c(t)\, m(\widetilde{X}_t, t)\, dt + \sqrt{v'(t)}\, dW_t, \qquad \widetilde{X}_0 \sim p_0,
\end{equation}
has one-dimensional marginals equal to those of $X$ under~\eqref{eq:forward-intro}: $\widetilde{X}_t \stackrel{d}{=} X_t$ for every $t \in [0,T]$. The processes $\widetilde{X}$ and $X$ are \emph{not} equal in law as processes; only their marginals coincide.

\medskip\noindent\emph{(ii) Reverse-time SDE.} The reverse-time process $\overline{X}_\tau := \widetilde{X}_{T-\tau}$ satisfies
\begin{equation}\label{eq:reverse-sde}
  d\overline{X}_\tau = \left[ -\mu(T-\tau)\, c(T-\tau)\, m(\overline{X}_\tau, T-\tau) + v'(T-\tau)\, \partial_x \log p_{T-\tau}(\overline{X}_\tau) \right] d\tau + \sqrt{v'(T-\tau)}\, d\overline{B}_\tau,
\end{equation}
with $\overline{X}_0 \sim p_T$ and $\overline{B}$ a reverse-time Brownian motion.

\medskip\noindent\emph{(iii) Closed form of the drift.} Using Theorem~\ref{thmB}, the score satisfies $v(T-\tau) \partial_x \log p_{T-\tau}(x) = -(x - c(T-\tau) m(x, T-\tau))$, so
\begin{equation}\label{eq:reverse-sde-explicit}
  d\overline{X}_\tau = \Bigl[ -\mu(T-\tau)\, c(T-\tau)\, m(\overline{X}_\tau, T-\tau) - \tfrac{v'(T-\tau)}{v(T-\tau)}\, \bigl(\overline{X}_\tau - c(T-\tau)\, m(\overline{X}_\tau, T-\tau)\bigr) \Bigr] d\tau + \sqrt{v'(T-\tau)}\, d\overline{B}_\tau.
\end{equation}
The drift depends on $\overline{X}_\tau$ only through $m(\overline{X}_\tau, T-\tau)$, which is a neural-network-learnable scalar function of $(x,t)$.

\label{lem:volterra-transfer}
For $\varphi_t(s) = g(s) c(t)/c(s) \cdot \mathbf{1}_{[0,t]}(s)$ and the Type~II kernel $K_H$ of~\eqref{eq:RL-kernel},
\begin{equation}\label{eq:wiener-transfer}
  \int_0^t \varphi_t(s)\, dB^H_s = \int_0^t \beta(t,s)\, dB_s,
\end{equation}
where, setting $c_H := 1/\Gamma(H+\tfrac{1}{2})$,
\begin{equation}\label{eq:beta-explicit}
  \beta(t,s) = c_H\,\varphi_t(s)\, (t-s)^{H-1/2} \;+\; c_H\,(H-\tfrac{1}{2}) \int_s^t \bigl(\varphi_t(u) - \varphi_t(s)\bigr)\, (u-s)^{H-3/2}\, du,
\end{equation}
with $\varphi_t(s) = g(s) c(t)/c(s) \cdot \mathbf{1}_{[0,t]}(s)$. Equivalently, $\beta(t,\cdot) = \mathcal{K}_H^* \varphi_t$ where $\mathcal{K}_H^*$ is the $L^2$-adjoint of the Volterra operator $\mathcal{K}_H: L^2([0,T]) \to L^2([0,T])$ defined by $(\mathcal{K}_H f)(t) := \int_0^t K_H(t,s) f(s)\, ds$.

\label{cor:fOU-beta}
For the constant-coefficient forward $dX_t = -\theta X_t\, dt + g\, dB^H_t$ with $\theta, g > 0$ constants, the Volterra transfer depends only on $r := t - s$:
\begin{equation}\label{eq:fOU-beta}
  \beta(t,s) = \beta_0(t - s), \qquad \beta_0(r) := \frac{g}{\Gamma(H+\tfrac{1}{2})}\, r^{H-1/2}\, e^{-\theta r}\, M\!\bigl(H - \tfrac{1}{2},\; H + \tfrac{1}{2};\; \theta r\bigr),
\end{equation}
where $M(a,b;z) := \sum_{k=0}^\infty \frac{(a)_k}{(b)_k}\frac{z^k}{k!}$ is the Kummer confluent hypergeometric function. Consequently
\begin{equation}\label{eq:fOU-variance}
  v(t) = \int_0^t \beta_0(r)^2\, dr, \qquad v'(t) = \beta_0(t)^2 = \frac{g^2}{\Gamma(H+\tfrac{1}{2})^2}\, t^{2H-1}\, e^{-2\theta t}\, M\!\bigl(H - \tfrac{1}{2},\; H + \tfrac{1}{2};\; \theta t\bigr)^2.
\end{equation}
At $H = 1/2$: $M(0, 1; z) = 1$ and~\eqref{eq:fOU-variance} recovers the classical OU variance $v(t) = g^2(1 - e^{-2\theta t})/(2\theta)$.

\label{prop:alpha-convergence}
Let $\alpha^K$ be the MA-fBM kernel of~\eqref{eq:alpha-def} with $\omega^K$ the $L^2$-optimal coefficients of~\cite{Daems2023}, and let $\beta(t,\cdot)$ be the Volterra transfer of Lemma~\ref{lem:volterra-transfer}. Then for every $t \in (0,T]$:
