\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\[
\calH_{\mathrm{IBM}} = \{h \in C^1([0, T]) : h(0) = h'(0) = 0,\, h'' \in L^2([0, T])\}
\]
with inner product $\langle h, g\rangle_{\calH_{\mathrm{IBM}}} = \int_0^T h''(r)\,g''(r)\,dr$.

Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Let $\calH^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\calH^{(1)}} = \|h'\|_{L^2(\R_+)}$), and let $\calH^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\calH^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}
\calH_Z = \calH^{(1)} \otimes \calH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:DZ}
For a smooth function $f : \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B^{(2)}_T|))$, the operator derivative decomposes as $D_Z F = D^{(1)}F + D^{(2)}F$, where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$. Explicitly, by the chain rule (Tier~3):
\begin{align}
D^{(1)}_s F &= f'(Z_T) \cdot \mathbf{1}_{[0,|B^{(2)}_T|]}(s), \label{eq:D1} \\
D^{(2)}_s F &= f'(Z_T) \cdot \frac{\partial B^{(1)}}{\partial s}\bigg|_{s=|B^{(2)}_T|} \cdot \sgn(B^{(2)}_T) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:D2}
\end{align}

\label{thm:iterated-bracket}
The process $Z_t = B^{(1)}(|B^{(2)}_t|)$ has energy function
\begin{equation}\label{eq:iterated-bracket}
\Gamma^Z(t) := \|D^{(1)}_\cdot Z_t\|_{\calH^{(1)}}^2 = |B^{(2)}_t|,
\end{equation}
which is a \emph{random}, continuous semimartingale. By Tanaka's formula,
\begin{equation}\label{eq:iterated-Tanaka}
d\Gamma^Z(t) = d|B^{(2)}_t| = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}),
\end{equation}
where $L^0_t(B^{(2)})$ is the local time of $B^{(2)}$ at level zero.

\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B^{(2)}_t|)$, the marginal density $p(t, x)$ satisfies, in the distributional sense,
\begin{equation}
\partial_t p = \tfrac{1}{8}\partial_x^4 p + \tfrac{1}{\sqrt{8\pi t}}\,\partial_x^2\,\delta_0(x).
\end{equation}
For $x \neq 0$, the source term vanishes and the density satisfies the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial_x^4 p$.

following_proof:
The proof proceeds in four steps.

\medskip\noindent\textbf{Step 1: Conditional structure.} Define the random time-change $\tau_t = |B^{(2)}_t|$. Conditional on $B^{(2)}$ (equivalently, conditional on the entire path $(\tau_s)_{s\in[0,T]}$), the process $Z_t = B^{(1)}(\tau_t)$ is a time-changed Brownian motion. By the classical Feynman--Kac theorem applied to $B^{(1)}$, for any $f \in C^2_b(\R)$,
\begin{equation}
\E[f(Z_T) \mid Z_t = x, B^{(2)}] = u(\tau_t, x)
\end{equation}
where $u(s, x)$ solves the heat equation in the $s$-variable:
\begin{equation}\label{eq:heat-outer}
\partial_s u + \tfrac{1}{2}\partial_x^2 u = 0, \qquad u(\tau_T, x) = f(x).
\end{equation}

\medskip\noindent\textbf{Step 2: Time-change dynamics via Tanaka's formula.} The random clock $\tau_t = |B^{(2)}_t|$ satisfies Tanaka's formula:
\[
d\tau_t = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\]
The quadratic variation of $\tau$ is $d[\tau]_t = dt$, since $\sgn(B^{(2)}_t)^2 = 1$ for $B^{(2)}_t \neq 0$ (which holds a.e.\ in $t$, $\mathbb{P}$-a.s.).

\medskip\noindent\textbf{Step 3: It\^o formula for the composition.} We apply the classical It\^o formula to the composite function $v(t, x) := u(\tau_t, x)$. Since $u$ is smooth in both arguments and $\tau_t$ is a semimartingale, It\^o's formula gives:
\begin{equation}
dv = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial_s^2 u \cdot d[\tau]_t = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial_s^2 u \cdot dt.
\end{equation}
Now substitute $\partial_s u = -\frac{1}{2}\partial_x^2 u$ from~\eqref{eq:heat-outer}. For the second-order term, differentiate~\eqref{eq:heat-outer} in $s$ to obtain $\partial_s^2 u = \frac{1}{4}\partial_x^4 u$. Therefore:
\begin{equation}
dv = -\tfrac{1}{2}\partial_x^2 u \cdot d\tau_t + \tfrac{1}{8}\partial_x^4 u \cdot dt.
\end{equation}

\medskip\noindent\textbf{Step 4: Marginal density equation via Fourier analysis.} The characteristic function of $Z_t$ is computed by iterated conditioning:
\begin{equation}
\hat p(t, \xi) = \E[e^{i\xi Z_t}] = \E\!\left[\E\!\left[e^{i\xi B^{(1)}(\tau_t)} \mid B^{(2)}\right]\right] = \E\!\left[e^{-\xi^2 \tau_t/2}\right] = \E\!\left[e^{-\xi^2 |B^{(2)}_t|/2}\right].
\end{equation}
For $|B^{(2)}_t|$ with the half-normal distribution, the Laplace transform is:
\[
\E\!\left[e^{-\lambda|B^{(2)}_t|}\right] = e^{\lambda^2 t/2}\,\erfc\!\left(\lambda\sqrt{t/2}\right),
\]
where $\erfc$ is the complementary error function. Setting $\lambda = \xi^2/2$ gives $\hat p(t, \xi) = F(t)$ where $F(t) = e^{ct}\,\erfc(\sqrt{ct})$ with $c = \xi^4/8$.

We now compute $F'(t)$ explicitly. By the product and chain rules, using $\frac{d}{dt}\erfc(\sqrt{ct}) = -\frac{2}{\sqrt{\pi}}\,e^{-ct}\,\frac{\sqrt{c}}{2\sqrt{t}} = -\frac{\sqrt{c}}{\sqrt{\pi t}}\,e^{-ct}$:
\begin{equation}
F'(t) = c\,e^{ct}\,\erfc(\sqrt{ct}) + e^{ct}\!\left(-\frac{e^{-ct}\sqrt{c}}{\sqrt{\pi t}}\right) = c\,F(t) - \sqrt{\frac{c}{\pi t}}.
\end{equation}
Substituting $c = \xi^4/8$:
\begin{equation}\label{eq:Fourier-ODE}
\partial_t \hat p(t, \xi) = \frac{\xi^4}{8}\hat p(t, \xi) - \frac{\xi^2}{\sqrt{8\pi t}}.
\end{equation}
The remainder term $R(t, \xi) = -\xi^2/\sqrt{8\pi t}$ does not vanish. In our Fourier convention $\hat p = \int e^{i\xi x} p\,dx$, the transform of $\partial_x^4 p$ is $(i\xi)^4 \hat p = \xi^4 \hat p$, and the transform of $\partial_x^2 \delta_0(x)$ is $(i\xi)^2 = -\xi^2$. Therefore~\eqref{eq:Fourier-ODE} inverts to the distributional PDE
\begin{equation}
\partial_t p = \tfrac{1}{8}\partial_x^4 p + \tfrac{1}{\sqrt{8\pi t}}\,\partial_x^2\,\delta_0(x).
\end{equation}
For $x \neq 0$ the source term vanishes, giving the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial_x^4 p$, consistent with Allouba--Zheng \cite{AZ}.

statement:
\label{def:Poisson-deriv}
For a functional $F = f(N_T)$ where $f : \mathbb{Z}_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0, T]$ and $\omega \in \Omega$,
\begin{equation}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T(\omega) + 1) - f(N_T(\omega)),
\end{equation}
where $\delta_t$ denotes the Dirac mass at time $t$ (adding a jump at time $t$), not to be confused with the divergence operator $\delta_N$.

\label{thm:Poisson-gen}
The generator for the Poisson process acting on functions $f : \mathbb{Z}_{\geq 0} \to \R$ is
\begin{equation}
Lf(n) = \lambda(f(n + 1) - f(n)), \quad n \in \mathbb{Z}_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t, n) = \E[f(N_T) \mid N_t = n]$ satisfies $\partial_t u + \lambda(u(\cdot, n + 1) - u(\cdot, n)) = 0$.

\label{thm:compound-gen}
The generator acting on $f \in C^2(\R)$ is the nonlocal operator:
\begin{equation}
Lf(x) = \lambda \int_\R (f(x + z) - f(x))\,\nu_J(dz).
\end{equation}

\label{thm:pure-jump-gen}
The generator acting on $f \in C^2(\R)$ is:
\begin{equation}
Lf(x) = \int_\R \bigl[f(x + z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\bigr]\,\nu(dz).
\end{equation}

For the symmetric $\alpha$-stable process with $\alpha \in (0, 2)$, the L\'evy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha}\,dz$ where $c_\alpha > 0$. The generator is the fractional Laplacian:
\begin{equation}
Lf(x) = -(-\Delta)^{\alpha/2}f(x) = c_\alpha\,\PV\!\int_\R \frac{f(x + z) - f(x)}{|z|^{1+\alpha}}\,dz.
\end{equation}

\label{thm:main}
Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space, and let $X = (X_t)_{t\in[0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\calH$. Assume the filtration $(\calF_t)_{t\geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0, T]\times\R^d)$, and let $\varphi \in C^2(\R)$. Assume the operator It\^o formula (Theorem~\ref{thm:ito}) applies. Then the second-order term in the It\^o expansion of $\varphi(Y_t)$ is
\begin{equation}\label{eq:second-order}
\tfrac{1}{2}\,\varphi''(Y_t)\,d\langle Y \rangle_t^{(D,\Pi)}
= \tfrac{1}{2}\,\varphi''(Y_t)\,d\Gamma^Y(t),
\end{equation}
where $\Gamma^Y(t) := \|\Pi D_X Y_t\|_{\calH}^2$ is the energy function. When $\Gamma^Y$ is absolutely continuous, this reduces to $\frac{1}{2}\,\varphi''(Y_t)\,\dot\Gamma^Y(t)\,dt = \frac{1}{2}\,\varphi''(Y_t)\,\frac{d}{dt}\|\Pi D_X Y_t\|_{\calH}^2\,dt$.

For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:iterBM}
Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Define iterated Brownian motion by $Z_t = B^{(1)}(|B^{(2)}_t|)$ for $t \in [0, T]$. Then:
\begin{enumerate}[(a),nosep]
\item The energy space is the tensor product $\calH_Z = \calH^{(1)} \otimes \calH^{(2)}$.
\item The operator derivative decomposes as $D_Z = D^{(1)} + D^{(2)}$ with the chain rule applied at each level.
\item The energy function $\Gamma^Z(t) = \|D^{(1)}_\cdot Z_t\|_{\calH^{(1)}}^2 = |B^{(2)}_t|$ is a random semimartingale (not a deterministic BV function), with Tanaka decomposition $d\Gamma^Z = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)})$ and quadratic variation $[\Gamma^Z]_t = t$, $\mathbb{P}$-a.s.
\item The marginal density $p(t, x)$ satisfies, in the distributional sense,
\begin{equation}\label{eq:biharmonic}
\partial_t p = \tfrac{1}{8}\partial_x^4 p + \tfrac{1}{\sqrt{8\pi t}}\,\partial_x^2\,\delta_0(x).
\end{equation}
Away from the origin ($x \neq 0$), the source term vanishes and $p$ satisfies the pure
biharmonic equation $\partial_t p = \frac{1}{8}\partial_x^4 p$. This recovers the Allouba--Zheng result~\cite{AZ} and identifies the source term as the contribution of the local time $L^0_t(B^{(2)})$ in the operator framework.
\end{enumerate}

\label{thm:Levy}
Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space supporting a L\'evy process $(X_t)_{t\in[0,T]}$ with L\'evy measure $\nu$ satisfying $\int_\R (1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\calF_t)_{t\geq 0}$ be its natural filtration. Then:
\begin{enumerate}[(a),nosep]
\item The energy space for jumps is $\calH_J = L^2([0, T] \times \R, dt \otimes \nu)$. This is the space of integrands for the compensated Poisson integral, not a moment condition on $X_t$ itself. In particular, $X_t$ need not belong to $L^2(\Omega)$; the operator derivative acts on functionals $F = f(X_T)$ where $f$ belongs to a sufficiently regular class (e.g., $C^2_c(\R)$) ensuring $F \in L^2(\Omega)$.
\item The operator derivative is the difference operator: $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator acting on $f \in C^2(\R)$ is nonlocal:
\begin{equation}\label{eq:Levy-gen}
Lf(x) = \int_\R \bigl[f(x + z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\bigr]\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with $\alpha \in (0, 2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

Let $X$ be a stochastic process with energy space $\calH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \calH)$ is defined via Riesz representation:
\begin{equation}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u\rangle_{\calH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\calH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}
F - \E[F] = \delta_X(\Pi D_X F), \qquad \mathbb{P}\text{-a.s.}
\end{equation}

\label{thm:ito}
Let $X$ be a centered Volterra Gaussian process---i.e., $X_t = \int_0^t K(t,s)\,dW_s$ for a square-integrable Volterra kernel~$K$---satisfying the Decreusefond--\"Ust\"unel conditions~\cite{DU} (measurability and integrability conditions on~$K$ ensuring the Malliavin calculus is well-defined; see \cite[Hypothesis~H]{DU}), with operator triple $(D,\delta,\Pi)$ satisfying the chain rule (Assumption~2.3 of~\cite{paper3}), the factorization $(\Id - \E) = \delta\Pi D$, orthogonality of $\Pi$, and energy regularity ($\Gamma^X(t) := \|\Pi DX_t\|_{\calH}^2 \in \BV[0,T]$). For $\varphi \in C^3_b(\R)$,
