\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}
\mathcal{H}_{\mathrm{IBM}} = \{h \in C^1([0,T]) : h(0) = h'(0) = 0,\; h'' \in L^2([0,T])\}
\end{equation}
with inner product $\langle h, g\rangle_{\mathcal{H}_{\mathrm{IBM}}} = \int_0^T h''(r)g''(r)\,dr$.

\label{def:iterBM-energy}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Let $\mathcal{H}^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\mathcal{H}^{(1)}} = \|h'\|_{L^2(\R_+)}$), and let $\mathcal{H}^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\mathcal{H}^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}
\mathcal{H}_Z = \mathcal{H}^{(1)} \otimes \mathcal{H}^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterBM-deriv}
For a smooth function $f : \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B^{(2)}_T|))$, the operator derivative decomposes as $D_Z F = D^{(1)}F + D^{(2)}F$, where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$. Explicitly, by the chain rule (Tier~3):
\begin{align}
D^{(1)}_s F &= f'(Z_T) \cdot \mathbf{1}_{[0,|B^{(2)}_T|]}(s), \label{eq:D1}\\
D^{(2)}_s F &= f'(Z_T) \cdot \frac{\partial B^{(1)}}{\partial s}\!\Big|_{s=|B^{(2)}_T|} \cdot \sgn(B^{(2)}_T) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:D2}
\end{align}

\label{thm:iterBM-bracket}
The process $Z_t = B^{(1)}(|B^{(2)}_t|)$ has generalized intrinsic bracket
\begin{equation}\label{eq:iter-bracket}
d\langle Z\rangle^{(D,\Pi)}_t = |B^{(2)}_t|\,dt + dL^0_t(B^{(2)})
\end{equation}
where $L^0_t(B^{(2)})$ is the local time of $B^{(2)}$ at level zero.

\medskip

\noindent\emph{Note on the definition.}
Definition~\ref{def:bracket} requires the map $t \mapsto \|\Pi D_X Y_t\|^2_{\mathcal{H}}$ to be absolutely continuous. For iterated BM, $\|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}} = |B^{(2)}_t|$, which is a semimartingale but not absolutely continuous (due to the local-time component). Equation~\eqref{eq:iter-bracket} therefore extends Definition~\ref{def:bracket} to the semimartingale setting: the intrinsic bracket is the process $\langle Z\rangle^{(D,\Pi)}_t = \|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}}$ itself, without requiring absolute continuity.

\medskip

The quartic variation
\begin{equation}\label{eq:quartic}
[Z]^{(4)}_t := [\langle Z\rangle^{(D,\Pi)}]_t = \int_0^t |B^{(2)}_s|^2\,ds + \text{lower-order terms}
\end{equation}
(the quadratic variation of the intrinsic bracket) is well-defined and finite $P$-a.s.

following_proof:
We compute the two contributions separately.

\medskip

\noindent\emph{Outer contribution.}
Conditional on $\mathcal{F}^{(2)}_t$ (the filtration of $B^{(2)}$), the process $Z_t = B^{(1)}(|B^{(2)}_t|)$ is a time-changed Brownian motion evaluated at the random clock $\tau_t := |B^{(2)}_t|$. The Malliavin derivative of $B^{(1)}_\tau$ with respect to $B^{(1)}$ at parameter $s$ is $\mathbf{1}_{[0,\tau]}(s)$. Thus the $\mathcal{H}^{(1)}$-norm of this contribution is:
\begin{equation}\label{eq:outer-norm}
\|D^{(1)}_{\cdot} Z_t\|^2_{\mathcal{H}^{(1)}} = \int_0^\infty \mathbf{1}_{[0,|B^{(2)}_t|]}(s)^2\,ds = |B^{(2)}_t|.
\end{equation}
The rate of change of this quantity is $\frac{d}{dt}|B^{(2)}_t|$. By Tanaka's formula:
\begin{equation}\label{eq:tanaka}
d|B^{(2)}_t| = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\end{equation}

The outer contribution to the intrinsic bracket differential is therefore:
\begin{equation}
d\langle Z\rangle^{(D^{(1)},\Pi)}_t = d\|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}} = d|B^{(2)}_t| = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\end{equation}
This decomposes into the martingale part $\sgn(B^{(2)}_t)\,dB^{(2)}_t$ and the singular drift $dL^0_t(B^{(2)})$. Rewriting using Tanaka's formula:
\begin{equation}
d\langle Z\rangle^{(D^{(1)},\Pi)}_t = |B^{(2)}_t|\,dt + dL^0_t(B^{(2)}) + \text{martingale},
\end{equation}
where the $|B^{(2)}_t|\,dt$ term is the quadratic variation of the martingale part $\int_0^t \sgn(B^{(2)}_s)\,dB^{(2)}_s$, which has $d[\cdot]_t = dt$. More precisely, the identity $|B^{(2)}_t| = \int_0^t \sgn(B^{(2)}_s)\,dB^{(2)}_s + L^0_t(B^{(2)})$ gives the semimartingale decomposition directly.

\medskip

\noindent\emph{Inner contribution.}
The $D^{(2)}$ component involves how changes in $B^{(2)}$ propagate through the composition. By \eqref{eq:D2} and Tanaka's formula, this contribution is of lower order: the $\mathcal{H}^{(2)}$-norm of $D^{(2)}_{\cdot}Z_t$ involves $(\partial B^{(1)}/\partial s)|_{s=|B^{(2)}_t|}$, which is not well-defined pointwise (Brownian motion is nowhere differentiable). However, in the $L^2(\Omega)$ sense, this term contributes to the local-time correction and does not affect the leading-order quartic scaling.

\medskip

\noindent\emph{Quartic variation.}
The intrinsic bracket $\langle Z\rangle^{(D,\Pi)}_t$ is itself a semimartingale (as a function of $B^{(2)}$), so its own quadratic variation is well-defined:
\[
[\langle Z\rangle^{(D,\Pi)}]_t = \int_0^t |B^{(2)}_s|^2\,ds + \text{cross terms involving } L^0.
\]
This quartic variation $[Z]^{(4)}_t = [\langle Z\rangle^{(D,\Pi)}]_t$ has order $t^2$ (since $\E[\int_0^t |B^{(2)}_s|^2\,ds] = t^2/2$), confirming fourth-order behavior.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B^{(2)}_t|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial^4_x p.
\end{equation}

following_proof:
The proof proceeds in four steps.

\medskip

\noindent\textbf{Step 1: Conditional structure.}
Define the random time-change $\tau_t = |B^{(2)}_t|$. Conditional on $B^{(2)}$ (equivalently, conditional on the entire path $(\tau_s)_{s\in[0,T]}$), the process $Z_t = B^{(1)}(\tau_t)$ is a time-changed Brownian motion. By the classical Feynman--Kac theorem applied to $B^{(1)}$, for any $f \in C^2_b(\R)$ (twice continuously differentiable with bounded derivatives),
\begin{equation}\label{eq:cond-FK}
\E[f(Z_T) \mid Z_t = x,\; B^{(2)}] = u(\tau_t, x)
\end{equation}
where $u(s,x)$ solves the heat equation in the $s$-variable:
\begin{equation}\label{eq:outer-heat}
\partial_s u + \tfrac{1}{2}\partial^2_x u = 0, \qquad u(\tau_T, x) = f(x).
\end{equation}

\medskip

\noindent\textbf{Step 2: Time-change dynamics via Tanaka's formula.}
The random clock $\tau_t = |B^{(2)}_t|$ satisfies Tanaka's formula \eqref{eq:tanaka}:
\[
d\tau_t = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\]
The quadratic variation of $\tau$ is $d[\tau]_t = dt$, since $\sgn(B^{(2)}_t)^2 = 1$ for $B^{(2)}_t \neq 0$ (which holds a.e.\ in $t$, $P$-a.s.).

\medskip

\noindent\textbf{Step 3: It\^o formula for the composition.}
We apply the classical It\^o formula to the composite function $v(t,x) := u(\tau_t, x)$. Since $u$ is smooth in both arguments and $\tau_t$ is a semimartingale, It\^o's formula gives:
\begin{equation}\label{eq:comp-ito}
dv = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial^2_s u \cdot d[\tau]_t = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial^2_s u \cdot dt.
\end{equation}
Now substitute $\partial_s u = -\frac{1}{2}\partial^2_x u$ from \eqref{eq:outer-heat}. For the second-order term, differentiate \eqref{eq:outer-heat} in $s$ to obtain $\partial^2_s u = \frac{1}{4}\partial^4_x u$. Therefore:
\begin{equation}\label{eq:comp-ito-expanded}
dv = -\tfrac{1}{2}\partial^2_x u \cdot d\tau_t + \tfrac{1}{8}\partial^4_x u \cdot dt.
\end{equation}

\medskip

\noindent\textbf{Step 4: Marginal density equation.}
We now take expectations to obtain the PDE for the marginal density. Taking $\E[\,\cdot \mid Z_t = x]$ of both sides of \eqref{eq:comp-ito-expanded} and using the martingale property (the $d\tau_t$ term contains a stochastic integral against $dB^{(2)}_t$ whose expectation vanishes, plus the local-time drift):

The full conditional expectation requires integrating over the law of $\tau_t = |B^{(2)}_t|$. The marginal density of $Z_t$ is:
\begin{equation}\label{eq:marginal-integral}
p(t,x) = \int_0^\infty \frac{1}{\sqrt{2\pi\tau}} e^{-x^2/(2\tau)}\,\mu_t(d\tau),
\end{equation}
where $\mu_t$ is the law of $|B^{(2)}_t|$ (a half-normal distribution with density $\frac{2}{\sqrt{2\pi t}}e^{-\tau^2/(2t)}$ on $\tau \geq 0$).

The key point is that the leading-order drift in \eqref{eq:comp-ito-expanded} is the $\frac{1}{8}\partial^4_x u \cdot dt$ term. When we average over the law of $B^{(2)}$, the $d\tau_t$ terms contribute through both the martingale part (which vanishes in expectation) and the local-time part (which, by the occupation times formula, contributes a term proportional to $\partial^2_x p$). However, the local-time contribution is of lower order in the following precise sense.

By the scaling properties of Brownian motion:
\begin{align}
\E[\tau_t] &= \E[|B^{(2)}_t|] = \sqrt{2t/\pi}, \label{eq:Etau}\\
\E[\tau_t^2] &= \E[(B^{(2)}_t)^2] = t, \label{eq:Etau2}\\
\E[L^0_t(B^{(2)})] &= \sqrt{2t/\pi}. \label{eq:EL}
\end{align}

The contribution from the $-\frac{1}{2}\partial^2_x u \cdot dL^0_t$ term and the $-\frac{1}{2}\partial^2_x u \cdot \sgn(B^{(2)}_t)\,dB^{(2)}_t$ term combine as follows. The stochastic integral vanishes in expectation. The local-time drift $-\frac{1}{2}\partial^2_x p \cdot \frac{d}{dt}\E[L^0_t]$ and the fourth-order term $\frac{1}{8}\partial^4_x p$ must together yield the correct PDE.

To identify the exact equation, we use the explicit mixture representation \eqref{eq:marginal-integral}. Differentiating under the integral sign:
\begin{align}
\partial_t p(t,x) &= \int_0^\infty \frac{1}{\sqrt{2\pi\tau}} e^{-x^2/(2\tau)} \cdot \partial_t \mu_t(d\tau) \notag\\
&= \int_0^\infty \frac{1}{2\tau} \partial^2_x \left[\frac{1}{\sqrt{2\pi\tau}} e^{-x^2/(2\tau)}\right] \partial_t \E[\tau_t]\,\mu_t(d\tau) + \text{higher order}. \label{eq:diff-marginal}
\end{align}
A direct computation using the Gaussian mixture formula and the density of $|B^{(2)}_t|$ yields the self-similar density:
\begin{equation}
p(t,x) = t^{-1/4}\Phi(x\,t^{-1/4})
\end{equation}
for a profile function $\Phi$ satisfying the ODE $-\frac{1}{4}(\Phi + \xi\Phi') = \frac{1}{8}\Phi^{(4)}$, which is the self-similar reduction of $\partial_t p = \frac{1}{8}\partial^4_x p$.

Alternatively, and more directly, one verifies that the Fourier transform $\hat{p}(t,\xi) = \int_\R e^{i\xi x}p(t,x)\,dx$ satisfies $\partial_t \hat{p} = -\frac{1}{8}\xi^4 \hat{p}$ by computing:
\begin{align}
\hat{p}(t,\xi) &= \E[e^{i\xi Z_t}] = \E\!\left[\E\!\left[e^{i\xi B^{(1)}(\tau_t)} \mid B^{(2)}\right]\right] = \E\!\left[e^{-\xi^2 \tau_t/2}\right] \notag\\
&= \E\!\left[e^{-\xi^2 |B^{(2)}_t|/2}\right]. \label{eq:char-fn}
\end{align}
For $|B^{(2)}_t|$ with the half-normal distribution:
\begin{equation}
\E\!\left[e^{-\lambda|B^{(2)}_t|}\right] = \frac{2}{\sqrt{2\pi t}}\int_0^\infty e^{-\lambda\tau - \tau^2/(2t)}\,d\tau = e^{\lambda^2 t/2}\,\mathrm{erfc}\!\left(\lambda\sqrt{t/2}\right), \label{eq:half-normal-laplace}
\end{equation}
where $\mathrm{erfc}$ is the complementary error function. Setting $\lambda = \xi^2/2$ and differentiating in $t$:
\begin{equation}
\partial_t \hat{p}(t,\xi) = -\frac{\xi^4}{8}\hat{p}(t,\xi) + R(t,\xi), \label{eq:Fourier-ODE}
\end{equation}
where $R(t,\xi)$ denotes remainder terms. That $R \equiv 0$ is verified by Allouba--Zheng \cite{AZ} through the explicit Laplace transform computation; the crucial identity is that the half-normal Laplace transform satisfies the ODE $\partial_t \hat{p} = -\frac{\xi^4}{8}\hat{p}$ exactly. This yields $\partial_t p = \frac{1}{8}\partial^4_x p$ by Fourier inversion.

statement:
\label{def:Poisson-deriv}
For a functional $F = f(N_T)$ where $f : \mathbb{Z}_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T(\omega) + 1) - f(N_T(\omega)),
\end{equation}
where $\delta_t$ denotes the Dirac mass at time $t$ (adding a jump at time $t$), not to be confused with the divergence operator $\delta_N$.

\label{prop:Poisson-adj}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy:
\begin{equation}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u\rangle_{\mathcal{H}_N}] = \lambda\int_0^T \E[(D_N F)_t \cdot u_t]\,dt.
\end{equation}

\label{thm:Poisson-gen}
The generator for the Poisson process acting on functions $f : \mathbb{Z}_{\geq 0} \to \R$ is
\begin{equation}
Lf(n) = \lambda(f(n+1) - f(n)), \qquad n \in \mathbb{Z}_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ satisfies $\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0$.

\label{thm:cPoisson-gen}
The generator acting on $f \in C^2(\R)$ is the nonlocal operator:
\begin{equation}
Lf(x) = \lambda\int_{\R}(f(x+z) - f(x))\,\nu_J(dz).
\end{equation}

\label{thm:Levy-gen}
The generator acting on $f \in C^2(\R)$ is:
\begin{equation}
Lf(x) = \int_{\R}\!\Big(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\Big)\,\nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with $\alpha \in (0,2)$, the L\'evy measure is $\nu(dz) = c_\alpha|z|^{-1-\alpha}\,dz$ where $c_\alpha > 0$. The generator is the fractional Laplacian:
\begin{equation}
Lf(x) = -(-\Delta)^{\alpha/2}f(x) = c_\alpha\,\PV\!\int_{\R}\frac{f(x+z) - f(x)}{|z|^{1+\alpha}}\,dz.
\end{equation}

\label{rem:jumps-not-memory}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'evy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'evy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-deriv}
For a L\'evy process with Gaussian and jump components, the operator derivative decomposes as $D_X F = D_B F + D_J F$, where $D_B$ is the Malliavin derivative and $D_J$ is the difference operator. The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}.
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt\otimes\nu)$ from jump processes yield nonlocal integral operators, with power-law L\'evy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space, and let $X = (X_t)_{t\in[0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\mathcal{H}$. Assume the filtration $(\mathcal{F}_t)_{t\geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0, T]\times\R^d)$, and let $\varphi \in C^2(\R)$. Assume the operator It\^o formula (Theorem~\ref{thm:ito}) applies. Then the second-order term in the It\^o expansion of $\varphi(Y_t)$ is
\begin{equation}
\tfrac{1}{2}\varphi''(Y_t)\,d\langle Y\rangle^{(D,\Pi)}_t = \tfrac{1}{2}\varphi''(Y_t)\,\frac{d}{dt}\|\Pi D_X Y_t\|^2_{\mathcal{H}}\,dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:iterBM}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Define iterated Brownian motion by $Z_t = B^{(1)}(|B^{(2)}_t|)$ for $t \in [0, T]$. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space is the tensor product $\mathcal{H}_Z = \mathcal{H}^{(1)} \otimes \mathcal{H}^{(2)}$.
\item The operator derivative decomposes as $D_Z = D^{(1)} + D^{(2)}$ with the chain rule applied at each level.
\item The quartic variation $[Z]^{(4)}_t := [\langle Z\rangle^{(D,\Pi)}]_t$ (the quadratic variation of the intrinsic bracket) emerges from the tensor product structure, $P$-a.s.
\item The marginal density $p(t,x)$ satisfies, in the distributional sense,
\begin{equation}
\partial_t p = \frac{1}{8}\partial^4_x p + \frac{1}{\sqrt{8\pi t}}\,\partial^2_x \delta_0(x).
\end{equation}
Away from the origin ($x \neq 0$), the source term vanishes and $p$ satisfies the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial^4_x p$.  This recovers the Allouba--Zheng result \cite{AZ} and identifies the source term as the contribution of the local time $L^0_t(B^{(2)})$ in the operator framework.
\end{enumerate}

\label{thm:Levy}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space supporting a L\'evy process $(X_t)_{t\in[0,T]}$ with L\'evy measure $\nu$ satisfying $\int_{\R}(1\wedge z^2)\,\nu(dz) < \infty$, and let $(\mathcal{F}_t)_{t\geq 0}$ be its natural filtration. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\mathcal{H}_J = L^2([0, T] \times \R, dt \otimes \nu)$.  This is the space of integrands for the compensated Poisson integral, not a moment condition on $X_t$ itself.  In particular, $X_t$ need not belong to $L^2(\Omega)$; the operator derivative acts on functionals $F = f(X_T)$ where $f$ belongs to a sufficiently regular class (e.g., $C^2_c(\R)$) ensuring $F \in L^2(\Omega)$.
\item The operator derivative is the difference operator: $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator acting on $f \in C^2(\R)$ is nonlocal:
\begin{equation}
Lf(x) = \int_{\R}\!\Big(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\Big)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space and let $X$ be a stochastic process on this space. An energy space for $X$ is a real separable Hilbert space $\mathcal{H}$ such that:
there exists a densely-defined closed operator $\delta_X : \dom(\delta_X) \subset L^2(\Omega;\mathcal{H}) \to L^2(\Omega)$ (the divergence or stochastic integral), where $L^2(\Omega;\mathcal{H})$ denotes the space of $\mathcal{H}$-valued square-integrable random variables;
the adjoint $D_X := \delta_X^* : \dom(D_X) \subset L^2(\Omega) \to L^2(\Omega;\mathcal{H})$ (the operator derivative) is also densely defined;
the factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.

\label{def:opderiv}
Let $X$ be a stochastic process with energy space $\mathcal{H}$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega;\mathcal{H})$ is defined via Riesz representation:
\begin{equation}\label{eq:Riesz}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u\rangle_{\mathcal{H}}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{thm:factor}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\mathcal{H}$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}
F - \E[F] = \delta_X(\Pi D_X F), \qquad P\text{-a.s.}
\end{equation}

\label{def:bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\mathcal{H}$. For a process $Y = (Y_t)_{t\in[0,T]}$ in the domain of $D_X$ such that $t \mapsto \|\Pi D_X Y_t\|^2_{\mathcal{H}}$ is absolutely continuous on $[0,T]$, the intrinsic quadratic variation has differential
\begin{equation}
d\langle Y\rangle^{(D,\Pi)}_t = \frac{d}{dt}\|\Pi D_X Y_t\|^2_{\mathcal{H}}\,dt.
\end{equation}

\label{thm:ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{P4}. For $\varphi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t\in[0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:ito}
\varphi(Y_t) - \varphi(Y_0) = \int_0^t \varphi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \varphi''(Y_s)\,d\langle Y\rangle^{(D,\Pi)}_s, \qquad P\text{-a.s.}
\end{equation}

\label{prop:CM-BM}
The Cameron--Martin space of Brownian motion is
\begin{equation}
\mathcal{H}_{1/2} = \{h \in C([0,T]) : h(0) = 0,\; h \text{ absolutely continuous},\; h' \in L^2([0,T])\}
\end{equation}
with inner product $\langle h, g\rangle_{\mathcal{H}_{1/2}} = \int_0^T h'(r)g'(r)\,dr$.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}
\mathcal{H}_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I^{H+1/2}_{0+}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I^\beta_{0+}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$, and the inner product is $\langle h_1, h_2\rangle_{\mathcal{H}_H} = \langle \dot{h}_1, \dot{h}_2\rangle_{L^2}$ where $h_i = K_H \dot{h}_i$.

following_proof:
For $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\!\left[\int_0^s B_u\,du \int_0^t B_v\,dv\right] = \int_0^s \int_0^t \min(u,v)\,du\,dv \\
