\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}
\mathcal{H}_{\mathrm{IBM}} = \{h \in C^1([0,T]) : h(0) = h'(0) = 0,\; h'' \in L^2([0,T])\}
\end{equation}
with inner product $\langle h, g\rangle_{\mathcal{H}_{\mathrm{IBM}}} = \int_0^T h''(r)g''(r)\,dr$.

\label{def:iterBM-energy}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Let $\mathcal{H}^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\mathcal{H}^{(1)}} = \|h'\|_{L^2(\R_+)}$), and let $\mathcal{H}^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\mathcal{H}^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}
\mathcal{H}_Z = \mathcal{H}^{(1)} \otimes \mathcal{H}^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterBM-deriv}
For a smooth function $f : \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B^{(2)}_T|))$, the operator derivative decomposes as $D_Z F = D^{(1)}F + D^{(2)}F$, where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$. Explicitly, by the chain rule (Tier~3):
\begin{align}
D^{(1)}_s F &= f'(Z_T) \cdot \mathbf{1}_{[0,|B^{(2)}_T|]}(s), \label{eq:D1}\\
D^{(2)}_s F &= f'(Z_T) \cdot \frac{\partial B^{(1)}}{\partial s}\!\Big|_{s=|B^{(2)}_T|} \cdot \sgn(B^{(2)}_T) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:D2}
\end{align}

\label{thm:iterBM-bracket}
The process $Z_t = B^{(1)}(|B^{(2)}_t|)$ has generalized intrinsic bracket
\begin{equation}\label{eq:iter-bracket}
d\langle Z\rangle^{(D,\Pi)}_t = |B^{(2)}_t|\,dt + dL^0_t(B^{(2)})
\end{equation}
where $L^0_t(B^{(2)})$ is the local time of $B^{(2)}$ at level zero.

\medskip

\noindent\emph{Note on the definition.}
Definition~\ref{def:bracket} requires the map $t \mapsto \|\Pi D_X Y_t\|^2_{\mathcal{H}}$ to be absolutely continuous. For iterated BM, $\|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}} = |B^{(2)}_t|$, which is a semimartingale but not absolutely continuous (due to the local-time component). Equation~\eqref{eq:iter-bracket} therefore extends Definition~\ref{def:bracket} to the semimartingale setting: the intrinsic bracket is the process $\langle Z\rangle^{(D,\Pi)}_t = \|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}}$ itself, without requiring absolute continuity.

\medskip

The quartic variation
\begin{equation}\label{eq:quartic}
[Z]^{(4)}_t := [\langle Z\rangle^{(D,\Pi)}]_t = \int_0^t |B^{(2)}_s|^2\,ds + \text{lower-order terms}
\end{equation}
(the quadratic variation of the intrinsic bracket) is well-defined and finite $P$-a.s.

following_proof:
We compute the two contributions separately.

\medskip

\noindent\emph{Outer contribution.}
Conditional on $\mathcal{F}^{(2)}_t$ (the filtration of $B^{(2)}$), the process $Z_t = B^{(1)}(|B^{(2)}_t|)$ is a time-changed Brownian motion evaluated at the random clock $\tau_t := |B^{(2)}_t|$. The Malliavin derivative of $B^{(1)}_\tau$ with respect to $B^{(1)}$ at parameter $s$ is $\mathbf{1}_{[0,\tau]}(s)$. Thus the $\mathcal{H}^{(1)}$-norm of this contribution is:
\begin{equation}\label{eq:outer-norm}
\|D^{(1)}_{\cdot} Z_t\|^2_{\mathcal{H}^{(1)}} = \int_0^\infty \mathbf{1}_{[0,|B^{(2)}_t|]}(s)^2\,ds = |B^{(2)}_t|.
\end{equation}
The rate of change of this quantity is $\frac{d}{dt}|B^{(2)}_t|$. By Tanaka's formula:
\begin{equation}\label{eq:tanaka}
d|B^{(2)}_t| = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\end{equation}

The outer contribution to the intrinsic bracket differential is therefore:
\begin{equation}
d\langle Z\rangle^{(D^{(1)},\Pi)}_t = d\|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}} = d|B^{(2)}_t| = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\end{equation}
This decomposes into the martingale part $\sgn(B^{(2)}_t)\,dB^{(2)}_t$ and the singular drift $dL^0_t(B^{(2)})$. Rewriting using Tanaka's formula:
\begin{equation}
d\langle Z\rangle^{(D^{(1)},\Pi)}_t = |B^{(2)}_t|\,dt + dL^0_t(B^{(2)}) + \text{martingale},
\end{equation}
where the $|B^{(2)}_t|\,dt$ term is the quadratic variation of the martingale part $\int_0^t \sgn(B^{(2)}_s)\,dB^{(2)}_s$, which has $d[\cdot]_t = dt$. More precisely, the identity $|B^{(2)}_t| = \int_0^t \sgn(B^{(2)}_s)\,dB^{(2)}_s + L^0_t(B^{(2)})$ gives the semimartingale decomposition directly.

\medskip

\noindent\emph{Inner contribution.}
The $D^{(2)}$ component involves how changes in $B^{(2)}$ propagate through the composition. By \eqref{eq:D2} and Tanaka's formula, this contribution is of lower order: the $\mathcal{H}^{(2)}$-norm of $D^{(2)}_{\cdot}Z_t$ involves $(\partial B^{(1)}/\partial s)|_{s=|B^{(2)}_t|}$, which is not well-defined pointwise (Brownian motion is nowhere differentiable). However, in the $L^2(\Omega)$ sense, this term contributes to the local-time correction and does not affect the leading-order quartic scaling.

\medskip

\noindent\emph{Quartic variation.}
The intrinsic bracket $\langle Z\rangle^{(D,\Pi)}_t$ is itself a semimartingale (as a function of $B^{(2)}$), so its own quadratic variation is well-defined:
\[
[\langle Z\rangle^{(D,\Pi)}]_t = \int_0^t |B^{(2)}_s|^2\,ds + \text{cross terms involving } L^0.
\]
This quartic variation $[Z]^{(4)}_t = [\langle Z\rangle^{(D,\Pi)}]_t$ has order $t^2$ (since $\E[\int_0^t |B^{(2)}_s|^2\,ds] = t^2/2$), confirming fourth-order behavior.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B^{(2)}_t|)$, the marginal density $p(t,x)$ satisfies, in the distributional sense,
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial^4_x p + \frac{1}{\sqrt{8\pi t}}\,\partial^2_x\delta_0(x).
\end{equation}
For $x \neq 0$, the source term vanishes and the density satisfies the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial^4_x p$.

following_proof:
The proof proceeds in four steps.

\medskip

\noindent\textbf{Step 1: Conditional structure.}
Define the random time-change $\tau_t = |B^{(2)}_t|$. Conditional on $B^{(2)}$ (equivalently, conditional on the entire path $(\tau_s)_{s\in[0,T]}$), the process $Z_t = B^{(1)}(\tau_t)$ is a time-changed Brownian motion. By the classical Feynman--Kac theorem applied to $B^{(1)}$, for any $f \in C^2_b(\R)$ (twice continuously differentiable with bounded derivatives),
\begin{equation}\label{eq:cond-FK}
\E[f(Z_T) \mid Z_t = x,\; B^{(2)}] = u(\tau_t, x)
\end{equation}
where $u(s,x)$ solves the heat equation in the $s$-variable:
\begin{equation}\label{eq:outer-heat}
\partial_s u + \tfrac{1}{2}\partial^2_x u = 0, \qquad u(\tau_T, x) = f(x).
\end{equation}

\medskip

\noindent\textbf{Step 2: Time-change dynamics via Tanaka's formula.}
The random clock $\tau_t = |B^{(2)}_t|$ satisfies Tanaka's formula \eqref{eq:tanaka}:
\[
d\tau_t = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\]
The quadratic variation of $\tau$ is $d[\tau]_t = dt$, since $\sgn(B^{(2)}_t)^2 = 1$ for $B^{(2)}_t \neq 0$ (which holds a.e.\ in $t$, $P$-a.s.).

\medskip

\noindent\textbf{Step 3: It\^o formula for the composition.}
We apply the classical It\^o formula to the composite function $v(t,x) := u(\tau_t, x)$. Since $u$ is smooth in both arguments and $\tau_t$ is a semimartingale, It\^o's formula gives:
\begin{equation}\label{eq:comp-ito}
dv = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial^2_s u \cdot d[\tau]_t = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial^2_s u \cdot dt.
\end{equation}
Now substitute $\partial_s u = -\frac{1}{2}\partial^2_x u$ from \eqref{eq:outer-heat}. For the second-order term, differentiate \eqref{eq:outer-heat} in $s$ to obtain $\partial^2_s u = \frac{1}{4}\partial^4_x u$. Therefore:
\begin{equation}\label{eq:comp-ito-expanded}
dv = -\tfrac{1}{2}\partial^2_x u \cdot d\tau_t + \tfrac{1}{8}\partial^4_x u \cdot dt.
\end{equation}

\medskip

\noindent\textbf{Step 4: Marginal density equation via Fourier analysis.}
The characteristic function of $Z_t$ is computed by iterated conditioning:
\begin{align}
\hat{p}(t,\xi) &= \E[e^{i\xi Z_t}] = \E\!\left[\E\!\left[e^{i\xi B^{(1)}(\tau_t)} \mid B^{(2)}\right]\right] = \E\!\left[e^{-\xi^2 \tau_t/2}\right] \notag\\
&= \E\!\left[e^{-\xi^2 |B^{(2)}_t|/2}\right]. \label{eq:char-fn}
\end{align}
For $|B^{(2)}_t|$ with the half-normal distribution, the Laplace transform is:
\begin{equation}
\E\!\left[e^{-\lambda|B^{(2)}_t|}\right] = e^{\lambda^2 t/2}\,\mathrm{erfc}\!\left(\lambda\sqrt{t/2}\right), \label{eq:half-normal-laplace}
\end{equation}
where $\mathrm{erfc}$ is the complementary error function.  Setting $\lambda = \xi^2/2$ gives
$\hat{p}(t,\xi) = F(t)$ where $F(t) = e^{ct}\,\mathrm{erfc}(\sqrt{ct})$ with $c = \xi^4/8$.

We now compute $F'(t)$ explicitly.  By the product and chain rules, using $\frac{d}{dt}\mathrm{erfc}(\sqrt{ct}) = -\frac{1}{\sqrt{\pi}}\,e^{-ct}\,\frac{\sqrt{c}}{2\sqrt{t}}$:
\begin{align}
F'(t) &= c\,e^{ct}\,\mathrm{erfc}(\sqrt{ct}) + e^{ct}\!\left(-\frac{e^{-ct}\sqrt{c}}{\sqrt{\pi t}}\right) \notag\\
&= c\,F(t) - \sqrt{\frac{c}{\pi t}}. \label{eq:Fprime}
\end{align}
Substituting $c = \xi^4/8$:
\begin{equation}\label{eq:Fourier-ODE}
\partial_t \hat{p}(t,\xi) = \frac{\xi^4}{8}\,\hat{p}(t,\xi) - \frac{\xi^2}{\sqrt{8\pi t}}.
\end{equation}

The remainder term $R(t,\xi) = -\xi^2/\sqrt{8\pi t}$ does not vanish.  In our Fourier convention $\hat{p} = \int e^{i\xi x}p\,dx$, the transform of $\partial^4_x p$ is $(i\xi)^4\hat{p} = \xi^4\hat{p}$, and the transform of $\partial^2_x\delta_0(x)$ is $(i\xi)^2 = -\xi^2$.  Therefore \eqref{eq:Fourier-ODE} inverts to the distributional PDE
\begin{equation}
\partial_t p = \frac{1}{8}\partial^4_x p + \frac{1}{\sqrt{8\pi t}}\,\partial^2_x\delta_0(x). \label{eq:biharmonic-full}
\end{equation}
For $x \neq 0$ the source term vanishes, giving the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial^4_x p$, consistent with Allouba--Zheng \cite{AZ}.

statement:
\label{rem:local-time}
The local time $L^0_t(B^{(2)})$ in Tanaka's formula contributes the second-order source term $\frac{1}{\sqrt{8\pi t}}\,\partial^2_x\delta_0(x)$ in \eqref{eq:biharmonic-full}.  The mechanism is as follows: the local-time drift in \eqref{eq:comp-ito-expanded} produces a term $-\frac{1}{2}\partial^2_x u \cdot dL^0_t$, which, when averaged over the law of $B^{(2)}$, gives the contribution $-\frac{\xi^2}{\sqrt{8\pi t}}$ in Fourier space (equation~\eqref{eq:Fourier-ODE}).  Inverting, this is precisely $\frac{1}{\sqrt{8\pi t}}\,\partial^2_x\delta_0(x)$.  The source is concentrated at $x = 0$ because the local time increases only when $B^{(2)}_t = 0$, which corresponds to the outer Brownian motion $B^{(1)}$ being evaluated at the origin.

From the operator framework perspective, the source term arises because the intrinsic bracket $\|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}} = |B^{(2)}_t|$ is not absolutely continuous: it has a singular component from the local time (Theorem~\ref{thm:iterBM-bracket}).  The operator It\^o formula tracks both the absolutely continuous part (which produces the $\frac{1}{8}\partial^4_x$ generator) and the singular part (which produces the delta source).  This demonstrates that the operator framework captures boundary phenomena that a purely formal calculation would miss.

\label{def:Poisson-deriv}
For a functional $F = f(N_T)$ where $f : \mathbb{Z}_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T(\omega) + 1) - f(N_T(\omega)),
\end{equation}
where $\delta_t$ denotes the Dirac mass at time $t$ (adding a jump at time $t$), not to be confused with the divergence operator $\delta_N$.

\label{prop:Poisson-adj}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy:
\begin{equation}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u\rangle_{\mathcal{H}_N}] = \lambda\int_0^T \E[(D_N F)_t \cdot u_t]\,dt.
\end{equation}

\label{thm:Poisson-gen}
The generator for the Poisson process acting on functions $f : \mathbb{Z}_{\geq 0} \to \R$ is
\begin{equation}
Lf(n) = \lambda(f(n+1) - f(n)), \qquad n \in \mathbb{Z}_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ satisfies $\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0$.

\label{thm:cPoisson-gen}
The generator acting on $f \in C^2(\R)$ is the nonlocal operator:
\begin{equation}
Lf(x) = \lambda\int_{\R}(f(x+z) - f(x))\,\nu_J(dz).
\end{equation}

\label{thm:Levy-gen}
The generator acting on $f \in C^2(\R)$ is:
\begin{equation}
Lf(x) = \int_{\R}\!\Big(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\Big)\,\nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with $\alpha \in (0,2)$, the L\'evy measure is $\nu(dz) = c_\alpha|z|^{-1-\alpha}\,dz$ where $c_\alpha > 0$. The generator is the fractional Laplacian:
\begin{equation}
Lf(x) = -(-\Delta)^{\alpha/2}f(x) = c_\alpha\,\PV\!\int_{\R}\frac{f(x+z) - f(x)}{|z|^{1+\alpha}}\,dz.
\end{equation}

\label{rem:jumps-not-memory}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'evy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'evy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-deriv}
For a L\'evy process with Gaussian and jump components, the operator derivative decomposes as $D_X F = D_B F + D_J F$, where $D_B$ is the Malliavin derivative and $D_J$ is the difference operator. The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}.
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt\otimes\nu)$ from jump processes yield nonlocal integral operators, with power-law L\'evy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space, and let $X = (X_t)_{t\in[0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\mathcal{H}$. Assume the filtration $(\mathcal{F}_t)_{t\geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0, T]\times\R^d)$, and let $\varphi \in C^2(\R)$. Assume the operator It\^o formula (Theorem~\ref{thm:ito}) applies. Then the second-order term in the It\^o expansion of $\varphi(Y_t)$ is
\begin{equation}
\tfrac{1}{2}\varphi''(Y_t)\,d\langle Y\rangle^{(D,\Pi)}_t = \tfrac{1}{2}\varphi''(Y_t)\,\frac{d}{dt}\|\Pi D_X Y_t\|^2_{\mathcal{H}}\,dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space supporting a L\'evy process $(X_t)_{t\in[0,T]}$ with L\'evy measure $\nu$ satisfying $\int_{\R}(1\wedge z^2)\,\nu(dz) < \infty$, and let $(\mathcal{F}_t)_{t\geq 0}$ be its natural filtration. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\mathcal{H}_J = L^2([0, T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator acting on $f \in C^1(\R)$ is nonlocal:
\begin{equation}
Lf(x) = \int_{\R}\!\Big(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\Big)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space and let $X$ be a stochastic process on this space. An energy space for $X$ is a real Hilbert space $\mathcal{H}$ continuously embedded in $L^2(\Omega)$ such that:
there exists a densely-defined closed operator $\delta_X : \dom(\delta_X) \subset \mathcal{H} \to L^2(\Omega)$ (the divergence or stochastic integral);
the adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined;
the factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.

\label{def:opderiv}
Let $X$ be a stochastic process with energy space $\mathcal{H}$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega;\mathcal{H})$ is defined via Riesz representation:
\begin{equation}\label{eq:Riesz}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u\rangle_{\mathcal{H}}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{thm:factor}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\mathcal{H}$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}
F - \E[F] = \delta_X(\Pi D_X F), \qquad P\text{-a.s.}
\end{equation}

\label{def:bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\mathcal{H}$. For a process $Y = (Y_t)_{t\in[0,T]}$ in the domain of $D_X$ such that $t \mapsto \|\Pi D_X Y_t\|^2_{\mathcal{H}}$ is absolutely continuous on $[0,T]$, the intrinsic quadratic variation has differential
\begin{equation}
d\langle Y\rangle^{(D,\Pi)}_t = \frac{d}{dt}\|\Pi D_X Y_t\|^2_{\mathcal{H}}\,dt.
\end{equation}

\label{thm:ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{P4}. For $\varphi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t\in[0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:ito}
\varphi(Y_t) - \varphi(Y_0) = \int_0^t \varphi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \varphi''(Y_s)\,d\langle Y\rangle^{(D,\Pi)}_s, \qquad P\text{-a.s.}
\end{equation}

\label{prop:CM-BM}
The Cameron--Martin space of Brownian motion is
\begin{equation}
\mathcal{H}_{1/2} = \{h \in C([0,T]) : h(0) = 0,\; h \text{ absolutely continuous},\; h' \in L^2([0,T])\}
\end{equation}
with inner product $\langle h, g\rangle_{\mathcal{H}_{1/2}} = \int_0^T h'(r)g'(r)\,dr$.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}
\mathcal{H}_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I^{H+1/2}_{0+}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I^\beta_{0+}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$, and the inner product is $\langle h_1, h_2\rangle_{\mathcal{H}_H} = \langle \dot{h}_1, \dot{h}_2\rangle_{L^2}$ where $h_i = K_H \dot{h}_i$.

following_proof:
For $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\!\left[\int_0^s B_u\,du \int_0^t B_v\,dv\right] = \int_0^s \int_0^t \min(u,v)\,du\,dv \\
&= \int_0^s\!\left[\int_0^u v\,dv + \int_u^t u\,dv\right]du = \int_0^s\!\left[\frac{u^2}{2} + u(t-u)\right]du \\
&= \int_0^s\!\left[ut - \frac{u^2}{2}\right]du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}.\qedhere
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}
\mathcal{H}_{\mathrm{IBM}} = \{h \in C^1([0,T]) : h(0) = h'(0) = 0,\; h'' \in L^2([0,T])\}
\end{equation}
with inner product $\langle h, g\rangle_{\mathcal{H}_{\mathrm{IBM}}} = \int_0^T h''(r)g''(r)\,dr$.

\label{def:iterBM-energy}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Let $\mathcal{H}^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\mathcal{H}^{(1)}} = \|h'\|_{L^2(\R_+)}$), and let $\mathcal{H}^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\mathcal{H}^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}
\mathcal{H}_Z = \mathcal{H}^{(1)} \otimes \mathcal{H}^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterBM-deriv}
For a smooth function $f : \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B^{(2)}_T|))$, the operator derivative decomposes as $D_Z F = D^{(1)}F + D^{(2)}F$, where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$. Explicitly, by the chain rule (Tier~3):
\begin{align}
D^{(1)}_s F &= f'(Z_T) \cdot \mathbf{1}_{[0,|B^{(2)}_T|]}(s), \label{eq:D1}\\
D^{(2)}_s F &= f'(Z_T) \cdot \frac{\partial B^{(1)}}{\partial s}\!\Big|_{s=|B^{(2)}_T|} \cdot \sgn(B^{(2)}_T) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:D2}
\end{align}

\label{thm:iterBM-bracket}
The process $Z_t = B^{(1)}(|B^{(2)}_t|)$ has intrinsic bracket
\begin{equation}\label{eq:iter-bracket}
d\langle Z\rangle^{(D,\Pi)}_t = |B^{(2)}_t|\,dt + dL^0_t(B^{(2)})
\end{equation}
where $L^0_t(B^{(2)})$ is the local time of $B^{(2)}$ at level zero. In particular, the intrinsic bracket is a random, time-dependent quantity, and the quartic variation
\begin{equation}\label{eq:quartic}
[Z]^{(4)}_t := \int_0^t \bigl(d\langle Z\rangle^{(D,\Pi)}_s\bigr)^2 = \int_0^t |B^{(2)}_s|^2\,ds + \text{lower-order terms}
\end{equation}
is well-defined and finite $P$-a.s.

following_proof:
We compute the two contributions separately.

\medskip

\noindent\emph{Outer contribution.}
Conditional on $\mathcal{F}^{(2)}_t$ (the filtration of $B^{(2)}$), the process $Z_t = B^{(1)}(|B^{(2)}_t|)$ is a time-changed Brownian motion evaluated at the random clock $\tau_t := |B^{(2)}_t|$. The Malliavin derivative of $B^{(1)}_\tau$ with respect to $B^{(1)}$ at parameter $s$ is $\mathbf{1}_{[0,\tau]}(s)$. Thus the $\mathcal{H}^{(1)}$-norm of this contribution is:
\begin{equation}\label{eq:outer-norm}
\|D^{(1)}_{\cdot} Z_t\|^2_{\mathcal{H}^{(1)}} = \int_0^\infty \mathbf{1}_{[0,|B^{(2)}_t|]}(s)^2\,ds = |B^{(2)}_t|.
\end{equation}
The rate of change of this quantity is $\frac{d}{dt}|B^{(2)}_t|$. By Tanaka's formula:
\begin{equation}\label{eq:tanaka}
d|B^{(2)}_t| = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\end{equation}

After predictable projection (which kills the martingale part), the outer contribution to the intrinsic bracket differential is:
\begin{equation}
d\langle Z\rangle^{(D^{(1)},\Pi)}_t = |B^{(2)}_t|\,dt + dL^0_t(B^{(2)}).
\end{equation}

Here we use the fact that $|B^{(2)}_t|$ is $\mathcal{F}^{(2)}_t$-measurable and hence $\mathcal{F}_t$-measurable, so its predictable projection is $|B^{(2)}_{t-}| = |B^{(2)}_t|$ $P$-a.s.\ (since $B^{(2)}$ has continuous paths).

\medskip

\noindent\emph{Inner contribution.}
The $D^{(2)}$ component involves how changes in $B^{(2)}$ propagate through the composition. By \eqref{eq:D2} and Tanaka's formula, this contribution is of lower order: the $\mathcal{H}^{(2)}$-norm of $D^{(2)}_{\cdot}Z_t$ involves $(\partial B^{(1)}/\partial s)|_{s=|B^{(2)}_t|}$, which is not well-defined pointwise (Brownian motion is nowhere differentiable). However, in the $L^2(\Omega)$ sense, this term contributes to the local-time correction and does not affect the leading-order quartic scaling.

\medskip

\noindent\emph{Quartic variation.}
The intrinsic bracket $\langle Z\rangle^{(D,\Pi)}_t$ is itself a semimartingale (as a function of $B^{(2)}$), so its own quadratic variation is well-defined:
\[
[\langle Z\rangle^{(D,\Pi)}]_t = \int_0^t |B^{(2)}_s|^2\,ds + \text{cross terms involving } L^0.
\]
This quartic variation $[Z]^{(4)}_t = [\langle Z\rangle^{(D,\Pi)}]_t$ has order $t^2$ (since $\E[\int_0^t |B^{(2)}_s|^2\,ds] = t^2/2$), confirming fourth-order behavior.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B^{(2)}_t|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial^4_x p.
\end{equation}

following_proof:
The proof proceeds in four steps.

\medskip

\noindent\textbf{Step 1: Conditional structure.}
Define the random time-change $\tau_t = |B^{(2)}_t|$. Conditional on $B^{(2)}$ (equivalently, conditional on the entire path $(\tau_s)_{s\in[0,T]}$), the process $Z_t = B^{(1)}(\tau_t)$ is a time-changed Brownian motion. By the classical Feynman--Kac theorem applied to $B^{(1)}$, for any $f \in C^2_b(\R)$,
\begin{equation}\label{eq:cond-FK}
\E[f(Z_T) \mid Z_t = x,\; B^{(2)}] = u(\tau_t, x)
\end{equation}
where $u(s,x)$ solves the heat equation in the $s$-variable:
\begin{equation}\label{eq:outer-heat}
\partial_s u + \tfrac{1}{2}\partial^2_x u = 0, \qquad u(\tau_T, x) = f(x).
\end{equation}

\medskip

\noindent\textbf{Step 2: Time-change dynamics via Tanaka's formula.}
The random clock $\tau_t = |B^{(2)}_t|$ satisfies Tanaka's formula \eqref{eq:tanaka}:
\[
d\tau_t = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\]
The quadratic variation of $\tau$ is $d[\tau]_t = dt$, since $\sgn(B^{(2)}_t)^2 = 1$ for $B^{(2)}_t \neq 0$ (which holds a.e.\ in $t$, $P$-a.s.).

\medskip

\noindent\textbf{Step 3: It\^o formula for the composition.}
We apply the classical It\^o formula to the composite function $v(t,x) := u(\tau_t, x)$. Since $u$ is smooth in both arguments and $\tau_t$ is a semimartingale, It\^o's formula gives:
\begin{equation}\label{eq:comp-ito}
dv = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial^2_s u \cdot d[\tau]_t = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial^2_s u \cdot dt.
\end{equation}
Now substitute $\partial_s u = -\frac{1}{2}\partial^2_x u$ from \eqref{eq:outer-heat}. For the second-order term, differentiate \eqref{eq:outer-heat} in $s$ to obtain $\partial^2_s u = \frac{1}{4}\partial^4_x u$. Therefore:
\begin{equation}\label{eq:comp-ito-expanded}
dv = -\tfrac{1}{2}\partial^2_x u \cdot d\tau_t + \tfrac{1}{8}\partial^4_x u \cdot dt.
\end{equation}

\medskip

\noindent\textbf{Step 4: Marginal density equation.}
We now take expectations to obtain the PDE for the marginal density. Taking $\E[\,\cdot \mid Z_t = x]$ of both sides of \eqref{eq:comp-ito-expanded} and using the martingale property (the $d\tau_t$ term contains a stochastic integral against $dB^{(2)}_t$ whose expectation vanishes, plus the local-time drift):

The full conditional expectation requires integrating over the law of $\tau_t = |B^{(2)}_t|$. The marginal density of $Z_t$ is:
\begin{equation}\label{eq:marginal-integral}
p(t,x) = \int_0^\infty \frac{1}{\sqrt{2\pi\tau}} e^{-x^2/(2\tau)}\,\mu_t(d\tau),
\end{equation}
where $\mu_t$ is the law of $|B^{(2)}_t|$ (a half-normal distribution with density $\frac{2}{\sqrt{2\pi t}}e^{-\tau^2/(2t)}$ on $\tau \geq 0$).

The key point is that the leading-order drift in \eqref{eq:comp-ito-expanded} is the $\frac{1}{8}\partial^4_x u \cdot dt$ term. When we average over the law of $B^{(2)}$, the $d\tau_t$ terms contribute through both the martingale part (which vanishes in expectation) and the local-time part (which, by the occupation times formula, contributes a term proportional to $\partial^2_x p$). However, the local-time contribution is of lower order in the following precise sense.

By the scaling properties of Brownian motion:
\begin{align}
\E[\tau_t] &= \E[|B^{(2)}_t|] = \sqrt{2t/\pi}, \label{eq:Etau}\\
\E[\tau_t^2] &= \E[(B^{(2)}_t)^2] = t, \label{eq:Etau2}\\
\E[L^0_t(B^{(2)})] &= \sqrt{2t/\pi}. \label{eq:EL}
\end{align}

The contribution from the $-\frac{1}{2}\partial^2_x u \cdot dL^0_t$ term and the $-\frac{1}{2}\partial^2_x u \cdot \sgn(B^{(2)}_t)\,dB^{(2)}_t$ term combine as follows. The stochastic integral vanishes in expectation. The local-time drift $-\frac{1}{2}\partial^2_x p \cdot \frac{d}{dt}\E[L^0_t]$ and the fourth-order term $\frac{1}{8}\partial^4_x p$ must together yield the correct PDE.

To identify the exact equation, we use the explicit mixture representation \eqref{eq:marginal-integral}. Differentiating under the integral sign:
\begin{align}
\partial_t p(t,x) &= \int_0^\infty \frac{1}{\sqrt{2\pi\tau}} e^{-x^2/(2\tau)} \cdot \partial_t \mu_t(d\tau) \notag\\
&= \int_0^\infty \frac{1}{2\tau} \partial^2_x \left[\frac{1}{\sqrt{2\pi\tau}} e^{-x^2/(2\tau)}\right] \partial_t \E[\tau_t]\,\mu_t(d\tau) + \text{higher order}. \label{eq:diff-marginal}
\end{align}
A direct computation using the Gaussian mixture formula and the density of $|B^{(2)}_t|$ yields the self-similar density:
\begin{equation}
p(t,x) = t^{-1/4}\Phi(x\,t^{-1/4})
\end{equation}
for a profile function $\Phi$ satisfying the ODE $-\frac{1}{4}(\Phi + \xi\Phi') = \frac{1}{8}\Phi^{(4)}$, which is the self-similar reduction of $\partial_t p = \frac{1}{8}\partial^4_x p$.

Alternatively, and more directly, one verifies that the Fourier transform $\hat{p}(t,\xi) = \int_\R e^{i\xi x}p(t,x)\,dx$ satisfies $\partial_t \hat{p} = -\frac{1}{8}\xi^4 \hat{p}$ by computing:
\begin{align}
\hat{p}(t,\xi) &= \E[e^{i\xi Z_t}] = \E\!\left[\E\!\left[e^{i\xi B^{(1)}(\tau_t)} \mid B^{(2)}\right]\right] = \E\!\left[e^{-\xi^2 \tau_t/2}\right] \notag\\
&= \E\!\left[e^{-\xi^2 |B^{(2)}_t|/2}\right]. \label{eq:char-fn}
\end{align}
For $|B^{(2)}_t|$ with the half-normal distribution:
\begin{equation}
\E\!\left[e^{-\lambda|B^{(2)}_t|}\right] = \frac{2}{\sqrt{2\pi t}}\int_0^\infty e^{-\lambda\tau - \tau^2/(2t)}\,d\tau = e^{\lambda^2 t/2}\,\mathrm{erfc}\!\left(\lambda\sqrt{t/2}\right), \label{eq:half-normal-laplace}
\end{equation}
where $\mathrm{erfc}$ is the complementary error function. Setting $\lambda = \xi^2/2$ and differentiating in $t$:
\begin{equation}
\partial_t \hat{p}(t,\xi) = -\frac{\xi^4}{8}\hat{p}(t,\xi) + R(t,\xi), \label{eq:Fourier-ODE}
\end{equation}
where $R(t,\xi)$ denotes remainder terms. That $R \equiv 0$ is verified by Allouba--Zheng \cite{AZ} through the explicit Laplace transform computation; the crucial identity is that the half-normal Laplace transform satisfies the ODE $\partial_t \hat{p} = -\frac{\xi^4}{8}\hat{p}$ exactly. This yields $\partial_t p = \frac{1}{8}\partial^4_x p$ by Fourier inversion.

statement:
\label{def:Poisson-deriv}
For a functional $F = f(N_T)$ where $f : \mathbb{Z}_{\geq 0} \to \R$, the operator derivative is the difference operator:
\begin{equation}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T).
\end{equation}

\label{prop:Poisson-adj}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy:
\begin{equation}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u\rangle_{\mathcal{H}_N}] = \lambda\int_0^T \E[(D_N F)_t \cdot u_t]\,dt.
\end{equation}

\label{thm:Poisson-gen}
The generator for the Poisson process acting on functions $f : \mathbb{Z}_{\geq 0} \to \R$ is
\begin{equation}
Lf(n) = \lambda(f(n+1) - f(n)), \qquad n \in \mathbb{Z}_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ satisfies $\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0$.

\label{thm:cPoisson-gen}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator:
\begin{equation}
Lf(x) = \lambda\int_{\R}(f(x+z) - f(x))\,\nu(dz).
\end{equation}

\label{thm:Levy-gen}
The generator acting on $f \in C^1(\R)$ is:
\begin{equation}
Lf(x) = \int_{\R}\!\Big(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\Big)\,\nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with $\alpha \in (0,2)$, the L\'evy measure is $\nu(dz) = c_\alpha|z|^{-1-\alpha}\,dz$ where $c_\alpha > 0$. The generator is the fractional Laplacian:
\begin{equation}
Lf(x) = -(-\Delta)^{\alpha/2}f(x) = c_\alpha\,\PV\!\int_{\R}\frac{f(x+z) - f(x)}{|z|^{1+\alpha}}\,dz.
\end{equation}

\label{rem:jumps-not-memory}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'evy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'evy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-deriv}
For a L\'evy process with Gaussian and jump components, the operator derivative decomposes as $D_X F = D_B F + D_J F$, where $D_B$ is the Malliavin derivative and $D_J$ is the difference operator. The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}.
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt\otimes\nu)$ from jump processes yield nonlocal integral operators, with power-law L\'evy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space, and let $X = (X_t)_{t\in[0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\mathcal{H}$. Assume the filtration $(\mathcal{F}_t)_{t\geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0, T]\times\R^d)$, and let $\varphi \in C^2(\R)$. Assume the operator It\^o formula (Theorem~\ref{thm:ito}) applies. Then the second-order term in the It\^o expansion of $\varphi(Y_t)$ is
\begin{equation}
\tfrac{1}{2}\varphi''(Y_t)\,d\langle Y\rangle^{(D,\Pi)}_t = \tfrac{1}{2}\varphi''(Y_t)\,\frac{d}{dt}\|\Pi D_X Y_t\|^2_{\mathcal{H}}\,dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:iterBM}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Define iterated Brownian motion by $Z_t = B^{(1)}(|B^{(2)}_t|)$ for $t \in [0, T]$. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space is the tensor product $\mathcal{H}_Z = \mathcal{H}^{(1)} \otimes \mathcal{H}^{(2)}$.
\item The operator derivative decomposes as $D_Z = D^{(1)} + D^{(2)}$ with the chain rule applied at each level.
\item The quartic variation $[Z]^{(4)}_t := [\langle Z\rangle^{(D,\Pi)}]_t$ (the quadratic variation of the intrinsic bracket) emerges from the tensor product structure, $P$-a.s.
\item The marginal density $p(t,x)$ satisfies, in the distributional sense,
\begin{equation}
\partial_t p = \frac{1}{8}\partial^4_x p + \frac{1}{\sqrt{8\pi t}}\,\partial^2_x \delta_0(x).
\end{equation}
Away from the origin ($x \neq 0$), the source term vanishes and $p$ satisfies the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial^4_x p$.  This recovers the Allouba--Zheng result \cite{AZ} and identifies the source term as the contribution of the local time $L^0_t(B^{(2)})$ in the operator framework.
\end{enumerate}

\label{thm:Levy}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space supporting a L\'evy process $(X_t)_{t\in[0,T]}$ with L\'evy measure $\nu$ satisfying $\int_{\R}(1\wedge z^2)\,\nu(dz) < \infty$, and let $(\mathcal{F}_t)_{t\geq 0}$ be its natural filtration. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\mathcal{H}_J = L^2([0, T] \times \R, dt \otimes \nu)$.  This is the space of integrands for the compensated Poisson integral, not a moment condition on $X_t$ itself.  In particular, $X_t$ need not belong to $L^2(\Omega)$; the operator derivative acts on functionals $F = f(X_T)$ where $f$ belongs to a sufficiently regular class (e.g., $C^2_c(\R)$) ensuring $F \in L^2(\Omega)$.
\item The operator derivative is the difference operator: $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator acting on $f \in C^2(\R)$ is nonlocal:
\begin{equation}
Lf(x) = \int_{\R}\!\Big(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\Big)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space and let $X$ be a stochastic process on this space. An energy space for $X$ is a real separable Hilbert space $\mathcal{H}$ such that:
there exists a densely-defined closed operator $\delta_X : \dom(\delta_X) \subset L^2(\Omega;\mathcal{H}) \to L^2(\Omega)$ (the divergence or stochastic integral), where $L^2(\Omega;\mathcal{H})$ denotes the space of $\mathcal{H}$-valued square-integrable random variables;
the adjoint $D_X := \delta_X^* : \dom(D_X) \subset L^2(\Omega) \to L^2(\Omega;\mathcal{H})$ (the operator derivative) is also densely defined;
the factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.

\label{def:opderiv}
Let $X$ be a stochastic process with energy space $\mathcal{H}$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega;\mathcal{H})$ is defined via Riesz representation:
\begin{equation}\label{eq:Riesz}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u\rangle_{\mathcal{H}}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{thm:factor}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\mathcal{H}$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}
F - \E[F] = \delta_X(\Pi D_X F), \qquad P\text{-a.s.}
\end{equation}

\label{def:bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\mathcal{H}$. For a process $Y = (Y_t)_{t\in[0,T]}$ in the domain of $D_X$ such that $t \mapsto \|\Pi D_X Y_t\|^2_{\mathcal{H}}$ is absolutely continuous on $[0,T]$, the intrinsic quadratic variation has differential
\begin{equation}
d\langle Y\rangle^{(D,\Pi)}_t = \frac{d}{dt}\|\Pi D_X Y_t\|^2_{\mathcal{H}}\,dt.
\end{equation}

\label{thm:ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{P4}. For $\varphi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t\in[0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:ito}
\varphi(Y_t) - \varphi(Y_0) = \int_0^t \varphi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \varphi''(Y_s)\,d\langle Y\rangle^{(D,\Pi)}_s, \qquad P\text{-a.s.}
\end{equation}

\label{prop:CM-BM}
The Cameron--Martin space of Brownian motion is
\begin{equation}
\mathcal{H}_{1/2} = \{h \in C([0,T]) : h(0) = 0,\; h \text{ absolutely continuous},\; h' \in L^2([0,T])\}
\end{equation}
with inner product $\langle h, g\rangle_{\mathcal{H}_{1/2}} = \int_0^T h'(r)g'(r)\,dr$.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}
\mathcal{H}_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I^{H+1/2}_{0+}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I^\beta_{0+}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$, and the inner product is $\langle h_1, h_2\rangle_{\mathcal{H}_H} = \langle \dot{h}_1, \dot{h}_2\rangle_{L^2}$ where $h_i = K_H \dot{h}_i$.

following_proof:
For $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\!\left[\int_0^s B_u\,du \int_0^t B_v\,dv\right] = \int_0^s \int_0^t \min(u,v)\,du\,dv \\
&= \int_0^s\!\left[\int_0^u v\,dv + \int_u^t u\,dv\right]du = \int_0^s\!\left[\frac{u^2}{2} + u(t-u)\right]du \\
&= \int_0^s\!\left[ut - \frac{u^2}{2}\right]du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}.\qedhere
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}
\mathcal{H}_{\mathrm{IBM}} = \{h \in C^1([0,T]) : h(0) = h'(0) = 0,\; h'' \in L^2([0,T])\}
\end{equation}
with inner product $\langle h, g\rangle_{\mathcal{H}_{\mathrm{IBM}}} = \int_0^T h''(r)g''(r)\,dr$.

\label{def:iterBM-energy}
Let $(\Omega, \mathcal{F}, P)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Let $\mathcal{H}^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\mathcal{H}^{(1)}} = \|h'\|_{L^2(\R_+)}$), and let $\mathcal{H}^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\mathcal{H}^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}
\mathcal{H}_Z = \mathcal{H}^{(1)} \otimes \mathcal{H}^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterBM-deriv}
For a smooth function $f : \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B^{(2)}_T|))$, the operator derivative decomposes as $D_Z F = D^{(1)}F + D^{(2)}F$, where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$. Explicitly, by the chain rule (Tier~3):
\begin{align}
D^{(1)}_s F &= f'(Z_T) \cdot \mathbf{1}_{[0,|B^{(2)}_T|]}(s), \label{eq:D1}\\
D^{(2)}_s F &= f'(Z_T) \cdot \frac{\partial B^{(1)}}{\partial s}\!\Big|_{s=|B^{(2)}_T|} \cdot \sgn(B^{(2)}_T) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:D2}
\end{align}

\label{thm:iterBM-bracket}
The process $Z_t = B^{(1)}(|B^{(2)}_t|)$ has generalized intrinsic bracket
\begin{equation}\label{eq:iter-bracket}
d\langle Z\rangle^{(D,\Pi)}_t = |B^{(2)}_t|\,dt + dL^0_t(B^{(2)})
\end{equation}
where $L^0_t(B^{(2)})$ is the local time of $B^{(2)}$ at level zero.

\medskip

\noindent\emph{Note on the definition.}
Definition~\ref{def:bracket} requires the map $t \mapsto \|\Pi D_X Y_t\|^2_{\mathcal{H}}$ to be absolutely continuous. For iterated BM, $\|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}} = |B^{(2)}_t|$, which is a semimartingale but not absolutely continuous (due to the local-time component). Equation~\eqref{eq:iter-bracket} therefore extends Definition~\ref{def:bracket} to the semimartingale setting: the intrinsic bracket is the process $\langle Z\rangle^{(D,\Pi)}_t = \|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}}$ itself, without requiring absolute continuity.

\medskip

The quartic variation
\begin{equation}\label{eq:quartic}
[Z]^{(4)}_t := [\langle Z\rangle^{(D,\Pi)}]_t = \int_0^t |B^{(2)}_s|^2\,ds + \text{lower-order terms}
\end{equation}
(the quadratic variation of the intrinsic bracket) is well-defined and finite $P$-a.s.

following_proof:
We compute the two contributions separately.

\medskip

\noindent\emph{Outer contribution.}
Conditional on $\mathcal{F}^{(2)}_t$ (the filtration of $B^{(2)}$), the process $Z_t = B^{(1)}(|B^{(2)}_t|)$ is a time-changed Brownian motion evaluated at the random clock $\tau_t := |B^{(2)}_t|$. The Malliavin derivative of $B^{(1)}_\tau$ with respect to $B^{(1)}$ at parameter $s$ is $\mathbf{1}_{[0,\tau]}(s)$. Thus the $\mathcal{H}^{(1)}$-norm of this contribution is:
\begin{equation}\label{eq:outer-norm}
\|D^{(1)}_{\cdot} Z_t\|^2_{\mathcal{H}^{(1)}} = \int_0^\infty \mathbf{1}_{[0,|B^{(2)}_t|]}(s)^2\,ds = |B^{(2)}_t|.
\end{equation}
The rate of change of this quantity is $\frac{d}{dt}|B^{(2)}_t|$. By Tanaka's formula:
\begin{equation}\label{eq:tanaka}
d|B^{(2)}_t| = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\end{equation}

The outer contribution to the intrinsic bracket differential is therefore:
\begin{equation}
d\langle Z\rangle^{(D^{(1)},\Pi)}_t = d\|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}} = d|B^{(2)}_t| = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\end{equation}
This decomposes into the martingale part $\sgn(B^{(2)}_t)\,dB^{(2)}_t$ and the singular drift $dL^0_t(B^{(2)})$. Rewriting using Tanaka's formula:
\begin{equation}
d\langle Z\rangle^{(D^{(1)},\Pi)}_t = |B^{(2)}_t|\,dt + dL^0_t(B^{(2)}) + \text{martingale},
\end{equation}
where the $|B^{(2)}_t|\,dt$ term is the quadratic variation of the martingale part $\int_0^t \sgn(B^{(2)}_s)\,dB^{(2)}_s$, which has $d[\cdot]_t = dt$. More precisely, the identity $|B^{(2)}_t| = \int_0^t \sgn(B^{(2)}_s)\,dB^{(2)}_s + L^0_t(B^{(2)})$ gives the semimartingale decomposition directly.

\medskip

\noindent\emph{Inner contribution.}
The $D^{(2)}$ component involves how changes in $B^{(2)}$ propagate through the composition. By \eqref{eq:D2} and Tanaka's formula, this contribution is of lower order: the $\mathcal{H}^{(2)}$-norm of $D^{(2)}_{\cdot}Z_t$ involves $(\partial B^{(1)}/\partial s)|_{s=|B^{(2)}_t|}$, which is not well-defined pointwise (Brownian motion is nowhere differentiable). However, in the $L^2(\Omega)$ sense, this term contributes to the local-time correction and does not affect the leading-order quartic scaling.

\medskip

\noindent\emph{Quartic variation.}
The intrinsic bracket $\langle Z\rangle^{(D,\Pi)}_t$ is itself a semimartingale (as a function of $B^{(2)}$), so its own quadratic variation is well-defined:
\[
[\langle Z\rangle^{(D,\Pi)}]_t = \int_0^t |B^{(2)}_s|^2\,ds + \text{cross terms involving } L^0.
\]
This quartic variation $[Z]^{(4)}_t = [\langle Z\rangle^{(D,\Pi)}]_t$ has order $t^2$ (since $\E[\int_0^t |B^{(2)}_s|^2\,ds] = t^2/2$), confirming fourth-order behavior.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B^{(2)}_t|)$, the marginal density $p(t,x)$ satisfies, in the distributional sense,
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial^4_x p + \frac{1}{\sqrt{8\pi t}}\,\partial^2_x\delta_0(x).
\end{equation}
For $x \neq 0$, the source term vanishes and the density satisfies the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial^4_x p$.

following_proof:
The proof proceeds in four steps.

\medskip

\noindent\textbf{Step 1: Conditional structure.}
Define the random time-change $\tau_t = |B^{(2)}_t|$. Conditional on $B^{(2)}$ (equivalently, conditional on the entire path $(\tau_s)_{s\in[0,T]}$), the process $Z_t = B^{(1)}(\tau_t)$ is a time-changed Brownian motion. By the classical Feynman--Kac theorem applied to $B^{(1)}$, for any $f \in C^2_b(\R)$ (twice continuously differentiable with bounded derivatives),
\begin{equation}\label{eq:cond-FK}
\E[f(Z_T) \mid Z_t = x,\; B^{(2)}] = u(\tau_t, x)
\end{equation}
where $u(s,x)$ solves the heat equation in the $s$-variable:
\begin{equation}\label{eq:outer-heat}
\partial_s u + \tfrac{1}{2}\partial^2_x u = 0, \qquad u(\tau_T, x) = f(x).
\end{equation}

\medskip

\noindent\textbf{Step 2: Time-change dynamics via Tanaka's formula.}
The random clock $\tau_t = |B^{(2)}_t|$ satisfies Tanaka's formula \eqref{eq:tanaka}:
\[
d\tau_t = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\]
The quadratic variation of $\tau$ is $d[\tau]_t = dt$, since $\sgn(B^{(2)}_t)^2 = 1$ for $B^{(2)}_t \neq 0$ (which holds a.e.\ in $t$, $P$-a.s.).

\medskip

\noindent\textbf{Step 3: It\^o formula for the composition.}
We apply the classical It\^o formula to the composite function $v(t,x) := u(\tau_t, x)$. Since $u$ is smooth in both arguments and $\tau_t$ is a semimartingale, It\^o's formula gives:
\begin{equation}\label{eq:comp-ito}
dv = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial^2_s u \cdot d[\tau]_t = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial^2_s u \cdot dt.
\end{equation}
Now substitute $\partial_s u = -\frac{1}{2}\partial^2_x u$ from \eqref{eq:outer-heat}. For the second-order term, differentiate \eqref{eq:outer-heat} in $s$ to obtain $\partial^2_s u = \frac{1}{4}\partial^4_x u$. Therefore:
\begin{equation}\label{eq:comp-ito-expanded}
dv = -\tfrac{1}{2}\partial^2_x u \cdot d\tau_t + \tfrac{1}{8}\partial^4_x u \cdot dt.
\end{equation}

\medskip

\noindent\textbf{Step 4: Marginal density equation via Fourier analysis.}
The characteristic function of $Z_t$ is computed by iterated conditioning:
\begin{align}
\hat{p}(t,\xi) &= \E[e^{i\xi Z_t}] = \E\!\left[\E\!\left[e^{i\xi B^{(1)}(\tau_t)} \mid B^{(2)}\right]\right] = \E\!\left[e^{-\xi^2 \tau_t/2}\right] \notag\\
&= \E\!\left[e^{-\xi^2 |B^{(2)}_t|/2}\right]. \label{eq:char-fn}
\end{align}
For $|B^{(2)}_t|$ with the half-normal distribution, the Laplace transform is:
\begin{equation}
\E\!\left[e^{-\lambda|B^{(2)}_t|}\right] = e^{\lambda^2 t/2}\,\mathrm{erfc}\!\left(\lambda\sqrt{t/2}\right), \label{eq:half-normal-laplace}
\end{equation}
where $\mathrm{erfc}$ is the complementary error function.  Setting $\lambda = \xi^2/2$ gives
$\hat{p}(t,\xi) = F(t)$ where $F(t) = e^{ct}\,\mathrm{erfc}(\sqrt{ct})$ with $c = \xi^4/8$.

We now compute $F'(t)$ explicitly.  By the product and chain rules, using $\frac{d}{dt}\mathrm{erfc}(\sqrt{ct}) = -\frac{1}{\sqrt{\pi}}\,e^{-ct}\,\frac{\sqrt{c}}{2\sqrt{t}}$:
\begin{align}
F'(t) &= c\,e^{ct}\,\mathrm{erfc}(\sqrt{ct}) + e^{ct}\!\left(-\frac{e^{-ct}\sqrt{c}}{\sqrt{\pi t}}\right) \notag\\
&= c\,F(t) - \sqrt{\frac{c}{\pi t}}. \label{eq:Fprime}
\end{align}
Substituting $c = \xi^4/8$:
\begin{equation}\label{eq:Fourier-ODE}
\partial_t \hat{p}(t,\xi) = \frac{\xi^4}{8}\,\hat{p}(t,\xi) - \frac{\xi^2}{\sqrt{8\pi t}}.
\end{equation}

The remainder term $R(t,\xi) = -\xi^2/\sqrt{8\pi t}$ does not vanish.  In our Fourier convention $\hat{p} = \int e^{i\xi x}p\,dx$, the transform of $\partial^4_x p$ is $(i\xi)^4\hat{p} = \xi^4\hat{p}$, and the transform of $\partial^2_x\delta_0(x)$ is $(i\xi)^2 = -\xi^2$.  Therefore \eqref{eq:Fourier-ODE} inverts to the distributional PDE
\begin{equation}
\partial_t p = \frac{1}{8}\partial^4_x p + \frac{1}{\sqrt{8\pi t}}\,\partial^2_x\delta_0(x). \label{eq:biharmonic-full}
\end{equation}
For $x \neq 0$ the source term vanishes, giving the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial^4_x p$, consistent with Allouba--Zheng \cite{AZ}.

statement:
\label{rem:local-time}
The local time $L^0_t(B^{(2)})$ in Tanaka's formula contributes the second-order source term $\frac{1}{\sqrt{8\pi t}}\,\partial^2_x\delta_0(x)$ in \eqref{eq:biharmonic-full}.  The mechanism is as follows: the local-time drift in \eqref{eq:comp-ito-expanded} produces a term $-\frac{1}{2}\partial^2_x u \cdot dL^0_t$, which, when averaged over the law of $B^{(2)}$, gives the contribution $-\frac{\xi^2}{\sqrt{8\pi t}}$ in Fourier space (equation~\eqref{eq:Fourier-ODE}).  Inverting, this is precisely $\frac{1}{\sqrt{8\pi t}}\,\partial^2_x\delta_0(x)$.  The source is concentrated at $x = 0$ because the local time increases only when $B^{(2)}_t = 0$, which corresponds to the outer Brownian motion $B^{(1)}$ being evaluated at the origin.

From the operator framework perspective, the source term arises because the intrinsic bracket $\|D^{(1)}_\cdot Z_t\|^2_{\mathcal{H}^{(1)}} = |B^{(2)}_t|$ is not absolutely continuous: it has a singular component from the local time (Theorem~\ref{thm:iterBM-bracket}).  The operator It\^o formula tracks both the absolutely continuous part (which produces the $\frac{1}{8}\partial^4_x$ generator) and the singular part (which produces the delta source).  This demonstrates that the operator framework captures boundary phenomena that a purely formal calculation would miss.

\label{def:Poisson-deriv}
For a functional $F = f(N_T)$ where $f : \mathbb{Z}_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T(\omega) + 1) - f(N_T(\omega)),
\end{equation}
where $\delta_t$ denotes the Dirac mass at time $t$ (adding a jump at time $t$), not to be confused with the divergence operator $\delta_N$.

\label{prop:Poisson-adj}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy:
\begin{equation}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u\rangle_{\mathcal{H}_N}] = \lambda\int_0^T \E[(D_N F)_t \cdot u_t]\,dt.
\end{equation}

\label{thm:Poisson-gen}
The generator for the Poisson process acting on functions $f : \mathbb{Z}_{\geq 0} \to \R$ is
\begin{equation}
Lf(n) = \lambda(f(n+1) - f(n)), \qquad n \in \mathbb{Z}_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ satisfies $\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0$.

\label{thm:cPoisson-gen}
The generator acting on $f \in C^2(\R)$ is the nonlocal operator:
\begin{equation}
Lf(x) = \lambda\int_{\R}(f(x+z) - f(x))\,\nu_J(dz).
\end{equation}

\label{thm:Levy-gen}
The generator acting on $f \in C^2(\R)$ is:
\begin{equation}
Lf(x) = \int_{\R}\!\Big(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\Big)\,\nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with $\alpha \in (0,2)$, the L\'evy measure is $\nu(dz) = c_\alpha|z|^{-1-\alpha}\,dz$ where $c_\alpha > 0$. The generator is the fractional Laplacian:
\begin{equation}
Lf(x) = -(-\Delta)^{\alpha/2}f(x) = c_\alpha\,\PV\!\int_{\R}\frac{f(x+z) - f(x)}{|z|^{1+\alpha}}\,dz.
\end{equation}

\label{rem:jumps-not-memory}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'evy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'evy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-deriv}
For a L\'evy process with Gaussian and jump components, the operator derivative decomposes as $D_X F = D_B F + D_J F$, where $D_B$ is the Malliavin derivative and $D_J$ is the difference operator. The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}.
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt\otimes\nu)$ from jump processes yield nonlocal integral operators, with power-law L\'evy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator is nonlocal:
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For $\alpha$-stable processes, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. The operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a process $Y$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(t) g'(t)\,dt.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel and $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$.

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(t) g''(t) \, dt$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For $u(s,x) = \E[f(B_T^{(1)}) \mid B_s^{(1)} = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T] \times \{1\}, \lambda \, dt) \cong L^2([0,T])
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$, the operator derivative is the difference operator:
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation:
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)).
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator is the nonlocal operator
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator is
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz.
\end{equation}

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega).
\end{equation*}
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ (where $\R_+ = [0,\infty)$) be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega).
\end{equation*}
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2([0,T])}$---the $L^2([0,T])$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ (where $\R_+ = [0,\infty)$) be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element of the energy space):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega).
\end{equation*}
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For an $\HH$-valued process $u = (u_t)_{t \in [0,T]}$ with $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2([0,T])}$---the $L^2([0,T])$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ (where $\R_+ = [0,\infty)$) be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative of $F \in L^2(\Omega)$ (in the appropriate domain) decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$: for $F, G \in L^2(\Omega)$ in the appropriate domains,
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element of the energy space):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$ (the space of functions with one continuous derivative in $t$ and two continuous derivatives in $x$), and let $\phi \in C^2(\R)$ (twice continuously differentiable). Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt,
\end{equation}
where $\phi''$ denotes the second derivative of $\phi$.
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ (a process with stationary independent increments, $X_0 = 0$, and càdlàg paths) with L\'{e}vy measure $\nu$ (a $\sigma$-finite measure on $\R \setminus \{0\}$ characterizing the jump intensity) satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega),
\end{equation*}
where $\delta_t$ denotes the Dirac mass at time $t$, so $\omega + z\delta_t$ represents the path $\omega$ with an additional jump of size $z$ at time $t$.
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz),
\end{equation}
where $\mathbf{1}_{|z| \leq 1}$ is the indicator function (equal to $1$ if $|z| \leq 1$ and $0$ otherwise).
\item For symmetric $\alpha$-stable processes (Lévy processes with $\nu(dz) = c_\alpha |z|^{-1-\alpha} dz$ for a constant $c_\alpha > 0$) with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ (meaning there exists a constant $C > 0$ such that $\|h\|_{L^2(\Omega)} \leq C\|h\|_{\HH}$ for all $h \in \HH$) such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For an $\HH$-valued process $u = (u_t)_{t \in [0,T]}$ with $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2([0,T])}$---the $L^2([0,T])$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel (an integral operator depending on $H$), $I_{0+}^{\beta}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$ defined by $(I_{0+}^{\beta} f)(t) = \frac{1}{\Gamma(\beta)} \int_0^t (t-s)^{\beta - 1} f(s) \, ds$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ (functions with two weak derivatives in $L^2$, vanishing at the boundary along with their first derivatives) with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\HH^{(1)}} = \|h'\|_{L^2(\R_+)}$, where $\R_+ = [0,\infty)$), and let $\HH^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\HH^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at level zero (a non-decreasing process that increases only when $B^{(2)}$ is at zero, formally defined as the density of the occupation measure). The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$ (with $\Z_{\geq 0} = \{0, 1, 2, \ldots\}$ denoting the non-negative integers), the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value (the symmetric limit $\lim_{\epsilon \to 0^+} \int_{|z| > \epsilon}$).

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative of $F \in L^2(\Omega)$ (in the appropriate domain) decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$: for $F, G \in L^2(\Omega)$ in the appropriate domains,
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element of the energy space):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$ (the space of functions with one continuous derivative in $t$ and two continuous derivatives in $x$), and let $\phi \in C^2(\R)$ (twice continuously differentiable). Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ (a process with stationary independent increments, $X_0 = 0$, and càdlàg paths) with L\'{e}vy measure $\nu$ (a $\sigma$-finite measure on $\R \setminus \{0\}$ characterizing the jump intensity) satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega),
\end{equation*}
where $\delta_t$ denotes the Dirac mass at time $t$, so $\omega + z\delta_t$ represents the path $\omega$ with an additional jump of size $z$ at time $t$.
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes (Lévy processes with $\nu(dz) = c_\alpha |z|^{-1-\alpha} dz$ for a constant $c_\alpha > 0$) with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ (meaning there exists a constant $C > 0$ such that $\|h\|_{L^2(\Omega)} \leq C\|h\|_{\HH}$ for all $h \in \HH$) such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For an $\HH$-valued process $u = (u_t)_{t \in [0,T]}$ with $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2([0,T])}$---the $L^2([0,T])$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel (an integral operator depending on $H$), $I_{0+}^{\beta}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$ defined by $(I_{0+}^{\beta} f)(t) = \frac{1}{\Gamma(\beta)} \int_0^t (t-s)^{\beta - 1} f(s) \, ds$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ (functions with two weak derivatives in $L^2$, vanishing at the boundary along with their first derivatives) with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\HH^{(1)}} = \|h'\|_{L^2(\R_+)}$, where $\R_+ = [0,\infty)$), and let $\HH^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\HH^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at level zero (a non-decreasing process that increases only when $B^{(2)}$ is at zero, formally defined as the density of the occupation measure). The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative of $F \in L^2(\Omega)$ (in the appropriate domain) decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$: for $F, G \in L^2(\Omega)$ in the appropriate domains,
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element of the energy space):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$ (the space of functions with one continuous derivative in $t$ and two continuous derivatives in $x$), and let $\phi \in C^2(\R)$ (twice continuously differentiable). Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ (a process with stationary independent increments, $X_0 = 0$, and càdlàg paths) with L\'{e}vy measure $\nu$ (a $\sigma$-finite measure on $\R \setminus \{0\}$ characterizing the jump intensity) satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega),
\end{equation*}
where $\delta_t$ denotes the Dirac mass at time $t$, so $\omega + z\delta_t$ represents the path $\omega$ with an additional jump of size $z$ at time $t$.
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes (Lévy processes with $\nu(dz) = c_\alpha |z|^{-1-\alpha} dz$ for a constant $c_\alpha > 0$) with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ (meaning there exists a constant $C > 0$ such that $\|h\|_{L^2(\Omega)} \leq C\|h\|_{\HH}$ for all $h \in \HH$) such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For an $\HH$-valued process $u = (u_t)_{t \in [0,T]}$ with $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) has differential
\begin{equation}\label{eq:intrinsic-bracket}
d\langle Y \rangle_t^{(D,\Pi)} = \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
Equivalently, $\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \frac{d}{ds}\|\Pi D_X Y_s\|_{\HH}^2 \, ds$. For Gaussian processes where $D_X X_t = k_t$ (the evaluation representer), this becomes $d\langle X \rangle_t^{(D,\Pi)} = \frac{d}{dt}R(t,t) \, dt$ where $R$ is the covariance function.

When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2([0,T])}$---the $L^2([0,T])$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel (an integral operator depending on $H$), $I_{0+}^{\beta}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$ defined by $(I_{0+}^{\beta} f)(t) = \frac{1}{\Gamma(\beta)} \int_0^t (t-s)^{\beta - 1} f(s) \, ds$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ (functions with two weak derivatives in $L^2$, vanishing at the boundary along with their first derivatives) with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\HH^{(1)}} = \|h'\|_{L^2(\R_+)}$, where $\R_+ = [0,\infty)$), and let $\HH^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\HH^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at level zero (a non-decreasing process that increases only when $B^{(2)}$ is at zero, formally defined as the density of the occupation measure). The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative of $F \in L^2(\Omega)$ (in the appropriate domain) decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$: for $F, G \in L^2(\Omega)$ in the appropriate domains,
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element of the energy space):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$ (the space of functions with one continuous derivative in $t$ and two continuous derivatives in $x$), and let $\phi \in C^2(\R)$ (twice continuously differentiable). Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \, d\langle Y \rangle_t^{(D,\Pi)} = \frac{1}{2}\phi''(Y_t) \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ (a process with stationary independent increments, $X_0 = 0$, and càdlàg paths) with L\'{e}vy measure $\nu$ (a $\sigma$-finite measure on $\R \setminus \{0\}$ characterizing the jump intensity) satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega),
\end{equation*}
where $\delta_t$ denotes the Dirac mass at time $t$, so $\omega + z\delta_t$ represents the path $\omega$ with an additional jump of size $z$ at time $t$.
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes (Lévy processes with $\nu(dz) = c_\alpha |z|^{-1-\alpha} dz$ for a constant $c_\alpha > 0$) with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ (meaning there exists a constant $C > 0$ such that $\|h\|_{L^2(\Omega)} \leq C\|h\|_{\HH}$ for all $h \in \HH$) such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For an $\HH$-valued process $u = (u_t)_{t \in [0,T]}$ with $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) has differential
\begin{equation}\label{eq:intrinsic-bracket}
d\langle Y \rangle_t^{(D,\Pi)} = \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
Equivalently, $\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \frac{d}{ds}\|\Pi D_X Y_s\|_{\HH}^2 \, ds$. For Gaussian processes where $D_X X_t = k_t$ (the evaluation representer), this becomes $d\langle X \rangle_t^{(D,\Pi)} = \frac{d}{dt}R(t,t) \, dt$ where $R$ is the covariance function.

When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2([0,T])}$---the $L^2([0,T])$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel (an integral operator depending on $H$), $I_{0+}^{\beta}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$ defined by $(I_{0+}^{\beta} f)(t) = \frac{1}{\Gamma(\beta)} \int_0^t (t-s)^{\beta - 1} f(s) \, ds$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ (functions with two weak derivatives in $L^2$, vanishing at the boundary along with their first derivatives) with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\HH^{(1)}} = \|h'\|_{L^2(\R_+)}$, where $\R_+ = [0,\infty)$), and let $\HH^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\HH^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at level zero (a non-decreasing process that increases only when $B^{(2)}$ is at zero, formally defined as the density of the occupation measure). The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative of $F \in L^2(\Omega)$ (in the appropriate domain) decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$: for $F, G \in L^2(\Omega)$ in the appropriate domains,
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element of the energy space):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$ (the space of functions with one continuous derivative in $t$ and two continuous derivatives in $x$), and let $\phi \in C^2(\R)$ (twice continuously differentiable). Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \, d\langle Y \rangle_t^{(D,\Pi)} = \frac{1}{2}\phi''(Y_t) \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ (a process with stationary independent increments, $X_0 = 0$, and càdlàg paths) with L\'{e}vy measure $\nu$ (a $\sigma$-finite measure on $\R \setminus \{0\}$ characterizing the jump intensity) satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega),
\end{equation*}
where $\delta_t$ denotes the Dirac mass at time $t$, so $\omega + z\delta_t$ represents the path $\omega$ with an additional jump of size $z$ at time $t$.
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes (Lévy processes with $\nu(dz) = c_\alpha |z|^{-1-\alpha} dz$ for a constant $c_\alpha > 0$) with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ (meaning there exists a constant $C > 0$ such that $\|h\|_{L^2(\Omega)} \leq C\|h\|_{\HH}$ for all $h \in \HH$) such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For an $\HH$-valued process $u = (u_t)_{t \in [0,T]}$ with $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$ such that $t \mapsto \|\Pi D_X Y_t\|_{\HH}^2$ is absolutely continuous on $[0,T]$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) has differential
\begin{equation}\label{eq:intrinsic-bracket}
d\langle Y \rangle_t^{(D,\Pi)} = \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
Equivalently, $\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \frac{d}{ds}\|\Pi D_X Y_s\|_{\HH}^2 \, ds$. For Gaussian processes where $D_X X_t = k_t$ (the evaluation representer), this becomes $d\langle X \rangle_t^{(D,\Pi)} = \frac{d}{dt}R(t,t) \, dt$ where $R$ is the covariance function.

When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2([0,T])}$---the $L^2([0,T])$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel (an integral operator depending on $H$), $I_{0+}^{\beta}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$ defined by $(I_{0+}^{\beta} f)(t) = \frac{1}{\Gamma(\beta)} \int_0^t (t-s)^{\beta - 1} f(s) \, ds$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ (functions with two weak derivatives in $L^2$, vanishing at the boundary along with their first derivatives) with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\HH^{(1)}} = \|h'\|_{L^2(\R_+)}$, where $\R_+ = [0,\infty)$), and let $\HH^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\HH^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at level zero (a non-decreasing process that increases only when $B^{(2)}$ is at zero, formally defined as the density of the occupation measure). The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative of $F \in L^2(\Omega)$ (in the appropriate domain) decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$: for $F, G \in L^2(\Omega)$ in the appropriate domains,
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element of the energy space):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$ (the space of functions with one continuous derivative in $t$ and two continuous derivatives in $x$), and let $\phi \in C^2(\R)$ (twice continuously differentiable). Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \, d\langle Y \rangle_t^{(D,\Pi)} = \frac{1}{2}\phi''(Y_t) \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ (a process with stationary independent increments, $X_0 = 0$, and càdlàg paths) with L\'{e}vy measure $\nu$ (a $\sigma$-finite measure on $\R \setminus \{0\}$ characterizing the jump intensity) satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega),
\end{equation*}
where $\delta_t$ denotes the Dirac mass at time $t$, so $\omega + z\delta_t$ represents the path $\omega$ with an additional jump of size $z$ at time $t$.
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes (Lévy processes with $\nu(dz) = c_\alpha |z|^{-1-\alpha} dz$ for a constant $c_\alpha > 0$) with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ (meaning there exists a constant $C > 0$ such that $\|h\|_{L^2(\Omega)} \leq C\|h\|_{\HH}$ for all $h \in \HH$) such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For an $\HH$-valued process $u = (u_t)_{t \in [0,T]}$ with $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$ such that $t \mapsto \|\Pi D_X Y_t\|_{\HH}^2$ is absolutely continuous on $[0,T]$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) has differential
\begin{equation}\label{eq:intrinsic-bracket}
d\langle Y \rangle_t^{(D,\Pi)} = \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
Equivalently, $\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \frac{d}{ds}\|\Pi D_X Y_s\|_{\HH}^2 \, ds$. For Gaussian processes where $D_X X_t = k_t$ (the evaluation representer), this becomes $d\langle X \rangle_t^{(D,\Pi)} = \frac{d}{dt}R(t,t) \, dt$ where $R$ is the covariance function.

When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2([0,T])}$---the $L^2([0,T])$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel (an integral operator depending on $H$), $I_{0+}^{\beta}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$ defined by $(I_{0+}^{\beta} f)(t) = \frac{1}{\Gamma(\beta)} \int_0^t (t-s)^{\beta - 1} f(s) \, ds$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ (functions with two weak derivatives in $L^2$, vanishing at the boundary along with their first derivatives) with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\HH^{(1)}} = \|h'\|_{L^2(\R_+)}$, where $\R_+ = [0,\infty)$), and let $\HH^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\HH^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at level zero (a non-decreasing process that increases only when $B^{(2)}$ is at zero, formally defined as the density of the occupation measure). The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative of $F \in L^2(\Omega)$ (in the appropriate domain) decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$: for $F, G \in L^2(\Omega)$ in the appropriate domains,
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element of the energy space):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$ (the space of functions with one continuous derivative in $t$ and two continuous derivatives in $x$), and let $\phi \in C^2(\R)$ (twice continuously differentiable). Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \, d\langle Y \rangle_t^{(D,\Pi)} = \frac{1}{2}\phi''(Y_t) \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ (a process with stationary independent increments, $X_0 = 0$, and càdlàg paths) with L\'{e}vy measure $\nu$ (a $\sigma$-finite measure on $\R \setminus \{0\}$ characterizing the jump intensity) satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega),
\end{equation*}
where $\delta_t$ denotes the Dirac mass at time $t$, so $\omega + z\delta_t$ represents the path $\omega$ with an additional jump of size $z$ at time $t$.
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes (Lévy processes with $\nu(dz) = c_\alpha |z|^{-1-\alpha} dz$ for a constant $c_\alpha > 0$) with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ (meaning there exists a constant $C > 0$ such that $\|h\|_{L^2(\Omega)} \leq C\|h\|_{\HH}$ for all $h \in \HH$) such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For an $\HH$-valued process $u = (u_t)_{t \in [0,T]}$ with $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$ such that $t \mapsto \|\Pi D_X Y_t\|_{\HH}^2$ is absolutely continuous on $[0,T]$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) has differential
\begin{equation}\label{eq:intrinsic-bracket}
d\langle Y \rangle_t^{(D,\Pi)} = \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
Equivalently, $\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \frac{d}{ds}\|\Pi D_X Y_s\|_{\HH}^2 \, ds$. For Gaussian processes where $D_X X_t = k_t$ (the evaluation representer), this becomes $d\langle X \rangle_t^{(D,\Pi)} = \frac{d}{dt}R(t,t) \, dt$ where $R$ is the covariance function.

When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2([0,T])}$---the $L^2([0,T])$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel (an integral operator depending on $H$), $I_{0+}^{\beta}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$ defined by $(I_{0+}^{\beta} f)(t) = \frac{1}{\Gamma(\beta)} \int_0^t (t-s)^{\beta - 1} f(s) \, ds$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ (functions with two weak derivatives in $L^2$, vanishing at the boundary along with their first derivatives) with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\HH^{(1)}} = \|h'\|_{L^2(\R_+)}$, where $\R_+ = [0,\infty)$), and let $\HH^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\HH^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at level zero (a non-decreasing process that increases only when $B^{(2)}$ is at zero, formally defined as the density of the occupation measure). The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative of $F \in L^2(\Omega)$ (in the appropriate domain) decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$: for $F, G \in L^2(\Omega)$ in the appropriate domains,
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element of the energy space):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator is nonlocal:
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For $\alpha$-stable processes, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a process $Y$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(t) g'(t)\,dt.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel and $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$.

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(t) g''(t) \, dt$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For $u(s,x) = \E[f(B_T^{(1)}) \mid B_s^{(1)} = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T] \times \{1\}, \lambda \, dt) \cong L^2([0,T])
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$, the operator derivative is the difference operator:
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation:
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)).
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator is the nonlocal operator
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator is
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz.
\end{equation}

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$ (the space of functions with one continuous derivative in $t$ and two continuous derivatives in $x$), and let $\phi \in C^2(\R)$ (twice continuously differentiable). Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \, d\langle Y \rangle_t^{(D,\Pi)} = \frac{1}{2}\phi''(Y_t) \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ (a process with stationary independent increments, $X_0 = 0$, and càdlàg paths) with L\'{e}vy measure $\nu$ (a $\sigma$-finite measure on $\R \setminus \{0\}$ characterizing the jump intensity) satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega),
\end{equation*}
where $\delta_t$ denotes the Dirac mass at time $t$, so $\omega + z\delta_t$ represents the path $\omega$ with an additional jump of size $z$ at time $t$.
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes (Lévy processes with $\nu(dz) = c_\alpha |z|^{-1-\alpha} dz$ for a constant $c_\alpha > 0$) with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ (meaning there exists a constant $C > 0$ such that $\|h\|_{L^2(\Omega)} \leq C\|h\|_{\HH}$ for all $h \in \HH$) such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For an $\HH$-valued process $u = (u_t)_{t \in [0,T]}$ with $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$ such that $t \mapsto \|\Pi D_X Y_t\|_{\HH}^2$ is absolutely continuous on $[0,T]$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) has differential
\begin{equation}\label{eq:intrinsic-bracket}
d\langle Y \rangle_t^{(D,\Pi)} = \frac{d}{dt}\|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
Equivalently, $\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \frac{d}{ds}\|\Pi D_X Y_s\|_{\HH}^2 \, ds$. For Gaussian processes where $D_X X_t = k_t$ (the evaluation representer), this becomes $d\langle X \rangle_t^{(D,\Pi)} = \frac{d}{dt}R(t,t) \, dt$ where $R$ is the covariance function.

When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a real-valued process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2([0,T])}$---the $L^2([0,T])$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel (an integral operator depending on $H$), $I_{0+}^{\beta}$ denotes the Riemann--Liouville fractional integral of order $\beta > 0$ defined by $(I_{0+}^{\beta} f)(t) = \frac{1}{\Gamma(\beta)} \int_0^t (t-s)^{\beta - 1} f(s) \, ds$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ (functions with two weak derivatives in $L^2$, vanishing at the boundary along with their first derivatives) with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\HH^{(1)}} = \|h'\|_{L^2(\R_+)}$, where $\R_+ = [0,\infty)$), and let $\HH^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\HH^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth function $f: \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at level zero (a non-decreasing process that increases only when $B^{(2)}$ is at zero, formally defined as the density of the occupation measure). The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$, defined for $t \in (0,T]$ and $x \in \R$, satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For a smooth function $f: \R \to \R$ and the Feynman--Kac function $u(s,x) = \E[f(B_S^{(1)}) \mid B_s^{(1)} = x]$ for $B^{(1)}$ (where $S > 0$ is a terminal time for the outer process), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator acting on $f \in C^1(\R)$ is the nonlocal operator: for $x \in \R$,
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size: for $F = f(X_T)$ with $f \in C^1(\R)$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator acting on $f \in C^1(\R)$ is given by: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative of $F \in L^2(\Omega)$ (in the appropriate domain) decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$: for $F, G \in L^2(\Omega)$ in the appropriate domains,
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space (where $h$ denotes a generic element of the energy space):
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main}
Let $X = (X_t)_{t\in[0,T]}$ be a centered Volterra Gaussian process---i.e., $X_t = \int_0^t K(t,s)\,dW_s$ for a square-integrable Volterra kernel~$K$---on a complete probability space $(\Omega, \calF, \mathbb{P})$, with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\calH$ satisfying:
\begin{enumerate}[(A1),nosep]
\item \textit{Adjointness}: $\delta_X = D_X^*$ (the divergence is the Hilbert-space adjoint of the derivation);
\item \textit{Chain rule}: $D(\varphi(Y)) = \varphi'(Y)\,DY$ for smooth $\varphi$ and $Y \in \dom(D)$;
\item \textit{Orthogonal projection}: $\Pi = \Pi^*$ on $L^2(\Omega; \calH)$;
\item \textit{Energy regularity}: $\Gamma^X(t) := \|\Pi DX_t\|_{\calH}^2 \in \BV[0,T]$.
\end{enumerate}
Then the second-order correction in the operator It\^o formula is uniquely determined by the energy function: for $\varphi \in C^3_b(\R)$,
\begin{equation}\label{eq:second-order}
\varphi(X_t) = \varphi(0) + \delta\!\bigl(\varphi'(X)\,\Pi DX \cdot \mathbf{1}_{[0,t]}\bigr) + \tfrac{1}{2}\int_0^t \varphi''(X_s)\,d\Gamma^X(s),
\end{equation}
where the correction integral is Lebesgue--Stieltjes (since $\Gamma^X$ is deterministic for Gaussian processes) and the equality holds in $L^2(\Omega)$. For Markov processes, the intrinsic bracket determines the generator~$L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the marginal density equation.

\label{thm:iterBM}
Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Define iterated Brownian motion by $Z_t = B^{(1)}(|B^{(2)}_t|)$ for $t \in [0, T]$. Then:
\begin{enumerate}[(a),nosep]
\item The energy space is the tensor product $\calH_Z = \calH^{(1)} \otimes \calH^{(2)}$.
\item The operator derivative decomposes as $D_Z = D^{(1)} + D^{(2)}$ with the chain rule applied at each level.
\item The energy function $\Gamma^Z(t) = \|D^{(1)}_\cdot Z_t\|_{\calH^{(1)}}^2 = |B^{(2)}_t|$ is a random semimartingale (not a deterministic BV function), with Tanaka decomposition $d\Gamma^Z = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)})$ and quadratic variation $[\Gamma^Z]_t = t$, $\mathbb{P}$-a.s.
\item The marginal density $p(t, x)$ satisfies, in the distributional sense,
\begin{equation}\label{eq:biharmonic}
\partial_t p = \tfrac{1}{8}\partial_x^4 p + \tfrac{1}{\sqrt{8\pi t}}\,\partial_x^2\,\delta_0(x).
\end{equation}
Away from the origin ($x \neq 0$), the source term vanishes and $p$ satisfies the pure
biharmonic equation $\partial_t p = \frac{1}{8}\partial_x^4 p$. This recovers the Allouba--Zheng result~\cite{AZ} and identifies the source term as the contribution of the local time $L^0_t(B^{(2)})$ in the operator framework.
\end{enumerate}

\label{thm:Levy}
Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space supporting a L\'evy process $(X_t)_{t\in[0,T]}$ with L\'evy measure $\nu$ satisfying $\int_\R (1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\calF_t)_{t\geq 0}$ be its natural filtration. Then:
\begin{enumerate}[(a),nosep]
\item The energy space for jumps is $\calH_J = L^2([0, T] \times \R, dt \otimes \nu)$. This is the space of integrands for the compensated Poisson integral, not a moment condition on $X_t$ itself. In particular, $X_t$ need not belong to $L^2(\Omega)$; the operator derivative acts on functionals $F = f(X_T)$ where $f$ belongs to a sufficiently regular class (e.g., $C^2_c(\R)$) ensuring $F \in L^2(\Omega)$.
\item The operator derivative is the difference operator: $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator acting on $f \in C^2(\R)$ is nonlocal:
\begin{equation}\label{eq:Levy-gen}
Lf(x) = \int_\R \bigl[f(x + z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\bigr]\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with $\alpha \in (0, 2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

Let $X$ be a stochastic process with energy space $\calH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \calH)$ is defined via Riesz representation:
\begin{equation}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u\rangle_{\calH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\calH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}
F - \E[F] = \delta_X(\Pi D_X F), \qquad \mathbb{P}\text{-a.s.}
\end{equation}

Throughout this paper, the notation $\int_0^t \varphi''(Y_s)\,d\Gamma^Y(s)$ denotes:
\begin{itemize}[nosep]
\item a \emph{Lebesgue--Stieltjes} integral when $\Gamma^Y$ is deterministic and of bounded variation (the Gaussian setting of Theorem~\ref{thm:ito}; Sections~\ref{sec:BM}--\ref{sec:fBM});
\item a \emph{semimartingale} (It\^o-type) integral when $\Gamma^Y$ is random (iterated Brownian motion, Section~\ref{sec:iterated-bracket}).
\end{itemize}
The two notions coincide when $\Gamma^Y$ is deterministic. The distinction is essential: the operator It\^o formula (Theorem~\ref{thm:ito}) is proved rigorously only in the Lebesgue--Stieltjes case; in the semimartingale case, the PDE results are established by independent classical methods.

\label{thm:ito}
Let $X$ be a centered Volterra Gaussian process---i.e., $X_t = \int_0^t K(t,s)\,dW_s$ for a square-integrable Volterra kernel~$K$---satisfying the Decreusefond--\"Ust\"unel conditions~\cite{DU} (measurability and integrability conditions on~$K$ ensuring the Malliavin calculus is well-defined; see \cite[Hypothesis~H]{DU}), with operator triple $(D,\delta,\Pi)$ satisfying the chain rule (Assumption~2.3 of~\cite{paper3}), the factorization $(\Id - \E) = \delta\Pi D$, orthogonality of $\Pi$, and energy regularity ($\Gamma^X(t) := \|\Pi DX_t\|_{\calH}^2 \in \BV[0,T]$). For $\varphi \in C^3_b(\R)$,
\begin{equation}\label{eq:ito-formula}
\varphi(X_t)
= \varphi(0) + \delta\!\bigl(\varphi'(X)\,\Pi DX \cdot \mathbf{1}_{[0,t]}\bigr)
+ \tfrac{1}{2}\int_0^t \varphi''(X_s)\,d\Gamma^X(s),
\end{equation}
where $\Gamma^X(s) = \|\Pi DX_s\|_{\calH}^2 = \E[X_s^2]$ is the deterministic energy function and the equality holds in $L^2(\Omega)$. When $\Gamma^X$ is absolutely continuous with density $\dot\Gamma^X$, the correction reduces to $\frac{1}{2}\int_0^t \varphi''(X_s)\,\dot\Gamma^X(s)\,ds$.

\label{prop:CM-BM}
The Cameron--Martin space of Brownian motion is
\[
\calH_{1/2} = \{h \in C([0, T]) : h(0) = 0,\, h \text{ absolutely continuous},\, h' \in L^2([0, T])\}
\]
with inner product $\langle h, g\rangle_{\calH_{1/2}} = \int_0^T h'(r)\,g'(r)\,dr$.

\label{prop:no-spatial-frac}
Let $X$ be any centered Gaussian process with continuous covariance $R(s,t) = \E[X_s X_t]$. Then the energy function $\Gamma^X(t) = R(t,t)$ is a deterministic, non-negative, continuous function, and the marginal density equation takes the form $\partial_t p = \frac{1}{2}\dot\Gamma^X(t)\,\partial_x^2 p$ (when $\Gamma^X$ is absolutely continuous). In particular:
\begin{enumerate}[(i),nosep]
\item The spatial operator is always the ordinary Laplacian~$\partial_x^2$;
\item Memory manifests exclusively as time-dependent scaling of~$\partial_x^2$;
\item No choice of covariance $R$ produces a spatial fractional operator $(-\Delta)^\beta$ with $\beta \neq 1$.
\end{enumerate}

following_proof:
For $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\!\left[\int_0^s B_u\,du \int_0^t B_v\,dv\right] = \int_0^s \int_0^t \min(u, v)\,du\,dv \\
&= \int_0^s \!\left(\int_0^u v\,dv + \int_u^t u\,dv\right)du = \int_0^s\!\left(\frac{u^2}{2} + u(t - u)\right)du \\
&= \int_0^s\!\left(ut - \frac{u^2}{2}\right)du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t - s)}{6}.
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\[
\calH_{\mathrm{IBM}} = \{h \in C^1([0, T]) : h(0) = h'(0) = 0,\, h'' \in L^2([0, T])\}
\]
with inner product $\langle h, g\rangle_{\calH_{\mathrm{IBM}}} = \int_0^T h''(r)\,g''(r)\,dr$.

Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Let $\calH^{(1)}$ be the Cameron--Martin space of $B^{(1)}$ (with norm $\|h\|_{\calH^{(1)}} = \|h'\|_{L^2(\R_+)}$), and let $\calH^{(2)}$ be the Cameron--Martin space of $B^{(2)}$ (with norm $\|h\|_{\calH^{(2)}} = \|h'\|_{L^2([0,T])}$). The energy space for iterated BM is
\begin{equation}
\calH_Z = \calH^{(1)} \otimes \calH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:DZ}
For a smooth function $f : \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B^{(2)}_T|))$, the operator derivative decomposes as $D_Z F = D^{(1)}F + D^{(2)}F$, where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$. Explicitly, by the chain rule (Tier~3):
\begin{align}
D^{(1)}_s F &= f'(Z_T) \cdot \mathbf{1}_{[0,|B^{(2)}_T|]}(s), \label{eq:D1} \\
D^{(2)}_s F &= f'(Z_T) \cdot \frac{\partial B^{(1)}}{\partial s}\bigg|_{s=|B^{(2)}_T|} \cdot \sgn(B^{(2)}_T) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:D2}
\end{align}

\label{thm:iterated-bracket}
The process $Z_t = B^{(1)}(|B^{(2)}_t|)$ has energy function
\begin{equation}\label{eq:iterated-bracket}
\Gamma^Z(t) := \|D^{(1)}_\cdot Z_t\|_{\calH^{(1)}}^2 = |B^{(2)}_t|,
\end{equation}
which is a \emph{random}, continuous semimartingale. By Tanaka's formula,
\begin{equation}\label{eq:iterated-Tanaka}
d\Gamma^Z(t) = d|B^{(2)}_t| = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}),
\end{equation}
where $L^0_t(B^{(2)})$ is the local time of $B^{(2)}$ at level zero.

\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B^{(2)}_t|)$, the marginal density $p(t, x)$ satisfies, in the distributional sense,
\begin{equation}
\partial_t p = \tfrac{1}{8}\partial_x^4 p + \tfrac{1}{\sqrt{8\pi t}}\,\partial_x^2\,\delta_0(x).
\end{equation}
For $x \neq 0$, the source term vanishes and the density satisfies the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial_x^4 p$.

following_proof:
The proof proceeds in four steps.

\medskip\noindent\textbf{Step 1: Conditional structure.} Define the random time-change $\tau_t = |B^{(2)}_t|$. Conditional on $B^{(2)}$ (equivalently, conditional on the entire path $(\tau_s)_{s\in[0,T]}$), the process $Z_t = B^{(1)}(\tau_t)$ is a time-changed Brownian motion. By the classical Feynman--Kac theorem applied to $B^{(1)}$, for any $f \in C^2_b(\R)$,
\begin{equation}
\E[f(Z_T) \mid Z_t = x, B^{(2)}] = u(\tau_t, x)
\end{equation}
where $u(s, x)$ solves the heat equation in the $s$-variable:
\begin{equation}\label{eq:heat-outer}
\partial_s u + \tfrac{1}{2}\partial_x^2 u = 0, \qquad u(\tau_T, x) = f(x).
\end{equation}

\medskip\noindent\textbf{Step 2: Time-change dynamics via Tanaka's formula.} The random clock $\tau_t = |B^{(2)}_t|$ satisfies Tanaka's formula:
\[
d\tau_t = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}).
\]
The quadratic variation of $\tau$ is $d[\tau]_t = dt$, since $\sgn(B^{(2)}_t)^2 = 1$ for $B^{(2)}_t \neq 0$ (which holds a.e.\ in $t$, $\mathbb{P}$-a.s.).

\medskip\noindent\textbf{Step 3: It\^o formula for the composition.} We apply the classical It\^o formula to the composite function $v(t, x) := u(\tau_t, x)$. Since $u$ is smooth in both arguments and $\tau_t$ is a semimartingale, It\^o's formula gives:
\begin{equation}
dv = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial_s^2 u \cdot d[\tau]_t = \partial_s u \cdot d\tau_t + \tfrac{1}{2}\partial_s^2 u \cdot dt.
\end{equation}
Now substitute $\partial_s u = -\frac{1}{2}\partial_x^2 u$ from~\eqref{eq:heat-outer}. For the second-order term, differentiate~\eqref{eq:heat-outer} in $s$ to obtain $\partial_s^2 u = \frac{1}{4}\partial_x^4 u$. Therefore:
\begin{equation}
dv = -\tfrac{1}{2}\partial_x^2 u \cdot d\tau_t + \tfrac{1}{8}\partial_x^4 u \cdot dt.
\end{equation}

\medskip\noindent\textbf{Step 4: Marginal density equation via Fourier analysis.} The characteristic function of $Z_t$ is computed by iterated conditioning:
\begin{equation}
\hat p(t, \xi) = \E[e^{i\xi Z_t}] = \E\!\left[\E\!\left[e^{i\xi B^{(1)}(\tau_t)} \mid B^{(2)}\right]\right] = \E\!\left[e^{-\xi^2 \tau_t/2}\right] = \E\!\left[e^{-\xi^2 |B^{(2)}_t|/2}\right].
\end{equation}
For $|B^{(2)}_t|$ with the half-normal distribution, the Laplace transform is:
\[
\E\!\left[e^{-\lambda|B^{(2)}_t|}\right] = e^{\lambda^2 t/2}\,\erfc\!\left(\lambda\sqrt{t/2}\right),
\]
where $\erfc$ is the complementary error function. Setting $\lambda = \xi^2/2$ gives $\hat p(t, \xi) = F(t)$ where $F(t) = e^{ct}\,\erfc(\sqrt{ct})$ with $c = \xi^4/8$.

We now compute $F'(t)$ explicitly. By the product and chain rules, using $\frac{d}{dt}\erfc(\sqrt{ct}) = -\frac{2}{\sqrt{\pi}}\,e^{-ct}\,\frac{\sqrt{c}}{2\sqrt{t}} = -\frac{\sqrt{c}}{\sqrt{\pi t}}\,e^{-ct}$:
\begin{equation}
F'(t) = c\,e^{ct}\,\erfc(\sqrt{ct}) + e^{ct}\!\left(-\frac{e^{-ct}\sqrt{c}}{\sqrt{\pi t}}\right) = c\,F(t) - \sqrt{\frac{c}{\pi t}}.
\end{equation}
Substituting $c = \xi^4/8$:
\begin{equation}\label{eq:Fourier-ODE}
\partial_t \hat p(t, \xi) = \frac{\xi^4}{8}\hat p(t, \xi) - \frac{\xi^2}{\sqrt{8\pi t}}.
\end{equation}
The remainder term $R(t, \xi) = -\xi^2/\sqrt{8\pi t}$ does not vanish. In our Fourier convention $\hat p = \int e^{i\xi x} p\,dx$, the transform of $\partial_x^4 p$ is $(i\xi)^4 \hat p = \xi^4 \hat p$, and the transform of $\partial_x^2 \delta_0(x)$ is $(i\xi)^2 = -\xi^2$. Therefore~\eqref{eq:Fourier-ODE} inverts to the distributional PDE
\begin{equation}
\partial_t p = \tfrac{1}{8}\partial_x^4 p + \tfrac{1}{\sqrt{8\pi t}}\,\partial_x^2\,\delta_0(x).
\end{equation}
For $x \neq 0$ the source term vanishes, giving the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial_x^4 p$, consistent with Allouba--Zheng \cite{AZ}.

statement:
\label{def:Poisson-deriv}
For a functional $F = f(N_T)$ where $f : \mathbb{Z}_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0, T]$ and $\omega \in \Omega$,
\begin{equation}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T(\omega) + 1) - f(N_T(\omega)),
\end{equation}
where $\delta_t$ denotes the Dirac mass at time $t$ (adding a jump at time $t$), not to be confused with the divergence operator $\delta_N$.

\label{thm:Poisson-gen}
The generator for the Poisson process acting on functions $f : \mathbb{Z}_{\geq 0} \to \R$ is
\begin{equation}
Lf(n) = \lambda(f(n + 1) - f(n)), \quad n \in \mathbb{Z}_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t, n) = \E[f(N_T) \mid N_t = n]$ satisfies $\partial_t u + \lambda(u(\cdot, n + 1) - u(\cdot, n)) = 0$.

\label{thm:compound-gen}
The generator acting on $f \in C^2(\R)$ is the nonlocal operator:
\begin{equation}
Lf(x) = \lambda \int_\R (f(x + z) - f(x))\,\nu_J(dz).
\end{equation}

\label{thm:pure-jump-gen}
The generator acting on $f \in C^2(\R)$ is:
\begin{equation}
Lf(x) = \int_\R \bigl[f(x + z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\bigr]\,\nu(dz).
\end{equation}

For the symmetric $\alpha$-stable process with $\alpha \in (0, 2)$, the L\'evy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha}\,dz$ where $c_\alpha > 0$. The generator is the fractional Laplacian:
\begin{equation}
Lf(x) = -(-\Delta)^{\alpha/2}f(x) = c_\alpha\,\PV\!\int_\R \frac{f(x + z) - f(x)}{|z|^{1+\alpha}}\,dz.
\end{equation}

\label{thm:main}
Let $X = (X_t)_{t\in[0,T]}$ be a centered Volterra Gaussian process---i.e., $X_t = \int_0^t K(t,s)\,dW_s$ for a square-integrable Volterra kernel~$K$---on a complete probability space $(\Omega, \calF, \mathbb{P})$, with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\calH$ satisfying:
\begin{enumerate}[(A1),nosep]
\item \textit{Adjointness}: $\delta_X = D_X^*$ (the divergence is the Hilbert-space adjoint of the derivation);
\item \textit{Chain rule}: $D(\varphi(Y)) = \varphi'(Y)\,DY$ for smooth $\varphi$ and $Y \in \dom(D)$;
\item \textit{Orthogonal projection}: $\Pi = \Pi^*$ on $L^2(\Omega; \calH)$;
\item \textit{Energy regularity}: $\Gamma^X(t) := \|\Pi DX_t\|_{\calH}^2 \in \BV[0,T]$.
\end{enumerate}
Then the second-order correction in the operator It\^o formula is uniquely determined by the energy function: for $\varphi \in C^3_b(\R)$,
\begin{equation}\label{eq:second-order}
\varphi(X_t) = \varphi(0) + \delta\!\bigl(\varphi'(X)\,\Pi DX \cdot \mathbf{1}_{[0,t]}\bigr) + \tfrac{1}{2}\int_0^t \varphi''(X_s)\,d\Gamma^X(s),
\end{equation}
where the correction integral is Lebesgue--Stieltjes (since $\Gamma^X$ is deterministic for Gaussian processes) and the equality holds in $L^2(\Omega)$. For Markov processes, the intrinsic bracket determines the generator~$L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the marginal density equation.

\label{thm:iterBM}
Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Define iterated Brownian motion by $Z_t = B^{(1)}(|B^{(2)}_t|)$ for $t \in [0, T]$. Then:
\begin{enumerate}[(a),nosep]
\item The energy space is the tensor product $\calH_Z = \calH^{(1)} \otimes \calH^{(2)}$.
\item The operator derivative decomposes as $D_Z = D^{(1)} + D^{(2)}$ with the chain rule applied at each level.
\item The energy function $\Gamma^Z(t) = \|D^{(1)}_\cdot Z_t\|_{\calH^{(1)}}^2 = |B^{(2)}_t|$ is a random semimartingale (not a deterministic BV function), with Tanaka decomposition $d\Gamma^Z = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)})$ and quadratic variation $[\Gamma^Z]_t = t$, $\mathbb{P}$-a.s.
\item The marginal density $p(t, x)$ satisfies, in the distributional sense,
\begin{equation}\label{eq:biharmonic}
\partial_t p = \tfrac{1}{8}\partial_x^4 p + \tfrac{1}{\sqrt{8\pi t}}\,\partial_x^2\,\delta_0(x).
\end{equation}
Away from the origin ($x \neq 0$), the source term vanishes and $p$ satisfies the pure
biharmonic equation $\partial_t p = \frac{1}{8}\partial_x^4 p$. This recovers the Allouba--Zheng result~\cite{AZ} and identifies the source term as the contribution of the local time $L^0_t(B^{(2)})$ in the operator framework.
\end{enumerate}

\label{thm:Levy}
Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space supporting a L\'evy process $(X_t)_{t\in[0,T]}$ with L\'evy measure $\nu$ satisfying $\int_\R (1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\calF_t)_{t\geq 0}$ be its natural filtration. Then:
\begin{enumerate}[(a),nosep]
\item The energy space for jumps is $\calH_J = L^2([0, T] \times \R, dt \otimes \nu)$. This is the space of integrands for the compensated Poisson integral, not a moment condition on $X_t$ itself. In particular, $X_t$ need not belong to $L^2(\Omega)$; the operator derivative acts on functionals $F = f(X_T)$ where $f$ belongs to a sufficiently regular class (e.g., $C^2_c(\R)$) ensuring $F \in L^2(\Omega)$.
\item The operator derivative is the difference operator: $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator acting on $f \in C^2(\R)$ is nonlocal:
\begin{equation}\label{eq:Levy-gen}
Lf(x) = \int_\R \bigl[f(x + z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\bigr]\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with $\alpha \in (0, 2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

Let $X$ be a stochastic process with energy space $\calH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \calH)$ is defined via Riesz representation:
\begin{equation}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u\rangle_{\calH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\calH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}
F - \E[F] = \delta_X(\Pi D_X F), \qquad \mathbb{P}\text{-a.s.}
\end{equation}

Throughout this paper, the notation $\int_0^t \varphi''(Y_s)\,d\Gamma^Y(s)$ denotes:
\begin{itemize}[nosep]
\item a \emph{Lebesgue--Stieltjes} integral when $\Gamma^Y$ is deterministic and of bounded variation (the Gaussian setting of Theorem~\ref{thm:ito}; Sections~\ref{sec:BM}--\ref{sec:fBM});
\item a \emph{semimartingale} (It\^o-type) integral when $\Gamma^Y$ is random (iterated Brownian motion, Section~\ref{sec:iterated-bracket}).
\end{itemize}
The two notions coincide when $\Gamma^Y$ is deterministic. The distinction is essential: the operator It\^o formula (Theorem~\ref{thm:ito}) is proved rigorously only in the Lebesgue--Stieltjes case; in the semimartingale case, the PDE results are established by independent classical methods.

\label{thm:ito}
Let $X$ be a centered Volterra Gaussian process---i.e., $X_t = \int_0^t K(t,s)\,dW_s$ for a square-integrable Volterra kernel~$K$---satisfying the Decreusefond--\"Ust\"unel conditions~\cite{DU} (measurability and integrability conditions on~$K$ ensuring the Malliavin calculus is well-defined; see \cite[Hypothesis~H]{DU}), with operator triple $(D,\delta,\Pi)$ satisfying the chain rule (Assumption~2.3 of~\cite{paper3}), the factorization $(\Id - \E) = \delta\Pi D$, orthogonality of $\Pi$, and energy regularity ($\Gamma^X(t) := \|\Pi DX_t\|_{\calH}^2 \in \BV[0,T]$). For $\varphi \in C^3_b(\R)$,
\begin{equation}\label{eq:ito-formula}
\varphi(X_t)
= \varphi(0) + \delta\!\bigl(\varphi'(X)\,\Pi DX \cdot \mathbf{1}_{[0,t]}\bigr)
+ \tfrac{1}{2}\int_0^t \varphi''(X_s)\,d\Gamma^X(s),
\end{equation}
where $\Gamma^X(s) = \|\Pi DX_s\|_{\calH}^2 = \E[X_s^2]$ is the deterministic energy function and the equality holds in $L^2(\Omega)$. When $\Gamma^X$ is absolutely continuous with density $\dot\Gamma^X$, the correction reduces to $\frac{1}{2}\int_0^t \varphi''(X_s)\,\dot\Gamma^X(s)\,ds$.

\label{prop:CM-BM}
The Cameron--Martin space of Brownian motion is
\[
\calH_{1/2} = \{h \in C([0, T]) : h(0) = 0,\, h \text{ absolutely continuous},\, h' \in L^2([0, T])\}
\]
with inner product $\langle h, g\rangle_{\calH_{1/2}} = \int_0^T h'(r)\,g'(r)\,dr$.

\label{prop:no-spatial-frac}
Let $X$ be any centered Gaussian process with continuous covariance $R(s,t) = \E[X_s X_t]$. Then the energy function $\Gamma^X(t) = R(t,t)$ is a deterministic, non-negative, continuous function, and the marginal density equation takes the form $\partial_t p = \frac{1}{2}\dot\Gamma^X(t)\,\partial_x^2 p$ (when $\Gamma^X$ is absolutely continuous). In particular:
\begin{enumerate}[(i),nosep]
\item The spatial operator is always the ordinary Laplacian~$\partial_x^2$;
\item Memory manifests exclusively as time-dependent scaling of~$\partial_x^2$;
\item No choice of covariance $R$ produces a spatial fractional operator $(-\Delta)^\beta$ with $\beta \neq 1$.
\end{enumerate}

