\label{prop:DZ}
For a smooth function $f : \R \to \R$ and the functional $F = f(Z_T) = f(B^{(1)}(|B^{(2)}_T|))$, the operator derivative decomposes as $D_Z F = D^{(1)}F + D^{(2)}F$, where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$. Explicitly, by the chain rule (Tier~3):
\begin{align}
D^{(1)}_s F &= f'(Z_T) \cdot \mathbf{1}_{[0,|B^{(2)}_T|]}(s), \label{eq:D1} \\
D^{(2)}_s F &= f'(Z_T) \cdot \frac{\partial B^{(1)}}{\partial s}\bigg|_{s=|B^{(2)}_T|} \cdot \sgn(B^{(2)}_T) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:D2}
\end{align}

\label{thm:iterated-bracket}
The process $Z_t = B^{(1)}(|B^{(2)}_t|)$ has energy function
\begin{equation}\label{eq:iterated-bracket}
\Gamma^Z(t) := \|D^{(1)}_\cdot Z_t\|_{\calH^{(1)}}^2 = |B^{(2)}_t|,
\end{equation}
which is a \emph{random}, continuous semimartingale. By Tanaka's formula,
\begin{equation}\label{eq:iterated-Tanaka}
d\Gamma^Z(t) = d|B^{(2)}_t| = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)}),
\end{equation}
where $L^0_t(B^{(2)})$ is the local time of $B^{(2)}$ at level zero.

\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B^{(2)}_t|)$, the marginal density $p(t, x)$ satisfies, in the distributional sense,
\begin{equation}
\partial_t p = \tfrac{1}{8}\partial_x^4 p + \tfrac{1}{\sqrt{8\pi t}}\,\partial_x^2\,\delta_0(x).
\end{equation}
