\label{def:Poisson-deriv}
For a functional $F = f(N_T)$ where $f : \mathbb{Z}_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0, T]$ and $\omega \in \Omega$,
\begin{equation}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T(\omega) + 1) - f(N_T(\omega)),
\end{equation}
where $\delta_t$ denotes the Dirac mass at time $t$ (adding a jump at time $t$), not to be confused with the divergence operator $\delta_N$.

\label{thm:Poisson-gen}
The generator for the Poisson process acting on functions $f : \mathbb{Z}_{\geq 0} \to \R$ is
\begin{equation}
Lf(n) = \lambda(f(n + 1) - f(n)), \quad n \in \mathbb{Z}_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t, n) = \E[f(N_T) \mid N_t = n]$ satisfies $\partial_t u + \lambda(u(\cdot, n + 1) - u(\cdot, n)) = 0$.

\label{thm:compound-gen}
The generator acting on $f \in C^2(\R)$ is the nonlocal operator:
\begin{equation}
Lf(x) = \lambda \int_\R (f(x + z) - f(x))\,\nu_J(dz).
\end{equation}

\label{thm:pure-jump-gen}
The generator acting on $f \in C^2_c(\R)$ (or $f \in \calS(\R)$) is:
\begin{equation}
Lf(x) = \int_\R \bigl[f(x + z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\bigr]\,\nu(dz).
\end{equation}

For the symmetric $\alpha$-stable process with $\alpha \in (0, 2)$, the L\'evy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha}\,dz$ where $c_\alpha > 0$. The generator is the fractional Laplacian:
\begin{equation}
Lf(x) = -(-\Delta)^{\alpha/2}f(x) = c_\alpha\,\PV\!\int_\R \frac{f(x + z) - f(x)}{|z|^{1+\alpha}}\,dz.
\end{equation}

\label{thm:main}
Let $X = (X_t)_{t\in[0,T]}$ be a centered Volterra Gaussian process---i.e., $X_t = \int_0^t K(t,s)\,dW_s$ for a square-integrable Volterra kernel~$K$---on a complete probability space $(\Omega, \calF, \mathbb{P})$, with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\calH$ satisfying:
\begin{enumerate}[(A1),nosep]
\item \textit{Adjointness}: $\delta_X = D_X^*$ (the divergence is the Hilbert-space adjoint of the derivation);
\item \textit{Chain rule}: $D(\varphi(Y)) = \varphi'(Y)\,DY$ for smooth $\varphi$ and $Y \in \dom(D)$;
\item \textit{Orthogonal projection}: $\Pi = \Pi^*$ on $L^2(\Omega; \calH)$;
\item \textit{Energy regularity}: $\Gamma^X(t) := \|\Pi DX_t\|_{\calH}^2 \in \BV[0,T]$.
\end{enumerate}
Then the second-order correction in the operator It\^o formula is uniquely determined by the energy function: for $\varphi \in C^3_b(\R)$,
\begin{equation}\label{eq:second-order}
\varphi(X_t) = \varphi(0) + \delta\!\bigl(\varphi'(X)\,\Pi DX \cdot \mathbf{1}_{[0,t]}\bigr) + \tfrac{1}{2}\int_0^t \varphi''(X_s)\,d\Gamma^X(s),
\end{equation}
where the correction integral is Lebesgue--Stieltjes (since $\Gamma^X$ is deterministic for Gaussian processes) and the equality holds in $L^2(\Omega)$. For Markov processes, the intrinsic bracket determines the generator~$L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the marginal density equation.

\label{rem:novelty}
For Brownian motion ($H = 1/2$), the theorem reduces to the classical It\^o formula; for fBM, the marginal density PDE $\partial_t p = Ht^{2H-1}\partial_x^2 p$ follows from differentiating the Gaussian density $p(t,x) = (2\pi t^{2H})^{-1/2}\exp(-x^2/2t^{2H})$---a three-line calculation that does not require operator theory.  What the theorem adds is the identification of the coefficient as $\frac{1}{2}\dot\Gamma^X(t) = \frac{1}{2}\frac{d}{dt}\|k_t\|_{\calH}^2$: a single formula that produces the correct PDE coefficient for \emph{every} Gaussian Volterra process simultaneously, from the RKHS structure alone.  This is explanatory, not computational: it tells you \emph{why} the coefficient is what it is, not how to calculate it.

The genuine new theorems of the broader program---cylindrical reduction, the Leibniz obstruction, and the representability obstruction---are in~\cite{paper4, paper5}.

\label{thm:iterBM}
Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B^{(1)}_s)_{s\geq 0}$ and $B^{(2)} = (B^{(2)}_t)_{t\in[0,T]}$. Define iterated Brownian motion by $Z_t = B^{(1)}(|B^{(2)}_t|)$ for $t \in [0, T]$. Then:
\begin{enumerate}[(a),nosep]
\item The energy space is the tensor product $\calH_Z = \calH^{(1)} \otimes \calH^{(2)}$.
\item The operator derivative has a well-defined outer component $D^{(1)}$ (equation~\eqref{eq:D1}); the inner component $D^{(2)}$ encounters a pathwise regularity obstruction (Remark~\ref{rem:D2}).
\item The energy function $\Gamma^Z(t) = \|D^{(1)}_\cdot Z_t\|_{\calH^{(1)}}^2 = |B^{(2)}_t|$ is a random semimartingale (not a deterministic BV function), with Tanaka decomposition $d\Gamma^Z = \sgn(B^{(2)}_t)\,dB^{(2)}_t + dL^0_t(B^{(2)})$ and quadratic variation $[\Gamma^Z]_t = t$, $\mathbb{P}$-a.s.
\item The marginal density $p(t, x)$ satisfies, in the distributional sense,
\begin{equation}\label{eq:biharmonic}
\partial_t p = \tfrac{1}{8}\partial_x^4 p + \tfrac{1}{\sqrt{8\pi t}}\,\partial_x^2\,\delta_0(x).
\end{equation}
Away from the origin ($x \neq 0$), the source term vanishes and $p$ satisfies the pure
biharmonic equation $\partial_t p = \frac{1}{8}\partial_x^4 p$. This recovers the Allouba--Zheng result~\cite{AZ} and identifies the source term as the contribution of the local time $L^0_t(B^{(2)})$.
\end{enumerate}

\label{thm:Levy}
Let $(\Omega, \calF, \mathbb{P})$ be a complete probability space supporting a L\'evy process $(X_t)_{t\in[0,T]}$ with L\'evy measure $\nu$ satisfying $\int_\R (1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\calF_t)_{t\geq 0}$ be its natural filtration. Then:
\begin{enumerate}[(a),nosep]
\item The energy space for jumps is $\calH_J = L^2([0, T] \times \R, dt \otimes \nu)$. This is the space of integrands for the compensated Poisson integral, not a moment condition on $X_t$ itself. In particular, $X_t$ need not belong to $L^2(\Omega)$; the operator derivative acts on functionals $F = f(X_T)$ where $f$ belongs to a sufficiently regular class (e.g., $C^2_c(\R)$) ensuring $F \in L^2(\Omega)$.
\item The operator derivative is the difference operator: $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator acting on $f \in C^2_c(\R)$ is nonlocal:
\begin{equation}\label{eq:Levy-gen}
Lf(x) = \int_\R \bigl[f(x + z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\bigr]\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with $\alpha \in (0, 2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

Let $X$ be a stochastic process with energy space $\calH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \calH)$ is defined via Riesz representation:
\begin{equation}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u\rangle_{\calH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\calH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}
F - \E[F] = \delta_X(\Pi D_X F), \qquad \mathbb{P}\text{-a.s.}
\end{equation}

Throughout this paper, the notation $\int_0^t \varphi''(Y_s)\,d\Gamma^Y(s)$ denotes:
\begin{itemize}[nosep]
\item a \emph{Lebesgue--Stieltjes} integral when $\Gamma^Y$ is deterministic and of bounded variation (the Gaussian setting of Theorem~\ref{thm:ito}; Sections~\ref{sec:BM}--\ref{sec:fBM});
\item a \emph{semimartingale} (It\^o-type) integral when $\Gamma^Y$ is random (iterated Brownian motion, Section~\ref{sec:iterated-bracket}).
\end{itemize}
The two notions coincide when $\Gamma^Y$ is deterministic. The distinction is essential: the operator It\^o formula (Theorem~\ref{thm:ito}) is proved rigorously only in the Lebesgue--Stieltjes case; in the semimartingale case, the PDE results are established by independent classical methods.

\label{thm:ito}
Let $X$ be a centered Volterra Gaussian process---i.e., $X_t = \int_0^t K(t,s)\,dW_s$ for a square-integrable Volterra kernel~$K$---satisfying the Decreusefond--\"Ust\"unel conditions~\cite{DU} (measurability and integrability conditions on~$K$ ensuring the Malliavin calculus is well-defined; see \cite[Hypothesis~H]{DU}), with operator triple $(D,\delta,\Pi)$ satisfying the chain rule (Assumption~2.3 of~\cite{paper3}), the factorization $(\Id - \E) = \delta\Pi D$, orthogonality of $\Pi$, and energy regularity ($\Gamma^X(t) := \|\Pi DX_t\|_{\calH}^2 \in \BV[0,T]$). For $\varphi \in C^3_b(\R)$,
\begin{equation}\label{eq:ito-formula}
\varphi(X_t)
= \varphi(0) + \delta\!\bigl(\varphi'(X)\,\Pi DX \cdot \mathbf{1}_{[0,t]}\bigr)
+ \tfrac{1}{2}\int_0^t \varphi''(X_s)\,d\Gamma^X(s),
\end{equation}
where $\Gamma^X(s) = \|\Pi DX_s\|_{\calH}^2 = \E[X_s^2]$ is the deterministic energy function and the equality holds in $L^2(\Omega)$. When $\Gamma^X$ is absolutely continuous with density $\dot\Gamma^X$, the correction reduces to $\frac{1}{2}\int_0^t \varphi''(X_s)\,\dot\Gamma^X(s)\,ds$.

\label{prop:CM-BM}
The Cameron--Martin space of Brownian motion is
\[
\calH_{1/2} = \{h \in C([0, T]) : h(0) = 0,\, h \text{ absolutely continuous},\, h' \in L^2([0, T])\}
\]
with inner product $\langle h, g\rangle_{\calH_{1/2}} = \int_0^T h'(r)\,g'(r)\,dr$.

\label{prop:no-spatial-frac}
Let $X$ be any centered Gaussian process with continuous covariance $R(s,t) = \E[X_s X_t]$. Then the energy function $\Gamma^X(t) = R(t,t)$ is a deterministic, non-negative, continuous function, and the marginal density equation takes the form $\partial_t p = \frac{1}{2}\dot\Gamma^X(t)\,\partial_x^2 p$ (when $\Gamma^X$ is absolutely continuous). In particular:
\begin{enumerate}[(i),nosep]
\item The spatial operator is always the ordinary Laplacian~$\partial_x^2$;
\item Memory manifests exclusively as time-dependent scaling of~$\partial_x^2$;
\item No choice of Gaussian covariance $R$ produces a spatial fractional operator $(-\Delta)^\beta$ with $\beta \neq 1$.
\end{enumerate}

