Now substitute $\partial_s u = -\frac{1}{2}\partial_x^2 u$ from~\eqref{eq:heat-outer}. For the second-order term, differentiate~\eqref{eq:heat-outer} in $s$ to obtain $\partial_s^2 u = \frac{1}{4}\partial_x^4 u$. Therefore:
\begin{equation}
dv = -\tfrac{1}{2}\partial_x^2 u \cdot d\tau_t + \tfrac{1}{8}\partial_x^4 u \cdot dt.
\end{equation}

\medskip\noindent\textbf{Step 4: Marginal density equation via Fourier analysis.} The characteristic function of $Z_t$ is computed by iterated conditioning:
\begin{equation}
\hat p(t, \xi) = \E[e^{i\xi Z_t}] = \E\!\left[\E\!\left[e^{i\xi B^{(1)}(\tau_t)} \mid B^{(2)}\right]\right] = \E\!\left[e^{-\xi^2 \tau_t/2}\right] = \E\!\left[e^{-\xi^2 |B^{(2)}_t|/2}\right].
\end{equation}
For $|B^{(2)}_t|$ with the half-normal distribution, the Laplace transform is:
\[
\E\!\left[e^{-\lambda|B^{(2)}_t|}\right] = e^{\lambda^2 t/2}\,\erfc\!\left(\lambda\sqrt{t/2}\right),
\]
where $\erfc$ is the complementary error function. Setting $\lambda = \xi^2/2$ gives $\hat p(t, \xi) = F(t)$ where $F(t) = e^{ct}\,\erfc(\sqrt{ct})$ with $c = \xi^4/8$.

We now compute $F'(t)$ explicitly. By the product and chain rules, using $\frac{d}{dt}\erfc(\sqrt{ct}) = -\frac{2}{\sqrt{\pi}}\,e^{-ct}\,\frac{\sqrt{c}}{2\sqrt{t}} = -\frac{\sqrt{c}}{\sqrt{\pi t}}\,e^{-ct}$:
\begin{equation}
F'(t) = c\,e^{ct}\,\erfc(\sqrt{ct}) + e^{ct}\!\left(-\frac{e^{-ct}\sqrt{c}}{\sqrt{\pi t}}\right) = c\,F(t) - \sqrt{\frac{c}{\pi t}}.
\end{equation}
Substituting $c = \xi^4/8$:
\begin{equation}\label{eq:Fourier-ODE}
\partial_t \hat p(t, \xi) = \frac{\xi^4}{8}\hat p(t, \xi) - \frac{\xi^2}{\sqrt{8\pi t}}.
\end{equation}
The remainder term $R(t, \xi) = -\xi^2/\sqrt{8\pi t}$ does not vanish. In our Fourier convention $\hat p = \int e^{i\xi x} p\,dx$, the transform of $\partial_x^4 p$ is $(i\xi)^4 \hat p = \xi^4 \hat p$, and the transform of $\partial_x^2 \delta_0(x)$ is $(i\xi)^2 = -\xi^2$. Therefore~\eqref{eq:Fourier-ODE} inverts to the distributional PDE
\begin{equation}
\partial_t p = \tfrac{1}{8}\partial_x^4 p + \tfrac{1}{\sqrt{8\pi t}}\,\partial_x^2\,\delta_0(x).
\end{equation}
For $x \neq 0$ the source term vanishes, giving the pure biharmonic equation $\partial_t p = \frac{1}{8}\partial_x^4 p$, consistent with Allouba--Zheng \cite{AZ}.

statement:
\label{def:Poisson-deriv}
For a functional $F = f(N_T)$ where $f : \mathbb{Z}_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0, T]$ and $\omega \in \Omega$,
\begin{equation}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T(\omega) + 1) - f(N_T(\omega)),
\end{equation}
where $\delta_t$ denotes the Dirac mass at time $t$ (adding a jump at time $t$), not to be confused with the divergence operator $\delta_N$.

\label{thm:Poisson-gen}
The generator for the Poisson process acting on functions $f : \mathbb{Z}_{\geq 0} \to \R$ is
\begin{equation}
Lf(n) = \lambda(f(n + 1) - f(n)), \quad n \in \mathbb{Z}_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t, n) = \E[f(N_T) \mid N_t = n]$ satisfies $\partial_t u + \lambda(u(\cdot, n + 1) - u(\cdot, n)) = 0$.

\label{thm:compound-gen}
The generator acting on $f \in C^2(\R)$ is the nonlocal operator:
\begin{equation}
Lf(x) = \lambda \int_\R (f(x + z) - f(x))\,\nu_J(dz).
\end{equation}

\label{thm:pure-jump-gen}
The generator acting on $f \in C^2_c(\R)$ is:
\begin{equation}
Lf(x) = \int_\R \bigl[f(x + z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1}\bigr]\,\nu(dz).
\end{equation}

For the symmetric $\alpha$-stable process with $\alpha \in (0, 2)$, the L\'evy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha}\,dz$ where $c_\alpha > 0$. The generator is the fractional Laplacian:
\begin{equation}
Lf(x) = -(-\Delta)^{\alpha/2}f(x) = c_\alpha\,\PV\!\int_\R \frac{f(x + z) - f(x)}{|z|^{1+\alpha}}\,dz.
\end{equation}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator is nonlocal:
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For $\alpha$-stable processes, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a process $Y$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(t) g'(t)\,dt.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel and $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$.

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(t) g''(t) \, dt$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For $u(s,x) = \E[f(B_T^{(1)}) \mid B_s^{(1)} = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T] \times \{1\}, \lambda \, dt) \cong L^2([0,T])
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$, the operator derivative is the difference operator:
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation:
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator is the nonlocal operator
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator is
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz.
\end{equation}

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator is nonlocal:
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For $\alpha$-stable processes, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a process $Y$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(t) g'(t)\,dt.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(t) g''(t) \, dt$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For $u(s,x) = \E[f(B_T^{(1)}) \mid B_s^{(1)} = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T] \times \{1\}, \lambda \, dt) \cong L^2([0,T])
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$, the operator derivative is the difference operator:
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation:
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator is the nonlocal operator
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator is
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator is nonlocal:
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For $\alpha$-stable processes, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a process $Y$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(t) g'(t)\,dt.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(t) g''(t) \, dt$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For $u(s,x) = \E[f(B_T^{(1)}) \mid B_s^{(1)} = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T] \times \{1\}, \lambda \, dt) \cong L^2([0,T])
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$, the operator derivative is the difference operator:
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation:
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator is the nonlocal operator
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator is
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator is nonlocal:
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For $\alpha$-stable processes, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a process $Y$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(t) g'(t)\,dt.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(t) g''(t) \, dt$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For $u(s,x) = \E[f(B_T^{(1)}) \mid B_s^{(1)} = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T] \times \{1\}, \lambda \, dt) \cong L^2([0,T])
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$, the operator derivative is the difference operator:
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation:
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator is the nonlocal operator
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator is
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega).
\end{equation*}
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a process $Y$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(t) g'(t)\,dt.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(t) g''(t) \, dt$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For $u(s,x) = \E[f(B_T^{(1)}) \mid B_s^{(1)} = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T] \times \{1\}, \lambda \, dt) \cong L^2([0,T])
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation:
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator is the nonlocal operator
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator is
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega).
\end{equation*}
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a process $Y$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(t) g'(t)\,dt.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(t) g''(t) \, dt$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For $u(s,x) = \E[f(B_T^{(1)}) \mid B_s^{(1)} = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator is the nonlocal operator
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator is
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$, and let $\phi \in C^2(\R)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator: for $F \in L^2(\Omega)$ in the domain of $D_J$, $t \in [0,T]$, $z \in \R$, and $\omega \in \Omega$,
\begin{equation*}
(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega).
\end{equation*}
\item The generator acting on $f \in C^1(\R)$ is nonlocal: for $x \in \R$,
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For symmetric $\alpha$-stable processes with stability index $\alpha \in (0,2)$, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. For $F \in L^2(\Omega)$ in the domain of $D_X$, the operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \in [0,T]}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is defined for each $t \in [0,T]$ by
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra, with the convention that $\F_{0^-} = \F_0$.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F), \quad \PP\text{-a.s.}
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is defined for $t \in [0,T]$ by
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a process $Y$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}, \quad \PP\text{-a.s.}
\end{equation}
for all $t \in [0,T]$.

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{1/2}$,
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(r) g'(r)\,dr.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel, $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$, and $\dot{h}$ denotes an element of $L^2([0,T])$ (the ``derivative'' of $h$ in a generalized sense).

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$ for $i = 1, 2$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance function $R_I: [0,T] \times [0,T] \to \R$ given by
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s, t \in [0,T] \text{ with } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s, t \in [0,T]$ with $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product, for $h, g \in \HH_{\mathrm{IBM}}$, given by $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(r) g''(r) \, dr$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For $u(s,x) = \E[f(B_T^{(1)}) \mid B_s^{(1)} = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T], \lambda \, dt)
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process and $u = (u_s)_{s \in [0,T]}$ is a predictable process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$ where $f: \Z_{\geq 0} \to \R$, the operator derivative is the difference operator: for $t \in [0,T]$ and $\omega \in \Omega$,
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation: for $F \in L^2(\Omega)$ in the domain of $D_N$ and $u \in \HH_N$,
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)), \quad n \in \Z_{\geq 0}.
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ for $t \in [0,T]$ and $n \in \Z_{\geq 0}$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator is the nonlocal operator
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator is
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with stability index $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$ where $c_\alpha > 0$ is a normalizing constant depending on $\alpha$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz,
\end{equation}
where $\mathrm{P.V.}$ denotes the Cauchy principal value.

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM with Hurst parameter $H$ has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while symmetric $\alpha$-stable processes (with stability index $\alpha \in (0,2)$) have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

\label{thm:main-mechanism}
Let $(\Omega, \F, \PP)$ be a complete probability space, and let $X = (X_t)_{t \in [0,T]}$ be a stochastic process taking values in $\R^d$ with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\HH$. Assume the filtration $(\F_t)_{t \geq 0}$ is the natural filtration of $X$, augmented to satisfy the usual conditions. Let $Y_t = g(t, X_t)$ for $g \in C^{1,2}([0,T] \times \R^d)$. Assume the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) applies. Then the second-order term in the It\^{o} expansion of $\phi(Y_t)$ is
\begin{equation}\label{eq:second-order-term}
\frac{1}{2}\phi''(Y_t) \|\Pi D_X Y_t\|_{\HH}^2 \, dt.
\end{equation}
For Markov processes with time-homogeneous transitions, this determines the generator $L$ via Feynman--Kac; for non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:Levy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting a L\'{e}vy process $(X_t)_{t \in [0,T]}$ with L\'{e}vy measure $\nu$ satisfying $\int_{\R}(1 \wedge z^2)\,\nu(dz) < \infty$, and let $(\F_t)_{t \geq 0}$ be its natural filtration, augmented to satisfy the usual conditions. Then:
\begin{enumerate}[label=(\alph*)]
\item The energy space for jumps is $\HH_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item The operator derivative is the difference operator $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item The generator is nonlocal:
\begin{equation}\label{eq:Levy-generator}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr)\,\nu(dz).
\end{equation}
\item For $\alpha$-stable processes, this yields the fractional Laplacian $(-\Delta)^{\alpha/2}$---which arises from jump structure, not memory.
\end{enumerate}

\label{def:energy-space}
Let $(\Omega, \F, \PP)$ be a complete probability space and let $X$ be a stochastic process on this space. An \emph{energy space} for $X$ is a real Hilbert space $\HH$ continuously embedded in $L^2(\Omega)$ such that:
\begin{enumerate}[label=(\roman*)}
\item There exists a densely-defined closed operator $\delta_X: \dom(\delta_X) \subset \HH \to L^2(\Omega)$ (the divergence or stochastic integral).
\item The adjoint $D_X := \delta_X^*$ (the operator derivative) is also densely defined.
\item The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

\label{def:operator-derivative}
Let $X$ be a stochastic process with energy space $\HH$. The operator derivative $D_X F \in L^2(\Omega; \HH)$ is defined via Riesz representation:
\begin{equation}\label{eq:operator-derivative-def}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HH}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}

\label{def:predictable-projection}
Let $(\F_t)_{t \geq 0}$ be the natural filtration of $X$, augmented to satisfy the usual conditions. For $u \in L^2(\Omega; \HH)$, the predictable projection is
\begin{equation}\label{eq:predictable-projection-def}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-} = \sigma\bigl(\bigcup_{s < t} \F_s\bigr)$ is the left-limit $\sigma$-algebra.

\label{thm:factorization}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}\label{eq:factorization-thm}
F - \E[F] = \delta_X(\Pi D_X F).
\end{equation}

\label{def:intrinsic-bracket}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\HH$. For a process $Y = (Y_t)_{t \in [0,T]}$ in the domain of $D_X$, the \emph{intrinsic quadratic variation} (or intrinsic bracket) is
\begin{equation}\label{eq:intrinsic-bracket}
\langle Y \rangle_t^{(D,\Pi)} = \int_0^t \|\Pi D_X Y_s\|_{\HH}^2 \, ds.
\end{equation}
When the driving process $X$ is clear from context, we write simply $\langle Y \rangle_t$. When ambiguity is possible (e.g., for compositions), we write $\langle Y \rangle_t^{(D_X, \Pi_X)}$ to indicate the operator derivative and predictable projection associated with $X$.

\label{thm:operator-ito}
Let $X$ be a stochastic process satisfying Tiers 1 and 3 of \cite{Fontes2026d}. For $\phi \in C^2(\R)$ and a process $Y$ in the domain of $D_X$,
\begin{equation}\label{eq:operator-ito}
\phi(Y_t) - \phi(Y_0) = \int_0^t \phi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \phi''(Y_s)\,d\langle Y \rangle_s^{(D,\Pi)}.
\end{equation}

\label{prop:BM-RKHS}
The Cameron--Martin space of Brownian motion is
\begin{equation}\label{eq:BM-CM-space}
\HH_{1/2} = \bigl\{h \in C([0,T]) : h(0) = 0, \; h \text{ absolutely continuous}, \; h' \in L^2([0,T])\bigr\}
\end{equation}
with inner product
\begin{equation}\label{eq:BM-CM-inner-product}
\langle h, g \rangle_{\HH_{1/2}} = \int_0^T h'(t) g'(t)\,dt.
\end{equation}
The RKHS norm is $\|h\|_{\HH_{1/2}} = \|h'\|_{L^2}$---the $L^2$ norm of the first derivative.

\label{prop:fBM-RKHS}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}\label{eq:fBM-CM-space}
\HH_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I_{0+}^{H+1/2}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel and $I_{0+}^{\alpha}$ denotes the Riemann--Liouville fractional integral of order $\alpha$.

The inner product is
\begin{equation}\label{eq:fBM-CM-inner-product}
\langle h_1, h_2 \rangle_{\HH_H} = \langle \dot{h}_1, \dot{h}_2 \rangle_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$.

\label{prop:IBM-covariance}
Integrated Brownian motion has covariance
\begin{equation}\label{eq:IBM-covariance}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u \, du \int_0^t B_v \, dv\right] = \int_0^s \int_0^t \min(u,v) \, du \, dv \label{eq:IBM-cov-1} \\
&= \int_0^s \left[\int_0^u v \, dv + \int_u^t u \, dv\right] du = \int_0^s \left[\frac{u^2}{2} + u(t-u)\right] du \label{eq:IBM-cov-2} \\
&= \int_0^s \left[ut - \frac{u^2}{2}\right] du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \label{eq:IBM-cov-3}
\end{align}

statement:
\label{prop:IBM-RKHS}
The RKHS of integrated Brownian motion is
\begin{equation}\label{eq:IBM-RKHS}
\HH_{\mathrm{IBM}} = \bigl\{h \in C^1([0,T]) : h(0) = h'(0) = 0, \; h'' \in L^2([0,T])\bigr\}
\end{equation}
with inner product $\langle h, g \rangle_{\HH_{\mathrm{IBM}}} = \int_0^T h''(t) g''(t) \, dt$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}\label{eq:IBM-kernel-rep}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v) \, du \, dv = \int_0^{s \wedge t} (s-u)(t-u) \, du.
\end{equation}

This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H_0^2([0,T])$ with the stated norm.

statement:
\label{thm:AZ}
The density of iterated Brownian motion satisfies
\begin{equation}\label{eq:AZ-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

\label{def:iterated-BM-energy}
Let $(\Omega, \F, \PP)$ be a complete probability space supporting two independent standard Brownian motions $B^{(1)} = (B_s^{(1)})_{s \geq 0}$ and $B^{(2)} = (B_t^{(2)})_{t \in [0,T]}$. Let $\HH^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\HH^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}\label{eq:iterated-BM-energy}
\HH_Z = \HH^{(1)} \otimes \HH^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-BM-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B_T^{(2)}|))$, the operator derivative decomposes as:
\begin{equation}\label{eq:iterated-BM-derivative-decomp}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D_s^{(1)} F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B_T^{(2)}|]}(s), \label{eq:iterated-D1} \\
D_s^{(2)} F &= f'(Z_T) \cdot (D_{|B_T^{(2)}|}^{(1)} B^{(1)}) \cdot D_s^{(2)} |B_T^{(2)}| = f'(Z_T) \cdot \sgn(B_T^{(2)}) \cdot \mathbf{1}_{[0,T]}(s). \label{eq:iterated-D2}
\end{align}

\label{thm:quartic-variation}
The process $Z_t = B^{(1)}(|B_t^{(2)}|)$ has intrinsic bracket
\begin{equation}\label{eq:iterated-bracket}
d\langle Z \rangle_t^{(D,\Pi)} = |B_t^{(2)}| \, dt + \frac{1}{2}L_t^0(B^{(2)}) \, dt
\end{equation}
where $L_t^0(B^{(2)})$ is the local time of $B^{(2)}$ at zero. The appearance of local time follows from Tanaka's formula applied to $|B_t^{(2)}|$ \cite{RevuzYor1999}.

The quartic variation is
\begin{equation}\label{eq:quartic-var}
[Z]_t^{(4)} := \int_0^t \bigl(d\langle Z \rangle_s^{(D,\Pi)}\bigr)^2 = \int_0^t |B_s^{(2)}|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\emph{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}\label{eq:D1-contribution}
\|D_s^{(1)} Z_t\|_{\HH^{(1)}}^2 = \int_0^\infty \mathbf{1}_{[0, |B_t^{(2)}|]}(s)^2 \, ds = |B_t^{(2)}|.
\end{equation}

\emph{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B_t^{(2)}|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}\label{eq:Tanaka}
d|B_t^{(2)}| = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle_t^{(D,\Pi)}$ itself has quadratic variation of order $t^2$ (since $|B_t^{(2)}|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic}
For iterated Brownian motion $Z_t = B^{(1)}(|B_t^{(2)}|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}\label{eq:biharmonic}
\partial_t p = \frac{1}{8}\partial_x^4 p.
\end{equation}

following_proof:
We apply the operator It\^{o} formula (Theorem~\ref{thm:operator-ito}) at two levels.

\emph{Step 1: Inner expansion.} For the time-change $\tau_t = |B_t^{(2)}|$, Tanaka's formula gives:
\begin{equation}\label{eq:inner-expansion}
d\tau_t = \sgn(B_t^{(2)}) \, dB_t^{(2)} + dL_t^0, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\emph{Step 2: Outer expansion.} For $u(s,x) = \E[f(B_T^{(1)}) \mid B_s^{(1)} = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}\label{eq:outer-FK}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\emph{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}\label{eq:composition}
\partial_t v = \E\left[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}\right].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}\label{eq:higher-order}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\emph{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B_t^{(2)}|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}\label{eq:density-biharmonic}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
\label{def:Poisson-energy}
The energy space for the Poisson process is
\begin{equation}\label{eq:Poisson-energy}
\HH_N = L^2([0,T] \times \{1\}, \lambda \, dt) \cong L^2([0,T])
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process.

\label{def:Poisson-derivative}
For a functional $F = f(N_T)$, the operator derivative is the difference operator:
\begin{equation}\label{eq:Poisson-derivative}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:Poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation:
\begin{equation}\label{eq:Poisson-adjoint}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\HH_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:Poisson-generator}
The generator for the Poisson process acting on functions $f: \Z_{\geq 0} \to \R$ is
\begin{equation}\label{eq:Poisson-generator}
Lf(n) = \lambda(f(n+1) - f(n)).
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ satisfies
\begin{equation}\label{eq:Poisson-FK}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^{o} formula gives:
\begin{equation}\label{eq:Poisson-ito}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}

The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}\label{eq:Poisson-martingale}
\partial_t u + \lambda(u(t, n+1) - u(t,n)) = 0.
\end{equation}

statement:
\label{rmk:difference-vs-differential}
The Poisson generator $Lf(n) = \lambda(f(n+1) - f(n))$ is a \emph{difference operator}, not a differential operator. This reflects the discrete jumps of the process: the ``derivative'' $D_N$ is a finite difference, and the ``second-order term'' in the Feynman--Kac equation is a shift operator.

Compare with Brownian motion where $D_B$ is a true derivative and the generator is $\frac{1}{2}\partial_x^2$.

\label{thm:compound-Poisson}
The generator is the nonlocal operator
\begin{equation}\label{eq:compound-Poisson-generator}
Lf(x) = \lambda \int_{\R} (f(x+z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}\label{eq:compound-Poisson-derivative}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}

The energy space is $\HH_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^{o} formula for compound Poisson gives:
\begin{equation}\label{eq:compound-Poisson-ito}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:Levy-generator}
The generator is
\begin{equation}\label{eq:Levy-generator-formula}
Lf(x) = \int_{\R} \bigl(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z| \leq 1}\bigr) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with $\alpha \in (0,2)$, the L\'{e}vy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$. The generator is the fractional Laplacian:
\begin{equation}\label{eq:fractional-Laplacian}
Lf(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \mathrm{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz.
\end{equation}

\label{rmk:fractional-jumps}
The fractional Laplacian $(-\Delta)^{\alpha/2}$ arises from jump structure (the L\'{e}vy measure $|z|^{-1-\alpha}$), not from memory or long-range dependence.

This is the key distinction from fractional Brownian motion: fBM has memory and produces a time-dependent coefficient $Ht^{2H-1}$ in front of the ordinary Laplacian, while $\alpha$-stable processes have independent increments but produce a spatially nonlocal operator. The operator framework clarifies this: fBM has an RKHS with modified covariance, producing time-dependent coefficients; stable processes have a L\'{e}vy measure with power-law tails, producing a nonlocal spatial operator.

\label{thm:Levy-operator-derivative}
For a L\'{e}vy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}\label{eq:Levy-D-decomp}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \cdot D_B G + G \cdot D_B F, \label{eq:Leibniz-Gaussian} \\
D_J(FG)_{t,z} &= F \cdot D_J G_{t,z} + G \cdot D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}. \label{eq:Leibniz-jump}
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

following_proof:
The Gaussian component satisfies the standard Leibniz rule by Theorem~\ref{thm:BM}. For the jump component:
\begin{align}
D_J(FG)_{t,z} &= (FG)(\omega + z\delta_t) - (FG)(\omega) \label{eq:jump-Leibniz-1} \\
&= F(\omega + z\delta_t) G(\omega + z\delta_t) - F(\omega) G(\omega) \label{eq:jump-Leibniz-2} \\
&= (F + D_J F)(G + D_J G) - FG \label{eq:jump-Leibniz-3} \\
&= F \cdot D_J G + G \cdot D_J F + D_J F \cdot D_J G. \label{eq:jump-Leibniz-4}
\end{align}

statement:
\label{cor:classification}
The PDE type is determined by the energy space:
\begin{itemize}
\item Energy space norm involving first derivatives ($\|h'\|_{L^2}$) yields second-order differential operators.
\item Energy space norm involving second derivatives ($\|h''\|_{L^2}$) yields time-dependent coefficients.
\item Tensor product energy spaces from compositions yield higher-order operators.
\item Energy spaces of the form $L^2(dt \otimes \nu)$ from jump processes yield nonlocal integral operators, with power-law L\'{e}vy measures producing fractional Laplacians.
\end{itemize}

An \textbf{energy space} for a stochastic process $X$ is a Hilbert space $\Hi$ such that:
\begin{enumerate}
\item[(i)] There exists a densely-defined closed operator $\delta_X : \mathrm{dom}(\delta_X) \subset \Hi \to L^2(\Omega)$ (the \textbf{divergence} or stochastic integral).
\item[(ii)] The adjoint $D_X := \delta_X^*$ (the \textbf{operator derivative}) is also densely defined.
\item[(iii)] The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

The operator derivative $D_X F \in L^2(\Omega; \Hi)$ is defined via Riesz representation:
\begin{equation}\label{eq:riesz-def}
\E[F \cdot \delta_X(u)] = \E[\ip{D_X F}{u}_\Hi] \quad \text{for all } u \in \mathrm{dom}(\delta_X).
\end{equation}

For $u \in L^2(\Omega; \Hi)$,
\begin{equation}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-}$ is the left-limit of the filtration generated by $X$.

\label{thm:factorization}
For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}
F - \E[F] = \delta_X(\Pi D_X F).
\end{equation}

For a process $Y_t$ in the domain of $D$, define
\begin{equation}
\langle Y \rangle^{(D,\Pi)}_t = \int_0^t \|\Pi D_X Y_s\|^2_\Hi\,ds.
\end{equation}

\label{thm:ito}
For $\varphi \in C^2(\R)$ and suitable $Y_t$,
\begin{equation}
\varphi(Y_t) - \varphi(Y_0) = \int_0^t \varphi'(Y_s)\,dY_s + \frac{1}{2}\int_0^t \varphi''(Y_s)\,d\langle Y \rangle^{(D,\Pi)}_s.
\end{equation}

\label{prop:bm-rkhs}
The Cameron--Martin space of Brownian motion is
\begin{equation}
\Hi_{1/2} = \left\{h \in C([0,T]) : h(0) = 0,\, h \text{ absolutely continuous},\, h' \in L^2([0,T])\right\}
\end{equation}
with inner product
\begin{equation}
\ip{h}{g}_{\Hi_{1/2}} = \int_0^T h'(t) g'(t)\,dt.
\end{equation}

\label{prop:fbm-rkhs}
The Cameron--Martin space of fBM with Hurst parameter $H$ is
\begin{equation}
\Hi_H = \{K_H \dot{h} : \dot{h} \in L^2([0,T])\} = I^{H+1/2}_{0+}(L^2[0,T]),
\end{equation}
where $K_H$ is the fractional integral kernel and $I^\alpha_{0+}$ denotes the Riemann--Liouville fractional integral of order $\alpha$.

The inner product is
\begin{equation}
\ip{h_1}{h_2}_{\Hi_H} = \ip{\dot{h}_1}{\dot{h}_2}_{L^2}
\end{equation}
where $h_i = K_H \dot{h}_i$.

The direct density calculation proves Theorem~\ref{thm:main-fbm}(a) but does not explain it. The operator derivation shows that:
\begin{enumerate}
\item The coefficient $Ht^{2H-1}$ equals $\frac{1}{2}\frac{d}{dt}\|k^H_t\|^2_{\Hi_H}$.
\item This generalizes: for \emph{any} Gaussian process, the analogous coefficient is $\frac{1}{2}\frac{d}{dt}R(t,t)$.
\item The RKHS norm encodes the correlation structure, which manifests as time-dependence in the PDE.
\end{enumerate}

\label{prop:ibm-cov}
Integrated Brownian motion has covariance
\begin{equation}
R_I(s,t) = \E[I_s I_t] = \frac{s^2(3t-s)}{6} \quad \text{for } s \leq t.
\end{equation}
In particular, $\mathrm{Var}(I_t) = R_I(t,t) = \frac{t^3}{3}$.

following_proof:
For $s \leq t$:
\begin{align}
\E[I_s I_t] &= \E\left[\int_0^s B_u\,du \int_0^t B_v\,dv\right] = \int_0^s \int_0^t \min(u,v)\,du\,dv \\
&= \int_0^s \left(\int_0^u v\,dv + \int_u^t u\,dv\right) du = \int_0^s \left(\frac{u^2}{2} + u(t-u)\right) du \\
&= \int_0^s \left(ut - \frac{u^2}{2}\right) du = \frac{s^2 t}{2} - \frac{s^3}{6} = \frac{s^2(3t-s)}{6}. \qedhere
\end{align}

statement:
\label{prop:ibm-rkhs}
The RKHS of integrated Brownian motion is
\begin{equation}
\Hi_{\mathrm{IBM}} = \left\{h \in C^1([0,T]) : h(0) = h'(0) = 0,\, h'' \in L^2([0,T])\right\}
\end{equation}
with inner product $\langle h, g \rangle_{\Hi_{\mathrm{IBM}}} = \int_0^T h''(t) g''(t)\,dt$.

following_proof:
The covariance kernel $R_I(s,t) = \frac{s^2(3t-s)}{6}$ for $s \leq t$ can be written as
\begin{equation}
R_I(s,t) = \int_0^s \int_0^t (u \wedge v)\,du\,dv = \int_0^{s \wedge t} (s-u)(t-u)\,du.
\end{equation}
This is the kernel of the operator $(d^2/dt^2)^{-1}$ with boundary conditions $h(0) = h'(0) = 0$. The RKHS is therefore the Sobolev space $H^2_0([0,T])$ with the stated norm.

statement:
\label{thm:allouba-zheng}
The density of iterated Brownian motion satisfies
\begin{equation}
\partial_t p = c \, \partial_x^4 p
\end{equation}
for an explicit constant $c > 0$.

Let $\Hi^{(1)} = L^2(\R_+)$ be the energy space for the outer Brownian motion $B^{(1)}$, and let $\Hi^{(2)} = L^2([0,T])$ be the energy space for the inner Brownian motion $B^{(2)}$. The energy space for iterated BM is
\begin{equation}
\Hi_Z = \Hi^{(1)} \otimes \Hi^{(2)}
\end{equation}
with the product structure reflecting the independence of $B^{(1)}$ and $B^{(2)}$.

\label{prop:iterated-derivative}
For a smooth functional $F = f(Z_T) = f(B^{(1)}(|B^{(2)}_T|))$, the operator derivative decomposes as:
\begin{equation}
D_Z F = D^{(1)} F + D^{(2)} F
\end{equation}
where $D^{(1)}$ differentiates with respect to $B^{(1)}$ and $D^{(2)}$ differentiates with respect to $B^{(2)}$.

Explicitly, by the chain rule (Tier 3, which holds for each Brownian motion):
\begin{align}
D^{(1)}_s F &= f'(Z_T) \cdot \mathbf{1}_{[0, |B^{(2)}_T|]}(s), \\
D^{(2)}_s F &= f'(Z_T) \cdot (D^{(1)}_{|B^{(2)}_T|} B^{(1)}) \cdot D^{(2)}_s |B^{(2)}_T| = f'(Z_T) \cdot \mathrm{sgn}(B^{(2)}_T) \cdot \mathbf{1}_{[0,T]}(s).
\end{align}

\label{thm:quartic}
The process $Z_t = B^{(1)}(|B^{(2)}_t|)$ has intrinsic bracket
\begin{equation}
d\langle Z \rangle^{(D,\Pi)}_t = |B^{(2)}_t| \, dt + \frac{1}{2}L^0_t(B^{(2)}) \, dt
\end{equation}
where $L^0_t(B^{(2)})$ is the local time of $B^{(2)}$ at zero.

The quartic variation is
\begin{equation}
[Z]^{(4)}_t := \int_0^t (d\langle Z \rangle^{(D,\Pi)}_s)^2 = \int_0^t |B^{(2)}_s|^2 \, ds + \text{lower order terms}.
\end{equation}

following_proof:
The intrinsic bracket has two components:

\textbf{From $D^{(1)}$:} The outer Brownian motion contributes
\begin{equation}
\|D^{(1)}_s Z_t\|^2_{\Hi^{(1)}} = \int_0^\infty \mathbf{1}_{[0,|B^{(2)}_t|]}(s)^2 \, ds = |B^{(2)}_t|.
\end{equation}

\textbf{From $D^{(2)}$:} The inner Brownian motion contributes through the derivative of $|B^{(2)}_t|$, which involves the local time at zero via Tanaka's formula:
\begin{equation}
d|B^{(2)}_t| = \mathrm{sgn}(B^{(2)}_t) \, dB^{(2)}_t + dL^0_t.
\end{equation}

The total intrinsic bracket is the sum of these contributions.

The quartic variation arises because $\langle Z \rangle^{(D,\Pi)}_t$ itself has quadratic variation of order $t^2$ (since $|B^{(2)}_t|$ has order $\sqrt{t}$), giving fourth-order behavior overall.

statement:
\label{thm:biharmonic-derived}
For iterated Brownian motion $Z_t = B^{(1)}(|B^{(2)}_t|)$, the marginal density $p(t,x)$ satisfies
\begin{equation}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c = \frac{1}{8}$.

following_proof:
We apply the operator It\^o formula (Theorem~\ref{thm:ito}) at two levels.

\textbf{Step 1: Inner expansion.} For the time-change $\tau_t = |B^{(2)}_t|$, Tanaka's formula gives:
\begin{equation}
d\tau_t = \mathrm{sgn}(B^{(2)}_t) \, dB^{(2)}_t + dL^0_t, \qquad d\langle \tau \rangle_t = dt.
\end{equation}

\textbf{Step 2: Outer expansion.} For $u(s,x) = \E[f(B^{(1)}_T) \mid B^{(1)}_s = x]$ (the Feynman--Kac function for $B^{(1)}$), we have
\begin{equation}
\partial_s u + \frac{1}{2}\partial_x^2 u = 0.
\end{equation}

\textbf{Step 3: Composition.} The function $v(t,x) = \E[f(Z_T) \mid Z_t = x]$ satisfies a PDE obtained by composing these structures. Formally:
\begin{equation}
\partial_t v = \E[\partial_\tau u \cdot \partial_t \tau + \frac{1}{2}\partial_x^2 u \cdot d\langle \tau \rangle_t + \text{higher order}].
\end{equation}

The ``higher order'' terms arise because $\tau_t$ has its own quadratic variation, leading to:
\begin{equation}
\partial_t v = \frac{1}{2}\partial_x^2 v \cdot \E[d\tau_t] + \frac{1}{8}\partial_x^4 v \cdot \E[(d\tau_t)^2] + \cdots
\end{equation}

\textbf{Step 4: Scaling.} The dominant term at small $t$ is the fourth-order term because $\E[\tau_t] = \E[|B^{(2)}_t|] = \sqrt{2t/\pi}$ while $\E[\tau_t^2] = t$. More precisely, the density $p(t,x)$ satisfies:
\begin{equation}
\partial_t p = c \, \partial_x^4 p
\end{equation}
where $c$ is determined by the scaling of the quartic variation. Allouba--Zheng \cite{AlloubaZheng2001} compute $c = \frac{1}{8}$.

statement:
The energy space for the Poisson process is
\begin{equation}
\Hi_N = L^2([0,T] \times \{1\}, \lambda \, dt) \cong L^2([0,T])
\end{equation}
with the stochastic integral $\delta_N(u) = \int_0^T u_s \, d\tilde{N}_s$ where $\tilde{N}_t = N_t - \lambda t$ is the compensated Poisson process.

For a functional $F = f(N_T)$, the operator derivative is the \textbf{difference operator}:
\begin{equation}
(D_N F)_t = F(\omega + \delta_t) - F(\omega) = f(N_T + 1) - f(N_T)
\end{equation}
where $\omega + \delta_t$ denotes the path with an additional jump at time $t$.

\label{prop:poisson-adjoint}
The difference operator $D_N$ and the compensated integral $\delta_N$ satisfy the adjointness relation:
\begin{equation}
\E[F \cdot \delta_N(u)] = \E[\langle D_N F, u \rangle_{\Hi_N}] = \lambda \int_0^T \E[(D_N F)_t \cdot u_t] \, dt.
\end{equation}

\label{thm:poisson-generator}
The generator for the Poisson process acting on functions $f : \mathbb{Z}_{\geq 0} \to \R$ is
\begin{equation}
\mathcal{L} f(n) = \lambda (f(n+1) - f(n)).
\end{equation}
The Feynman--Kac function $u(t,n) = \E[f(N_T) \mid N_t = n]$ satisfies
\begin{equation}
\partial_t u + \lambda(u(\cdot, n+1) - u(\cdot, n)) = 0.
\end{equation}

following_proof:
For $F = f(N_T)$ and $Y_t = f(N_t)$, the operator It\^o formula gives:
\begin{equation}
dY_t = (D_N Y_t) \, dN_t = (f(N_{t^-} + 1) - f(N_{t^-})) \, dN_t.
\end{equation}
The compensator is $\lambda(f(N_t + 1) - f(N_t)) \, dt$. For $u(t,n) = \E[f(N_T) \mid N_t = n]$ to be a martingale, the drift must vanish:
\begin{equation}
\partial_t u + \lambda(u(t, n+1) - u(t, n)) = 0. \qedhere
\end{equation}

statement:
\label{thm:compound-poisson}
The generator is the nonlocal operator
\begin{equation}
\mathcal{L} f(x) = \lambda \int_{\R} (f(x + z) - f(x)) \, \nu(dz).
\end{equation}

following_proof:
The operator derivative now depends on the jump size:
\begin{equation}
(D_X F)_{t,z} = F(\omega + z \cdot \delta_t) - F(\omega) = f(X_T + z) - f(X_T).
\end{equation}
The energy space is $\Hi_X = L^2([0,T] \times \R, \lambda \, dt \otimes \nu(dz))$.

The It\^o formula for compound Poisson gives:
\begin{equation}
df(X_t) = \int_{\R} (f(X_{t^-} + z) - f(X_{t^-})) \, \tilde{N}(dt, dz) + \lambda \int_{\R} (f(X_t + z) - f(X_t)) \, \nu(dz) \, dt
\end{equation}
where $\tilde{N}$ is the compensated Poisson random measure. The generator is the coefficient of $dt$.

statement:
\label{thm:levy-generator}
The generator is
\begin{equation}
\mathcal{L} f(x) = \int_{\R} (f(x+z) - f(x) - z f'(x) \mathbf{1}_{|z| \leq 1}) \, \nu(dz).
\end{equation}

\label{ex:stable}
For the symmetric $\alpha$-stable process with $\alpha \in (0,2)$, the L\'evy measure is $\nu(dz) = c_\alpha |z|^{-1-\alpha} \, dz$. The generator is the \textbf{fractional Laplacian}:
\begin{equation}
\mathcal{L} f(x) = -(-\Delta)^{\alpha/2} f(x) = c_\alpha \, \text{P.V.} \int_{\R} \frac{f(x+z) - f(x)}{|z|^{1+\alpha}} \, dz.
\end{equation}

\label{thm:levy-operator}
For a L\'evy process with Gaussian and jump components, the operator derivative decomposes as
\begin{equation}
D_X F = D_B F + D_J F
\end{equation}
where $D_B$ is the Malliavin derivative (for the Gaussian part) and $D_J$ is the difference operator (for jumps).

The Leibniz rule holds for $D_B$ but requires correction for $D_J$:
\begin{align}
D_B(FG) &= F \, D_B G + G \, D_B F, \\
D_J(FG)_{t,z} &= F \, D_J G_{t,z} + G \, D_J F_{t,z} + D_J F_{t,z} \cdot D_J G_{t,z}.
\end{align}
The correction term $D_J F \cdot D_J G$ reflects the discrete nature of jumps.

For $f : \mathbb{C} \to \mathbb{C}$ analytic, the function $u(t,z) = \E[f(Z_T) \mid Z_t = z]$ satisfies:
\begin{enumerate}
\item[(a)] The heat equation $\partial_t u + \frac{1}{2}\Delta u = 0$.
\item[(b)] The Cauchy--Riemann equation $\partial_{\bar{z}} u = 0$ (analyticity in $z$).
\item[(c)] Therefore $\partial_t u = 0$: the conditional expectation is constant in $t$.
\end{enumerate}

\label{thm:general-principle}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi)$ on energy space $\Hi$. Then:
\begin{enumerate}
\item[(a)] The intrinsic bracket of $X$ satisfies $d\langle X \rangle^{(D,\Pi)}_t = \|\Pi D_X X_t\|^2_\Hi \, dt$.
\item[(b)] For Gaussian $X$ with covariance $R$, this equals $\frac{d}{dt}R(t,t)\,dt$.
\item[(c)] For jump processes with L\'evy measure $\nu$, the generator includes the nonlocal term $\int(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1})\,\nu(dz)$.
\item[(d)] For compositions $Z = X \circ Y$, the energy space is a tensor product and the generator may be higher-order.
\end{enumerate}

\label{thm:main-bm}
For Brownian motion, the RKHS norm is $\|h\|_\Hi = \|h'\|_{L^2}$, and the Feynman--Kac equation is
\begin{equation}
\partial_t u + \frac{1}{2}\Delta u = 0.
\end{equation}

\label{thm:main-fbm}
For fractional Brownian motion with Hurst parameter $H \neq 1/2$, the marginal density satisfies
\begin{equation}
\partial_t p = H t^{2H-1} \Delta p.
\end{equation}
The time-dependent coefficient reflects non-Markovian memory encoded in the RKHS---not a spatial fractional operator.

The operator derivative $D_X F \in L^2(\Omega; \Hi)$ is defined via Riesz representation:
\begin{equation}\label{eq:riesz-def}
\E[F \cdot \delta_X(u)] = \E[\ip{D_X F}{u}_\Hi] \quad \text{for all } u \in \Hi.
\end{equation}

For $u \in L^2(\Omega; \Hi)$,
\begin{equation}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-}$ is the left-limit of the filtration generated by $X$.

\label{thm:factorization}
For $F$ in a dense subalgebra of $L^2(\Omega)$,
\begin{equation}
F - \E[F] = \delta_X(\Pi D_X F).
\end{equation}

For a process $Y_t$ in the domain of $D$, define
\begin{equation}
\langle Y \rangle^{(D,\Pi)}_t = \int_0^t \|\Pi D_X Y_s\|^2_\Hi\,ds.
\end{equation}

\label{thm:ito}
