\end{equation}
with norm $\|h\|_{\Hi_{\mathrm{IBM}}} = \|h''\|_{L^2}$.

\label{thm:main-principle}
Let $X$ be a stochastic process with operator triple $(D_X, \delta_X, \Pi_X)$ on an energy space $\Hi$. Let $Y_t = g(t, X_t)$ for smooth $g$. Assume the operator It\^o formula (Theorem~\ref{thm:ito}) applies. Then the second-order term in the It\^o expansion of $\varphi(Y_t)$ is
\begin{equation}
\frac{1}{2}\varphi''(Y_t) \|\Pi D_X Y_t\|^2_\Hi \, dt.
\end{equation}
For Markov processes with time-homogeneous transition densities, this determines the generator $\mathcal{L}$ via the Feynman--Kac correspondence. For non-Markov processes, it determines the time-dependent coefficient in the PDE.

\label{thm:main-bm}
For standard Brownian motion $B_t$ with RKHS norm $\|h\|_\Hi = \|h'\|_{L^2}$:
\begin{enumerate}
\item[(a)] The intrinsic bracket satisfies $d\langle B \rangle^{(D,\Pi)}_t = dt$.
\item[(b)] The generator is $\mathcal{L} = \frac{1}{2}\Delta$.
\item[(c)] The Feynman--Kac function $u(t,x) = \E[f(B_T) \mid B_t = x]$ satisfies $\partial_t u + \frac{1}{2}\Delta u = 0$.
\end{enumerate}

\label{thm:main-fbm}
For fractional Brownian motion $B^H_t$ with $H \in (0,1)$:
\begin{enumerate}
\item[(a)] The marginal density $p(t,x)$ satisfies $\partial_t p = Ht^{2H-1} \partial_x^2 p$.
\item[(b)] The time-dependent coefficient $Ht^{2H-1} = \frac{1}{2}\frac{d}{dt}\mathrm{Var}(B^H_t)$ arises from the RKHS covariance structure.
\item[(c)] No time-homogeneous generator exists (non-Markov), but the intrinsic bracket $\|\Pi D F\|^2_{\Hi_H}$ is well-defined.
\end{enumerate}

\label{thm:main-ibm}
For integrated Brownian motion $I_t = \int_0^t B_s\,ds$ with RKHS norm $\|h\|_\Hi = \|h''\|_{L^2}$:
\begin{enumerate}
\item[(a)] The intrinsic bracket satisfies $d\langle I \rangle^{(D,\Pi)}_t = t^2\,dt$.
\item[(b)] The marginal density $p(t,x)$ satisfies $\partial_t p = \frac{t^2}{2} \partial_x^2 p$.
\item[(c)] For the joint process $(B_t, I_t)$, the Kolmogorov backward equation involves $\frac{1}{2}\partial_x^2 + x\partial_y$, consistent with the fourth-order structure when $B$ is integrated out.
\end{enumerate}

\label{thm:main-iterated}
For iterated Brownian motion $Z_t = B^{(1)}(|B^{(2)}_t|)$ with independent Brownian motions $B^{(1)}, B^{(2)}$:
\begin{enumerate}
\item[(a)] The energy space is the tensor product $\Hi_Z = \Hi^{(1)} \otimes \Hi^{(2)}$.
\item[(b)] The operator derivative decomposes as $D_Z = D^{(1)} + D^{(2)}$, with the chain rule applied at each level.
\item[(c)] The quartic variation arises from the intrinsic bracket: $[Z]^{(4)}_t = \int_0^t (d\langle Z\rangle^{(D,\Pi)}_s)^2$.
\item[(d)] The marginal density satisfies $\partial_t p = \frac{1}{8}\partial_x^4 p$ (the biharmonic equation).
\end{enumerate}
This recovers the Allouba--Zheng result \cite{AlloubaZheng2001} from the operator framework.

\label{thm:main-levy}
For a L\'evy process $X_t$ with L\'evy measure $\nu$:
\begin{enumerate}
\item[(a)] The energy space for the jump component is $\Hi_J = L^2([0,T] \times \R, dt \otimes \nu)$.
\item[(b)] The operator derivative is the difference operator $(D_J F)_{t,z} = F(\omega + z\delta_t) - F(\omega)$.
\item[(c)] The generator is nonlocal: $\mathcal{L}f(x) = \int(f(x+z) - f(x) - zf'(x)\mathbf{1}_{|z|\leq 1})\,\nu(dz)$.
\item[(d)] For $\alpha$-stable processes, this gives the fractional Laplacian $(-\Delta)^{\alpha/2}$.
\end{enumerate}
The fractional Laplacian arises from jump structure, not memory---contrasting with fBM.

An \textbf{energy space} for a stochastic process $X$ is a Hilbert space $\Hi$ such that:
\begin{enumerate}
\item[(i)] There exists a densely-defined closed operator $\delta_X : \mathrm{dom}(\delta_X) \subset \Hi \to L^2(\Omega)$ (the \textbf{divergence} or stochastic integral).
\item[(ii)] The adjoint $D_X := \delta_X^*$ (the \textbf{operator derivative}) is also densely defined.
\item[(iii)] The factorization $F - \E[F] = \delta_X(\Pi D_X F)$ holds for a dense class of $F \in L^2(\Omega)$.
\end{enumerate}

The operator derivative $D_X F \in L^2(\Omega; \Hi)$ is defined via Riesz representation:
\begin{equation}\label{eq:riesz-def}
\E[F \cdot \delta_X(u)] = \E[\ip{D_X F}{u}_\Hi] \quad \text{for all } u \in \mathrm{dom}(\delta_X).
\end{equation}

For $u \in L^2(\Omega; \Hi)$,
\begin{equation}
(\Pi u)_t = \E[u_t \mid \F_{t^-}],
\end{equation}
where $\F_{t^-}$ is the left-limit of the filtration generated by $X$.

\label{thm:factorization}
