\label{def:axioms}
Assume the following hold for all $t\in[0,T]$.
\begin{enumerate}[label=\textbf{(A\arabic*)},leftmargin=2.2em]
  \item \textbf{(Decomposition / defect).} For all $F\in\Dom(D)$,
  \begin{equation}\label{eq:A1}
    D(\E_t F) = P_t(DF) + C_t(F).
  \end{equation}

  \item \textbf{(Causal range of $P_t$).} For all $G\in L^2(\Omega;H)$,
  \begin{equation}\label{eq:A2}
    (I-Q_t)P_t(G)=0.
  \end{equation}

  \item \textbf{(Causal range of conditioned derivative).} For all $F\in\Dom(D)$,
  \begin{equation}\label{eq:A3}
    (I-Q_t)D(\E_t F)=0.
  \end{equation}

  \item \textbf{(Relative defect bound).} There exists $K(t)\ge 0$ such that for all $F\in\Dom(D)$,
  \begin{equation}\label{eq:A4}
    \|C_t(F)\|_{L^2(\Omega;H)} \le K(t)\,\|P_t(DF)\|_{L^2(\Omega;H)}.
  \end{equation}

  \item \textbf{(Past nondegeneracy of $\Pi$).} For a given orthogonal projection $\Pi:H\to H$, there exists $\gamma(t)>0$ such that
  \begin{equation}\label{eq:A5}
    \|Q_t h\|_H \le \gamma(t)^{-1}\,\|\Pi Q_t h\|_H\qquad \forall\,h\in H.
  \end{equation}
  Equivalently, $\inf_{\|h\|=1,\ h\in\Ran(Q_t)}\|\Pi h\|\ge \gamma(t)$.

  \item \textbf{(Controllability / richness).} For every $h\in \Ran((I-Q_t)\Pi)$ and every $\varepsilon>0$, there exists $F\in\Dom(D)$ such that
  \begin{equation}\label{eq:A6}
    \|P_t(DF)-h\|_{L^2(\Omega;H)}+\|C_t(F)-h\|_{L^2(\Omega;H)}<\varepsilon.
  \end{equation}
\end{enumerate}

Axioms (A1)--(A3) encode ``conditioning/prediction removes future dependence'' at the level of $H$-directions.
(A4) is an energy/orthogonality bound; (A5) is a geometric principal-angle condition between $\Ran(Q_t)$ and $\Ran(\Pi)$;
(A6) yields sharp obstruction (near-extremizers) when leakage is nonzero.

\label{thm:spectral}
Assume $\alpha := 2H_2 \in (0, 1)$, i.e., $H_2 \in (0, 1/2)$
(monotone regime).  In the large-$\tau$ limit, the spectral
retention ceiling of \eqref{eq:spectral-win} satisfies
\begin{equation}\label{eq:spectral-ceiling}
\log A_{\mathrm{spec}}(H_1, H_2) \;=\;
\frac{1}{2H_2}\left[\log\frac{r_c}{r_d}
- \log\bigl(c\,\Gamma(1-2H_2)\bigr)
- 2H_1\log|\xi_c|
- \log E_{2H_2}\bigl(-c|\xi_d|^{2H_1}\bigr)\right]
+ o(1),
\end{equation}
as $c \to 0$ or equivalently $\tau_{\max} \to \infty$.

\label{cor:sensitivity}
The ratio of retention's sensitivity to $H_2$ versus $H_1$ is,
from \eqref{eq:spectral-ceiling},
\begin{equation}\label{eq:sensitivity}
\left|\frac{\partial \log A_{\mathrm{spec}}/\partial H_2}
          {\partial \log A_{\mathrm{spec}}/\partial H_1}\right|
\;\approx\; \frac{1}{H_2} \cdot
\frac{\log(r_c/r_d) + 2H_1 \log(|\xi_d|/|\xi_c|) + \text{const}}
     {2 \log(|\xi_d|/|\xi_c|)}.
\end{equation}
$H_2$ dominance grows as $1/H_2$ (stronger in the long-tail
regime) and shrinks proportionally to $\log(|\xi_d|/|\xi_c|)$
(weaker for larger spectral contrast).

\label{def:triple}
A \emph{causal derivation--divergence triple} is $(D,\delta,\Pi)$ where:
\begin{enumerate}[label=(\arabic*)]
\item $D: \Dom(D) \subset L^2(\Omega) \to L^2(\Omega;\HH)$ is a densely-defined closed linear operator (the \emph{derivation}) with $\mathbf{1}\in\Dom(D)$ and $D\mathbf{1}=0$.
\item $\delta: \Dom(\delta) \subset L^2(\Omega;\HH) \to L^2(\Omega)$ is the Hilbert space adjoint of $D$ (the \emph{divergence}):
\begin{equation}\label{eq:adjoint}
\mathbb{E}[F\delta(u)] = \mathbb{E}[\inner{DF}{u}_\HH], \qquad F \in \Dom(D),\; u \in \Dom(\delta).
\end{equation}
\item $\Pi: L^2(\Omega;\HH) \to L^2(\Omega;\HH)$ is a bounded projection (``causal'' or ``predictable'') with $\Pi^2 = \Pi$.
\end{enumerate}

\label{ass:chain}
There exists a subalgebra $\AAA \subset \Dom(D)$ dense in $L^2(\Omega)$ and stable under multiplication such that for $F\in\AAA$ and $\varphi\in C^1_b(\mathbb{R})$,
\begin{equation}\label{eq:chain}
D(\varphi(F)) = \varphi'(F)DF.
\end{equation}
For $\varphi\in C^1_b(\mathbb{R}^n)$ and $F=(F_1,\ldots,F_n)$ with $F_i\in\AAA$,
$D(\varphi(F)) = \sum_{i=1}^n \partial_i\varphi(F)\,DF_i$.

\label{ass:factor}
For $F\in\AAA$,
\begin{equation}\label{eq:factor}
(\Id - \mathbb{E})F = \delta(\Pi DF).
\end{equation}

\label{def:bracket}
Let $Y = (Y_t)_{t\in[0,T]}$ be such that $Y_t\in\Dom(D)$ for a.e.\ $t$ and $t\mapsto \Pi DY_t$ lies in $L^2([0,T]\times\Omega;\HH)$. Define the \emph{intrinsic bracket}
\begin{equation}\label{eq:bracket}
\langle Y\rangle^{(D,\Pi)}_t := \int_0^t \norm{\Pi DY_s}_\HH^2\,ds.
\end{equation}

\label{def:Ito}
A real process $Y = (Y_t)_{t\in[0,T]}$ is called a \emph{$(D,\delta,\Pi)$-It\^o process} if:
\begin{enumerate}[label=(\arabic*)]
\item $t\mapsto Y_t$ is $L^2(\Omega)$-continuous and $Y_t\in\Dom(D)$ for each $t\in[0,T]$.
\item There exists $a\in L^2([0,T]\times\Omega)$ (the \emph{drift}) such that for all $t\in[0,T]$,
\begin{equation}\label{eq:decomp}
Y_t = Y_0 + \int_0^t a_s\,ds + \delta(\Pi DY\cdot\mathbf{1}_{[0,t]}),
\end{equation}
where the equality holds in $L^2(\Omega)$.
\item The map $t\mapsto \Pi DY_t$ lies in $L^2([0,T]\times\Omega;\HH)$.
\end{enumerate}

\label{rem:existence}
The decomposition~\eqref{eq:decomp} is a \emph{definition} of the class, not a theorem asserting existence. We do not claim that every $L^2$-continuous process admits this form. Rather:
\begin{enumerate}[label=(\alph*)]
\item For Volterra Gaussian processes (Section~\ref{sec:volterra}), existence of the decomposition follows from the Malliavin calculus construction.
\item For other processes, one must either verify the decomposition directly or work within a class where it is known to hold.
\end{enumerate}

\label{thm:product}
