For $N > 0$ and $A > 1$, define the frequency shell $S_N^A := \{\xi \in \R^3 : N/A \leq |\xi| \leq AN\}$ and:
\begin{align}
\Eloc(t; N, A) &:= \int_{S_N^A} |\xi| \, |\hat{u}(\xi, t)|^2 \, d\xi \\
\Dloc(t; N, A) &:= \int_{S_N^A} |\xi|^3 \, |\hat{u}(\xi, t)|^2 \, d\xi \\
\Floc(t; N, A) &:= \int_{S_N^A} |\xi|^5 \, |\hat{u}(\xi, t)|^2 \, d\xi
\end{align}

Let $P_N^A$ denote the Fourier projection onto $S_N^A$. Define:
\begin{equation}
\Tril_{\mathrm{loc}}(t; N, A) := \langle (P_N^A u \cdot \nabla) P_N^A u, |\nabla| P_N^A u \rangle
\end{equation}

\label{ass:CC}
We assume the solution $u$ satisfies the following on $[t_0, T^*)$ for some $t_0 < T^*$:

There exist continuous functions $N: [t_0, T^*) \to (0, \infty)$ and $x: [t_0, T^*) \to \R^3$, and constants $A_0 > 1$, $\delta_0 \in (0, 1)$, such that:

\begin{enumerate}[label=(CC\arabic*)]
\item \textbf{Frequency concentration:} For all $t \in [t_0, T^*)$ and all $A \geq A_0$:
\begin{equation}\label{eq:CC1}
\Eloc(t; N(t), A) \geq (1 - \delta_0) E(t)
\end{equation}

\item \textbf{Frequency scale divergence:}
\begin{equation}\label{eq:CC2}
\lim_{t \to T^*} N(t) = +\infty
\end{equation}

\item \textbf{Critical blow-up:}
\begin{equation}\label{eq:CC3}
\lim_{t \to T^*} E(t) = +\infty
\end{equation}
\end{enumerate}

Assumption~\ref{ass:CC} follows from:
\begin{itemize}
\item The existence of a blow-up solution (CC3)
\item The concentration-compactness/profile decomposition theory of Gallagher-Koch-Planchon, which implies that minimal blow-up solutions satisfy (CC1) and (CC2)
\end{itemize}
We take this as a hypothesis rather than reproving the concentration-compactness theory.

\label{lem:energy}
For smooth solutions to \eqref{eq:NS}:
\begin{equation}\label{eq:energy-evol}
\frac{dE}{dt} = -2\Tril - 2\nu D
\end{equation}

\label{lem:tril-bound}
For any $u \in \Hdot{1/2} \cap \Hdot{3/2}$:
\begin{equation}\label{eq:tril-bound}
|\Tril| \leq C_0 \, E \, D^{1/2}
\end{equation}
where $C_0$ is a universal constant (depending only on dimension).

\label{lem:tril-decomp}
Under Assumption~\ref{ass:CC}, for any $A \geq A_0$:
\begin{equation}\label{eq:tril-decomp}
\Tril = \Tril_{\mathrm{loc}}(t; N(t), A) + \Tril_{\mathrm{err}}(t; A)
\end{equation}
where the error satisfies:
\begin{equation}\label{eq:tril-err}
|\Tril_{\mathrm{err}}(t; A)| \leq C_1 \sqrt{\delta_0} \, E(t) \, D(t)^{1/2}
\end{equation}
with $C_1$ depending only on $A$ and dimension.

\label{lem:diss}
Under Assumption~\ref{ass:CC}:
\begin{equation}\label{eq:diss-lower}
D(t) \geq (1 - \delta_0) \Dloc(t; N(t), A_0)
\end{equation}
and
\begin{equation}\label{eq:diss-freq}
\Dloc(t; N(t), A_0) \geq \frac{N(t)^2}{A_0^2} \Eloc(t; N(t), A_0) \geq \frac{(1-\delta_0) N(t)^2}{A_0^2} E(t)
\end{equation}

\label{thm:main}
Let $u$ be a smooth solution to \eqref{eq:NS} satisfying Assumption~\ref{ass:CC} with parameters $A_0$, $\delta_0$, $N(t)$, $x(t)$.

Define the \textbf{effective frequency ratio}:
\begin{equation}
\Lambda(t) := \frac{C_0 (1 + C_1\sqrt{\delta_0}) E(t)^{1/2}}{\nu N(t) / A_0}
\end{equation}
where $C_0$ is from Lemma~\ref{lem:tril-bound} and $C_1$ from Lemma~\ref{lem:tril-decomp}.

Then exactly one of the following holds for each $t \in [t_0, T^*)$:

\textbf{Case I (Trilinear-Dominated Regime):} $\Lambda(t) > 1$
\begin{equation}
\text{The bound } |\Tril| \leq C_0(1 + C_1\sqrt{\delta_0}) E D^{1/2} \text{ does not preclude } \Tril < -\nu D
\end{equation}

\textbf{Case II (Dissipation-Dominated Regime):} $\Lambda(t) \leq 1$
\begin{equation}\label{eq:case2}
\frac{dE}{dt} \leq -2\nu D + 2|\Tril| \leq -2\nu D + 2C_0(1+C_1\sqrt{\delta_0}) E D^{1/2} \leq 0
\end{equation}
In this case, $E(t)$ is non-increasing.

\label{cor:case1}
Under Assumption~\ref{ass:CC}, if $E(t) \to \infty$ as $t \to T^*$, then $\Lambda(t) > 1$ for all $t$ sufficiently close to $T^*$.

Equivalently:
\begin{equation}\label{eq:freq-bound}
N(t) < \frac{C_0 (1 + C_1\sqrt{\delta_0}) A_0}{\nu} E(t)^{1/2}
\end{equation}

\label{ass:angular}
The CC-localized solution has a limiting profile $\phi$ (in the sense of almost-periodicity) satisfying:
\begin{equation}
\rho^\phi := \frac{\max_j E_j^\phi}{\|\phi\|_{\Hdot{1/2}}^2} \geq 1 - \eps_*
\end{equation}
for some $\eps_* < 1/4$.

\label{thm:conditional}
Under Assumptions~\ref{ass:CC} and \ref{ass:angular}, the localized trilinear satisfies:
\begin{equation}
|\Tril_{\mathrm{loc}}| \leq C_0 (\theta_0 + \sqrt{\eps_*} + \sqrt{\delta_0}) E D^{1/2}
\end{equation}

For $\theta_0$, $\eps_*$, $\delta_0$ sufficiently small (depending on $\nu$, $A_0$, $C_0$), this leads to a contradiction with blow-up.

\label{thm:conditional-regularity}
Assume the concentration hypothesis and the \emph{early-time
entropy control hypothesis}
(Hypothesis~\ref{hyp:early-entropy} below).  Then $T^*
= \infty$: the Navier--Stokes solution is globally regular.

\label{hyp:concentration}
The blow-up solution $u$ admits a decomposition~\eqref{eq:profile}
where the profile $U^*$ has $\delta(U^*) \geq \theta_0 > 0$,
and the remainder satisfies
$\norm{w(t)}_{\Hdot{1/2}} \to 0$ as $t \to T^*$.

\label{hyp:early-entropy}
The angular entropy satisfies
$\cS(u(t)) \geq \cS_* > 0$ for $t \in [0, t_0]$,
where $t_0$ is from Theorem~\ref{thm:Phi-near-blowup}
and $\cS_*$ depends on $u_0$, $\nu$, and $T^*$.

\label{lem:perturb-bounds}
With $\norm{w} \leq \eta E^{*1/2}$:
