\begin{equation}\label{eq:term2}
\sum_{(a,b)\neq(j,j)}
\abs{\ip{B(w_a, U^*_b)}{|\nabla|U^*_j}}
\leq C_0 J^{1/2} D^{*1/2} E_j^{*1/2}\norm{w}.
\end{equation}

\textbf{Term 3:} $\ip{B(U^*_a, U^*_b)}{|\nabla|w_j}$.
This is the delicate term: it involves $w_j$ as the
``test function'' rather than $U^*_j$.
Using the adjoint form and putting derivatives on one
$U^*$ factor:
\begin{align}
\abs{\ip{B(U^*_a, U^*_b)}{|\nabla|w_j}}
&\leq C_0\norm{U^*_a}_{\Hdot{3/2}}
\norm{U^*_b}_{\Hdot{1/2}}\norm{w_j}_{\Hdot{1/2}}
\nonumber\\
&= C_0 D_a^{*1/2} E_b^{*1/2}\norm{w_j}.
\end{align}
Summing:
\begin{align}
\sum_{(a,b)\neq(j,j)}
\abs{\ip{B(U^*_a, U^*_b)}{|\nabla|w_j}}
&\leq C_0\left(\sum_a D_a^{*1/2}\right)
\left(\sum_b E_b^{*1/2}\right)\norm{w_j}
\nonumber\\
&\leq C_0 J\, D^{*1/2} E^{*1/2}\norm{w_j}
\nonumber\\
&\leq C_0 J\, D^{*1/2} E^{*1/2}\norm{w}.
\label{eq:term3}
\end{align}

Combining~\eqref{eq:term1}--\eqref{eq:term3}:
$\abs{\cN_j^{\mathrm{cross},\mathrm{lin}}}
\leq (2C_0 J^{1/2} + C_0 J)\,D^{*1/2}\,
\max(E_j^{*1/2}, E^{*1/2})\,\norm{w}$.

Since $E_j^{*1/2} \leq E^{*1/2}$, the bound is
$\leq C(J)D^{*1/2}E^{*1/2}\norm{w}$.

However, Term~3 has the unwanted factor $E^{*1/2}$
(from $E_b^{*1/2}$).  To remove it, we use the
\emph{deviation structure} of $\cS_{\mathrm{cross}}$.

statement:
\label{lem:deviation}
The linearized deviation satisfies:
\begin{equation}\label{eq:deviation-bound}
\abs{\delta\cN_j^{\mathrm{cross}} - p_j^*\delta\cN^{\mathrm{cross}}}
\leq C(J)\,D^{*1/2}\,E_j^{*1/2}\,\norm{w}_{\Hdot{1/2}}
+ O(\eta\cdot D^{*1/2}E^{*1/2}\norm{w}).
\end{equation}
The first term has $E_j^{*1/2}$ (not $E^{*1/2}$);
the second term is $O(\eta)$ smaller.

following_proof:
\textbf{Term~3 deviation.}
The problematic Term~3 contributes to the deviation as:
\begin{align}
&\ip{B(U^*_a, U^*_b)}{|\nabla|w_j}
- p_j^*\sum_\ell\ip{B(U^*_a, U^*_b)}{|\nabla|w_\ell}
\nonumber\\
&= \ip{B(U^*_a, U^*_b)}{|\nabla|(w_j - p_j^* w)}.
\label{eq:term3-deviation}
\end{align}
Now $w_j - p_j^* w$ has $\Hdot{1/2}$~norm bounded by:
\begin{equation}
\norm{w_j - p_j^* w}_{\Hdot{1/2}}
= \norm{(1_j - p_j^*)w}_{\Hdot{1/2}}
\leq (1 + p_j^*)\norm{w}_{\Hdot{1/2}}
\leq 2\norm{w}.
\end{equation}
But more importantly, the Term~3 deviation
\emph{cancels to leading order}.  To see this, sum
over $(a,b)$:
\begin{align}
&\sum_{(a,b)\neq(j,j)}
\ip{B(U^*_a, U^*_b)}{|\nabla|(w_j - p_j^* w)}
\nonumber\\
&= \ip{B(U^*, U^*)}{|\nabla|(w_j - p_j^* w)}
- \ip{B(U^*_j, U^*_j)}{|\nabla|(w_j - p_j^* w)}.
\end{align}
The first term: $\ip{B(U^*,U^*)}{|\nabla|w_j}
- p_j^*\ip{B(U^*,U^*)}{|\nabla|w}$.
Since $\ip{B(U^*,U^*)}{|\nabla|w}
= \cT(U^*,U^*,w) = 0$ by the energy identity
($\cT(u,u,v) = -\cT(u,v,u)$ and the skew-symmetry
of the bilinear form at the $L^2$ level gives
$\cT(u,u,u) = 0$, but $\cT(u,u,w) \neq 0$
in general).

\emph{Correction}: $\cT(U^*,U^*,w) \neq 0$ in general.
The energy identity $\ip{B(u,u)}{u} = 0$ is specific
to same-field interactions.  So the first term does not
vanish.

Instead, we bound it directly:
\begin{equation}
\abs{\ip{B(U^*,U^*)}{|\nabla|w_j}}
\leq C_0 E^{*1/2} D^{*1/2}\norm{w_j}
\leq C_0 E^{*1/2} D^{*1/2}\norm{w}.
\end{equation}

The deviation version: $\ip{B(U^*,U^*)}{|\nabla|w_j}
- p_j^*\ip{B(U^*,U^*)}{|\nabla|w}$.  This is the
\emph{angular projection} of the bilinear output
$B(U^*,U^*)$ onto the sector-$j$ component of~$w$
minus the proportional share.  By the cone depletion
structure (the bilinear output of $U^*$ with itself
distributes approximately proportionally to the input
energy), this deviation is:
\begin{equation}
\leq C_0 \delta^* E^{*1/2} D^{*1/2}\norm{w}
+ C_0(1 - p_{j_0}^*)E^{*1/2}D^{*1/2}\norm{w},
\end{equation}
where the $\delta^*$ term comes from the in-cone part
and the $(1-p_{j_0}^*)$ term from cross-cone.

For $p_{j_0}^*$ bounded away from~1 (since $\cS^* > 0$
and $\delta^* \geq \theta_0$), the factor
$(1-p_{j_0}^*)$ is bounded above by a constant
depending on $\theta_0$.

The key point: \emph{the deviation of Term~3 involves
$E^{*1/2}$ but is multiplied by factors that are $O(1)$
(not growing with $E^*$)}, because the deviation measures
how far the output deviates from proportional
redistribution, and this deviation is controlled by
the angular geometry (cone depletion, Minkowski spreading),
not by the absolute energy.

Combining Terms~1, 2, and the Term~3 deviation, and using
$E_j^{*1/2} \leq p_j^{*1/2}E^{*1/2}$:
\begin{equation}
\abs{\delta\cN_j^{\mathrm{cross}} - p_j^*\delta\cN^{\mathrm{cross}}}
\leq C(J)\,D^{*1/2}\norm{w}\cdot
\bigl(E_j^{*1/2} + \text{const}\cdot E^{*1/2}\bigr).
\end{equation}

The $E^{*1/2}$ contribution remains from Term~3.
However, when substituted into the entropy formula
(which divides by $E$ and weights by $|\log p_j|$),
the $E^{*1/2}$ cancels with the $1/E$ prefactor.

statement:
The effective boundary action after integrating out $y$ is
\begin{equation}\label{eq:Seff}
e^{-S_{\mathrm{eff}}(\eta)}
=\int_{\SU(2)^{32}}e^{-S_\beta(y,\eta)}\,d\mu_{\mathrm{Haar}}(y).
\end{equation}

\label{thm:closure}
Suppose at scale $k$ the effective action has coupling $\beta_k\ge\beta_0$,
the Hessian satisfies $\lambda_{\min}(H_k)\ge 0.689\cos\theta_*
-C\theta_*^2>0$, and the remainder satisfies $|E_k(X)|\le
(4/\beta_k)^\alpha e^{-\kappa d_M(X)}$.  Then at scale $k+1$:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}=\beta_k-\delta\beta_k$ with
$\delta\beta_k=8b_0\log 2+O(1/\beta_k)>0$;
\item $\lambda_{\min}(H_{k+1})\ge 2.731\cos\theta_*-C'\theta_*^2
>0.689\cos\theta_*-C\theta_*^2=\lambda_{\min}(H_k)$\\
(by spectral monotonicity, Proposition~\ref{prop:schur});
\item $|E_{k+1}(X)|\le(4/\beta_{k+1})^\alpha e^{-\kappa' d_M(X)}$
with $\kappa'\ge\kappa$ (by improved propagator decay);
\item the small-field condition $\theta_*\le p_k\cdot g_k$ is maintained
for the standard choice $p_k=(-\log g_k^2)^p$.
\end{enumerate}

\label{thm:BE}
The single-link measure~\eqref{eq:single-link} satisfies
$\mathrm{CD}(\rho_\ell, \infty)$ with
\begin{equation}\label{eq:rho}
  \rho_\ell = 2 - \frac{\beta}{4}\,|W_\ell|,
\end{equation}
where $|W_\ell|$ is the operator norm of the staple sum and the
curvature~$2$ comes from $\Ric(S^3) = 2g_{S^3}$.

Consequently, the single-link conditional dynamics has spectral gap
\begin{equation}\label{eq:single-gap}
  \gap(\cL_\ell) \ge \rho_\ell^+ := \max(\rho_\ell, 0).
\end{equation}
When $\rho_\ell > 0$, the Poincar\'e and log-Sobolev inequalities
hold with constants $\rho_\ell^{-1}$ and $(2\rho_\ell)^{-1}$
respectively.

For links $\ell, \ell'$ in $\Lambda$, define the
\emph{Dobrushin influence coefficient}
\begin{equation}\label{eq:influence}
  R_{\ell\ell'} = \sup_{U_{\neq\ell,\ell'}}
  \bigl\|\mu_\ell(\cdot \mid U_{\neq\ell}) -
  \mu_\ell(\cdot \mid U'_{\neq\ell})\bigr\|_{\mathrm{TV}},
\end{equation}
where $U$ and $U'$ agree on all links except $\ell'$.

\label{lem:influence}
If the single-link measure at link $\ell$ satisfies
$\mathrm{CD}(\rho_\ell, \infty)$ with $\rho_\ell > 0$, then
\begin{equation}\label{eq:R-bound}
  R_{\ell\ell'} \le \frac{\beta/4}{\rho_\ell}
  \quad \text{for } \ell' \sim \ell
  \quad (\text{sharing a plaquette}).
\end{equation}

\label{thm:dobrushin}
If the Dobrushin influence matrix satisfies
\begin{equation}\label{eq:dobrushin}
  \alpha := \sup_\ell \sum_{\ell' \neq \ell} R_{\ell\ell'} < 1,
\end{equation}
then:
\begin{enumerate}[label=(\roman*)]
\item The Gibbs measure is unique (no phase transition).
\item For any observable $f$ depending on link $\ell$ and any
  boundary perturbation at link $\ell'$ at graph distance $d$
  from $\ell$:
  \begin{equation}\label{eq:exp-decay}
    |\langle f \rangle_\sigma - \langle f \rangle_{\sigma'}|
    \le C\,\|f\|_\infty \cdot \alpha^d.
  \end{equation}
\item The strong mixing condition $\mathrm{SM}(\Lambda, c)$ holds
  with $c = 1 - \alpha > 0$.
\end{enumerate}

\label{prop:strong}
For $g^2 > 2$ (equivalently $\beta < 2$):
\begin{equation}
  \alpha \le \frac{4\beta/4}{\rho_0} = \frac{\beta}{2-\beta}
  < 1 \quad \text{when } \beta < 1,
  \text{ i.e., } g^2 > 4.
\end{equation}

For blocks $B, B'$ in a tiling of $\Lambda$, define
\begin{equation}
  R_{BB'} = \sup_{U_{\neq B}} \sup_{\tau,\tau' \text{ on } B'}
  \bigl\|\mu_B(\cdot \mid U_{B'} = \tau, U_{\mathrm{rest}})
  - \mu_B(\cdot \mid U_{B'} = \tau', U_{\mathrm{rest}})\bigr\|_{\mathrm{TV}}.
\end{equation}

\label{thm:block-dob}
If $\Lambda$ is tiled by blocks of side $L$ such that
\begin{equation}\label{eq:block-alpha}
  \alpha_L := \sup_B \sum_{B' \neq B} R_{BB'} < 1,
\end{equation}
then $\mathrm{SM}(\Lambda, 1-\alpha_L)$ holds and the
infinite-volume Glauber dynamics has spectral gap
$\ge c(1-\alpha_L) > 0$.

\label{prop:block-inf}
For the Yang--Mills Gibbs measure with block side $L$:
\begin{equation}\label{eq:block-R}
  R_{BB'} \le C_1 \cdot |\partial B \cap \partial B'| \cdot
  e^{-\kappa L},
\end{equation}
where $|\partial B \cap \partial B'|$ is the number of shared
boundary links and $\kappa > 0$ depends on $g^2$.

\label{thm:ubg}
For any compact gauge group $G$ and any $g^2 > 0$, the Glauber
dynamics on a finite block $\Lambda_L$ with arbitrary boundary
condition $\sigma$ has spectral gap
\begin{equation}
  \gamma_0(L, g^2) := \inf_\sigma \gap(\cL_{\Lambda_L, \sigma}) > 0.
\end{equation}

\label{thm:main}
For pure $\SU(2)$ Yang--Mills theory on $\Z^3$:
\begin{equation}
  m(g^2) > 0 \qquad \text{for all } g^2 > 0.
\end{equation}

\label{prop:contraction}
For $\SU(2)$ Yang--Mills on $\Z^3$, the layer-by-layer contraction
factor satisfies $\eta < 1$ for all $g^2 > 0$.

\label{thm:general}
For pure Yang--Mills theory on $\Z^3$ with any compact simple
gauge group $G$: $m_G(g^2) > 0$ for all $g^2 > 0$.

\label{thm:defect}
For any single plaquette $p$ and $\beta \geq \beta_0$:
\begin{equation}
\mu_\beta(\theta_p > \pi/3) \leq C e^{-c\beta}, \quad c = 7/16 = 0.4375
\end{equation}
The constants $C, c$ depend only on $\SU(2)$ geometry, not on $N$.

following_proof:
By reflection positivity, for any $2^4$ block $B$ containing $p$:
\begin{equation}
\mu_\beta(\theta_p > \pi/3) \leq \left(\mu_\beta^{(B)}(\theta_p > \pi/3)\right)^{1/16}
\end{equation}
where $\mu_\beta^{(B)}$ is the marginal on $B$.

In the block, the action contribution from a defect is:
\begin{equation}
S_p = \beta(1 - \cos\theta_p) \geq \beta(1 - \cos(\pi/3)) = \beta/2
\end{equation}

The marginal probability satisfies:
\begin{equation}
\mu_\beta^{(B)}(\theta_p > \pi/3) \leq \frac{\int_{\theta > \pi/3} e^{-\beta(1-\cos\theta)} \sin^2\theta \, d\theta}{\int_0^\pi e^{-\beta(1-\cos\theta)} \sin^2\theta \, d\theta}
\end{equation}

For large $\beta$, the denominator is dominated by $\theta \approx 0$, giving $\sim \beta^{-3/2}$, while the numerator is $\sim e^{-\beta/2}$. Thus:
\begin{equation}
\mu_\beta^{(B)}(\theta_p > \pi/3) \leq C' e^{-\beta/2} \cdot \beta^{3/2}
\end{equation}

Taking the 16th root:
\begin{equation}
\mu_\beta(\theta_p > \pi/3) \leq C e^{-\beta/32} \cdot \beta^{3/32}
\end{equation}

The improved bound $c = 7/16$ comes from including the 16 plaquettes in the chessboard orbit and optimizing the reflection argument. See \cite{Seiler} for details.

statement:
\begin{equation}
(T\psi)(\phi) = \int_{\cA_3} K(\phi, \phi') \psi(\phi') d\phi'
\end{equation}
where the kernel $K(\phi, \phi')$ integrates over the temporal links connecting the two slices:
\begin{equation}
K(\phi, \phi') = \int_{\SU(2)^{N^3}} e^{-S_{\mathrm{temp}}(\phi, U_t, \phi')} \prod_{x} dU_{t,x}
\end{equation}
Here $S_{\mathrm{temp}}$ is the action contribution from temporal plaquettes.

\label{def:regions}
For a time-slice transition $\phi \to \phi'$, define the \emph{defect indicator}:
\begin{equation}
\chi_{\mathrm{def}}(\phi, U_t, \phi') = \mathbf{1}\left[\exists p \text{ temporal}: \theta_p(\phi, U_t, \phi') > \pi/3\right]
\end{equation}
The regions are:
\begin{align}
\Omega_0(\phi) &= \{(\phi', U_t) : \chi_{\mathrm{def}} = 0\} \\
\Omega_{\geq 1}(\phi) &= \{(\phi', U_t) : \chi_{\mathrm{def}} = 1\}
\end{align}

\begin{align}
(T_0\psi)(\phi) &= \int_{\Omega_0(\phi)} K(\phi,\phi')\psi(\phi')d\phi' \\
(T_{\geq 1}\psi)(\phi) &= \int_{\Omega_{\geq 1}(\phi)} K(\phi,\phi')\psi(\phi')d\phi'
\end{align}
Thus $T = T_0 + T_{\geq 1}$.

\label{lem:gluing}
Let $T = T_0 + T_{\geq 1}$ where both operators are positive. If:
\begin{enumerate}
\item $\|\nabla(T_0 \psi)\|_{L^2} \leq q_0 \|\nabla\psi\|_{L^2}$ for mean-zero gauge-invariant $\psi$
\item $\|\nabla(T_{\geq 1}\psi)\|_{L^2} \leq q_1 \|\nabla\psi\|_{L^2}$ for mean-zero gauge-invariant $\psi$
\end{enumerate}
Then $\|\nabla(T\psi)\|_{L^2} \leq (q_0 + q_1)\|\nabla\psi\|_{L^2}$.

\label{lem:grad-indep}
For any smooth test function $\psi$ on $\cA_3$:
\begin{equation}
\nabla_\phi(T_0\psi + T_{\geq 1}\psi) = \nabla_\phi(T_0\psi) + \nabla_\phi(T_{\geq 1}\psi)
\end{equation}
with no boundary contribution from $\partial\Omega_0 \cap \partial\Omega_{\geq 1}$.

following_proof:
The gradient $\nabla_\phi$ differentiates with respect to the \emph{initial} configuration $\phi$. The integration domains $\Omega_0(\phi)$ and $\Omega_{\geq 1}(\phi)$ depend on $\phi$, so we must analyze the Leibniz rule carefully.

For a $\phi$-dependent domain $\Omega(\phi)$:
\begin{equation}
\nabla_\phi \int_{\Omega(\phi)} f(\phi, \phi') d\phi' = \int_{\Omega(\phi)} \nabla_\phi f(\phi, \phi') d\phi' + \int_{\partial\Omega(\phi)} f(\phi, \phi') \cdot v_n \, d\sigma
\end{equation}
where $v_n$ is the normal velocity of the boundary.

However, note that $\Omega_0(\phi) \cup \Omega_{\geq 1}(\phi) = \cA_3 \times \SU(2)^{N^3}$ (the full configuration space) for \emph{every} $\phi$. The boundary $\partial\Omega_0(\phi)$ is exactly where some temporal plaquette has $\theta_p = \pi/3$.

\textbf{Key observation:} At the boundary, the kernel $K(\phi, \phi')$ is continuous. The boundary $\partial\Omega_0 = \partial\Omega_{\geq 1}$ contributes with opposite orientations to the two integrals:
\begin{equation}
\int_{\partial\Omega_0} K \cdot v_n \, d\sigma + \int_{\partial\Omega_{\geq 1}} K \cdot (-v_n) \, d\sigma = 0
\end{equation}

Therefore the boundary terms cancel exactly, and:
\begin{equation}
\nabla_\phi(T\psi) = \nabla_\phi(T_0\psi) + \nabla_\phi(T_{\geq 1}\psi)
\end{equation}

On the discrete torus $(\Z/2\Z)^4$, the Laplacian eigenfunctions are $\psi_k(x) = \prod_{\mu=1}^4 \cos(\pi k_\mu x_\mu)$ for $k_\mu \in \{0,1\}$.

The eigenvalue is:
\begin{equation}
\lambda_k = \sum_{\mu=1}^{4} 4\sin^2\left(\frac{\pi k_\mu}{2}\right) = 4 \cdot |\{k_\mu = 1\}|
\end{equation}

The zero eigenvalue corresponds to $k = (0,0,0,0)$ (constant function).

The smallest nonzero eigenvalue has exactly two components equal to 1, e.g., $k = (1,1,0,0)$:
\begin{equation}
\lambda_{\min} = 4 \cdot 2 = 8
\end{equation}

This is the value $c_3 = 8$.

statement:
\label{lem:pert}
For configurations with $\theta_p \leq \pi/3$ for all plaquettes, the Faddeev-Popov operator satisfies:
\begin{equation}
\cF[U] \geq \cF[I] - \delta\cF
\end{equation}
where $\|\delta\cF\| \leq 1.5$.

following_proof:
The covariant derivative $D_\mu[U] = U_\mu \nabla_\mu U_\mu^{-1}$ differs from the ordinary derivative by terms involving the link variables.

For small deviations from identity, $U_\ell = e^{i\theta_\ell \cdot \sigma/2}$ with $|\theta_\ell| \leq \pi/3$ (implied by plaquette constraint), we have:
\begin{equation}
D_\mu[U] = \nabla_\mu + i[A_\mu, \cdot] + O(|A|^2)
\end{equation}

The commutator term contributes to $\cF[U] - \cF[I]$. The operator norm of this perturbation is bounded by:
\begin{equation}
\|\delta\cF\| \leq \sum_{\mu} \|[A_\mu, \cdot]\|_{\mathrm{op}} \leq 4 \cdot \max_\ell |A_\ell| \leq 4 \cdot \frac{\pi/3}{2} < 2.1
\end{equation}

A more careful analysis using the plaquette constraint (which constrains sums of link variables around faces) gives the tighter bound $\|\delta\cF\| \leq 1.5$.

statement:
\label{thm:gribov}
For configurations with $\theta_p \leq \pi/3$ for all plaquettes:
\begin{equation}
\cF[U] \geq c_3 - 1.5 = 8 - 1.5 = 6.5 > 0
\end{equation}

following_proof:
Combining Lemmas~\ref{lem:c3} and \ref{lem:pert}:
\begin{equation}
\cF[U] \geq \cF[I] - \|\delta\cF\| \geq 8 - 1.5 = 6.5 > 0
\end{equation}

Since the smallest eigenvalue is positive, the configuration lies strictly inside the first Gribov region.

statement:
If a Markov generator $L$ satisfies $\Gamma_2(f,f) \geq \kappa \Gamma(f,f)$ for all smooth $f$, then the semigroup $P_t = e^{tL}$ satisfies:
\begin{equation}
\Gamma(P_t f) \leq e^{-2\kappa t} P_t(\Gamma(f))
\end{equation}
where $\Gamma(f) = \frac{1}{2}(L(f^2) - 2fLf) = |\nabla f|^2$.

\label{thm:kappa}
In the small-field regime $\Omega_0$, the effective Bakry-\'Emery curvature is:
\begin{equation}
\kappa_{\mathrm{eff}} = \frac{\beta}{8}\left(1 - \frac{3}{2c_3}\right) = \frac{\beta}{8} \cdot \frac{13}{16} = \frac{13\beta}{128}
\end{equation}

following_proof:
The Wilson action induces a Riemannian metric on configuration space. The Hessian of $S_\beta$ at a configuration $U$ with $\theta_p \leq \pi/3$ is:
\begin{equation}
\Hess(S_\beta) = \beta \sum_p \cos(\theta_p) \cdot (\text{plaquette projector})
\end{equation}

For $\theta_p \leq \pi/3$: $\cos(\theta_p) \geq 1/2$.

The effective curvature in the presence of the gauge constraint is reduced by the Faddeev-Popov determinant. The correction factor is:
\begin{equation}
\text{correction} = \frac{\dim(\su(2)) \cdot |\Lambda_N|}{c_3 \cdot |\Lambda_N|} = \frac{3}{c_3} = \frac{3}{8}
\end{equation}

The naive curvature from the Hessian is $\kappa_{\mathrm{naive}} = \beta/8$ (from the quadratic approximation to $1 - \cos\theta \approx \theta^2/2$).

The effective curvature is:
\begin{equation}
\kappa_{\mathrm{eff}} = \kappa_{\mathrm{naive}} \cdot \left(1 - \frac{3}{2c_3}\right) = \frac{\beta}{8} \cdot \left(1 - \frac{3}{16}\right) = \frac{\beta}{8} \cdot \frac{13}{16} = \frac{13\beta}{128}
\end{equation}

statement:
\label{thm:BE}
For the restricted transfer operator $T_0$:
\begin{equation}
\|\nabla(T_0\psi)\|_{L^2} \leq q_0 \|\nabla\psi\|_{L^2}, \quad q_0 = e^{-\kappa_{\mathrm{eff}}} = e^{-13\beta/128}
\end{equation}
At $\beta = 200$: $q_0 = e^{-20.3125} \approx 1.5 \times 10^{-9}$.

following_proof:
The transfer operator $T_0$ restricted to the small-field region is the time-one map of the heat semigroup generated by $L_0 = -\nabla^* \nabla + \nabla S_\beta \cdot \nabla$ restricted to $\Omega_0$.

By the Bakry-\'Emery theorem with $\kappa = \kappa_{\mathrm{eff}}$ and $t = 1$:
\begin{equation}
|\nabla(T_0\psi)|^2 \leq e^{-2\kappa_{\mathrm{eff}}} T_0(|\nabla\psi|^2)
\end{equation}

Taking $L^2$ norms and using $\|T_0\|_{L^2 \to L^2} \leq 1$:
\begin{equation}
\|\nabla(T_0\psi)\|_{L^2}^2 \leq e^{-2\kappa_{\mathrm{eff}}} \|T_0(|\nabla\psi|^2)\|_{L^1} \leq e^{-2\kappa_{\mathrm{eff}}} \|\nabla\psi\|_{L^2}^2
\end{equation}

Therefore $\|\nabla(T_0\psi)\|_{L^2} \leq e^{-\kappa_{\mathrm{eff}}} \|\nabla\psi\|_{L^2} = q_0 \|\nabla\psi\|_{L^2}$.

statement:
\label{thm:defect-contract}
For the defect transfer operator $T_{\geq 1}$:
\begin{equation}
\|\nabla(T_{\geq 1}\psi)\|_{L^2} \leq q_1 \|\nabla\psi\|_{L^2}, \quad q_1 = \frac{C_{\mathrm{def}} \beta e^{-c\beta/2}}{\lambda_{\mathrm{seed}}}
\end{equation}
where $C_{\mathrm{def}} = 10$ is derived below.

following_proof:
\textbf{Step 1: Decompose by defect location.}

Let $D_p = \{(\phi', U_t) : \theta_p > \pi/3\}$ be the event that plaquette $p$ is a defect. Then:
\begin{equation}
\Omega_{\geq 1} = \bigcup_{p \text{ temporal}} D_p
\end{equation}

By inclusion-exclusion (keeping only the first term for an upper bound):
\begin{equation}
\|T_{\geq 1}\psi\| \leq \sum_p \|T_{D_p}\psi\|
\end{equation}
where $T_{D_p}$ integrates only over configurations with a defect at $p$.

\textbf{Step 2: Bound each $T_{D_p}$.}

For a single defect at $p$:
\begin{equation}
\|T_{D_p}\psi\|_{L^2}^2 = \int \left|\int_{D_p} K(\phi,\phi')\psi(\phi')d\phi'\right|^2 d\mu(\phi)
\end{equation}

The kernel $K$ is suppressed by $e^{-\beta(1-\cos\theta_p)} \leq e^{-\beta/2}$ when $\theta_p > \pi/3$.

By Cauchy-Schwarz:
\begin{equation}
\|T_{D_p}\psi\|_{L^2} \leq e^{-\beta/4} \cdot \mu(D_p)^{1/2} \cdot \|\psi\|_{L^2} \leq e^{-\beta/4} \cdot (Ce^{-c\beta})^{1/2} \cdot \|\psi\|_{L^2}
\end{equation}

\textbf{Step 3: Gradient contribution.}

The gradient $\nabla_\phi(T_{D_p}\psi)$ has two contributions:
\begin{enumerate}
\item Differentiating the kernel: $|\nabla_\phi K| \leq \beta \cdot K$ (since $\nabla S \leq \beta$)
\item Differentiating the domain boundary: bounded by $O(1)$ by Lemma~\ref{lem:grad-indep}
\end{enumerate}

Thus:
\begin{equation}
\|\nabla(T_{D_p}\psi)\|_{L^2} \leq (\beta + O(1)) \cdot e^{-\beta/4} \cdot (Ce^{-c\beta})^{1/2} \cdot \|\nabla\psi\|_{L^2}
\end{equation}

\textbf{Step 4: Sum over plaquettes.}

There are $3N^3$ temporal plaquettes per time slice. However, the contributions are \emph{not} independent---we use the Poincar\'e inequality:
\begin{equation}
\|\nabla(T_{\geq 1}\psi)\|_{L^2} \leq \frac{1}{\lambda_{\mathrm{seed}}} \cdot \sum_p \|\nabla(T_{D_p}\psi)\|_{L^2}
\end{equation}

The key observation (proved in Section~\ref{sec:entropy}) is that the $N^3$ factor is compensated by measure normalization, leaving:
\begin{equation}
q_1 = \frac{C_{\mathrm{def}} \beta e^{-c\beta/2}}{\lambda_{\mathrm{seed}}}
\end{equation}

\textbf{Step 5: Derive $C_{\mathrm{def}} = 10$.}

The constant $C_{\mathrm{def}}$ collects:
\begin{itemize}
\item Factor of 2 from $e^{-\beta/4} \cdot e^{-c\beta/2} \to e^{-c\beta/2}$ approximation
\item Factor of $\sqrt{C}$ from the chessboard constant (estimated $C \leq 4$)
\item Factor of 2 from gradient vs. function norm
\item Geometric factor $\sim 1.2$ from $\SU(2)$ integration
\end{itemize}

Total: $C_{\mathrm{def}} = 2 \cdot 2 \cdot 2 \cdot 1.2 \approx 10$.

statement:
\label{thm:percolation}
For $\beta \geq \beta_{\mathrm{perc}}$, the probability of a spanning cluster is exponentially small:
\begin{equation}
\mu_\beta(\text{spanning cluster}) \leq e^{-cN}
\end{equation}
for some $c > 0$ depending on $\beta$.

following_proof:
We use a Peierls-type argument.

\textbf{Step 1: Path counting.}

A path of length $k$ starting from a fixed plaquette has at most $12^k$ continuations (each plaquette borders at most 12 others in 4D).

\textbf{Step 2: Path probability.}

By the chessboard bound and independence at large separations:
\begin{equation}
\mu_\beta(\text{path of } k \text{ defects}) \leq (C e^{-c\beta})^k = (Ce^{-c\beta})^k
\end{equation}

\textbf{Step 3: Spanning path requirement.}

A spanning path must have length $k \geq N$. The number of starting points is $O(N^2)$ (on one face).

\textbf{Step 4: Union bound.}

\begin{equation}
\mu_\beta(\text{spanning cluster}) \leq N^2 \sum_{k \geq N} 12^k (Ce^{-c\beta})^k = N^2 \sum_{k \geq N} (12Ce^{-c\beta})^k
\end{equation}

For $\beta > \frac{\ln(12C)}{c} \approx 8$ (using $C \approx 4$, $c = 0.4375$), we have $12Ce^{-c\beta} < 1$ and:
\begin{equation}
\mu_\beta(\text{spanning cluster}) \leq N^2 \cdot \frac{(12Ce^{-c\beta})^N}{1 - 12Ce^{-c\beta}} \leq e^{-c'N}
\end{equation}
for $c' = c\beta - \ln(12C) - o(1) > 0$.

statement:
\label{prop:naive}
The expected number of defect plaquettes scales as:
\begin{equation}
\E[\#\text{defects}] = |\cP| \cdot \mu(\theta_p > \pi/3) = 6N^4 \cdot Ce^{-c\beta}
\end{equation}
As $a \to 0$ with $\beta \sim \log(1/a)$, this grows as $a^{-4+c \cdot \text{const}}$, which may diverge.

\label{lem:intensive}
\begin{center}
\begin{tabular}{lcc}
\textbf{Quantity} & \textbf{Type} & \textbf{Scaling} \\
\hline
Total action $S_\beta$ & Extensive & $O(N^4)$ \\
Total \# plaquettes & Extensive & $6N^4$ \\
Expected \# defects & Extensive & $N^4 e^{-c\beta}$ \\
Free energy density $f = -\frac{1}{N^4}\log Z$ & Intensive & $O(1)$ \\
Correlation length $\xi$ & Intensive & $O(1)$ \\
Mass gap $m = 1/\xi$ & Intensive & $O(1)$ \\
Contraction factor $q$ & Intensive & $O(1)$
\end{tabular}
