Hurst parameter $H$ is a centered Gaussian process
$B^H = (B^H_t)_{t \geq 0}$ with covariance
\begin{equation}\label{eq:fbm-cov}
  R_H(s,t)
  \;:=\;
  \E[B^H_s\,B^H_t]
  \;=\;
  \frac{1}{2}\bigl(|s|^{2H} + |t|^{2H} - |s-t|^{2H}\bigr).
\end{equation}

\label{cor:pd}
The kernel $\Psi_\gamma(\xi,\eta) = R_{\gamma/2}(|\xi|,|\eta|)$ is
positive definite on $\R$ for all $\gamma \in (0,2)$.

\label{prop:curvature}
For $f(x) = e^{i\xi x}$:
\begin{equation}\label{eq:curvature-fourier}
  \Gamma_{\gamma,2}(f,f)
  = |\xi|^{2\gamma}, \qquad
  \frac{\Gamma_{\gamma,2}(f,f)}{\Gamma_\gamma(f,f)}
  = |\xi|^\gamma.
\end{equation}
In particular, on Fourier modes the curvature ratio equals the
characteristic exponent.

