\label{thm:main}
Let $\gamma \in (1,2)$ and $p \in (1,\gamma)$.
There exists no quasi-Banach space $\mathcal{H}$ of
predictable integrands
$h : [0,T] \times \R \times \Omega \to \R$
satisfying all three of:
\begin{enumerate}[label=\textup{(A\arabic*)}]
\item \textup{(Homogeneity.)}
  $\|ch\|_{\mathcal{H}} = |c|\,\|h\|_{\mathcal{H}}$
  for all $c \in \R$, $h \in \mathcal{H}$.
\item \textup{(BR control.)}
  There exists $C > 0$ such that
  for all $h \in \mathcal{H}$,
  \begin{equation}\label{eq:BR-control}
    \E\!\int\!\!\int|h|^p\,\nu\,dt
    \;+\;
    \E\!\left[\left(\int\!\!\int|h|^2\,\nu\,dt
    \right)^{\!p/2}\right]
    < \infty.
  \end{equation}
\item \textup{(Contains the process.)}
  The constant-in-$t$ integrand $h(t,z) = z$ lies in
  $\mathcal{H}$.
\end{enumerate}
In particular, there is no $p$-homogeneous quasi-norm
on integrands that simultaneously contains $z$ and
yields a BDG-type equivalence
$\|\widetilde{\delta}(h)\|_{L^p}^p \asymp
\|h\|_{\mathcal{H}}^p$.

\label{prop:regular}
Let $h(t,z,\omega)$ satisfy
$|h(t,z,\omega)| \leq C(\omega)\,|z|^\beta$ for
$|z| \leq 1$, with $\beta > \gamma/p$.  Then
$h \in L^p(dt \otimes \nu \otimes dP)$ (provided
$C \in L^p(\Omega)$ and $h$ has suitable tail decay),
and the BDG upper bound
\begin{equation}\label{eq:BDG-regular}
  \|\widetilde{\delta}(h)\|_{L^p}
  \leq \tilde{C}_p\,\|h\|_{L^p(\nu \otimes dt \otimes dP)}
\end{equation}
holds.

\label{def:OCD}
Let $X$ be a square-integrable process with energy space~$\mathcal{H}_X$ and stochastic integral $\delta_X \colon \mathcal{H}_X \to L^2(\Omega)$. For $F \in L^2(\Omega)$, the \emph{operator--covariant derivative} $D_X F \in \mathcal{H}_X$ is the unique element satisfying
\begin{equation}\label{eq:adjoint}
\E[F \cdot \delta_X(u)] \;=\; \langle D_X F,\, u \rangle_{\mathcal{H}_X}
\quad \text{for all } u \in \mathcal{H}_X.
\end{equation}
The operator $D_X \colon L^2(\Omega) \to \mathcal{H}_X$ is called the \emph{operator--covariant derivative}.

\label{thm:CO}
Let $X$ be a square-integrable process with natural filtration $(\mathcal{F}_t^X)_{t \in [0,T]}$, energy space~$\mathcal{H}_X$, stochastic integral~$\delta_X$, predictable projection~$\Pi_X$, and operator--covariant derivative $D_X = \delta_X^*$. Assume:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \textup{Centered integrals:} $\E[\delta_X(u)] = 0$ for all $u \in \mathcal{H}_X$.
\item \textup{Isometry on predictable processes:} $\E[|\delta_X(u)|^2] = \|u\|_{\mathcal{H}_X}^2$ for predictable $u \in \mathcal{H}_X$.
\item \textup{Representation property:} Every $\mathcal{F}_T^X$-measurable $\tilde{F} \in L^2(\Omega)$ with $\E[\tilde{F}] = 0$ can be written as $\tilde{F} = \delta_X(v)$ for some predictable $v \in \mathcal{H}_X$.
\end{enumerate}
Then for all $\mathcal{F}_T^X$-measurable $F \in L^2(\Omega)$:
\begin{equation}\label{eq:CO_thm}
