The \textbf{stochastic Cauchy operator} is
\begin{equation}\label{eq:stoch-cauchy}
\mathcal{C}[F] := \delta_Z \, \Pi^{1,0} \, \Pi_{\cA} \, D_Z F
\end{equation}
where $D_Z$ is the operator derivative, $\Pi_{\cA}$ is the predictable projection, $\Pi^{1,0}$ is the holomorphic projection, and $\delta_Z = D_Z^*$ is the divergence.

\label{thm:intro-decomp}
Every $F \in L^2(\Omega)$ decomposes as
\begin{equation}
F = \E[F] + \mathcal{C}[F] + \overline{\mathcal{C}}[F]
\end{equation}
with $\mathcal{C}[F] \perp \overline{\mathcal{C}}[F]$ in $L^2(\Omega)$ when Tier 2 holds.

\label{thm:intro-energy}
For complex Brownian motion (Tier 2 holds):
\begin{equation}
\Var(F) = \E\left[\|\Pi^{1,0} \Pi_\cA D_Z F\|^2_{\HH_Z}\right] + \E\left[\|\Pi^{0,1} \Pi_\cA D_Z F\|^2_{\HH_Z}\right].
\end{equation}
For complex fBM with $H \neq 1/2$ (Tier 2 fails), covariance corrections appear (Section~\ref{sec:fbm}).

\label{thm:intro-conformal}
Let $\phi: D \to D'$ be a conformal map between simply connected domains. The stochastic Cauchy operator is conformally covariant: for $F = (f \circ \phi)(Z_{\tau_D})$ with $f$ analytic,
\begin{equation}
\mathcal{C}[F] = \int_0^{\tau_D} (f' \circ \phi)(Z_t) \cdot \phi'(Z_t) \, dZ_t
\end{equation}
which equals $\mathcal{C}[f(\tilde{Z}_{\tilde{\tau}})]$ in law under the conformal time change, where $\tilde{Z} = \phi(Z)$.

\label{def:operator_derivative}
Let $X$ be a centered Gaussian process with energy space $\HH_X$ and stochastic integral $\delta_X : \HH_X \to L^2(\Omega)$. The \textbf{operator derivative} $D_X F \in L^2(\Omega; \HH_X)$ is defined, when it exists, as the unique element satisfying
\begin{equation}\label{eq:riesz}
\E[F \cdot \delta_X(u)] = \E[\inner{D_X F}{u}_{\HH_X}] \quad \text{for all } u \in \HH_X.
\end{equation}

The \textbf{predictable projection} $\Pi_\cA : L^2(\Omega; \HH_X) \to L^2(\Omega; \HH_X)$ is
\begin{equation}
(\Pi_\cA u)_t := \E[u_t \,|\, \cF_t].
\end{equation}

\label{thm:factorization}
For $F \in \Dom(D_X)$:
\begin{equation}\label{eq:factorization}
F - \E[F] = \delta_X(\Pi_\cA D_X F).
\end{equation}

\label{prop:cylindrical}
Let $X$ be a Gaussian process with covariance $R(s,t) = \E[X_s X_t]$. For a cylindrical functional $F = f(X_{t_1}, \ldots, X_{t_n})$ with $f \in C^\infty_b(\R^n)$:
\begin{equation}\label{eq:cylindrical}
D_X F = \sum_{i=1}^n \partial_i f(X_{t_1}, \ldots, X_{t_n}) \cdot k_{t_i}
\end{equation}
where $k_t \in \HH_X$ is the representer of evaluation: $\inner{k_t}{h}_{\HH_X} = h(t)$.

following_proof:
By the Gaussian integration-by-parts formula: for $F = f(X_{t_1}, \ldots, X_{t_n})$ and deterministic $u \in \HH_X$,
\begin{equation}
\E[F \cdot \delta_X(u)] = \sum_{i=1}^n \E[\partial_i f(X_{t_1}, \ldots, X_{t_n})] \cdot \inner{k_{t_i}}{u}_{\HH_X}.
\end{equation}
This is the defining equation \eqref{eq:riesz} with $D_X F$ given by \eqref{eq:cylindrical}.

