For $F \in \Dom(D_Z)$, define
\begin{align}
\mathcal{D}_z F &:= \frac{1}{2}(D_X F - i D_Y F) \in L^2(\Omega; \HH_Z), \\
\mathcal{D}_{\bar{z}} F &:= \frac{1}{2}(D_X F + i D_Y F) \in L^2(\Omega; \HH_Z).
\end{align}

$F \in L^2(\Omega; \C)$ is \textbf{operator-holomorphic} (or \textbf{stochastically analytic}) if
\begin{equation}
\mathcal{D}_{\bar{z}} F = 0 \quad \text{in } L^2(\Omega; \HH_Z).
\end{equation}

\label{prop:CR}
Let $F = U + iV$ with $U, V$ real-valued. Then $\mathcal{D}_{\bar{z}} F = 0$ iff
\begin{align}
D_X U &= D_Y V, \label{eq:CR1}\\
D_Y U &= -D_X V. \label{eq:CR2}
\end{align}

following_proof:
Compute:
\begin{align}
\mathcal{D}_{\bar{z}} F &= \frac{1}{2}(D_X + i D_Y)(U + iV) \\
&= \frac{1}{2}\bigl[(D_X U - D_Y V) + i(D_Y U + D_X V)\bigr].
\end{align}
This vanishes iff both real and imaginary parts vanish, giving \eqref{eq:CR1}--\eqref{eq:CR2}.

For $u \in \HH^{1,0}$ and $v \in \HH^{0,1}$, write $u = (h, -ih)$ and $v = (k, ik)$ for some $h, k \in \HH_X = \HH_Y$. Then
