\textbf{Step 1: Compute $D_X F$ and $D_Y F$ using the cylindrical formula.}

Write $f(z) = f(x + iy)$ and consider $F = f(Z_T) = f(X_T + iY_T)$ as a function of $(X_T, Y_T)$.

By Proposition~\ref{prop:cylindrical} (the explicit formula for cylindricals):
\begin{align}
D_X F &= \frac{\partial f}{\partial x}(X_T + iY_T) \cdot k_T, \\
D_Y F &= \frac{\partial f}{\partial y}(X_T + iY_T) \cdot k_T,
\end{align}
where $k_T \in \HH_X$ (resp.\ $\HH_Y$) is the evaluation representer at time $T$.

\textbf{Step 2: Apply the classical Cauchy-Riemann equations.}

Since $f$ is analytic, it satisfies the classical Cauchy-Riemann equations:
\begin{equation}
\frac{\partial f}{\partial \bar{z}} = \frac{1}{2}\left(\frac{\partial f}{\partial x} + i\frac{\partial f}{\partial y}\right) = 0.
\end{equation}

Equivalently: $\frac{\partial f}{\partial y} = i \frac{\partial f}{\partial x}$.

\textbf{Step 3: Compute $\mathcal{D}_{\bar{z}} F$.}

\begin{align}
\mathcal{D}_{\bar{z}} F &= \frac{1}{2}(D_X F + i D_Y F) \\
&= \frac{1}{2}\left(\frac{\partial f}{\partial x}(Z_T) + i \frac{\partial f}{\partial y}(Z_T)\right) \cdot k_T \\
&= \frac{\partial f}{\partial \bar{z}}(Z_T) \cdot k_T \\
&= 0.
\end{align}

\textbf{Step 4: Conclude (b) and (c).}

From $D_Y F = i D_X F$ (by Cauchy-Riemann), we have:
\begin{equation}
D_Z F = (D_X F, D_Y F) = (D_X F, i D_X F) = f'(Z_T) \cdot (k_T, ik_T).
\end{equation}

The element $(k_T, ik_T)$ lies in $\HH^{1,0}$:
\begin{equation}
\Pi^{0,1}(k_T, ik_T) = \frac{1}{2}(k_T + i \cdot ik_T) = \frac{1}{2}(k_T - k_T) = 0.
\end{equation}

Therefore $D_Z F \in \HH^{1,0}$, so $\Pi^{0,1} D_Z F = 0$, hence $\overline{\mathcal{C}}[F] = \delta_Z(\Pi^{0,1} \Pi_\cA D_Z F) = 0$.

By Theorem~\ref{thm:cauchy-decomp}: $F - \E[F] = \mathcal{C}[F] + \overline{\mathcal{C}}[F] = \mathcal{C}[F]$.

