f(Z_T) = \E[f(Z_T)] + \delta_Z(\Pi_\cA(f'(Z_T) \cdot (k_T, ik_T))).
\end{equation}

For complex Brownian motion, where $k_T = \mathbf{1}_{[0,T]}$ and the predictable projection of $f'(Z_T)$ is $f'(Z_t)$:
\begin{equation}
f(Z_T) = \E[f(Z_T)] + \int_0^T f'(Z_t) \, dZ_t.
\end{equation}

\begin{equation}
f(Z_\tau) = \E[f(Z_\tau)] + \int_0^\tau f'(Z_t) \, dZ_t
\end{equation}
and when Tier 2 holds:
\begin{equation}
\Var(f(Z_\tau)) = \E\left[\int_0^\tau |f'(Z_t)|^2 \, dt\right].
\end{equation}

\label{cor:fbm-cauchy}
For $f$ analytic with polynomial growth:
\begin{equation}
f(Z_T) = \E[f(Z_T)] + \delta_Z^H(\Pi_\cA(f'(Z_T) \cdot (k_T^H, ik_T^H)))
\end{equation}
where $\delta_Z^H$ is the fBM divergence and $k_T^H$ is the fBM evaluation representer.

\label{thm:fbm-energy}
For $F = f(Z_T)$ with $f$ analytic:
\begin{equation}
\Var(f(Z_T)) = \E\left[\iint_{[0,T]^2} \Pi_\cA(f'(Z_T))_s \cdot \overline{\Pi_\cA(f'(Z_T))_t} \, d\tilde{R}_H(s,t)\right]
\end{equation}
where $d\tilde{R}_H(s,t) = dR_H(s,t) + dR_H(s,t)$ accounts for both real and imaginary components.

\label{prop:fbm-power}
For $F = Z_T^n$ and complex fBM with parameter $H$:
\begin{equation}
\E[|Z_T^n|^2] = n^2 \iint_{[0,T]^2} \E\left[\Pi_\cA(Z_T^{n-1})_s \cdot \overline{\Pi_\cA(Z_T^{n-1})_t}\right] d\tilde{R}_H(s,t).
\end{equation}

For $H = 1/2$, $\E[B_T | \cF_s] = B_s$ (martingale property) and $dR_{1/2}(s,t) = ds \, \delta(s-t)$, recovering
\begin{equation}
\E[|Z_T^2|^2] = 4 \int_0^T \E[|Z_s|^2] \, ds = 4 \int_0^T s \, ds = 2T^2.
\end{equation}
For $H \neq 1/2$, the double integral structure reflects non-trivial long-range dependence.

\label{prop:fbm-exp}
For $F = e^{Z_T}$ and complex fBM:
\begin{equation}
\E[e^{Z_T}] = \exp\left(\frac{1}{2}T^{2H} - \frac{1}{2}T^{2H}\right) = 1
\end{equation}
and
\begin{equation}
\Var(e^{Z_T}) = \iint_{[0,T]^2} \E\left[\Pi_\cA(e^{Z_T})_s \cdot \overline{\Pi_\cA(e^{Z_T})_t}\right] d\tilde{R}_H(s,t).
\end{equation}

\label{prop:fbm-not-orthog}
For complex fBM with $H \neq 1/2$ and $F = |Z_T|^2$:
\begin{equation}
\E[\mathcal{C}[F] \cdot \overline{\overline{\mathcal{C}}[F]}] = \iint_{[0,T]^2} \E\left[\bar{Z}_s Z_t\right] dR_H(s,t) \neq 0 \quad \text{in general}.
\end{equation}

\label{thm:levy-conformal}
Let $\phi: D \to D'$ be a conformal map between simply connected domains, and let $Z_t$ be complex Brownian motion started at $z_0 \in D$. Define the time change
\begin{equation}
\sigma(t) := \int_0^t |\phi'(Z_s)|^2 \, ds
\end{equation}
and let $\tau_D := \inf\{t : Z_t \notin D\}$. Then:
\begin{equation}
\tilde{Z}_{\sigma(t)} := \phi(Z_t), \quad t \in [0, \tau_D]
\end{equation}
is complex Brownian motion in $D'$ started at $\phi(z_0)$, run until time $\sigma(\tau_D)$.

\label{prop:conformal-D}
Let $\phi: D \to D'$ be conformal, $F = f(Z_{\tau_D})$ for $f$ analytic on $\bar{D}'$, and $\tilde{F} = f(\tilde{Z}_{\sigma(\tau_D)}) = f(\phi(Z_{\tau_D}))$. Then:
\begin{equation}
D_Z \tilde{F} = (f' \circ \phi)(Z_{\tau_D}) \cdot \phi'(Z_{\tau_D}) \cdot (k_{\tau_D}, ik_{\tau_D}).
\end{equation}

following_proof:
By the chain rule (Tier 3):
\begin{equation}
D_Z(f \circ \phi)(Z_{\tau_D}) = (f' \circ \phi)(Z_{\tau_D}) \cdot D_Z(\phi(Z_{\tau_D})).
\end{equation}
Since $\phi$ is analytic, Theorem~\ref{thm:analytic-holo} gives $D_Z \phi(Z_{\tau_D}) = \phi'(Z_{\tau_D}) \cdot (k_{\tau_D}, ik_{\tau_D})$.

statement:
\label{thm:conformal-C}
Let $\phi: D \to D'$ be conformal, $\tau = \tau_D$ the exit time from $D$, and $f$ analytic on $\bar{D}'$. Define:
\begin{itemize}
\item $F = (f \circ \phi)(Z_\tau)$ --- functional of $Z$ in domain $D$
\item $\tilde{F} = f(\tilde{Z}_{\tilde{\tau}})$ --- corresponding functional of $\tilde{Z}$ in domain $D'$
\end{itemize}
Then the Cauchy representations are related by:
\begin{equation}
\mathcal{C}[F] = \int_0^\tau (f' \circ \phi)(Z_t) \cdot \phi'(Z_t) \, dZ_t
\end{equation}
and
\begin{equation}
\mathcal{C}[\tilde{F}] = \int_0^{\tilde{\tau}} f'(\tilde{Z}_s) \, d\tilde{Z}_s.
\end{equation}
These are equal in law under the time change $s = \sigma(t)$.

following_proof:
For $F = (f \circ \phi)(Z_\tau)$, Corollary~\ref{cor:cauchy-rep} gives:
\begin{equation}
\mathcal{C}[F] = \int_0^\tau [(f \circ \phi)'](Z_t) \, dZ_t = \int_0^\tau (f' \circ \phi)(Z_t) \cdot \phi'(Z_t) \, dZ_t.
\end{equation}

For the transformed process, $\tilde{F} = f(\tilde{Z}_{\tilde{\tau}})$ where $\tilde{Z}_s = \phi(Z_{\sigma^{-1}(s)})$:
\begin{equation}
\mathcal{C}[\tilde{F}] = \int_0^{\tilde{\tau}} f'(\tilde{Z}_s) \, d\tilde{Z}_s.
\end{equation}

Under the time change $s = \sigma(t)$, we have $d\tilde{Z}_s = \phi'(Z_t) \, dZ_t$ (by the conformal map formula for Brownian motion), so:
\begin{align}
\int_0^{\tilde{\tau}} f'(\tilde{Z}_s) \, d\tilde{Z}_s &= \int_0^\tau f'(\phi(Z_t)) \cdot \phi'(Z_t) \, dZ_t \\
&= \int_0^\tau (f' \circ \phi)(Z_t) \cdot \phi'(Z_t) \, dZ_t.
\end{align}
This matches $\mathcal{C}[F]$.

statement:
\label{cor:conformal-energy}
For $f$ analytic on $\bar{D}'$ and $\phi: D \to D'$ conformal:
\begin{equation}
\E\left[\int_0^{\tau_D} |(f' \circ \phi)(Z_t)|^2 |\phi'(Z_t)|^2 \, dt\right] = \E\left[\int_0^{\tau_{D'}} |f'(\tilde{Z}_s)|^2 \, ds\right].
\end{equation}

