\label{thm:antisym}
The curvature error decomposes as $\cK=\cK^{\mathrm{Chr}}+\cK^{\mathrm{met}}$:

\begin{enumerate}[label=(\alph*)]
\item \textbf{Christoffel correction} (antisymmetric, $O(\theta)$):
\begin{equation}\label{eq:Chr}
\cK^{\mathrm{Chr}}_{\ell\ell',ab}
=-\frac{1}{2}\sum_{p:\ell,\ell'\in p}s_\ell(p)s_{\ell'}(p)\,
\epsilon_{cab}\,g(\theta_p)\,\hat\theta_p^c,
\end{equation}
where $g(\theta)=(\theta\cos\theta-\sin\theta)/(\theta\sin\theta)$,
$\hat\theta_p^c$ is the plaquette holonomy direction, and $\epsilon_{cab}$ is the
$\su(2)$ structure constant.  This satisfies
\begin{equation}\label{eq:antisym}
\cK^{\mathrm{Chr}}_{\ell\ell',ab}+\cK^{\mathrm{Chr}}_{\ell'\ell,ba}=0.
\end{equation}
Therefore, for all $v$:
\begin{equation}\label{eq:kill}
\boxed{\sum_{\ell,a,\ell',b}\cK^{\mathrm{Chr}}_{\ell\ell',ab}\,v_\ell^a v_{\ell'}^b=0.}
\end{equation}

\item \textbf{Metric correction} (symmetric, $O(\theta^2)$):
\begin{equation}\label{eq:met}
\cK^{\mathrm{met}}_{\ell\ell',ab}
=\bigl(\cos\theta_p-1\bigr)\sum_{p:\ell,\ell'\in p}s_\ell(p)s_{\ell'}(p)\,\delta_{ab}
+R_{\ell\ell',ab},
\end{equation}
where $R$ collects BCH commutator and exponential-map Jacobian remainders satisfying
$\norm{R}_\op\le C'\theta_*^2$ on $\{\max_p\theta_p\le\theta_*\}$.
\end{enumerate}

