\label{lem:antisym}
The curvature error $\cK$ in~\eqref{eq:hess-decomp} decomposes as
$\cK=\cK^{\mathrm{Chr}}+\cK^{\mathrm{met}}$ with:

\begin{enumerate}[label=(\alph*)]
\item \textbf{Christoffel correction} (antisymmetric):
\begin{equation}
\cK^{\mathrm{Chr}}_{\ell\ell',ab}
=-\frac{1}{2}\sum_{p:\ell,\ell'\in p}s_\ell(p)s_{\ell'}(p)\,\epsilon_{cab}\,
g(\theta_p)\,\hat\theta_p^c,
\end{equation}
where $g(\theta)=(\theta\cos\theta-\sin\theta)/(\theta\sin\theta)$,
$\hat\theta_p^c$ is the plaquette holonomy direction, and $\epsilon_{cab}$ is the
$\su(2)$ structure constant.  This correction satisfies
\begin{equation}\label{eq:antisym}
\cK^{\mathrm{Chr}}_{\ell\ell',ab}+\cK^{\mathrm{Chr}}_{\ell'\ell,ba}=0,
\end{equation}
and therefore
\begin{equation}\label{eq:antisym-kill}
\sum_{\ell,a,\ell',b}\cK^{\mathrm{Chr}}_{\ell\ell',ab}\,v_\ell^a v_{\ell'}^b=0
\quad\text{for all }v.
\end{equation}

\item \textbf{Metric correction} (symmetric, $O(\theta^2)$):
\begin{equation}
\cK^{\mathrm{met}}_{\ell\ell',ab}
=(\cos\theta_p-1)\sum_{p:\ell,\ell'\in p}s_\ell(p)s_{\ell'}(p)\,\delta_{ab}
+O(\theta_*^2)\,\delta_{ab}.
\end{equation}
\end{enumerate}

