\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
