\begin{tabular}{llll}
\toprule
\textbf{Region} & \textbf{Method} & \textbf{Bound} & \textbf{Section}\\
\midrule
Small field & Cluster expansion & $O(g^4)$ (activity $O(g^2)$) & \ref{sec:cluster}\\
Large field & Peierls/chessboard & $O(e^{-c\beta})$ &
\ref{sec:largefield}\\
