\label{thm:C-prime-su2}
For $\SU(2)$ and the $2^4$ block with boundary condition $\eta$
such that $\max_p\theta_p \leq \theta_*$:
\begin{equation}
\cK^{\mathrm{met}}_{\ell\ell',ab}
= \bigl(\tfrac{\sin\theta_p}{\theta_p} - 1\bigr)
  H_{\ell\ell'}\,\delta_{ab}
+ h(\theta_p)\,H^{(p)}_{\ell\ell'}\,
  (\hat\Theta_p^a\hat\Theta_p^b - \tfrac{1}{3}\delta_{ab})
+ O(\theta_*^2)\delta_{ab},
\end{equation}
where the spin-$2$ coefficient is smooth, vanishing at
$\theta = 0$, and $O(\theta^2)$, and the $O(\theta_*^2)$
remainder includes the BCH second-order and Jacobian corrections.

The effective bound on the good region $\Omega_g(\theta_*)$ is:
\begin{equation}
\cK^{\mathrm{met}} \succeq
\bigl(\tfrac{\sin\theta_*}{\theta_*} - 1\bigr)H_{yy}\otimes I_3
- C'\theta_*^2\,I
\end{equation}
with
\begin{equation}\label{eq:C-prime-explicit}
C' = C_2^{\max}\,n_p + C_{\mathrm{BCH}} + C_{\mathrm{Jac}},
\end{equation}
where:
\begin{enumerate}[label=(\roman*)]
\item $C_2^{\max} = \max_{\hat\Theta}|h(\theta_*)|
  \leq \frac{2}{3}\theta_*$ is the spin-$2$ channel bound (using
  $|h(\theta)| \leq \frac{2}{3}|\theta|$ for
  $|\theta| \leq \pi/2$);
\item $n_p = 6$ is the maximum number of plaquettes per edge;
\item $C_{\mathrm{BCH}} \leq \frac{1}{12}\cdot 6 \cdot N_{\mathrm{pair}} \cdot \theta_*^2$
  accounts for the symmetric second-order BCH terms, with
  $N_{\mathrm{pair}}$ the number of adjacent link pairs per
  plaquette;
\item $C_{\mathrm{Jac}} \leq \frac{1}{6}\cdot 6$ accounts for
  the exponential map Jacobian.
\end{enumerate}

For $\theta_* \leq \pi/4$: $C' \leq 4 + \frac{1}{12}\cdot 72 + 1
= 11$. (This is a crude upper bound; the actual value is smaller
because the spin-$2$ and Jacobian terms partially cancel, and
the maximum is not achieved simultaneously on all plaquettes.)

\label{thm:curvature-SUN}
For $\SU(N)$ lattice gauge theory on the $2^4$ block, with
boundary condition $\eta$ such that $\max_p \theta_p \leq \theta_*$:
\begin{equation}\label{eq:kappa-SUN}
\kappa_B^{(N)} = \frac{N}{4}
+ \beta\bigl(\cos(\theta_*)\,\lambda_{\min}^{(N)}
- C'_N\,\theta_*^2\bigr)
\end{equation}
where:
\begin{enumerate}[label=(\roman*)]
\item $N/4$ is the Ricci curvature of $\SU(N)$ (increasing with $N$).
\item $\lambda_{\min}^{(N)}$ is the smallest eigenvalue of the
  physical Hessian for $\SU(N)$, equal to $\lambda_{\min}^{(2)}
  = 0.6893$ (the scalar Hessian is independent of $N$; the color
  structure is diagonal in the abelian approximation).
\item $C'_N \leq C'_2 + C'_d(N)$ where $C'_d(N) = O(N)$ accounts
