\label{lem:cap-regularity}
Let $u(t)$ be a smooth solution to the Navier-Stokes equations on $[0, T)$. Then:

\begin{enumerate}[label=(\roman*)]
\item Each $E_j(t)$ is absolutely continuous on $[0, T)$.

\item $\Emax(t)$ is absolutely continuous on $[0, T)$.

\item $\Emax(t)$ is differentiable at all but countably many times $t \in [0, T)$.

\item At points of differentiability:
\begin{equation}\label{eq:Emax-deriv}
\frac{d\Emax}{dt} = \frac{dE_{j^*(t)}}{dt} = -2\nu D_{j^*} + T_{j^*}
\end{equation}
where $D_{j^*} = \|u_{j^*}\|_{\Hdot{3/2}}^2$ and $T_{j^*} = \sum_{k,\ell} T_{k\ell}^{j^*}$ is the total nonlinear transfer into cap $j^*$.
\end{enumerate}

\label{lem:Emax-ineq}
For smooth NS solutions, the upper Dini derivative satisfies:
\begin{equation}\label{eq:Emax-Dini}
D^+ \Emax \leq -2\nu \Dmax + C_* \theta_0 E^{1/2} D^{1/2} + C_{adj} \eps^{1/2} E^{1/2} D^{1/2}
\end{equation}
where:
\begin{itemize}
\item $\Dmax = D_{j^*}$ is the dissipation in the dominant cap
\item $\eps = 1 - \rho = 1 - \Emax/E$ is the non-concentration parameter
\item $C_*$ depends on Sobolev constants
\item $C_{adj}$ accounts for adjacent cap interactions
\end{itemize}

Under concentration ($\rho \geq 1 - \eps_*$):
\begin{equation}\label{eq:Emax-concentrated}
D^+ \Emax \leq -2\nu(1-\eps_*) D + C(\theta_0 + \eps_*^{1/2}) E^{1/2} D^{1/2}
\end{equation}

following_proof:
From Lemma~\ref{lem:cap-regularity}(iv):
\[
\frac{dE_{j^*}}{dt} = -2\nu D_{j^*} + T_{j^*}
\]

The transfer term decomposes as:
\[
T_{j^*} = T_{j^* j^*}^{j^*} + \sum_{k \neq j^*} (T_{j^* k}^{j^*} + T_{k j^*}^{j^*}) + \sum_{k,\ell \neq j^*} T_{k\ell}^{j^*}
\]

\textbf{Bound on $T_{j^* j^*}^{j^*}$ (self-interaction):}

By cone depletion (Proposition in main paper):
\[
|T_{j^* j^*}^{j^*}| \leq C_* \theta_0 E_{j^*} D_{j^*}^{1/2} \leq C_* \theta_0 E D^{1/2}
\]

\textbf{Bound on cross-terms $T_{j^* k}^{j^*}$:}

For $k$ adjacent to $j^*$:
\[
|T_{j^* k}^{j^*}| \leq C E_{j^*}^{1/2} E_k^{1/2} (D_{j^*}^{1/2} + D_k^{1/2})
\]

Summing over $O(1)$ adjacent caps with $E_k \leq \eps E$:
\[
\sum_{k \text{ adj}} |T_{j^* k}^{j^*}| \leq C' \eps^{1/2} E D^{1/2}
\]

For $k$ non-adjacent: $T_{j^* k}^{j^*} = 0$ by Minkowski sum geometry.

\textbf{Bound on $T_{k\ell}^{j^*}$ (external interactions):}

These require $j^* \in \Omega_k \oplus \Omega_\ell$. With concentration, $\sum_{k \neq j^*} E_k \leq \eps E$:
\[
\sum_{k,\ell \neq j^*} |T_{k\ell}^{j^*}| \leq C'' \eps E D^{1/2}
\]

\textbf{Combining:}
\[
T_{j^*} \leq C_* \theta_0 E D^{1/2} + C' \eps^{1/2} E D^{1/2} + C'' \eps E D^{1/2}
\]

For $\eps \leq \eps_*$ small:
\[
T_{j^*} \leq C(\theta_0 + \eps^{1/2}) E D^{1/2}
\]

Under concentration, $D_{j^*} \geq (1-\eps) D \geq (1-\eps_*) D$, so:
\[
D^+ \Emax \leq -2\nu(1-\eps_*) D + C(\theta_0 + \eps_*^{1/2}) E^{1/2} D^{1/2}
\]

statement:
\label{thm:non-conc-bound}
Suppose $\rho(t) \leq 1 - \eps_*$ for all $t \in [0, T]$. Then:

\textbf{(a) Instantaneous bound:}
\[
|\mathcal{T}(t)| \leq C E(t) D(t)^{1/2}
\]
This is the standard bound with no improvement.

\textbf{(b) Time-averaged bound:}
\[
\frac{1}{T} \int_0^T |\mathcal{T}(t)| \, dt \leq (1 - \delta(\eps_*)) \nu \cdot \frac{1}{T} \int_0^T D(t) \, dt + R(E_0, T)
\]
where $\delta(\eps_*) > 0$ depends on the non-concentration parameter and $R$ is a remainder depending on initial energy.

Non-concentration ($\rho \leq 1 - \eps_*$) does not by itself prevent blow-up. The spread energy could still cascade to high frequencies.

What non-concentration DOES give:
\begin{enumerate}
\item A lower bound on the spread functional $\mathcal{A} \geq c(\eps_*) E^2$
\item Constraints on how energy can flow between caps
\item The solution is ``generic'' (not in the special concentrated regime)
\end{enumerate}

The blow-up prevention comes from the COMBINATION:
\begin{itemize}
\item If concentrated: dichotomy prevents blow-up
\item If not concentrated: solution cannot transition to concentration fast enough to enable blow-up
\end{itemize}

\label{lem:almost-helical-trilin}
For $\eps$-helical $u = u^+ + u^-$ with $\|u^-\|_{\Hdot{1/2}} \leq \eps \|u\|_{\Hdot{1/2}}$:
\[
|\mathcal{T}(u)| \leq C \eps \|u\|_{\Hdot{1/2}}^2 \|u\|_{\Hdot{3/2}}
\]

\label{def:levy-driver}
The \emph{L\'evy driver} is
\begin{equation}\label{eq:levy-driver}
  L_t := \sigma W_t + \int_0^t\!\!\int_\R z\,\Ntilde(ds,dz),
  \qquad \sigma \geq 0,
\end{equation}
where the integral converges in $L^p$ for $p \in (1,\gamma)$ when
$\nu$ is the measure of a symmetric $\gamma$-stable process
($\gamma \in (1,2)$), and in $L^2$ when
$\int |z|^2\,\nu(dz) < \infty$.

\label{def:VL}
Let $K : [0,T]^2 \to \R$ be a causal kernel ($K(t,s) = 0$ for
$s > t$). The \emph{Volterra--L\'evy process} is
\begin{equation}\label{eq:VL}
  V_t := \int_0^t K(t,s)\,dL_s
  = \sigma\!\int_0^t K(t,s)\,dW_s
  + \int_0^t\!\!\int_\R K(t,s)\,z\,\Ntilde(ds,dz).
\end{equation}

\label{ass:kernel}
The kernel $K$ satisfies:
\begin{enumerate}[label=(K\arabic*)]
\item\label{K1} \textbf{$L^\gamma$-integrability:}
  $\displaystyle\sup_{t \in [0,T]} \int_0^t |K(t,s)|^\gamma\,ds < \infty$.
  This ensures that $V_t$ is well-defined in $L^p$ for
  $p \in (1,\gamma)$.
\item\label{K2} \textbf{$L^2$-integrability (when $\sigma > 0$):}
  $\displaystyle\sup_{t \in [0,T]} \int_0^t K(t,s)^2\,ds < \infty$.
  This ensures the Gaussian part is well-defined in $L^2$.
\end{enumerate}

\label{def:combined-energy}
The \emph{combined energy space} is the product Banach space
\begin{equation}\label{eq:HVL}
  \HH_{VL} := H_W \times \widetilde{H}_J,
\end{equation}
where:
\begin{enumerate}[label=(\roman*)]
\item The \emph{continuous energy space}:
  \begin{equation}\label{eq:HW}
    H_W := L^2\bigl([0,T] \times \Omega,\;
    \mathcal{P},\; \sigma^2\,ds \otimes d\PP\bigr),
  \end{equation}
  with norm
  $\|u\|_{H_W}^2 = \E\!\int_0^T u_t^2\,\sigma^2\,dt$
  and divergence
  $\delta_W(u) = \sigma\!\int_0^T u_t\,dW_t$.
  This is a Hilbert space.

\item The \emph{jump energy space}:
  \begin{equation}\label{eq:HJ}
    \widetilde{H}_J :=
    L^p\bigl([0,T] \times \R \times \Omega,\;
    \mathcal{P} \otimes \mathcal{B}(\R),\;
    dt \otimes \nu(dz) \otimes d\PP\bigr),
  \end{equation}
  with norm
  $\|h\|_{\widetilde{H}_J}^p = \E\!\int_0^T\!\!\int_\R
  |h(t,z)|^p\,\nu(dz)\,dt$
  and divergence
  $\widetilde{\delta}_J(h) = \int_0^T\!\!\int_\R
  h(t,z)\,\Ntilde(dt,dz)$.
  This is a Banach space (non-Hilbert for $p \neq 2$).
\end{enumerate}
The \emph{combined divergence} is
\begin{equation}\label{eq:delta-VL}
  \delta_{VL}(u,h) := \delta_W(u) + \widetilde{\delta}_J(h)
  = \sigma\!\int_0^T u_t\,dW_t
  + \int_0^T\!\!\int_\R h(t,z)\,\Ntilde(dt,dz).
\end{equation}

\label{def:D-VL}
The \emph{combined operator derivative} is the Banach dual
\begin{equation}\label{eq:D-VL}
  D_{VL} := \delta_{VL}^* : L^q(\Omega) \to \HH_{VL}^*,
\end{equation}
defined by
$\ip{D_{VL} F}{(u,h)} = \E[F \cdot \delta_{VL}(u,h)]$
for $F \in L^q(\Omega)$, $(u,h) \in \HH_{VL}$.

\label{prop:D-split}
$D_{VL} F = (D_W F,\, \widetilde{D}_J F)$, where
\begin{align}
  \ip{D_W F}{u}_{H_W^*, H_W}
  &= \E\!\left[F \cdot \sigma\!\int_0^T u_t\,dW_t\right],
  \label{eq:DW}\\
  \ip{\widetilde{D}_J F}{h}_{\widetilde{H}_J^*, \widetilde{H}_J}
  &= \E\!\left[F \cdot \int_0^T\!\!\int_\R
  h(t,z)\,\Ntilde(dt,dz)\right].
  \label{eq:DJ}
\end{align}
