\label{lem:decomp}
Under the cap partition, the trilinear decomposes as:
\[
\Tril = \sum_j \Tril_j^{self} + \sum_{j \neq k} \Tril_{jk}^{cross}
\]
where:
\begin{align}
\Tril_j^{self} &= \langle (u_j \cdot \nabla)u_j, |\nabla|u \rangle \quad \text{(self-interaction of cap } j\text{)} \\
\Tril_{jk}^{cross} &= \langle (u_j \cdot \nabla)u_k + (u_k \cdot \nabla)u_j, |\nabla|u \rangle \quad \text{(cross-interaction)}
\end{align}

\label{prop:self}
The self-interaction terms satisfy:
\[
\sum_j |\Tril_j^{self}| \leq C \theta_0 E D^{1/2}
\]
where $\theta_0$ is the cap diameter. This bound holds regardless of concentration.

\label{prop:cross}
The cross-interaction terms satisfy:
\[
\sum_{j \neq k} |\Tril_{jk}^{cross}| \leq C (1 - \rho^2)^{1/2} E D^{1/2}
\]

Under non-concentration ($\rho \leq 1 - \eps_*$):
\[
\sum_{j \neq k} |\Tril_{jk}^{cross}| \leq C (1 - (1-\eps_*)^2)^{1/2} E D^{1/2} = C (2\eps_* - \eps_*^2)^{1/2} E D^{1/2}
\]

For $\lambda > 0$, define:
\begin{align}
E_{<\lambda} &= \int_{|\xi| < \lambda} |\xi| |\hat{u}|^2 \, d\xi \\
E_{\geq\lambda} &= \int_{|\xi| \geq \lambda} |\xi| |\hat{u}|^2 \, d\xi
\end{align}

\label{prop:high-freq}
For any $\lambda > 0$:
\[
|\Tril_{\geq\lambda}| := |\langle (u \cdot \nabla)u, |\nabla|u_{\geq\lambda} \rangle| \leq C E D^{1/2} \cdot \frac{E_{\geq\lambda}}{E}
\]

If high frequencies are non-concentrated (i.e., $E_{j,\geq\lambda} \leq (1-\eps_*) E_{\geq\lambda}$ for all $j$), then the same bound holds with no improvement.

\label{thm:obstacle}
The trilinear form $\Tril = \langle (u \cdot \nabla)u, |\nabla|u \rangle$ satisfies:
\[
\Tril = \sum_{p,q,k} i(p \cdot \hat{u}(q)) \hat{u}(p) \cdot |k| \overline{\hat{u}(k)} \cdot \delta(p+q-k)
\]

The sign and magnitude of $\Tril$ depend on:
\begin{enumerate}
\item Phase relationships between Fourier modes
\item Directional alignment of velocity vectors $\hat{u}(p) \cdot \overline{\hat{u}(k)}$
\item The geometry of the triadic interactions $p + q = k$
\end{enumerate}

\textbf{Non-concentration controls (1) the distribution of $|\hat{u}|^2$ across directions, but NOT:}
\begin{itemize}
\item The phases of $\hat{u}$
\item The vector directions of $\hat{u}(\xi)$ within the plane $\perp \xi$
\item The triadic geometry
\end{itemize}

Therefore, non-concentration cannot bound $\Tril$ beyond the generic estimate $|\Tril| \leq C E D^{1/2}$.

\label{thm:factorization}
Under axioms \ref{ax:adjoint}--\ref{ax:filtration}, for $F \in \mathcal{D}$ with $\Pi DF \in \Dom(\delta)$:
\begin{equation}
F - \E[F] = \delta(\Pi DF).
\end{equation}

$D$ is a \textbf{derivation} if
\begin{equation}
D(FG) = F \cdot DG + G \cdot DF.
\end{equation}

$D$ is a \textbf{cocycle} (for the add-one shift) if
\begin{equation}
D(FG) = F \cdot DG + G \cdot DF + DF \cdot DG.
\end{equation}

\label{thm:product-derivation}
If $D$ is a derivation, then for $F \in \mathcal{D}$ and predictable $u \in \Dom(\delta)$:
\begin{equation}\label{eq:product-derivation}
\delta(Fu) = F \cdot \delta(u) - \inner{DF}{u}_\HH.
\end{equation}

\label{thm:product-cocycle}
If $D$ is a cocycle, then for $F \in \mathcal{D}$ and predictable $u \in \Dom(\delta)$:
\begin{equation}\label{eq:product-cocycle}
\delta(Fu) = F \cdot \delta(u) - \inner{DF}{u}_\HH - \inner{DF \cdot u}{\mathbf{1}}_\HH,
\end{equation}
where the correction term $\inner{DF \cdot u}{\mathbf{1}}_\HH = \int_0^T D_t F \cdot u_t \, \lambda \, dt$ for Poisson.

The It\^o formula for a process $X$ depends on whether $D$ is a derivation or cocycle:
\begin{itemize}
\item \textbf{Derivation (diffusion):} $df(X_t) = f'(X_t) dX_t + \frac{1}{2} f''(X_t) d[X]_t$.
\item \textbf{Cocycle (jump):} $df(X_t) = f'(X_{t-}) dX_t^c + \sum_{s \leq t} [f(X_s) - f(X_{s-})]$, where the sum captures the discrete jumps.
\end{itemize}

\label{def:one-param}
The \emph{one-parameter energy space}, \emph{divergence},
and \emph{derivative} are:
\begin{align}
  H_L &:= L^p([0,T]\times\Omega,\,\mathcal{P},\,
  dt\otimes dP), \label{eq:HL}\\
  \delta_L &: H_L \to L^p(\Omega), \qquad
  \delta_L(u) := \int_0^T u_t\,dL_t, \label{eq:deltaL}\\
  D_L &:= \delta_L^* : L^q(\Omega) \to H_L^*, \qquad
  \langle D_L F, u \rangle = \E[F\cdot\delta_L(u)].
  \label{eq:DL}
\end{align}
The BDG equivalence
$c_p\|u\|_{H_L} \leq \|\delta_L(u)\|_{L^p}
\leq C_p\|u\|_{H_L}$ holds for constants
$c_p, C_p > 0$.

\label{def:two-param}
The \emph{two-parameter energy space} is
\begin{equation}\label{eq:tHL}
  \widetilde{H}_L :=
  L^p\bigl([0,T]\times\R\times\Omega,\;
  \mathcal{P}\otimes\mathcal{B}(\R),\;
  dt\otimes\nu(dz)\otimes dP\bigr),
\end{equation}
equipped with the norm
\begin{equation}\label{eq:tHL-norm}
  \|h\|_{\widetilde{H}_L}
  := \left(\E\!\int_0^T\!\!\int_{\R}
  |h(t,z)|^p\,\nu(dz)\,dt\right)^{1/p}.
\end{equation}
The \emph{two-parameter divergence} is
\begin{equation}\label{eq:tdelta}
  \widetilde{\delta}_L : \widetilde{H}_L \to L^p(\Omega),
  \qquad
  \widetilde{\delta}_L(h) :=
  \int_0^T\!\!\int_{\R} h(t,z)\,\widetilde{N}(dt,dz).
\end{equation}
The \emph{two-parameter derivative} is the adjoint
\begin{equation}\label{eq:tDL}
  \widetilde{D}_L := \widetilde{\delta}_L^* :
  L^q(\Omega) \to \widetilde{H}_L^*,
  \qquad
  \langle \widetilde{D}_L F, h \rangle
  = \E\bigl[F \cdot \widetilde{\delta}_L(h)\bigr]
\end{equation}
for $F \in L^q(\Omega)$,
$h \in \widetilde{H}_L$.

\label{def:linearization}
For $u \in H_L$, define the \emph{linearization}
$\Lambda u : [0,T]\times\R\times\Omega \to \R$ by
\begin{equation}\label{eq:Lambda}
  (\Lambda u)(t,z) := u(t) \cdot z.
\end{equation}

\label{thm:two-param-BDG}
For $p \in (1,\gamma)$ with $\gamma \in (1,2)$, there exist
constants $\tilde{c}_p, \tilde{C}_p > 0$ (depending on $p$,
$\gamma$, and $T$) such that for all
$h \in \widetilde{H}_L$,
\begin{equation}\label{eq:two-param-BDG}
  \tilde{c}_p\,\|h\|_{\widetilde{H}_L}
  \leq \|\widetilde{\delta}_L(h)\|_{L^p(\Omega)}
  \leq \tilde{C}_p\,\|h\|_{\widetilde{H}_L}.
\end{equation}

\label{thm:surjectivity}
The closure $\overline{\im(\widetilde{\delta}_L)}^{L^p}
= L^p_0(\Omega)$.  That is, every centered
$F \in L^p(\Omega)$ lies in the $L^p$-closure of the range
of $\widetilde{\delta}_L$.

\label{thm:two-param-factorization}
For $p \in (1,\gamma)$ with $\gamma \in (1,2)$, the identity
\begin{equation}\label{eq:two-param-fact}
  F - \E[F]
  = \widetilde{\delta}_L\bigl(
  \widetilde{\iota}_L^{-1}(\widetilde{D}_L F)\bigr)
\end{equation}
holds for all $F \in L^p(\Omega) \cap L^q(\Omega)$.

\label{thm:clark-ocone}
For $p \in (1,\gamma)$ and $F \in L^p(\Omega) \cap L^q(\Omega)$,
there exists a unique $h_F \in \widetilde{H}_L$ such that
\begin{equation}\label{eq:clark-ocone}
  F - \E[F]
  = \int_0^T\!\!\int_{\R} h_F(t,z)\,\widetilde{N}(dt,dz),
\end{equation}
with the estimate
\begin{equation}\label{eq:CO-estimate}
