\label{thm:defect-decomposition}
Let $\phi \in C_b^3(\R)$ and $F = \phi(L_T)$.  Define
\begin{align*}
  g_\phi(s,z) &:= \phi(L_{s-}+z) - \phi(L_{s-})
                - \phi'(L_{s-})z,\\
  M_T^{(1)} &:= \int_0^T\!\!\int_\R
                g_\phi(s,z)\,\widetilde{N}(ds,dz)
              = \widetilde{\delta}_L(g_\phi),\\
  A_T^{(1)} &:= \int_0^T\!\!\int_\R
                g_\phi(s,z)\,\nu(dz)\,ds
              = \int_0^T \mathcal{L}\phi(L_s)\,ds,
\end{align*}
where $\mathcal{L} = -(-\Delta)^{\gamma/2}$ is the
generator of $L$.  Then:
\begin{enumerate}[label=(\alph*)]
\item \textup{(Doob--Meyer for the jump defect.)}
  $\Gamma_L^\phi(T) = M_T^{(1)} + A_T^{(1)}$, with
  $M^{(1)}$ a martingale and $A^{(1)}$ predictable of
  finite variation.
\item \textup{(Three-term decomposition.)}
  \begin{equation}\label{eq:three-term}
    \phi(L_T) - \E[\phi(L_T)]
    \;=\;
    \underbrace{\delta_L(\phi'(L_{\cdot-}))}_{\text{stable
    integral}}
    \;+\;
    \underbrace{M_T^{(1)}}_{\text{martingale defect}}
    \;+\;
    \underbrace{\bigl(A_T^{(1)} - \E[A_T^{(1)}]\bigr)}_{\text{compensator
    fluctuation}}.
  \end{equation}
\item \textup{(Classification of the three terms.)}
\begin{itemize}
\item $\delta_L(\phi'(L_{\cdot-}))$ is $\nu$-singular
  (its unique two-parameter integrand $\phi'(L_{t-})z$
  fails the global $L^p(\nu)$ component of
  $\|\cdot\|_{\widetilde{H}_L}$, so
  $\delta_L(\phi'(L_{\cdot-})) \notin
  \im(\widetilde{\delta}_L)$).  It exists as a stable
  stochastic integral in the standard L\'evy sense.
\item $M_T^{(1)} = \widetilde{\delta}_L(g_\phi)$ is
  \emph{explicitly $\nu$-regular}: its integrand
  $g_\phi \in \widetilde{H}_L$ (with the
  Bichteler--Jacod norm), and the bound
  $\|M_T^{(1)}\|_{L^p}
  \leq \widetilde{C}_p\,\|g_\phi\|_{\widetilde{H}_L}$
  holds via Theorem~\ref{thm:two-param-BDG}.
\item $A_T^{(1)} - \E[A_T^{(1)}]$ is a centered finite-
  variation path functional, bounded above
  ($|A_T^{(1)}| \leq T\|\mathcal{L}\phi\|_\infty$, with
  $\mathcal{L}\phi$ bounded for $\phi \in C_b^3$ and
  $\gamma < 2$), hence in $L^r(\Omega)$ for every
  $r \geq 1$.  By Theorem~\ref{thm:surjectivity} it lies
  in the $L^p$-closure $\overline{\im(\widetilde{\delta}_L)}^{L^p}
  = L^p_0(\Omega)$.  We do \emph{not} establish whether
  it lies in $\im(\widetilde{\delta}_L)$ itself, i.e.,
  whether it admits an explicit $\widetilde{H}_L$-integrand;
  see Remark~\ref{rem:compensator-rep} below.
\end{itemize}
\end{enumerate}

