$c_p, C_p > 0$.

\label{def:two-param}
The \emph{two-parameter energy space} is
\begin{equation}\label{eq:tHL}
  \widetilde{H}_L :=
  L^p\bigl([0,T]\times\R\times\Omega,\;
  \mathcal{P}\otimes\mathcal{B}(\R),\;
  dt\otimes\nu(dz)\otimes dP\bigr),
\end{equation}
equipped with the norm
\begin{equation}\label{eq:tHL-norm}
  \|h\|_{\widetilde{H}_L}
  := \left(\E\!\int_0^T\!\!\int_{\R}
  |h(t,z)|^p\,\nu(dz)\,dt\right)^{1/p}.
\end{equation}
The \emph{two-parameter divergence} is
\begin{equation}\label{eq:tdelta}
  \widetilde{\delta}_L : \widetilde{H}_L \to L^p(\Omega),
  \qquad
  \widetilde{\delta}_L(h) :=
  \int_0^T\!\!\int_{\R} h(t,z)\,\widetilde{N}(dt,dz).
\end{equation}
The \emph{two-parameter derivative} is the adjoint
\begin{equation}\label{eq:tDL}
  \widetilde{D}_L := \widetilde{\delta}_L^* :
  L^q(\Omega) \to \widetilde{H}_L^*,
  \qquad
  \langle \widetilde{D}_L F, h \rangle
  = \E\bigl[F \cdot \widetilde{\delta}_L(h)\bigr]
\end{equation}
for $F \in L^q(\Omega)$,
$h \in \widetilde{H}_L$.

\label{def:linearization}
For $u \in H_L$, define the \emph{linearization}
$\Lambda u : [0,T]\times\R\times\Omega \to \R$ by
\begin{equation}\label{eq:Lambda}
  (\Lambda u)(t,z) := u(t) \cdot z.
\end{equation}

\label{thm:two-param-BDG}
For $p \in (1,\gamma)$ with $\gamma \in (1,2)$, there exist
constants $\tilde{c}_p, \tilde{C}_p > 0$ (depending on $p$,
$\gamma$, and $T$) such that for all
$h \in \widetilde{H}_L$,
\begin{equation}\label{eq:two-param-BDG}
  \tilde{c}_p\,\|h\|_{\widetilde{H}_L}
  \leq \|\widetilde{\delta}_L(h)\|_{L^p(\Omega)}
  \leq \tilde{C}_p\,\|h\|_{\widetilde{H}_L}.
\end{equation}

\label{thm:surjectivity}
The closure $\overline{\im(\widetilde{\delta}_L)}^{L^p}
= L^p_0(\Omega)$.  That is, every centered
$F \in L^p(\Omega)$ lies in the $L^p$-closure of the range
of $\widetilde{\delta}_L$.

\label{thm:two-param-factorization}
For $p \in (1,\gamma)$ with $\gamma \in (1,2)$, the identity
\begin{equation}\label{eq:two-param-fact}
  F - \E[F]
  = \widetilde{\delta}_L\bigl(
  \widetilde{\iota}_L^{-1}(\widetilde{D}_L F)\bigr)
\end{equation}
holds for all $F \in L^p(\Omega) \cap L^q(\Omega)$.

\label{thm:clark-ocone}
For $p \in (1,\gamma)$ and $F \in L^p(\Omega) \cap L^q(\Omega)$,
there exists a unique $h_F \in \widetilde{H}_L$ such that
\begin{equation}\label{eq:clark-ocone}
  F - \E[F]
  = \int_0^T\!\!\int_{\R} h_F(t,z)\,\widetilde{N}(dt,dz),
\end{equation}
with the estimate
\begin{equation}\label{eq:CO-estimate}
  \tilde{c}_p\,\|h_F\|_{\widetilde{H}_L}
  \leq \|F - \E[F]\|_{L^p(\Omega)}
  \leq \tilde{C}_p\,\|h_F\|_{\widetilde{H}_L}.
\end{equation}
The integrand $h_F$ is predictable (in $t$) and
$\nu$-measurable (in $z$).

\label{prop:attn}
For any fixed $q$:
\textnormal{(i)}~$\Pi_q$ is linear;
\textnormal{(ii)}~positive
($v_i \geq 0 \Rightarrow \Pi_q(v) \geq 0$);
\textnormal{(iii)}~normalized
($\Pi_q(\mathbf{1}) = 1$);
\textnormal{(iv)}~a contraction
($\norm{\Pi_q(v)} \leq \max_i \norm{v_i}$, by Jensen).

\label{prop:innovation}
Applying~\eqref{eq:diff} before the attention layers:
\textnormal{(i)}~costs $O(L)$, negligible relative to
$O(L^2)$ attention;
\textnormal{(ii)}~changes no parameters;
\textnormal{(iii)}~transforms temporal signals from
a space where they are invisible to $\Pi$
(content-similar values) to one where they are
visible (sparse innovations at transitions).

\label{cor:bounds}
For $\alpha \in (0,1)$, $\lambda > 0$, and $t > 0$:
\begin{equation}\label{eq:bounds}
\frac{1}{1 + \lambda\,t^\alpha / \Gamma(1+\alpha)}
\;\leq\; E_\alpha(-\lambda\,t^\alpha)
\;\leq\; \frac{1}{1 + \lambda\,t^\alpha
  / \Gamma(1-\alpha)}.
\end{equation}

\label{rem:alpha_role}
The fractional order $\alpha$ controls the sharpness
of temporal discrimination:
$\alpha \to 1$ approaches exponential decay
(sharp cutoff, short memory);
$\alpha \to 0$ approaches a constant function
(no discrimination, infinite memory).
The spectral representation~\eqref{eq:spectral}
makes this explicit: at $\alpha = 1$, the spectral
density concentrates on a single rate $r = \lambda$;
at smaller $\alpha$, the density spreads over a
continuum of rates, generating the multi-scale
persistence that characterizes fractional dynamics.

\label{def:opderiv}
For $F \in L^2(\Omega)$ such that the functional $u \mapsto \E[F \cdot \delta_X(u)]$ is continuous on $\dom(\delta_X) \subseteq L^2(\Omega; \HX)$ with respect to the $L^2(\Omega; \HX)$-norm, the \emph{operator derivative} $D_X F$ is the unique element of $L^2(\Omega; \HX)$ satisfying
\begin{equation}\label{eq:adj}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HX}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}
Existence follows from the Riesz representation theorem applied to the continuous functional $u \mapsto \E[F \cdot \delta_X(u)]$ on $\overline{\dom(\delta_X)}^{L^2(\Omega;\HX)}$; uniqueness from the density of $\dom(\delta_X)$.

\label{cond:iso}
For predictable $u, v \in L^2(\Omega; \HX)$:
\begin{equation}\label{eq:isometry}
\E[\delta_X(u) \cdot \delta_X(v)] = \E[\langle u, v \rangle_{\HX}].
\end{equation}

\label{thm:CO}
Let $X$ have energy space $(\HX, \delta_X)$, predictable projection $\Pi_X$, and $D_X = \delta_X^*$. Assume:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \textup{Centered integrals:} $\E[\delta_X(u)] = 0$ for all $u \in \dom(\delta_X)$.
\item \textup{Isometry on predictable processes:} Condition~\ref{cond:iso} holds.
\item \textup{Predictable representation property (PRP):} Every centered ${\FX}_T$-measurable $\tilde{F} \in L^2(\Omega)$ can be written as $\tilde{F} = \delta_X(v)$ for some predictable $v \in L^2(\Omega; \HX)$.
\end{enumerate}
Then for ${\FX}_T$-measurable $F \in L^2(\Omega)$:
\begin{equation}\label{eq:clark_ocone}
F = \E[F] + \delta_X(\Pi_X D_X F).
\end{equation}
Equivalently, $(\Id - \E) = \delta_X \circ \Pi_X \circ D_X$ on $L^2(\Omega, {\FX}_T, P)$.

following_proof:
Write $\tilde{F} := F - \E[F]$. By PRP, there exists a predictable $v \in L^2(\Omega; \HX)$ such that $\tilde{F} = \delta_X(v)$. We claim $\Pi_X D_X F = v$.

\emph{Step 1: Adjointness and isometry.} For any predictable $u \in L^2(\Omega; \HX)$, the adjoint relation~\eqref{eq:adj} gives
\begin{equation}\label{eq:CO_step1}
\E[\langle D_X F, u \rangle_{\HX}] = \E[F \cdot \delta_X(u)].
\end{equation}
Since $\delta_X$ is centered, $\E[\E[F] \cdot \delta_X(u)] = \E[F] \cdot \E[\delta_X(u)] = 0$, so
\begin{equation}\label{eq:CO_step2}
\E[\langle D_X F, u \rangle_{\HX}] = \E[\tilde{F} \cdot \delta_X(u)] = \E[\delta_X(v) \cdot \delta_X(u)].
\end{equation}

\emph{Step 2: Polarization of isometry.} The isometry (Condition~\ref{cond:iso}) states $\E[|\delta_X(w)|^2] = \E[\|w\|^2_{\HX}]$ for predictable~$w$. Polarizing: replace $w$ by $v + u$ and $v - u$ and subtract:
\[
\E[\delta_X(v) \cdot \delta_X(u)] = \tfrac{1}{4}\bigl(\E[\|v+u\|^2_{\HX}] - \E[\|v-u\|^2_{\HX}]\bigr) = \E[\langle v, u \rangle_{\HX}].
\]
Both $v$ and $u$ are predictable, so the isometry applies.

\emph{Step 3: Identification.} Combining~\eqref{eq:CO_step2} with the polarization:
\begin{equation}\label{eq:CO_step3}
\E[\langle D_X F, u \rangle_{\HX}] = \E[\langle v, u \rangle_{\HX}] \quad \text{for all predictable } u.
\end{equation}
This means $\E[\langle D_X F - v, u \rangle_{\HX}] = 0$ for all predictable~$u$, i.e., $D_X F - v$ is orthogonal to the subspace of predictable processes. By definition of the predictable projection, $\Pi_X D_X F = v$.

\emph{Step 4: Conclusion.} $\tilde{F} = \delta_X(v) = \delta_X(\Pi_X D_X F)$, giving $F = \E[F] + \delta_X(\Pi_X D_X F)$.

