\label{lem:prod_rule}
Under Leibniz, for $F \in \dom(D)\cap L^\infty$ and $u \in \dom(\delta)$ with $\|DF\|_{\mathcal{H}}\,\|u\|_{\mathcal{H}} \in L^2(\Omega)$ and $Fu \in \dom(\delta)$:
\begin{equation}\label{eq:prod_rule}
\delta(Fu) = F\delta(u) - \langle DF, u\rangle_{\mathcal{H}}.
\end{equation}

\label{lem:skor_iso}
Let $(D,\delta,\Pi)$ satisfy the framework axioms and let $u \in \dom(\delta)$ be adapted ($\Pi u_s = u_s$ for a.e.~$s$) with $s \mapsto u_s$ H\"older continuous in $L^2(\Omega;\mathcal{H})$ with exponent $\gamma > 0$. Then for any interval $[t_k, t_{k+1}]$ with $\Delta t := t_{k+1}-t_k$:
\begin{equation}\label{eq:skor_iso}
\E\bigl[|\delta(u\cdot\mathbf{1}_{(t_k,t_{k+1}]})|^2\bigr] = \E\!\left[\int_{t_k}^{t_{k+1}}\|u_s\|^2_{\mathcal{H}}\,ds\right] + O((\Delta t)^{2\gamma+1}).
\end{equation}

\label{thm:ito}
Let $(D,\delta,\Pi)$ satisfy the chain rule with $\Pi$ orthogonal, and assume the factorization $(\Id - \E)G = \delta(\Pi DG)$ holds for all $G$ in a class containing $\varphi(Y_t)$ (this is automatic when $Y$ generates the filtration and has PRP, and holds for Gaussian Volterra processes). Let $Y$ be a $(D,\delta,\Pi)$-It\^o process with $t\mapsto\Pi DY_t$ H\"older continuous in $L^2(\Omega;\mathcal{H})$. For $\varphi \in C_b^3(\R)$:
\begin{equation}\label{eq:ito}
\varphi(Y_t) = \varphi(Y_0)+\int_0^t\varphi'(Y_s)a_s\,ds+\delta(\varphi'(Y)\Pi DY\cdot\mathbf{1}_{[0,t]})+\frac{1}{2}\int_0^t\varphi''(Y_s)\|\Pi DY_s\|^2\,ds.
\end{equation}

\label{thm:multi_ito}
For $Y = (Y^1,\ldots,Y^n)$ with each $Y^i$ a $(D,\delta,\Pi)$-It\^o process, $\varphi \in C_b^3(\R^n)$:
\begin{align}
\varphi(Y_t) &= \varphi(Y_0)+\sum_i\int_0^t\partial_i\varphi(Y_s)a^i_s\,ds+\sum_i\delta(\partial_i\varphi(Y)\Pi DY^i\cdot\mathbf{1}_{[0,t]}) \notag\\
&\quad+\frac{1}{2}\sum_{i,j}\int_0^t\partial_i\partial_j\varphi(Y_s)\langle\Pi DY^i_s,\Pi DY^j_s\rangle_{\mathcal{H}}\,ds. \label{eq:multi_ito}
\end{align}

\label{prop:DM}
For $F \in \mathbb{D}^{1,2}$, the operator derivative on $\HM^{\mathrm{ext}}$ satisfies
\begin{equation}\label{eq:DM}
(D_M F)_t = \frac{D_t^W F}{\sigma_t} \qquad dt \otimes dP\text{-a.e.}
\end{equation}

\label{thm:leib_sv}
Under Assumption~\ref{ass:sv}, $D_M$ on $\HM^{\mathrm{ext}}$ satisfies the Leibniz rule: for $F, G \in \mathbb{D}^{1,4}(\Omega)$,
\begin{equation}\label{eq:leib_sv}
D_M(FG) = F\,D_M G + G\,D_M F \qquad \text{in } L^2(\Omega; \HM^{\mathrm{ext}}).
\end{equation}

\label{prop:rand_cyl}
$(\delta_M^{\mathrm{ext}}, \HM^{\mathrm{ext}})$ satisfies the integration-by-parts formula~\eqref{eq:IBP_abstract} on smooth $M$-cylindricals $\mathcal{C}_M := \{f(M_{t_1},\ldots,M_{t_n}) : f \in C_b^\infty\}$ with random representers
\begin{equation}\label{eq:kappa}
\kappa_i(t) := \frac{D_t^W(M_{t_i})}{\sigma_t} = \mathbf{1}_{[0,t_i]}(t) + \frac{1}{\sigma_t}\int_t^{t_i} D_t^W(\sigma_s)\,dW_s.
\end{equation}
When $\sigma$ is deterministic, $D_t^W(\sigma_s) = 0$ for all $s$, so $\kappa_i(t) = \mathbf{1}_{[0,t_i]}(t)$: the standard deterministic representers.

following_proof:
\emph{Step 1: Identify the representer from the IBP.} By part~(a) of the cylindrical reduction theorem (Theorem~\ref{thm:cylred}), the operator derivative on cylindricals satisfies $D_M F = \sum_i \partial_i f(\xi)\,\kappa_i$. Taking $n = 1$, $\xi_1 = M_{t_j}$, $f(x) = x$:
\begin{equation}\label{eq:obstr_deriv}
(D_M(M_{t_j}))_t = \kappa_j(t) \qquad \text{in } L^2(\Omega;\HM^{\mathrm{ext}}).
\end{equation}

\emph{Step 2: Compute via the adapted Malliavin derivative formula.} By Proposition~\ref{prop:DM}, $(D_M(M_{t_j}))_t = D_t^W(M_{t_j})/\sigma_t$ on $\HM^{\mathrm{ext}}$. Since $\sigma$ is progressively measurable, $M_{t_j} = \int_0^{t_j}\sigma_s\,dW_s$ is an It\^o integral. The Malliavin derivative of an It\^o integral with adapted, Malliavin-differentiable integrand~\cite[Proposition 1.3.3]{Nualart2006} gives, for $t \le t_j$:
\begin{equation}\label{eq:obstr_mall}
D_t^W(M_{t_j}) = \sigma_t + \int_t^{t_j} D_t^W(\sigma_s)\,dW_s.
\end{equation}
The integral $\int_t^{t_j} D_t^W(\sigma_s)\,dW_s$ is a \emph{genuine It\^o integral}: for fixed~$t$, the process $s \mapsto D_t^W(\sigma_s)$ is $\mathcal{F}_s$-adapted for $s > t$ (the Malliavin derivative of an adapted process at a fixed perturbation time inherits adaptedness in the forward variable; see~\cite[Theorem 2.2.1]{Nualart2006} for SDE solutions). For $t > t_j$: $D_t^W(M_{t_j}) = 0$ since $M_{t_j}$ is $\mathcal{F}_{t_j}$-measurable.

Dividing~\eqref{eq:obstr_mall} by $\sigma_t > 0$:
\begin{equation}\label{eq:obstr_explicit}
(D_M(M_{t_j}))_t = \mathbf{1}_{[0,t_j]}(t) + \frac{1}{\sigma_t}\int_t^{t_j} D_t^W(\sigma_s)\,dW_s.
\end{equation}

\emph{Step 3: Force deterministic representers.} Comparing~\eqref{eq:obstr_deriv} and~\eqref{eq:obstr_explicit}: if $\kappa_j(t)$ is deterministic, then for a.e.\ $t \le t_j$,
\begin{equation}\label{eq:obstr_det}
\frac{1}{\sigma_t}\int_t^{t_j} D_t^W(\sigma_s)\,dW_s = \kappa_j(t) - 1 =: c_j(t),
\end{equation}
where $c_j(t)$ is a deterministic constant (in $\omega$). Multiplying by $\sigma_t > 0$:
\begin{equation}\label{eq:obstr_ito}
\int_t^{t_j} D_t^W(\sigma_s)\,dW_s = c_j(t)\,\sigma_t \qquad \text{a.s.}
\end{equation}
The left side is an It\^o integral (established in Step~2), hence \emph{centered}: $\E[\int_t^{t_j} D_t^W(\sigma_s)\,dW_s] = 0$. Taking expectations of~\eqref{eq:obstr_ito}:
\[
0 = c_j(t)\,\E[\sigma_t].
\]
Since $\sigma_t > 0$ a.s., we have $\E[\sigma_t] > 0$. Therefore $c_j(t) = 0$ for a.e.~$t \le t_j$.

\emph{Step 4: Conclude.} From $c_j(t) = 0$ and~\eqref{eq:obstr_ito}: $\int_t^{t_j} D_t^W(\sigma_s)\,dW_s = 0$ a.s.\ for a.e.~$t \le t_j$. By the It\^o isometry (valid since this is an It\^o integral):
\[
\E\!\left[\left(\int_t^{t_j} D_t^W(\sigma_s)\,dW_s\right)^{\!2}\right] = \E\!\left[\int_t^{t_j} |D_t^W(\sigma_s)|^2\,ds\right] = 0.
\]
Hence $D_t^W(\sigma_s) = 0$ for $ds\otimes dP$-a.e.\ $(s,\omega)$ with $s \in [t, t_j]$, for a.e.~$t$. Taking $t_j = T$: $D_t^W(\sigma_s) = 0$ for a.e.\ $(s,t)$ with $t \le s \le T$. For $s < t$, adaptedness of $\sigma$ gives $D_t^W(\sigma_s) = 0$ (since $\sigma_s$ is $\mathcal{F}_s$-measurable). Thus $D_t^W(\sigma_s) = 0$ for $ds\otimes dt\otimes dP$-a.e.\ $(s,t,\omega)$. By the characterization of the Malliavin derivative~\cite[Proposition 1.2.1]{Nualart2006}, $\sigma_s$ is deterministic for a.e.~$s$, and $\langle M\rangle_T = \int_0^T\sigma_t^2\,dt$ is deterministic.

