\label{prop:DM}
For $F \in \mathbb{D}^{1,2}$, the operator derivative on $\HM^{\mathrm{ext}}$ satisfies
\begin{equation}\label{eq:DM}
(D_M F)_t = \frac{D_t^W F}{\sigma_t} \qquad dt \otimes dP\text{-a.e.}
\end{equation}

\label{thm:leib_sv}
Under Assumption~\ref{ass:sv}, $D_M$ on $\HM^{\mathrm{ext}}$ satisfies the Leibniz rule: for $F, G \in \mathbb{D}^{1,2} \cap L^4(\Omega)$,
\begin{equation}\label{eq:leib_sv}
D_M(FG) = F\,D_M G + G\,D_M F \qquad \text{in } L^2(\Omega; \HM^{\mathrm{ext}}).
\end{equation}

\label{prop:rand_cyl}
$(\delta_M^{\mathrm{ext}}, \HM^{\mathrm{ext}})$ admits a cylindrical structure (Definition~\ref{def:cyl}) with coordinates $\xi_i = M_{t_i}$ and random representers
\begin{equation}\label{eq:kappa}
\kappa_i(t) := \frac{D_t^W(M_{t_i})}{\sigma_t} = \mathbf{1}_{[0,t_i]}(t) + \frac{1}{\sigma_t}\int_0^{t_i} D_t^W(\sigma_s)\,dW_s.
\end{equation}
When $\sigma$ is deterministic, $D_t^W(\sigma_s) = 0$ for all $s$, so $\kappa_i(t) = \mathbf{1}_{[0,t_i]}(t)$: the standard deterministic representers.

following_proof:
\emph{Step 1: IBP with a quadratic test function.} Take $n = 1$, $\xi_1 = M_T$, and $f(x) = x^2$. Since $f \notin C_b^\infty$, approximate by $f_\varepsilon(x) := x^2 e^{-\varepsilon x^2}$ with $f_\varepsilon \in C_b^\infty$. The IBP gives $\E[f_\varepsilon(M_T) \cdot \delta_M(u)] = \E[f_\varepsilon'(M_T) \cdot \langle \kappa_1, u \rangle_{\HM}]$. Since $M_T \in L^4(\Omega)$ (by Assumption~\ref{ass:sv} and the Burkholder--Davis--Gundy inequality), pass $\varepsilon \to 0$ by dominated convergence:
\begin{equation}\label{eq:obstr_IBP}
\E[M_T^2 \cdot \delta_M(u)] = 2\,\E[M_T \cdot \langle \kappa_1, u \rangle_{\HM}].
\end{equation}

\emph{Step 2: Expand the left side.} By It\^o's formula, $M_T^2 = 2\int_0^T M_t\,dM_t + \langle M \rangle_T$. Using adjointness:
\begin{align}
\E[M_T^2 \cdot \delta_M(u)] &= \E\!\left[\left(2\int_0^T M_t\,dM_t + \langle M \rangle_T\right) \delta_M(u)\right] \notag \\
&= 2\,\E\!\left[\int_0^T M_t\,u_t\,d\langle M \rangle_t\right] + \E[\langle M \rangle_T \cdot \delta_M(u)], \label{eq:obstr_left}
\end{align}
where the first term uses the isometry/adjointness: $\E[(\int M_t\,dM_t) \cdot \delta_M(u)] = \E[\langle M_\cdot, u \rangle_{\HM}] = \E[\int M_t u_t \sigma_t^2\,dt]$.

\emph{Step 3: Expand the right side.} Since $\kappa_1$ is deterministic: $\langle \kappa_1, u \rangle_{\HM} = \E[\int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt \mid \mathcal{P}]$. For predictable $u$ and deterministic $\kappa_1$:
\begin{equation}\label{eq:obstr_right}
2\,\E[M_T \cdot \langle \kappa_1, u \rangle_{\HM}] = 2\,\E\!\left[M_T \int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt\right].
\end{equation}

\emph{Step 4: Equate and extract.} Combining~\eqref{eq:obstr_IBP},~\eqref{eq:obstr_left},~\eqref{eq:obstr_right}:
\[
2\,\E\!\left[\int_0^T M_t\,u_t\,\sigma_t^2\,dt\right] + \E[\langle M \rangle_T \cdot \delta_M(u)] = 2\,\E\!\left[M_T \int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt\right].
\]
Rearranging: $\E[\langle M \rangle_T \cdot \delta_M(u)] = 2\,\E[\int_0^T (M_T \kappa_1(t) - M_t)\,u_t\,\sigma_t^2\,dt]$.

By adjointness, $\E[\langle M \rangle_T \cdot \delta_M(u)] = \E[\langle D_M(\langle M \rangle_T), u \rangle_{\HM}] = \E[\int_0^T (D_M(\langle M \rangle_T))_t\,u_t\,\sigma_t^2\,dt]$. Since this holds for all predictable $u$:
\begin{equation}\label{eq:obstr_id}
(D_M(\langle M \rangle_T))_t = 2(M_T \kappa_1(t) - M_t) \qquad dt \otimes dP\text{-a.e.}
\end{equation}

\emph{Step 5: Contradiction.} Via the Malliavin derivative of the underlying Brownian motion:
\[
(D_M(\langle M \rangle_T))_t = \frac{D_t^W(\langle M \rangle_T)}{\sigma_t} = \frac{D_t^W(\int_0^T \sigma_s^2\,ds)}{\sigma_t} = \frac{2\int_0^T \sigma_s\,D_t^W(\sigma_s)\,ds}{\sigma_t}.
\]
If $\kappa_1$ is deterministic, then the right side of~\eqref{eq:obstr_id} is $2(M_T \kappa_1(t) - M_t)$: a function of $(M_T, M_t, t)$ that is linear in $M_T$ and $M_t$. But the left side is $2\sigma_t^{-1}\int_0^T \sigma_s D_t^W(\sigma_s)\,ds$: a functional of the entire Brownian path through the Malliavin derivative of $\sigma$.

To make the contradiction precise: take $u_t = \varepsilon^{-1}\mathbf{1}_{[s, s+\varepsilon]}(t)$ for fixed $s \in (0,T)$ and send $\varepsilon \to 0$. The identity~\eqref{eq:obstr_id} becomes pointwise:
\[
\frac{2\int_0^T \sigma_r D_s^W(\sigma_r)\,dr}{\sigma_s} = 2(M_T \kappa_1(s) - M_s).
\]
The right side is $\mathcal{F}_T^M$-measurable with specific dependence on $M_T$ and $M_s$. The left side depends on $D_s^W(\sigma_r)$ for all $r \in [0,T]$, which is a functional of the entire Brownian path. For stochastic $\sigma$ (e.g., $d\sigma = a(\sigma)\,dW$ with $a \neq 0$), $D_s^W(\sigma_r) \neq 0$ generically, and the left side cannot equal a linear function of $(M_T, M_s)$. In particular, taking $\E[\cdot \mid M_T, M_s]$ on both sides: the right side is unchanged, but the left side involves $\E[\sigma_r D_s^W(\sigma_r) \mid M_T, M_s]$, which depends on the entire conditional structure of $\sigma$ given $M$---not just on $(M_T, M_s)$. This is a contradiction unless $D_s^W(\sigma_r) = 0$ a.e., i.e., $\sigma$ is deterministic.

statement:
\label{def:opderiv}
For $F \in L^2(\Omega)$ such that the functional $u \mapsto \E[F \cdot \delta_X(u)]$ is continuous on $\dom(\delta_X) \subseteq L^2(\Omega; \HX)$ with respect to the $L^2(\Omega; \HX)$-norm, the \emph{operator derivative} $D_X F$ is the unique element of $L^2(\Omega; \HX)$ satisfying
\begin{equation}\label{eq:adj}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HX}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}
Existence follows from the Riesz representation theorem applied to the continuous functional $u \mapsto \E[F \cdot \delta_X(u)]$ on $\overline{\dom(\delta_X)}^{L^2(\Omega;\HX)}$; uniqueness from the density of $\dom(\delta_X)$.

\label{cond:iso}
For predictable $u, v \in L^2(\Omega; \HX)$:
\begin{equation}\label{eq:isometry}
\E[\delta_X(u) \cdot \delta_X(v)] = \E[\langle u, v \rangle_{\HX}].
\end{equation}

\label{thm:CO}
Let $X$ have energy space $(\HX, \delta_X)$, predictable projection $\Pi_X$, and $D_X = \delta_X^*$. Assume:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \textup{Centered integrals:} $\E[\delta_X(u)] = 0$ for all $u \in \dom(\delta_X)$.
\item \textup{Isometry on predictable processes:} Condition~\ref{cond:iso} holds.
\item \textup{Predictable representation property (PRP):} Every centered ${\FX}_T$-measurable $\tilde{F} \in L^2(\Omega)$ can be written as $\tilde{F} = \delta_X(v)$ for some predictable $v \in L^2(\Omega; \HX)$.
\end{enumerate}
Then for ${\FX}_T$-measurable $F \in L^2(\Omega)$:
\begin{equation}\label{eq:clark_ocone}
F = \E[F] + \delta_X(\Pi_X D_X F).
\end{equation}
Equivalently, $(\Id - \E) = \delta_X \circ \Pi_X \circ D_X$ on $L^2(\Omega, {\FX}_T, P)$.

following_proof:
Write $\tilde{F} := F - \E[F]$. By PRP, there exists a predictable $v \in L^2(\Omega; \HX)$ such that $\tilde{F} = \delta_X(v)$. We claim $\Pi_X D_X F = v$.

\emph{Step 1: Adjointness and isometry.} For any predictable $u \in L^2(\Omega; \HX)$, the adjoint relation~\eqref{eq:adj} gives
\begin{equation}\label{eq:CO_step1}
\E[\langle D_X F, u \rangle_{\HX}] = \E[F \cdot \delta_X(u)].
\end{equation}
Since $\delta_X$ is centered, $\E[\E[F] \cdot \delta_X(u)] = \E[F] \cdot \E[\delta_X(u)] = 0$, so
\begin{equation}\label{eq:CO_step2}
\E[\langle D_X F, u \rangle_{\HX}] = \E[\tilde{F} \cdot \delta_X(u)] = \E[\delta_X(v) \cdot \delta_X(u)].
\end{equation}

\emph{Step 2: Polarization of isometry.} The isometry (Condition~\ref{cond:iso}) states $\E[|\delta_X(w)|^2] = \E[\|w\|^2_{\HX}]$ for predictable~$w$. Polarizing: replace $w$ by $v + u$ and $v - u$ and subtract:
\[
\E[\delta_X(v) \cdot \delta_X(u)] = \tfrac{1}{4}\bigl(\E[\|v+u\|^2_{\HX}] - \E[\|v-u\|^2_{\HX}]\bigr) = \E[\langle v, u \rangle_{\HX}].
\]
Both $v$ and $u$ are predictable, so the isometry applies.

\emph{Step 3: Identification.} Combining~\eqref{eq:CO_step2} with the polarization:
\begin{equation}\label{eq:CO_step3}
\E[\langle D_X F, u \rangle_{\HX}] = \E[\langle v, u \rangle_{\HX}] \quad \text{for all predictable } u.
\end{equation}
This means $\E[\langle D_X F - v, u \rangle_{\HX}] = 0$ for all predictable~$u$, i.e., $D_X F - v$ is orthogonal to the subspace of predictable processes. By definition of the predictable projection, $\Pi_X D_X F = v$.

\emph{Step 4: Conclusion.} $\tilde{F} = \delta_X(v) = \delta_X(\Pi_X D_X F)$, giving $F = \E[F] + \delta_X(\Pi_X D_X F)$.

statement:
\label{ex:poisson}
Let $\tilde{N}_t = N_t - \lambda t$ be a compensated Poisson process with intensity $\lambda > 0$ and natural filtration $(\mathcal{F}_t^N)$. The energy space is as in Example~\ref{ex:poiss_energy}. Since $\tilde{N}$ has the PRP~\cite[Chapter 12]{DiNunno2009}, Theorem~\ref{thm:CO} gives
\begin{equation}\label{eq:poisson_CO}
F = \E[F] + \int_0^T (D_{\tilde{N}} F)_t\,d\tilde{N}_t.
\end{equation}

The natural difference operator for Poisson functionals is the \emph{add-a-point} operator: for a sample path~$\omega$ identified with its jump times, let $\omega + \varepsilon_t$ denote the configuration with one additional jump at time~$t$, and define
\begin{equation}\label{eq:add_a_point}
(\mathcal{D}_t^+ F)(\omega) := F(\omega + \varepsilon_t) - F(\omega).
\end{equation}

\begin{proposition}[Explicit form of $D_{\tilde{N}}$]\label{prop:poisson_explicit}
For $\mathcal{F}_T^N$-measurable $F \in L^2(\Omega)$:
$(D_{\tilde{N}} F)_t = \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]$, $dt \otimes dP$-a.e.
\end{proposition}

\begin{proof}
For predictable $u$, the Poisson integration-by-parts formula~\cite[Proposition 1.9]{Privault2009} gives
\[
\E\Bigl[F \cdot \int_0^T u_t\,d\tilde{N}_t\Bigr] = \lambda\,\E\Bigl[\int_0^T u_t\,\mathcal{D}_t^+ F\,dt\Bigr].
\]
Since $u_t$ is $\mathcal{F}_{t-}$-measurable, the tower property yields
$\E[u_t \cdot \mathcal{D}_t^+ F] = \E[u_t \cdot \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]]$.
So
\[
\E[F \cdot \delta_{\tilde{N}}(u)] = \lambda\,\E\Bigl[\int_0^T u_t \cdot \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]\,dt\Bigr] = \E\Bigl[\bigl\langle \E[\mathcal{D}_\cdot^+ F \mid \mathcal{F}_{\cdot-}], u \bigr\rangle_{\mathcal{H}_{\tilde{N}}}\Bigr].
\]
By uniqueness of the adjoint representer: $(D_{\tilde{N}} F)_t = \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]$.
\end{proof}

\label{prop:poisson_explicit}
For $\mathcal{F}_T^N$-measurable $F \in L^2(\Omega)$:
$(D_{\tilde{N}} F)_t = \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]$, $dt \otimes dP$-a.e.

\label{thm:fact_fbm}
For fBM $\BH$ with $H \in (0,1)$, $H \neq 1/2$, and $F \in L^2(\Omega,{\FBH}_T)$ with $D_{\BH}F \in L^2(\Omega;\HH)$:
\begin{equation}\label{eq:fact_fbm}
(\Id-\E)\,F = \delta_H(\Pi_{\BH}D_{\BH}F).
\end{equation}

\label{thm:gub}
Under the hypotheses of Theorem~\ref{thm:fact_fbm}, let $Y_t := \E[F\mid{\FBH}_t]$. Then
\begin{equation}\label{eq:gub}
Y_t - Y_s = \langle(\Pi_{\BH}D_{\BH}F)_s, k_t-k_s\rangle_{\HH} + R_{s,t}, \quad \E[R_{s,t}^2] = O(|t-s|^{\min(4H,\,2H+1)}).
\end{equation}
For $H < 1/2$: $\min(4H, 2H+1) = 4H$, recovering the Gubinelli regularity. For $H > 1/2$: $\min(4H, 2H+1) = 2H+1 > 2$, so the remainder decays faster than any power of $|t-s|^2$---the expansion is even better behaved. The operator approach is uniform in~$H$; the restriction $H < 1/2$ in rough path theory reflects path irregularity, not algebraic structure. The identity $(\Pi_{\BH}D_{\BH}F)_s = Y'_s$ is an equality in $L^2(\Omega; \HH)$; it identifies the Gubinelli derivative as an $L^2$-algebraic object, not as a pathwise-defined controlled path.

\label{rem:gub_scalar}
In Gubinelli's formulation~\cite{Gubinelli2004}, the controlled path expansion $Y_t-Y_s = Y'_s(X_t-X_s)+R_{s,t}$ requires $H > 1/3$ for level-2 controlled paths; for $H \le 1/3$, higher-order iterated integrals are needed (Lyons's rough paths for $H > 1/4$, Hairer's regularity structures~\cite{Hairer2014} for general $H$). These restrictions are \emph{pathwise}: they arise because the sample paths of $\BH$ have H\"older exponent $H-\varepsilon$, and pathwise integration theories require minimum regularity.

The operator approach provides a single $L^2$ mechanism across the entire range of Hurst parameters, where pathwise approaches require different theories for $H > 1/2$ (Young), $1/4 < H \le 1/2$ (Gubinelli), and $H \le 1/4$ (regularity structures). This uniformity comes at a cost: the $L^2$ framework averages over~$\Omega$ and does not provide the pathwise stability needed to solve rough differential equations. The operator derivative identifies the Gubinelli derivative as a predictable projection (Theorem~\ref{thm:gub}), but does not replace the pathwise analytical machinery required for applications such as rough integration or rough PDE theory. The two viewpoints---$L^2$-algebraic and pathwise-analytic---answer different questions and neither subsumes the other.

\label{def:normalized_CM}
For fractional Brownian motion with $H \in (0,1)$, $H \neq 1/2$, we normalize the Cameron--Martin space $\HH$ so that the representer $k_t := D_H{\BH}_t$ satisfies
\begin{equation}\label{eq:normalization}
\|k_t\|^2_{\HH} = 2Ht^{2H-1}.
\end{equation}
This ensures $\int_0^t\|k_s\|^2_{\HH}\,ds = t^{2H}$, aligning with the classical Skorokhod integral formulas~\cite{Decreusefond1999,Nualart2006}.

\label{def:cyl}
$(\delta_X,\HX)$ admits a \emph{cylindrical structure} if there exist coordinates $(\xi_i)$ and representers $\kappa_i \in L^2(\Omega;\HX)$ such that $\mathcal{C} = \{f(\xi_1,\ldots,\xi_n) : f \in C_b^\infty\}$ is dense in $\dom(D_X)$ (graph norm) and satisfies the IBP:
\begin{equation}\label{eq:IBP_abstract}
\E[F\delta_X(u)] = \sum_{i=1}^n\E[\partial_if(\xi)\langle\kappa_i,u\rangle_{\HX}].
\end{equation}
Representers may be deterministic or random.

\label{rem:cyl_meaning}
The closure argument in step (c) is standard functional analysis. The content of the theorem is not the closure but the \emph{criterion}: it reduces the process-dependent question ``does $D_X$ satisfy Leibniz?'' to the structural question ``does $(\delta_X, \HX)$ admit a cylindrical structure?'' This is a nontrivial condition. Gaussian processes satisfy it via Cameron--Martin quasi-invariance (Theorem~\ref{thm:leib_gauss}). Discrete innovation processes satisfy it via algebraic structure (Theorem~\ref{thm:leib_disc}). Compensated Poisson processes satisfy it with a modified Leibniz (Proposition~\ref{prop:levy}). Stochastic volatility martingales satisfy it only with random representers (Theorem~\ref{thm:leib_sv}), and the obstruction (Theorem~\ref{thm:obstr}) proves deterministic representers are impossible. The theorem organizes this classification.

Cylindrical reduction is sufficient for Leibniz, not necessary. Whether a converse holds---whether every process satisfying Leibniz admits some cylindrical structure---is an open question. The known examples suggest this may be true, but we do not prove it.

\label{prop:levy}
For L\'evy $X = \sigma W + \int z\widetilde{\mathcal{N}}(ds,dz)$:
\begin{align}
D^W(FG) &= FD^WG + GD^WF, \label{eq:levy_gauss} \\
D^{\widetilde{\mathcal{N}}}(FG)_{t,z} &= FD^{\widetilde{\mathcal{N}}}G + GD^{\widetilde{\mathcal{N}}}F + D^{\widetilde{\mathcal{N}}}F\cdot D^{\widetilde{\mathcal{N}}}G. \label{eq:levy_jump}
\end{align}

\label{lem:prod_rule}
Under Leibniz, for $F \in \dom(D)\cap L^\infty$ and $u \in \dom(\delta)$ with $Fu \in \dom(\delta)$:
\begin{equation}\label{eq:prod_rule}
\delta(Fu) = F\delta(u) - \langle DF, u\rangle_{\mathcal{H}}.
\end{equation}

\label{lem:skor_iso}
Let $(D,\delta,\Pi)$ satisfy the framework axioms and let $u \in \dom(\delta)$ be adapted ($\Pi u_s = u_s$ for a.e.~$s$) with $s \mapsto u_s$ H\"older continuous in $L^2(\Omega;\mathcal{H})$ with exponent $\gamma > 0$. Then for any interval $[t_k, t_{k+1}]$ with $\Delta t := t_{k+1}-t_k$:
\begin{equation}\label{eq:skor_iso}
\E\bigl[|\delta(u\cdot\mathbf{1}_{(t_k,t_{k+1}]})|^2\bigr] = \E\!\left[\int_{t_k}^{t_{k+1}}\|u_s\|^2_{\mathcal{H}}\,ds\right] + O((\Delta t)^{2\gamma+1}).
\end{equation}

\label{thm:ito}
Let $(D,\delta,\Pi)$ satisfy the chain rule with $\Pi$ orthogonal, and assume the factorization $(\Id - \E)G = \delta(\Pi DG)$ holds for all $G$ in a class containing $\varphi(Y_t)$ (this is automatic when $Y$ generates the filtration and has PRP, and holds for Gaussian Volterra processes). Let $Y$ be a $(D,\delta,\Pi)$-It\^o process with $t\mapsto\Pi DY_t$ H\"older continuous in $L^2(\Omega;\mathcal{H})$. For $\varphi \in C_b^3(\R)$:
\begin{equation}\label{eq:ito}
\varphi(Y_t) = \varphi(Y_0)+\int_0^t\varphi'(Y_s)a_s\,ds+\delta(\varphi'(Y)\Pi DY\cdot\mathbf{1}_{[0,t]})+\frac{1}{2}\int_0^t\varphi''(Y_s)\|\Pi DY_s\|^2\,ds.
\end{equation}

\label{thm:multi_ito}
For $Y = (Y^1,\ldots,Y^n)$ with each $Y^i$ a $(D,\delta,\Pi)$-It\^o process, $\varphi \in C_b^3(\R^n)$:
\begin{align}
\varphi(Y_t) &= \varphi(Y_0)+\sum_i\int_0^t\partial_i\varphi(Y_s)a^i_s\,ds+\sum_i\delta(\partial_i\varphi(Y)\Pi DY^i\cdot\mathbf{1}_{[0,t]}) \notag\\
&\quad+\frac{1}{2}\sum_{i,j}\int_0^t\partial_i\partial_j\varphi(Y_s)\langle\Pi DY^i_s,\Pi DY^j_s\rangle_{\mathcal{H}}\,ds. \label{eq:multi_ito}
\end{align}

\label{prop:DM}
For $F \in \mathbb{D}^{1,2}$, the operator derivative on $\HM^{\mathrm{ext}}$ satisfies
\begin{equation}\label{eq:DM}
(D_M F)_t = \frac{D_t^W F}{\sigma_t} \qquad dt \otimes dP\text{-a.e.}
\end{equation}

\label{thm:leib_sv}
Under Assumption~\ref{ass:sv}, $D_M$ on $\HM^{\mathrm{ext}}$ satisfies the Leibniz rule: for $F, G \in \mathbb{D}^{1,2} \cap L^4(\Omega)$,
\begin{equation}\label{eq:leib_sv}
D_M(FG) = F\,D_M G + G\,D_M F \qquad \text{in } L^2(\Omega; \HM^{\mathrm{ext}}).
\end{equation}

\label{prop:rand_cyl}
$(\delta_M^{\mathrm{ext}}, \HM^{\mathrm{ext}})$ admits a cylindrical structure (Definition~\ref{def:cyl}) with coordinates $\xi_i = M_{t_i}$ and random representers
\begin{equation}\label{eq:kappa}
\kappa_i(t) := \frac{D_t^W(M_{t_i})}{\sigma_t} = \mathbf{1}_{[0,t_i]}(t) + \frac{1}{\sigma_t}\int_0^{t_i} D_t^W(\sigma_s)\,dW_s.
\end{equation}
When $\sigma$ is deterministic, $D_t^W(\sigma_s) = 0$ for all $s$, so $\kappa_i(t) = \mathbf{1}_{[0,t_i]}(t)$: the standard deterministic representers.

following_proof:
\emph{Step 1: IBP with a quadratic test function.} Take $n = 1$, $\xi_1 = M_T$, and $f(x) = x^2$. Since $f \notin C_b^\infty$, approximate by $f_\varepsilon(x) := x^2 e^{-\varepsilon x^2}$ with $f_\varepsilon \in C_b^\infty$. The IBP gives $\E[f_\varepsilon(M_T) \cdot \delta_M(u)] = \E[f_\varepsilon'(M_T) \cdot \langle \kappa_1, u \rangle_{\HM}]$. Since $M_T \in L^4(\Omega)$ (by Assumption~\ref{ass:sv} and the Burkholder--Davis--Gundy inequality), pass $\varepsilon \to 0$ by dominated convergence:
\begin{equation}\label{eq:obstr_IBP}
\E[M_T^2 \cdot \delta_M(u)] = 2\,\E[M_T \cdot \langle \kappa_1, u \rangle_{\HM}].
\end{equation}

\emph{Step 2: Expand the left side.} By It\^o's formula, $M_T^2 = 2\int_0^T M_t\,dM_t + \langle M \rangle_T$. Using adjointness:
\begin{align}
\E[M_T^2 \cdot \delta_M(u)] &= \E\!\left[\left(2\int_0^T M_t\,dM_t + \langle M \rangle_T\right) \delta_M(u)\right] \notag \\
&= 2\,\E\!\left[\int_0^T M_t\,u_t\,d\langle M \rangle_t\right] + \E[\langle M \rangle_T \cdot \delta_M(u)], \label{eq:obstr_left}
\end{align}
where the first term uses the isometry/adjointness: $\E[(\int M_t\,dM_t) \cdot \delta_M(u)] = \E[\langle M_\cdot, u \rangle_{\HM}] = \E[\int M_t u_t \sigma_t^2\,dt]$.

\emph{Step 3: Expand the right side.} Since $\kappa_1$ is deterministic: $\langle \kappa_1, u \rangle_{\HM} = \E[\int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt \mid \mathcal{P}]$. For predictable $u$ and deterministic $\kappa_1$:
\begin{equation}\label{eq:obstr_right}
2\,\E[M_T \cdot \langle \kappa_1, u \rangle_{\HM}] = 2\,\E\!\left[M_T \int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt\right].
\end{equation}

\emph{Step 4: Equate and extract.} Combining~\eqref{eq:obstr_IBP},~\eqref{eq:obstr_left},~\eqref{eq:obstr_right}:
\[
2\,\E\!\left[\int_0^T M_t\,u_t\,\sigma_t^2\,dt\right] + \E[\langle M \rangle_T \cdot \delta_M(u)] = 2\,\E\!\left[M_T \int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt\right].
\]
Rearranging: $\E[\langle M \rangle_T \cdot \delta_M(u)] = 2\,\E[\int_0^T (M_T \kappa_1(t) - M_t)\,u_t\,\sigma_t^2\,dt]$.

By adjointness, $\E[\langle M \rangle_T \cdot \delta_M(u)] = \E[\langle D_M(\langle M \rangle_T), u \rangle_{\HM}] = \E[\int_0^T (D_M(\langle M \rangle_T))_t\,u_t\,\sigma_t^2\,dt]$. Since this holds for all predictable $u$:
\begin{equation}\label{eq:obstr_id}
(D_M(\langle M \rangle_T))_t = 2(M_T \kappa_1(t) - M_t) \qquad dt \otimes dP\text{-a.e.}
\end{equation}

\emph{Step 5: Contradiction.} Via the Malliavin derivative of the underlying Brownian motion:
\[
(D_M(\langle M \rangle_T))_t = \frac{D_t^W(\langle M \rangle_T)}{\sigma_t} = \frac{D_t^W(\int_0^T \sigma_s^2\,ds)}{\sigma_t} = \frac{2\int_0^T \sigma_s\,D_t^W(\sigma_s)\,ds}{\sigma_t}.
\]
If $\kappa_1$ is deterministic, then the right side of~\eqref{eq:obstr_id} is $2(M_T \kappa_1(t) - M_t)$: a function of $(M_T, M_t, t)$ that is linear in $M_T$ and $M_t$. But the left side is $2\sigma_t^{-1}\int_0^T \sigma_s D_t^W(\sigma_s)\,ds$: a functional of the entire Brownian path through the Malliavin derivative of $\sigma$.

To make the contradiction precise: take $u_t = \varepsilon^{-1}\mathbf{1}_{[s, s+\varepsilon]}(t)$ for fixed $s \in (0,T)$ and send $\varepsilon \to 0$. The identity~\eqref{eq:obstr_id} becomes pointwise:
\[
\frac{2\int_0^T \sigma_r D_s^W(\sigma_r)\,dr}{\sigma_s} = 2(M_T \kappa_1(s) - M_s).
\]
The right side is $\mathcal{F}_T^M$-measurable with specific dependence on $M_T$ and $M_s$. The left side depends on $D_s^W(\sigma_r)$ for all $r \in [0,T]$, which is a functional of the entire Brownian path. For stochastic $\sigma$ (e.g., $d\sigma = a(\sigma)\,dW$ with $a \neq 0$), $D_s^W(\sigma_r) \neq 0$ generically, and the left side cannot equal a linear function of $(M_T, M_s)$. In particular, taking $\E[\cdot \mid M_T, M_s]$ on both sides: the right side is unchanged, but the left side involves $\E[\sigma_r D_s^W(\sigma_r) \mid M_T, M_s]$, which depends on the entire conditional structure of $\sigma$ given $M$---not just on $(M_T, M_s)$. This is a contradiction unless $D_s^W(\sigma_r) = 0$ a.e., i.e., $\sigma$ is deterministic.

statement:
\label{def:opderiv}
For $F \in L^2(\Omega)$ such that the functional $u \mapsto \E[F \cdot \delta_X(u)]$ is continuous on $\dom(\delta_X) \subseteq L^2(\Omega; \HX)$ with respect to the $L^2(\Omega; \HX)$-norm, the \emph{operator derivative} $D_X F$ is the unique element of $L^2(\Omega; \HX)$ satisfying
\begin{equation}\label{eq:adj}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HX}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}
Existence follows from the Riesz representation theorem applied to the continuous functional $u \mapsto \E[F \cdot \delta_X(u)]$ on $\overline{\dom(\delta_X)}^{L^2(\Omega;\HX)}$; uniqueness from the density of $\dom(\delta_X)$.

\label{cond:iso}
For predictable $u, v \in L^2(\Omega; \HX)$:
\begin{equation}\label{eq:isometry}
\E[\delta_X(u) \cdot \delta_X(v)] = \E[\langle u, v \rangle_{\HX}].
\end{equation}

\label{thm:CO}
Let $X$ have energy space $(\HX, \delta_X)$, predictable projection $\Pi_X$, and $D_X = \delta_X^*$. Assume:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \textup{Centered integrals:} $\E[\delta_X(u)] = 0$ for all $u \in \dom(\delta_X)$.
\item \textup{Isometry on predictable processes:} Condition~\ref{cond:iso} holds.
\item \textup{Predictable representation property (PRP):} Every centered $\FX_T$-measurable $\tilde{F} \in L^2(\Omega)$ can be written as $\tilde{F} = \delta_X(v)$ for some predictable $v \in L^2(\Omega; \HX)$.
\end{enumerate}
Then for $\FX_T$-measurable $F \in L^2(\Omega)$:
\begin{equation}\label{eq:clark_ocone}
F = \E[F] + \delta_X(\Pi_X D_X F).
\end{equation}
Equivalently, $(\Id - \E) = \delta_X \circ \Pi_X \circ D_X$ on $L^2(\Omega, \FX_T, P)$.

following_proof:
Write $\tilde{F} := F - \E[F]$. By PRP, there exists a predictable $v \in L^2(\Omega; \HX)$ such that $\tilde{F} = \delta_X(v)$. We claim $\Pi_X D_X F = v$.

\emph{Step 1: Adjointness and isometry.} For any predictable $u \in L^2(\Omega; \HX)$, the adjoint relation~\eqref{eq:adj} gives
\begin{equation}\label{eq:CO_step1}
\E[\langle D_X F, u \rangle_{\HX}] = \E[F \cdot \delta_X(u)].
\end{equation}
Since $\delta_X$ is centered, $\E[\E[F] \cdot \delta_X(u)] = \E[F] \cdot \E[\delta_X(u)] = 0$, so
\begin{equation}\label{eq:CO_step2}
\E[\langle D_X F, u \rangle_{\HX}] = \E[\tilde{F} \cdot \delta_X(u)] = \E[\delta_X(v) \cdot \delta_X(u)].
\end{equation}

\emph{Step 2: Polarization of isometry.} The isometry (Condition~\ref{cond:iso}) states $\E[|\delta_X(w)|^2] = \E[\|w\|^2_{\HX}]$ for predictable~$w$. Polarizing: replace $w$ by $v + u$ and $v - u$ and subtract:
\[
\E[\delta_X(v) \cdot \delta_X(u)] = \tfrac{1}{4}\bigl(\E[\|v+u\|^2_{\HX}] - \E[\|v-u\|^2_{\HX}]\bigr) = \E[\langle v, u \rangle_{\HX}].
\]
Both $v$ and $u$ are predictable, so the isometry applies.

\emph{Step 3: Identification.} Combining~\eqref{eq:CO_step2} with the polarization:
\begin{equation}\label{eq:CO_step3}
\E[\langle D_X F, u \rangle_{\HX}] = \E[\langle v, u \rangle_{\HX}] \quad \text{for all predictable } u.
\end{equation}
This means $\E[\langle D_X F - v, u \rangle_{\HX}] = 0$ for all predictable~$u$, i.e., $D_X F - v$ is orthogonal to the subspace of predictable processes. By definition of the predictable projection, $\Pi_X D_X F = v$.

\emph{Step 4: Conclusion.} $\tilde{F} = \delta_X(v) = \delta_X(\Pi_X D_X F)$, giving $F = \E[F] + \delta_X(\Pi_X D_X F)$.

statement:
\label{ex:poisson}
Let $\tilde{N}_t = N_t - \lambda t$ be a compensated Poisson process with intensity $\lambda > 0$ and natural filtration $(\mathcal{F}_t^N)$. The energy space is as in Example~\ref{ex:poiss_energy}. Since $\tilde{N}$ has the PRP~\cite[Chapter 12]{DiNunno2009}, Theorem~\ref{thm:CO} gives
\begin{equation}\label{eq:poisson_CO}
F = \E[F] + \int_0^T (D_{\tilde{N}} F)_t\,d\tilde{N}_t.
\end{equation}

The natural difference operator for Poisson functionals is the \emph{add-a-point} operator: for a sample path~$\omega$ identified with its jump times, let $\omega + \varepsilon_t$ denote the configuration with one additional jump at time~$t$, and define
\begin{equation}\label{eq:add_a_point}
(\mathcal{D}_t^+ F)(\omega) := F(\omega + \varepsilon_t) - F(\omega).
\end{equation}

\begin{proposition}[Explicit form of $D_{\tilde{N}}$]\label{prop:poisson_explicit}
For $\mathcal{F}_T^N$-measurable $F \in L^2(\Omega)$:
$(D_{\tilde{N}} F)_t = \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]$, $dt \otimes dP$-a.e.
\end{proposition}

\begin{proof}
For predictable $u$, the Poisson integration-by-parts formula~\cite[Proposition 1.9]{Privault2009} gives
\[
\E\Bigl[F \cdot \int_0^T u_t\,d\tilde{N}_t\Bigr] = \lambda\,\E\Bigl[\int_0^T u_t\,\mathcal{D}_t^+ F\,dt\Bigr].
\]
Since $u_t$ is $\mathcal{F}_{t-}$-measurable, the tower property yields
$\E[u_t \cdot \mathcal{D}_t^+ F] = \E[u_t \cdot \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]]$.
So
\[
\E[F \cdot \delta_{\tilde{N}}(u)] = \lambda\,\E\Bigl[\int_0^T u_t \cdot \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]\,dt\Bigr] = \E\Bigl[\bigl\langle \E[\mathcal{D}_\cdot^+ F \mid \mathcal{F}_{\cdot-}], u \bigr\rangle_{\mathcal{H}_{\tilde{N}}}\Bigr].
\]
By uniqueness of the adjoint representer: $(D_{\tilde{N}} F)_t = \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]$.
\end{proof}

\label{prop:poisson_explicit}
For $\mathcal{F}_T^N$-measurable $F \in L^2(\Omega)$:
$(D_{\tilde{N}} F)_t = \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]$, $dt \otimes dP$-a.e.

\label{thm:fact_fbm}
For fBM $\BH$ with $H \in (0,1)$, $H \neq 1/2$, and $F \in L^2(\Omega,\FBH_T)$ with $D_{\BH}F \in L^2(\Omega;\HH)$:
\begin{equation}\label{eq:fact_fbm}
(\Id-\E)\,F = \delta_H(\Pi_{\BH}D_{\BH}F).
\end{equation}

\label{thm:gub}
Under the hypotheses of Theorem~\ref{thm:fact_fbm}, let $Y_t := \E[F\mid\FBH_t]$. Then
\begin{equation}\label{eq:gub}
Y_t - Y_s = \langle(\Pi_{\BH}D_{\BH}F)_s, k_t-k_s\rangle_{\HH} + R_{s,t}, \quad \E[R_{s,t}^2] = O(|t-s|^{\min(4H,\,2H+1)}).
\end{equation}
For $H < 1/2$: $\min(4H, 2H+1) = 4H$, recovering the Gubinelli regularity. For $H > 1/2$: $\min(4H, 2H+1) = 2H+1 > 2$, so the remainder decays faster than any power of $|t-s|^2$---the expansion is even better behaved. The operator approach is uniform in~$H$; the restriction $H < 1/2$ in rough path theory reflects path irregularity, not algebraic structure.

\label{rem:gub_scalar}
In Gubinelli's formulation~\cite{Gubinelli2004}, the controlled path expansion $Y_t-Y_s = Y'_s(X_t-X_s)+R_{s,t}$ requires $H > 1/3$ for level-2 controlled paths; for $H \le 1/3$, higher-order iterated integrals are needed (Lyons's rough paths for $H > 1/4$, Hairer's regularity structures~\cite{Hairer2014} for general $H$). These restrictions are \emph{pathwise}: they arise because the sample paths of $\BH$ have H\"older exponent $H-\varepsilon$, and pathwise integration theories require minimum regularity.

The operator derivative sees none of this. Theorem~\ref{thm:gub} gives the controlled expansion for all $H \in (0,1)$, $H \neq 1/2$, with a uniform proof: split the integrand, freeze at the left endpoint, estimate the remainder in $L^2$. The $L^2$-duality framework operates on the energy space $\HH$, not on sample paths. For $H > 1/2$, the expansion is better than needed (the remainder decays as $O(|t-s|^{2H+1})$); for $H < 1/2$, it recovers exactly the Gubinelli regularity. The operator approach thus provides a single mechanism across the entire range of Hurst parameters, where pathwise approaches require different theories for $H > 1/2$ (Young), $1/4 < H \le 1/2$ (Gubinelli), and $H \le 1/4$ (regularity structures).

\label{def:normalized_CM}
For fractional Brownian motion with $H \in (0,1)$, $H \neq 1/2$, we normalize the Cameron--Martin space $\HH$ so that the representer $k_t := D_H\BH_t$ satisfies
\begin{equation}\label{eq:normalization}
\|k_t\|^2_{\HH} = 2Ht^{2H-1}.
\end{equation}
This ensures $\int_0^t\|k_s\|^2_{\HH}\,ds = t^{2H}$, aligning with the classical Skorokhod integral formulas~\cite{Decreusefond1999,Nualart2006}.

\label{def:cyl}
$(\delta_X,\HX)$ admits a \emph{cylindrical structure} if there exist coordinates $(\xi_i)$ and representers $\kappa_i \in L^2(\Omega;\HX)$ such that $\mathcal{C} = \{f(\xi_1,\ldots,\xi_n) : f \in C_b^\infty\}$ is dense in $\dom(D_X)$ (graph norm) and satisfies the IBP:
\begin{equation}\label{eq:IBP_abstract}
\E[F\delta_X(u)] = \sum_{i=1}^n\E[\partial_if(\xi)\langle\kappa_i,u\rangle_{\HX}].
\end{equation}
Representers may be deterministic or random.

\label{prop:levy}
For L\'evy $X = \sigma W + \int z\widetilde{\mathcal{N}}(ds,dz)$:
\begin{align}
D^W(FG) &= FD^WG + GD^WF, \label{eq:levy_gauss} \\
D^{\widetilde{\mathcal{N}}}(FG)_{t,z} &= FD^{\widetilde{\mathcal{N}}}G + GD^{\widetilde{\mathcal{N}}}F + D^{\widetilde{\mathcal{N}}}F\cdot D^{\widetilde{\mathcal{N}}}G. \label{eq:levy_jump}
\end{align}

\label{lem:prod_rule}
Under Leibniz, for $F \in \dom(D)\cap L^\infty$ and $u \in \dom(\delta)$ with $Fu \in \dom(\delta)$:
\begin{equation}\label{eq:prod_rule}
\delta(Fu) = F\delta(u) - \langle DF, u\rangle_{\mathcal{H}}.
\end{equation}

\label{lem:skor_iso}
Let $(D,\delta,\Pi)$ satisfy the framework axioms and let $u \in \dom(\delta)$ be adapted ($\Pi u_s = u_s$ for a.e.~$s$) with $s \mapsto u_s$ H\"older continuous in $L^2(\Omega;\mathcal{H})$ with exponent $\gamma > 0$. Then for any interval $[t_k, t_{k+1}]$ with $\Delta t := t_{k+1}-t_k$:
\begin{equation}\label{eq:skor_iso}
\E\bigl[|\delta(u\cdot\mathbf{1}_{(t_k,t_{k+1}]})|^2\bigr] = \E\!\left[\int_{t_k}^{t_{k+1}}\|u_s\|^2_{\mathcal{H}}\,ds\right] + O((\Delta t)^{2\gamma+1}).
\end{equation}

\label{thm:ito}
Let $(D,\delta,\Pi)$ satisfy the chain rule with $\Pi$ orthogonal, and assume the factorization $(\Id - \E)G = \delta(\Pi DG)$ holds for all $G$ in a class containing $\varphi(Y_t)$ (this is automatic when $Y$ generates the filtration and has PRP, and holds for Gaussian Volterra processes). Let $Y$ be a $(D,\delta,\Pi)$-It\^o process with $t\mapsto\Pi DY_t$ H\"older continuous in $L^2(\Omega;\mathcal{H})$. For $\varphi \in C_b^3(\R)$:
\begin{equation}\label{eq:ito}
\varphi(Y_t) = \varphi(Y_0)+\int_0^t\varphi'(Y_s)a_s\,ds+\delta(\varphi'(Y)\Pi DY\cdot\mathbf{1}_{[0,t]})+\frac{1}{2}\int_0^t\varphi''(Y_s)\|\Pi DY_s\|^2\,ds.
\end{equation}

\label{thm:multi_ito}
For $Y = (Y^1,\ldots,Y^n)$ with each $Y^i$ a $(D,\delta,\Pi)$-It\^o process, $\varphi \in C_b^3(\R^n)$:
\begin{align}
\varphi(Y_t) &= \varphi(Y_0)+\sum_i\int_0^t\partial_i\varphi(Y_s)a^i_s\,ds+\sum_i\delta(\partial_i\varphi(Y)\Pi DY^i\cdot\mathbf{1}_{[0,t]}) \notag\\
&\quad+\frac{1}{2}\sum_{i,j}\int_0^t\partial_i\partial_j\varphi(Y_s)\langle\Pi DY^i_s,\Pi DY^j_s\rangle_{\mathcal{H}}\,ds. \label{eq:multi_ito}
\end{align}

\label{prop:DM}
For $F \in \mathbb{D}^{1,2}$, the operator derivative on $\HM^{\mathrm{ext}}$ satisfies
\begin{equation}\label{eq:DM}
(D_M F)_t = \frac{D_t^W F}{\sigma_t} \qquad dt \otimes dP\text{-a.e.}
\end{equation}

\label{thm:leib_sv}
Under Assumption~\ref{ass:sv}, $D_M$ on $\HM^{\mathrm{ext}}$ satisfies the Leibniz rule: for $F, G \in \mathbb{D}^{1,2} \cap L^4(\Omega)$,
\begin{equation}\label{eq:leib_sv}
D_M(FG) = F\,D_M G + G\,D_M F \qquad \text{in } L^2(\Omega; \HM^{\mathrm{ext}}).
\end{equation}

\label{prop:rand_cyl}
$(\delta_M^{\mathrm{ext}}, \HM^{\mathrm{ext}})$ admits a cylindrical structure (Definition~\ref{def:cyl}) with coordinates $\xi_i = M_{t_i}$ and random representers
\begin{equation}\label{eq:kappa}
\kappa_i(t) := \frac{D_t^W(M_{t_i})}{\sigma_t} = \mathbf{1}_{[0,t_i]}(t) + \frac{1}{\sigma_t}\int_0^{t_i} D_t^W(\sigma_s)\,dW_s.
\end{equation}
When $\sigma$ is deterministic, $D_t^W(\sigma_s) = 0$ for all $s$, so $\kappa_i(t) = \mathbf{1}_{[0,t_i]}(t)$: the standard deterministic representers.

following_proof:
\emph{Step 1: IBP with a quadratic test function.} Take $n = 1$, $\xi_1 = M_T$, and $f(x) = x^2$. Since $f \notin C_b^\infty$, approximate by $f_\varepsilon(x) := x^2 e^{-\varepsilon x^2}$ with $f_\varepsilon \in C_b^\infty$. The IBP gives $\E[f_\varepsilon(M_T) \cdot \delta_M(u)] = \E[f_\varepsilon'(M_T) \cdot \langle \kappa_1, u \rangle_{\HM}]$. Since $M_T \in L^4(\Omega)$ (by Assumption~\ref{ass:sv} and the Burkholder--Davis--Gundy inequality), pass $\varepsilon \to 0$ by dominated convergence:
\begin{equation}\label{eq:obstr_IBP}
\E[M_T^2 \cdot \delta_M(u)] = 2\,\E[M_T \cdot \langle \kappa_1, u \rangle_{\HM}].
\end{equation}

\emph{Step 2: Expand the left side.} By It\^o's formula, $M_T^2 = 2\int_0^T M_t\,dM_t + \langle M \rangle_T$. Using adjointness:
\begin{align}
\E[M_T^2 \cdot \delta_M(u)] &= \E\!\left[\left(2\int_0^T M_t\,dM_t + \langle M \rangle_T\right) \delta_M(u)\right] \notag \\
&= 2\,\E\!\left[\int_0^T M_t\,u_t\,d\langle M \rangle_t\right] + \E[\langle M \rangle_T \cdot \delta_M(u)], \label{eq:obstr_left}
\end{align}
where the first term uses the isometry/adjointness: $\E[(\int M_t\,dM_t) \cdot \delta_M(u)] = \E[\langle M_\cdot, u \rangle_{\HM}] = \E[\int M_t u_t \sigma_t^2\,dt]$.

\emph{Step 3: Expand the right side.} Since $\kappa_1$ is deterministic: $\langle \kappa_1, u \rangle_{\HM} = \E[\int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt \mid \mathcal{P}]$. For predictable $u$ and deterministic $\kappa_1$:
\begin{equation}\label{eq:obstr_right}
2\,\E[M_T \cdot \langle \kappa_1, u \rangle_{\HM}] = 2\,\E\!\left[M_T \int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt\right].
\end{equation}

\emph{Step 4: Equate and extract.} Combining~\eqref{eq:obstr_IBP},~\eqref{eq:obstr_left},~\eqref{eq:obstr_right}:
\[
2\,\E\!\left[\int_0^T M_t\,u_t\,\sigma_t^2\,dt\right] + \E[\langle M \rangle_T \cdot \delta_M(u)] = 2\,\E\!\left[M_T \int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt\right].
\]
Rearranging: $\E[\langle M \rangle_T \cdot \delta_M(u)] = 2\,\E[\int_0^T (M_T \kappa_1(t) - M_t)\,u_t\,\sigma_t^2\,dt]$.

By adjointness, $\E[\langle M \rangle_T \cdot \delta_M(u)] = \E[\langle D_M(\langle M \rangle_T), u \rangle_{\HM}] = \E[\int_0^T (D_M(\langle M \rangle_T))_t\,u_t\,\sigma_t^2\,dt]$. Since this holds for all predictable $u$:
\begin{equation}\label{eq:obstr_id}
(D_M(\langle M \rangle_T))_t = 2(M_T \kappa_1(t) - M_t) \qquad dt \otimes dP\text{-a.e.}
\end{equation}

\emph{Step 5: Contradiction.} Via the Malliavin derivative of the underlying Brownian motion:
\[
(D_M(\langle M \rangle_T))_t = \frac{D_t^W(\langle M \rangle_T)}{\sigma_t} = \frac{D_t^W(\int_0^T \sigma_s^2\,ds)}{\sigma_t} = \frac{2\int_0^T \sigma_s\,D_t^W(\sigma_s)\,ds}{\sigma_t}.
\]
If $\kappa_1$ is deterministic, then the right side of~\eqref{eq:obstr_id} is $2(M_T \kappa_1(t) - M_t)$: a function of $(M_T, M_t, t)$ that is linear in $M_T$ and $M_t$. But the left side is $2\sigma_t^{-1}\int_0^T \sigma_s D_t^W(\sigma_s)\,ds$: a functional of the entire Brownian path through the Malliavin derivative of $\sigma$.

