Under Assumption~\ref{ass:sv}, $D_M$ on $\HM^{\mathrm{ext}}$ satisfies the Leibniz rule: for $F, G \in \mathbb{D}^{1,2} \cap L^4(\Omega)$,
\begin{equation}\label{eq:leib_sv}
D_M(FG) = F\,D_M G + G\,D_M F \qquad \text{in } L^2(\Omega; \HM^{\mathrm{ext}}).
\end{equation}

\label{prop:rand_cyl}
$(\delta_M^{\mathrm{ext}}, \HM^{\mathrm{ext}})$ admits a cylindrical structure (Definition~\ref{def:cyl}) with coordinates $\xi_i = M_{t_i}$ and random representers
\begin{equation}\label{eq:kappa}
\kappa_i(t) := \frac{D_t^W(M_{t_i})}{\sigma_t} = \mathbf{1}_{[0,t_i]}(t) + \frac{1}{\sigma_t}\int_0^{t_i} D_t^W(\sigma_s)\,dW_s.
\end{equation}
When $\sigma$ is deterministic, $D_t^W(\sigma_s) = 0$ for all $s$, so $\kappa_i(t) = \mathbf{1}_{[0,t_i]}(t)$: the standard deterministic representers.

following_proof:
\emph{Step 1: IBP with a quadratic test function.} Take $n = 1$, $\xi_1 = M_T$, and $f(x) = x^2$. Since $f \notin C_b^\infty$, approximate by $f_\varepsilon(x) := x^2 e^{-\varepsilon x^2}$ with $f_\varepsilon \in C_b^\infty$. The IBP gives $\E[f_\varepsilon(M_T) \cdot \delta_M(u)] = \E[f_\varepsilon'(M_T) \cdot \langle \kappa_1, u \rangle_{\HM}]$. Since $M_T \in L^4(\Omega)$ (by Assumption~\ref{ass:sv} and the Burkholder--Davis--Gundy inequality), pass $\varepsilon \to 0$ by dominated convergence:
\begin{equation}\label{eq:obstr_IBP}
\E[M_T^2 \cdot \delta_M(u)] = 2\,\E[M_T \cdot \langle \kappa_1, u \rangle_{\HM}].
\end{equation}

\emph{Step 2: Expand the left side.} By It\^o's formula, $M_T^2 = 2\int_0^T M_t\,dM_t + \langle M \rangle_T$. Using adjointness:
\begin{align}
\E[M_T^2 \cdot \delta_M(u)] &= \E\!\left[\left(2\int_0^T M_t\,dM_t + \langle M \rangle_T\right) \delta_M(u)\right] \notag \\
&= 2\,\E\!\left[\int_0^T M_t\,u_t\,d\langle M \rangle_t\right] + \E[\langle M \rangle_T \cdot \delta_M(u)], \label{eq:obstr_left}
\end{align}
where the first term uses the isometry/adjointness: $\E[(\int M_t\,dM_t) \cdot \delta_M(u)] = \E[\langle M_\cdot, u \rangle_{\HM}] = \E[\int M_t u_t \sigma_t^2\,dt]$.

\emph{Step 3: Expand the right side.} Since $\kappa_1$ is deterministic: $\langle \kappa_1, u \rangle_{\HM} = \E[\int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt \mid \mathcal{P}]$. For predictable $u$ and deterministic $\kappa_1$:
\begin{equation}\label{eq:obstr_right}
2\,\E[M_T \cdot \langle \kappa_1, u \rangle_{\HM}] = 2\,\E\!\left[M_T \int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt\right].
\end{equation}

\emph{Step 4: Equate and extract.} Combining~\eqref{eq:obstr_IBP},~\eqref{eq:obstr_left},~\eqref{eq:obstr_right}:
\[
2\,\E\!\left[\int_0^T M_t\,u_t\,\sigma_t^2\,dt\right] + \E[\langle M \rangle_T \cdot \delta_M(u)] = 2\,\E\!\left[M_T \int_0^T \kappa_1(t)\,u_t\,\sigma_t^2\,dt\right].
\]
Rearranging: $\E[\langle M \rangle_T \cdot \delta_M(u)] = 2\,\E[\int_0^T (M_T \kappa_1(t) - M_t)\,u_t\,\sigma_t^2\,dt]$.

By adjointness, $\E[\langle M \rangle_T \cdot \delta_M(u)] = \E[\langle D_M(\langle M \rangle_T), u \rangle_{\HM}] = \E[\int_0^T (D_M(\langle M \rangle_T))_t\,u_t\,\sigma_t^2\,dt]$. Since this holds for all predictable $u$:
\begin{equation}\label{eq:obstr_id}
(D_M(\langle M \rangle_T))_t = 2(M_T \kappa_1(t) - M_t) \qquad dt \otimes dP\text{-a.e.}
\end{equation}

\emph{Step 5: Contradiction.} Via the Malliavin derivative of the underlying Brownian motion:
\[
(D_M(\langle M \rangle_T))_t = \frac{D_t^W(\langle M \rangle_T)}{\sigma_t} = \frac{D_t^W(\int_0^T \sigma_s^2\,ds)}{\sigma_t} = \frac{2\int_0^T \sigma_s\,D_t^W(\sigma_s)\,ds}{\sigma_t}.
\]
If $\kappa_1$ is deterministic, then the right side of~\eqref{eq:obstr_id} is $2(M_T \kappa_1(t) - M_t)$: a function of $(M_T, M_t, t)$ that is linear in $M_T$ and $M_t$. But the left side is $2\sigma_t^{-1}\int_0^T \sigma_s D_t^W(\sigma_s)\,ds$: a functional of the entire Brownian path through the Malliavin derivative of $\sigma$.

To make the contradiction precise: take $u_t = \varepsilon^{-1}\mathbf{1}_{[s, s+\varepsilon]}(t)$ for fixed $s \in (0,T)$ and send $\varepsilon \to 0$. The identity~\eqref{eq:obstr_id} becomes pointwise:
\[
\frac{2\int_0^T \sigma_r D_s^W(\sigma_r)\,dr}{\sigma_s} = 2(M_T \kappa_1(s) - M_s).
\]
The right side is $\mathcal{F}_T^M$-measurable with specific dependence on $M_T$ and $M_s$. The left side depends on $D_s^W(\sigma_r)$ for all $r \in [0,T]$, which is a functional of the entire Brownian path. For stochastic $\sigma$ (e.g., $d\sigma = a(\sigma)\,dW$ with $a \neq 0$), $D_s^W(\sigma_r) \neq 0$ generically, and the left side cannot equal a linear function of $(M_T, M_s)$. In particular, taking $\E[\cdot \mid M_T, M_s]$ on both sides: the right side is unchanged, but the left side involves $\E[\sigma_r D_s^W(\sigma_r) \mid M_T, M_s]$, which depends on the entire conditional structure of $\sigma$ given $M$---not just on $(M_T, M_s)$. This is a contradiction unless $D_s^W(\sigma_r) = 0$ a.e., i.e., $\sigma$ is deterministic.

