\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$, satisfying
$\|\Delta_{\mathrm{metric}}\|\le\theta_*^2/2$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction vanishes in the
Bakry--\'Emery curvature:
\begin{equation}\label{eq:cancel}
\langle\xi,\Delta_{\mathrm{Chr}}(\theta_0)\,\xi\rangle=0
\qquad\forall\,\xi\in\su(2),\;\forall\,\theta_0.
\end{equation}

\label{cor:curvature}
For $\theta_*<0.94$\,rad ($53.9^\circ$):
\begin{equation}\label{eq:kappa}
\kappa_B(\xi,\xi)
\ge\Bigl[\frac{1}{2}+\beta\bigl(\lambda_{\min}\cos\theta_*
-C\theta_*^2\bigr)\Bigr]|\xi|^2
\ge\Bigl[\frac{1}{2}+\beta\cdot 0.632\Bigr]|\xi|^2>0.
\end{equation}
The bound is quadratic in $\theta_*$ rather than linear, because the
Christoffel term that would contribute $O(\theta_*)$ is absent.

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue \emph{increases} under blocking:
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The antisymmetry cancellation (Theorem~\ref{thm:antisym}) is preserved
under the Schur complement:
\begin{equation}
\langle\xi,\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\,\xi\rangle=0
\qquad\forall\,\xi\in\su(2),
\end{equation}
where $\Delta_{\mathrm{Chr}}^{\mathrm{eff}}$ is the Christoffel
correction to the non-abelian Schur complement.

\label{cor:NAschur}
$H_{\mathrm{eff}}^{\mathrm{NA}}=H_{\mathrm{eff}}^{\mathrm{ab}}
+O(\theta_*^2)$, with no $O(\theta_*)$ correction.

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_k d(X)}$ for connected
regions $X$, with exponential spatial decay.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=7.916/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma=\sqrt{\lambda_{\min}}=0.830$.
\end{enumerate}

\label{lem:activity}
$|\zeta(X)|\le(C_0\theta_*^2/\lambda_{\min})^{|X|}
\cdot e^{-(\beta\lambda_{\min}/4)\delta(X)}$.

\label{thm:cluster}
The polymer expansion converges absolutely whenever the
Koteck\'y--Preiss condition~\cite{KP} holds:
\begin{equation}
\theta_*<\theta_c
=\sqrt{e^{-1}}\cdot\lambda_{\min}=0.418\;\mathrm{rad}
\approx 24.0^\circ.
\end{equation}
This is satisfied for $\beta\ge 100$ with the Balaban small-field
cutoff $\theta_*=(-\log g_k^2)^{1/2}\cdot g_k$.

The cluster expansion remainder is
\begin{equation}\label{eq:remainder}
|E^{\mathrm{small}}(X)|\le C\cdot(4/\beta)^2\cdot e^{-\kappa\,d(X)},
\qquad\kappa=0.83.
\end{equation}
This is $O(g^4)=O(1/\beta^2)$, two powers of $g$ better than the
generic $O(g^2)$.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr)
=\exp(-0.0861\,\beta).
\end{equation}

\label{thm:largefield}
For $\beta\ge 35$:
\begin{equation}
|E^{\mathrm{large}}|\le 20\cdot e^{-0.043\beta}=O(e^{-c\beta}).
\end{equation}

\label{thm:singlestep}
For $\beta_k\ge 100$, the effective action after one blocking step is
\begin{equation}
S_{k+1}(\eta)=\beta_{k+1}\sum_p(1-\tfrac{1}{2}\tr\,V_p)+E_{k+1}(\eta),
\end{equation}
with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}=\beta_k-8b_0\log 2+O(1/\beta_k)$
(asymptotic freedom);
\item $|E_{k+1}(X)|\le C(4/\beta_k)^2 e^{-0.83\,d(X)}$
(localized remainder);
\item gauge invariance on the coarse lattice.
\end{enumerate}
These bounds are stable under iteration for $\beta_k\ge 35$.

