For a smooth NS solution $u(t)$ on $\T^3$, define
the shell-level enstrophy in sector~$j$ at shell~$r$:
\begin{equation}
E_j^{(r)}(t) := \sum_{k\in\Omega_j\cap S_r}
|k|^2|\hat u(k,t)|^2.
\end{equation}
The shell enstrophy is $E(r) = \sum_j E_j^{(r)}$,
the shell sector fraction is $p_j^{(r)} = E_j^{(r)}/E(r)$,
and the shell angular variance is
$\mathcal{V}(r) = \sum_j(p_j^{(r)}-1/J)^2$.

\label{prop:mode-enst}
For each mode $k\neq 0$:
\begin{equation}\label{eq:mode-enst}
\frac{1}{2}\frac{d}{dt}\bigl(|k|^2|\hat u(k)|^2\bigr)
= |k|^2\,\mathrm{Re}\bigl[\hat u^*(k)\cdot
\widehat{B(u,u)}(k)\bigr]
- \nu|k|^4|\hat u(k)|^2.
\end{equation}
Summing over $k\in\Omega_j\cap S_r$:
\begin{equation}\label{eq:sector-shell-enst}
\frac{d}{dt}E_j^{(r)} = F_j^{(r)} - 2\nu D_j^{(r)},
\end{equation}
where $F_j^{(r)} = 2\sum_{k\in\Omega_j\cap S_r}
|k|^2\,\mathrm{Re}[\hat u^*\cdot\widehat{B}(k)]$
is the nonlinear forcing into sector~$j$ at shell~$r$,
and $D_j^{(r)} = \sum_{k\in\Omega_j\cap S_r}
|k|^4|\hat u(k)|^2$ is the sector-shell palinstrophy.

\label{prop:excess-damping}
Define the sector-shell excess enstrophy
$\tilde E_j^{(r)} := E_j^{(r)} - E(r)/J$
(the deviation from the isotropic share).  Then:
\begin{equation}\label{eq:excess-evol}
\frac{d}{dt}\tilde E_j^{(r)}
= \tilde F_j^{(r)} - 2\nu\tilde D_j^{(r)},
\end{equation}
where $\tilde F_j^{(r)} = F_j^{(r)} - F(r)/J$
is the excess forcing (how much more sector~$j$
is forced than average) and
$\tilde D_j^{(r)} = D_j^{(r)} - D(r)/J$ is the
excess palinstrophy.

