\end{equation}
defined by
$\ip{D_{VL} F}{(u,h)} = \E[F \cdot \delta_{VL}(u,h)]$
for $F \in L^q(\Omega)$, $(u,h) \in \HH_{VL}$.

\label{prop:D-split}
$D_{VL} F = (D_W F,\, \widetilde{D}_J F)$, where
\begin{align}
