\item $C(f,p) = C_p^p \cdot \|f''\|_\infty^p / 2^p$
  is the small-jump coefficient.
\item $R(f,T,p)$ is the large-jump remainder:
  $R = C'\,T\!\int_{|z|>1}(1+|z|^p)\nu(dz)$, which is
  finite under~\ref{L2} with $q \geq p$.
\end{itemize}
