Let $E_0<E_1$ be the two lowest eigenvalues of $PHP$ and let $E_Q^{\min}=\min_{s\in Q\mathcal{H}}E(s)$. If
\begin{equation}\label{eq:feshbach_condition}
\frac{g^2}{2}\,E_Q^{\min} > E_1,
\end{equation}
then
\begin{equation}\label{eq:feshbach_bound}
\mathrm{gap}(H) \ge \mathrm{gap}(PHP) - \frac{2\,\|QBP\|^2}{g^4\bigl(\frac{g^2}{2}\,E_Q^{\min}-E_1\bigr)}.
\end{equation}

\label{thm:vac_gap}
For the $j_{\max}=1$ Hamiltonian restricted to the $(+,+,+)$~holonomy sector on the $2^3$~torus:
\begin{equation}
\mathrm{gap}_{(+,+,+)}(g^2) > 0 \qquad \text{for all } g^2 > 0.
\end{equation}

\label{thm:full_gap}
For the untruncated Hamiltonian
\begin{equation}
H(g^2) = \frac{g^2}{2}\sum_\ell j_\ell(j_\ell+1) - \frac{1}{g^2}\sum_p B_p,
\end{equation}
restricted to the $(+,+,+)$~holonomy sector on the $2^3$~torus:
\begin{equation}
\mathrm{gap}_{(+,+,+)}(g^2) > 0 \qquad \text{for all } g^2 > 0.
\end{equation}

\label{thm:strong}
For SU(2) lattice gauge theory on $\Z^4$ with the Wilson action, the mass gap satisfies $m(\beta)>0$ for all $\beta\in(0,4.6)$, with the quantitative lower bound
\begin{equation}
m(\beta) \ge 4\,m_0(\beta) - \log\bigl(1+3\,\alpha_{1/2}(\beta)^4\bigr),
\end{equation}
where $m_0=-\log\alpha_{1/2}$ and $\alpha_{1/2}(\beta)=I_2(\beta)/I_1(\beta)$ is the fundamental character expansion coefficient.

\label{thm:continuum}
In the continuum limit (taken along a renormalization group trajectory at $\beta\ge 35$), the physical mass gap satisfies
\begin{equation}
m_{\mathrm{phys}} \ge c\,\Lambda > 0,
\end{equation}
where $\Lambda$ is the dynamically generated scale and $c>0$ is an explicit constant.

The \emph{closed-surface growth constant} $\mu_{\mathrm{cs}}$ is defined by
\begin{equation}
\mu_{\mathrm{cs}} = \limsup_{n\to\infty} N(n)^{1/n},
\end{equation}
where $N(n)$ is the number of connected contractible closed surfaces of size~$n$ containing a fixed plaquette~$p$.

following_proof:
We bound $N(n)$ using a \emph{cube-tree construction}. Every connected closed surface can be built by sequentially attaching cube boundaries: start with one of the $4$ cubes containing~$p$, then iteratively attach cubes sharing a face with the existing surface. Each cube contributes approximately $5$~new plaquettes (6 total minus 1 shared face) and offers at most $6$ attachment sites for the next cube (its 6 faces). A tree of $k$~cubes therefore has at most $6^k$ distinct shapes and contributes $n\approx 5k$~plaquettes. Hence
\begin{equation}
N(n) \le C\cdot 6^{n/5}
\end{equation}
for a constant $C>0$, giving $\mu_{\mathrm{cs}}\le 6^{1/5}$.

statement:
\label{thm:KP}
If there exists a function $a:\{\text{polymers}\}\to[0,\infty)$ such that for every polymer~$\gamma$,
\begin{equation}\label{eq:KP}
\sum_{\gamma'\not\sim\gamma}|w(\gamma')|\,e^{a(\gamma')} \le a(\gamma),
\end{equation}
then the polymer expansion (and hence the cluster expansion for $\log Z$) converges absolutely.

following_proof:
Choose $a(S)=a\cdot|S|$ for a constant $a>0$ to be optimized. Using exact counts for $|S|\le 10$ and the growth bound $N(n)\le\mu_{\mathrm{cs}}^n$ for $n\ge 12$, the Koteck\'y--Preiss condition \eqref{eq:KP} becomes
\begin{equation}
4\cdot N(6)\,\alpha^6\,e^{6a} + 4\cdot N(10)\,\alpha^{10}\,e^{10a} + \frac{4\,(\mu_{\mathrm{cs}}\,\alpha\,e^a)^{12}}{1-\mu_{\mathrm{cs}}\,\alpha\,e^a} \le a,
\end{equation}
where $\alpha=\alpha_{1/2}(\beta)$. At $a=0$, the leading condition is $\mu_{\mathrm{cs}}\cdot\alpha<1$, which gives $\alpha<1/1.431=0.699$, i.e., $\beta<4.62$.\qed

statement:
\label{thm:mass_gap_strong}
For $\beta\in(0,4.6)$, the mass gap satisfies
\begin{equation}\label{eq:mass_bound}
m(\beta) \ge 4\,m_0(\beta) - \log\bigl(1+3\,\alpha_{1/2}(\beta)^4\bigr),
\end{equation}
where $m_0=-\log\alpha_{1/2}$ is the single-plaquette mass and the logarithmic correction accounts for the entropy of bent tubes (at most 3 bending directions per step, each costing 4 additional plaquettes).

following_proof:
The connected correlator satisfies
\begin{equation}
\langle O(0)\,O(x)\rangle_c \le \sum_{\substack{S:\,\partial S=\partial p_0+\partial p_x \\ S\text{ connected}}} w(S),
\end{equation}
where the inequality uses $w(S)>0$ and $Z\ge 1$. The minimum-size term is the straight 4-wall tube of size $4d$, contributing $4\,\alpha^{4d}$. Bent tubes of length $4d+4b$ (with $b$ bends) contribute at most $\binom{d}{b}\,3^b\,\alpha^{4b}$ additional weight per unit of the straight-tube weight. Summing:
\begin{equation}
\sum_{\text{tube shapes}}\alpha^{4|\text{tube}|} \le \bigl[\alpha^4(1+3\alpha^4)\bigr]^d.
\end{equation}
The convergence of the full surface sum (including non-tube surfaces) is guaranteed by Proposition~\ref{prop:convergence} for $\mu_{\mathrm{cs}}\cdot\alpha<1$, ensuring $m\ge -\log[\alpha^4(1+3\alpha^4)] = 4m_0-\log(1+3\alpha^4)$.\qed

statement:
\label{thm:peierls}
For $\beta\ge 5.0$, the mass gap satisfies $m(\beta)>0$, with
\begin{equation}
m(\beta) \ge \mu_{\mathrm{surf}} - \log 7,
\end{equation}
where $\mu_{\mathrm{surf}}(\beta)$ is the optimized surface tension per unit area of the Peierls defect contour, and $7$ is the growth constant for connected plaquette clusters on the spatial (3D) plaquette lattice.

\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ equation~\eqref{eq:rNG})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ equation~\eqref{eq:rNG})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ equation~\eqref{eq:rNG})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ equation~\eqref{eq:rNG})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ equation~\eqref{eq:rNG})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ equation~\eqref{eq:rNG})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ equation~\eqref{eq:rNG})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ equation~\eqref{eq:rNG})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ equation~\eqref{eq:rNG})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{lem:nontriviality}
For every $\beta\ge\beta_0$, there exists a gauge-invariant
observable $\Phi$ on the lattice $a\Z^4$, localized in a
region of fixed physical size $\ell_*$, whose connected
two-point function satisfies
\begin{equation}\label{eq:nontriviality-lemma}
\langle\Phi(X_1^*)\,\Phi(X_2^*)\rangle_{\mu_\beta,c}
\ge\frac{0.01093\,[\varphi(0)]^2}{\beta_*^2}>0,
\end{equation}
uniformly in $a$, where $X_1^*,X_2^*\in\ell_*\Z^4$ are
adjacent coarse vertices (at separation $\ell_*$) and
$\varphi(0)>0$ is the value at the origin of the bump
function $\varphi$ used in~\eqref{eq:Phi-def}.

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{lem:nontriviality}
For every $\beta\ge\beta_0$, there exists a gauge-invariant
observable $\Phi$ on the lattice $a\Z^4$, localized in a
region of fixed physical size $\ell_*$, whose connected
two-point function satisfies
\begin{equation}\label{eq:nontriviality-lemma}
\langle\Phi(X_1^*)\,\Phi(X_2^*)\rangle_{\mu_\beta,c}
\ge\frac{0.01093\,[\varphi(0)]^2}{\beta_*^2}>0,
\end{equation}
uniformly in $a$, where $X_1^*,X_2^*\in\ell_*\Z^4$ are
adjacent coarse vertices (at separation $\ell_*$) and
$\varphi(0)>0$ is the value at the origin of the bump
function $\varphi$ used in~\eqref{eq:Phi-def}.

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{lem:nontriviality}
For every $\beta\ge\beta_0$, there exists a gauge-invariant
observable $\Phi$ on the lattice $a\Z^4$, localized in a
region of fixed physical size $\ell_*$, whose connected
two-point function satisfies
\begin{equation}\label{eq:nontriviality-lemma}
\langle\Phi(X_1^*)\,\Phi(X_2^*)\rangle_{\mu_\beta,c}
\ge\frac{0.0468\,[\varphi(0)]^2}{\beta_*^2}>0,
\end{equation}
uniformly in $a$, where $X_1^*,X_2^*\in\ell_*\Z^4$ are
adjacent coarse vertices (at separation $\ell_*$) and
$\varphi(0)>0$ is the value at the origin of the bump
function $\varphi$ used in~\eqref{eq:Phi-def}.

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{lem:nontriviality}
For every $\beta\ge\beta_0$, there exists a gauge-invariant
observable $\Phi$ on the lattice $a\Z^4$, localized in a
region of fixed physical size $\ell_*$, whose connected
two-point function satisfies
\begin{equation}\label{eq:nontriviality-lemma}
\langle\Phi(X_1^*)\,\Phi(X_2^*)\rangle_{\mu_\beta,c}
\ge\frac{0.0468\,[\varphi(0)]^2}{\beta_*^2}>0,
\end{equation}
uniformly in $a$, where $X_1^*,X_2^*\in\ell_*\Z^4$ are
adjacent coarse vertices (at separation $\ell_*$) and
$\varphi(0)>0$ is the value at the origin of the bump
function $\varphi$ used in~\eqref{eq:Phi-def}.

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

%
\label{prop:global-poincare}
Consider the Glauber dynamics generator
$\mathcal{L}f(U)=\sum_\ell(E_\ell[f]-f)$,
where $E_\ell[f](U)=\int_{\SU(2)}f(U'_\ell,U_{\neq\ell})\,
d\mu_\ell(U'_\ell)$ is the single-site conditional expectation.
Define the \emph{Dobrushin interdependence matrix}
$C=(C_{\ell\ell'})$ by
\begin{equation}\label{eq:dobrushin}
C_{\ell\ell'}=\sup_{U,\tilde{U}:\,U_j=\tilde{U}_j\;\forall j\ne\ell'}
\|\mu_\ell(\cdot\,|\,U_{\neq\ell})
-\mu_\ell(\cdot\,|\,\tilde{U}_{\neq\ell})\|_{\mathrm{TV}},
\end{equation}
measuring how much the conditional at~$\ell$ depends on the
value at~$\ell'$.

If (i)~$\kappa_\ell\ge\kappa>0$ for all~$\ell$
(Proposition~\ref{prop:single-site-BE}),
and (ii)~$\|C\|_\infty:=\sup_\ell\sum_{\ell'}C_{\ell\ell'}<1$,
then the global Gibbs measure $\mu_\beta$ satisfies
\begin{equation}\label{eq:global-poincare}
\mathrm{Var}_{\mu_\beta}(f)
\le\frac{1}{\kappa(1-\|C\|_\infty)^2}
\sum_\ell\int\mathrm{Var}_{\mu_\ell}(f)\,d\mu_\beta.
\end{equation}

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition used in the
Clay Millennium Problem statement~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

\label{thm:Tt}
The mass gap of the temporal transfer matrix $T_t$ on $(\Z/L\Z)^3$
with $L\ge 2$ is
\begin{equation}\label{eq:mTt}
m_t(\beta)=-\log\frac{\lambda_1}{\lambda_0}
=-4\log\frac{I_2(\beta)}{I_1(\beta)}>0
\qquad\text{for all }\beta\in(0,\infty).
\end{equation}

\label{lem:bessel}
For all $x>0$ and $\nu>\mu\ge 0$:
\begin{equation}\label{eq:bessel-ineq}
I_\nu(x)<I_\mu(x).
\end{equation}
In particular, $\alpha_j(\beta)=I_{2j+1}(\beta)/I_1(\beta)<1$ for
all $j>0$ and all $\beta>0$.

\label{lem:mt-monotone}
The function $\beta\mapsto m_t(\beta)=-4\log[I_2(\beta)/I_1(\beta)]$
is strictly positive and strictly decreasing on $(0,\infty)$, with
\begin{equation}
m_t(\beta)\sim\frac{6}{\beta}\qquad(\beta\to\infty),
\qquad m_t(\beta)\to+\infty\qquad(\beta\to 0^+).
\end{equation}

\label{thm:Ts}
For $\SU(2)$ Wilson lattice gauge theory on $(\Z/L\Z)^3\times\Z$
with $L\ge 2$, the mass gap of the full transfer matrix
$T=T_s^{1/2}\,T_t\,T_s^{1/2}$ satisfies
\begin{equation}\label{eq:full-gap}
m(\beta,L)>0\qquad\text{for all }\beta>0,\;L\ge 2.
\end{equation}

\label{syn-thm:fsc}
For any compact simple Lie group~$G$, $d \geq 2$, and
any $\beta > 0$,
the block conditional measure has a strictly positive
spectral gap: $\gap(\mu_Q(\cdot|\Phi,\beta)) > 0$.

For $d \geq 3$, assuming
Conjecture~\ref{syn-conj:unique_min}
\textup{(}proved for $G = U(1)$;
numerically verified for $G = \SU(2)$\textup{)},
the lattice Yang--Mills theory satisfies the
Dobrushin--Shlosman finite size criterion $\mathrm{FSC}(2)$:
for every $2$-cube $Q$ and every boundary condition~$\Phi$,
\begin{equation}\label{syn-eq:fsc}
  \gap\!\bigl(\mu_Q(\cdot \mid \Phi)\bigr)
  \;\geq\; c_B(G) \;>\; 0,
\end{equation}
where $c_B$ depends only on~$G$, not on $\beta$ or~$\Phi$.
Consequently, the Gibbs measure is unique and
$m(\beta) \cdot a > 0$ for each~$\beta$.

\label{syn-prop:dobrushin}
Define $\beta_c(d)$ as the unique positive solution of
\begin{equation}\label{syn-eq:threshold}
  6(d{-}1)\bigl(1 - e^{-2\beta_c}\bigr) = 1.
\end{equation}
For all $\beta < \beta_c$, the Wilson measure on any finite
volume~$\Lambda$ with any boundary condition satisfies
a volume-uniform log-Sobolev inequality with constant
\begin{equation}
  \rho_\Lambda(\beta) \;\geq\;
  \rho_G\,e^{-4(d-1)\beta}
  \cdot\bigl(1 - 6(d{-}1)(1 - e^{-2\beta})\bigr)
  \;>\; 0.
\end{equation}

\label{syn-prop:perturbed_dob}
Under (B1)--(B4) (Theorem~\ref{syn-thm:eac}), for $\beta$ sufficiently
large, the effective measure~$\mu_{k_*}$ has a strictly positive
mass gap
\begin{equation}
  m(\beta_*) \;\geq\;
  \frac{m_0 - C\,\varepsilon_{k_*}}{\ell_*}
  \;>\; 0,
\end{equation}
where $m_0 = 0.0067$ is the RP mass gap
\textup{(the RP spectral gap proposition)} and
$\varepsilon_{k_*} = C_{\mathrm{acc}}(4/150)^2
\ll m_0$.

\label{syn-thm:entropy}
For $\beta$ sufficiently large, the relative entropy
$W_k = \KL(\mu_k \| \nu_k)$ satisfies
\begin{equation}\label{syn-eq:entropy_decay}
  W_k \;\leq\; W_0 \;\leq\; \frac{C}{\beta^2}
\end{equation}
for all $k \geq 0$, where $C$ depends only on $d$,
$N$, $L$.

\label{syn-cor:U1}
For $G = U(1)$ in $d \geq 2$ dimensions:
\begin{enumerate}[label=\textup{(\alph*)},nosep]
  \item \textup{(Uniform block gap.)}
    The FSC$(2)$ condition holds unconditionally:
    $\gap(\mu_Q(\cdot|\Phi, \beta))
    \geq c_B(d) > 0$ uniformly in $\beta$ and~$\Phi$.
  \item \textup{(Mass gap for $d \leq 3$.)}
    For $d = 2$ and $d = 3$, compact $U(1)$ lattice gauge
    theory is confining for all~$\beta$, and the
    Dobrushin--Shlosman
    theorem~\cite{DobrushinShlosman,Martinelli1999}
    gives unique Gibbs measure and mass gap
    $m(\beta) \cdot a > 0$ for every $\beta > 0$.
\end{enumerate}
For $d = 2$, no assumptions beyond the definition of the
model are required.  For $d = 3$, the proof uses the
G\"opfert--Mack confinement theorem~\cite{GopfertMack82}
(a standard result in constructive gauge theory).

For a gauge-invariant local operator $\mathcal{O}$
of dimension~$\Delta_{\mathcal{O}}$
\textup{(}e.g.\ $\mathcal{O} = \tr F_{\mu\nu}^2$\textup{)},
define the renormalized Schwinger functions
$G_R^{(n)} = Z_{\mathcal{O}}^n \cdot G_{\mathrm{bare}}^{(n)}$
and the dimensionless four-point coupling
\begin{equation}\label{syn-eq:lambda4}
  \lambda_4
  \;:=\; \frac{G_{R,\mathrm{conn}}^{(4)}(p_1,\ldots,p_4)}
  {\bigl[G_R^{(2)}(p_1)\bigr]^2}
  \bigg|_{|p_i| = \mu},
\end{equation}
evaluated at a common momentum scale~$\mu$.

following_proof:
\textbf{Step~1: Perturbative contribution.}
At a perturbative scale $\mu \gg \Lambda_{\mathrm{QCD}}$,
the connected four-point function of $\tr F^2$ is given
to leading order by one-loop gluon box and crossed
diagrams:
\begin{equation}\label{syn-eq:lambda4_pert}
  \lambda_4^{\mathrm{pert}}(\mu)
  = c_1\,g(\mu)^4 + c_2\,g(\mu)^6 + \cdots
\end{equation}
with $c_1 \neq 0$ (an explicit, computable constant
depending on the external kinematics and the gauge group).
This is a standard perturbative calculation~\cite{Seiler82}.

\smallskip
\textbf{Step~2: Non-perturbative bound.}
By the Dobrushin analyticity proposition (cluster expansion
analyticity at the matching scale), the polymer expansion
bounds~(B1--B4) transfer to individual Schwinger functions.
The non-perturbative contribution satisfies:
\begin{equation}
  |\lambda_4 - \lambda_4^{\mathrm{pert}}|
  \;\leq\; C\,e^{-c/g(\mu)^2}.
\end{equation}
Along the asymptotic freedom trajectory at
scale~$\mu$: $g(\mu)^2 = 1/(2\beta_0 \log(\mu
/\Lambda_{\mathrm{QCD}}))$.  For
$\mu = R\,\Lambda_{\mathrm{QCD}}$ with $R$ large:
\begin{equation}
  e^{-c/g(\mu)^2}
  = e^{-2c\beta_0\,\log R}
  = R^{-2c\beta_0}.
\end{equation}
For $\SU(2)$ with $c = 8\pi^2/N$:
$2c\beta_0 \approx 3.67$, so the non-perturbative
correction decays as $R^{-3.67}$.

\smallskip
\textbf{Step~3: Perturbative dominance.}
Choose $R$ large enough that
$C\,R^{-3.67} < \tfrac{1}{2}\,|c_1|\,g(R\Lambda)^4$.
Since $g(R\Lambda)^4 \sim 1/(\log R)^2$ decays only
logarithmically while $R^{-3.67}$ decays as a power,
such $R$ exists.  At this scale:
\begin{equation}
  |\lambda_4| \;\geq\;
  |c_1|\,g^4 - C\,e^{-c/g^2}
  \;>\; \tfrac{1}{2}\,|c_1|\,g^4 \;>\; 0.
\end{equation}

\smallskip
\textbf{Step~4: Continuum limit.}
By Proposition~\ref{syn-thm:unique}(b), the renormalized
Schwinger functions converge as $a \to 0$.  By
Lemma~\ref{syn-lem:lambda4_rg}, $\lambda_4$ is
RG-invariant (the $Z$-factors cancel).  Therefore the
continuum value equals the lattice value at any scale:
\begin{equation}
  \lambda_4^{\mathrm{cont}}
  = \lim_{a \to 0} \lambda_4^{\mathrm{latt}}(a)
  = \lambda_4(\mu)
  \;\neq\; 0.
\end{equation}
A generalized free field has
$G_{\mathrm{conn}}^{(4)} \equiv 0$, hence
$\lambda_4 = 0$.  Since $\lambda_4 \neq 0$,
the continuum theory is not free.

statement:
\label{syn-rem:os}
With reflection positivity established, the full set of
Osterwalder--Schrader axioms is
verified~\cite{OsterwalderSchrader}:
\textup{(OS0)}~temperedness (from exponential decay);
\textup{(OS1)}~Euclidean covariance (Remark~\ref{syn-rem:euclidean});
\textup{(OS2)}~reflection positivity (Proposition~\ref{syn-prop:rp});
\textup{(OS3)}~symmetry (bosonic fields);
\textup{(OS4)}~cluster property (exponential clustering from
mass gap).
By the OS reconstruction theorem, there exists a
Wightman QFT with positive Hamiltonian, unique vacuum, and
mass gap $\Delta > 0$.  This completes the proof of
Proposition~\ref{syn-thm:unique}(e)--(f).

\label{sun-def:structure}
The structure constants are defined by
\begin{equation}
[T_a,T_b]=if^{abc}T_c.\label{sun-eq:commutator}
\end{equation}
The symmetric tensor $d^{abc}$ is defined by
\begin{equation}\label{sun-eq:dabc}
d^{abc}=2\,\tr_R\bigl(\{T_a,T_b\}T_c\bigr).
\end{equation}
For $G=\SU(N)$, $\{I,T_a\}$ spans all
$N\times N$ Hermitian matrices, so the
anticommutator decomposes as
\begin{equation}\label{sun-eq:anticommutator}
\{T_a,T_b\}=\tfrac{1}{N}\delta_{ab}\,I
+d^{abc}T_c\qquad(G=\SU(N)).
\end{equation}

\label{sun-lem:alpha}
For any compact Lie group $G$ and any non-trivial
irreducible representation~$R'$:
\begin{equation}
0<\lambda_{R'}(\beta)<1\qquad
\text{for all }\beta\in(0,\infty).
\end{equation}
Moreover, $\lambda_{R'}$ is real-analytic, strictly
increasing, with $\lambda_{R'}(0)=0$ and
$\lim_{\beta\to\infty}\lambda_{R'}(\beta)=1$.

\label{sun-thm:full}
For any simple compact $G$ on
$(\Z/L\Z)^3\times\Z$ with $L\ge 2$:
\begin{equation}
m(\beta,L)>0\quad\text{for all }\beta>0,\;L\ge 2.
\end{equation}
For the thermodynamic limit: $m(\beta)>0$ for
$\beta<\beta_{\mathrm{SC}}(G)$ (strong coupling) and
for $\beta\ge\beta_0(G)$ (Peierls/RG).

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

