statement:
\label{def:Hyy}
The \emph{abelian Hessian} restricted to interior links is the
$32\times 32$ matrix
\begin{equation}\label{eq:Hyy}
(H_{yy})_{\ell\ell'}
=\sum_{\substack{p\in\mathcal{P}(B)\\\ell,\ell'\in p}}
\epsilon_\ell(p)\,\epsilon_{\ell'}(p),
\end{equation}
where $\mathcal{P}(B)$ is the set of 72 plaquettes touching $B$, and
$\epsilon_\ell(p)=+1$ if $\ell$ appears with positive orientation in
$p$ and $-1$ otherwise.

\label{def:NAhess}
The non-abelian Hessian at background field $\theta_0$ decomposes as
\begin{equation}\label{eq:NAdecomp}
H^{\mathrm{NA}}(\theta_0)
=H^{\mathrm{ab}}+\Delta_{\mathrm{metric}}(\theta_0)
+\Delta_{\mathrm{Chr}}(\theta_0),
\end{equation}
where:
\begin{enumerate}[nosep,label=(\roman*)]
\item $H^{\mathrm{ab}}$ is the abelian Hessian~\eqref{eq:Hyy};
\item $\Delta_{\mathrm{metric}}(\theta_0)$ is the metric correction
from $\cos\theta_p^0\ne 1$: $\Delta_{\mathrm{metric}}
=\sum_p(\cos\theta_p^0-1)\,P_p^T P_p$, satisfying the operator
inequality $\Delta_{\mathrm{metric}}\ge-(1-\cos\theta_*)\,H^{\mathrm{ab}}$;
\item $\Delta_{\mathrm{Chr}}(\theta_0)$ is the Christoffel correction
from the Baker--Campbell--Hausdorff formula.
\end{enumerate}

\label{thm:antisym}
For $G=\SU(2)$, the Christoffel correction satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item \textbf{Same-link vanishing:}
$(\Delta_{\mathrm{Chr}})_{(\ell,a),(\ell,b)}=0$ for all
$a,b$ and all links $\ell$.  The on-diagonal (single-link)
Christoffel contribution vanishes because
$\epsilon^{abc}\xi^b\xi^c=0$ for any fixed $\xi\in\su(2)$.
\item \textbf{Cross-link bound:}
The full Christoffel correction on the $2^4$ block satisfies
\begin{equation}\label{eq:chrbound}
\|\Delta_{\mathrm{Chr}}(\theta_0)\|
\le\tfrac{1}{2}\,\theta_0\cdot\|S_{\mathrm{block}}\|
=3.006\,\theta_0,
\end{equation}
where $\|S_{\mathrm{block}}\|=6.01$ is the operator norm of the
antisymmetric link-coupling matrix $S_{\mathrm{block}}$ summed over
the $24$ interior plaquettes.
\end{enumerate}

\label{def:schur}
The \emph{effective boundary Hessian} (Schur complement) is
\begin{equation}\label{eq:schur}
H_{\mathrm{eff}}=H_{\eta\eta}-H_{\eta y}\,H_{yy}^{-1}\,H_{y\eta},
\end{equation}
where $H_{yy}^{-1}$ denotes the pseudo-inverse (projecting out the
gauge zero mode).

\label{thm:schur}
The $80\times 80$ matrix $H_{\mathrm{eff}}$ has 46 zero eigenvalues
(boundary gauge modes) and 34 physical eigenvalues with:
\begin{equation}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964,\qquad
\lambda_{\max}(H_{\mathrm{eff}})=6.089.
\end{equation}
The degeneracy structure is:

\begin{center}
\begin{tabular}{cccccc}
\toprule
$\lambda$ & Mult. & $\lambda$ & Mult. & $\lambda$ & Mult.\\
\midrule
$0.6964$ & 3 & $0.8863$ & 3 & $3.6275$ & 2\\
$0.7446$ & 3 & $1.0000$ & 6 & $4.8390$ & 3\\
$0.8270$ & 2 & $2.7496$ & 3 & $6.0889$ & 3\\
$0.8378$ & 3 & $3.5358$ & 3 & &\\
\bottomrule
\end{tabular}
\end{center}

\label{thm:monotone}
The minimum physical eigenvalue of the effective boundary Hessian
(Schur complement, a $34$-dimensional operator on boundary modes)
exceeds the minimum physical eigenvalue of the interior Hessian
(a $31$-dimensional operator on interior modes):
\begin{equation}\label{eq:monotone}
\lambda_{\min}(H_{\mathrm{eff}})=0.6964
>\lambda_{\min}(H_{yy})=0.6893.
\end{equation}

\label{thm:antisym-scale}
The quantitative Christoffel bound (Theorem~\ref{thm:antisym}) is
preserved under the Schur complement: the effective Christoffel
correction satisfies
\begin{equation}
\|\Delta_{\mathrm{Chr}}^{\mathrm{eff}}\|
\le\tfrac{1}{2}\theta_*\cdot\|S_{\mathrm{eff}}\|,
\end{equation}
where $\|S_{\mathrm{eff}}\|\le\|S_{\mathrm{block}}\|+O(\theta_*^2)$.

\label{def:IH}
\begin{enumerate}[nosep,label=(IH\arabic*)]
\item \textbf{Coupling:}
The effective coupling $\beta_k$ satisfies $\beta_k\ge\beta_*=\beta_0$ (remains
in the weak/crossover regime).
\item \textbf{Hessian gap:}
The physical Hessian at scale $k$ has
$\lambda_{\min}(H_k)\ge\lambda_0>0$ on the small-field region.
\item \textbf{Remainder decay:}
The irrelevant part of the effective action satisfies
$|E_k(X)|\le(4/\beta_k)^{2\alpha}e^{-\kappa_0 d(X)}$ for connected
regions $X$, where $d(X)$ is the tree diameter, with $\kappa_0=1$ (the KP weight parameter,
Remark~\ref{rem:kappa-value}) and $\alpha=1$,
so the remainder is $O(g^4)$ since $g^2=4/\beta$.
The exponent $2\alpha=2$ rather than $2\alpha=1$
is essential: it ensures the remainder is smaller than the
$O(g^2)$ Wilson-form coupling shift by one power of $g^2$.
\item \textbf{Gauge invariance:}
$S_k$ is invariant under gauge transformations on the scale-$k$ lattice.
\end{enumerate}

%
\label{lem:pullback-hessian}
Let $y_*$ be a critical point of
$S(\cdot\,,\eta)$ on $\SU(2)^{32}$ (i.e.,
$\nabla_\ell S|_{y_*}=0$ for every interior link $\ell$).
Define the parametrization map $F:\R^{93}\to\SU(2)^{31}$ by
$F(\xi)_\ell=y_{*,\ell}\cdot\exp(i\iota(\xi)_\ell\cdot\sigma/2)$
for $\ell\ne\ell_0$, and $S_\Sigma=S\circ F$.
Then:
\begin{equation}\label{eq:hessian-pullback}
D^2 S_\Sigma|_{\xi=0}
=DF|_0^T\cdot D^2 S|_{y_*}\cdot DF|_0
\;+\;\underbrace{\sum_m\frac{\partial S}{\partial U_m}\bigg|_{y_*}
\cdot D^2 F_m|_0}_{=\,0\;\text{(criticality)}}.
\end{equation}
Moreover, $DF|_0=I_{93\times 93}$ (the identity on the physical
subspace), so
\begin{equation}\label{eq:Hphys-submatrix}
(H_{\mathrm{phys}})_{\ell\ell'}^{ab}
:=\bigl(D^2 S_\Sigma|_{\xi=0}\bigr)_{\ell\ell'}^{ab}
=\frac{\partial^2 S}{\partial\delta\theta_\ell^a\,
\partial\delta\theta_{\ell'}^b}\bigg|_{y_*}
\qquad(\ell,\ell'\ne\ell_0).
\end{equation}
That is, $H_{\mathrm{phys}}$ is the $93\times 93$
\emph{principal submatrix} of the full $96\times 96$ Hessian
$H$, obtained by deleting the 3~rows and 3~columns
corresponding to $\ell_0$.  No Schur complement, projected
operator, or orthogonal-complement identification is involved.

\label{prop:oneloop}
The Gaussian integral over physical modes yields
\begin{equation}\label{eq:1loop}
Z_B^{\mathrm{Gauss}}(\eta)=e^{-\beta S(y_*,\eta)}
\cdot\bigl(\tfrac{2\pi}{\beta}\bigr)^{93/2}
(\det H_{\mathrm{phys}})^{-3/2}
\cdot\bigl(1+O(\theta_*)\bigr),
\end{equation}
where $93=31\times 3$ counts physical modes ($31$~link modes, each
carrying 3~color components for $\su(2)$).

\label{prop:propagator}
The covariance $C$ satisfies:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\|C\|=1/(\beta\lambda_{\min})=1.451/\beta$;
\item $\tr C=\sum_{j=1}^{31}\lambda_j^{-1}/\beta=13.498/\beta$;
\item Exponential decay:
$|C(\ell,\ell')|\le(1.451/\beta)e^{-\gamma d(\ell,\ell')}$
with $\gamma\ge 0.81$ (Combes--Thomas).
\end{enumerate}
Within a single $2^4$ block (diameter~$2$), the precise value of
$\gamma$ is unimportant: the maximum distance between interior links
is~$2$, so $e^{-\gamma\cdot 2}\le e^{-1.62}=0.20$ for any pair.

%
\label{lem:centering}
In the gauge-fixed chart variables
$\{\delta\theta_\ell^a:\ell\ne\ell_0,\;a=1,2,3\}\in\R^{93}$,
the full block density has the form
\begin{equation}\label{eq:full-density}
\rho(\delta\theta)
=\underbrace{e^{-\beta S(y_*)}}_{\text{const}}
\cdot
\underbrace{e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}
\delta\theta}}_{\text{Gaussian (even)}}
\cdot
\underbrace{e^{-V_3(\delta\theta)-V_4(\delta\theta)-\cdots}}_
{W=\text{non-Gaussian}}
\cdot
\underbrace{\prod_{\ell\ne\ell_0}j(\delta\theta_\ell)}_
{\text{Haar Jacobian (even)}},
\end{equation}
with \emph{no linear term in the exponent}.  In particular,
the reference Gaussian $d\mu_C\propto
e^{-\frac{\beta}{2}\delta\theta^T H_{\mathrm{phys}}\delta\theta}
\,d^{93}\delta\theta$ is exactly centered at $\delta\theta=0$.

\label{def:polymer}
A \emph{polymer} $X$ is a connected subset of interior links of $B$.
Two polymers $X_1,X_2$ are \emph{compatible} ($X_1\sim X_2$) if they
share no common plaquette (i.e., no plaquette touches links in both
$X_1$ and $X_2$).

Let $\psi:\R_{\ge 0}\to[0,1]$ be smooth with $\psi(t)=1$ for $t\le 1$
and $\psi(t)=0$ for $t\ge 2$.  The \emph{cutoff non-Gaussian potential}
is
\begin{equation}
\widetilde{W}_X(\delta\theta)
=W_X(\delta\theta)\cdot\prod_{\ell\in X}\psi(|\delta\theta_\ell|),
\end{equation}
where $W_X=\sum_{n\ge 3}(\beta/n!)S_X^{(n)}(\delta\theta)$ is the
restriction of the non-Gaussian potential $W$ to plaquettes
touching~$X$ (cubic and higher Taylor remainder), and the product of
cutoffs ensures $\widetilde{W}_X$ is compactly supported and smooth
on $\R^{3|X|}$.  The \emph{activity} of $X$ is
\begin{equation}\label{eq:activity-def}
\zeta(X)=\int\prod_{\ell\in X}d\mu_C(\delta y_\ell)\;
\bigl[e^{-\widetilde{W}_X(\delta y)}-1\bigr].
\end{equation}

%
\label{thm:wilson-id}
The complete connected cluster sum at order $1/\beta$ equals
\begin{equation}\label{eq:full-wilson-id}
\sum_{\substack{X\text{ connected}\\X\ni\ell}}
\zeta(X)\Big|_{O(1/\beta)}
=\delta\beta^{\mathrm{total}}\cdot
\bigl(1-\tfrac{1}{2}\tr\,V_{p(\ell)}\bigr)
+R_\ell^{(4)},
\qquad |R_\ell^{(4)}|\le C\,(4/\beta)^2\,e^{-\kappa d(\ell)},
\end{equation}
where $\delta\beta^{\mathrm{total}}
=\delta\beta^{1\text{-loop}}+\delta\beta^{\mathrm{NG}}$
(Proposition~\ref{prop:betaeff} $+$ Lemma~\ref{lem:Q-bounded})
and the remainder is $O(g^4)$ with exponential locality.

\label{lem:polymer-count}
Let $G=(V,E)$ be the link-plaquette adjacency graph of the
$2^4$ block: vertices are the 32~interior links, and two
links are adjacent if they share a plaquette.  Define
$c_d=\max_{\ell\in V}\deg(\ell)$ (maximum degree in $G$).
Then the number of connected subgraphs of $G$ with
$n$~vertices containing a fixed vertex~$\ell$ satisfies
\begin{equation}\label{eq:polymer-count}
|\{Y\subset V: \ell\in Y,\;|Y|=n,\;
G[Y]\text{ connected}\}|
\le e\cdot c_d^{n-1}.
\end{equation}

%
\label{lem:wilson-form}
For any interior link $\ell$ in the $2^4$ block, the single-link
polymer activity $\zeta(\{\ell\})$ admits the decomposition
\begin{equation}\label{eq:wilson-decomp}
\zeta(\{\ell\})
=-\frac{\delta_\ell}{\beta}\sum_{p\ni\ell}
\bigl(1-\tfrac{1}{2}\tr\,V_p(\eta)\bigr)
+R_\ell(\eta),
\end{equation}
where $\delta_\ell=O(1)$ (an $\eta$-independent coefficient determined
by the spectrum of $H_{\mathrm{phys}}$), and the remainder satisfies
$|R_\ell(\eta)|\le C/\beta^2$ uniformly on the small-field region.

\label{thm:chess}
For $\SU(2)$ Wilson lattice gauge theory with the \emph{original}
Wilson action $S_W=\beta\sum_p(1-\frac{1}{2}\tr U_p)$
(not the effective action after RG), the probability that a single
plaquette has large angle satisfies:
\begin{equation}\label{eq:chess}
\mu_\beta(\theta_p>\theta_*)
\le\exp\bigl(-\beta(1-\cos\theta_*)\bigr).
\end{equation}
For $\theta_*=\pi/3$: $\mu_\beta(\theta_p>\pi/3)
\le\exp(-\beta/2)$.

\label{lem:conn}
In four dimensions, each plaquette has at most $c_{\mathrm{conn}}=20$
neighbors in the plaquette adjacency graph.

\label{thm:peierls}
The probability that a given plaquette belongs to a contour of size
$\ge n$ is bounded by
\begin{equation}
\mu_\beta(\text{defect contour of size}\ge n\text{ at }p)
\le\sum_{k\ge n}(c_{\mathrm{conn}})^k\cdot
e^{-k\beta(1-\cos\theta_*)}
=\frac{(20\,e^{-\beta(1-\cos\theta_*)})^n}
{1-20\,e^{-\beta(1-\cos\theta_*)}}.
\end{equation}
The expansion converges when
$20\,e^{-\beta(1-\cos\theta_*)}<1$, i.e.,
\begin{equation}
\beta>\frac{\log 20}{1-\cos\theta_*}.
\end{equation}

\label{thm:largefield}
For $\beta\ge\beta_0$ (where $\beta_0=\lceil\log 20/(1-\cos\theta_*)\rceil$
is the Peierls threshold; see Proposition~\ref{prop:saddle}(iii)
and Remark~\ref{rem:parameters}), the large-field contribution to the
effective action is bounded:
\begin{equation}
|E^{\mathrm{large}}(\eta)|\le C_l\cdot e^{-c_l\beta},
\qquad c_l=1-\cos\theta_*.
\end{equation}

\label{def:blockingmap}
The map $Q:\SU(2)^{|\Lambda_k|}\to\SU(2)^{|\Lambda_{k+1}|}$ sends the
fine configuration $U$ to the coarse configuration $V=QU$ defined by
\begin{equation}
V_{\ell'}=\prod_{\ell\in\gamma(\ell')}U_\ell,
\end{equation}
where $\gamma(\ell')$ is a fixed path in the fine lattice along the
block boundary from the source to target of the coarse link $\ell'$.

\label{thm:inductive}
If IH($k$) (Definition~\ref{def:IH}) holds with $\beta_k\ge\beta_*$,
then IH($k+1$) holds with:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\beta_{k+1}<\beta_k$ (coupling decreases);
\item $\lambda_{\min}(H_{k+1})\ge\lambda_0=0.079>0$ (uniform
Hessian gap, from the scale-independent certified eigenvalue
$\lambda_{\min}(H_{\mathrm{eff}}^{\mathrm{ab}})=0.6964$);
\item $\kappa_{k+1}\ge\kappa_0>0$ (decay rate bounded below);
\item gauge invariance preserved (Proposition~\ref{prop:equiv}).
\end{enumerate}
The iteration terminates at the matching scale
$\beta_{k_*}=\beta_*$.

%
\label{prop:remainder-uniform}
For all $\beta_{\mathrm{in}}\ge\beta_0$ and any number of RG
steps $k_*=\lfloor(\beta_{\mathrm{in}}-\beta_*)/\delta\beta\rfloor$,
the accumulated remainder satisfies
\begin{equation}\label{eq:eps-uniform}
\varepsilon_{k_*}\;\le\;\varepsilon_\infty
\;:=\;\frac{16\,C_{\mathrm{fresh}}}
{\delta\beta\,(1-\alpha)\,\beta_0},
\end{equation}
where $\alpha=C''/\delta\beta=0.283<1$ and
$C_{\mathrm{fresh}}=C(4/\beta_0)^2$ is the fresh
single-step remainder at the minimum coupling.
In particular:
\begin{enumerate}[nosep,label=(\roman*)]
\item $\varepsilon_\infty$ is independent of
$\beta_{\mathrm{in}}$ and of $k_*$;
\item the KP convergence margin at the matching
scale $\beta_*$ is $\ge 7000\times$ at $\beta_0=9587$;
\item no constant in the proof chain acquires a factor
of $k_*$ at any stage of the induction.
\end{enumerate}

\label{prop:matching}
\begin{equation}\label{eq:matching}
\frac{1}{\ell_*}=C_{\mathrm{match}}\cdot\Lam,
\qquad\Lam=\frac{1}{a}\exp\Bigl(-\frac{\beta}{8b_0}\Bigr),
\end{equation}
where $C_{\mathrm{match}}$ is an explicit, finite, $\beta$-independent
constant determined by the blocking scheme.

\label{thm:massgap}
The mass gap at the matching scale satisfies
\begin{equation}\label{eq:mgap}
m\ge\frac{\gamma_0}{\ell_*},
\end{equation}
where $\gamma_0\ge 1$ is the exponential clustering rate from the
convergent cluster expansion for the full effective measure at
$\beta_*$ (Lemma~\ref{lem:cluster-rate};
rigorous: $\beta_*=9587$, illustrative: $\beta_*=150$).

In the continuum limit:
\begin{equation}\label{eq:mgap-phys}
m_{\mathrm{phys}}\ge\frac{\gamma_0}{2\ell_*}
=\frac{\gamma_0}{2}\cdot C_{\mathrm{match}}\cdot
\Lambda_{\mathrm{block}}\ge c\cdot\Lam>0,
\end{equation}
where $c=(\gamma_0/4)\cdot C_{\mathrm{match}}>0$ is a ($\beta$-independent)
constant (Proposition~\ref{prop:matching},
equation~\eqref{eq:matching-2loop}).

%
\label{def:massgap}
The \emph{mass gap} (inverse correlation length) of the lattice
gauge theory is
\begin{equation}
m=-\lim_{|t|\to\infty}\frac{1}{|t|}
\log\sup_{\mathcal{O}_1,\mathcal{O}_2}
\frac{|\langle\mathcal{O}_1(0)\mathcal{O}_2(t)\rangle_c|}
{\|\mathcal{O}_1\|_\infty\|\mathcal{O}_2\|_\infty},
\end{equation}
where the supremum is over gauge-invariant local observables
and the connected correlator is
$\langle\mathcal{O}_1\mathcal{O}_2\rangle_c
=\langle\mathcal{O}_1\mathcal{O}_2\rangle
-\langle\mathcal{O}_1\rangle\langle\mathcal{O}_2\rangle$.
This is the standard Euclidean definition~\cite{JaffeWitten}:
$m>0$ if and only if connected correlators decay
exponentially.

%
\label{lem:KL-gap}
Let $\{S_n\}$ be a system of Schwinger functions satisfying
reflection positivity \textup{(OS3)} and exponential clustering:
\begin{equation}\label{eq:KL-hypothesis}
|S_{2,c}(x,y)|\le C\,e^{-m_0\,|x-y|}
\end{equation}
for some $m_0>0$ and all $|x-y|$ sufficiently large.
Then the OS-reconstructed Wightman QFT has a spectral mass gap
$\Delta\ge m_0$: the spectrum of the Hamiltonian $H$ is
contained in $\{0\}\cup[m_0,\infty)$.

\label{lem:nontriviality}
For every $\beta\ge\beta_0$, there exists a gauge-invariant
observable $\Phi$ on the lattice $a\Z^4$, localized in a
region of fixed physical size $\ell_*$, whose connected
two-point function satisfies
\begin{equation}\label{eq:nontriviality-lemma}
\langle\Phi(X_1^*)\,\Phi(X_2^*)\rangle_{\mu_\beta,c}
\ge\frac{0.0468\,[\varphi(0)]^2}{\beta_*^2}>0,
\end{equation}
uniformly in $a$, where $X_1^*,X_2^*\in\ell_*\Z^4$ are
adjacent coarse vertices (at separation $\ell_*$) and
$\varphi(0)>0$ is the value at the origin of the bump
function $\varphi$ used in~\eqref{eq:Phi-def}.

\label{lem:cos-lip}
Let $U_1,\ldots,U_4,V_1,\ldots,V_4\in\SU(2)$ and define
$U_p=U_1 U_2 U_3^{-1}U_4^{-1}$ (plaquette holonomy),
$V_p=V_1 V_2 V_3^{-1}V_4^{-1}$.  Then
\begin{equation}
|\tr\,U_p-\tr\,V_p|\le 2\sum_{j=1}^4\|U_j-V_j\|_{\mathrm{op}}.
\end{equation}
In particular, $|\cos\theta_p(U)-\cos\theta_p(V)|
\le\sum_j\|U_j-V_j\|_{\mathrm{op}}$.

following_proof:
By telescoping:
$U_1 U_2 U_3^{-1}U_4^{-1}-V_1 V_2 V_3^{-1}V_4^{-1}
=(U_1-V_1)U_2 U_3^{-1}U_4^{-1}
+V_1(U_2-V_2)U_3^{-1}U_4^{-1}
+V_1 V_2(U_3^{-1}-V_3^{-1})U_4^{-1}
+V_1 V_2 V_3^{-1}(U_4^{-1}-V_4^{-1})$.
Taking traces: $|\tr(AB)|\le\|A\|_{\mathrm{op}}\cdot|\tr\,B|
\le 2\|A\|_{\mathrm{op}}$ for $B\in\SU(2)$ (since $|\tr\,B|\le 2$).
Each telescoping term has one factor $(U_j-V_j)$ and three
$\SU(2)$ factors with operator norm~$1$.  Therefore
$|\tr\,U_p-\tr\,V_p|\le 2\sum_j\|U_j-V_j\|_{\mathrm{op}}$.
For exponential coordinates $U_j=y_j e^{i\xi_j}$,
$V_j=y_j e^{i\eta_j}$: $\|U_j-V_j\|_{\mathrm{op}}
=\|e^{i\xi_j}-e^{i\eta_j}\|_{\mathrm{op}}\le|\xi_j-\eta_j|$
(since $\|e^{iA}-e^{iB}\|\le\|A-B\|$ for self-adjoint $A,B$
with $\|A\|,\|B\|\le\pi$).

statement:
\label{thm:A-informal}
For any compact Lie group $G$ with bi-invariant metric, the
Christoffel correction to the Wilson action Hessian lies in
$\bigwedge^2(\mathfrak{g})$ and vanishes from the Hessian
quadratic form. In particular, for $\SU(N)$ with any $N \geq 2$:
\begin{equation}
\sum_{\ell,a,\ell',b}
\cK^{\mathrm{Chr}}_{\ell\ell',ab}\,v_\ell^a v_{\ell'}^b = 0
\qquad \text{for all } v \in \mathfrak{g}^{|\cL|}.
\end{equation}

\label{thm:B-informal}
The symmetric part of the curvature error decomposes as
\begin{equation}
\cK^{\mathrm{met}}_{\ell\ell',ab}
= \underbrace{\alpha(\theta_p)\,H_{\ell\ell'}\,\delta_{ab}}_{\text{scalar channel}}
+ \underbrace{\gamma(\theta_p)\,H_{\ell\ell'}^{(p)}\,
F_{ab}(\hat\Theta_p)}_{\text{adjoint and higher channels}},
\end{equation}
where $\alpha(\theta_p) = \cos\theta_p - 1 = O(\theta_p^2)$ is
the leading scalar contribution,
$F_{ab}(\hat\Theta_p)$ is a traceless tensor in the Lie algebra
indices depending on the plaquette holonomy direction, and
$\gamma(\theta_p) = O(\theta_p^2)$.

\label{lem:casimirs}
With the normalization~\eqref{eq:basis-norm}:
\begin{align}
f_{acd}\,f_{bcd} &= N\,\delta_{ab},
\label{eq:ff-contraction}\\
d_{acd}\,d_{bcd} &= \frac{N^2 - 4}{N}\,\delta_{ab}
\qquad (N \geq 3),
\label{eq:dd-contraction}\\
f_{acd}\,d_{bcd} &= 0.
\label{eq:fd-contraction}
\end{align}

\label{lem:ricci-SUN}
With the bi-invariant metric $\ip{X}{Y} = -2\Tr(XY)$ on
$\SU(N)$:
\begin{equation}\label{eq:ricci-SUN}
\Ric_{\SU(N)} = \frac{N}{4}\,g.
\end{equation}

\label{lem:connection}
The Levi-Civita connection on $(\SU(N), -2\Tr)$ satisfies
$\nabla_{\tilde X}\tilde Y = \frac{1}{2}[\tilde X, \tilde Y]$
for left-invariant fields. In the basis $\{T_a\}$:
\begin{equation}
\Gamma^c_{ab} = \frac{1}{2}f_{abc}.
\end{equation}

\label{thm:christoffel}
Let $G$ be a compact Lie group with bi-invariant metric. For
any lattice gauge theory with Wilson action on
$G^{|\cL|}$, the Christoffel correction satisfies
\begin{equation}
\cK^{\mathrm{Chr}}_{\ell\ell',ab}
+ \cK^{\mathrm{Chr}}_{\ell'\ell,ba} = 0.
\end{equation}
Consequently, $\cK^{\mathrm{Chr}}$ does not contribute to the
Hessian quadratic form:
\begin{equation}\label{eq:christoffel-vanishing}
\sum_{\ell,a,\ell',b}
\cK^{\mathrm{Chr}}_{\ell\ell',ab}\,v_\ell^a v_{\ell'}^b = 0
\qquad \text{for all } v \in \mathfrak{g}^{|\cL|}.
\end{equation}

following_proof:
The connection coefficients satisfy $\Gamma^c_{ab} =
\frac{1}{2}f_{abc}$. Since $f_{abc}$ is totally antisymmetric
(Lemma~\ref{lem:fd-symmetry}(a)):
\begin{equation}
\Gamma^c_{ab} = \frac{1}{2}f_{abc}
= -\frac{1}{2}f_{bac} = -\Gamma^c_{ba}.
\end{equation}
The incidence factors satisfy
$s_\ell(p)s_{\ell'}(p) = s_{\ell'}(p)s_\ell(p)$.
The plaquette derivative $\partial_c S_p$ depends on the
plaquette, not on the link pair $(\ell,\ell')$.
Therefore:
\begin{align}
\cK^{\mathrm{Chr}}_{\ell'\ell,ba}
&= -\sum_p s_{\ell'}(p)s_\ell(p)\,\Gamma^c_{ba}\,
(\partial_c S_p)\,\phi(\theta_p) \\
&= -\sum_p s_\ell(p)s_{\ell'}(p)\,(-\Gamma^c_{ab})\,
(\partial_c S_p)\,\phi(\theta_p) \\
&= -\cK^{\mathrm{Chr}}_{\ell\ell',ab}.
\end{align}
The quadratic form vanishing follows from the general identity:
for any antisymmetric bilinear form $A_{ij}$,
$\sum_{ij} A_{ij}v_i v_j = 0$.

statement:
\label{def:projectors}
For a tensor $M_{ab}$ on $\su(N)$:
\begin{align}
M^{(\mathbf{1})}_{ab} &= \frac{1}{N^2-1}\,M_{cc}\,\delta_{ab}
&&\text{(scalar channel)}, \label{eq:proj-scalar}\\
M^{(\ad,f)}_{ab} &= \frac{1}{2N}\,
(f_{acd}f_{bce} - f_{bcd}f_{ace})\,M_{de}
&&\text{(antisymmetric adjoint)}, \label{eq:proj-f}\\
M^{(\ad,d)}_{ab} &= \frac{N}{N^2-4}\,
d_{acd}\,M_{de}\,d_{bce}\;
-\;\text{trace}
&&\text{(symmetric adjoint, $N\geq 3$)}, \label{eq:proj-d}
\end{align}
where ``$-\text{trace}$'' denotes subtraction of the scalar
component to ensure orthogonality to the $\mathbf{1}$ channel.

\label{cor:surviving}
The channels contributing to $\cK^{\mathrm{met}}$ are:
\begin{center}
\begin{tabular}{lll}
\toprule
Channel & Contribution & Groups \\
\midrule
$\mathbf{1}$ (scalar, $\delta_{ab}$) & $\alpha(\theta_p) = O(\theta_p^2)$ & All $\SU(N)$ \\
$\ad$ via $f_{abc}$ & $0$ (vanishes) & All $\SU(N)$ \\
$\ad$ via $d_{abc}$ & $\beta_d(\theta_p) = O(\theta_p^2)$ & $N \geq 3$ only \\
Higher irreps & $O(\theta_p^2)$ & All $\SU(N)$ \\
\bottomrule
\end{tabular}
\end{center}

\label{thm:C-prime-su2}
For $\SU(2)$ and the $2^4$ block with boundary condition $\eta$
such that $\max_p\theta_p \leq \theta_*$:
\begin{equation}
\cK^{\mathrm{met}}_{\ell\ell',ab}
= \bigl(\tfrac{\sin\theta_p}{\theta_p} - 1\bigr)
  H_{\ell\ell'}\,\delta_{ab}
+ h(\theta_p)\,H^{(p)}_{\ell\ell'}\,
  (\hat\Theta_p^a\hat\Theta_p^b - \tfrac{1}{3}\delta_{ab})
+ O(\theta_*^2)\delta_{ab},
\end{equation}
where the spin-$2$ coefficient is smooth, vanishing at
$\theta = 0$, and $O(\theta^2)$, and the $O(\theta_*^2)$
remainder includes the BCH second-order and Jacobian corrections.

The effective bound on the good region $\Omega_g(\theta_*)$ is:
\begin{equation}
\cK^{\mathrm{met}} \succeq
\bigl(\tfrac{\sin\theta_*}{\theta_*} - 1\bigr)H_{yy}\otimes I_3
- C'\theta_*^2\,I
\end{equation}
with
\begin{equation}\label{eq:C-prime-explicit}
C' = C_2 + C_{\mathrm{BCH}} + C_{\mathrm{Jac}},
\end{equation}
where each term is the constant coefficient (independent of
$\theta_*$) bounding the corresponding contribution:
\begin{enumerate}[label=(\roman*)]
\item $C_2 = n_p \cdot \sup_{|\theta|\leq\pi/2}
  |h(\theta)|/\theta^2 \leq 6 \cdot \frac{1}{3} = 2$
  is the spin-$2$ channel bound, using
  $|h(\theta)| = |\cos\theta - \frac{\sin\theta}{\theta}|
  \leq \frac{\theta^2}{3}$ for $|\theta| \leq \pi/2$;
\item $n_p = 6$ is the maximum number of plaquettes per edge;
\item $C_{\mathrm{BCH}} \leq \frac{1}{12}\cdot 6 \cdot N_{\mathrm{pair}}
  = 6$ accounts for the symmetric second-order BCH terms, with
  $N_{\mathrm{pair}} = 12$ (the total number of oriented link
  pairs across all plaquettes sharing a given edge);
\item $C_{\mathrm{Jac}} \leq \frac{1}{6}\cdot 6 = 1$ accounts for
  the exponential map Jacobian (one factor of $\frac{1}{6}$ per
  plaquette from~\eqref{eq:dexp}, summed over $n_p$ plaquettes).
\end{enumerate}

Hence $C' \leq 2 + 6 + 1 = 9$. (This is a crude upper bound;
the actual value is smaller because the spin-$2$ and Jacobian
terms partially cancel, and the maximum is not achieved
simultaneously on all plaquettes.)

\label{def:DX}
For $f: \SU(2)^{|\cL|} \to \R$ smooth, the operator derivative is
\begin{equation}
(D_U f)_\ell^a = \nabla_\ell^a f(U),
\end{equation}
viewed as an element of
$T_U^*(\SU(2)^{|\cL|}) \cong \su(2)^{|\cL|}$ via the bi-invariant
metric.

The carr\'e du champ operator for the Langevin generator is
\begin{equation}
\Gamma(f,g) = \frac{1}{2}\bigl[L(fg) - fLg - gLf\bigr]
= \sum_{\ell,a} \nabla_\ell^a f \cdot \nabla_\ell^a g.
\end{equation}

\begin{equation}
\Gamma_2(f,f) = \frac{1}{2}\bigl[L\,\Gamma(f,f) - 2\Gamma(f, Lf)\bigr].
\end{equation}

\label{def:leibniz}
For an operator $\mathcal{D}$ mapping functions to sections of a
vector bundle, the \emph{Leibniz defect} is
\begin{equation}\label{eq:leibniz-abstract}
\Gamma_{\mathcal{D}}(f,g)
:= \mathcal{D}(fg) - f \cdot \mathcal{D}(g) - g \cdot \mathcal{D}(f).
\end{equation}
When $\Gamma_{\mathcal{D}} = 0$, the operator is a derivation.

\label{prop:micro-deriv}
The Riemannian operator derivative $D_U = \nabla$ is a derivation:
$\Gamma_{D_U}(f,g) = 0$ for all smooth $f, g$.

\label{def:block-leibniz}
The Leibniz defect of $\mathcal{D}_{\mathrm{eff}}$ is
\begin{align}\label{eq:block-leibniz}
\Gamma_B(f,g) &:= \mathcal{D}_{\mathrm{eff}}(fg)
- T_B(f) \cdot \mathcal{D}_{\mathrm{eff}}(g)
- T_B(g) \cdot \mathcal{D}_{\mathrm{eff}}(f) \\
&\;= \nabla_x\,\E[fg \mid x]
- \E[f \mid x]\,\nabla_x\,\E[g \mid x]
- \E[g \mid x]\,\nabla_x\,\E[f \mid x]. \notag
\end{align}

\label{prop:leibniz-cov}
\begin{equation}
\Gamma_B(f,g) = \nabla_x\,\Cov_{\mu_B(\cdot|x)}(f, g).
\end{equation}
In particular, $\Gamma_B = 0$ if and only if
$\nabla_x\,\Cov(f,g \mid x) = 0$---i.e., the conditional covariance
is constant in the boundary condition.

\label{lem:cancel}
For any internal edge $\ell$ in the $2^4$ block:
\begin{equation}\label{eq:cancel}
\sum_p (A_\ell)_p = 0.
\end{equation}
Each internal edge appears in exactly $6$ plaquettes, grouped into $3$
pairs by coordinate plane, with opposite orientations in each pair.

\label{lem:curv-leibniz}
The curvature error $\cK$ in~\eqref{eq:hess-decomp} has two
components:
\begin{enumerate}[label=(\alph*)]
\item \textbf{Christoffel correction:}
  $\cK^{\mathrm{Chr}}_{\ell\ell',ab}
  = -\frac{1}{2}\sum_{p:\,\ell,\ell' \in p}
  s_\ell(p)\,s_{\ell'}(p)\,\epsilon_{cab}\,g(\theta_p)\,\hat\theta_p^c$
  where $g(\theta) = (\theta\cos\theta - \sin\theta)/(\theta\sin\theta)$
  and $\hat\theta_p^c$ is the plaquette holonomy direction.
  This correction is \textbf{antisymmetric} in the full index
  $(\ell,a) \leftrightarrow (\ell',b)$:
  \begin{equation}
  \cK^{\mathrm{Chr}}_{\ell\ell',ab}
  + \cK^{\mathrm{Chr}}_{\ell'\ell,ba} = 0,
  \end{equation}
  because $\epsilon_{cab} + \epsilon_{cba} = 0$. Therefore
  $\cK^{\mathrm{Chr}}$ does not contribute to the Hessian quadratic
  form: $\sum_{\ell,a,\ell',b}
  \cK^{\mathrm{Chr}}_{\ell\ell',ab}\,v_\ell^a v_{\ell'}^b = 0$.

\item \textbf{Metric correction:} The Riemannian metric in
  exponential coordinates $U_\ell = \exp(A_\ell)$ differs from the
  flat metric by $O(\theta^2)$ terms. The dominant contribution
  replaces the abelian Hessian $H_{\ell\ell'}\delta_{ab}$ by
  $\cos(\theta_p)\,H_{\ell\ell'}\delta_{ab}$:
  \begin{equation}
  \cK^{\mathrm{met}}_{\ell\ell',ab}
  = \bigl(\cos(\theta_p) - 1\bigr)\sum_{p:\,\ell,\ell' \in p}
  s_\ell(p)s_{\ell'}(p)\,\delta_{ab}
  + O(\theta_*^2)\,\delta_{ab}.
  \end{equation}
  This is \textbf{symmetric} in $(\ell,a) \leftrightarrow (\ell',b)$
  and $O(\theta_*^2)$.
\end{enumerate}

\label{lem:curv-bound}
On the good region $\Omega_g(\theta_*) = \{\max_p \theta_p \leq \theta_*\}$
with $\theta_* \leq \pi/2$, the symmetric part of the curvature error
satisfies
\begin{equation}
\cK^{\mathrm{sym}} \succeq (\cos\theta_* - 1)\,H_{yy} \otimes I_3
- C'\theta_*^2\,I
\end{equation}
where $C'$ accounts for the BCH and Jacobian remainders.
Equivalently, the full interior Hessian satisfies
\begin{equation}
\Hess_y(S_\beta) \succeq
\beta\cos(\theta_*)\,H_{\mathrm{phys}} \otimes I_3
- C'\beta\theta_*^2\,I.
\end{equation}

\label{thm:curvature}
Fix a block $B$ and a boundary condition $\eta$ such that all
plaquettes touching $B^{\mathrm{int}}$ satisfy
$\theta_p \leq \theta_*$ with $\theta_* \leq \pi/2$. Then the
block-conditional Bakry--\'Emery--Ricci tensor satisfies
\begin{equation}\label{eq:curvature-bound}
\Ric_{\mu_B(\cdot|\eta)}
\geq \kappa_B(\beta, \theta_*)\,g
\end{equation}
on the physical (gauge-orthogonal) subspace, with
\begin{equation}\label{eq:kappa-B}
\kappa_B(\beta, \theta_*) = \frac{1}{2}
+ \beta\bigl(\cos(\theta_*)\,\lambda_{\min}(H_{\mathrm{phys}})
- C'\theta_*^2\bigr).
\end{equation}

\label{thm:chessboard}
For any plaquette $p$, any $\theta_* \in (0, \pi)$, and $\beta \geq 1$:
\begin{equation}
\mu_\beta(\theta_p > \theta_*)
\leq C\,\exp\bigl(-\beta\,(1 - \cos\theta_*)/2\bigr).
\end{equation}

\label{thm:block-poincare-local}
For each block $B$, boundary condition $\eta$, and $\beta \geq \beta_0$:
\begin{equation}
\Var_{\mu_B(\cdot|\eta)}(f)
\leq \frac{C_P}{\beta}\,
\int |\nabla_y f|^2\,d\mu_B(\cdot|\eta),
\end{equation}
with $C_P$ depending only on the block geometry,
uniform in $\eta$ and $N$.

\label{lem:var-decomp}
For $f \in L^2(\mu_\beta)$:
\begin{equation}
\Var(f) = \Var(\E[f|\cF_0])
+ \sum_{k=1}^M \E\bigl[\Var(\E[f|\cF_k] \mid \cF_{k-1})\bigr].
\end{equation}

\label{lem:block-good}
For $k \geq 1$ and gauge-invariant $f$:
\begin{equation}
\E\bigl[\Var(\E[f|\cF_k] \mid \cF_{k-1})\bigr]
\leq \frac{C_P}{\beta}\,\E\bigl[|\nabla_{B_k} f|^2\bigr].
\end{equation}

\label{thm:global-poincare}
For gauge-invariant $f$ and $\beta \geq \beta_0$:
\begin{equation}
\Var_{\mu_\beta}(f) \leq \frac{C_P}{\beta}\,\cE(f,f),
\end{equation}
giving spectral gap $\lambda_1 \geq \beta/C_P$,
\textbf{conditional} on the boundary-term Poincar\'e inequality
described in Remark~\ref{rem:boundary-term}.

