\label{thm:single_link}
For any compact simple $G$ and $\beta > 0$, the single-link
conditional measure satisfies the log-Sobolev inequality
with constant
\begin{equation}
  \alpha_\ell(\beta) \ge \frac{1}{c_G(\beta + 1)},
\end{equation}
where $c_G$ depends only on $G$. Equivalently, the
single-link spectral gap satisfies
$\gamma_\ell(\beta) \ge c_0(G) > 0$ uniformly in $\beta$.

\label{thm:lattice_gap}
For any compact gauge group $G$, any lattice
$\Lambda_a$, and any $\beta > 0$:
\begin{equation}
  \gap(H_{\mathrm{lat}}) \ge m_{\mathrm{lat}}(\beta) > 0,
\end{equation}
where $H_{\mathrm{lat}}$ is the transfer matrix Hamiltonian.
The gap is uniform over boundary conditions.

\label{thm:uniform}
For 3D Yang--Mills with compact simple $G$ and $g^2 > 0$:
\begin{equation}
  m_{\mathrm{phys}}(a) =
  a \cdot \gap(H_{\mathrm{lat}}(\beta(a)))
  \ge c(g^2, G) > 0
  \qquad \forall\, a \in (0, a_0].
\end{equation}

\label{prop:uv_bbd}
In $d = 3$, Ba{\l}aban's effective action
bounds~\cite{Bal85e} imply that the Hessian correction
at RG scale $k$ (corresponding to lattice spacing
$\eta_k = L^{k-N}$) satisfies
\begin{equation}\label{eq:hessian_3d}
  \left\|(\Hess V_k)_+\right\|_\infty
  \le \frac{C}{\beta_k} = C g^2 \eta_k = C g^2 L^{k-N}.
\end{equation}
Consequently, the UV contribution to the BBD
integral is
\begin{equation}
  \sum_{k=0}^{N} \frac{C g^2}{L^{N-k}}
  = C g^2 \sum_{j=0}^{N} L^{-j}
  \le \frac{C g^2}{1 - L^{-1}} = O(g^2),
\end{equation}
which converges uniformly in $N$ (the UV cutoff).

For $\delta > 0$, the \emph{$\delta$-local data}
of a state $\omega$ is the collection
$\{\omega(W_\gamma^R) : \diam(\gamma) \le \delta,\;
R \text{ irreducible}\}$.

\label{thm:rigidity}
Let $\omega, \omega'$ be two states on Wilson loop
expectations satisfying:
\begin{enumerate}[label=(\alph*),nosep]
  \item OS reflection positivity;
  \item translation invariance;
  \item gauge invariance;
  \item mass gap $m \ge m_* > 0$;
  \item same $\delta$-local data for some $\delta > 0$:
    $\omega(W_\gamma^R) = \omega'(W_\gamma^R)$ for
    all loops with $\diam(\gamma) \le \delta$.
\end{enumerate}
Then $\omega = \omega'$.

\label{thm:rotation}
The continuum limit $\omega = \lim_{a \to 0} \omega_a$
is invariant under $\SO(3)$.

\label{thm:os}
Let $\omega$ be a state on Wilson loop expectations
satisfying reflection positivity, translation invariance,
and gauge invariance. Then there exist:
\begin{enumerate}[label=(\alph*),nosep]
  \item A Hilbert space $\cH$ of gauge-invariant states;
  \item A unit vector $\Omega \in \cH$ (vacuum);
  \item A self-adjoint operator $H \ge 0$ on $\cH$
    with $H\Omega = 0$;
  \item A unitary representation of the translation group
    with $H$ as the generator of time translations;
\end{enumerate}
such that Wilson loop expectations are recovered
as vacuum matrix elements of the transfer matrix.

\label{thm:uniform-gap}
For any compact simple $G$ and any $g^2 > 0$, there exists
$c = c(G, g^2, L) > 0$ such that for all $a > 0$:
\begin{equation}\label{eq:uniform-decay}
  \bigl|\langle W_\gamma\, W_{\gamma'}\rangle_{\mu_a}
  - \langle W_\gamma\rangle_{\mu_a}
  \langle W_{\gamma'}\rangle_{\mu_a}\bigr|
  \le C \cdot e^{-c \cdot d(\gamma, \gamma') / a}
\end{equation}
for all Wilson loops $\gamma, \gamma'$ at lattice distance
$d(\gamma, \gamma')/a$ apart. In physical units, the mass
gap satisfies
\begin{equation}
  m_{\mathrm{phys}}(a) := c / a \ge m_*(g^2) > 0
  \quad \text{uniformly in } a.
\end{equation}

\label{prop:weak}
For $\beta \ge \beta_0(G)$ sufficiently large, the Bakry--\'Emery
curvature of the single-link conditional measure satisfies
\begin{equation}\label{eq:weak-curvature}
  \kappa_\ell(\beta) \ge \rho_G - \frac{C(G, d)}{\beta}.
\end{equation}
In particular, $\kappa_\ell(\beta) \ge \rho_G/2 > 0$ for
$\beta \ge 2C/\rho_G$.

\label{prop:Balaban}
Balaban's UV stability~\cite{Balaban85} implies that for
$d = 3$:
\begin{equation}
  \langle W_\gamma(0) W_{\gamma'}(t)\rangle_{\mu_a}
  \le C(\gamma, \gamma') \cdot e^{-m_0 |t|}
\end{equation}
for some $m_0 = m_0(g^2) > 0$ independent of $a$, where $t$
is the Euclidean time separation.

The \textbf{state} of the lattice measure $\mu_a$ is the
collection of all Wilson loop expectations:
\begin{equation}
  \omega_a(\gamma_1, \ldots, \gamma_n; R_1, \ldots, R_n) :=
  \langle W_{\gamma_1}^{R_1} \cdots W_{\gamma_n}^{R_n}
  \rangle_{\mu_a}.
\end{equation}
These are the Schwinger functions of the theory, evaluated on
Wilson loop observables.

\label{prop:transfer-gap}
For all $a > 0$:
\begin{equation}
  m_a^{(T)} \ge c(g^2) \cdot a > 0.
\end{equation}
In physical units: $m_{\mathrm{phys}} = m_a^{(T)}/a \ge c(g^2) > 0$.

\label{thm:continuum-gap}
The transfer matrix $T$ of the limit measure $\omega$ has
a spectral gap: $\|T^t|_{\Omega^\perp}\| \le e^{-m_* t}$
for all $t > 0$, where $m_* = m_*(g^2) > 0$ is the uniform
physical mass gap from Theorem~\ref{thm:uniform-gap}.

Equivalently: the Hamiltonian $H = -\log T$ (generator of
the OS semigroup) satisfies
\begin{equation}
  \inf\,\sigma(H) \setminus \{0\} \ge m_* > 0.
\end{equation}

\label{thm:BBD-3D}
The BBD integral for 3D Yang--Mills is finite:
\begin{equation}
  \gamma^{-1} \le \frac{C}{\gamma_0}\,t_*
  + \frac{1}{2\rho_G}\,e^{-2\lambda_{t_*}} < \infty,
\end{equation}
where $\gamma_0 > 0$ is the lattice block gap and
$\rho_G$ is the Ricci curvature of $G$.

\label{conj:inv}
The CCHS flow admits an invariant probability measure $\mu$ on
$\fO$, and $\mu$ is the continuum YM measure.

\label{thm:main}
For any compact simple $G$, any $g^2 > 0$, and any
$L > 0$: there exists $m_* = m_*(G, g^2, L) > 0$ such that
for all $a > 0$ (with $a$ dividing $L$),
\begin{equation}
  m_{\mathrm{phys}}(a) \ge m_* > 0,
\end{equation}
where $m_{\mathrm{phys}}(a)$ is the physical mass gap of
the lattice YM theory at spacing $a$.

\label{lem:gaussian}
In the variable $X \in \fg$, the conditional measure becomes
\begin{equation}\label{eq:gauss-approx}
  d\nu_\ell^{(X)} \propto
  \exp\Bigl(-\frac{|\Sigma_\ell|}{2n}|X|^2
  + O(|X|^3/\sqrt{\beta})\Bigr)\,dX
  + O(e^{-c\beta}).
\end{equation}
The leading term is $\mathcal{N}(0, \sigma^2 I)$ with
$\sigma^2 = n/|\Sigma_\ell|$.

\label{prop:curv-fluct}
In the $X$-parametrization, the Bakry--\'Emery curvature of
$\nu_\ell^{(X)}$ satisfies
\begin{equation}\label{eq:curv-fluct}
  \kappa_\ell^{(X)} \ge \frac{|\Sigma_\ell|}{n}
  - \frac{C}{\sqrt{\beta}}.
\end{equation}
For $\beta \ge \beta_0(G)$:
$\kappa_\ell^{(X)} \ge \frac{|\Sigma_\ell|}{2n} > 0$.

\label{lem:staple}
At weak lattice coupling ($\beta \gg 1$), the staple satisfies
\begin{equation}
  |\Sigma_\ell| = 2(d-1)\,n + O(1/\sqrt{\beta})
  = 4n + O(1/\sqrt{\beta})
\end{equation}
with high probability under the lattice YM measure, where
$d = 3$ and each link participates in $2(d-1) = 4$ plaquettes.

\label{cor:curv-weak}
For $\beta \ge \beta_0$: the single-link curvature satisfies
$\kappa_\ell^{(X)} \ge 2 - C/\sqrt{\beta} \ge 1$ (for $d = 3$).

\label{prop:dob-weak}
The Dobrushin interdependence coefficient between links
$\ell, \ell'$ sharing a plaquette satisfies
\begin{equation}\label{eq:dob-coeff}
  C_{\ell\ell'}(\beta) \le \frac{C_0}{1 + \kappa_\ell^{(X)}}
  = O\bigl(1\bigr)
\end{equation}
at large $\beta$, with the total interaction per link:
\begin{equation}\label{eq:dob-total}
  \sum_{\ell' \ne \ell} C_{\ell\ell'}
  \le \frac{\Delta_{\mathrm{ext}}}
  {\kappa_\ell^{(X)} + \Delta_{\mathrm{ext}}}
  \le \frac{4(d-1)}{2 + 4(d-1)} = \frac{8}{10} = 0.8
  < 1
\end{equation}
for $d = 3$, using $\kappa_\ell^{(X)} \ge 2$ and
$\Delta_{\mathrm{ext}} \le 4(d-1) = 8$.

