\label{prop:hess_prop}
Under Condition~$\star$ at scale $k$:
\begin{equation}\label{eq:hess_prop}
  \|\Hess\,\cV_{k+1}\|_{\mathrm{op}}
  \le \bigl\|\langle \Hess_\Phi H_B \rangle_{\mu_B}
  \bigr\|_{\mathrm{op}}
  \le \beta_k \cdot \|\Hess_\Phi S_B\|
  + C_\star g^2(k).
\end{equation}

\label{prop:renorm_hess}
After perturbative subtraction through one loop,
the effective potential correction satisfies:
\begin{equation}\label{eq:renorm_bound}
  \|\Hess\,\cV_{k+1}\|_{\mathrm{op}}
  \le C_\star g^2(k)
  + \frac{C_R}{L^4 \rho_G}
  + C_2 g^4(k),
\end{equation}
where $C_R$ is a constant depending on the
two-loop and higher contributions.

\label{cond:gauge_hess}
For the gauge-fixed effective action $\bar{H}_B$ (after
axial gauge fixing on the block), the non-perturbative
remainder $\delta\bar{H}_B = \bar{H}_B - \bar{H}_B^{(1)}$
satisfies:
\begin{equation}\label{eq:gauge_hess}
  \|\nabla_U \nabla_\Phi \delta\bar{H}_B\|_{\mathrm{op}}
  \le C \cdot g^2(k)
\end{equation}
on the small-field region, where the norm is computed
in the gauge-fixed coordinates.

\label{prop:gauge_closes}
Condition~\ref{cond:gauge_hess} implies Condition~$\star$
(from~\cite{FontesStar}) for all $0 \le k \le N$.

\label{lem:cubic}
For a plaquette $p$ involving interior link $\ell$ and
boundary link $b$:
\begin{equation}\label{eq:cubic_bound}
  \|\nabla_{A_\ell} \nabla_{\Phi_b}\, s_p^{(3)}\|
  \le \frac{\beta}{N}\, C_3\, \|A\|_\infty,
\end{equation}
where $C_3$ is a universal constant and $\|A\|_\infty =
\max_{\ell'} |A_{\ell'}|$.

\label{lem:higher}
For $s_p^{(\ge 4)}$:
\begin{equation}
  \|\nabla_{A_\ell} \nabla_{\Phi_b}\, s_p^{(\ge 4)}\|
  \le \frac{\beta}{N}\, C_4\, \|A\|_\infty^2,
\end{equation}
where $C_4$ depends on $N$.

\label{prop:op_norm}
On the small-field region $\|F\|_\infty \le g^{1-\delta}(k)$:
\begin{equation}\label{eq:op_norm_bound}
  \|\nabla_A \nabla_\Phi\, \delta\bar{S}_B\|_{\mathrm{op}}
  \le \beta_k \cdot C_3' \cdot g^{1-\delta}(k)
  + \beta_k \cdot C_4' \cdot g^{2-2\delta}(k).
\end{equation}
Since $\beta_k = 1/g^2(k)$:
\begin{equation}\label{eq:op_norm_final}
  \|\nabla_A \nabla_\Phi\, \delta\bar{S}_B\|_{\mathrm{op}}
  \le C_3' \cdot g^{-1-\delta}(k) + C_4' \cdot g^{-2\delta}(k).
\end{equation}

\label{lem:one_loop}
