  V_k(\phi_{\le k}) = -\log \int e^{-\sum_{j > k} H_j}
  \,d\phi_{>k}.
\end{equation}
If the Bakry--\'Emery condition holds at each scale:
\begin{equation}\label{eq:bbd_abstract}
  \Ric_{\cM_k} + \Hess_{k}\,(V_k + V_k^{\mathrm{Gauss}})
  \ge -\kappa_k\,g_k
\end{equation}
with $\sum_{k=0}^N \kappa_k^+ < \infty$ (where
$\kappa_k^+ = \max(\kappa_k, 0)$), then $\mu$ satisfies
a log-Sobolev inequality:
\begin{equation}\label{eq:bbd_lsi}
  \Ent_\mu(f^2) \le 2\alpha \int |\nabla f|^2 d\mu,
  \quad \alpha \le C \exp\!\Bigl(C'\sum_k \kappa_k^+\Bigr).
\end{equation}

\label{prop:fluct_curv}
Under Condition~$\star$ at scale $k$ with
$g^2(k) \le \rho_G/(2C_\star)$:
\begin{equation}\label{eq:kappa_B}
  \kappa_B := \inf_{\cM_B} \lambda_{\min}\!\bigl(
  \Ric_{\cM_B} + \Hess_U\,H_B\bigr)
  \ge n_{\mathrm{phys}}\cdot\frac{\rho_G}{2}.
\end{equation}

\label{cor:moments}
Under the conditions of Proposition~\ref{prop:fluct_curv},
writing $U_i = e^{iA_i}$ for each physical link:
\begin{equation}\label{eq:link_moments}
  \langle |A_i|^{2p} \rangle_{\mu_B}
  \le \left(\frac{C_p \cdot n_G}{\beta_k + \rho_G}\right)^p
  \le \left(\frac{C_p n_G g^2(k)}{\rho_G g^2(k) + 1}\right)^p
  \le (C_p' g^2(k))^p
\end{equation}
for all $p \ge 1$, where $C_p'$ depends on $p$, $N$,
and $\rho_G$ but not on $k$ or the cutoff.

In particular:
\begin{equation}\label{eq:fourth_moment}
  \langle |A_i|^4 \rangle_{\mu_B}
  \le C_2' \cdot g^4(k).
\end{equation}

\label{prop:fluct_bound}
After the one-loop subtraction (which is absorbed in the
passage from $g^2(k)$ to $g^2(k+1)$ via the $\beta$-function):
\begin{equation}\label{eq:fluct_final}
  \|\Cov_{\mu_B}^{\mathrm{sub}}(\nabla_\Phi H_B,
  \nabla_\Phi H_B)\|_{\mathrm{op}}
  \le \frac{1}{\kappa_B} \cdot n_\partial \cdot
  \bigl(C_{\mathrm{sub}}/\rho_G^2 + C_\star^2 g^4\bigr),
\end{equation}
where $C_{\mathrm{sub}}$ is a constant (depending on $G$
but not on $k$ or $N$), $n_\partial = O(L^3)$
(Lemma~\ref{lem:boundary}), and $\kappa_B \ge
n_{\mathrm{phys}}\rho_G/2 \ge 3L^4\rho_G/2$.

Dividing:
\begin{equation}\label{eq:fluct_divided}
  \|\text{fluctuation}\|_{\mathrm{op}}
  \le \frac{L^3 \cdot C_{\mathrm{sub}}/\rho_G^2}
  {3L^4 \rho_G/2}
  + \frac{L^3 \cdot C_\star^2 g^4}{3L^4\rho_G/2}
  = \frac{2 C_{\mathrm{sub}}}{3L\rho_G^3}
  + \frac{2 C_\star^2 g^4}{3L\rho_G}.
\end{equation}

\label{thm:hess_prop}
Under (B1)--(B4) and Condition~$\star$ at scale $k$,
for $g^2(k) \ge \epsilon_*$ and $L \ge L_0$:
\begin{equation}\label{eq:propagation}
  \|\Hess\,\cV_{k+1}\|_{\mathrm{op}}
  \le C_\star g^2(k)
  + \frac{C_F}{L\,\rho_G^3}
  + C_R g^4(k),
\end{equation}
where $C_F = 2C_{\mathrm{sub}}/3$ is the fluctuation
constant and $C_R = 2C_\star^2/(3\rho_G) + C_{\mathrm{mf}}$
combines the coupling-dependent fluctuation and mean-field
corrections.

\label{prop:base}
For $g^2(k) \le \epsilon_*$ with $\epsilon_*$
sufficiently small (depending on $G$ and $L$):
\begin{equation}\label{eq:base}
