\end{equation}
where $C_1$ depends on $G$, $L$, and $\epsilon_*$.

\label{thm:bootstrap}
For $G$ compact simple, $d = 4$, $L \ge L_0(G)$, and
$g_0^2$ sufficiently small:

Condition~$\star$ holds: $\|\Hess\,\cV_k\|_{\mathrm{op}}
\le C_\star g^2(k)$ for all $0 \le k \le N$, uniformly
in $N$.

