\label{thm:main}
Let $\Lambda_N = (\Z/N\Z)^4$ with $N = 2^n$, $n \geq 2$. For
$\SU(2)$ lattice gauge theory with Wilson action at coupling
$\beta \geq \beta_0$, the following hold:
\begin{enumerate}[label=(\roman*)]
\item \textbf{Bakry--\'Emery curvature:} There exists $\kappa > 0$
  depending only on the block geometry such that
  \begin{equation}
  \Gamma_2(f,f) \geq \kappa\beta\,\Gamma(f,f)
  \end{equation}
  for all gauge-invariant $f$, with $\kappa \geq 0.18$.

\item \textbf{Spectral gap:} The spectral gap on gauge-invariant
  functions satisfies $\lambda_1 \geq \kappa\beta$, uniformly in $N$.

\item \textbf{Exponential clustering:} For gauge-invariant observables
  $F, G$ with separated supports:
  \begin{equation}
  \abs{\Cov_{\mu_\beta}(F,G)} \leq C\norm{F}_\infty\norm{G}_\infty\,
  e^{-m\,\mathrm{dist}(F,G)}
  \end{equation}
  with $m = c\sqrt{\kappa\beta} > 0$.
\end{enumerate}

