The carr\'e du champ operator for the Langevin generator is
\begin{equation}
\Gamma(f,g) = \frac{1}{2}\bigl[L(fg) - fLg - gLf\bigr]
= \sum_{\ell,a} \nabla_\ell^a f \cdot \nabla_\ell^a g.
\end{equation}

\begin{equation}
\Gamma_2(f,f) = \frac{1}{2}\bigl[L\,\Gamma(f,f) - 2\Gamma(f, Lf)\bigr].
\end{equation}

\label{def:leibniz}
For smooth $f, g: \SU(2)^{|\cL|} \to \R$:
\begin{equation}\label{eq:leibniz}
\Gamma_U(f,g) := D_U(fg) - f \cdot D_U g - g \cdot D_U f.
\end{equation}

\label{def:block-leibniz}
For a block $B$ with boundary links $x$ and interior links $y$:
\begin{equation}\label{eq:block-leibniz}
\Gamma_B(f,g) := \nabla_x\,\E[fg \mid x]
- \E[f \mid x]\,\nabla_x\,\E[g \mid x]
- \E[g \mid x]\,\nabla_x\,\E[f \mid x].
\end{equation}

\label{prop:leibniz-cov}
\begin{equation}
\Gamma_B(f,g) = \nabla_x\,\Cov_{\mu_B(\cdot|x)}(f, g).
\end{equation}
In particular, $\norm{\Gamma_B(f,g)} \leq
\norm{\nabla_x \Cov(f,g \mid x)}$, and $\Gamma_B = 0$ if and only if
$f$ and $g$ are conditionally independent given the boundary.

\label{lem:cancel}
For any interior edge in the $2^4$ block:
\begin{equation}\label{eq:cancel}
A^\top \mathbf{1} = \sum_p A_p = 0.
\end{equation}
The edge appears in exactly 6 plaquettes, grouped into 3 pairs by
coordinate plane, with opposite orientations in each pair.

\label{thm:free-leibniz}
For the quadratic Wilson action
$V^{(0)}(x,y) = \frac{\beta c_2}{2}\sum_p \omega_p^2$
with $\omega_p = A_p y + b_p(x)$, the block Leibniz defect of the
free (Gaussian) conditional measure vanishes:
\begin{equation}
\Gamma_B^{(0)}(f,g) = 0 \quad \text{for all } f, g.
\end{equation}
Equivalently, the conditional expectation $T_0 = \E_{\mu_0}[\cdot|x]$
preserves the product structure: $D_{X_0}$ is a derivation.

\label{lem:curv-leibniz}
The curvature error satisfies
\begin{equation}
\cK_{\ell\ell',ab} = \sum_p \frac{\partial\theta_p}{\partial A_\ell^c}\,
\epsilon_{cab}\,\frac{\partial\theta_p}{\partial A_{\ell'}^c}\,f(\theta_p)
\end{equation}
where $\epsilon_{abc}$ are the $\SU(2)$ structure constants and
$f(\theta) = O(\theta)$ near $\theta = 0$.

\label{cor:block-curv}
On the good region, the conditional Bakry--\'Emery--Ricci tensor for
block $B$ satisfies
\begin{equation}
\Ric_{\mu_B(\cdot|\eta)} \geq \kappa_B\beta\,g
\end{equation}
with $\kappa_B = (1/(4\beta) + 0.6893 - 12\theta_*^2/\beta)/1
\geq 0.6893 + 1/(4\beta) - 12\theta_*^2/\beta$.

For $\beta \geq 10^3$ and $\theta_* = \pi/3$:
$\kappa_B \geq 0.689$.

\label{thm:chessboard}
For any plaquette $p$ and $\beta \geq 1$:
\begin{equation}
\mu_\beta(\theta_p > \pi/3) \leq C\,e^{-\beta/2}.
\end{equation}

\label{cor:global-curv}
For any smooth gauge-invariant $f$:
\begin{equation}
\int_{\Omega_g^c} \Gamma(f,f)\,d\mu_\beta
\leq C|\cP|\,e^{-\beta/2}\,\norm{\nabla f}^2_\infty.
\end{equation}
For $\beta$ large enough, the bad-region contribution is
exponentially small and does not affect the curvature bound.

\label{thm:global-poincare}
For gauge-invariant $f$:
\begin{equation}
\Var_{\mu_\beta}(f) \leq \frac{1}{\kappa\beta}\,\cE(f,f),
\end{equation}
i.e., $\lambda_1 \geq \kappa\beta$.

