Let $f,g\in C^\infty(\SU)$.
For each $X\in\g$,
\begin{equation}\label{eq:haar-ibp}
  \int_{\SU} (\nabla^{L}_X f)(u)\, g(u)\,du
  = -\int_{\SU} f(u)\, (\nabla^{L}_X g)(u)\,du,
\end{equation}
