plaquettes touching the interior, the probability that
all plaquette angles are small satisfies:
\begin{equation}\label{eq:block_conc}
  \mu_B\!\bigl(\Omega_{\theta_*}^c \mid \Phi\bigr)
  \le n_p \cdot C_G\,e^{-c_G\,\beta\,\theta_*^2/4},
\end{equation}
where $\Omega_{\theta_*} = \bigl\{U_y :
\max_{p \cap B^\circ \ne \varnothing}
|\alpha_p(U_y, \Phi)| \le \theta_*\bigr\}$,
and the bound is \emph{uniform in the boundary
condition~$\Phi$}.

\label{def:theta_star}
Define the \emph{Schur complement threshold}:
\begin{equation}\label{eq:theta_star_def}
  \theta_* = \sqrt{\frac{\lambda_{\min}
  (H_{yy,\mathrm{phys}})}{2\,C_K'}},
\end{equation}
so that~\eqref{eq:kappa_bound} gives
$\kappa \ge \rho_G
+ \beta\,\lambda_{\min}(H_{yy,\mathrm{phys}})/2 > 0$.

\label{thm:block_poincare}
For any boundary condition $\Phi$, the block conditional
measure~\eqref{eq:block_measure} satisfies
\begin{equation}\label{eq:block_gap}
  \gap(\mu_B(\cdot | \Phi)) \ge c_B > 0,
\end{equation}
where $c_B = c_B(G, L)$ depends only on $G$ and $L$,
not on $\beta$ or~$\Phi$.

More precisely:
\begin{equation}\label{eq:block_gap_precise}
  c_B(\beta) \ge
  \begin{cases}
    \rho_G\,e^{-c\beta_0 L^d} & \text{if }
      \beta \le \beta_0, \\[4pt]
    \dfrac{1}{8}\beta\,
    \lambda_{\min}(H_{yy,\mathrm{phys}})
    & \text{if } \beta \ge \beta_1,
  \end{cases}
\end{equation}
where $\beta_0 = \beta_0(G)$ is from
Lemma~\ref{lem:high_temp}.

\label{def:block_dob}
For adjacent blocks $B, B'$, define
\begin{equation}
  C_{BB'} = \sup_{\Phi, \Phi'} \frac{1}{2}
  \bigl\|\mu_B(\cdot | \Phi) - \mu_B(\cdot | \Phi')
  \bigr\|_{\mathrm{TV}},
\end{equation}
where the supremum is over all boundary conditions $\Phi,
\Phi'$ for $B$ that agree except on the face shared with $B'$.

